-- ============================================================
-- 圣经全文（新译本（主名作「主/主神」））· 数据文件 4/6
-- 先运行 bible_cuv_schema.sql 建表（已运行过可跳过），再按序号运行。
-- 可重复运行（冲突自动跳过）。本文件 5200 节。
-- ============================================================
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '诗篇', 19, 104, 35, '愿罪人从世上灭绝，也不再有恶人存在。我的心哪！你要称颂主。你们要赞美主。'),
('CNV', '诗篇', 19, 105, 1, '你们要称谢主，求告他的名；在万民中传扬他的作为。'),
('CNV', '诗篇', 19, 105, 2, '你们要向他歌唱，歌颂他，讲论他一切奇妙的作为。'),
('CNV', '诗篇', 19, 105, 3, '你们要以他的圣名夸耀；愿寻求主的人都心里欢喜。'),
('CNV', '诗篇', 19, 105, 4, '你们要追求主与他的能力，常常寻求他的面。'),
('CNV', '诗篇', 19, 105, 5, '记念他所作的奇事、他的神迹，和他口里的判词。'),
('CNV', '诗篇', 19, 105, 6, '他仆人亚伯拉罕的后裔啊！他所拣选的人，雅各的子孙哪！'),
('CNV', '诗篇', 19, 105, 7, '他是主我们的神，他的判词充满全地。'),
('CNV', '诗篇', 19, 105, 8, '他永远记念他的约，他记念他所吩咐的话，直到千代，'),
('CNV', '诗篇', 19, 105, 9, '就是与亚伯拉罕所立的约，向以撒所起的誓。'),
('CNV', '诗篇', 19, 105, 10, '他把这约向雅各定为律例，向以色列坚立为永远的约，'),
('CNV', '诗篇', 19, 105, 11, '说：“我必把迦南地赐给你们，作你们产业的分。”'),
('CNV', '诗篇', 19, 105, 12, '那时，他们人数不多，实在很少，而且是在那地寄居的。'),
('CNV', '诗篇', 19, 105, 13, '他们从这邦飘流到那邦，从这国飘流到另一国。'),
('CNV', '诗篇', 19, 105, 14, '他不容任何人欺压他们，为了他们的缘故，他曾指责君王，说：'),
('CNV', '诗篇', 19, 105, 15, '“不可伤害我的受膏者，也不可恶待我的先知。”'),
('CNV', '诗篇', 19, 105, 16, '他命令饥荒临到那地，断绝了一切粮食的供应。'),
('CNV', '诗篇', 19, 105, 17, '在他们之前，他差遣一个人去，就是被卖为奴的约瑟。'),
('CNV', '诗篇', 19, 105, 18, '人用脚镣弄伤他的脚，他的颈项被铁链锁着，'),
('CNV', '诗篇', 19, 105, 19, '直到他的话应验，主的话为他证实的时候。'),
('CNV', '诗篇', 19, 105, 20, '王就派人去释放他，统治众民的把他释放了。'),
('CNV', '诗篇', 19, 105, 21, '王立他执掌朝政，管理王一切所有的，'),
('CNV', '诗篇', 19, 105, 22, '使他可以随意捆绑王的群臣，把智慧教导王的长老。'),
('CNV', '诗篇', 19, 105, 23, '后来以色列到了埃及，雅各在含地寄居。'),
('CNV', '诗篇', 19, 105, 24, '主使他的子民生育众多，使他们比他们的敌人更强盛。'),
('CNV', '诗篇', 19, 105, 25, '他改变敌人的心去憎恨他的子民，用诡诈待他的众仆人。'),
('CNV', '诗篇', 19, 105, 26, '他差派了他的仆人摩西，和他拣选的亚伦。'),
('CNV', '诗篇', 19, 105, 27, '他们在敌人中间施行他的神迹，在含地显明他的奇事。'),
('CNV', '诗篇', 19, 105, 28, '他命黑暗降下，使那地黑暗；他的话是不能违背的。'),
('CNV', '诗篇', 19, 105, 29, '他使埃及的水都变成血，使他们的鱼都死掉。'),
('CNV', '诗篇', 19, 105, 30, '在他们的地上，以及君王的内室，青蛙多多滋生。'),
('CNV', '诗篇', 19, 105, 31, '他一发命令，苍蝇就成群而来，并且虱子进入他们的四境。'),
('CNV', '诗篇', 19, 105, 32, '他给他们降下冰雹为雨，又在他们的地上降下火焰。'),
('CNV', '诗篇', 19, 105, 33, '他击打他们的葡萄树和无花果树，又毁坏他们境内的树木。'),
('CNV', '诗篇', 19, 105, 34, '他一发命令，蝗虫就来，蚱蜢也来，多得无法数算，'),
('CNV', '诗篇', 19, 105, 35, '吃尽了他们地上的一切植物，吃光了他们土地的出产。'),
('CNV', '诗篇', 19, 105, 36, '他击杀了他们境内所有的长子，就是他们强壮的时候所生的头生子。'),
('CNV', '诗篇', 19, 105, 37, '他领自己的子民带着金银出来；他们众支派中没有一个畏缩的。'),
('CNV', '诗篇', 19, 105, 38, '他们出来的时候，埃及人很欢喜，因为埃及人都惧怕他们。'),
('CNV', '诗篇', 19, 105, 39, '他展开云彩作遮盖，夜间有火光照。'),
('CNV', '诗篇', 19, 105, 40, '他们一求，他就使鹌鹑飞来，并且用天上的粮食使他们饱足。'),
('CNV', '诗篇', 19, 105, 41, '他裂开磐石，水就涌流出来；在干旱之处水流成河。'),
('CNV', '诗篇', 19, 105, 42, '因为他记念他向自己的仆人亚伯拉罕应许的圣言。'),
('CNV', '诗篇', 19, 105, 43, '他带领自己的子民欢欢乐乐出来，带领自己的选民欢呼着出来。'),
('CNV', '诗篇', 19, 105, 44, '他把多国的地土赐给他们，他们就承受众民劳碌的成果，'),
('CNV', '诗篇', 19, 105, 45, '为要使他们谨守他的律例，遵守他的律法。你们要赞美主。'),
('CNV', '诗篇', 19, 106, 1, '你们要赞美主。你们要称谢主，因为他是美善的；他的慈爱永远长存。'),
('CNV', '诗篇', 19, 106, 2, '谁能述说主大能的作为，谁能说尽赞美他的话？'),
('CNV', '诗篇', 19, 106, 3, '谨守公正，常行公义的人，都是有福的。'),
('CNV', '诗篇', 19, 106, 4, '主啊！你恩待你子民的时候，求你记念我；你拯救他们的时候，求你眷念我；'),
('CNV', '诗篇', 19, 106, 5, '使我得见你选民的福乐，因你国民的欢乐而欢乐，与你的产业一同夸耀。'),
('CNV', '诗篇', 19, 106, 6, '我们和我们的列祖都犯了罪，我们作了孽，也行了恶。'),
('CNV', '诗篇', 19, 106, 7, '我们的列祖在埃及的时候，不明白你的奇事，也不记念你丰盛的慈爱，反倒在红海的海边悖逆了你。'),
('CNV', '诗篇', 19, 106, 8, '但他因自己的名的缘故拯救他们，为要彰显他的大能。'),
('CNV', '诗篇', 19, 106, 9, '他斥责红海，海就干了；他领他们走过海底，像经过旷野一样。'),
('CNV', '诗篇', 19, 106, 10, '他拯救他们脱离憎恨他们的人的手，从仇敌的手中救赎了他们。'),
('CNV', '诗篇', 19, 106, 11, '海水淹没了他们的敌人，连一个也没有留下。'),
('CNV', '诗篇', 19, 106, 12, '那时他们才相信他的话，唱歌赞美他。'),
('CNV', '诗篇', 19, 106, 13, '可是他们很快就忘记了他的作为，不仰望他的意旨，'),
('CNV', '诗篇', 19, 106, 14, '反而在旷野大起贪欲，在沙漠试探神。'),
('CNV', '诗篇', 19, 106, 15, '神把他们所求的赐给他们，却使灾病临到他们身上。'),
('CNV', '诗篇', 19, 106, 16, '他们在营中嫉妒摩西，以及归主为圣的亚伦。'),
('CNV', '诗篇', 19, 106, 17, '于是地裂开，吞下了大坍，把亚比兰一伙的人也掩埋了。'),
('CNV', '诗篇', 19, 106, 18, '有火在他们的党羽中燃烧起来，烈焰焚毁了恶人。'),
('CNV', '诗篇', 19, 106, 19, '他们在何烈山做了牛犊，敬拜铸成的偶像。'),
('CNV', '诗篇', 19, 106, 20, '这样，他们用吃草的牛的像，代替了他们的荣耀的神。'),
('CNV', '诗篇', 19, 106, 21, '他们竟忘记了拯救他们的神；他曾在埃及行了大事，'),
('CNV', '诗篇', 19, 106, 22, '在含地行了奇事，在红海边行了可畏可惧的事。'),
('CNV', '诗篇', 19, 106, 23, '所以他说要灭绝他们，不是有他拣选的摩西，在他面前站在破口上，使他的怒气转消，恐怕他早已毁灭他们了。'),
('CNV', '诗篇', 19, 106, 24, '他们又轻视那美地，不信他的应许。'),
('CNV', '诗篇', 19, 106, 25, '他们在自己的帐棚里发怨言，不听从主的话。'),
('CNV', '诗篇', 19, 106, 26, '所以他对他们起誓，必使他们倒在旷野，'),
('CNV', '诗篇', 19, 106, 27, '使他们的后裔四散在万国中，使他们分散在各地。'),
('CNV', '诗篇', 19, 106, 28, '他们又归附巴力．毗珥，吃了祭过死神的祭物。'),
('CNV', '诗篇', 19, 106, 29, '他们的行为触怒了主，于是有瘟疫在他们中间发生。'),
('CNV', '诗篇', 19, 106, 30, '那时非尼哈站起来，执行刑罚，瘟疫才止息。'),
('CNV', '诗篇', 19, 106, 31, '这就算为他的义，世世代代直到永远。'),
('CNV', '诗篇', 19, 106, 32, '他们在米利巴水边惹主发怒，以致摩西因他们的缘故也受了惩罚。'),
('CNV', '诗篇', 19, 106, 33, '因为他们抗拒神的灵（“他们抗拒神的灵”或译：“他们激动摩西的心”），摩西用嘴说出冒失的话。'),
('CNV', '诗篇', 19, 106, 34, '他们没有照着主吩咐他们的，灭绝外族的人民，'),
('CNV', '诗篇', 19, 106, 35, '反而和外族人混居杂处，学习他们的风俗习惯。'),
('CNV', '诗篇', 19, 106, 36, '他们又事奉外族人的偶像，这就成了他们的网罗。'),
('CNV', '诗篇', 19, 106, 37, '他们把自己的儿女祭祀鬼魔。'),
('CNV', '诗篇', 19, 106, 38, '他们流了无辜人的血，就是他们自己儿女的血，把他们祭祀迦南的偶像；那地就被血污秽了。'),
('CNV', '诗篇', 19, 106, 39, '这样，他们因自己所作的成了不洁，他们的行为使他们犯了邪淫。'),
('CNV', '诗篇', 19, 106, 40, '所以主的怒气向他的子民发作；他厌恶自己的产业，'),
('CNV', '诗篇', 19, 106, 41, '把他们交在外族人的手里，恨恶他们的人就管辖他们。'),
('CNV', '诗篇', 19, 106, 42, '他们的仇敌压迫他们，他们就屈服在仇敌的手下。'),
('CNV', '诗篇', 19, 106, 43, '神曾多次搭救他们，他们却故意悖逆，以致因自己的罪孽降为卑微。'),
('CNV', '诗篇', 19, 106, 44, '可是他听到了他们哀叫的时候，就垂顾他们的苦难。'),
('CNV', '诗篇', 19, 106, 45, '他为他们的缘故记念他自己的约，照着他丰盛的慈爱回心转意。'),
('CNV', '诗篇', 19, 106, 46, '他又使他们在所有掳掠他们的人面前，得蒙怜恤。'),
('CNV', '诗篇', 19, 106, 47, '主我们的神啊！求你拯救我们，把我们从万国中招聚回来，我们好称谢你的圣名，以赞美你为夸耀。'),
('CNV', '诗篇', 19, 106, 48, '主以色列的神是应当称颂的，从永远到永远。愿众民都说：“阿们。”你们要赞美主。'),
('CNV', '诗篇', 19, 107, 1, '你们要称谢主，因他本是良善的；他的慈爱永远长存。'),
('CNV', '诗篇', 19, 107, 2, '愿主救赎的子民这样称谢他；这民就是他从敌人的手里救赎出来，'),
('CNV', '诗篇', 19, 107, 3, '把他们从各地，就是从东从西、从南（“南”原文作“海”）从北，招聚回来的。'),
('CNV', '诗篇', 19, 107, 4, '他们有些人在旷野、在荒漠飘流，寻不见路往可居住的城巿。'),
('CNV', '诗篇', 19, 107, 5, '他们又饥又渴，心灵疲弱。'),
('CNV', '诗篇', 19, 107, 6, '他们在急难中呼求主，主就救他们脱离困苦；'),
('CNV', '诗篇', 19, 107, 7, '领他们走正直的路，使他们去到可居住的城巿。'),
('CNV', '诗篇', 19, 107, 8, '愿人因主的慈爱，和他向世人所行的奇事称谢他。'),
('CNV', '诗篇', 19, 107, 9, '因为他使干渴的人得到满足，又使饥饿的人饱享美物。'),
('CNV', '诗篇', 19, 107, 10, '他们有些人坐在黑暗和死荫里，被困苦和铁链捆锁着；'),
('CNV', '诗篇', 19, 107, 11, '因为他们违背了神的话，藐视了至高者的旨意。'),
('CNV', '诗篇', 19, 107, 12, '所以神用苦难治服他们的心；他们跌倒，也没有人帮助。'),
('CNV', '诗篇', 19, 107, 13, '他们在急难中呼求主，主就拯救他们脱离困苦。'),
('CNV', '诗篇', 19, 107, 14, '他从黑暗里和死荫中把他们领出来，弄断他们的锁链。'),
('CNV', '诗篇', 19, 107, 15, '愿人因主的慈爱，和他向世人所行的奇事称谢他。'),
('CNV', '诗篇', 19, 107, 16, '因为他打破了铜门，砍断了铁闩。'),
('CNV', '诗篇', 19, 107, 17, '他们有些人因自己的过犯成了愚妄人，有人受苦是因为自己的罪孽。'),
('CNV', '诗篇', 19, 107, 18, '他们厌恶各样食物，就临近死门。'),
('CNV', '诗篇', 19, 107, 19, '于是他们在急难中呼求主，他就拯救他们脱离困苦。'),
('CNV', '诗篇', 19, 107, 20, '他发出话语医治他们，搭救他们脱离死亡。'),
('CNV', '诗篇', 19, 107, 21, '愿人因主的慈爱，因他向世人所行的奇事称谢他。'),
('CNV', '诗篇', 19, 107, 22, '愿他们以感谢为祭献给他，欢欣地述说他的作为。'),
('CNV', '诗篇', 19, 107, 23, '他们有些人坐船出海，在大海上往来经商。'),
('CNV', '诗篇', 19, 107, 24, '他们见过主的作为，和他在深海中所行的奇事。'),
('CNV', '诗篇', 19, 107, 25, '他一吩咐，狂风就刮起，海中的波浪也高扬。'),
('CNV', '诗篇', 19, 107, 26, '他们上到天上，下到深渊，他们的心因危难而惊慌。'),
('CNV', '诗篇', 19, 107, 27, '他们摇摇晃晃，东倒西歪，好像醉酒的人；他们的一切智慧都没有用了。'),
('CNV', '诗篇', 19, 107, 28, '于是他们在急难中呼求主，他就拯救他们脱离困苦。'),
('CNV', '诗篇', 19, 107, 29, '他使狂风止息，海浪就平静无声。'),
('CNV', '诗篇', 19, 107, 30, '风平浪静了，他们就欢喜；他引领他们到他们所愿去的港口。'),
('CNV', '诗篇', 19, 107, 31, '愿人因主的慈爱，和他向世人所行的奇事称谢他。'),
('CNV', '诗篇', 19, 107, 32, '愿他们在众民的会中尊崇他，在长老的集会中赞美他。'),
('CNV', '诗篇', 19, 107, 33, '他使江河变为旷野，使水泉变为干旱无水之地。'),
('CNV', '诗篇', 19, 107, 34, '他使肥沃的土地变为咸田，都因住在那里的居民的邪恶。'),
('CNV', '诗篇', 19, 107, 35, '他使旷野变为池塘，使旱地变为水泉。'),
('CNV', '诗篇', 19, 107, 36, '他使饥饿的人住在那里，好让他们建造可以居住的城巿。'),
('CNV', '诗篇', 19, 107, 37, '他们耕种田地，栽种葡萄园，得到丰盛的收成。'),
('CNV', '诗篇', 19, 107, 38, '他又赐福给他们，使他们人口众多，也没有使他们的牲畜减少。'),
('CNV', '诗篇', 19, 107, 39, '以后他们因为压迫、患难、愁苦，就人数减少，降为卑微。'),
('CNV', '诗篇', 19, 107, 40, '他使权贵受羞辱，使他们在荒废无路的地方飘流。'),
('CNV', '诗篇', 19, 107, 41, '他却把贫穷的人安置在高处，免受苦难，使他的家族繁衍，好像羊群。'),
('CNV', '诗篇', 19, 107, 42, '正直的人看见了，就欢喜；但所有邪恶的人都必闭口无言。'),
('CNV', '诗篇', 19, 107, 43, '凡有智慧的，愿他留意这些事；愿他思想主的慈爱。'),
('CNV', '诗篇', 19, 108, 1, '神啊！我的心坚定；我要用我的灵（“灵”或译：“荣耀”或“肝”；与16:9，30:12，57:8同）歌唱和颂赞。'),
('CNV', '诗篇', 19, 108, 2, '琴和瑟啊！你们都要醒过来；我也要唤醒黎明。'),
('CNV', '诗篇', 19, 108, 3, '主啊！我要在万民中称谢你，在万族中歌颂你。'),
('CNV', '诗篇', 19, 108, 4, '因为你的慈爱伟大，高及诸天；你的信实上达云霄。'),
('CNV', '诗篇', 19, 108, 5, '神啊！愿你被尊崇，过于诸天；愿你的荣耀遍及全地。'),
('CNV', '诗篇', 19, 108, 6, '求你用右手拯救我们，应允我们，使你喜爱的人得拯救。'),
('CNV', '诗篇', 19, 108, 7, '神在自己的圣所（“神在自己的圣所”或译：“神指着自己的圣洁”）说：“我必夸胜，我必分开示剑，我必量度疏割谷。'),
('CNV', '诗篇', 19, 108, 8, '基列是我的，玛拿西是我的；以法莲是我的头盔；犹大是我的权杖，'),
('CNV', '诗篇', 19, 108, 9, '摩押是我的洗脚盆；我要向以东抛鞋，我要因战胜非利士欢呼。”'),
('CNV', '诗篇', 19, 108, 10, '谁能带我进坚固城？谁能领我到以东地去呢？'),
('CNV', '诗篇', 19, 108, 11, '神啊！你不是把我们丢弃了吗？神啊！你不和我们的军队一同出战吗？'),
('CNV', '诗篇', 19, 108, 12, '求你帮助我们抵挡敌人，因为人的援助是没有用的。'),
('CNV', '诗篇', 19, 108, 13, '我们靠着神奋勇作战，因为他必践踏我们的敌人。'),
('CNV', '诗篇', 19, 109, 1, '我所赞美的神啊！求你不要缄默无声，（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 109, 2, '因为邪恶的人的嘴和诡诈的人的口，已经张开攻击我；他们用虚谎的舌头对我说话。'),
('CNV', '诗篇', 19, 109, 3, '他们说毒恨的话围攻我，无缘无故攻击我。'),
('CNV', '诗篇', 19, 109, 4, '他们以敌对的态度来回报我的爱；至于我，我只有祷告。'),
('CNV', '诗篇', 19, 109, 5, '他们对我以恶报善，以憎恨回报我的爱。'),
('CNV', '诗篇', 19, 109, 6, '求你派一个恶人对付他；派一个对头站在他的右边。'),
('CNV', '诗篇', 19, 109, 7, '他受审判的时候，愿他被判为有罪；愿他的祷告成为罪。'),
('CNV', '诗篇', 19, 109, 8, '愿他的年日短少，愿别人取代他的职分。'),
('CNV', '诗篇', 19, 109, 9, '愿他的儿女成为孤儿；愿他的妻子成为寡妇。'),
('CNV', '诗篇', 19, 109, 10, '愿他的儿女流离失所，到处求乞；愿他们从他们破毁的家中被赶逐出去。'),
('CNV', '诗篇', 19, 109, 11, '愿债主夺去他一切所有的；愿外人都劫掠他劳碌得来的。'),
('CNV', '诗篇', 19, 109, 12, '愿无人对他施仁慈；愿无人恩待他的孤儿。'),
('CNV', '诗篇', 19, 109, 13, '愿他的后人被除灭，愿他们的名字在下一代被涂抹。'),
('CNV', '诗篇', 19, 109, 14, '愿他列祖的罪孽被主谨记；愿他母亲的罪恶不被涂抹。'),
('CNV', '诗篇', 19, 109, 15, '愿这些罪常在主面前，好使他们的名号从地上被除掉。'),
('CNV', '诗篇', 19, 109, 16, '因为他从没有想起要施慈爱，只知道迫害困苦、贫穷和伤心的人，要把他们置于死地。'),
('CNV', '诗篇', 19, 109, 17, '他爱咒诅，愿咒诅临到他；他不喜爱祝福，愿福乐远离他。'),
('CNV', '诗篇', 19, 109, 18, '他以咒诅当作衣服穿上，咒诅就像水一般进入他的内脏，像油一样进入他的骨头。'),
('CNV', '诗篇', 19, 109, 19, '愿这咒诅像衣服一般给他披上，并当作他常常束上的腰带。'),
('CNV', '诗篇', 19, 109, 20, '愿敌对我和用恶言攻击我的，都从主那里得到这报应。'),
('CNV', '诗篇', 19, 109, 21, '至于你，主神啊！求你为你名的缘故恩待我；按着你美好的慈爱拯救我。'),
('CNV', '诗篇', 19, 109, 22, '因为我困苦贫穷，我的内心伤痛。'),
('CNV', '诗篇', 19, 109, 23, '我像日影倾斜，渐渐消逝，又像蝗虫被抖掉。'),
('CNV', '诗篇', 19, 109, 24, '我因禁食，双膝软弱无力；我的身体消瘦枯干。'),
('CNV', '诗篇', 19, 109, 25, '我成了他们羞辱的对象；他们一看见我，就摇头。'),
('CNV', '诗篇', 19, 109, 26, '主我的神啊！求你帮助我；求你按着你的慈爱拯救我，'),
('CNV', '诗篇', 19, 109, 27, '好让人知道这是出于你的手，是你主所作的事。'),
('CNV', '诗篇', 19, 109, 28, '任凭他们咒诅，只愿你赐福；愿起来攻击我的都蒙羞，你的仆人却要欢喜。'),
('CNV', '诗篇', 19, 109, 29, '愿敌对我的披戴羞辱；愿他们以自己的耻辱为外袍披在身上。'),
('CNV', '诗篇', 19, 109, 30, '我要用口极力称谢主；我要在众人中间赞美他。'),
('CNV', '诗篇', 19, 109, 31, '因为他必站在贫穷人的右边，拯救他脱离定他死罪的人。'),
('CNV', '诗篇', 19, 110, 1, '主对我主说：“你坐在我的右边，等我使你的仇敌作你的脚凳。”（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 110, 2, '主必使你从锡安伸出能力的权杖，你要在你的仇敌中掌权。'),
('CNV', '诗篇', 19, 110, 3, '在你征战的日子，你的人民都乐意投身；你的少年人以圣洁为装饰，好像清晨的甘露，到你那里。'),
('CNV', '诗篇', 19, 110, 4, '主起了誓，就决不反悔；他说：“你永远作祭司，是照着麦基洗德的体系。”'),
('CNV', '诗篇', 19, 110, 5, '主在你右边，在他发怒的日子，必剿灭列王。'),
('CNV', '诗篇', 19, 110, 6, '他必在列国中施行审判，尸首就遍满各处；他要剿灭地上各处的首领。'),
('CNV', '诗篇', 19, 110, 7, '王要喝路旁的河水，因此他必挺胸昂首。'),
('CNV', '诗篇', 19, 111, 1, '你们要赞美主。在正直人的议会中和大会里，我要全心称谢主。'),
('CNV', '诗篇', 19, 111, 2, '主的作为伟大，喜爱他作为的人都努力查究。'),
('CNV', '诗篇', 19, 111, 3, '他的作为满有尊荣和威严，他的公义永远长存。'),
('CNV', '诗篇', 19, 111, 4, '他使人记念他所行的奇事；主有恩典，有怜悯。'),
('CNV', '诗篇', 19, 111, 5, '他赐粮食给敬畏他的人；他永远记念自己的约。'),
('CNV', '诗篇', 19, 111, 6, '他向自己的子民彰显大能的作为，把列国赐给他们为业。'),
('CNV', '诗篇', 19, 111, 7, '他手所作的都是诚实和公正；他的训词都是可信靠的。'),
('CNV', '诗篇', 19, 111, 8, '他的训词是永远确定的，是按着信实和正直制订的。'),
('CNV', '诗篇', 19, 111, 9, '他向自己的子民施行救赎；他命定自己的约，直到永远；他的名神圣可畏。'),
('CNV', '诗篇', 19, 111, 10, '敬畏主是智慧的开端；凡是这样行的都是明智的。主该受赞美，直到永远。'),
('CNV', '诗篇', 19, 112, 1, '你们要赞美主。敬畏主、热爱他的诫命的，这人是有福的。'),
('CNV', '诗篇', 19, 112, 2, '他的后裔在地上必强盛，正直人的后代必蒙福。'),
('CNV', '诗篇', 19, 112, 3, '他家中有财富，有金钱，他的仁义存到永远。'),
('CNV', '诗篇', 19, 112, 4, '正直人在黑暗中有光照亮他，他满有恩慈，好怜恤，行公义。'),
('CNV', '诗篇', 19, 112, 5, '恩待人，借贷给别人，按公正处理自己事务的，这人必享福乐。'),
('CNV', '诗篇', 19, 112, 6, '因为他永远不会动摇，义人必永远被记念。'),
('CNV', '诗篇', 19, 112, 7, '他必不因坏消息惧怕；他的心坚定，倚靠主。'),
('CNV', '诗篇', 19, 112, 8, '他的心坚决，毫不惧怕，直到他看见他的敌人遭报。'),
('CNV', '诗篇', 19, 112, 9, '他广施钱财，周济穷人；他的仁义存到永远；他的角必被高举，大有荣耀。'),
('CNV', '诗篇', 19, 112, 10, '恶人看见就恼怒，他必咬牙切齿，身心耗损；恶人的心愿必幻灭。'),
('CNV', '诗篇', 19, 113, 1, '你们要赞美主。主的仆人哪！你们要赞美，要赞美主的名。'),
('CNV', '诗篇', 19, 113, 2, '主的名是应当称颂的，从现在直到永远。'),
('CNV', '诗篇', 19, 113, 3, '从日出之地到日落之处，主的名都该受赞美。'),
('CNV', '诗篇', 19, 113, 4, '主高过万国，他的荣耀超越诸天。'),
('CNV', '诗篇', 19, 113, 5, '谁像主我们的神呢？他坐在至高之处，'),
('CNV', '诗篇', 19, 113, 6, '他俯首垂顾天上和地下的事。'),
('CNV', '诗篇', 19, 113, 7, '他从灰尘中抬举贫寒人，从粪堆中提拔穷乏人，'),
('CNV', '诗篇', 19, 113, 8, '使他们和权贵同坐，就是和他子民中的权贵同坐，'),
('CNV', '诗篇', 19, 113, 9, '他使不能生育的妇人安居家中，成了有许多儿女的快乐母亲。你们要赞美主。'),
('CNV', '诗篇', 19, 114, 1, '以色列出了埃及，雅各家离开了说外国语言的人民的时候，'),
('CNV', '诗篇', 19, 114, 2, '犹大就成了主的圣所，以色列成了他的王国。'),
('CNV', '诗篇', 19, 114, 3, '大海看见就奔逃，约旦河也倒流。'),
('CNV', '诗篇', 19, 114, 4, '大山跳跃像公羊，小山蹦跳像小羊。'),
('CNV', '诗篇', 19, 114, 5, '大海啊！你为什么奔逃？约旦河啊！你为什么倒流？'),
('CNV', '诗篇', 19, 114, 6, '大山啊！你们为什么跳跃像公羊？小山啊！你们为什么蹦跳像小羊？'),
('CNV', '诗篇', 19, 114, 7, '大地啊！你在主的面前，在雅各的神面前要战抖。'),
('CNV', '诗篇', 19, 114, 8, '他使磐石变为水池，使坚石变为水泉。'),
('CNV', '诗篇', 19, 115, 1, '主啊！不要把荣耀归给我们，不要归给我们；要因你的慈爱和信实把荣耀归在你的名下。'),
('CNV', '诗篇', 19, 115, 2, '为什么容列国的人说：“他们的神在哪里呢？”'),
('CNV', '诗篇', 19, 115, 3, '我们的神在天上；他喜欢什么，就作什么。'),
('CNV', '诗篇', 19, 115, 4, '列国的偶像是金的、银的，是人手所做的。'),
('CNV', '诗篇', 19, 115, 5, '它们有口，却不能说话；有眼，却不能看；'),
('CNV', '诗篇', 19, 115, 6, '有耳，却不能听；有鼻，却不能闻；'),
('CNV', '诗篇', 19, 115, 7, '有手，却不能摸；有脚，却不能行；也不能用喉咙发声。'),
('CNV', '诗篇', 19, 115, 8, '做偶像的必和偶像一样；凡是倚靠它们的，都必这样。'),
('CNV', '诗篇', 19, 115, 9, '以色列啊！你们要倚靠主；他是你们（“你们”原文作“他们”）的帮助、你们（“你们”原文作“他们”）的盾牌。'),
('CNV', '诗篇', 19, 115, 10, '亚伦家啊！你们要倚靠主；他是你们（“你们”原文作“他们”）的帮助、你们（“你们”原文作“他们”）的盾牌。'),
('CNV', '诗篇', 19, 115, 11, '敬畏主的啊！你们要倚靠主；他是你们（“你们”原文作“他们”）的帮助、你们（“你们”原文作“他们”）的盾牌。'),
('CNV', '诗篇', 19, 115, 12, '主顾念我们，必赐福给我们；他必赐福给以色列家，赐福给亚伦家。'),
('CNV', '诗篇', 19, 115, 13, '敬畏主的，无论大小尊卑，他都必赐福。'),
('CNV', '诗篇', 19, 115, 14, '愿主使你们增多，使你们和你们的子孙增多。'),
('CNV', '诗篇', 19, 115, 15, '愿你们蒙创造天地的主赐福。'),
('CNV', '诗篇', 19, 115, 16, '天属于主，地，他却赐给了世人。'),
('CNV', '诗篇', 19, 115, 17, '死人不能赞美主，下到阴间的不能赞美他。'),
('CNV', '诗篇', 19, 115, 18, '至于我们，我们要称颂主，从现在直到永远。你们要赞美主。'),
('CNV', '诗篇', 19, 116, 1, '我爱主，因为他听了我的声音、我的恳求。'),
('CNV', '诗篇', 19, 116, 2, '因为他留心听我的恳求，我一生一世要求告他。'),
('CNV', '诗篇', 19, 116, 3, '死亡的绳索缠绕着我，阴间的痛苦抓住我；我遭遇患难和愁苦。'),
('CNV', '诗篇', 19, 116, 4, '那时，我呼求主的名，说：“主啊！求你拯救我。”'),
('CNV', '诗篇', 19, 116, 5, '主有恩典，有公义，我们的神满有怜悯。'),
('CNV', '诗篇', 19, 116, 6, '主保护愚蒙人，我落到卑微的地步，他拯救了我。'),
('CNV', '诗篇', 19, 116, 7, '我的心哪！你要回复安宁，因为主用厚恩待你。'),
('CNV', '诗篇', 19, 116, 8, '主啊！你救了我的性命脱离死亡，你使我的眼睛不致流泪，使我的双脚不致跌倒。'),
('CNV', '诗篇', 19, 116, 9, '我要在活人之地，行在主面前。'),
('CNV', '诗篇', 19, 116, 10, '我虽然说：“我受了极大的痛苦”，但我仍然相信。'),
('CNV', '诗篇', 19, 116, 11, '我在惊惶之中曾说：“人都是说谎的。”'),
('CNV', '诗篇', 19, 116, 12, '我拿什么报答主向我所施的一切厚恩呢？'),
('CNV', '诗篇', 19, 116, 13, '我要举起救恩的杯，称扬主的名。'),
('CNV', '诗篇', 19, 116, 14, '我要在主的众民面前，向他还我所许的愿。'),
('CNV', '诗篇', 19, 116, 15, '在主的眼中看来，圣民的死极为宝贵。'),
('CNV', '诗篇', 19, 116, 16, '主啊！我真是你的仆人；我是你仆人，你婢女的儿子；我的锁链你给我解开了。'),
('CNV', '诗篇', 19, 116, 17, '我要把感恩祭献给你，我要称扬主的名。'),
('CNV', '诗篇', 19, 116, 18, '我要在主的众民面前，向他还我所许的愿。'),
('CNV', '诗篇', 19, 116, 19, '耶路撒冷啊！就是在你的中间，在主殿的院子里，我要还我所许的愿。你们要赞美主。'),
('CNV', '诗篇', 19, 117, 1, '万国啊！你们要赞美主；万民哪！你们要颂赞他。'),
('CNV', '诗篇', 19, 117, 2, '他向我们所施的慈爱极大；主的信实永远长存。你们要赞美主。'),
('CNV', '诗篇', 19, 118, 1, '你们要称谢主，因他本是良善的；他的慈爱永远长存。'),
('CNV', '诗篇', 19, 118, 2, '愿以色列说：“他的慈爱永远长存。”'),
('CNV', '诗篇', 19, 118, 3, '愿亚伦家说：“他的慈爱永远长存。”'),
('CNV', '诗篇', 19, 118, 4, '愿敬畏主的说：“他的慈爱永远长存。”'),
('CNV', '诗篇', 19, 118, 5, '我在急难中求告主，他就应允我，使我站在宽阔之地。'),
('CNV', '诗篇', 19, 118, 6, '主是我的帮助，我决不害怕，人能把我怎么样呢？'),
('CNV', '诗篇', 19, 118, 7, '主是我的帮助，我必看见恨我的人遭报。'),
('CNV', '诗篇', 19, 118, 8, '投靠主，胜过倚靠人。'),
('CNV', '诗篇', 19, 118, 9, '投靠主，胜过倚靠王子。'),
('CNV', '诗篇', 19, 118, 10, '列国围困着我，我靠着主的名必除灭他们。'),
('CNV', '诗篇', 19, 118, 11, '他们围绕着我，把我围困，我靠着主的名必除灭他们。'),
('CNV', '诗篇', 19, 118, 12, '他们如同蜜蜂围绕着我，但他们要像烧荆棘的火熄灭；我靠着主的名必除灭他们。'),
('CNV', '诗篇', 19, 118, 13, '他们（“他们”原文作“你”）极力推我，要我跌倒，主却帮助了我。'),
('CNV', '诗篇', 19, 118, 14, '主是我的力量，我的诗歌；他也成了我的拯救。'),
('CNV', '诗篇', 19, 118, 15, '在义人的帐棚里，有欢呼和得胜的声音，说：“主的右手行了大能的事。'),
('CNV', '诗篇', 19, 118, 16, '主的右手高高举起；主的右手行了大能的事。”'),
('CNV', '诗篇', 19, 118, 17, '我必不至于死，我要活下去，并且要述说主的作为。'),
('CNV', '诗篇', 19, 118, 18, '主虽严厉地管教我，却没有把我置于死地。'),
('CNV', '诗篇', 19, 118, 19, '请你们为我打开正义的门，我要进去，称谢主。'),
('CNV', '诗篇', 19, 118, 20, '这是主的门，义人才可以进去。'),
('CNV', '诗篇', 19, 118, 21, '我要称谢你，因为你应允了我，又成了我的拯救。'),
('CNV', '诗篇', 19, 118, 22, '建筑工人所弃的石头，成了房角的主要石头；'),
('CNV', '诗篇', 19, 118, 23, '这是主作的，在我们眼中看为希奇。'),
('CNV', '诗篇', 19, 118, 24, '这是主所定的日子，我们要在这一日欢喜快乐。'),
('CNV', '诗篇', 19, 118, 25, '主啊！求你施行拯救；主啊！求你使我们亨通。'),
('CNV', '诗篇', 19, 118, 26, '奉主的名来的是应当称颂的，我们从主的殿中给你们祝福。'),
('CNV', '诗篇', 19, 118, 27, '主是神，他光照了我们。你们要用绳索把祭牲拴住，带到祭坛的角那里（“你们要用绳索把祭牲拴住，带到祭坛的角那里”或译：“你们要手拿树枝，开始向祭坛列队前行”）。'),
('CNV', '诗篇', 19, 118, 28, '你是我的神，我要称谢你；你是我的神，我要尊崇你。'),
('CNV', '诗篇', 19, 118, 29, '你们要称谢主，因他本是良善的；他的慈爱永远长存。'),
('CNV', '诗篇', 19, 119, 1, '行为完全，遵行主律法的，都是有福的。'),
('CNV', '诗篇', 19, 119, 2, '谨守他的法度，全心寻求他的，都是有福的。'),
('CNV', '诗篇', 19, 119, 3, '他们不作不义的事；他们遵行他的道。'),
('CNV', '诗篇', 19, 119, 4, '你曾把你的训词吩咐我们，要我们殷勤遵守。'),
('CNV', '诗篇', 19, 119, 5, '但愿我的道路坚定，为要遵守你的律例。'),
('CNV', '诗篇', 19, 119, 6, '我重视你的一切诫命，就不至于羞愧。'),
('CNV', '诗篇', 19, 119, 7, '我学会了你公义的法则，就以正直的心称谢你。'),
('CNV', '诗篇', 19, 119, 8, '我必遵守你的律例，求你不要把我弃绝。'),
('CNV', '诗篇', 19, 119, 9, '少年人用什么洁净自己的行为呢？就是要遵守你的话。'),
('CNV', '诗篇', 19, 119, 10, '我一心寻求你，求你不要容我偏离你的诫命。'),
('CNV', '诗篇', 19, 119, 11, '我把你的话藏在心里，免得我得罪你。'),
('CNV', '诗篇', 19, 119, 12, '主啊！你是该受称颂的；求你把你的律例教导我。'),
('CNV', '诗篇', 19, 119, 13, '我用嘴唇传扬从你口中所出的一切典章。'),
('CNV', '诗篇', 19, 119, 14, '我喜欢你法度定下的道路，如同喜欢一切财富。'),
('CNV', '诗篇', 19, 119, 15, '我要默想你的训词，重视你的道路。'),
('CNV', '诗篇', 19, 119, 16, '我喜爱你的律例，我不会忘记你的话。'),
('CNV', '诗篇', 19, 119, 17, '求你恩待你的仆人，使我可以活着，也可以谨守你的话。'),
('CNV', '诗篇', 19, 119, 18, '求你开我的眼睛，使我能看出你律法的奇妙。'),
('CNV', '诗篇', 19, 119, 19, '我是在世上作寄居的，求你不要向我隐瞒你的命令。'),
('CNV', '诗篇', 19, 119, 20, '我常常切慕你的典章，以致我心力交瘁。'),
('CNV', '诗篇', 19, 119, 21, '那些受咒诅的傲慢人，和那些偏离了你诫命的人，你必斥责他们。'),
('CNV', '诗篇', 19, 119, 22, '求你除去我所受的羞辱和藐视，因为我遵守你的法度。'),
('CNV', '诗篇', 19, 119, 23, '虽有作领袖的坐着毁谤我，你的仆人却默想你的律例。'),
('CNV', '诗篇', 19, 119, 24, '你的法度是我的喜乐，是我的谋士。'),
('CNV', '诗篇', 19, 119, 25, '我快要归回尘土，求你按着你的话把我救活过来。'),
('CNV', '诗篇', 19, 119, 26, '我陈明我所行的，你就应允了我；求你把你的律例教导我。'),
('CNV', '诗篇', 19, 119, 27, '求你使我明白你的训词，我就默想你的奇妙。'),
('CNV', '诗篇', 19, 119, 28, '我因愁苦而流泪，求你照着你的话使我坚强。'),
('CNV', '诗篇', 19, 119, 29, '求你使我离开虚谎的路，施恩把你的律法赐给我。'),
('CNV', '诗篇', 19, 119, 30, '我拣选了信实的道路，我把你的典章摆在我面前。'),
('CNV', '诗篇', 19, 119, 31, '我紧守你的法度，主啊！求你不要使我蒙羞。'),
('CNV', '诗篇', 19, 119, 32, '因为你使我的心舒畅，我就跑在你诫命的路上。'),
('CNV', '诗篇', 19, 119, 33, '主啊！求你把你的律例指教我，我必遵守到底。'),
('CNV', '诗篇', 19, 119, 34, '求你赐我悟性，我好遵守你的律法，我必一心谨守。'),
('CNV', '诗篇', 19, 119, 35, '求你领我走在你诫命的路上，因为这是我喜悦的。'),
('CNV', '诗篇', 19, 119, 36, '求你使我的心倾向你的法度，不倾向不义之财。'),
('CNV', '诗篇', 19, 119, 37, '求你使我转眼不看虚空的事；又使我在你的道中存活。'),
('CNV', '诗篇', 19, 119, 38, '求你向你的仆人实践你的诺言，就是你向敬畏你的人所应许的。'),
('CNV', '诗篇', 19, 119, 39, '求你使我所怕的羞辱离开我，因为你的典章都是美好的。'),
('CNV', '诗篇', 19, 119, 40, '我切慕你的训词，求你使我活在你的公义中。'),
('CNV', '诗篇', 19, 119, 41, '主啊！愿你照着你的应许，使你的慈爱、你的救恩临到我。'),
('CNV', '诗篇', 19, 119, 42, '我就有话回答那羞辱我的，因为我倚靠你的话。'),
('CNV', '诗篇', 19, 119, 43, '求你使真理的话总不离开我的口，因为我仰望你的典章。'),
('CNV', '诗篇', 19, 119, 44, '我要常常谨守你的律法，直到永远。'),
('CNV', '诗篇', 19, 119, 45, '我必行在宽阔之处，因为我一向寻求你的训词。'),
('CNV', '诗篇', 19, 119, 46, '我在君王面前讲论你的法度，也不以为耻。'),
('CNV', '诗篇', 19, 119, 47, '我要以你的诫命为乐，这些诫命是我所爱的。'),
('CNV', '诗篇', 19, 119, 48, '我又要向你的诫命举手，这些诫命是我所爱的；我也要默想你的律例。'),
('CNV', '诗篇', 19, 119, 49, '求你记念你向你仆人应许的话，因为你使我有盼望。'),
('CNV', '诗篇', 19, 119, 50, '你的应许使我存活；这就是我在困苦中的安慰。'),
('CNV', '诗篇', 19, 119, 51, '骄傲的人苛刻地讥诮我，我却没有偏离你的律法。'),
('CNV', '诗篇', 19, 119, 52, '主啊！我思念你在古时赐下的典章，我就得了安慰。'),
('CNV', '诗篇', 19, 119, 53, '因为恶人离弃你的律法，我就非常忿怒。'),
('CNV', '诗篇', 19, 119, 54, '在我寄居的住所里，你的律例成了我的诗歌。'),
('CNV', '诗篇', 19, 119, 55, '主啊！我在夜间记念你的名，我要谨守你的律法。'),
('CNV', '诗篇', 19, 119, 56, '我这样作，是因为我遵守你的训词。'),
('CNV', '诗篇', 19, 119, 57, '主啊！你是我的业分，我曾说我要谨守你的话。'),
('CNV', '诗篇', 19, 119, 58, '我曾一心向你乞恩，愿你照着你的应许恩待我。'),
('CNV', '诗篇', 19, 119, 59, '我思想我所行的道路，就转回脚步归向你的法度。'),
('CNV', '诗篇', 19, 119, 60, '我赶快谨守你的命令，不敢耽延。'),
('CNV', '诗篇', 19, 119, 61, '恶人的绳索虽然捆绑我，我却不忘记你的律法。'),
('CNV', '诗篇', 19, 119, 62, '因你公义的典章，我半夜起来称谢你。'),
('CNV', '诗篇', 19, 119, 63, '凡是敬畏你，谨守你训词的，我都与他们为友。'),
('CNV', '诗篇', 19, 119, 64, '主啊！你的慈爱遍满大地；求你把你的律例教导我。'),
('CNV', '诗篇', 19, 119, 65, '主啊！你向来照着你的话，善待你的仆人。'),
('CNV', '诗篇', 19, 119, 66, '求你把聪明和知识指教我，因为我信靠你的命令。'),
('CNV', '诗篇', 19, 119, 67, '我受苦以先，犯了错误；现在我谨守你的话。'),
('CNV', '诗篇', 19, 119, 68, '你本是良善的，你所行的也是良善的；求你把你的律例教导我。'),
('CNV', '诗篇', 19, 119, 69, '傲慢人用谎言中伤我，我却一心遵守你的训词。'),
('CNV', '诗篇', 19, 119, 70, '他们的心麻木如同脂油，我却喜欢你的律法。'),
('CNV', '诗篇', 19, 119, 71, '我受苦是对我有益的，为要使我学习你的律例。'),
('CNV', '诗篇', 19, 119, 72, '你口中的律法对我有益，胜过千千万万的金银。'),
('CNV', '诗篇', 19, 119, 73, '你的手造了我，建立了我；求你使我有悟性，可以学习你的命令。'),
('CNV', '诗篇', 19, 119, 74, '愿敬畏你的人看见我就欢喜，因为我仰望你的话。'),
('CNV', '诗篇', 19, 119, 75, '主啊！我知道你的判语是公义的，为了你的信实，你使我受苦。'),
('CNV', '诗篇', 19, 119, 76, '求你按着你给你仆人的应许，以你的慈爱安慰我。'),
('CNV', '诗篇', 19, 119, 77, '愿你的怜悯临到我，使我活着，因为我喜欢你的律法。'),
('CNV', '诗篇', 19, 119, 78, '愿傲慢人蒙羞，因为他们以诡诈诬蔑我；至于我，我却要默想你的训词。'),
('CNV', '诗篇', 19, 119, 79, '愿敬畏你、知道你法度的人，都归向我；'),
('CNV', '诗篇', 19, 119, 80, '愿我的心在你的律例上无可指摘，使我不至蒙羞。'),
('CNV', '诗篇', 19, 119, 81, '我渴望你的救恩以致心力衰竭，但我仍仰望你的话。'),
('CNV', '诗篇', 19, 119, 82, '我仰望你的应许以致眼睛昏花，我说：“你什么时候才安慰我呢？”'),
('CNV', '诗篇', 19, 119, 83, '我虽然好像烟薰的皮袋，我却没有忘记你的律例。'),
('CNV', '诗篇', 19, 119, 84, '你仆人的日子还有多少？你什么时候才向那些逼迫我的人施行审判呢？'),
('CNV', '诗篇', 19, 119, 85, '傲慢人为我掘了坑，他们就是那些不按着你律法而行的人。'),
('CNV', '诗篇', 19, 119, 86, '你的一切命令都是可信靠的；他们以诡诈逼迫我，求你帮助我。'),
('CNV', '诗篇', 19, 119, 87, '他们几乎把我从世上除灭了；至于我，我却没有离弃你的训词。'),
('CNV', '诗篇', 19, 119, 88, '求你照着你的慈爱使我存活，我就必谨守你口中的法度。'),
('CNV', '诗篇', 19, 119, 89, '主啊！你的话存到永远，坚立在天上。'),
('CNV', '诗篇', 19, 119, 90, '你的信实存到万代；你坚立了地，地就长存。'),
('CNV', '诗篇', 19, 119, 91, '天地照着你的安排存到今日，因为万有都是你的仆役。'),
('CNV', '诗篇', 19, 119, 92, '如果我不是喜欢你的律法，就早已在苦难中灭亡了。'),
('CNV', '诗篇', 19, 119, 93, '我永远不会忘记你的训词，因为你用这些训词使我存活。'),
('CNV', '诗篇', 19, 119, 94, '我是属于你的，求你拯救我，因为我寻求你的训词。'),
('CNV', '诗篇', 19, 119, 95, '恶人等待着要把我毁灭，我却思考你的法度。'),
('CNV', '诗篇', 19, 119, 96, '我看一切圆满的事都有尽头，只有你的命令是广阔无边的。'),
('CNV', '诗篇', 19, 119, 97, '我多么爱慕你的律法，终日不住地默想。'),
('CNV', '诗篇', 19, 119, 98, '你的命令使我比我的仇敌更有智慧，因为你的命令常存在我里面。'),
('CNV', '诗篇', 19, 119, 99, '我比我所有的老师明智，因为我默想你的法度。'),
('CNV', '诗篇', 19, 119, 100, '我比老年人更明理，因为我遵守你的训词。'),
('CNV', '诗篇', 19, 119, 101, '我制止我的脚不走任何邪恶的路，为要谨守你的话。'),
('CNV', '诗篇', 19, 119, 102, '我没有偏离你的典章，因为你亲自教导了我。'),
('CNV', '诗篇', 19, 119, 103, '你的话语在我的上膛多么甜美，在我的口中比蜂蜜更甜。'),
('CNV', '诗篇', 19, 119, 104, '我藉着你的训词，得以明白事理；因此，我恨恶一切虚谎的道。'),
('CNV', '诗篇', 19, 119, 105, '你的话是我脚前的灯，是我路上的光。'),
('CNV', '诗篇', 19, 119, 106, '我曾起誓，并且坚守誓言，我必遵守你公义的典章。'),
('CNV', '诗篇', 19, 119, 107, '我受苦极重；主啊！求你照着你的应许使我存活。'),
('CNV', '诗篇', 19, 119, 108, '主啊！求你悦纳我口中的甘心祭，又把你的典章教导我。'),
('CNV', '诗篇', 19, 119, 109, '我的性命常在危险中，我却没有忘记你的律法。'),
('CNV', '诗篇', 19, 119, 110, '恶人虽然设下陷阱要害我，我却没有偏离你的训词。'),
('CNV', '诗篇', 19, 119, 111, '我以你的法度为我永远的产业；因为它们是我心中的喜乐。'),
('CNV', '诗篇', 19, 119, 112, '我专心遵行你的律例，永不改变，遵行到底。'),
('CNV', '诗篇', 19, 119, 113, '我恨恶心怀二意的人，我却喜爱你的律法。'),
('CNV', '诗篇', 19, 119, 114, '你是我的避难所，我的盾牌；我仰望你的话。'),
('CNV', '诗篇', 19, 119, 115, '作恶的人哪！你们离开我吧，好让我遵守我神的命令。'),
('CNV', '诗篇', 19, 119, 116, '求你照着你的应许扶持我，使我存活；不要使我因仰望你而蒙羞。'),
('CNV', '诗篇', 19, 119, 117, '求你扶持我，我就必得救；我必常常重视你的律例。'),
('CNV', '诗篇', 19, 119, 118, '偏离你的律例的，你都把他们弃绝；他们的诡诈是徒然的。'),
('CNV', '诗篇', 19, 119, 119, '世上所有的恶人，你都把他们除灭，如同除去渣滓，因此我喜爱你的法度。'),
('CNV', '诗篇', 19, 119, 120, '我因惧怕你而战栗；我畏惧你的审判。'),
('CNV', '诗篇', 19, 119, 121, '我曾秉公行义；求你不要把我撇下，交给欺压我的人。'),
('CNV', '诗篇', 19, 119, 122, '求你作你仆人的保证人，确保我的好处；不要容傲慢人欺压我。'),
('CNV', '诗篇', 19, 119, 123, '因盼望你的救恩和你公义的应许，我的眼睛都昏花了。'),
('CNV', '诗篇', 19, 119, 124, '求你按着你的慈爱待你的仆人，把你的律例教导我。'),
('CNV', '诗篇', 19, 119, 125, '我是你的仆人，求你赐我悟性，使我可以明白你的法度。'),
('CNV', '诗篇', 19, 119, 126, '现在是主行动的时候；因为人都违犯了你的律法。'),
('CNV', '诗篇', 19, 119, 127, '因此我爱你的命令，胜过金子，甚至胜过精金。'),
('CNV', '诗篇', 19, 119, 128, '在一切事上，你所有的训词我都视为正直；我恨恶一切虚谎的道。'),
('CNV', '诗篇', 19, 119, 129, '你的法度奇妙，所以我必遵守你的法度，'),
('CNV', '诗篇', 19, 119, 130, '你的话一解开，就发出亮光，使愚人有悟性。'),
('CNV', '诗篇', 19, 119, 131, '我张口喘气，因为我切慕你的命令。'),
('CNV', '诗篇', 19, 119, 132, '求你转向我，恩待我；像你素常对待那些爱你名的人那样。'),
('CNV', '诗篇', 19, 119, 133, '求你用你的话引导我的脚步，不容什么罪孽辖制我。'),
('CNV', '诗篇', 19, 119, 134, '求你救赎我脱离人的欺压，好让我谨守你的训词。'),
('CNV', '诗篇', 19, 119, 135, '求你用你的脸光照你的仆人，把你的律例教导我。'),
('CNV', '诗篇', 19, 119, 136, '我的眼泪像河水涌流，因为人都不谨守你的律法。'),
('CNV', '诗篇', 19, 119, 137, '主啊！你是公义的，你的判词也是正直的。'),
('CNV', '诗篇', 19, 119, 138, '你以公义和至诚，命定了你的法度。'),
('CNV', '诗篇', 19, 119, 139, '我心中迫切如同火烧，因为我的敌人忘记了你的话。'),
('CNV', '诗篇', 19, 119, 140, '你的话语十分精炼，因此你的仆人喜爱你的话语。'),
('CNV', '诗篇', 19, 119, 141, '我虽然微小，被人藐视，我却没有忘记你的训词。'),
('CNV', '诗篇', 19, 119, 142, '你的公义是永远的公义，你的律法是可信可靠的。'),
('CNV', '诗篇', 19, 119, 143, '我遭遇患难和困苦，但你的命令仍是我欢喜的。'),
('CNV', '诗篇', 19, 119, 144, '你的法度永远是公义的，求你赐我悟性，好让我存活。'),
('CNV', '诗篇', 19, 119, 145, '主啊！我一心呼求你，求你应允我；我必遵守你的律例。'),
('CNV', '诗篇', 19, 119, 146, '我向你呼求，求你救我；我必谨守你的法度。'),
('CNV', '诗篇', 19, 119, 147, '天还未亮我就呼求救助，我所仰望的就是你的话。'),
('CNV', '诗篇', 19, 119, 148, '我整夜睁开眼睛，为要默想你的话语。'),
('CNV', '诗篇', 19, 119, 149, '主啊！求你照着你的慈爱垂听我的声音，求你按着你的公正使我存活。'),
('CNV', '诗篇', 19, 119, 150, '追求奸恶的人临近了，他们远离你的律法。'),
('CNV', '诗篇', 19, 119, 151, '主啊！你和我十分接近，你的一切命令都是可信可靠的。'),
('CNV', '诗篇', 19, 119, 152, '我从你的法度早已知道，这些法度是你立定，存到永远的。'),
('CNV', '诗篇', 19, 119, 153, '求你察看我的苦难，搭救我；因为我没有忘记你的律法。'),
('CNV', '诗篇', 19, 119, 154, '求你为我的案件申辩，救赎我；按着你的应许使我存活。'),
('CNV', '诗篇', 19, 119, 155, '救恩远离恶人，因为他们不寻求你的律例。'),
('CNV', '诗篇', 19, 119, 156, '主啊！你的怜悯浩大；求你照着你的公正使我存活。'),
('CNV', '诗篇', 19, 119, 157, '逼迫我的和敌挡我的很多，但我没有偏离你的法度。'),
('CNV', '诗篇', 19, 119, 158, '我看见诡诈的人就讨厌，因为他们不遵守你的话语。'),
('CNV', '诗篇', 19, 119, 159, '你看我多么爱你的训词；主啊！求你按着你的慈爱使我存活。'),
('CNV', '诗篇', 19, 119, 160, '你的话的总纲就是真理，你一切公义的典章要存到永远。'),
('CNV', '诗篇', 19, 119, 161, '领袖们无缘无故迫害我，我的心却畏惧你的话。'),
('CNV', '诗篇', 19, 119, 162, '我因你的话语欢喜，像得了许多战利品的人一样。'),
('CNV', '诗篇', 19, 119, 163, '虚伪是我憎恨厌恶的，你的律法却是我所爱的。'),
('CNV', '诗篇', 19, 119, 164, '我因你公义的典章，一天七次赞美你。'),
('CNV', '诗篇', 19, 119, 165, '喜爱你律法的必有丰盛的平安，什么都不能绊倒他们。'),
('CNV', '诗篇', 19, 119, 166, '主啊！我要等候你的救恩，我要遵行你的命令。'),
('CNV', '诗篇', 19, 119, 167, '我的心谨守你的法度，这些法度是我热爱的。'),
('CNV', '诗篇', 19, 119, 168, '我谨守你的训词和法度，因我所行的一切都在你面前。'),
('CNV', '诗篇', 19, 119, 169, '主啊！愿我的呼求达到你面前；求你照着你的话赐我悟性。'),
('CNV', '诗篇', 19, 119, 170, '愿我的恳求达到你面前；求你照着你的应许拯救我。'),
('CNV', '诗篇', 19, 119, 171, '愿我的嘴唇涌出赞美的话，因为你把你的律例教导了我。'),
('CNV', '诗篇', 19, 119, 172, '愿我的舌头歌唱你的话语，因为你的一切命令都是公义的。'),
('CNV', '诗篇', 19, 119, 173, '愿你的手帮助我，因为我选择了你的训词。'),
('CNV', '诗篇', 19, 119, 174, '主啊！我渴慕你的救恩，我喜欢你的律法。'),
('CNV', '诗篇', 19, 119, 175, '求你容我活着，可以赞美你；愿你的典章帮助我。'),
('CNV', '诗篇', 19, 119, 176, '我像亡羊走迷了路；求你寻找你的仆人，因为我没有忘记你的命令。'),
('CNV', '诗篇', 19, 120, 1, '我在急难中呼求主，他就应允我。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 120, 2, '主啊！求你救我脱离说谎的嘴唇，救我脱离诡诈的舌头。'),
('CNV', '诗篇', 19, 120, 3, '诡诈的舌头啊！他要给你什么呢？他要加给你什么呢？'),
('CNV', '诗篇', 19, 120, 4, '就是勇士的利箭，和罗腾木烧的炭火。'),
('CNV', '诗篇', 19, 120, 5, '我寄居在米设，住在基达的帐棚中，有祸了。'),
('CNV', '诗篇', 19, 120, 6, '我和恨恶和平的人，同住得太久。'),
('CNV', '诗篇', 19, 120, 7, '我希望有和平，但我一说话，他们就要争战。'),
('CNV', '诗篇', 19, 121, 1, '我要向群山举目，我的帮助从哪里来呢？（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 121, 2, '我的帮助是从造天地的主而来。'),
('CNV', '诗篇', 19, 121, 3, '他必不使你的脚滑倒；保护你的必不打盹。'),
('CNV', '诗篇', 19, 121, 4, '看哪！保护以色列的，必不打盹，也不睡觉。'),
('CNV', '诗篇', 19, 121, 5, '保护你的是主，主在你的右边荫庇你。'),
('CNV', '诗篇', 19, 121, 6, '白天太阳必不伤你，夜里月亮必不害你。'),
('CNV', '诗篇', 19, 121, 7, '主要保护你脱离一切灾祸，他要保护你的性命。'),
('CNV', '诗篇', 19, 121, 8, '你出你入，主要保护你，从现在直到永远。'),
('CNV', '诗篇', 19, 122, 1, '人对我说：“我们到主的殿那里去”，我就欢喜。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 122, 2, '耶路撒冷啊！我们的脚正站在你的门内。'),
('CNV', '诗篇', 19, 122, 3, '耶路撒冷被建造，好像一座结构完整的城巿。'),
('CNV', '诗篇', 19, 122, 4, '众支派，就是主的支派，都上那里去；照着以色列的定例，称颂主的名。'),
('CNV', '诗篇', 19, 122, 5, '因为在那里设有审判的宝座，就是大卫家的宝座。'),
('CNV', '诗篇', 19, 122, 6, '你们要为耶路撒冷求平安，说：“耶路撒冷啊！愿爱你的人都亨通。'),
('CNV', '诗篇', 19, 122, 7, '愿你的城墙内有平安，愿你的宫殿中有安稳。”'),
('CNV', '诗篇', 19, 122, 8, '为了我的兄弟和朋友的缘故，我要说：“愿你中间有平安。”'),
('CNV', '诗篇', 19, 122, 9, '为了主我们神的殿的缘故，我要为你求福乐。'),
('CNV', '诗篇', 19, 123, 1, '坐在天上的主啊！我向你举目。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 123, 2, '仆人的眼睛怎样望着主人的手，婢女的眼睛怎样望着主母的手，我们的眼睛也照样望着主我们的神，直到他向我们施恩。'),
('CNV', '诗篇', 19, 123, 3, '主啊！求你向我们施恩，求你向我们施恩；因为我们饱受藐视，到了极点。'),
('CNV', '诗篇', 19, 123, 4, '我们饱受那些安逸的人的嘲笑，和骄傲的人的藐视，到了极点。'),
('CNV', '诗篇', 19, 124, 1, '愿以色列人说：如果不是主帮助我们，（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 124, 2, '如果不是主帮助我们；那么，人起来攻击我们，'),
('CNV', '诗篇', 19, 124, 3, '向我们发怒的时候，就把我们活活吞下去了。'),
('CNV', '诗篇', 19, 124, 4, '那时，洪水漫过我们，急流淹没我们；'),
('CNV', '诗篇', 19, 124, 5, '汹涌的洪水把我们淹没。'),
('CNV', '诗篇', 19, 124, 6, '主是应当称颂的，他没有容让敌人把我们当作猎物撕裂。'),
('CNV', '诗篇', 19, 124, 7, '我们像雀鸟从捕鸟的人的网罗里逃脱；网罗破裂，我们就逃脱了。'),
('CNV', '诗篇', 19, 124, 8, '我们的帮助在于主的名，他是造天地的主。'),
('CNV', '诗篇', 19, 125, 1, '倚靠主的人好像锡安山，总不动摇，永远屹立。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 125, 2, '群山怎样围绕着耶路撒冷，主也照样围绕着他的子民，从现在直到永远。'),
('CNV', '诗篇', 19, 125, 3, '恶人的杖不会常留在义人的地业上，免得义人伸手作恶。'),
('CNV', '诗篇', 19, 125, 4, '主啊！求你善待那些良善，和心里正直的人。'),
('CNV', '诗篇', 19, 125, 5, '至于那些偏行弯曲道路的人，主必把他们和作恶的人一同除去。愿平安归于以色列。'),
('CNV', '诗篇', 19, 126, 1, '主使被掳的人归回锡安的时候，我们好像在作梦的人。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 126, 2, '那时，我们满口喜笑，满舌欢呼；那时列国中有人说：“主为他们行了大事。”'),
('CNV', '诗篇', 19, 126, 3, '主为我们行了大事，我们就欢喜。'),
('CNV', '诗篇', 19, 126, 4, '主啊，求你使我们被掳的人归回，像南地的河水复流一样。'),
('CNV', '诗篇', 19, 126, 5, '那些流泪撒种的，必欢呼收割。'),
('CNV', '诗篇', 19, 126, 6, '那带着种子流着泪出去撒种的，必带着禾捆欢呼快乐地回来。'),
('CNV', '诗篇', 19, 127, 1, '如果不是主建造房屋，建造的人就徒然劳苦；如果不是主看守城池，看守的人就徒然警醒。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 127, 2, '你们清早起来，很晚才歇息，吃劳碌得来的饭，都是徒然；因为主必使他所爱的安睡。'),
('CNV', '诗篇', 19, 127, 3, '儿女是主所赐的产业，腹中的胎儿是他的赏赐。'),
('CNV', '诗篇', 19, 127, 4, '年轻时所生的儿女，好像勇士手中的箭。'),
('CNV', '诗篇', 19, 127, 5, '箭袋装满了箭的人是有福的，他们在城门口和仇敌说话的时候，必不至于羞愧。'),
('CNV', '诗篇', 19, 128, 1, '敬畏主，遵行他的道的人，是有福的。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 128, 2, '你必吃你亲手劳碌得来的，你必享福，事事顺利。'),
('CNV', '诗篇', 19, 128, 3, '你的妻子在你的内室，好像多结果子的葡萄树；你的儿女环绕着你的桌子，好像橄榄树的枝条。'),
('CNV', '诗篇', 19, 128, 4, '看哪！敬畏主的人必这样蒙福。'),
('CNV', '诗篇', 19, 128, 5, '愿主从锡安赐福给你；愿你一生一世得见耶路撒冷的繁荣。'),
('CNV', '诗篇', 19, 128, 6, '愿你得见你儿女的儿女。愿平安归于以色列。'),
('CNV', '诗篇', 19, 129, 1, '愿以色列说：“从我幼年以来，敌人就多次苦害我。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 129, 2, '从我幼年以来，敌人虽然多次苦害我，却没有胜过我。'),
('CNV', '诗篇', 19, 129, 3, '他们好像犁田的人犁在我的背上，所犁的沟甚长。'),
('CNV', '诗篇', 19, 129, 4, '但主是公义的，他砍断了恶人的绳索。”'),
('CNV', '诗篇', 19, 129, 5, '愿所有恨恶锡安的，都蒙羞退后。'),
('CNV', '诗篇', 19, 129, 6, '愿他们像屋顶上的草，尚未长大，就枯干了；'),
('CNV', '诗篇', 19, 129, 7, '收割的不够一把，捆禾的不够满怀。'),
('CNV', '诗篇', 19, 129, 8, '过路的人也不说：“愿主所赐的福临到你们；我们奉主的名祝福你们。”'),
('CNV', '诗篇', 19, 130, 1, '主啊！我从深处向你呼求。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 130, 2, '主啊！求你听我的声音，求你留心听我恳求的声音。'),
('CNV', '诗篇', 19, 130, 3, '主啊！如果你究察罪孽，主啊！谁能站立得住呢？'),
('CNV', '诗篇', 19, 130, 4, '但你有赦免之恩，为要使人敬畏你。'),
('CNV', '诗篇', 19, 130, 5, '我等候主，我的心等候他，我仰望他的话。'),
('CNV', '诗篇', 19, 130, 6, '我的心等候主，比守夜的等候天亮还迫切，比守夜的等候天亮还迫切。'),
('CNV', '诗篇', 19, 130, 7, '以色列啊！你要仰望主，因为主有慈爱，也有丰盛的救恩。'),
('CNV', '诗篇', 19, 130, 8, '他必救赎以色列，脱离一切罪孽。'),
('CNV', '诗篇', 19, 131, 1, '主啊！我的心不骄傲，我的眼不自高；重大和超过我能力的事，我都不敢作。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 131, 2, '我的心平静安稳，像断过奶的孩子躺在他母亲的怀中，我的心在我里面真像断过奶的孩子。'),
('CNV', '诗篇', 19, 131, 3, '以色列啊！你要仰望主，从现在直到永远。'),
('CNV', '诗篇', 19, 132, 1, '主啊！求你记念大卫，记念他的一切苦难。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 132, 2, '他怎样向主起誓，向雅各的大能者许愿，说：'),
('CNV', '诗篇', 19, 132, 3, '“我必不进我的家（“家”原文作“家的帐棚”），也必不上我的床榻。'),
('CNV', '诗篇', 19, 132, 4, '我必不容我的眼睛睡觉，也不容我的眼睑打盹；'),
('CNV', '诗篇', 19, 132, 5, '直到我为主找着一个地方，为雅各的大能者找到居所。”'),
('CNV', '诗篇', 19, 132, 6, '我们听说约柜在以法他；我们在雅珥的田间找到它。'),
('CNV', '诗篇', 19, 132, 7, '“我们要进入他的居所，在他的脚凳前下拜。'),
('CNV', '诗篇', 19, 132, 8, '主啊，求你起来，求你和你有能力的约柜同入安息的居所。'),
('CNV', '诗篇', 19, 132, 9, '愿你的祭司都披上公义，愿你的圣民都欢呼。'),
('CNV', '诗篇', 19, 132, 10, '求你因你仆人大卫的缘故，不要转脸不理你的受膏者。”'),
('CNV', '诗篇', 19, 132, 11, '主实实在在向大卫起了誓，他必不会收回，他说：“我要从你的后裔中，立一位坐在你的王位上。'),
('CNV', '诗篇', 19, 132, 12, '如果你的子孙谨守我的约，和我教训他们的法度，他们的子孙也必永远坐在你的王位上。”'),
('CNV', '诗篇', 19, 132, 13, '因为主拣选了锡安，定意把它当作自己的居所。他说：'),
('CNV', '诗篇', 19, 132, 14, '“这是我永远安息的居所；我要住在这里，因为我定意这样作。'),
('CNV', '诗篇', 19, 132, 15, '我要赐给锡安丰盛的粮食，我要使城中的穷人饱足。'),
('CNV', '诗篇', 19, 132, 16, '我要使祭司都披上救恩，使圣民都大大欢呼。'),
('CNV', '诗篇', 19, 132, 17, '我要在那里使大卫的角长起来，我要为我的受膏者安排明灯。'),
('CNV', '诗篇', 19, 132, 18, '我要使他的仇敌都披上羞辱，但他的冠冕必在他头上发光。”'),
('CNV', '诗篇', 19, 133, 1, '看哪！弟兄和睦共处，是多么的善，多么的美。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 133, 2, '这好比那珍贵的油浇在亚伦的头上，流到胡须，又从亚伦的胡须，流到他的衣领上。'),
('CNV', '诗篇', 19, 133, 3, '又好比黑门的甘露落在锡安的众山上，在那里有主命定的福，就是永远的生命。'),
('CNV', '诗篇', 19, 134, 1, '主的众仆人哪！你们要称颂主；夜间在主殿中侍候的，你们要称颂主。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 134, 2, '你们要向圣所举手祷告，称颂主。'),
('CNV', '诗篇', 19, 134, 3, '愿造天地的主，从锡安赐福给你们。'),
('CNV', '诗篇', 19, 135, 1, '你们要赞美主，你们要赞美主的名；主的众仆人哪！你们都要赞美他。'),
('CNV', '诗篇', 19, 135, 2, '在主殿中侍候的，在我们神殿的院里侍候的，你们要赞美他。'),
('CNV', '诗篇', 19, 135, 3, '你们要赞美主，因主本是良善的；你们要歌颂他的名，因为他的名是美好的。'),
('CNV', '诗篇', 19, 135, 4, '因为主拣选了雅各归他自己，拣选了以色列作他自己的产业。'),
('CNV', '诗篇', 19, 135, 5, '我确实知道主是伟大的，我们的主超越万神之上。'),
('CNV', '诗篇', 19, 135, 6, '在天上，在地上，在海中，在一切深处，主喜欢什么，就作什么。'),
('CNV', '诗篇', 19, 135, 7, '他使云雾从地极上升，发出闪电随雨而来，又从他的府库吹出风来。'),
('CNV', '诗篇', 19, 135, 8, '他把埃及头生的，无论人或牲畜都击杀了。'),
('CNV', '诗篇', 19, 135, 9, '埃及啊！他在你当中施行神迹和奇事，惩罚法老和他所有的臣仆。'),
('CNV', '诗篇', 19, 135, 10, '他击杀了多国的民，杀戮了强悍的王，'),
('CNV', '诗篇', 19, 135, 11, '就是亚摩利王西宏、巴珊王噩，和迦南列国的王。'),
('CNV', '诗篇', 19, 135, 12, '他把他们的地赐给了自己的子民以色列作产业。'),
('CNV', '诗篇', 19, 135, 13, '主啊！你的名存到永远；主啊！你可记念的名留存万代。'),
('CNV', '诗篇', 19, 135, 14, '因为主要为自己的子民伸冤，他要怜悯自己的仆人。'),
('CNV', '诗篇', 19, 135, 15, '列国的偶像是金的银的，是人手所做的。'),
('CNV', '诗篇', 19, 135, 16, '有口却不能说话，有眼却不能看，'),
('CNV', '诗篇', 19, 135, 17, '有耳却不能听，口中也没有气息。'),
('CNV', '诗篇', 19, 135, 18, '做偶像的必和它们一样，所有倚靠它们的也必这样。'),
('CNV', '诗篇', 19, 135, 19, '以色列家啊！你们要称颂主；亚伦家啊！你们要称颂主；'),
('CNV', '诗篇', 19, 135, 20, '利未家啊！你们要称颂主；敬畏主的，你们要称颂主。'),
('CNV', '诗篇', 19, 135, 21, '从锡安来的主，就是住在耶路撒冷的，是应当称颂的。你们要赞美主。'),
('CNV', '诗篇', 19, 136, 1, '你们要称谢主，因他本是良善的，他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 2, '你们要称谢万神之神，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 3, '你们要称谢万主之主，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 4, '要称谢那独行大奇事的，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 5, '要称谢那用智慧造成诸天的，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 6, '要称谢那铺张大地在水上的，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 7, '要称谢那造成大光的，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 8, '他造太阳管白昼，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 9, '他造月亮和星星管黑夜，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 10, '要称谢那击杀埃及所有头生的，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 11, '他领以色列人从他们中间出来，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 12, '他用大能的手和伸出来的膀臂领他们出来，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 13, '要称谢那分开红海的，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 14, '他领以色列人从海中经过，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 15, '他把法老和他的军兵都抖落在红海里，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 16, '要称谢那引导自己的子民走过旷野的，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 17, '要称谢那击杀大君王的，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 18, '他杀戮了强盛的君王，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 19, '他杀了亚摩利王西宏，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 20, '他杀了巴珊王噩，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 21, '他把他们的地赐给了自己的子民作产业，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 22, '他把他们的地赐给他的仆人以色列作产业，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 23, '他在我们卑微的时候顾念我们，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 24, '他救我们脱离了敌人，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 25, '他把粮食赐给全人类，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 136, 26, '你们要称谢天上的神，因为他的慈爱永远长存。'),
('CNV', '诗篇', 19, 137, 1, '我们曾坐在巴比伦的河畔，在那里我们一想起锡安就哭了。'),
('CNV', '诗篇', 19, 137, 2, '我们把我们的琴挂在那里的柳树上。'),
('CNV', '诗篇', 19, 137, 3, '因为在那里，掳掠我们的人要我们唱歌，苦待我们的人要我们娱乐他们；他们说：“为我们唱一首锡安歌吧！”'),
('CNV', '诗篇', 19, 137, 4, '我们怎能在异族之地唱主的歌呢？'),
('CNV', '诗篇', 19, 137, 5, '耶路撒冷啊！如果我忘记你，情愿我的右手忘记技巧（“忘记技巧”或译：“枯干”）。'),
('CNV', '诗篇', 19, 137, 6, '如果我不记念你，如果我不高举耶路撒冷超过我最大的喜乐，情愿我的舌头紧贴上膛。'),
('CNV', '诗篇', 19, 137, 7, '主啊！求你记念以东人在耶路撒冷遭难的日子所行的，他们说：“拆毁它，拆毁它，直拆到根基。”'),
('CNV', '诗篇', 19, 137, 8, '将要被毁灭的（“将要被毁灭的”有古译本作“毁灭者”）巴比伦城（“城”原文作“女子”）啊！照着你待我们的行为报复你的，那人有福了。'),
('CNV', '诗篇', 19, 137, 9, '抓住你的婴孩摔在磐石上的，那人有福了。'),
('CNV', '诗篇', 19, 138, 1, '我要一心称谢你，我要在众神面前歌颂你。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 138, 2, '我要向你的圣殿下拜，我要因你的慈爱和信实称谢你的名；因为你使你的名和应许显为大，超过一切（“因为你使你的名和应许显为大，超过一切”原文作“因为你使你的应许显为大，超过你的一切名字”）。'),
('CNV', '诗篇', 19, 138, 3, '我呼求的日子，你就应允我；你使我刚强，心里有力。'),
('CNV', '诗篇', 19, 138, 4, '主啊！世上的君王都要称谢你，因为他们听见了你口中的言语。'),
('CNV', '诗篇', 19, 138, 5, '他们要歌颂主的作为，因为主大有荣耀。'),
('CNV', '诗篇', 19, 138, 6, '主虽然高高在上，仍然看顾卑微的人；他却从远处认出骄傲的人。'),
('CNV', '诗篇', 19, 138, 7, '我虽然处身在患难之中，你仍使我存活；我仇敌的怒气，你必伸手抵挡；你的右手必拯救我。'),
('CNV', '诗篇', 19, 138, 8, '主必成全关乎我的事；主啊！你的慈爱永远长存，求你不要离弃你手所造的。'),
('CNV', '诗篇', 19, 139, 1, '主啊！你鉴察了我，你认识我。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 139, 2, '我坐下，我起来，你都知道；你在远处就明白我的意念。'),
('CNV', '诗篇', 19, 139, 3, '我行路，我躺卧，你都细察；我的一切行为，你都熟悉。'),
('CNV', '诗篇', 19, 139, 4, '主啊！我的舌头还没有发言，你已经完全知道了。'),
('CNV', '诗篇', 19, 139, 5, '你在我前后围绕着我，你的手按在我身上。'),
('CNV', '诗篇', 19, 139, 6, '这样的知识奇妙，是我不能理解的；高超，是我不能达到的。'),
('CNV', '诗篇', 19, 139, 7, '我到哪里去躲避你的灵？我往哪里去逃避你的面呢？'),
('CNV', '诗篇', 19, 139, 8, '如果我升到天上，你在那里；如果我在阴间下榻，你也在那里。'),
('CNV', '诗篇', 19, 139, 9, '如果我展开清晨的翅膀，飞到海的极处居住，'),
('CNV', '诗篇', 19, 139, 10, '就是在那里，你的手仍必引导我，你的右手也必扶持我。'),
('CNV', '诗篇', 19, 139, 11, '如果我说：“愿黑暗遮盖我，愿我周围的亮光变成黑夜。”'),
('CNV', '诗篇', 19, 139, 12, '但对你来说，黑暗也不算是黑暗，黑夜必如同白昼一样发亮，黑暗和光明，在你看来都是一样的。'),
('CNV', '诗篇', 19, 139, 13, '我的脏腑是你所造的，在我母腹中你塑造了我。'),
('CNV', '诗篇', 19, 139, 14, '我要称谢你，因为我的受造奇妙可畏；你的作为奇妙，这是我深深知道的。'),
('CNV', '诗篇', 19, 139, 15, '我在隐密处被造，在地的深处被塑造，那时，我的形体不能向你隐藏。'),
('CNV', '诗篇', 19, 139, 16, '我未成形的身体，你的眼睛早已看见；为我所定的日子，我还未度过一日，都完全记在你的册上了。'),
('CNV', '诗篇', 19, 139, 17, '神啊！你的意念对我多么珍贵（“珍贵”或译：“深奥”），数目何等众多。'),
('CNV', '诗篇', 19, 139, 18, '如果我数点，它们比海沙更多；我睡醒的时候，仍然与你同在。'),
('CNV', '诗篇', 19, 139, 19, '神啊！甚愿你杀戮恶人；你们流人血的啊，离开我去吧！'),
('CNV', '诗篇', 19, 139, 20, '他们恶意说话顶撞你，你的仇敌妄称你的名。'),
('CNV', '诗篇', 19, 139, 21, '主啊！恨恶你的，我怎能不恨恶他们呢？起来攻击你的，我怎能不厌恶他们呢？'),
('CNV', '诗篇', 19, 139, 22, '我极度恨恶他们，把他们视为我的仇敌。'),
('CNV', '诗篇', 19, 139, 23, '神啊！求你鉴察我，知道我的心思；试验我，知道我的意念。'),
('CNV', '诗篇', 19, 139, 24, '看看我里面有什么恶行没有，引导我走永恒的道路。'),
('CNV', '诗篇', 19, 140, 1, '主啊！求你拯救我脱离恶人，求你保护我脱离强暴的人。'),
('CNV', '诗篇', 19, 140, 2, '他们心中图谋恶事，整天挑启争端。'),
('CNV', '诗篇', 19, 140, 3, '他们使自己的舌头尖利，如同蛇的舌头；他们嘴里有虺蛇的毒。（细拉）'),
('CNV', '诗篇', 19, 140, 4, '主啊！求你保护我脱离恶人的手，保护我脱离强暴的人，因为他们图谋推倒我。'),
('CNV', '诗篇', 19, 140, 5, '骄傲的人暗中布下陷阱害我，他们在路旁张开绳索作网，设下圈套陷害我。（细拉）'),
('CNV', '诗篇', 19, 140, 6, '我曾对主说：“你是我的神；主啊！求你留心听我恳求的声音！”'),
('CNV', '诗篇', 19, 140, 7, '主神，拯救我的力量啊，在争战的日子，你保护了我的头。'),
('CNV', '诗篇', 19, 140, 8, '主啊！求你不要容恶人的心愿得偿，不要使他们的计谋成功，免得他们自高自大。（细拉）'),
('CNV', '诗篇', 19, 140, 9, '至于那些围困我的人，愿他们的头被自己嘴唇的奸恶遮盖。'),
('CNV', '诗篇', 19, 140, 10, '愿炭火落在他们身上；愿他们掉在深坑里，不能再起来。'),
('CNV', '诗篇', 19, 140, 11, '愿搬弄是非的人在地上站立不住；愿灾祸连连猎取强暴的人。'),
('CNV', '诗篇', 19, 140, 12, '我知道主必为困苦人伸冤，必替穷乏人辨屈。'),
('CNV', '诗篇', 19, 140, 13, '义人必称赞你的名，正直的人必住在你面前。'),
('CNV', '诗篇', 19, 141, 1, '主啊！我呼求你，求你快来帮助我；我呼求你的时候，求你留心听我的声音。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 141, 2, '愿我的祷告好像香安放在你面前；愿我的手高举好像献晚祭。'),
('CNV', '诗篇', 19, 141, 3, '主啊！求你看守我的口，把守我的嘴。'),
('CNV', '诗篇', 19, 141, 4, '求你不要容我的心偏向恶事，免得我和作孽的人一同行恶，也不要使我吃他们的美食。'),
('CNV', '诗篇', 19, 141, 5, '愿义人击打我，这是出于慈爱；愿他责备我，这是膏我头的膏油，我的头不会拒绝。我仍要为恶人的恶行祷告。'),
('CNV', '诗篇', 19, 141, 6, '他们的官长被摔在山崖下的时候，他们就要听我的话，因为我的话甘美。'),
('CNV', '诗篇', 19, 141, 7, '他们说：“我们的骨头被抛散在墓旁，好像人犁田锄地时掘起的土块。”'),
('CNV', '诗篇', 19, 141, 8, '主神啊！我的眼睛仰望你；我投靠你，求你不要使我丧命。'),
('CNV', '诗篇', 19, 141, 9, '求你保护我脱离恶人为我所设的网罗，和作孽的人的圈套。'),
('CNV', '诗篇', 19, 141, 10, '愿恶人都落在自己的网罗里，我却得以安然逃脱。'),
('CNV', '诗篇', 19, 142, 1, '我大声向主呼求，高声向主恳求。'),
('CNV', '诗篇', 19, 142, 2, '我在他面前倾吐我的苦情，在他面前陈述我的患难。'),
('CNV', '诗篇', 19, 142, 3, '我的灵在我里面软弱的时候，你知道我的道路。在我所行的路上，敌人暗设网罗陷害我。'),
('CNV', '诗篇', 19, 142, 4, '求你向我右边观看，没有人关心我；我没有逃难的地方，也没有人照顾我。'),
('CNV', '诗篇', 19, 142, 5, '主啊！我向你呼求；我说：“你是我的避难所，是我在活人之地的业分。'),
('CNV', '诗篇', 19, 142, 6, '求你留心听我的呼求，因为我落到极卑微的地步；求你救我脱离逼迫我的人，因为他们比我强大。'),
('CNV', '诗篇', 19, 142, 7, '求你把我从牢狱中领出来，好让我称赞你的名；义人必环绕着我，因为你以厚恩待我。”'),
('CNV', '诗篇', 19, 143, 1, '主啊！求你听我的祷告，留心听我的恳求，凭你的信实和公义应允我。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 143, 2, '求你不要审判你的仆人，因为凡活着的人，在你面前没有一个是义的。'),
('CNV', '诗篇', 19, 143, 3, '仇敌逼迫我，把我压倒在地，使我住在黑暗之处，像死了很久的人一样。'),
('CNV', '诗篇', 19, 143, 4, '因此我的灵在我里面软弱，我的心在我里面战栗。'),
('CNV', '诗篇', 19, 143, 5, '我追念以往的日子，默想你的一切作为，沉思你手所作的。'),
('CNV', '诗篇', 19, 143, 6, '我向你伸出双手，我的心渴想你，好像干旱的地盼望雨水一样。（细拉）'),
('CNV', '诗篇', 19, 143, 7, '主啊！求你快快应允我，我的心灵已经衰竭，求你不要向我掩面，免得我像那些下坑的人一样。'),
('CNV', '诗篇', 19, 143, 8, '求你使我清晨得闻你的慈爱，因为我倚靠你。求你指示我当走的路，因为我的心仰望你。'),
('CNV', '诗篇', 19, 143, 9, '主啊！求你救我脱离我的仇敌，我往你那里藏身。'),
('CNV', '诗篇', 19, 143, 10, '求你教我遵行你的旨意，因为你是我的神；愿你至善的灵引导我到平坦的地。'),
('CNV', '诗篇', 19, 143, 11, '主啊！求你为你名的缘故使我存活，按着你的公义把我从患难中领出来。'),
('CNV', '诗篇', 19, 143, 12, '求你因你的慈爱使我的仇敌灭绝，求你消灭所有苦害我的人，因为我是你的仆人。'),
('CNV', '诗篇', 19, 144, 1, '主我的磐石是应当称颂的。他教导我的手作战，训练我的指头打仗。（本节在《马索拉文本》包括细字标题）'),
('CNV', '诗篇', 19, 144, 2, '他是我慈爱的神、我的堡垒、我的高台、我的救主、我的盾牌、我所投靠的，他使我的人民服在我以下。'),
('CNV', '诗篇', 19, 144, 3, '主啊！人算什么，你竟关怀他，世人算什么，你竟眷念他。'),
('CNV', '诗篇', 19, 144, 4, '人不过像一口气，他的年日仿佛影子消逝。'),
('CNV', '诗篇', 19, 144, 5, '主啊！求你使天下垂，亲自降临；求你触摸群山，使山冒烟。'),
('CNV', '诗篇', 19, 144, 6, '求你发出闪电，使仇敌四散；求你射出你的箭，使他们溃乱。'),
('CNV', '诗篇', 19, 144, 7, '求你从高天伸手救拔我，从大水之中，从外族人的手里拯救我。'),
('CNV', '诗篇', 19, 144, 8, '他们的口说虚谎的话，他们举起右手起假誓。'),
('CNV', '诗篇', 19, 144, 9, '神啊！我要向你唱新歌，我要用十弦琴向你歌唱。'),
('CNV', '诗篇', 19, 144, 10, '你是那使君王得胜的，是那救拔你（“你”原文作“他”）仆人大卫脱离杀人的刀的。'),
('CNV', '诗篇', 19, 144, 11, '求你救拔我，从外族人的手里拯救我；他们的口说虚谎的话，他们举起右手起假誓。'),
('CNV', '诗篇', 19, 144, 12, '愿我们的儿子，在幼年时都像旺盛的树木；愿我们的女儿如同殿四角的柱子，为建造殿宇而凿成的。'),
('CNV', '诗篇', 19, 144, 13, '愿我们的仓库满溢，各种粮食不缺；愿我们牧场上的羊群，孳生千万。'),
('CNV', '诗篇', 19, 144, 14, '愿我们的牛群满驮货物；城墙没有缺口，没有人出去争战（“愿我们⋯⋯出去争战”或译：“愿我们的牛群多生多养，没有流产，没有死掉”），在我们的街上也没有呼叫的声音。'),
('CNV', '诗篇', 19, 144, 15, '得享这样景况的人民，是有福的，有主作他们神的，这人是有福的。'),
('CNV', '诗篇', 19, 145, 1, '我的神，我的王啊！我要尊崇你，（本节在《马索拉文本》包括细字标题）我要永永远远称颂你的名。'),
('CNV', '诗篇', 19, 145, 2, '我要天天称颂你，我要永永远远赞美你的名。'),
('CNV', '诗篇', 19, 145, 3, '主是至大的，配受极大的赞美，他的伟大无法测度。'),
('CNV', '诗篇', 19, 145, 4, '世世代代的人都要颂赞你的作为，他们要传扬你大能的作为。'),
('CNV', '诗篇', 19, 145, 5, '他们要讲述你威严的尊荣，我也要默想你奇妙的作为。'),
('CNV', '诗篇', 19, 145, 6, '他们要述说你所行可畏的事的能力，我也要宣扬你的伟大。'),
('CNV', '诗篇', 19, 145, 7, '他们要传述你可记念、至善的名，也要歌唱你的公义。'),
('CNV', '诗篇', 19, 145, 8, '主有恩典有怜悯，不轻易发怒，大有慈爱。'),
('CNV', '诗篇', 19, 145, 9, '主善待万有，他的怜悯临到他一切所造的。'),
('CNV', '诗篇', 19, 145, 10, '主啊！你一切所造的都要称谢你，你的圣民也要称颂你。'),
('CNV', '诗篇', 19, 145, 11, '他们要讲论你国的荣耀，也要述说你大能的作为。'),
('CNV', '诗篇', 19, 145, 12, '好使世人知道你大能的作为，和你国威严的尊荣。'),
('CNV', '诗篇', 19, 145, 13, '你的国是永远的国，你的王权存到万代（七十士译本加上“主在他的话是信实的，在他一切的作为都是圣洁的”﹔死海古卷则有“神在他的话是信实的，在他一切的作为都是慈爱的”和“主是应当称颂的，应当永远称颂他的名”等句）。'),
('CNV', '诗篇', 19, 145, 14, '跌倒的，主都扶持他们；被压迫的，他都扶他们起来。'),
('CNV', '诗篇', 19, 145, 15, '万人的眼睛都仰望你，你按时把粮食赐给他们。'),
('CNV', '诗篇', 19, 145, 16, '你把手张开，使所有生物都随愿得到饱足。'),
('CNV', '诗篇', 19, 145, 17, '主在他一切所行的事上，都是公义的，他对他一切所造的，都存着慈爱的心。'),
('CNV', '诗篇', 19, 145, 18, '凡是求告主的，主都和他们接近，就是和所有真诚求告他的人接近。'),
('CNV', '诗篇', 19, 145, 19, '敬畏他的，他必成就他们的心愿，也必听他们的呼求，拯救他们。'),
('CNV', '诗篇', 19, 145, 20, '主保护所有爱他的人，却要消灭所有恶人。'),
('CNV', '诗篇', 19, 145, 21, '我的口要说赞美主的话；愿所有的人都永永远远称颂他的圣名。'),
('CNV', '诗篇', 19, 146, 1, '你们要赞美主。我的心哪！要赞美主。'),
('CNV', '诗篇', 19, 146, 2, '我还活着的时候，我要赞美主；我还在世上的时候，我要歌颂我的神。'),
('CNV', '诗篇', 19, 146, 3, '你们不要倚靠权贵，不要倚靠世人，他们一点都不能救助你们。'),
('CNV', '诗篇', 19, 146, 4, '他们的气一断，就归回尘土；他们所计划的，当天就幻灭了。'),
('CNV', '诗篇', 19, 146, 5, '以雅各的神为自己的帮助，仰望主他的神的，这人就是有福的。'),
('CNV', '诗篇', 19, 146, 6, '主造天、地、海，和其中的万物；他持守信实，直到永远。'),
('CNV', '诗篇', 19, 146, 7, '他为受欺压的人伸冤，赐食物给饥饿的人，主使被囚的得自由。'),
('CNV', '诗篇', 19, 146, 8, '主开了瞎子的眼睛，主扶起被压迫的人，主喜爱义人。'),
('CNV', '诗篇', 19, 146, 9, '主保护寄居的，扶持孤儿寡妇，却使恶人的行动挫败。'),
('CNV', '诗篇', 19, 146, 10, '愿主作王，直到永远！锡安哪！愿你的神作王，直到万代。你们要赞美主。'),
('CNV', '诗篇', 19, 147, 1, '你们要赞美主。歌颂我们的神，这是多么美善，赞美他，这是美好的，是合宜的。'),
('CNV', '诗篇', 19, 147, 2, '主重建耶路撒冷，召聚被赶散的以色列人。'),
('CNV', '诗篇', 19, 147, 3, '他医好伤心的人，裹好他们的伤处。'),
('CNV', '诗篇', 19, 147, 4, '他数点星辰的数目，一一给它们起名。'),
('CNV', '诗篇', 19, 147, 5, '我们的主伟大，大有能力；他的智慧无法测度。'),
('CNV', '诗篇', 19, 147, 6, '主扶持谦卑的人，却把恶人丢弃在地。'),
('CNV', '诗篇', 19, 147, 7, '你们要以感谢的心向主歌唱，用琴向我们的神歌颂。'),
('CNV', '诗篇', 19, 147, 8, '他以密云遮盖天空，为大地预备雨水，使群山长满青草。'),
('CNV', '诗篇', 19, 147, 9, '他把食物赐给走兽，也赐给啼叫的小乌鸦。'),
('CNV', '诗篇', 19, 147, 10, '他喜欢的不是马的力大，他喜悦的不是人的腿快。'),
('CNV', '诗篇', 19, 147, 11, '主喜悦敬畏他的人，喜悦仰望他慈爱的人。'),
('CNV', '诗篇', 19, 147, 12, '耶路撒冷啊！你要颂赞主；锡安哪！你要赞美你的神。'),
('CNV', '诗篇', 19, 147, 13, '因为他坚固了你城门的门闩，赐福在你中间的儿女。'),
('CNV', '诗篇', 19, 147, 14, '他使你的边界平靖；用上好的麦子使你饱足。'),
('CNV', '诗篇', 19, 147, 15, '他向地发出命令，他的话迅速颁行。'),
('CNV', '诗篇', 19, 147, 16, '他降下像羊毛一样的雪，撒下像炉灰一样的霜。'),
('CNV', '诗篇', 19, 147, 17, '他抛下像碎屑一样的冰雹；面对他发出的寒冷，谁能承受得起呢？'),
('CNV', '诗篇', 19, 147, 18, '他发出命令，这一切就都融化；他使风刮起，水就流动。'),
('CNV', '诗篇', 19, 147, 19, '他把自己的话向雅各颁布，把自己的律例和典章向以色列颁布。'),
('CNV', '诗篇', 19, 147, 20, '他从没有这样对待其他各国；他们都不知道他的典章。你们要赞美主。'),
('CNV', '诗篇', 19, 148, 1, '你们要赞美主。你们要从天上赞美主，在高天赞美他。'),
('CNV', '诗篇', 19, 148, 2, '他的众使者啊！你们要赞美他；他的众军啊！你们也要赞美他。'),
('CNV', '诗篇', 19, 148, 3, '太阳和月亮啊！你们要赞美他；光亮的星星啊！你们都要赞美他。'),
('CNV', '诗篇', 19, 148, 4, '天上的天啊！你们要赞美他。天上的水啊！你们要赞美他。'),
('CNV', '诗篇', 19, 148, 5, '愿这一切都赞美主的名，因为他一发令，它们就都造成。'),
('CNV', '诗篇', 19, 148, 6, '他把它们立定，直到永永远远；他立了定律，永不废去（“废去”或译：“越过”）。'),
('CNV', '诗篇', 19, 148, 7, '你们要从地上赞美主。海怪和一切深海，'),
('CNV', '诗篇', 19, 148, 8, '火和冰雹，雪和云雾，执行他命令的狂风，'),
('CNV', '诗篇', 19, 148, 9, '大山和一切小山，果树和一切香柏树，'),
('CNV', '诗篇', 19, 148, 10, '野兽和一切牲畜，爬行的动物和飞鸟，'),
('CNV', '诗篇', 19, 148, 11, '地上的君王和万族的人民，领袖和地上所有的审判官，'),
('CNV', '诗篇', 19, 148, 12, '少男和少女，老年人和孩童，'),
('CNV', '诗篇', 19, 148, 13, '愿这一切都赞美主的名，因为独有他的名被尊崇，他的荣耀超越天地。'),
('CNV', '诗篇', 19, 148, 14, '他使自己子民的角得以高举（“他使自己子民的角得以高举”或译：“他为自己的子民兴起一个君王”；“君王”原文作“角”），他所有的圣民，就是和他接近的以色列人，都赞美他。你们要赞美主。'),
('CNV', '诗篇', 19, 149, 1, '你们要赞美主，要向主唱新歌，在圣民的会中赞美他。'),
('CNV', '诗篇', 19, 149, 2, '愿以色列因造他的主欢喜，愿锡安的居民因他们的王快乐。'),
('CNV', '诗篇', 19, 149, 3, '愿他们一边跳舞，一边赞美他的名，击鼓弹琴歌颂他。'),
('CNV', '诗篇', 19, 149, 4, '因为主喜悦自己的子民，以救恩给谦卑的人作装饰。'),
('CNV', '诗篇', 19, 149, 5, '愿圣民因所得的荣耀高兴，愿他们在床上欢呼。'),
('CNV', '诗篇', 19, 149, 6, '愿称赞神的话常在他们口中；愿他们手里拿着两刃的剑，'),
('CNV', '诗篇', 19, 149, 7, '为要报复列国，惩罚万民；'),
('CNV', '诗篇', 19, 149, 8, '用锁链捆住他们的君王，用铁镣锁住他们的权贵，'),
('CNV', '诗篇', 19, 149, 9, '要在他们身上施行记录在册上的审判。这就是他所有圣民的尊荣。你们要赞美主。'),
('CNV', '诗篇', 19, 150, 1, '你们要赞美主。要在神的圣所赞美他，要在他显能力的穹苍下赞美他。'),
('CNV', '诗篇', 19, 150, 2, '要因他大能的作为赞美他，要因他无限的伟大赞美他。'),
('CNV', '诗篇', 19, 150, 3, '要吹角赞美他，要鼓瑟弹琴赞美他。'),
('CNV', '诗篇', 19, 150, 4, '要击鼓跳舞赞美他，要弹奏丝弦的乐器和吹箫赞美他。'),
('CNV', '诗篇', 19, 150, 5, '要用声音洪亮的钹赞美他，要用声音铿锵的钹赞美他。'),
('CNV', '诗篇', 19, 150, 6, '凡有气息的，都要赞美主。你们要赞美主。'),
('CNV', '箴言', 20, 1, 1, '大卫的儿子以色列王所罗门的箴言：'),
('CNV', '箴言', 20, 1, 2, '要使人晓得智慧和教训，了解充满哲理的言语；'),
('CNV', '箴言', 20, 1, 3, '使人领受明慧的教训，就是公义、公正和正直；'),
('CNV', '箴言', 20, 1, 4, '使愚蒙人变成精明，使少年人获得知识和明辨的能力；'),
('CNV', '箴言', 20, 1, 5, '使智慧人听了，可以增长学问，使聪明人听了，可以获得智谋；')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '箴言', 20, 1, 6, '使人明白箴言和譬喻，懂得智慧人的言词和他们的隐语。'),
('CNV', '箴言', 20, 1, 7, '敬畏主是知识的开端，但愚妄人藐视智慧和教训。'),
('CNV', '箴言', 20, 1, 8, '我儿，要听从你父亲的教训，不可离弃你母亲的训诲。'),
('CNV', '箴言', 20, 1, 9, '因为这些要作你头上的华冠，作你颈上的金链。'),
('CNV', '箴言', 20, 1, 10, '我儿，如果坏人引诱你，你不可随从他们。'),
('CNV', '箴言', 20, 1, 11, '如果他们说：“你跟我们来吧！我们要埋伏流人的血，我们要无故地潜伏伤害无辜的人；'),
('CNV', '箴言', 20, 1, 12, '我们要好像阴间一般，把他们活生生吞下，他们整个被我们吞下，如同下坑的人一样；'),
('CNV', '箴言', 20, 1, 13, '这样，我们必得着各样贵重的财物，把掠物装满我们的房子。'),
('CNV', '箴言', 20, 1, 14, '加入我们的行列吧！我们大家共享一个钱袋。”'),
('CNV', '箴言', 20, 1, 15, '我儿，不可和他们走在一起，禁止你的脚走他们的路；'),
('CNV', '箴言', 20, 1, 16, '因为他们的脚奔向邪恶，他们急于流人的血。'),
('CNV', '箴言', 20, 1, 17, '在飞鸟眼前张设网罗，是徒劳无功的。'),
('CNV', '箴言', 20, 1, 18, '他们埋伏，是自流己血；他们潜伏，是自害己命。'),
('CNV', '箴言', 20, 1, 19, '凡是贪爱不义之财的，所走的路都是这样；那不义之财夺去了贪财者的性命。'),
('CNV', '箴言', 20, 1, 20, '智慧在街上呼喊，在广场上扬声；'),
('CNV', '箴言', 20, 1, 21, '在闹市中心呼叫，在城门口发出言语，说：'),
('CNV', '箴言', 20, 1, 22, '“你们愚蒙人喜爱愚蒙，好讥笑的人喜欢讥笑，愚昧人恨恶知识，要到几时呢？'),
('CNV', '箴言', 20, 1, 23, '你们要因我的责备回转，我就把我的心意（“心意”或译：“灵”）向你们倾吐，把我的话指示你们。'),
('CNV', '箴言', 20, 1, 24, '我呼唤，你们不肯听从；我伸手，没有人理会。'),
('CNV', '箴言', 20, 1, 25, '你们既轻忽我的一切劝告，不肯接受我的责备；'),
('CNV', '箴言', 20, 1, 26, '所以你们遭难的时候，我就发笑；惊恐临到你们的日子，我就嗤笑。'),
('CNV', '箴言', 20, 1, 27, '惊恐临到你们好像风暴，灾难如同飓风来临，患难困苦临到你们身上。'),
('CNV', '箴言', 20, 1, 28, '那时，他们必呼求我，我却不回答；他们切切寻找我，却寻不见；'),
('CNV', '箴言', 20, 1, 29, '因为他们恨恶知识，不选择敬畏主；'),
('CNV', '箴言', 20, 1, 30, '不接受我的劝告，轻视我的一切责备；'),
('CNV', '箴言', 20, 1, 31, '所以，他们必自食其果，必饱尝自己所设计谋的伤害。'),
('CNV', '箴言', 20, 1, 32, '愚蒙人的背道必杀害他们自己，愚昧人的安逸必毁灭他们自己；'),
('CNV', '箴言', 20, 1, 33, '唯有听从我的，必安然居住，得享安宁，免受灾祸的惊恐。”'),
('CNV', '箴言', 20, 2, 1, '我儿，如果你接受我的话，把我的诫命珍藏在心里，'),
('CNV', '箴言', 20, 2, 2, '留心听智慧，致力求聪明；'),
('CNV', '箴言', 20, 2, 3, '如果你为求哲理而呼喊，为求聪明而扬声；'),
('CNV', '箴言', 20, 2, 4, '如果你寻找它如同寻找银子，搜寻它好像搜寻宝藏；'),
('CNV', '箴言', 20, 2, 5, '你就明白怎样敬畏主，并且获得对神的认识。'),
('CNV', '箴言', 20, 2, 6, '因为主赐人智慧，知识和聪明都出自他的口。'),
('CNV', '箴言', 20, 2, 7, '他为正直人珍藏大智慧，给行为完全的人作盾牌；'),
('CNV', '箴言', 20, 2, 8, '为要看顾正直人的路径，护卫虔诚人的道路。'),
('CNV', '箴言', 20, 2, 9, '这样，你就明白公义、公正、正直，以及一切善道。'),
('CNV', '箴言', 20, 2, 10, '智慧必进入你的心，知识必使你欢悦。'),
('CNV', '箴言', 20, 2, 11, '明辨的能力必护卫你，聪明必看顾你；'),
('CNV', '箴言', 20, 2, 12, '要救你脱离邪恶的道路，脱离说话乖谬的人。'),
('CNV', '箴言', 20, 2, 13, '那些人离弃正道，走上黑暗的道路。'),
('CNV', '箴言', 20, 2, 14, '他们喜欢行恶，喜悦恶人的乖谬。'),
('CNV', '箴言', 20, 2, 15, '他们的道路弯曲，他们的行径偏离正道。'),
('CNV', '箴言', 20, 2, 16, '智慧要救你脱离淫妇，脱离说谄媚话的妓女。'),
('CNV', '箴言', 20, 2, 17, '她离弃年轻时的配偶，忘记了神的约；'),
('CNV', '箴言', 20, 2, 18, '她的家陷入死地，她的路径下落阴间。'),
('CNV', '箴言', 20, 2, 19, '凡是进到她那里去的，都不能转回，必得不着生路。'),
('CNV', '箴言', 20, 2, 20, '因此，智慧必使你走在良善人的道上，持守义人的路。'),
('CNV', '箴言', 20, 2, 21, '因为正直人必在地上安居，完全人必在世上存留；'),
('CNV', '箴言', 20, 2, 22, '但恶人必从地上除灭，行事奸诈的必从世上拔除。'),
('CNV', '箴言', 20, 3, 1, '我儿，不可忘记我的训诲，你的心要谨守我的诫命；'),
('CNV', '箴言', 20, 3, 2, '因为它们必把长久的日子、生命的岁数和平安，加给你。'),
('CNV', '箴言', 20, 3, 3, '不可让慈爱诚实离开你，要系在你的颈项上，刻在你的心版上。'),
('CNV', '箴言', 20, 3, 4, '这样，你在神和世人眼前，必蒙恩宠，得着美名（“名”原文作“明慧”）。'),
('CNV', '箴言', 20, 3, 5, '你要一心仰赖主，不可倚靠自己的聪明；'),
('CNV', '箴言', 20, 3, 6, '在你一切所行的路上，都要承认他，他必使你的路径平坦正直。'),
('CNV', '箴言', 20, 3, 7, '不可自以为有智慧，要敬畏主，远离恶事。'),
('CNV', '箴言', 20, 3, 8, '这必使你的身体健康，使你的骨头滋润。'),
('CNV', '箴言', 20, 3, 9, '你要把你的财物，和一切初熟的农作物，敬奉主。'),
('CNV', '箴言', 20, 3, 10, '这样，你的仓库必充满有余，你的榨酒池也必盈溢新酒。'),
('CNV', '箴言', 20, 3, 11, '我儿，不可轻看主的管教，也不可厌恶他的责备；'),
('CNV', '箴言', 20, 3, 12, '因为主所爱的，他必责备，正如父亲责备他喜爱的儿子一样。'),
('CNV', '箴言', 20, 3, 13, '得着智慧，获致聪明的人，是有福的。'),
('CNV', '箴言', 20, 3, 14, '因为智慧的利润胜过银子的利润，智慧的收益胜过黄金的收益。'),
('CNV', '箴言', 20, 3, 15, '智慧比红宝石更宝贵；你一切所喜爱的，都不足与智慧比较。'),
('CNV', '箴言', 20, 3, 16, '智慧的右手有长寿，左手有财富和尊荣。'),
('CNV', '箴言', 20, 3, 17, '智慧的道路尽是欢悦，智慧的路径全是平安。'),
('CNV', '箴言', 20, 3, 18, '对紧握智慧的人来说，智慧是生命树，凡是紧抓智慧的，都是有福的。'),
('CNV', '箴言', 20, 3, 19, '主以智慧奠定大地，以聪明坚立高天。'),
('CNV', '箴言', 20, 3, 20, '因他的知识，深渊就裂开，天空也滴下甘露。'),
('CNV', '箴言', 20, 3, 21, '我儿，要谨守大智慧和明辨的态度，不可让它们离开你的眼目。'),
('CNV', '箴言', 20, 3, 22, '这样，它们就必作你的生命，作你颈上的华饰。'),
('CNV', '箴言', 20, 3, 23, '你就可以安然走路，你的脚必不致绊倒。'),
('CNV', '箴言', 20, 3, 24, '你躺下的时候，必不会惊恐；你躺卧的时候，必睡得香甜。'),
('CNV', '箴言', 20, 3, 25, '忽然而来的惊恐，你不要惧怕；恶人的毁灭临到，你也不要恐惧；'),
('CNV', '箴言', 20, 3, 26, '因为主是你的倚靠，他必护卫你的脚不陷入网罗。'),
('CNV', '箴言', 20, 3, 27, '如果你的手有行善的力量，就不可推辞，要向那些需要帮助的人行善。'),
('CNV', '箴言', 20, 3, 28, '你那里如果有现成的，就不可对邻舍说：“你先回去，明天再来吧，到时，我必给你！”'),
('CNV', '箴言', 20, 3, 29, '你的邻舍在你旁边安居，你不可设计害他。'),
('CNV', '箴言', 20, 3, 30, '如果人没有加害于你，你不可无故与他相争。'),
('CNV', '箴言', 20, 3, 31, '不要嫉妒强暴的人，也不可选择他所行的一切道路；'),
('CNV', '箴言', 20, 3, 32, '因为偏离正道的人，是主所厌恶的，正直人却是他所亲爱的。'),
('CNV', '箴言', 20, 3, 33, '主咒诅恶人的家，却赐福给义人的居所。'),
('CNV', '箴言', 20, 3, 34, '他讥笑那些好讥笑的人，却赐恩给谦卑的人。'),
('CNV', '箴言', 20, 3, 35, '智慧人必承受尊荣，愚昧人必蒙受羞辱（“必蒙受羞辱”原文作“高升成为羞辱”）。'),
('CNV', '箴言', 20, 4, 1, '孩子们，要听父亲的教训，留心学习哲理；'),
('CNV', '箴言', 20, 4, 2, '因为我授予你们的，是美好的学问，我的训诲，你们不可离弃。'),
('CNV', '箴言', 20, 4, 3, '我在我父亲面前还是小孩子，在我母亲面前是独一的娇儿的时候，'),
('CNV', '箴言', 20, 4, 4, '父亲教导我，对我说：“你的心要持守我的话，你要遵守我的诫命，就可以存活；'),
('CNV', '箴言', 20, 4, 5, '要求取智慧和哲理，不可忘记，也不可偏离我口中的话。'),
('CNV', '箴言', 20, 4, 6, '不可离弃智慧，智慧就必护卫你；喜爱智慧，智慧就必看顾你。'),
('CNV', '箴言', 20, 4, 7, '智慧的开端（“智慧的开端”或译：“智慧是首要的”）是求取智慧，要用你所得的一切换取哲理。'),
('CNV', '箴言', 20, 4, 8, '你要高举智慧，智慧就必使你高升；你要怀抱智慧，智慧就必使你得尊荣。'),
('CNV', '箴言', 20, 4, 9, '智慧必把华冠加在你头上，把荣冕赐给你。”'),
('CNV', '箴言', 20, 4, 10, '我儿，你要听，并要接受我所说的，这样，你就必延年益寿。'),
('CNV', '箴言', 20, 4, 11, '我指教你走智慧的道，引导你行正直的路。'),
('CNV', '箴言', 20, 4, 12, '你行走的时候，脚步必不会受阻碍；你奔跑的时候，也不会跌倒。'),
('CNV', '箴言', 20, 4, 13, '你要坚守教训，不可放松；要谨守教训，因为那是你的生命。'),
('CNV', '箴言', 20, 4, 14, '不可走进恶人的路径，不可踏上坏人的道路。'),
('CNV', '箴言', 20, 4, 15, '要躲避，不可从那里经过，要转身离去。'),
('CNV', '箴言', 20, 4, 16, '因为他们不行恶，就不能入睡；不使人跌倒，就要失眠。'),
('CNV', '箴言', 20, 4, 17, '他们吃的，是奸恶的饭；他们喝的，是强暴的酒。'),
('CNV', '箴言', 20, 4, 18, '义人的路径却像黎明的曙光，越来越明亮，直到日午。'),
('CNV', '箴言', 20, 4, 19, '恶人的道路幽暗，他们不知道自己因什么跌倒。'),
('CNV', '箴言', 20, 4, 20, '我儿，要留心听我的话，侧耳听我所说的。'),
('CNV', '箴言', 20, 4, 21, '不可让它们离开你的眼目，要谨记在你的心中。'),
('CNV', '箴言', 20, 4, 22, '因为得着它们就是得着生命，整个人也得着医治。'),
('CNV', '箴言', 20, 4, 23, '你要谨守你的心，胜过谨守一切，因为生命的泉源由此而出。'),
('CNV', '箴言', 20, 4, 24, '你要除掉欺诈的口，远离乖谬的嘴唇。'),
('CNV', '箴言', 20, 4, 25, '你双眼要向前正视，你的眼睛要向前直望。'),
('CNV', '箴言', 20, 4, 26, '你要谨慎你脚下的路径，你一切所行的就必稳妥。'),
('CNV', '箴言', 20, 4, 27, '不可偏左偏右，要使你的脚远离恶事。'),
('CNV', '箴言', 20, 5, 1, '我儿，要留心听我的智慧，侧耳听我的哲理，'),
('CNV', '箴言', 20, 5, 2, '好让你持守明辨的态度，你的嘴唇谨守知识。'),
('CNV', '箴言', 20, 5, 3, '因为淫妇的嘴唇滴下蜂蜜，她的口比油更滑；'),
('CNV', '箴言', 20, 5, 4, '至终却苦似苦菫，快如两刃的剑。'),
('CNV', '箴言', 20, 5, 5, '她的脚走下死地，她的脚步踏向阴间。'),
('CNV', '箴言', 20, 5, 6, '她不理会生命之路，她的路径变迁无定，自己也不知道。'),
('CNV', '箴言', 20, 5, 7, '孩子们，现在要听从我，不可离弃我口中的话。'),
('CNV', '箴言', 20, 5, 8, '你的道路要远离她，不可走近她的家门；'),
('CNV', '箴言', 20, 5, 9, '免得你的精力给了别人，你的年日交给了残忍的人；'),
('CNV', '箴言', 20, 5, 10, '免得外人饱享你的财物，你劳碌得来的归入别人的家。'),
('CNV', '箴言', 20, 5, 11, '在你生命终结，你的肉体和身躯衰残的时候，你就悲叹，'),
('CNV', '箴言', 20, 5, 12, '说：“我为什么恨恶管教，我的心为什么轻视责备，'),
('CNV', '箴言', 20, 5, 13, '不听从我老师的话，也不留心听那些教导我的人。'),
('CNV', '箴言', 20, 5, 14, '在众民的集会中，我几乎落在万劫不复之地。”'),
('CNV', '箴言', 20, 5, 15, '你要喝自己池中的水，饮自己井里的活水。'),
('CNV', '箴言', 20, 5, 16, '你的泉源怎么可以外溢？你的河水怎么可以流在街上？'),
('CNV', '箴言', 20, 5, 17, '它们要独归你一人所有，不要让外人与你共享。'),
('CNV', '箴言', 20, 5, 18, '要使你的泉源蒙福，要喜悦你年轻时所娶的妻子。'),
('CNV', '箴言', 20, 5, 19, '她像可爱的母鹿，人所喜悦的母山羊，愿她的乳房时常使你满足，愿她的爱情常常使你恋慕。'),
('CNV', '箴言', 20, 5, 20, '我儿，为什么恋慕淫妇？为什么拥抱妓女的胸怀呢？'),
('CNV', '箴言', 20, 5, 21, '因为人的道路都在主眼前，他也审察人的一切路径。'),
('CNV', '箴言', 20, 5, 22, '恶人必被自己的罪孽捉住，他必被自己罪恶的绳索缠住。'),
('CNV', '箴言', 20, 5, 23, '他必因不受管教而死亡，又因自己过分愚妄而走进歧途。'),
('CNV', '箴言', 20, 6, 1, '我儿，如果你作朋友的保证人，替外人击掌担保；'),
('CNV', '箴言', 20, 6, 2, '如果你给自己口里的话缠累，给你口里的话绑住；'),
('CNV', '箴言', 20, 6, 3, '我儿，既然你落在你朋友的手中，就要这样行，好解救你自己，你要自己降卑，去恳求你的朋友。'),
('CNV', '箴言', 20, 6, 4, '不要让你的眼睛睡觉，不要容你的眼睑打盹；'),
('CNV', '箴言', 20, 6, 5, '要解救自己，像羚羊脱离猎人的手，像飞鸟脱离捕鸟人的手。'),
('CNV', '箴言', 20, 6, 6, '懒惰人哪！你去看看蚂蚁，察看它们所行的，就可得着智慧。'),
('CNV', '箴言', 20, 6, 7, '蚂蚁没有元帅，没有官长，也没有统治者，'),
('CNV', '箴言', 20, 6, 8, '尚且在夏天预备食物，在收割的时候积聚粮食。'),
('CNV', '箴言', 20, 6, 9, '懒惰人哪，你要睡到几时呢？你什么时候才睡醒呢？'),
('CNV', '箴言', 20, 6, 10, '再睡片时，打盹片时，抱着手躺卧片时，'),
('CNV', '箴言', 20, 6, 11, '你的贫穷就必像强盗来到，你的缺乏就必像拿兵器的人来到。'),
('CNV', '箴言', 20, 6, 12, '无赖汉、坏人到处使用欺诈的口；'),
('CNV', '箴言', 20, 6, 13, '他以眼传神，用脚示意，用指头指点，'),
('CNV', '箴言', 20, 6, 14, '心存乖谬，图谋恶事，常常散布纷争。'),
('CNV', '箴言', 20, 6, 15, '因此，灾难必忽然临到，他必突然毁灭，无法挽救。'),
('CNV', '箴言', 20, 6, 16, '主恨恶的事有六样，连他心里厌恶的，共有七样，'),
('CNV', '箴言', 20, 6, 17, '就是高傲的眼、说谎的舌头、流无辜人血的手、'),
('CNV', '箴言', 20, 6, 18, '图谋恶事的心、快跑行恶的脚、'),
('CNV', '箴言', 20, 6, 19, '说谎的假证人，和在弟兄中散布纷争的人。'),
('CNV', '箴言', 20, 6, 20, '我儿，要谨守你父亲的诫命，不可离弃你母亲的训诲。'),
('CNV', '箴言', 20, 6, 21, '要把它们常常系在你的心上，绑在你的颈项上。'),
('CNV', '箴言', 20, 6, 22, '你行走的时候，它们必引导你；你睡觉的时候，它们必保护你；你醒来的时候，它们必和你交谈。'),
('CNV', '箴言', 20, 6, 23, '因为诫命是灯，训诲是光，出于管教的责备是生命之道，'),
('CNV', '箴言', 20, 6, 24, '能保护你远离邪恶的女人，远离妓女谄媚的舌头。'),
('CNV', '箴言', 20, 6, 25, '你心里不要贪恋她的美色，也不要给她的媚眼勾引。'),
('CNV', '箴言', 20, 6, 26, '因为妓女使人只剩一块饼，通奸的妇人（“通奸的妇人”直译是“人的妻子”）猎取人宝贵的生命。'),
('CNV', '箴言', 20, 6, 27, '如果人把火藏在怀里，他的衣服怎能不烧着呢？'),
('CNV', '箴言', 20, 6, 28, '如果人在火炭上行走，他的脚怎能不灼伤呢？'),
('CNV', '箴言', 20, 6, 29, '凡是和别人的妻子通奸的，也是这样；凡是亲近她的，都必不免受罚。'),
('CNV', '箴言', 20, 6, 30, '盗贼因饥饿偷窃充饥，人不会鄙视他。'),
('CNV', '箴言', 20, 6, 31, '但如果他被捉住，就要七倍偿还，要把他家里所有的财物都交出来。'),
('CNV', '箴言', 20, 6, 32, '和妇人通奸的，实在无知；行这事的，是自我毁灭。'),
('CNV', '箴言', 20, 6, 33, '他必遭受击打，被凌辱，他的耻辱永不能涂抹。'),
('CNV', '箴言', 20, 6, 34, '因为嫉妒激起了丈夫的烈怒，使他在报仇的时候，必不留情。'),
('CNV', '箴言', 20, 6, 35, '任何赔偿，他都不接受，纵使你馈送许多礼物，他也不肯罢休。'),
('CNV', '箴言', 20, 7, 1, '我儿，要遵守我的话，把我的诫命珍藏在心里；'),
('CNV', '箴言', 20, 7, 2, '遵守我的诫命，你就可以存活；遵守我的训诲，好像护卫你眼中的瞳人。'),
('CNV', '箴言', 20, 7, 3, '要把它们系在你的指头上，刻在你的心版上。'),
('CNV', '箴言', 20, 7, 4, '要对智慧说：“你是我的姊妹”，要称呼聪明为亲人；'),
('CNV', '箴言', 20, 7, 5, '这样行就可以保护你脱离淫乱的妇人，脱离说谄媚话的妓女。'),
('CNV', '箴言', 20, 7, 6, '我在我家的窗户内，透过窗棂往外观看，'),
('CNV', '箴言', 20, 7, 7, '看见在愚蒙人中间，在少年人（“少年人”原文作“众子”）里面，我发觉有一个无知的少年人，'),
('CNV', '箴言', 20, 7, 8, '在街上经过，走近淫妇的住处，向着她的家走去，'),
('CNV', '箴言', 20, 7, 9, '那时是黄昏、傍晚，是在夜里，天黑的时候。'),
('CNV', '箴言', 20, 7, 10, '看哪！有一个妇人来迎接他，是妓女的打扮，心存诡诈。'),
('CNV', '箴言', 20, 7, 11, '这妇人喧哗不停，不受约束；她在家里停不住脚。'),
('CNV', '箴言', 20, 7, 12, '她有时在街上，有时在广场上，或在任何角落旁边藏伏。'),
('CNV', '箴言', 20, 7, 13, '她紧拉着那少年人，和他亲嘴，厚颜无耻地对他说：'),
('CNV', '箴言', 20, 7, 14, '“我曾许愿要献平安祭，今天我刚还了我所许的愿。'),
('CNV', '箴言', 20, 7, 15, '因此，我出来迎接你，切切寻找你，终于找到你。'),
('CNV', '箴言', 20, 7, 16, '我已用毯子，埃及线织成的花纹布，铺了我的床；'),
('CNV', '箴言', 20, 7, 17, '又用没药、沉香和桂皮，薰了我的榻。'),
('CNV', '箴言', 20, 7, 18, '来吧！我们来饱享爱情，直到天亮，我们来在爱中尽情享乐。'),
('CNV', '箴言', 20, 7, 19, '因为我丈夫不在家，远行去了。'),
('CNV', '箴言', 20, 7, 20, '他手里带着钱袋，要到月圆的时候才回家。”'),
('CNV', '箴言', 20, 7, 21, '淫妇用许多花言巧语引诱他，用谄媚的嘴唇勾引他。'),
('CNV', '箴言', 20, 7, 22, '少年人就立刻跟随她，好像牛走向屠房，又像愚妄人带着锁链去受刑罚，'),
('CNV', '箴言', 20, 7, 23, '直到箭矢射透他的肝；他仿佛飞鸟投入网罗，并不知道会丧失性命。'),
('CNV', '箴言', 20, 7, 24, '孩子们，现在你们要听从我，留心听我口中的话。'),
('CNV', '箴言', 20, 7, 25, '你的心不可偏向淫妇的道路，也不要迷恋她的路径。'),
('CNV', '箴言', 20, 7, 26, '因为她使许多人倒毙，被她杀害的实在无数。'),
('CNV', '箴言', 20, 7, 27, '她的家是通往阴间的路，是下到死亡的宫房。'),
('CNV', '箴言', 20, 8, 1, '智慧不是在呼唤，聪明不是在发声吗？'),
('CNV', '箴言', 20, 8, 2, '它在路旁高处的最高点，在十字路口站着；'),
('CNV', '箴言', 20, 8, 3, '在城门旁，在城门口，在进城门的空地上大声呼喊：'),
('CNV', '箴言', 20, 8, 4, '“众人哪！我向你们呼唤，对世人发声。'),
('CNV', '箴言', 20, 8, 5, '愚蒙人哪！你们要学习精明；愚昧人哪！你们心里要明白事理。'),
('CNV', '箴言', 20, 8, 6, '你们听着，因为我要讲论极美的事，我要开口说正直的事；'),
('CNV', '箴言', 20, 8, 7, '我的口要论述真理，我的嘴唇厌恶邪恶。'),
('CNV', '箴言', 20, 8, 8, '我口里的一切话都是公义的，毫无弯曲欺诈。'),
('CNV', '箴言', 20, 8, 9, '我的话对明理的人，都是对的；对得着知识的人，都是正直的。'),
('CNV', '箴言', 20, 8, 10, '你们要接受我的教训，不要银子；宁愿得着知识，胜过精金；'),
('CNV', '箴言', 20, 8, 11, '因为智慧比红宝石更好，你一切所喜爱的都不能和智慧比较。'),
('CNV', '箴言', 20, 8, 12, '我─智慧─和精明同住，我又获得知识和谋略。'),
('CNV', '箴言', 20, 8, 13, '敬畏主就是恨恶邪恶；骄傲、狂妄、邪恶的行为、乖谬的口，我都恨恶。'),
('CNV', '箴言', 20, 8, 14, '我有才智和大智慧，我有聪明，我有能力。'),
('CNV', '箴言', 20, 8, 15, '君王藉我掌权，统治者藉我制定法纪。'),
('CNV', '箴言', 20, 8, 16, '领袖、贵族和所有公义的审判官，都藉我治国。'),
('CNV', '箴言', 20, 8, 17, '爱我的，我必爱他；殷切寻找我的，必定寻见。'),
('CNV', '箴言', 20, 8, 18, '财富和尊荣是我的，恒久的财产和公义也是我的。'),
('CNV', '箴言', 20, 8, 19, '我的果实胜过黄金，胜过精金，我的出产胜过纯银。'),
('CNV', '箴言', 20, 8, 20, '我走在公义的道上，行在公正的路上，'),
('CNV', '箴言', 20, 8, 21, '使爱我的承受财产，使他们的府库满溢。'),
('CNV', '箴言', 20, 8, 22, '在主创造的开始，在太初创造一切以先，就有了我。'),
('CNV', '箴言', 20, 8, 23, '在亘古、在太初，在未有大地之前，我已经被立；'),
('CNV', '箴言', 20, 8, 24, '没有深渊，没有大水的泉源以先，我已经出生。'),
('CNV', '箴言', 20, 8, 25, '大山未曾奠定，小山未有以先，我已经出生。'),
('CNV', '箴言', 20, 8, 26, '那时，主还没有造大地和田野，也没有造地上的泥土。'),
('CNV', '箴言', 20, 8, 27, '他立定诸天的时候，我在那里；他在渊面上界划地平线的时候，我在那里；'),
('CNV', '箴言', 20, 8, 28, '他上使穹苍坚固，下使深渊的水泉稳定；'),
('CNV', '箴言', 20, 8, 29, '他为海洋定出界限，海水不能越过他的命令，他又划定大地的根基；'),
('CNV', '箴言', 20, 8, 30, '那时，我在他身边作工匠，每天都充满喜乐，时常在他面前欢笑，'),
('CNV', '箴言', 20, 8, 31, '在他的大地上欢笑，和世人一同喜乐。'),
('CNV', '箴言', 20, 8, 32, '孩子们，现在你们要听从我；持守我道路的，是有福的。'),
('CNV', '箴言', 20, 8, 33, '你们要听从教训，要作智慧人，不可离弃教训。'),
('CNV', '箴言', 20, 8, 34, '听从我，天天在我门口警醒仰望，在我门框旁边守候的人，是有福的。'),
('CNV', '箴言', 20, 8, 35, '因为找到我的，就找到生命，他也必得着主的恩惠。'),
('CNV', '箴言', 20, 8, 36, '得罪我的，是伤害自己；凡是恨恶我的，就是喜爱死亡。”'),
('CNV', '箴言', 20, 9, 1, '智慧建造自己的房屋，凿成七根柱子。'),
('CNV', '箴言', 20, 9, 2, '它宰杀牲口，调配美酒，摆设筵席。'),
('CNV', '箴言', 20, 9, 3, '它差派几个使女出去，自己又在城里的高处呼喊：'),
('CNV', '箴言', 20, 9, 4, '“谁是愚蒙人，可以到这里来！”又对无知的人说：'),
('CNV', '箴言', 20, 9, 5, '“你们都来，吃我的饼，喝我调配的酒。'),
('CNV', '箴言', 20, 9, 6, '愚蒙人哪！你们要丢弃愚蒙，就可以存活，并且要走在智慧的道路上。”'),
('CNV', '箴言', 20, 9, 7, '纠正好讥笑人的，必自招耻辱；责备恶人的，必遭受羞辱。'),
('CNV', '箴言', 20, 9, 8, '你不要责备好讥笑人的，免得他恨你；要责备智慧人，他必爱你。'),
('CNV', '箴言', 20, 9, 9, '教导智慧人，他就越有智慧；指教义人，他就增加学问。'),
('CNV', '箴言', 20, 9, 10, '敬畏主是智慧的开端，认识至圣者就是聪明。'),
('CNV', '箴言', 20, 9, 11, '因为藉着我，你的日子就必增多，你一生的年岁也必加添。'),
('CNV', '箴言', 20, 9, 12, '如果你有智慧，你的智慧必使你得益；如果你讥笑人，你就必独自担当一切后果。'),
('CNV', '箴言', 20, 9, 13, '愚昧的妇人喧哗不停，她是愚蒙，一无所知。'),
('CNV', '箴言', 20, 9, 14, '她坐在自己的家门口，坐在城中高处的座位上，'),
('CNV', '箴言', 20, 9, 15, '向过路的人呼叫，就是向往前直行的人呼叫：'),
('CNV', '箴言', 20, 9, 16, '“谁是愚蒙人，可以到这里来！”又对无知的人说：'),
('CNV', '箴言', 20, 9, 17, '“偷来的水是甜的，在暗中吃的饼是美味的。”'),
('CNV', '箴言', 20, 9, 18, '人却不知道她那里有阴魂，她的客人是在阴间的深处。'),
('CNV', '箴言', 20, 10, 1, '所罗门的箴言：智慧的儿子使父亲欢乐，愚昧的儿子使母亲忧愁。'),
('CNV', '箴言', 20, 10, 2, '不义之财毫无益处，唯有公义能救人脱离死亡。'),
('CNV', '箴言', 20, 10, 3, '主不容许义人忍受饥饿，恶人的欲念却无法得着。'),
('CNV', '箴言', 20, 10, 4, '游手好闲的，招致贫穷，勤力工作的，得到富足。'),
('CNV', '箴言', 20, 10, 5, '夏天收聚的，是明慧的人，收割时沉睡的，是贻羞的人。'),
('CNV', '箴言', 20, 10, 6, '福祉临到义人头上，强暴遮盖恶人的口。'),
('CNV', '箴言', 20, 10, 7, '义人的名必蒙称赞，恶人的名字却必腐朽。'),
('CNV', '箴言', 20, 10, 8, '心存智慧的，必接受诫命；嘴唇愚妄的，必自招灭亡。'),
('CNV', '箴言', 20, 10, 9, '行为完全的，步步安稳；行事弯曲的，终必败露。'),
('CNV', '箴言', 20, 10, 10, '以眼传神的，使人受害；嘴唇愚妄的，必自招灭亡。'),
('CNV', '箴言', 20, 10, 11, '义人的口是生命的泉源，强暴遮盖恶人的口。'),
('CNV', '箴言', 20, 10, 12, '恨能挑起纷争，爱能遮掩一切过失。'),
('CNV', '箴言', 20, 10, 13, '聪明人嘴里有智慧，无知人背上受刑杖。'),
('CNV', '箴言', 20, 10, 14, '智慧人积存知识，愚妄人的口招致毁灭。'),
('CNV', '箴言', 20, 10, 15, '富翁的财物是他的坚城，穷人的贫乏是他灭亡的因由。'),
('CNV', '箴言', 20, 10, 16, '义人的工价就是生命，恶人所得的却是刑罚。'),
('CNV', '箴言', 20, 10, 17, '遵守教训的，走在生命的路上；离弃责备的，却是走上错路。'),
('CNV', '箴言', 20, 10, 18, '隐藏怨恨的，嘴里必出谎言；散播谣言的，是愚昧人。'),
('CNV', '箴言', 20, 10, 19, '多言多语难免有过失；约束自己嘴唇的，是明慧人。'),
('CNV', '箴言', 20, 10, 20, '义人的舌头好像纯银，恶人的心思毫无价值。'),
('CNV', '箴言', 20, 10, 21, '义人的嘴唇培育多人，愚妄人因无知死亡。'),
('CNV', '箴言', 20, 10, 22, '主所赐的福使人富足，并不加上愁烦。'),
('CNV', '箴言', 20, 10, 23, '愚昧人以行恶为嬉戏，聪明人却以智慧为乐。'),
('CNV', '箴言', 20, 10, 24, '恶人所怕的，必临到他身上；义人所愿的，必蒙应允。'),
('CNV', '箴言', 20, 10, 25, '暴风一过，恶人就归于无有，义人却有永远的根基。'),
('CNV', '箴言', 20, 10, 26, '醋怎样使牙酸倒，烟怎样薰目，懒惰人也怎样使差他的人难受。'),
('CNV', '箴言', 20, 10, 27, '敬畏主可以延年益寿，恶人的年岁必被减少。'),
('CNV', '箴言', 20, 10, 28, '义人的盼望使他们喜乐，恶人的希望终必幻灭。'),
('CNV', '箴言', 20, 10, 29, '主的道是完全人的保障，却是作孽的人灭亡的因由。'),
('CNV', '箴言', 20, 10, 30, '义人永不动摇，恶人却不得安居在地上。'),
('CNV', '箴言', 20, 10, 31, '义人的口结出智慧的果子，乖谬的舌头必被割除。'),
('CNV', '箴言', 20, 10, 32, '义人的嘴使人喜悦，恶人的口说乖谬的话。'),
('CNV', '箴言', 20, 11, 1, '诡诈的天平是主所厌恶的，准确的法码是他所喜悦的。'),
('CNV', '箴言', 20, 11, 2, '傲慢来，羞辱也来；谦卑的人却有智慧。'),
('CNV', '箴言', 20, 11, 3, '正直人的纯正必引导他们自己，奸诈人的奸恶却毁灭自己。'),
('CNV', '箴言', 20, 11, 4, '在神发怒的日子，财物毫无益处；唯有公义能救人脱离死亡。'),
('CNV', '箴言', 20, 11, 5, '完全人的公义，必使自己的路平坦正直，但恶人必因自己的邪恶跌倒。'),
('CNV', '箴言', 20, 11, 6, '正直人的公义必拯救自己，但奸诈人必陷溺于自己的恶欲中。'),
('CNV', '箴言', 20, 11, 7, '恶人一死，他的希望就幻灭；有能力的人的盼望也消灭了。'),
('CNV', '箴言', 20, 11, 8, '义人得蒙拯救脱离患难，恶人却来代替他。'),
('CNV', '箴言', 20, 11, 9, '不敬虔的人用口败坏邻舍，义人却因知识免受其害。'),
('CNV', '箴言', 20, 11, 10, '义人亨通，全城欢乐；恶人灭亡，大家欢呼。'),
('CNV', '箴言', 20, 11, 11, '因正直人的祝福，城的地位就提高；因恶人的口，城就倾覆。'),
('CNV', '箴言', 20, 11, 12, '藐视邻舍的，真是无知；聪明人却缄默不言。'),
('CNV', '箴言', 20, 11, 13, '到处搬弄是非的，泄露秘密，心里诚实的，遮隐事情。'),
('CNV', '箴言', 20, 11, 14, '没有智谋，国家败落；谋士众多，就能得胜。'),
('CNV', '箴言', 20, 11, 15, '为外人作保证人的，必受亏损；厌恶替人击掌担保的，却得着安稳。'),
('CNV', '箴言', 20, 11, 16, '贤德的妇女得着尊荣，强暴的男子只得着财富。'),
('CNV', '箴言', 20, 11, 17, '仁慈的人自己获益，残忍的人自己受害。'),
('CNV', '箴言', 20, 11, 18, '恶人赚得的工价是虚假的，播种公义的得着实在的赏赐。'),
('CNV', '箴言', 20, 11, 19, '恒心行义的必得生命；追随邪恶的必致死亡。'),
('CNV', '箴言', 20, 11, 20, '欺诈的心是主厌恶的；行为完全是他所喜悦的。'),
('CNV', '箴言', 20, 11, 21, '恶人必不免受罚，但义人的后裔必蒙解救。'),
('CNV', '箴言', 20, 11, 22, '妇女美丽而无见识，就像金环带在猪鼻上一样。'),
('CNV', '箴言', 20, 11, 23, '义人的愿望，尽是美好，恶人的希望，必招致忿怒。'),
('CNV', '箴言', 20, 11, 24, '有人慷慨好施，财富却更增添；有人吝啬过度，反招致贫穷。'),
('CNV', '箴言', 20, 11, 25, '乐善好施的人，必得丰裕；施惠于人的，自己也必蒙施惠。'),
('CNV', '箴言', 20, 11, 26, '屯积五谷的，必被人民咒诅；出售粮食的，福祉必临到他的头上。'),
('CNV', '箴言', 20, 11, 27, '殷切求善的，必得到爱顾；追求邪恶的，邪恶必临到他。'),
('CNV', '箴言', 20, 11, 28, '倚赖自己财富的，必然衰落；义人却必繁茂，好像绿叶。'),
('CNV', '箴言', 20, 11, 29, '祸害自己家庭的，必承受清风；愚妄人必作心思智慧的人的仆人。'),
('CNV', '箴言', 20, 11, 30, '义人所结的果子就是生命树；智慧人必能得人。'),
('CNV', '箴言', 20, 11, 31, '义人在世上尚且受报应，何况恶人和罪人呢？'),
('CNV', '箴言', 20, 12, 1, '喜爱教训的，就是喜爱知识；厌恶责备的，却是愚顽人。'),
('CNV', '箴言', 20, 12, 2, '良善的人必得到主的恩宠；图谋奸计的人，主必把他定罪。'),
('CNV', '箴言', 20, 12, 3, '人不能恃凭恶行坚立；但义人的根必不动摇。'),
('CNV', '箴言', 20, 12, 4, '有才德的妻子是丈夫的冠冕，贻羞的妇人，如同丈夫骨中的朽烂。'),
('CNV', '箴言', 20, 12, 5, '义人的筹算是公平，恶人的计谋却是诡诈。'),
('CNV', '箴言', 20, 12, 6, '恶人的言语埋伏着，等待要流人的血，正直人的口能拯救人。'),
('CNV', '箴言', 20, 12, 7, '恶人倾覆，就不再存在；义人的家却必站立得住。'),
('CNV', '箴言', 20, 12, 8, '人因着自己的明慧必得称赞，但心中乖谬的必被藐视。'),
('CNV', '箴言', 20, 12, 9, '被人轻看却有仆人的人，胜过自尊自大却缺少食物的人。'),
('CNV', '箴言', 20, 12, 10, '义人连自己牲畜的性命也顾惜；但恶人的怜悯也是残忍。'),
('CNV', '箴言', 20, 12, 11, '耕种自己田地的，也有充足的粮食；追求虚幻的，实在无知。'),
('CNV', '箴言', 20, 12, 12, '恶人贪慕坏人的网罗；义人的根得以结果。'),
('CNV', '箴言', 20, 12, 13, '坏人嘴里的过失，是自己的网罗；但义人必脱离患难。'),
('CNV', '箴言', 20, 12, 14, '人因口所结的果子必饱尝美物；人手所作的必归到他身上。'),
('CNV', '箴言', 20, 12, 15, '愚妄人所行的，在自己眼中看为正直，只有智慧人肯听劝告。'),
('CNV', '箴言', 20, 12, 16, '愚妄人的恼怒立时显露，精明的人却能忍受羞辱。'),
('CNV', '箴言', 20, 12, 17, '吐露真情的，彰显正义，作假见证的却是诡诈。'),
('CNV', '箴言', 20, 12, 18, '有人说话不慎，好像利刀刺人，智慧人的舌头却能医治人。'),
('CNV', '箴言', 20, 12, 19, '说实话的嘴唇，永远坚立；撒谎的舌头，眨眼间消失。'),
('CNV', '箴言', 20, 12, 20, '图谋恶事的，心存诡诈；使人和睦的，心中喜乐。'),
('CNV', '箴言', 20, 12, 21, '义人不会遭遇灾祸，恶人却饱经祸患。'),
('CNV', '箴言', 20, 12, 22, '撒谎的嘴唇是主憎恶的；行事诚实是他所喜悦的。'),
('CNV', '箴言', 20, 12, 23, '精明的人隐藏自己的知识，愚昧人的心却显出愚妄。'),
('CNV', '箴言', 20, 12, 24, '殷勤人的手必掌权，懒惰人的手必作苦工。'),
('CNV', '箴言', 20, 12, 25, '心中忧虑，使人消沉；一句良言使他欢喜。'),
('CNV', '箴言', 20, 12, 26, '义人作自己邻舍的引导；恶人的道路，却使别人走迷。'),
('CNV', '箴言', 20, 12, 27, '懒惰的人不去烧烤他的猎物，殷勤的人却得宝贵的财物（“殷勤的人却得宝贵的财物”或译：“人宝贵的财物是殷勤”）。'),
('CNV', '箴言', 20, 12, 28, '在公义的路上有生命，这路径之上没有死亡（“这路径之上没有死亡”有古译本作“邪恶的路，引到死亡”）。'),
('CNV', '箴言', 20, 13, 1, '智慧的儿子听从父亲的教训，好讥笑人的不听责备。'),
('CNV', '箴言', 20, 13, 2, '人因口所结的果子，必得尝美物，奸诈人的欲望却是强暴。'),
('CNV', '箴言', 20, 13, 3, '谨慎口舌的，可保性命；口没遮拦的，自取灭亡。'),
('CNV', '箴言', 20, 13, 4, '懒惰人渴求，却一无所得；殷勤人必得丰裕。'),
('CNV', '箴言', 20, 13, 5, '义人恨恶虚假，恶人行事，遗臭贻羞。'),
('CNV', '箴言', 20, 13, 6, '正义护卫行为完全的人；邪恶却使犯罪的人倾覆。'),
('CNV', '箴言', 20, 13, 7, '有人自充富足，却一无所有；有人假装贫穷，财物却极多。'),
('CNV', '箴言', 20, 13, 8, '人的财富是他性命的赎价，穷人却听不见威吓的话。'),
('CNV', '箴言', 20, 13, 9, '义人的光必明亮，恶人的灯必熄灭。'),
('CNV', '箴言', 20, 13, 10, '傲慢只能引起争端；接受劝告的却有智慧。'),
('CNV', '箴言', 20, 13, 11, '不劳而获的财物，必快减少；慢慢积蓄的，必然增多。'),
('CNV', '箴言', 20, 13, 12, '所盼望的迟延未得，令人心忧；所愿的来到，好比生命树。'),
('CNV', '箴言', 20, 13, 13, '藐视训言的，必自取灭亡；敬畏诫命的，必得善报。'),
('CNV', '箴言', 20, 13, 14, '智慧人的训诲是生命的泉源，能使人避开死亡的网罗。'),
('CNV', '箴言', 20, 13, 15, '聪颖的明慧使人蒙恩，奸诈人的道路崎岖难行。'),
('CNV', '箴言', 20, 13, 16, '精明的人都按知识行事，愚昧人却显露自己的愚妄。'),
('CNV', '箴言', 20, 13, 17, '奸恶的使者，必陷在祸患里（“必陷在祸患里”或译：“必使人陷在祸患里”）；忠心的使臣，使人复原。'),
('CNV', '箴言', 20, 13, 18, '轻忽管教的，必致穷乏受辱；看重责备的，必得尊荣。'),
('CNV', '箴言', 20, 13, 19, '所愿的成功，使人心里甘甜；远离恶事，却为愚昧人憎恶。'),
('CNV', '箴言', 20, 13, 20, '与智慧人同行的，必得智慧；与愚昧人为友的，必受亏损。'),
('CNV', '箴言', 20, 13, 21, '祸患追赶罪人，义人必得善报。'),
('CNV', '箴言', 20, 13, 22, '善人给子孙留下产业，罪人的财富，却是为义人积藏。'),
('CNV', '箴言', 20, 13, 23, '穷人的耕地可产大量粮食，却因不义都被摧毁了。'),
('CNV', '箴言', 20, 13, 24, '不用杖责打儿子的，是恨恶他；爱儿子的，必对他勤加管教。'),
('CNV', '箴言', 20, 13, 25, '义人必吃得饱足，恶人却空着肚子。'),
('CNV', '箴言', 20, 14, 1, '智慧妇人建立家室，愚妄妇人亲手拆毁。'),
('CNV', '箴言', 20, 14, 2, '行事正直的，敬畏主；行为乖僻的，却藐视他。'),
('CNV', '箴言', 20, 14, 3, '愚妄人的口中长出骄傲的枝子；智慧人的嘴唇，能保障自己。'),
('CNV', '箴言', 20, 14, 4, '没有耕牛，槽头干净；出产丰盛，却是凭着牛的力量。'),
('CNV', '箴言', 20, 14, 5, '诚实的证人不说谎话；虚伪的证人吐出谎言。'),
('CNV', '箴言', 20, 14, 6, '好讥笑人的寻找智慧，却寻不着；聪明人寻找知识，却轻易得着。'),
('CNV', '箴言', 20, 14, 7, '你当离开愚昧人，因为你不会从他的嘴里晓得知识。'),
('CNV', '箴言', 20, 14, 8, '精明人的智慧能分辨自己的道路；愚昧人的愚妄却欺骗自己。'),
('CNV', '箴言', 20, 14, 9, '愚妄人讥笑赎愆祭，正直人中间却有恩宠。'),
('CNV', '箴言', 20, 14, 10, '人的苦楚，只有自己心里知道；心中的喜乐，外人也不能分享。'),
('CNV', '箴言', 20, 14, 11, '恶人的家必毁坏，正直人的帐棚却必兴盛。'),
('CNV', '箴言', 20, 14, 12, '有一条路，人以为是正路，走到尽头却是死亡之路。'),
('CNV', '箴言', 20, 14, 13, '人在喜笑中，心里也会有痛苦；欢乐的结局，会是愁苦。'),
('CNV', '箴言', 20, 14, 14, '心中背道的，必饱尝自己行为的恶果；善人也因自己所行的，得到善报。'),
('CNV', '箴言', 20, 14, 15, '愚蒙人凡话都信；精明的人却步步谨慎。'),
('CNV', '箴言', 20, 14, 16, '智慧人敬畏主（“智慧人敬畏主”或译：“智慧人恐惧战兢”），远离恶事；愚昧人却骄傲自恃。'),
('CNV', '箴言', 20, 14, 17, '轻易动怒的，行事愚妄；心怀诡计的人，被人恨恶。'),
('CNV', '箴言', 20, 14, 18, '愚蒙人得愚妄为产业；精明的人以知识为冠冕。'),
('CNV', '箴言', 20, 14, 19, '坏人必俯伏在好人面前，恶人必俯伏在义人门口。'),
('CNV', '箴言', 20, 14, 20, '穷人连邻舍也厌恶他；财主却有很多人爱他。'),
('CNV', '箴言', 20, 14, 21, '藐视邻舍的，是为有罪；恩待贫穷人的，是为有福。'),
('CNV', '箴言', 20, 14, 22, '图谋恶事的，不是走错了吗？谋求善事的，必得慈爱和诚实。'),
('CNV', '箴言', 20, 14, 23, '一切劳苦都有益处，嘴上空谈引致贫穷。'),
('CNV', '箴言', 20, 14, 24, '智慧人的冠冕是他们的财富；愚昧人的愚妄，始终是愚妄。'),
('CNV', '箴言', 20, 14, 25, '作真见证的，救人性命；吐出谎言的，以诡诈害人。'),
('CNV', '箴言', 20, 14, 26, '敬畏主的，大有倚靠；他的子孙也有避难所。'),
('CNV', '箴言', 20, 14, 27, '敬畏主是生命的泉源，能使人避开死亡的网罗。'),
('CNV', '箴言', 20, 14, 28, '君王的荣耀在于人民众多，帝王的没落由于国民寡少。'),
('CNV', '箴言', 20, 14, 29, '不轻易动怒的，十分聪明；轻易动怒的，大显愚妄。'),
('CNV', '箴言', 20, 14, 30, '心里平静，可使身体健康；但嫉妒能使骨头朽烂。'),
('CNV', '箴言', 20, 14, 31, '欺压贫寒的，就是辱骂造他的主；恩待穷苦人的，就是尊敬造他的主。'),
('CNV', '箴言', 20, 14, 32, '恶人必因自己所行的恶事被推倒，义人死的时候仍有所倚靠。'),
('CNV', '箴言', 20, 14, 33, '智慧居于聪明人的心中；愚昧人心里所存的，人所周知（“愚昧人心里所存的，人所周知”或译：“智慧在愚昧人心里也显明自己”）。'),
('CNV', '箴言', 20, 14, 34, '正义使国家兴盛，罪恶是人民的羞辱。'),
('CNV', '箴言', 20, 14, 35, '明慧的臣仆，为王喜悦；贻羞的仆人，遭王震怒。'),
('CNV', '箴言', 20, 15, 1, '柔和的回答使烈怒消退，暴戾的话激动怒气。'),
('CNV', '箴言', 20, 15, 2, '智慧人的舌头阐扬知识；愚昧人的口发出愚妄。'),
('CNV', '箴言', 20, 15, 3, '主的眼目无所不在；坏人好人他都鉴察。'),
('CNV', '箴言', 20, 15, 4, '说安慰话的舌头是生命树；奸恶的舌头使人心碎。'),
('CNV', '箴言', 20, 15, 5, '愚妄人藐视父亲的管教；看重责备的是精明的人。'),
('CNV', '箴言', 20, 15, 6, '义人家中财宝丰富；恶人的收入却带来扰害。'),
('CNV', '箴言', 20, 15, 7, '智慧人的嘴唇散播知识；愚昧人的心并不是这样。'),
('CNV', '箴言', 20, 15, 8, '恶人的祭物是主厌恶的；正直人的祷告却是他所喜悦的。'),
('CNV', '箴言', 20, 15, 9, '恶人的道路是主厌恶的；追求公义的人却是他所爱的。'),
('CNV', '箴言', 20, 15, 10, '离弃正路的必受严厉的管教；恨恶责备的必致死亡。'),
('CNV', '箴言', 20, 15, 11, '阴间和灭亡展露在主面前，何况世人的心呢？'),
('CNV', '箴言', 20, 15, 12, '好讥笑人的不喜爱责备他的人，也不到智慧人那里去。'),
('CNV', '箴言', 20, 15, 13, '喜乐的心使人脸上容光焕发；心中愁苦使人精神颓丧。'),
('CNV', '箴言', 20, 15, 14, '聪明人的心寻求知识，愚昧人的口只吃愚妄。'),
('CNV', '箴言', 20, 15, 15, '困苦人的日子尽是艰难；心中畅快的好像常享丰筵。'),
('CNV', '箴言', 20, 15, 16, '财物虽少而敬畏主，胜过财物丰富却烦恼不安。'),
('CNV', '箴言', 20, 15, 17, '吃素菜而彼此相爱，胜过吃肥牛却彼此憎恨。'),
('CNV', '箴言', 20, 15, 18, '脾气暴烈的人常引起纷争；不轻易动怒的可平息争执。'),
('CNV', '箴言', 20, 15, 19, '懒惰人的道路好像荆棘篱笆；正直人的路径是平坦的大道。'),
('CNV', '箴言', 20, 15, 20, '智慧的儿子使父亲快乐；愚昧人却藐视自己的母亲。'),
('CNV', '箴言', 20, 15, 21, '无知的人以愚妄为乐；聪明人却行事正直。'),
('CNV', '箴言', 20, 15, 22, '不经商议，计划必定失败；谋士众多，计划就可成功。'),
('CNV', '箴言', 20, 15, 23, '应对得当，自己也觉喜乐；合时的话，多么美好！'),
('CNV', '箴言', 20, 15, 24, '生命之路领明慧人向上，因此他可以离开在下面的阴间。'),
('CNV', '箴言', 20, 15, 25, '主必拆毁骄傲人的家，却要立定寡妇的地界。'),
('CNV', '箴言', 20, 15, 26, '邪恶的思想是主厌恶的；恩慈的话却是纯净的。'),
('CNV', '箴言', 20, 15, 27, '贪爱不义之财的祸害自己的家；恨恶贿赂的必可以存活。'),
('CNV', '箴言', 20, 15, 28, '义人的心思想怎样回答；恶人的口发出恶言。'),
('CNV', '箴言', 20, 15, 29, '主远离恶人，却垂听义人的祷告。'),
('CNV', '箴言', 20, 15, 30, '眼中的光采使人心快乐；好消息使骨头滋润。'),
('CNV', '箴言', 20, 15, 31, '听从有关生命之责备的，必住在智慧人中间。'),
('CNV', '箴言', 20, 15, 32, '轻忽管教的是藐视自己；听从责备的却得着智慧（“智慧”原文作“心”）。'),
('CNV', '箴言', 20, 15, 33, '敬畏主是智慧的教训；尊荣以先，必有谦卑。'),
('CNV', '箴言', 20, 16, 1, '心里的筹划在于人，舌头的应对却出于主。'),
('CNV', '箴言', 20, 16, 2, '人看自己一切所行的，都是清洁的；主却衡量人心。'),
('CNV', '箴言', 20, 16, 3, '当把你所作的交托主，你的计划就必成功。'),
('CNV', '箴言', 20, 16, 4, '主所造的各有目的，连恶人也是为祸患的日子而造的。'),
('CNV', '箴言', 20, 16, 5, '心里骄傲的人都是主厌恶的；他们必不免受罚。'),
('CNV', '箴言', 20, 16, 6, '因着怜悯和信实，罪孽得赎；因为敬畏主，人可以避开罪恶。'),
('CNV', '箴言', 20, 16, 7, '人所行的，若是蒙主喜悦，主也使他的仇敌与他和好。'),
('CNV', '箴言', 20, 16, 8, '收入少而有公义，胜过收入多却毫无正义。'),
('CNV', '箴言', 20, 16, 9, '人心计划自己的道路，他的脚步却由主指引。'),
('CNV', '箴言', 20, 16, 10, '王的嘴里有神的判语，审判的时候，他的口必不差错。'),
('CNV', '箴言', 20, 16, 11, '公正的秤和天平都属主，囊中的一切法码都是他所造的。'),
('CNV', '箴言', 20, 16, 12, '作恶是君王所厌恶的，因为王位是靠赖公义建立的。'),
('CNV', '箴言', 20, 16, 13, '公义的嘴唇是君王所喜悦的；他喜爱说话正直的人。'),
('CNV', '箴言', 20, 16, 14, '君王的烈怒好像死亡的使者，唯有智慧人能平息君王的怒气。'),
('CNV', '箴言', 20, 16, 15, '君王脸上欣悦的光采，使人得生命；君王的恩宠好像春日雨云。'),
('CNV', '箴言', 20, 16, 16, '得智慧胜过得金子，选择哲理，胜过选择银子。'),
('CNV', '箴言', 20, 16, 17, '正直人的大道远离罪恶；谨守自己道路的，保全自己的性命。'),
('CNV', '箴言', 20, 16, 18, '在灭亡以先，必有骄傲；在跌倒以前，心中高傲。'),
('CNV', '箴言', 20, 16, 19, '存谦卑的心与穷乏人在一起，胜过与骄傲人同分战利品。'),
('CNV', '箴言', 20, 16, 20, '留心听训言的必定得益；倚靠主的是有福的人。'),
('CNV', '箴言', 20, 16, 21, '心中有智慧的必称为聪明人；动听的话能增加说服力。'),
('CNV', '箴言', 20, 16, 22, '明慧人的明慧是他生命的泉源；愚妄人的惩罚就是愚妄。'),
('CNV', '箴言', 20, 16, 23, '智慧人的心教导自己的口，使自己口中的话增加说服力。'),
('CNV', '箴言', 20, 16, 24, '恩慈的话好像蜂巢中的蜂蜜，使人心里甘甜，骨头健壮。'),
('CNV', '箴言', 20, 16, 25, '有一条路，人以为是正路，走到尽头却是死亡之路。'),
('CNV', '箴言', 20, 16, 26, '劳力的人身体的需要促使他劳力；因为他的饥饿催逼着他。'),
('CNV', '箴言', 20, 16, 27, '无赖之徒挖出邪恶，他口里的话好像灼热的火。'),
('CNV', '箴言', 20, 16, 28, '乖谬的人散播纷争，搬弄是非的离间亲密的朋友。'),
('CNV', '箴言', 20, 16, 29, '强暴的人引诱邻舍，领他走邪恶的道路。'),
('CNV', '箴言', 20, 16, 30, '瞇着眼睛的，图谋乖谬的事；紧抿着嘴唇的，作成恶事。'),
('CNV', '箴言', 20, 16, 31, '白发是荣耀的冠冕，在公义的路上，必能得着。'),
('CNV', '箴言', 20, 16, 32, '不轻易动怒的，胜过勇士；克服己心的，胜过把城攻取的人。'),
('CNV', '箴言', 20, 16, 33, '签抛在人的怀中，一切决断却在于主。'),
('CNV', '箴言', 20, 17, 1, '平静相安地吃一块干饼，胜过筵席满屋，吵闹相争。'),
('CNV', '箴言', 20, 17, 2, '明慧的仆人，必管辖主人贻羞的儿子；又可以在众儿子中同分产业。'),
('CNV', '箴言', 20, 17, 3, '用锅炼银，用炉炼金；唯有主锻炼人心。'),
('CNV', '箴言', 20, 17, 4, '作恶的人留心听邪恶的话；说谎的人侧耳听攻击人的话。'),
('CNV', '箴言', 20, 17, 5, '嘲笑穷人的就是辱骂造他的主；幸灾乐祸的必难免受惩罚。'),
('CNV', '箴言', 20, 17, 6, '儿孙是老人的冠冕，父亲是儿女的荣耀。'),
('CNV', '箴言', 20, 17, 7, '愚顽人说佳美的话是不相称的，何况尊贵的人说虚谎的话呢！'),
('CNV', '箴言', 20, 17, 8, '在馈送的人看来，贿赂有如灵符（“灵符”原文作“恩惠宝石”）；无论他到哪里，都必顺利。'),
('CNV', '箴言', 20, 17, 9, '遮掩别人过犯的，得到人的喜爱；屡次提起别人过错的，离间亲密的朋友。'),
('CNV', '箴言', 20, 17, 10, '对聪明人说一句责备的话，胜过责打愚昧人一百下。'),
('CNV', '箴言', 20, 17, 11, '悖逆的人只求恶事，必有残忍的使者奉派去对付他。'),
('CNV', '箴言', 20, 17, 12, '宁愿遇见失掉幼子的母熊，也不愿遇见正在行愚妄事的愚昧人。'),
('CNV', '箴言', 20, 17, 13, '以恶报善的，灾祸必不离开他的家。'),
('CNV', '箴言', 20, 17, 14, '纷争的开始，如同决堤的水；所以在争执发生以前，就要制止。'),
('CNV', '箴言', 20, 17, 15, '宣判恶人为义，裁定义人有罪，二者都是主所厌恶的。'),
('CNV', '箴言', 20, 17, 16, '愚昧人既是无知，为什么手里拿着价银要买智慧呢？'),
('CNV', '箴言', 20, 17, 17, '朋友常显爱心，兄弟为患难而生。'),
('CNV', '箴言', 20, 17, 18, '为邻舍击掌作保证人的，是无知的人。'),
('CNV', '箴言', 20, 17, 19, '喜爱争竞的就是喜爱过犯；把家门建高的自取灭亡。'),
('CNV', '箴言', 20, 17, 20, '心存欺诈的得不着益处；舌头搬弄是非的必陷在祸患中。'),
('CNV', '箴言', 20, 17, 21, '生下愚昧的儿子，使父亲忧愁；愚顽人的父亲毫无喜乐。'),
('CNV', '箴言', 20, 17, 22, '心里喜乐就是良药；心灵忧郁使骨头枯干。'),
('CNV', '箴言', 20, 17, 23, '恶人暗中（“暗中”原文作“从怀里”）接受贿赂，为要歪曲公正。'),
('CNV', '箴言', 20, 17, 24, '聪明人面前有智慧，愚昧人却眼望地极。'),
('CNV', '箴言', 20, 17, 25, '愚昧的儿子使父亲愁烦，使母亲痛苦。'),
('CNV', '箴言', 20, 17, 26, '惩罚义人，已是不当；击打正直的官长，更是不妥。'),
('CNV', '箴言', 20, 17, 27, '有知识的约束自己的言语；聪明人心平气和。'),
('CNV', '箴言', 20, 17, 28, '愚妄人默不作声，也算是智慧；闭口不言，也算是聪明。'),
('CNV', '箴言', 20, 18, 1, '离群独处的，只顾自己的心愿；他抗拒一切大智慧。'),
('CNV', '箴言', 20, 18, 2, '愚昧人不喜欢明白事理，只喜欢显露自己的心意。'),
('CNV', '箴言', 20, 18, 3, '恶人来，也带来藐视；羞耻的事也引致羞辱。'),
('CNV', '箴言', 20, 18, 4, '人口中的言语如同深水，智慧的泉源好像涌流的河水。'),
('CNV', '箴言', 20, 18, 5, '在审判时，偏袒恶人、屈枉义人，是不对的。'),
('CNV', '箴言', 20, 18, 6, '愚昧人的嘴引起纷争，他的口招来责打。'),
('CNV', '箴言', 20, 18, 7, '愚昧人的口自取灭亡，他的嘴唇是自己性命的网罗。'),
('CNV', '箴言', 20, 18, 8, '搬弄是非的人的言语，如同美食，深入人的脏腑。'),
('CNV', '箴言', 20, 18, 9, '工作懒惰的，是灭亡者的兄弟。'),
('CNV', '箴言', 20, 18, 10, '主的名是坚固的高台，义人投奔，就得安全。'),
('CNV', '箴言', 20, 18, 11, '富翁的财物是他们的坚城；在他们的想象中，有如高墙。'),
('CNV', '箴言', 20, 18, 12, '灭亡以先，人心高傲；尊荣以先，必有谦卑。'),
('CNV', '箴言', 20, 18, 13, '不先聆听就回答的，这就是他的愚妄和羞辱。'),
('CNV', '箴言', 20, 18, 14, '人的心灵能忍受疾病，心灵忧郁，谁能承受呢？'),
('CNV', '箴言', 20, 18, 15, '聪明人的心获得知识；智慧人的耳朵寻求知识。'),
('CNV', '箴言', 20, 18, 16, '人的礼物能为他开路，引他到大人物面前。'),
('CNV', '箴言', 20, 18, 17, '首先陈述情由的，似乎有理，等他的邻舍来到，才可以查明实情。'),
('CNV', '箴言', 20, 18, 18, '抽签能止息纷争，排解二强之间的纠纷。'),
('CNV', '箴言', 20, 18, 19, '触怒兄弟，要劝他和解，比取坚城还难；这样的纷争，如同堡垒的门闩。'),
('CNV', '箴言', 20, 18, 20, '人口中所结的果子，必使自己的肚腹饱足；他嘴里所出的，必使他饱足。'),
('CNV', '箴言', 20, 18, 21, '生与死都在舌头的权下；爱把弄这权柄的，必自食其果。'),
('CNV', '箴言', 20, 18, 22, '觅得贤妻的，就是觅得幸福，也是蒙了主的恩宠。'),
('CNV', '箴言', 20, 18, 23, '穷人乞恩哀求，财主却声色俱厉地回答。'),
('CNV', '箴言', 20, 18, 24, '朋友众多的人，终必彼此破裂，但有一位朋友，比兄弟更亲密。'),
('CNV', '箴言', 20, 19, 1, '行为完全的穷人，胜过说话欺诈的愚昧人。'),
('CNV', '箴言', 20, 19, 2, '一个人没有知识是不好的，脚步匆忙的，难免失足。'),
('CNV', '箴言', 20, 19, 3, '人的愚妄毁灭自己的道路；他的心却恼怒主。'),
('CNV', '箴言', 20, 19, 4, '财富使朋友增多，但穷人连他的一个朋友也与他分离。'),
('CNV', '箴言', 20, 19, 5, '作假见证的必难免受惩罚；吐出谎言的必不能逃脱。'),
('CNV', '箴言', 20, 19, 6, '尊贵的人，很多人求他的情面；慷慨施赠的，人人都作他的朋友。'),
('CNV', '箴言', 20, 19, 7, '贫穷人的兄弟都恨他；他的朋友更疏远他。虽然他多多恳求他们，他们却不理会。'),
('CNV', '箴言', 20, 19, 8, '得着智慧的，爱惜自己的性命；保持明达的，必得益处。'),
('CNV', '箴言', 20, 19, 9, '作假见证的必难免受惩罚；吐出谎言的终必灭亡。'),
('CNV', '箴言', 20, 19, 10, '愚昧人生活奢侈是不相称的，何况奴仆管辖领袖呢！'),
('CNV', '箴言', 20, 19, 11, '人的明慧使他不轻易动怒；宽恕别人过失的，是自己的荣耀。'),
('CNV', '箴言', 20, 19, 12, '王的忿怒，好像狮子的吼叫，他的恩宠，如同草上的朝露。'),
('CNV', '箴言', 20, 19, 13, '愚昧的儿子是父亲的祸患，吵闹的妻子好像雨水不停地滴漏。'),
('CNV', '箴言', 20, 19, 14, '房屋与财富是祖宗遗留的产业；唯有明慧的妻子是主所赐的。'),
('CNV', '箴言', 20, 19, 15, '懒惰使人沉睡，闲懒的人必受饥饿。'),
('CNV', '箴言', 20, 19, 16, '谨守诫命的，保全自己的性命；轻忽自己道路的，必致死亡。'),
('CNV', '箴言', 20, 19, 17, '恩待穷人的，等于借钱给主；他所行的，主必偿还。'),
('CNV', '箴言', 20, 19, 18, '趁着还有指望的时候，要管教你的儿子；不可存心使他死亡。'),
('CNV', '箴言', 20, 19, 19, '常发烈怒的人，必须受罚，如果你帮助他，就必须一而再帮助他。'),
('CNV', '箴言', 20, 19, 20, '你要听劝告，受管教，好使你将来作个有智慧的人。'),
('CNV', '箴言', 20, 19, 21, '人心里的谋算很多，唯有主的计划能实现。'),
('CNV', '箴言', 20, 19, 22, '人所渴望的，就是忠诚；作穷人比作撒谎的人还好。'),
('CNV', '箴言', 20, 19, 23, '敬畏主的，得着生命；他必安居知足，不会遭受祸患。'),
('CNV', '箴言', 20, 19, 24, '懒惰人把手放在盘子里，连拿食物送回口边，也不愿意。'),
('CNV', '箴言', 20, 19, 25, '责打好讥笑人的，愚蒙人就会变得精明；责备聪明人，他就会明白知识。'),
('CNV', '箴言', 20, 19, 26, '虐待父亲，赶走母亲的，是贻羞可耻的儿子。'),
('CNV', '箴言', 20, 19, 27, '我儿，你若是停止听受管教，就会偏离知识的言语。'),
('CNV', '箴言', 20, 19, 28, '无赖作见证，嘲笑公平，恶人的口，吞吃罪孽。'),
('CNV', '箴言', 20, 19, 29, '刑罚是为好讥笑人的预备的，鞭打是为愚昧人的背预备的。'),
('CNV', '箴言', 20, 20, 1, '酒能使人狂放，烈酒能使人喧哗；所有因醉酒而犯错的，都没有智慧。'),
('CNV', '箴言', 20, 20, 2, '王的震怒好像狮子的吼叫；触怒他的是自害己命。'),
('CNV', '箴言', 20, 20, 3, '平息纷争就是人的荣耀；只有愚妄人个个都爱争执。'),
('CNV', '箴言', 20, 20, 4, '懒惰人冬天不耕种；到收割的时候，出去求食，必一无所得。'),
('CNV', '箴言', 20, 20, 5, '人心里的谋略如同深水，唯有聪明人能汲引出来。'),
('CNV', '箴言', 20, 20, 6, '很多人自称忠诚，但信实的人，谁能遇着呢？'),
('CNV', '箴言', 20, 20, 7, '行为完全的义人，他的后代是有福的。'),
('CNV', '箴言', 20, 20, 8, '君王坐在审判的位上，他的眼目查察一切恶事。'),
('CNV', '箴言', 20, 20, 9, '谁能说：“我洁净了我的心，我是清洁无罪的”？'),
('CNV', '箴言', 20, 20, 10, '不同的法码，不同的量器，两样都是主所厌恶的。'),
('CNV', '箴言', 20, 20, 11, '孩童的行动是否清洁正直，凭他的行为就可以把他自己显明出来。'),
('CNV', '箴言', 20, 20, 12, '能听的耳朵和能看的眼睛，两样都是主所造的。'),
('CNV', '箴言', 20, 20, 13, '不要贪睡，免得你贫穷；睁开眼睛，你才有饱餐。'),
('CNV', '箴言', 20, 20, 14, '买东西的说：“不好，不好！”离去以后，他就自夸。'),
('CNV', '箴言', 20, 20, 15, '虽有金子、许多红宝石和宝器，但充满知识的嘴唇比这一切更宝贵。'),
('CNV', '箴言', 20, 20, 16, '谁为陌生人作保证人，就拿去谁的衣服；谁替妓女作保证人，谁就要作担保。'),
('CNV', '箴言', 20, 20, 17, '欺骗得来的食物，人总觉得甘甜；事后他的口必充满沙石。'),
('CNV', '箴言', 20, 20, 18, '计划要有筹算才能确立；作战也要倚靠智谋。'),
('CNV', '箴言', 20, 20, 19, '到处搬弄是非的，泄露秘密；口无遮拦的，不可与他结交。'),
('CNV', '箴言', 20, 20, 20, '咒骂父母的，他的灯必在漆黑的幽暗中熄灭。'),
('CNV', '箴言', 20, 20, 21, '起初迅速得来的产业，最后却不是福气。'),
('CNV', '箴言', 20, 20, 22, '你不要说：“我要以恶报恶”；要等候主，他必拯救你。'),
('CNV', '箴言', 20, 20, 23, '不同的法码是主所厌恶的；诡诈的天平，也是邪恶的。'),
('CNV', '箴言', 20, 20, 24, '人的脚步是由主所定，人怎能明白自己的道路呢？'),
('CNV', '箴言', 20, 20, 25, '如果有人轻率地说：“这是归神为圣之物”，许愿以后才重新考虑，就是自陷网罗。'),
('CNV', '箴言', 20, 20, 26, '智慧的王簸散恶人，并用车轮碾他们。'),
('CNV', '箴言', 20, 20, 27, '人的灵是主的灯，探照人的脏腑。'),
('CNV', '箴言', 20, 20, 28, '慈爱和信实保护君王，他的王位也藉慈爱维持。'),
('CNV', '箴言', 20, 20, 29, '气力是年轻人的荣耀，白发是老年人的尊荣。'),
('CNV', '箴言', 20, 20, 30, '鞭伤能除净人的邪恶，责打能洗净人的脏腑。'),
('CNV', '箴言', 20, 21, 1, '君王的心在主手中，好像水沟的水，他可以随意转移。'),
('CNV', '箴言', 20, 21, 2, '人看自己一切所行的，都是正直的；主却衡量人心。'),
('CNV', '箴言', 20, 21, 3, '秉公行义，比献祭更蒙主悦纳。'),
('CNV', '箴言', 20, 21, 4, '高傲的眼、傲慢的心，恶人的灯，都是罪恶。'),
('CNV', '箴言', 20, 21, 5, '殷勤人的筹划必使他获利；行事急躁的必致贫穷。'),
('CNV', '箴言', 20, 21, 6, '凭撒谎的舌头得来的财宝，是飘荡的浮云、死亡的追寻。'),
('CNV', '箴言', 20, 21, 7, '恶人的暴行必拖累自己；因为他们不肯秉行公正。'),
('CNV', '箴言', 20, 21, 8, '罪人的道路充满狡诈，清洁的人，行为正直。'),
('CNV', '箴言', 20, 21, 9, '宁可住在房顶的一角，也不跟吵闹的妇人同住一间房屋。'),
('CNV', '箴言', 20, 21, 10, '恶人的心只求邪恶，他的眼并不顾惜邻舍。'),
('CNV', '箴言', 20, 21, 11, '好讥笑人的受刑罚的时候，愚蒙人就得着智慧；智慧人受训诲的时候，他就得着知识。'),
('CNV', '箴言', 20, 21, 12, '公义的神留意恶人的家，使恶人在祸患中毁灭。'),
('CNV', '箴言', 20, 21, 13, '塞耳不听贫穷人呼求的，他将来呼求，也得不到应允。'),
('CNV', '箴言', 20, 21, 14, '暗中送的礼物，可以平息怒气，怀里藏的贿赂，能平息暴怒。'),
('CNV', '箴言', 20, 21, 15, '秉行公正，使义人喜乐，却使作孽的人恐惧。'),
('CNV', '箴言', 20, 21, 16, '偏离明慧之道的人，必住在阴魂的会中。'),
('CNV', '箴言', 20, 21, 17, '贪爱享乐的，必成为穷乏人；好酒爱脂油的，必不会富足。'),
('CNV', '箴言', 20, 21, 18, '恶人作了义人的赎价，奸诈人作了正直人的替身。'),
('CNV', '箴言', 20, 21, 19, '宁可住在野地，也不跟吵闹易怒的妇人同住。'),
('CNV', '箴言', 20, 21, 20, '智慧人的居所中，积存珍贵的财物和油；愚昧人却把他所有的挥霍耗尽。'),
('CNV', '箴言', 20, 21, 21, '追求公义与慈爱的，必得着生命、公义和荣耀。'),
('CNV', '箴言', 20, 21, 22, '智慧人登上勇士的城，倾覆他倚靠的坚垒。'),
('CNV', '箴言', 20, 21, 23, '谨守口舌的，保护自己免受患难。'),
('CNV', '箴言', 20, 21, 24, '骄傲自大的人，他的名字是好讥笑人的；他行事狂妄骄傲。'),
('CNV', '箴言', 20, 21, 25, '懒惰人的愿望害死自己，因为他的手不肯工作。'),
('CNV', '箴言', 20, 21, 26, '他终日贪得无厌，但义人施予毫不吝啬。'),
('CNV', '箴言', 20, 21, 27, '恶人的祭物是主所厌恶的，更何况是怀着恶念来献的呢？'),
('CNV', '箴言', 20, 21, 28, '作假见证的必要灭亡，聆听真情的人，他的话长存。'),
('CNV', '箴言', 20, 21, 29, '恶人厚颜无耻，正直人却坚定他的道路。'),
('CNV', '箴言', 20, 21, 30, '任何智慧、聪明、谋略都不能敌挡主。'),
('CNV', '箴言', 20, 21, 31, '马是为打仗之日预备的，胜利却在于主。'),
('CNV', '箴言', 20, 22, 1, '名誉胜过多财，恩宠胜过金银。'),
('CNV', '箴言', 20, 22, 2, '世上有财主，也有穷人，两者都是主所造的。'),
('CNV', '箴言', 20, 22, 3, '精明人看见灾祸，就躲藏起来；愚蒙人却往前走，自取祸害。'),
('CNV', '箴言', 20, 22, 4, '谦卑和敬畏主的赏赐，就是财富、荣耀和生命。'),
('CNV', '箴言', 20, 22, 5, '奸诈人的道路，满布荆棘和网罗；谨慎自己的，必远离这些。'),
('CNV', '箴言', 20, 22, 6, '教养孩童走他当行的路，就是到老，他也不会偏离。'),
('CNV', '箴言', 20, 22, 7, '财主管辖穷人，欠债的作债主的奴仆。'),
('CNV', '箴言', 20, 22, 8, '散播邪恶的，必收祸害；他忿怒的杖终必毁掉。'),
('CNV', '箴言', 20, 22, 9, '心存良善看人的，必蒙赐福；因为他把自己的食物分给穷人。'),
('CNV', '箴言', 20, 22, 10, '赶走好讥笑人的，纷争就除去；争执和耻辱也必止息。'),
('CNV', '箴言', 20, 22, 11, '喜爱内心洁净，嘴上有恩言的，君王要作他的朋友。'),
('CNV', '箴言', 20, 22, 12, '主的眼目护卫知识，却倾覆奸诈人的话。'),
('CNV', '箴言', 20, 22, 13, '懒惰人说：“外面有狮子，我在街上必被杀害。”'),
('CNV', '箴言', 20, 22, 14, '淫妇的口是深坑，主所恼恨的必陷在其中。'),
('CNV', '箴言', 20, 22, 15, '愚妄束缚孩童的心，管教的杖可以把愚妄远远驱除。'),
('CNV', '箴言', 20, 22, 16, '欺压穷人为要增加自己财富的，送礼给财主的，必致穷乏。'),
('CNV', '箴言', 20, 22, 17, '你要留心听智慧人的言语，专心领受我的知识。'),
('CNV', '箴言', 20, 22, 18, '如果你心里谨守，嘴唇上常常诵念这一切，自会觉得甘美。'),
('CNV', '箴言', 20, 22, 19, '我今日特别指教你，为要使你倚靠主。'),
('CNV', '箴言', 20, 22, 20, '我不是曾经给你们写下（“我不是曾经给你们写下”或译：“我不是给你们写了三十条”）有关谋略和知识的事吗？'),
('CNV', '箴言', 20, 22, 21, '要教你认识确实的真理，使你把真理回覆那差派你来的人。'),
('CNV', '箴言', 20, 22, 22, '你不可因为贫穷人穷乏，就抢夺他的东西，也不可在城门口欺压穷苦人。'),
('CNV', '箴言', 20, 22, 23, '因为主必为他们伸冤，抢夺他们的，主也必夺取那人的性命。'),
('CNV', '箴言', 20, 22, 24, '容易发怒的人，不要与他为友；脾气暴躁的人，不要与他来往，'),
('CNV', '箴言', 20, 22, 25, '免得你效法他的行径，自己就陷在网罗里。'),
('CNV', '箴言', 20, 22, 26, '不要替别人击掌担保，也不可为欠债的作保证人。'),
('CNV', '箴言', 20, 22, 27, '如果你没有什么可以偿还，何必使人连你睡觉的床也夺去呢？'),
('CNV', '箴言', 20, 22, 28, '你的祖先立定古时的地界，你不可迁移。'),
('CNV', '箴言', 20, 22, 29, '你见过办事能干的人吗？他必侍立在君王面前，必不会侍立在低微的人面前。'),
('CNV', '箴言', 20, 23, 1, '你与官长一起坐席吃饭的时候，要特别留意在你面前的是谁。'),
('CNV', '箴言', 20, 23, 2, '你若是个贪吃的人，就当把刀子放在喉咙上。'),
('CNV', '箴言', 20, 23, 3, '不可贪恋他的美食，因为那是骗人的食物。'),
('CNV', '箴言', 20, 23, 4, '不要劳碌求富，你要明智地放下这企图。'),
('CNV', '箴言', 20, 23, 5, '你的眼睛注视在钱财上，钱财却不见了，因为钱财必长起翅膀，如鹰飞往天上。'),
('CNV', '箴言', 20, 23, 6, '不可吃吝啬人的饭，也不可贪恋他的美食。'),
('CNV', '箴言', 20, 23, 7, '因为他心里怎样计算，他的为人就是怎样；他虽然对你说：“请吃，请喝！”他的心里却没有你。'),
('CNV', '箴言', 20, 23, 8, '你所吃的那一点食物，必要吐出来，你道谢的美言，也都白费了。'),
('CNV', '箴言', 20, 23, 9, '不要说话给愚昧人听，因为他必藐视你明慧的言语。'),
('CNV', '箴言', 20, 23, 10, '你不可迁移古时的地界；也不可侵占孤儿的田地。'),
('CNV', '箴言', 20, 23, 11, '因为他们的救赎主大有能力，他必向你为他们的案件伸冤。'),
('CNV', '箴言', 20, 23, 12, '你要专心领受教训，留心听知识的言语。'),
('CNV', '箴言', 20, 23, 13, '要管教孩童，不可姑息，你虽然用杖打他，他也不会死；'),
('CNV', '箴言', 20, 23, 14, '你要用杖打他，就可以救他的灵魂免下阴间。'),
('CNV', '箴言', 20, 23, 15, '我儿，如果你的心有智慧，我的心也就欢喜；'),
('CNV', '箴言', 20, 23, 16, '你的嘴唇说正直话的时候，我的内心就欢乐。'),
('CNV', '箴言', 20, 23, 17, '你的心不要嫉妒罪人，只要时常敬畏主。'),
('CNV', '箴言', 20, 23, 18, '因为万事必有结局，你的盼望也不会断绝。'),
('CNV', '箴言', 20, 23, 19, '我儿，你要听，要有智慧，要引导你的心走在正路上。'),
('CNV', '箴言', 20, 23, 20, '酗酒的人，不可与他们来往；暴食的人，不要与他们为友。'),
('CNV', '箴言', 20, 23, 21, '因为酗酒暴食的人必致穷乏；贪睡的人必穿破衣。'),
('CNV', '箴言', 20, 23, 22, '你要听从生你的父亲；也不可因为母亲老了，就藐视她。'),
('CNV', '箴言', 20, 23, 23, '你要买真理，不可出卖；要得智慧、教训和哲理。'),
('CNV', '箴言', 20, 23, 24, '义人的父亲必大有快乐；生下智慧的儿子的，必因儿子欢喜。'),
('CNV', '箴言', 20, 23, 25, '要使你的父母欢喜，使生下你的快乐。'),
('CNV', '箴言', 20, 23, 26, '我儿，把你的心给我；你的眼目要关注我的道路。'),
('CNV', '箴言', 20, 23, 27, '因为妓女是深坑，淫妇是狭窄的井。'),
('CNV', '箴言', 20, 23, 28, '她像强盗一样埋伏，使人间增添很多奸诈的人。'),
('CNV', '箴言', 20, 23, 29, '谁有祸患？谁有愁苦？谁有纷争？谁有怨言？谁无故受伤？谁的眼睛赤红？'),
('CNV', '箴言', 20, 23, 30, '就是那些沉湎于酒，常去品尝调和了的酒的人。'),
('CNV', '箴言', 20, 23, 31, '你不要看酒怎样发红，在杯中怎样闪烁诱人，喝下去怎样舒畅，'),
('CNV', '箴言', 20, 23, 32, '最后它却像咬你的蛇、像刺你的毒蛇。'),
('CNV', '箴言', 20, 23, 33, '你的眼睛必看见怪异的事，你的心必说乖谬的话。'),
('CNV', '箴言', 20, 23, 34, '你必好像躺在海中，又好像躺在桅杆顶上。'),
('CNV', '箴言', 20, 23, 35, '你必说：“人打我，我不痛；人鞭打我，我不晓得；我什么时候清醒？我还要再去寻酒。”'),
('CNV', '箴言', 20, 24, 1, '你不要嫉妒恶人，也不要祈望与他们共处。'),
('CNV', '箴言', 20, 24, 2, '因为他们的心图谋强暴，他们的嘴唇讲论奸恶。'),
('CNV', '箴言', 20, 24, 3, '房屋的建造是凭着智慧，又藉着聪明得到坚立；'),
('CNV', '箴言', 20, 24, 4, '并且藉着知识，各房间充满各样宝贵和美好的财物。'),
('CNV', '箴言', 20, 24, 5, '智慧人大有能力，有知识的人力上加力。'),
('CNV', '箴言', 20, 24, 6, '你要凭着智谋去作战；谋士众多，就可得胜。'),
('CNV', '箴言', 20, 24, 7, '智慧对愚妄人来说是太高超，因此他在城门口哑口无言。'),
('CNV', '箴言', 20, 24, 8, '计划作恶的，必称为阴谋家。'),
('CNV', '箴言', 20, 24, 9, '愚妄人的计谋，尽是罪恶；好讥笑人的是人所厌恶的。'),
('CNV', '箴言', 20, 24, 10, '你在患难的日子若是懈怠，你的力量就微小。'),
('CNV', '箴言', 20, 24, 11, '被拉到死地的人，你要拯救；将要被杀戮的人，你要挽救。'),
('CNV', '箴言', 20, 24, 12, '如果你说：“这事我不知道。”那衡量人心的不明白吗？那看顾你性命的不晓得吗？他不按照各人的行为报应各人吗？'),
('CNV', '箴言', 20, 24, 13, '我儿，你要吃蜜，因为这是好的；吃蜂房下滴的蜜，就觉甘甜。'),
('CNV', '箴言', 20, 24, 14, '要知道智慧对你的心也是这样，如果你得着智慧，就必有好结局，你的盼望也不会断绝。'),
('CNV', '箴言', 20, 24, 15, '恶人哪！不要埋伏攻击义人的住处，不要毁坏他的居所。'),
('CNV', '箴言', 20, 24, 16, '因为义人虽然七次跌倒，仍能再起来；但恶人必在祸患中绊倒。'),
('CNV', '箴言', 20, 24, 17, '你的仇敌跌倒的时候，你不要欢喜；他绊倒的时候，你心里不可欢乐。'),
('CNV', '箴言', 20, 24, 18, '恐怕主看见了，就不喜悦，把他的怒气从仇敌的身上，转到你的身上。'),
('CNV', '箴言', 20, 24, 19, '不要因作恶的人心怀不平，也不要嫉妒恶人。'),
('CNV', '箴言', 20, 24, 20, '因为恶人必没有好结局，恶人的灯必要熄灭。'),
('CNV', '箴言', 20, 24, 21, '我儿，你要敬畏主，也要尊敬君王；不要与叛逆的人结交。'),
('CNV', '箴言', 20, 24, 22, '因为他们的刑罚必忽然临到；主与君王要施行的毁灭，谁能晓得呢？'),
('CNV', '箴言', 20, 24, 23, '以下也是智慧人的话：审判的时候看人的情面是不对的。'),
('CNV', '箴言', 20, 24, 24, '对坏人说“你是好人”的，万民都要咒骂他，万族都必憎恶他。'),
('CNV', '箴言', 20, 24, 25, '指责坏人的，必得欢悦；美福必临到他们。'),
('CNV', '箴言', 20, 24, 26, '应对诚实的，如同与别人亲嘴。'),
('CNV', '箴言', 20, 24, 27, '你要在外面预备好你的工作，在田间为自己准备妥当，然后建造你的房屋。'),
('CNV', '箴言', 20, 24, 28, '不可无故作证指控你的邻舍；不可诬告他人。'),
('CNV', '箴言', 20, 24, 29, '你不可说：“人怎样待我，我也怎样待他；我要照他所行的报复他。”'),
('CNV', '箴言', 20, 24, 30, '我经过懒惰人的田地，无知人的葡萄园；'),
('CNV', '箴言', 20, 24, 31, '只见到处长满蒺藜，地面盖满刺草，石墙也倒塌了。'),
('CNV', '箴言', 20, 24, 32, '我看了，就用心思想；我见了，就领受了教训。'),
('CNV', '箴言', 20, 24, 33, '再睡片时，打盹片时，抱着手躺卧片时，'),
('CNV', '箴言', 20, 24, 34, '你的贫穷就必像强盗来到，你的缺乏就必像拿兵器的人来到。'),
('CNV', '箴言', 20, 25, 1, '以下也是所罗门的箴言，是犹大王希西家的人抄录的：'),
('CNV', '箴言', 20, 25, 2, '把事隐藏，是神的荣耀；把事察清，是君王的光荣。'),
('CNV', '箴言', 20, 25, 3, '人不知天有多高，地有多厚，君王的心也照样测不透。'),
('CNV', '箴言', 20, 25, 4, '除去银子的渣滓，银匠就可以做出器皿；'),
('CNV', '箴言', 20, 25, 5, '除去君王面前的坏人，他的王位就可以靠公义坚立。'),
('CNV', '箴言', 20, 25, 6, '你在君王面前，不可妄自尊大；也不可擅自站立在大人物中间。'),
('CNV', '箴言', 20, 25, 7, '宁可让人对你说：“请上座！”胜过在你觐见的显贵面前，被人叫你退下去。'),
('CNV', '箴言', 20, 25, 8, '不可轻率出去与人争讼；否则，你的邻舍若使你受辱，结果你要怎么办呢？'),
('CNV', '箴言', 20, 25, 9, '如果有纷争，只与你的邻舍一人争论好了；不可揭发别人的秘密，'),
('CNV', '箴言', 20, 25, 10, '恐怕听见的人辱骂你，你的恶名就不能脱掉。'),
('CNV', '箴言', 20, 25, 11, '一句话说得合宜，就像金苹果镶在银的器物上。'),
('CNV', '箴言', 20, 25, 12, '智慧人的责备在听从的人耳中，好像金耳环和精金的饰物。'),
('CNV', '箴言', 20, 25, 13, '忠信的使者对那些差遣他的人来说，好像在收割的时候，有冰雪的凉气，使主人精神舒畅。'),
('CNV', '箴言', 20, 25, 14, '空夸送礼却没有实行的人，就像无雨的风云。'),
('CNV', '箴言', 20, 25, 15, '恒久忍耐可以劝服掌权的人，柔和的舌头，可以折断骨头。'),
('CNV', '箴言', 20, 25, 16, '你找到蜂蜜，吃够就好了；免得吃得过多，就呕吐出来。'),
('CNV', '箴言', 20, 25, 17, '你的脚要少进邻舍的家；免得他厌烦你，就憎恶你。'),
('CNV', '箴言', 20, 25, 18, '作假见证陷害邻舍的人，就像大锤、快刀和利箭。'),
('CNV', '箴言', 20, 25, 19, '遭遇灾难的时候，倚靠奸诈的人，就像倚靠坏牙和不稳的脚。'),
('CNV', '箴言', 20, 25, 20, '对着悲伤的心灵唱歌，就像冷天脱衣服，又像碱上倒酸。'),
('CNV', '箴言', 20, 25, 21, '如果你的仇敌饿了，就给他食物吃；如果渴了，就给他水喝，'),
('CNV', '箴言', 20, 25, 22, '因为你这样作，就是把炭火堆在他的头上，主必还报你。'),
('CNV', '箴言', 20, 25, 23, '北风带来雨水；暗中毁谤人的舌头，使人怒容满面。'),
('CNV', '箴言', 20, 25, 24, '宁可住在房顶的一角，也不跟吵闹的妇人同住一间房屋。'),
('CNV', '箴言', 20, 25, 25, '来自远方的好消息，好像疲乏的人得喝凉水。'),
('CNV', '箴言', 20, 25, 26, '义人在恶人面前屈服，好像混浊了的水泉、污染了的水井。'),
('CNV', '箴言', 20, 25, 27, '吃蜜过多是不好的；追寻自己的荣耀，也是不好的。'),
('CNV', '箴言', 20, 25, 28, '人若不控制自己的心，就像没有城墙，毁坏了的城一样。'),
('CNV', '箴言', 20, 26, 1, '夏天落雪，收割时下雨，都不合宜；照样，愚昧人获得尊荣，也不合宜。'),
('CNV', '箴言', 20, 26, 2, '麻雀怎样飞来飞去，燕子怎样翻飞；照样，无故的咒诅也不会临到人。'),
('CNV', '箴言', 20, 26, 3, '鞭子是为了打马，嚼环是为了勒驴；刑杖是为了打愚昧人的背。'),
('CNV', '箴言', 20, 26, 4, '不要照着愚昧人的愚妄回答他，免得你像他一样。'),
('CNV', '箴言', 20, 26, 5, '要照着愚昧人的愚妄回答他，免得他自以为有智慧。'),
('CNV', '箴言', 20, 26, 6, '藉愚昧人的手传递信息的，是自断己足，自寻烦恼。'),
('CNV', '箴言', 20, 26, 7, '箴言在愚昧人口中，就像瘸子的腿，虚悬无用。'),
('CNV', '箴言', 20, 26, 8, '把荣耀给愚昧人的，就像人把石子系在投石器上。'),
('CNV', '箴言', 20, 26, 9, '箴言在愚昧人口中，就像荆棘在醉汉手里。'),
('CNV', '箴言', 20, 26, 10, '雇用愚昧人和过路人的，就像胡乱射伤众人的弓箭手。'),
('CNV', '箴言', 20, 26, 11, '愚昧人一再重复他的愚妄，正像狗转过来，吃自己所吐的。'),
('CNV', '箴言', 20, 26, 12, '你见过自以为有智慧的人吗？愚昧人比他更有指望。'),
('CNV', '箴言', 20, 26, 13, '懒惰人说：“路上有狮子，广场上也有狮子。”'),
('CNV', '箴言', 20, 26, 14, '懒惰人在床上翻动，就像门绕着门铰转动一样。'),
('CNV', '箴言', 20, 26, 15, '懒惰人把手放在盘子里，连拿食物送回口边也觉得劳累。'),
('CNV', '箴言', 20, 26, 16, '懒惰人看自己，比七个善于应对的人更有智慧。'),
('CNV', '箴言', 20, 26, 17, '过路的人被激怒，去干涉与自己无关的争执，就像人揪住狗的耳朵。'),
('CNV', '箴言', 20, 26, 18, '人欺骗了邻舍，却说：“我不过是开玩笑罢了。”他就像疯狂的人，投掷火把、利箭和杀人的武器。'),
('CNV', '箴言', 20, 26, 20, '没有柴，火就熄灭；没有搬弄是非的人，纷争就平息。'),
('CNV', '箴言', 20, 26, 21, '好争竞的人，煽动争端，就像余烬上加炭，火上加柴一样。'),
('CNV', '箴言', 20, 26, 22, '搬弄是非的人的言语如同美食；深入人的脏腑。'),
('CNV', '箴言', 20, 26, 23, '嘴唇火热，心却奸恶，就像包上银渣的瓦器。'),
('CNV', '箴言', 20, 26, 24, '憎恶人的用话语掩饰自己，心里却存着诡诈。'),
('CNV', '箴言', 20, 26, 25, '他的话语虽然动听，你不可信他，因为他心里有七样可厌恶的事。'),
('CNV', '箴言', 20, 26, 26, '他的怨恨虽然以诡诈掩饰，但他的邪恶必在大会中显露出来。'),
('CNV', '箴言', 20, 26, 27, '挖掘陷坑的，自己必掉在其中；辊石头的，石头必辊回自己身上。'),
('CNV', '箴言', 20, 26, 28, '虚谎的舌头憎恶被它伤害的人；谄媚的口造成败坏。'),
('CNV', '箴言', 20, 27, 1, '不要为明日自夸，因为今天要发生什么事，你尚且不知道。'),
('CNV', '箴言', 20, 27, 2, '让外人夸奖你，不可自己夸奖自己；让别人称赞你，不可自己称赞自己。'),
('CNV', '箴言', 20, 27, 3, '石头重，沙土也重，愚妄人的怒气比这两样更重。'),
('CNV', '箴言', 20, 27, 4, '烈怒虽然凶残，暴怒又好像狂澜，人还可以忍受；但面对嫉妒，谁能站立得住呢？'),
('CNV', '箴言', 20, 27, 5, '坦白的责备，胜过暗中的爱。'),
('CNV', '箴言', 20, 27, 6, '爱你的人加的创伤是出于忠诚；恨你的人却与你连连亲吻。'),
('CNV', '箴言', 20, 27, 7, '吃饱的人连蜂房的蜜也厌恶；饥饿的人连一切苦的东西都觉得甘甜。'),
('CNV', '箴言', 20, 27, 8, '离家的人到处飘泊，好像离巢的雀鸟到处游飞一样。'),
('CNV', '箴言', 20, 27, 9, '膏油和香料使人心畅快，朋友真诚的劝勉也使人觉得甘甜。'),
('CNV', '箴言', 20, 27, 10, '你的朋友和你父亲的朋友，你都不可离弃；在你遭遇患难的日子，不可进你兄弟的家。在附近的邻舍胜过在远方的兄弟。'),
('CNV', '箴言', 20, 27, 11, '我儿，你要作智慧人，使我的心快乐，我也可以回答那羞辱我的。'),
('CNV', '箴言', 20, 27, 12, '精明人看见灾祸，就躲藏起来；愚蒙人反往前走，自取祸害。'),
('CNV', '箴言', 20, 27, 13, '谁为陌生人作保证人，就拿去谁的衣服；谁替妓女作保证人，谁就要作担保。'),
('CNV', '箴言', 20, 27, 14, '清晨起来大声为邻舍祝福的，就等于是咒诅他。'),
('CNV', '箴言', 20, 27, 15, '下大雨的时候不断滴漏；就像吵闹的妇人一样；'),
('CNV', '箴言', 20, 27, 16, '谁要拦阻她，就像拦阻风，也像右手抓油。'),
('CNV', '箴言', 20, 27, 17, '铁磨铁，磨得锋利；朋友互相切磋，才智（“才智”原文作“面”）也变得敏锐。'),
('CNV', '箴言', 20, 27, 18, '照料无花果树的，必吃树上的果子；事奉主人的，必得尊荣。'),
('CNV', '箴言', 20, 27, 19, '水怎样映照人面，人的心思也怎样反映其人。'),
('CNV', '箴言', 20, 27, 20, '阴间和灭亡不会满足，人的眼目也是一样。'),
('CNV', '箴言', 20, 27, 21, '用锅炼银，用炉炼金；人的称赞也试炼人。'),
('CNV', '箴言', 20, 27, 22, '你虽然用杵把愚妄人与碎谷一同捣在臼中，他的愚妄还是离不了他。'),
('CNV', '箴言', 20, 27, 23, '你要清楚知道你羊群的景况，专心照料你的牛群。'),
('CNV', '箴言', 20, 27, 24, '因为财富不是永恒的，冠冕也不能存到万代。'),
('CNV', '箴言', 20, 27, 25, '干草割去，嫩草又出现，山上的野草也都收集起来。'),
('CNV', '箴言', 20, 27, 26, '羊羔的毛可以给你作衣服，山羊可以作买田地的价银。'),
('CNV', '箴言', 20, 27, 27, '山羊奶足够作你的食物，也足够作你一家的食物，并且足够维持你众婢女的生活。'),
('CNV', '箴言', 20, 28, 1, '恶人虽然没有人追赶，仍然逃跑；义人却像狮子，放胆无惧。'),
('CNV', '箴言', 20, 28, 2, '国家因有过犯，领袖就经常更换；依赖聪明知识俱备的人，国家才可以长存。'),
('CNV', '箴言', 20, 28, 3, '穷人欺压贫寒人，就像暴雨冲没粮食。'),
('CNV', '箴言', 20, 28, 4, '离弃律法的，称赞恶人；遵守律法的，却与恶人相争。'),
('CNV', '箴言', 20, 28, 5, '坏人不知公正是什么，寻求主的却完全明白。'),
('CNV', '箴言', 20, 28, 6, '行为完全的穷人，胜过行事狡诈的财主。'),
('CNV', '箴言', 20, 28, 7, '谨守训诲的，是聪明的人；与贪食的人作伴的，却使父亲蒙羞。'),
('CNV', '箴言', 20, 28, 8, '凡是藉着高息厚利增加自己财富的，就是为那恩待穷人的人积蓄。'),
('CNV', '箴言', 20, 28, 9, '转身不听训诲的，他的祷告也是可厌恶的。'),
('CNV', '箴言', 20, 28, 10, '诱惑正直人走上邪路的，必掉在自己所挖的坑里；完全人却必承受福气。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '箴言', 20, 28, 11, '财主自以为有智慧，聪明的穷人却能看透他。'),
('CNV', '箴言', 20, 28, 12, '义人得胜的时候，有极大的荣耀；恶人兴起的时候，人就躲避。'),
('CNV', '箴言', 20, 28, 13, '遮掩自己过犯的，必不亨通；承认并离弃过犯的，必蒙怜悯。'),
('CNV', '箴言', 20, 28, 14, '常存戒惧之心的，这人就为有福；心里刚硬的，必陷在祸患里。'),
('CNV', '箴言', 20, 28, 15, '残暴的统治者辖制贫民，就像吼叫的狮子，又像饥饿觅食的熊。'),
('CNV', '箴言', 20, 28, 16, '昏庸的君主必多行强暴，憎恶不义之财的，必享长寿。'),
('CNV', '箴言', 20, 28, 17, '背负流人血之罪的，必逃跑至死，人不可帮助他。'),
('CNV', '箴言', 20, 28, 18, '行为完全的，必蒙拯救；行事狡诈的，必立刻跌倒。'),
('CNV', '箴言', 20, 28, 19, '耕种自己田地的，必有充足粮食；追求虚幻的，必饱受穷乏之苦。'),
('CNV', '箴言', 20, 28, 20, '忠实的人必有大福；急于发财的，不免受罚。'),
('CNV', '箴言', 20, 28, 21, '看人的情面是不对的；但有人为了一点食物，竟然犯法。'),
('CNV', '箴言', 20, 28, 22, '吝啬（“吝啬”直译是“恶眼”）的人急切求财，却不知穷乏快要临到。'),
('CNV', '箴言', 20, 28, 23, '责备人的，终必得人喜悦，胜过那用舌头谄媚人的。'),
('CNV', '箴言', 20, 28, 24, '偷窃自己父母财物，并说：“这不是罪过”的，这人是与强盗一伙。'),
('CNV', '箴言', 20, 28, 25, '贪心的人，必引起纷争；倚靠主的，必得丰裕。'),
('CNV', '箴言', 20, 28, 26, '自恃聪明的，是愚昧人；凭着智慧行事的，必蒙拯救。'),
('CNV', '箴言', 20, 28, 27, '周济穷人的，必不致缺乏；闭眼不理他们的，必多受咒诅。'),
('CNV', '箴言', 20, 28, 28, '恶人兴起的时候，人就躲避；恶人灭亡的时候，义人就增多。'),
('CNV', '箴言', 20, 29, 1, '人屡次受责备，仍然硬着颈项，他必突然毁灭，无法挽救。'),
('CNV', '箴言', 20, 29, 2, '义人增多的时候，人民就喜乐；恶人掌权的时候，人民就叹息。'),
('CNV', '箴言', 20, 29, 3, '喜爱智慧的，使父亲喜乐；亲近妓女的，耗尽家财。'),
('CNV', '箴言', 20, 29, 4, '君王以公正使国坚立；收受贿赂的，使国覆亡。'),
('CNV', '箴言', 20, 29, 5, '谄媚邻舍的人，是在他的脚下张设网罗。'),
('CNV', '箴言', 20, 29, 6, '恶人因为过犯，陷于网罗；义人却欢呼喜乐。'),
('CNV', '箴言', 20, 29, 7, '义人关注穷人的冤情；恶人却不分辨实情。'),
('CNV', '箴言', 20, 29, 8, '好讥笑人的煽动全城骚乱，智慧人却止息众怒。'),
('CNV', '箴言', 20, 29, 9, '智慧人与愚妄人争讼，愚妄人只会咆哮或嘲笑，总不能安静。'),
('CNV', '箴言', 20, 29, 10, '好流人血的恨恶完全人，并寻索正直人的性命。'),
('CNV', '箴言', 20, 29, 11, '愚昧人把怒气尽情发泄，智慧人却抑制怒气。'),
('CNV', '箴言', 20, 29, 12, '如果掌权者听信谎言，他所有的臣仆必都是坏人。'),
('CNV', '箴言', 20, 29, 13, '世上有穷人，也有欺压人的，两者的眼睛都蒙主光照。'),
('CNV', '箴言', 20, 29, 14, '如果君王诚实地审判穷人；他的国位必永远坚立。'),
('CNV', '箴言', 20, 29, 15, '杖责和管教能使人有智慧，放纵的孩子使母亲蒙羞。'),
('CNV', '箴言', 20, 29, 16, '恶人增多的时候，过犯也必增多；义人必看见他们倾覆。'),
('CNV', '箴言', 20, 29, 17, '管教你的儿子，他必使你得安息；也必使你的心得喜乐。'),
('CNV', '箴言', 20, 29, 18, '没有启示，人民就没有法纪；遵守律法的，就为有福。'),
('CNV', '箴言', 20, 29, 19, '只用言语，不能使奴仆受管教；他虽然明白，却没有反应。'),
('CNV', '箴言', 20, 29, 20, '你见过言语急躁的人吗？愚昧人比他更有指望。'),
('CNV', '箴言', 20, 29, 21, '如果人从小娇纵仆人，结果必带来忧愁。'),
('CNV', '箴言', 20, 29, 22, '容易发怒的人，引起纷争；脾气暴烈的人，多有过犯。'),
('CNV', '箴言', 20, 29, 23, '人的骄傲必使他卑微；心里谦卑的，必得尊荣。'),
('CNV', '箴言', 20, 29, 24, '与盗贼分赃的，是恨恶自己的性命；他虽然听见要他起誓作证的声音，却不说话。'),
('CNV', '箴言', 20, 29, 25, '惧怕人的，必陷入网罗；倚靠主的，必得安全。'),
('CNV', '箴言', 20, 29, 26, '很多人求掌权者的情面，但各人的判决是出于主。'),
('CNV', '箴言', 20, 29, 27, '不义的人是义人所厌恶的；行为正直的人是恶人所厌恶的。'),
('CNV', '箴言', 20, 30, 1, '雅基的儿子亚古珥的话，是神的默示。这人对以铁，对以铁和乌甲宣讲：'),
('CNV', '箴言', 20, 30, 2, '“我比众人更愚顽，也没有聪明。'),
('CNV', '箴言', 20, 30, 3, '我没有学习智慧，也不晓得有关至圣者的知识。'),
('CNV', '箴言', 20, 30, 4, '谁升上天，又降下来呢？谁收聚风在掌中呢？谁包水在衣服里呢？谁立定地的四极呢？他的名字叫什么？他儿子的名字叫什么？你知道吗？'),
('CNV', '箴言', 20, 30, 5, '神所说的话句句都是炼净的，投靠他的，他就作他们的盾牌。'),
('CNV', '箴言', 20, 30, 6, '他的话语，你不可增添；恐怕他责备你，你就表明是说谎的。'),
('CNV', '箴言', 20, 30, 7, '我有两件事求你，在我死去以前，求你答应我。'),
('CNV', '箴言', 20, 30, 8, '求你使虚假和谎言远离我；不要使我贫穷，也不要使我富裕，只要给我需用的食物。'),
('CNV', '箴言', 20, 30, 9, '免得我吃饱了，就不认你，说：‘主是谁？’又恐怕我贫穷，就偷窃，污渎了我神的名。'),
('CNV', '箴言', 20, 30, 10, '“不要向主人诽谤他的仆人，恐怕他咒诅你，你就判为有罪。'),
('CNV', '箴言', 20, 30, 11, '有一种人（“有一种人”直译是“有一世代”）咒诅父亲，又不给母亲祝福。'),
('CNV', '箴言', 20, 30, 12, '有一种人自以为清洁，却没有洗去自己的污秽。'),
('CNV', '箴言', 20, 30, 13, '有一种人眼目多么高傲，他们的眼睛，长在顶上。'),
('CNV', '箴言', 20, 30, 14, '有一种人牙如剑，齿如刀，要吞灭地上的困苦人和世人中的贫穷人。'),
('CNV', '箴言', 20, 30, 15, '水蛭有两个女儿，常说：‘给我！给我！’不知足的东西有三样，连总不说‘够了’的共有四样，'),
('CNV', '箴言', 20, 30, 16, '就是阴间、不能生育的妇人、水源不足之地和总不说‘够了’的火。'),
('CNV', '箴言', 20, 30, 17, '嘲笑父亲，藐视年老母亲的，他的眼必被谷中的乌鸦啄出来，给雏鹰所吃。'),
('CNV', '箴言', 20, 30, 18, '我测不透的奇事有三样，连我不知道的，共有四样：'),
('CNV', '箴言', 20, 30, 19, '就是鹰在空中飞翔之道，蛇在磐石上爬行之道，船在海中航行之道，男与女交合之道。'),
('CNV', '箴言', 20, 30, 20, '淫妇的行径是这样的：她吃了，把嘴一抹，就说：‘我没有作错事。’'),
('CNV', '箴言', 20, 30, 21, '使地震动的事有三样，连地也担当不起的，共有四样：'),
('CNV', '箴言', 20, 30, 22, '就是奴仆作王，愚顽人吃得饱，'),
('CNV', '箴言', 20, 30, 23, '被人厌恶的女子出嫁，婢女接替主母的地位。'),
('CNV', '箴言', 20, 30, 24, '地上有四样小东西，非常聪明：'),
('CNV', '箴言', 20, 30, 25, '蚂蚁是微小的昆虫，却能在夏天预备粮食。'),
('CNV', '箴言', 20, 30, 26, '石貛并不是强壮的动物，却能在岩石中做窟。'),
('CNV', '箴言', 20, 30, 27, '蝗虫没有君王，却能成群列队出发。'),
('CNV', '箴言', 20, 30, 28, '壁虎虽可以用手捕捉，却住在王宫中。'),
('CNV', '箴言', 20, 30, 29, '步伐威武的东西有三样，连行走威武的，共有四样：'),
('CNV', '箴言', 20, 30, 30, '就是在百兽中最威猛的狮子，它面对任何野兽，也不会退缩；'),
('CNV', '箴言', 20, 30, 31, '还有高视阔步的（“高视阔步的”原文作“束着腰的”，意义隐晦；现参古译本改译。）雄鸡和公山羊，以及率领军兵的君王。'),
('CNV', '箴言', 20, 30, 32, '如果你行事愚昧，自高自大，或是心怀恶计，就要用手掩口。'),
('CNV', '箴言', 20, 30, 33, '搅动牛乳必生出奶酪，紧压鼻子必压出血来，激起怒气必产生纷争。”'),
('CNV', '箴言', 20, 31, 1, '利慕伊勒王的话，是神的默示，是他母亲教训他的：'),
('CNV', '箴言', 20, 31, 2, '“我儿，我腹中生的儿啊！我许愿所得的儿啊，我要对你说什么呢？'),
('CNV', '箴言', 20, 31, 3, '不要把你的精力给妇女，也不要有败坏君王的行为。'),
('CNV', '箴言', 20, 31, 4, '利慕伊勒啊！君王不可喝酒；君王千万不可喝酒；掌权的不可贪饮烈酒。'),
('CNV', '箴言', 20, 31, 5, '恐怕喝了酒，就忘记律例，把困苦人的一切案件都颠倒了。'),
('CNV', '箴言', 20, 31, 6, '要把烈酒给将要灭亡的人喝；把酒给心里愁苦的人喝；'),
('CNV', '箴言', 20, 31, 7, '让他喝了，就忘记自己的贫穷，也不再记念自己的烦恼。'),
('CNV', '箴言', 20, 31, 8, '你要为不能自辩的人开口说话，为所有贫苦的人伸冤。'),
('CNV', '箴言', 20, 31, 9, '你要开口说话，秉公审判，为困苦和穷乏的人伸冤。”'),
('CNV', '箴言', 20, 31, 10, '有才德的妻子，谁能得着呢？她的价值远胜过红宝石。'),
('CNV', '箴言', 20, 31, 11, '她丈夫心里倚靠她，就不会缺少收入。'),
('CNV', '箴言', 20, 31, 12, '她一生的年日，只带给丈夫益处，没有害处。'),
('CNV', '箴言', 20, 31, 13, '她搜求羊毛和细麻，乐意亲手作工。'),
('CNV', '箴言', 20, 31, 14, '她好像一队商船，从远方运来食物。'),
('CNV', '箴言', 20, 31, 15, '天还未亮，她就起来，把食物分给家人，把当作的工分派众婢女。'),
('CNV', '箴言', 20, 31, 16, '她选择了一块田，就把它买下来，用自己双手赚得的收入栽种葡萄园。'),
('CNV', '箴言', 20, 31, 17, '她以能力束腰，使自己的膀臂有力。'),
('CNV', '箴言', 20, 31, 18, '她知道自己的经营获利，她的灯终夜不灭。'),
('CNV', '箴言', 20, 31, 19, '她伸手拿着卷线竿，手掌握着纺锤。'),
('CNV', '箴言', 20, 31, 20, '她张手周济困苦人，伸手帮助穷乏人。'),
('CNV', '箴言', 20, 31, 21, '她不因下雪为自己的家人担心，因为她全家都穿着温暖的朱红色衣服。'),
('CNV', '箴言', 20, 31, 22, '她为自己做床毯，她的衣服是细麻和紫色布料做的。'),
('CNV', '箴言', 20, 31, 23, '她丈夫与本地的长老在城门口同坐，是众人都认识的。'),
('CNV', '箴言', 20, 31, 24, '她做细麻布衣服出售，又供应腰带给商人。'),
('CNV', '箴言', 20, 31, 25, '她以能力和威仪为衣服，想到日后的幸福就欢笑。'),
('CNV', '箴言', 20, 31, 26, '她开口就说出智慧的话；她的舌头上充满慈爱的训诲。'),
('CNV', '箴言', 20, 31, 27, '她监管一切家务，从不白吃闲饭。'),
('CNV', '箴言', 20, 31, 28, '她的儿女都起来称她是有福的，她的丈夫也称赞她，说：'),
('CNV', '箴言', 20, 31, 29, '“有才德的女子很多，但你比她们更超卓。”'),
('CNV', '箴言', 20, 31, 30, '艷丽是虚假的，美容是虚浮的；唯有敬畏主的妇女，必得称赞。'),
('CNV', '箴言', 20, 31, 31, '愿她享受自己手所作的成果；愿她的工作在城门口使她受称赞。'),
('CNV', '传道书', 21, 1, 1, '以下是传道者，就是在耶路撒冷作王、大卫的儿子所说的话。'),
('CNV', '传道书', 21, 1, 2, '传道者说：虚空的虚空。虚空的虚空，一切都是虚空。'),
('CNV', '传道书', 21, 1, 3, '人的一切劳碌，就是他在日光之下的劳碌，对自己有什么益处呢？'),
('CNV', '传道书', 21, 1, 4, '一代过去，一代又来，地却永远存在。'),
('CNV', '传道书', 21, 1, 5, '太阳升起，太阳落下，匆忙回到它上升之处。'),
('CNV', '传道书', 21, 1, 6, '风向南刮，又往北转，循环周行，旋转不息。'),
('CNV', '传道书', 21, 1, 7, '江河向海里流，海却不满溢；江河之水归回本源，循环流转。'),
('CNV', '传道书', 21, 1, 8, '万事都令人厌倦，人说，说不尽；眼看，看不饱；耳听，听不足。'),
('CNV', '传道书', 21, 1, 9, '已有的事必再有，作过的事必再作；日光之下并无新事。'),
('CNV', '传道书', 21, 1, 10, '有什么事人可以说：“看啊！这是新的”？其实，很久之前已经有了，在我们之前早就有了。'),
('CNV', '传道书', 21, 1, 11, '以前的事，无人记念；将来的事，后来的人也不追忆。'),
('CNV', '传道书', 21, 1, 12, '那时，我传道者在耶路撒冷作以色列的王。'),
('CNV', '传道书', 21, 1, 13, '我曾用智慧专心寻求查究天下所发生的一切事；原来神给予世人的，是劳苦的担子，叫他们为此烦恼。'),
('CNV', '传道书', 21, 1, 14, '我看过日光之下所发生的一切事，不料，一切都是虚空，都是捕风。'),
('CNV', '传道书', 21, 1, 15, '弯曲的，不能弄直；缺少的，不能数算。'),
('CNV', '传道书', 21, 1, 16, '我自己心里说：“我得了极大的智慧，胜过所有在我以前统治耶路撒冷的人；我见识了许多智慧与知识。”'),
('CNV', '传道书', 21, 1, 17, '我又专心究察智慧和知识，狂妄和愚昧，才知道这也是捕风。'),
('CNV', '传道书', 21, 1, 18, '因为多有智慧，就多有烦恼；加增知识，就加增痛苦。'),
('CNV', '传道书', 21, 2, 1, '我自己心里说：“来吧，我用享乐试试你，让你看看有什么好处。”想不到，这也是虚空。'),
('CNV', '传道书', 21, 2, 2, '对嬉笑，我说：“那是狂妄”；对享乐，我说：“这有什么作用呢？”'),
('CNV', '传道书', 21, 2, 3, '我心里筹思，怎样用酒使我的身体畅快，又保持愚昧，但我的内心仍由智慧引导；直到我看明世人，在诸天之下一生有限的年日中所行的，对他们有益的是什么。'),
('CNV', '传道书', 21, 2, 4, '我大事发展：为自己建造房屋，栽种葡萄园，'),
('CNV', '传道书', 21, 2, 5, '修造园囿和庭园，在园中栽种各类果树，'),
('CNV', '传道书', 21, 2, 6, '挖造水池，用来浇灌培植树木的林园。'),
('CNV', '传道书', 21, 2, 7, '我买了仆婢，也有生在家中的奴仆；又拥有大群牛羊，胜过任何比我先在耶路撒冷的人所拥有的。'),
('CNV', '传道书', 21, 2, 8, '我又为自己积蓄金银，以及列王和各省的财宝。我又为自己招募男女歌手，收纳许多妃嫔，是世人所以为乐的。'),
('CNV', '传道书', 21, 2, 9, '于是我就日渐昌大，超过任何比我先在耶路撒冷的人；我的智慧仍然与我同在。'),
('CNV', '传道书', 21, 2, 10, '我眼中所求的，我都不禁止；我心所喜欢的，我都没抑制。我的心因我的一切劳碌而快乐，这就是我从一切劳碌中所得的分。'),
('CNV', '传道书', 21, 2, 11, '然后，我省察我手所作的一切，和我劳碌所成就的，想不到一切都是虚空，都是捕风，在日光之下毫无益处。'),
('CNV', '传道书', 21, 2, 12, '我转过来观察智慧、狂妄和愚昧。王的继承人还能作什么呢？只不过作先前作过的罢了。'),
('CNV', '传道书', 21, 2, 13, '于是我看出智慧胜过愚昧，如同光明胜过黑暗一样。'),
('CNV', '传道书', 21, 2, 14, '智慧人的眼目明亮，愚昧人却走在黑暗中。我也知道同一的命运要临到这两种人身上。'),
('CNV', '传道书', 21, 2, 15, '我自己心里说：“临到愚昧人身上的，也必临到我身上；那么，我为什么要更有智慧呢？”于是我心里说：“这也是虚空。”'),
('CNV', '传道书', 21, 2, 16, '因为智慧人和愚昧人一样，没有人永远记念他们，在未来的日子里，都会被人遗忘。可叹智慧人跟愚昧人一样，终必死亡。'),
('CNV', '传道书', 21, 2, 17, '因此我恨恶生命，因为在日光之下所发生的事，都使我厌烦。一切都是虚空，都是捕风。'),
('CNV', '传道书', 21, 2, 18, '我恨恶我的一切劳碌，就是我在日光之下的劳碌，因为我不得不把劳碌的成果留给后人。'),
('CNV', '传道书', 21, 2, 19, '那人将来是智是愚，有谁晓得呢？可是他竟要掌管一切我劳碌得来的，就是我在日光之下用智慧得来的。这又是虚空。'),
('CNV', '传道书', 21, 2, 20, '于是我转念，对日光之下我所劳碌的一切，心感绝望；'),
('CNV', '传道书', 21, 2, 21, '因为人用智慧、知识和技能所劳碌得来的，却必须留给未曾劳碌的人为分。这也是虚空，是极大的憾事。'),
('CNV', '传道书', 21, 2, 22, '人的一切劳碌和操心，就是他在日光之下所劳碌的，对自己有什么益处呢？'),
('CNV', '传道书', 21, 2, 23, '其实终其一生，他的担子既痛苦又烦恼，在夜间也不能安心。这也是虚空。'),
('CNV', '传道书', 21, 2, 24, '人最好是吃喝，在自己的劳碌中自得其乐；我看这也是出于神的手。'),
('CNV', '传道书', 21, 2, 25, '离开了他（按《马索拉文本》“离开了他”作“除了我”；现参照《七十士译本》等古译本翻译），谁能有吃的呢？谁能享乐呢？'),
('CNV', '传道书', 21, 2, 26, '神把智慧、知识和喜乐赐给他所喜悦的人，却使罪人作收集和积聚的差事，把所得的归给神所喜悦的人。这也是虚空，也是捕风。'),
('CNV', '传道书', 21, 3, 1, '万事都有定期，天下万务都有定时：'),
('CNV', '传道书', 21, 3, 2, '生有时，死有时；栽种有时，拔出所种的也有时；'),
('CNV', '传道书', 21, 3, 3, '杀戮有时，医治有时；拆毁有时，建造有时；'),
('CNV', '传道书', 21, 3, 4, '哭有时，笑有时；哀恸有时，踊跃有时；'),
('CNV', '传道书', 21, 3, 5, '抛掷石头有时，堆聚石头有时；拥抱有时，避免拥抱有时；'),
('CNV', '传道书', 21, 3, 6, '寻找有时，舍弃有时；保存有时，抛弃有时；'),
('CNV', '传道书', 21, 3, 7, '撕裂有时，缝补有时；静默有时，讲话有时；'),
('CNV', '传道书', 21, 3, 8, '爱有时，恨有时；战争有时，和平有时。'),
('CNV', '传道书', 21, 3, 9, '作工的人在自己的劳碌上得到什么益处呢？'),
('CNV', '传道书', 21, 3, 10, '我看神给予世人的担子，是要他们为此烦恼。'),
('CNV', '传道书', 21, 3, 11, '他使万事各按其时，成为美好；他又把永恒的意识放在人的心里；虽然这样，人还是不能察觉神自始至终的作为。'),
('CNV', '传道书', 21, 3, 12, '我晓得人生最好是寻乐享福，'),
('CNV', '传道书', 21, 3, 13, '人人有吃有喝，在自己的一切劳碌中自得其乐；这就是神的恩赐。'),
('CNV', '传道书', 21, 3, 14, '我知道神所作的一切，都必永存，无可增添，无可减少；神这样作，为要使人在他面前存敬畏的心。'),
('CNV', '传道书', 21, 3, 15, '现在有的，先前就有；将来有的，早已有了；因为神使已过的事重新出现（“使已过的事重新出现”直译是“寻找被追赶的”）。'),
('CNV', '传道书', 21, 3, 16, '我在日光之下又看见：审判的地方有奸恶，维护公义的地方也有奸恶。'),
('CNV', '传道书', 21, 3, 17, '我自己心里说：“神必审判义人和恶人，因为各样事务、各样工作都有定时。”'),
('CNV', '传道书', 21, 3, 18, '我自己心里说：“至于世人，神要试验他们，使他们看见自己与牲畜无异。'),
('CNV', '传道书', 21, 3, 19, '因为世人所遭遇的与牲畜所遭遇的，都是一样：这个怎样死，那个也怎样死，两者的气息都是一样，所以人并不胜于牲畜。一切都是虚空。'),
('CNV', '传道书', 21, 3, 20, '大家都到一个地方去，都出于尘土，也都归回尘土。'),
('CNV', '传道书', 21, 3, 21, '有谁知道人的灵是往上升，牲畜的魂（“魂”的原文与“灵”〔3:21〕和“气息”〔3:19〕相同）是下降而入地呢？”'),
('CNV', '传道书', 21, 3, 22, '因此我看人最好是在自己所作的事上自得其乐，因为这也是他的分；谁能使他看见他自己死后的事呢？'),
('CNV', '传道书', 21, 4, 1, '我又看见日光之下所发生一切欺压的事：受欺压的流泪，却无人安慰他们；欺压他们的，手里握着权柄，因此无人安慰受欺压的。'),
('CNV', '传道书', 21, 4, 2, '我赞叹那已死的人，胜过那还活着的人。'),
('CNV', '传道书', 21, 4, 3, '那还没生下来的，就是还没看过日光之下所行的恶事的，比这两种人更有福。'),
('CNV', '传道书', 21, 4, 4, '我看见各样的劳碌和各样精巧的工作，都是出于人与人彼此的竞争。这也是虚空，也是捕风。'),
('CNV', '传道书', 21, 4, 5, '愚昧人抱着手，吃自己的肉。'),
('CNV', '传道书', 21, 4, 6, '一掌盛满安宁，胜过两手抓满劳碌捕风。'),
('CNV', '传道书', 21, 4, 7, '我又看到日光之下有一件虚空的事。'),
('CNV', '传道书', 21, 4, 8, '有人孤单无依，没有儿子，没有兄弟，仍劳碌不休，眼目也不以自己的财富为足。他问：“我劳劳碌碌，刻薄自己不去享受，是为谁呢？”这也是虚空，是劳苦的担子。'),
('CNV', '传道书', 21, 4, 9, '二人胜过一人，因为他们一起的劳碌有美好的酬报。'),
('CNV', '传道书', 21, 4, 10, '如果一个跌倒，另一个可以把他的同伴扶起来。但一人孤身跌倒，没有别人把他扶起来，他就悲惨了。'),
('CNV', '传道书', 21, 4, 11, '还有，二人同睡，就都暖和；一人独睡，怎能暖和呢？'),
('CNV', '传道书', 21, 4, 12, '有人能制伏孤身一人，如果有二人就挡得住他。三股合成的绳子，不容易扯断。'),
('CNV', '传道书', 21, 4, 13, '贫穷但有智慧的年轻人，胜过年老不再纳谏的愚昧王。'),
('CNV', '传道书', 21, 4, 14, '虽然他是从监狱出来，在自己的国中，又是出身贫寒，却起来作王。'),
('CNV', '传道书', 21, 4, 15, '我看见所有在日光之下行走的活人，都随从那取代老王的年轻人（“那取代老王的年轻人”或译：“那取代他的第二位年轻人”）。'),
('CNV', '传道书', 21, 4, 16, '所有的人民，就是他所统治的人民，多得无数；然而后来的人却不喜欢他。这实在也是虚空，也是捕风。'),
('CNV', '传道书', 21, 5, 1, '你到神的殿，脚步要谨慎；近前聆听，胜于愚昧人献祭，因为他们不知道所作的是恶的。（本节在《马索拉文本》为4:17）'),
('CNV', '传道书', 21, 5, 2, '在神面前不可冒失开口，心急发言，因为神在天上，你在地上，所以你的言语要寡少。（本节在《马索拉文本》为5:1）'),
('CNV', '传道书', 21, 5, 3, '挂虑多就令人作梦，言语多就显出愚昧。'),
('CNV', '传道书', 21, 5, 4, '你向神许了愿，就不可迟迟不还，因为他不喜悦愚昧人；所许的愿必须偿还。'),
('CNV', '传道书', 21, 5, 5, '许愿不还，不如不许。'),
('CNV', '传道书', 21, 5, 6, '不可任你的口使自己犯罪，也不可在使者前面说是许错了。何必使神因你的声音发怒，破坏你手中的工作呢？'),
('CNV', '传道书', 21, 5, 7, '多梦和多话，都是虚空的，你只要敬畏神。'),
('CNV', '传道书', 21, 5, 8, '如果你在一省之中，看到穷人遭受欺压，公正和公义被夺去，也不必因此惊讶，因为高位者之上有较高的照应，在他们之上还有更高的。'),
('CNV', '传道书', 21, 5, 9, '各人都从土地得着利益，就是君王也得到田地的供应。'),
('CNV', '传道书', 21, 5, 10, '贪爱银子的，不因有银子满足；贪爱财富的，也不因得利知足。这也是虚空。'),
('CNV', '传道书', 21, 5, 11, '财物增加，吃用的人也增加，物主除了眼看以外，还有什么益处呢？'),
('CNV', '传道书', 21, 5, 12, '劳力的人无论吃多吃少，都睡得甜；财主的丰足，却不容他安睡。'),
('CNV', '传道书', 21, 5, 13, '我看见日光之下有一令人痛心的憾事，就是财主积聚财富，反受其害。'),
('CNV', '传道书', 21, 5, 14, '遭遇祸患，财富就尽失；他即使生了儿子，也没有什么留给他。'),
('CNV', '传道书', 21, 5, 15, '他怎样从母胎赤身而来，也必怎样赤身而去；在劳碌中得来的，他的手也带不走什么。'),
('CNV', '传道书', 21, 5, 16, '他怎样来，也要怎样去，这也是令人痛心的憾事；他为风劳碌，有什么益处呢？'),
('CNV', '传道书', 21, 5, 17, '他终生在黑暗中吃喝，多有愁烦、疾病与愤怨。'),
('CNV', '传道书', 21, 5, 18, '我认为既善又美的，就是人在神所赐给他一生有限的年日中吃喝，享受他在日光之下劳碌所得的一切，因为这是他的分。'),
('CNV', '传道书', 21, 5, 19, '蒙神赐予财富与资产的人，神都使他能够享用，并取自己的分，在劳碌中自得其乐，这是神的恩赐。'),
('CNV', '传道书', 21, 5, 20, '他不多思念自己一生的年日，因为神使喜乐充满他的心。'),
('CNV', '传道书', 21, 6, 1, '我看见日光之下有一件憾事，重压在世人身上。'),
('CNV', '传道书', 21, 6, 2, '蒙神赐予财富、资产和荣誉的人，心里所愿的，都一无所缺，可是神使他无力享用，反而有外人来享用。这是虚空，也是祸患。'),
('CNV', '传道书', 21, 6, 3, '人如果生下百子，活了许多岁数，年日长久，但是心里不因美物满足，又得不到安葬，我以为流产的胎比他还好。'),
('CNV', '传道书', 21, 6, 4, '因为这胎虚虚而来，暗暗而去，黑暗把他的名字遮蔽了。'),
('CNV', '传道书', 21, 6, 5, '这胎既看不见天日，又一无所知，就比那人更得安息。'),
('CNV', '传道书', 21, 6, 6, '那人即使活了一千年，再活一千年，也享受不到什么；他们两者不是都归一个地方吗？'),
('CNV', '传道书', 21, 6, 7, '人的一切劳碌都为口腹，他的心却还是填不满。'),
('CNV', '传道书', 21, 6, 8, '智慧人比愚昧人有什么长处呢？穷人在众人面前知道怎样行事为人，又有什么长处呢？'),
('CNV', '传道书', 21, 6, 9, '眼睛看见的，胜过心中想望的。这也是虚空，也是捕风。'),
('CNV', '传道书', 21, 6, 10, '已经存在的，早已有了名称；大家都知道人是怎样的；人绝对无法与比自己强的抗辩。'),
('CNV', '传道书', 21, 6, 11, '因为话语增多，虚空也增多，这对人有什么益处呢？'),
('CNV', '传道书', 21, 6, 12, '在虚空、消逝如影的人生，短暂的日子里，有谁知道什么是对人有益处呢？谁能告诉人他死后在日光之下会发生什么事呢？'),
('CNV', '传道书', 21, 7, 1, '美名优于美好的膏油，死亡的日子胜过诞生的日子。'),
('CNV', '传道书', 21, 7, 2, '往服丧之家，比往宴乐之家还好，因为死是人人的结局，活人要把这事放在心上。'),
('CNV', '传道书', 21, 7, 3, '忧愁胜于嬉笑，因为面带愁容，能使内心得着好处。'),
('CNV', '传道书', 21, 7, 4, '智慧人的心在服丧之家，愚昧人的心在欢乐之家。'),
('CNV', '传道书', 21, 7, 5, '听智慧人的斥责，胜过听愚昧人的歌唱。'),
('CNV', '传道书', 21, 7, 6, '愚昧人的笑声，就像锅底下荆棘的爆声一样。这也是虚空。'),
('CNV', '传道书', 21, 7, 7, '勒索会使智慧人变为愚妄，贿赂能败坏人心。'),
('CNV', '传道书', 21, 7, 8, '事情的结局胜于开端，存心忍耐的，胜过居心骄傲的。'),
('CNV', '传道书', 21, 7, 9, '你心里不要轻易动怒，因为恼怒留在愚昧人的胸怀中。'),
('CNV', '传道书', 21, 7, 10, '你不要说：“为什么从前的日子胜过现在的呢？”你这样问，不是出于智慧。'),
('CNV', '传道书', 21, 7, 11, '智慧与产业都是好的，对得见天日的人是有益的。'),
('CNV', '传道书', 21, 7, 12, '因为受智慧的庇护，如同受银子的庇护。唯有智慧能保全智慧人的生命，这就是知识的益处。'),
('CNV', '传道书', 21, 7, 13, '要观察神的作为，因为他所屈曲的，谁能弄直呢？'),
('CNV', '传道书', 21, 7, 14, '在亨通的日子，应当享福；遭遇患难的时候，就当省察。神使这两样并存，为了叫人查不出未来的事。'),
('CNV', '传道书', 21, 7, 15, '在我虚空的日子里，我见过这两件事：有义人行义反而灭亡，有恶人行恶倒享长寿。'),
('CNV', '传道书', 21, 7, 16, '不要过分公义，也不要太过有智慧，何必自取灭亡呢？'),
('CNV', '传道书', 21, 7, 17, '不要过分作恶，也不要作愚昧人，何必时候未到就死？'),
('CNV', '传道书', 21, 7, 18, '持守这个是好的，那个也不要放松，因为敬畏神的人，都必避免这两个极端。'),
('CNV', '传道书', 21, 7, 19, '智慧使智慧人比城中十个官长更有能力。'),
('CNV', '传道书', 21, 7, 20, '世上实在没有一个行善而不犯罪的义人。'),
('CNV', '传道书', 21, 7, 21, '人所说的一切话，都不要放在心上，因你可能听见仆人咒骂你。'),
('CNV', '传道书', 21, 7, 22, '其实你心里明白，自己也曾多次咒骂别人。'),
('CNV', '传道书', 21, 7, 23, '这一切我都用智慧试验过。我说：“我要得智慧”，智慧却远离我。'),
('CNV', '传道书', 21, 7, 24, '那离得远又极深奥的，谁能找到呢？'),
('CNV', '传道书', 21, 7, 25, '我转念，一心去了解、考察并寻觅智慧和事理，又要知道愚蒙是邪恶的，狂妄是愚昧的。'),
('CNV', '传道书', 21, 7, 26, '我发现一个比死亡更恶毒的妇人，她有如罗网，心如陷阱，手如锁链。蒙神喜悦的人得以摆脱她，罪人却被她缠住。'),
('CNV', '传道书', 21, 7, 27, '传道者说：“看哪！我发现了这件事，我一再揣摩，要找出事情的道理。'),
('CNV', '传道书', 21, 7, 28, '我的心仍在寻觅，却还找不到，就是在一千个男人中，我找到一个正直人，但在所有的女人中，连一个也找不到。'),
('CNV', '传道书', 21, 7, 29, '我所明白的，只有这件事：神造人原是正直的，他们却找出许多巧计。”'),
('CNV', '传道书', 21, 8, 1, '谁像智慧人，谁知道事情的解释呢？人的智慧使他容光焕发，使他脸上的戾气转消。'),
('CNV', '传道书', 21, 8, 2, '我劝你，因为你指着神起了誓，你就要遵守王的命令。'),
('CNV', '传道书', 21, 8, 3, '不要轻率离开王的面前，也不要参与恶事，因为王可以随己意作任何事。'),
('CNV', '传道书', 21, 8, 4, '既然王的话有权柄，谁敢问他：“你在作什么？”'),
('CNV', '传道书', 21, 8, 5, '遵守命令的，必不遭受灾祸；智慧人的心，晓得时机，懂得判断。'),
('CNV', '传道书', 21, 8, 6, '各样事务成就，都有合宜的时机和定局，尽管人的灾祸重压在自己身上。'),
('CNV', '传道书', 21, 8, 7, '他不晓得未来的事，将来要发生什么，谁能告诉他呢？'),
('CNV', '传道书', 21, 8, 8, '没有人能支配风，把它留住；没有人能控制死期；战争之时，没有人能免役；邪恶救不了行邪恶的人。'),
('CNV', '传道书', 21, 8, 9, '我看见了这一切，又专心查究在日光之下所发生的一切事。有这样的一个时候：有人管辖别人，叫他受害。'),
('CNV', '传道书', 21, 8, 10, '然后我看见恶人得以埋葬，他们生前在圣地往来，而在他们这样行的城中，竟被人遗忘。这也是虚空！'),
('CNV', '传道书', 21, 8, 11, '对恶行已判定的刑罚迟迟没有执行，世人的心就充满行恶的意图。'),
('CNV', '传道书', 21, 8, 12, '罪人既然作恶百次，还享长寿，那么我知道敬畏神的人，就是在他面前存敬畏的心的，必享福乐。'),
('CNV', '传道书', 21, 8, 13, '恶人却没有福乐，也得不到长寿；他好像影子的短暂，因为他在神面前不存敬畏的心。'),
('CNV', '传道书', 21, 8, 14, '在世上有一件虚空的事，就是义人照恶人所行的受报应，恶人照义人所行的得报偿。我说，这也是虚空。'),
('CNV', '传道书', 21, 8, 15, '于是我称颂快乐，因为人在日光之下最好是吃喝快乐。这是人在日光之下，神赐给他一生的年日里，从自己劳碌中所得的享受。'),
('CNV', '传道书', 21, 8, 16, '我专心认识智慧，察看世上的劳碌─有人昼夜不眠─'),
('CNV', '传道书', 21, 8, 17, '于是我看见了神的一切作为，知道在日光之下所发生的事，人不能查明；尽管人劳碌寻查，总是查不出来；即使智慧人以为知道了，还是查不出来。'),
('CNV', '传道书', 21, 9, 1, '我留心这一切事，并加以阐明：就是义人、智慧人和他们所作的，都在神手里。临到他们的一切，无论是爱是恨，人都不领悟。'),
('CNV', '传道书', 21, 9, 2, '众人的命运都是一样的：义人与恶人、好人与坏人、洁净的与不洁净的、献祭的与不献祭的，所遭遇的都是一样的；好人怎样，罪人也怎样；起誓的怎样，怕起誓的也怎样。'),
('CNV', '传道书', 21, 9, 3, '在日光之下所发生的一切事，有一件令人遗憾的，就是众人的命运都是一样的，并且世人的心充满邪恶，一生心怀狂妄，后来都归到死人那里去。'),
('CNV', '传道书', 21, 9, 4, '凡有生命的（“凡有生命的”原文作“凡与所有活人有关联的”），就有盼望，因为活狗比死狮更好。'),
('CNV', '传道书', 21, 9, 5, '活人还知道自己必死，死人却一无所知，而且再得不到酬劳，他们也被遗忘。'),
('CNV', '传道书', 21, 9, 6, '他们的爱，他们的恨，他们的嫉妒，都早已消失了，在日光之下所发生的一切事，永远也没有他们的分了。'),
('CNV', '传道书', 21, 9, 7, '你只管快快乐乐地去吃你的饭，怀着高兴的心去喝你的酒，因为神已经悦纳了你所作的。'),
('CNV', '传道书', 21, 9, 8, '你当经常穿着白色的衣袍，头上也不要缺少膏油。'),
('CNV', '传道书', 21, 9, 9, '在你一生虚空的年日中，就是神在日光之下赐你虚空的年日中，你要和你所爱的妻子享受人生，因为那是你一生在日光之下从劳碌中所得的分。'),
('CNV', '传道书', 21, 9, 10, '凡是你手可作的，都当尽力去作；因为在你所要去的阴间里，既没有工作，又没有筹谋；没有知识，也没有智慧。'),
('CNV', '传道书', 21, 9, 11, '我又看见在日光之下，跑得快的未必得奖，勇士未必战胜，智慧的未必得粮食，精明的未必致富，博学的未必得人赏识，因为时机和际遇左右众人。'),
('CNV', '传道书', 21, 9, 12, '原来人并不知道自己的时机，正像鱼被恶网圈住，鸟被网罗捉住，险恶的时机忽然临到世人身上的时候，世人也照样陷在其中。'),
('CNV', '传道书', 21, 9, 13, '在日光之下，我又看见一样智慧，觉得很有意义：'),
('CNV', '传道书', 21, 9, 14, '有一座小城，人数不多；有一个大君王来进攻，把它包围，建造巨大的高垒攻城。'),
('CNV', '传道书', 21, 9, 15, '城里有一个贫穷但有智慧的人，用他的智慧救了那城。然而，却没有人记念那穷人。'),
('CNV', '传道书', 21, 9, 16, '于是我说：“智慧胜过武力”，但是那个穷人的智慧被藐视，他的话也没有人听从。'),
('CNV', '传道书', 21, 9, 17, '听智慧人安安静静说出来的话，胜过听管理愚昧者的人的喊叫。'),
('CNV', '传道书', 21, 9, 18, '智慧胜于战斗的武器，但一个罪人能破坏许多好事。'),
('CNV', '传道书', 21, 10, 1, '几只死苍蝇能使做香料者的膏油发霉变臭，一点点愚昧比智慧和荣誉的影响更大。'),
('CNV', '传道书', 21, 10, 2, '智慧人的心向右，愚昧人的心偏左。'),
('CNV', '传道书', 21, 10, 3, '愚昧人连走路的时候，也显出无知；他对每一个人表现出他是个愚昧人（“他对每一个人表现出他是个愚昧人”或译：“他称每一个人都是愚昧的”）。'),
('CNV', '传道书', 21, 10, 4, '如果掌权者向你发怒，你不要离开原位，因为柔顺能免大过。'),
('CNV', '传道书', 21, 10, 5, '在日光之下我看见一件憾事，好像是出于官长无意的错误，'),
('CNV', '传道书', 21, 10, 6, '就是愚昧人得居众多高位，富有的人却处卑位。'),
('CNV', '传道书', 21, 10, 7, '我见过奴仆骑马，贵族却像奴仆一样在地上步行。'),
('CNV', '传道书', 21, 10, 8, '挖陷阱的，自己掉进去；拆墙垣的，有蛇来咬他。'),
('CNV', '传道书', 21, 10, 9, '采石的，被石打伤；劈柴的，被柴损害。'),
('CNV', '传道书', 21, 10, 10, '斧头若钝了，还不把斧刃磨快，就必多费力气；智慧的好处在于助人成功。'),
('CNV', '传道书', 21, 10, 11, '未行法术先被蛇咬，那么，法术对行法术的人就毫无用处。'),
('CNV', '传道书', 21, 10, 12, '智慧人的口，说出恩言；愚昧人的嘴，却吞灭自己。'),
('CNV', '传道书', 21, 10, 13, '愚昧人的话开头是愚昧，结尾是邪恶狂妄。'),
('CNV', '传道书', 21, 10, 14, '愚昧人多言多语。人不知道将来会有什么事，谁能告诉他死后会发生什么事呢？'),
('CNV', '传道书', 21, 10, 15, '愚昧人的劳碌徒使自己困乏，他连怎样进城也不知道。'),
('CNV', '传道书', 21, 10, 16, '邦国啊，如果你的王是个孩童，而你的大臣又一早吃喝宴乐，你就有祸了。'),
('CNV', '传道书', 21, 10, 17, '邦国啊，如果你的王是贵冑之子，而你的大臣又按时吃喝，为要得力，不为醉酒，你就有福了。'),
('CNV', '传道书', 21, 10, 18, '房顶塌下是因为懒惰，房屋滴漏是因为懒得动手。'),
('CNV', '传道书', 21, 10, 19, '设宴是为欢笑，酒能使人生快活，金钱能解决万事。'),
('CNV', '传道书', 21, 10, 20, '不要在意念中咒骂君王，也不要在卧房中咒骂财主，因为空中的飞鸟会传声，有翅膀的会述说这事。'),
('CNV', '传道书', 21, 11, 1, '要把你的粮食撒在水面上，因为日久你必得回。'),
('CNV', '传道书', 21, 11, 2, '你要分为七份，或分为八份，因为你不知道将来会有什么灾祸在地上发生。'),
('CNV', '传道书', 21, 11, 3, '云若充满水气，雨就倾倒在地上；树无论向南倒，或向北倒，倒在哪里，就横在哪里。'),
('CNV', '传道书', 21, 11, 4, '看风的，不撒种；观云的，不收割。'),
('CNV', '传道书', 21, 11, 5, '你不晓得风的路向，不知道骨头如何在孕妇胎中形成，照样，创造万物之神的作为，你也不得而知。'),
('CNV', '传道书', 21, 11, 6, '早晨要撒你的种，直到黄昏也不要歇手；因为你不知道哪一样种得成，是早撒的，或晚撒的，或两者都一样好。'),
('CNV', '传道书', 21, 11, 7, '光是美好的，眼睛得见天日，也是好的。'),
('CNV', '传道书', 21, 11, 8, '人无论多长寿，都当乐在其中，不过他要想到黑暗的日子，因为这些日子将会很多；要来的，都是虚空的。'),
('CNV', '传道书', 21, 11, 9, '年轻人哪！你在幼年时要快乐，在壮年的日子，要使你的心欢畅；顺着你心所愿的，眼所见的去行。不过，你要知道，为了这一切事，神必审问你。'),
('CNV', '传道书', 21, 11, 10, '所以你当除掉心中的烦恼，除去肉体的疾苦，因为无论是幼年或是壮年，都是虚空的。'),
('CNV', '传道书', 21, 12, 1, '在你壮年的日子，当记念你的创造主。不要等到衰败的日子，就是你所说：“我毫无喜乐”的那些年日临到，'),
('CNV', '传道书', 21, 12, 2, '日头、光明、月亮、星宿变暗，雨后乌云再现的时候。'),
('CNV', '传道书', 21, 12, 3, '那时，看守房子的发抖，强壮的弯腰，推磨的稀少，都停了工，往窗外看的都昏暗了，'),
('CNV', '传道书', 21, 12, 4, '当街的门口关闭，推磨的声音微弱。雀鸟一叫，人就起来。唱歌的歌声（“歌声”原文作“女子”）都低微。'),
('CNV', '传道书', 21, 12, 5, '人怕高处，怕路上有惊吓。杏树开花，蚱蜢蹒跚而行，催情果失效。因为人归他永远的家，哭丧的在街上游行。'),
('CNV', '传道书', 21, 12, 6, '银链断掉，金碗破裂，瓶子在泉旁破碎，打水的轮子在井边破烂。'),
('CNV', '传道书', 21, 12, 7, '尘土要归回原来之地，灵要归回赐灵的神。'),
('CNV', '传道书', 21, 12, 8, '传道者说：“虚空的虚空，一切都是虚空。”'),
('CNV', '传道书', 21, 12, 9, '传道者不但有智慧，还将知识教训众人；他既揣摩，又查考，也编撰了许多箴言。'),
('CNV', '传道书', 21, 12, 10, '传道者搜寻可喜悦的话，正确地写下真理。'),
('CNV', '传道书', 21, 12, 11, '智慧人的言语像刺棒，他们所汇集的箴言像钉牢的钉子，都是一位牧者所赐的。'),
('CNV', '传道书', 21, 12, 12, '我儿，还有，你当受劝勉：著书多，没有穷尽；读书多，身体疲倦。'),
('CNV', '传道书', 21, 12, 13, '你们一切都听见了，总而言之，应当敬畏神，谨守他的诫命，因为这是每一个人的本分。'),
('CNV', '传道书', 21, 12, 14, '人所作的每一件事，连一切隐藏的事，无论是善是恶，神都必审问。'),
('CNV', '雅歌', 22, 1, 1, '所罗门的歌，是歌中之歌。'),
('CNV', '雅歌', 22, 1, 2, '愿他用口中的热吻与我亲嘴，因为你的热爱比酒更美。'),
('CNV', '雅歌', 22, 1, 3, '你的膏油香气芬芳；你的名字如同倒出来的膏油；所以众童女都爱你。'),
('CNV', '雅歌', 22, 1, 4, '愿你吸引我，我们必快跑跟随你。王领我进入他的内室。王啊！我们要因你欢喜快乐；我们要提说你的爱，胜过提说美酒；她们爱你是合理的。'),
('CNV', '雅歌', 22, 1, 5, '耶路撒冷的众女子啊！我虽然黑，却是秀美，如同基达的帐棚，好像所罗门的幔幕。'),
('CNV', '雅歌', 22, 1, 6, '你们不要因为我黑，就盯着我，因为太阳把我晒黑了。我母亲的儿子生我的气；他们叫我看守家里的葡萄园，我自己私人的葡萄园，我却没有看守。'),
('CNV', '雅歌', 22, 1, 7, '我心所爱的啊！求你告诉我，你在哪里放羊？中午你在哪里使羊群躺卧休息。我为什么在你众同伴的羊群旁边，好像蒙着脸的女人呢？'),
('CNV', '雅歌', 22, 1, 8, '你这女子中最美丽的啊！你若不知道，可以出去，跟随羊群的脚踪，在牧人的帐棚边，牧放你的山羊羔。'),
('CNV', '雅歌', 22, 1, 9, '我的佳偶啊！我把你比作套在法老车上的骏马。'),
('CNV', '雅歌', 22, 1, 10, '你的两腮因耳环显得秀丽；你的颈项因珠链显得华美。'),
('CNV', '雅歌', 22, 1, 11, '我们要为你制金耳环，用银珠点缀。'),
('CNV', '雅歌', 22, 1, 12, '王正坐席的时候，我的哪哒香膏散发芬芳的香味，'),
('CNV', '雅歌', 22, 1, 13, '我以我的良人为一袋没药，挂在我的胸怀之中。'),
('CNV', '雅歌', 22, 1, 14, '我以我的良人为一束凤仙花，开放在隐．基底的葡萄园里。'),
('CNV', '雅歌', 22, 1, 15, '我的佳偶啊！你很美丽；你很美丽。你的眼好像鸽子的眼睛。'),
('CNV', '雅歌', 22, 1, 16, '我的良人，你很英俊，你很可爱。我们的床榻是青绿的树木；'),
('CNV', '雅歌', 22, 1, 17, '我们房屋的栋梁是香柏树，房屋的椽子是松树。'),
('CNV', '雅歌', 22, 2, 1, '我是沙仑平原的水仙花，是谷中的百合花。'),
('CNV', '雅歌', 22, 2, 2, '我的佳偶在女子中，正像荆棘里的百合花。'),
('CNV', '雅歌', 22, 2, 3, '我的良人在男子中，好像树林里的一棵苹果树；我欢欢喜喜地坐在它的荫下，它的果子香甜合我口味。'),
('CNV', '雅歌', 22, 2, 4, '他带我进入酒室，含情脉脉地望着我。'),
('CNV', '雅歌', 22, 2, 5, '求你们用葡萄饼增补我力，用苹果恢复我的精神，因为我因爱成病。'),
('CNV', '雅歌', 22, 2, 6, '他的左手托住我的头，他的右手拥抱着我。'),
('CNV', '雅歌', 22, 2, 7, '耶路撒冷的众女子啊！我指着田野的羚羊、母鹿恳求你们，不要激动，不要挑动爱情，等它自发吧。'),
('CNV', '雅歌', 22, 2, 8, '听啊！这是我良人的声音，他蹿山越岭而来。'),
('CNV', '雅歌', 22, 2, 9, '我的良人像羚羊，像小鹿。看哪！他站在我们的墙后；从窗口观看，从窗格往里面探视。'),
('CNV', '雅歌', 22, 2, 10, '我的良人对我说：“我的佳偶啊！你起来吧。我的佳丽啊！你来吧。'),
('CNV', '雅歌', 22, 2, 11, '因为冬天已过，雨水止息，已经过去了。'),
('CNV', '雅歌', 22, 2, 12, '地上百花齐放，百鸟齐鸣的时候已经来到；斑鸠的声音在我们境内也听见了。'),
('CNV', '雅歌', 22, 2, 13, '无花果树的果子渐渐成熟，葡萄树开花发香，我的佳偶啊！你起来吧。我的佳丽啊！你来吧。'),
('CNV', '雅歌', 22, 2, 14, '我的鸽子啊！在岩石的穴中，在悬崖石的隐密处，让我看看你的容貌；让我听听你的声音；因为你的声音甜美，你的容貌秀丽。'),
('CNV', '雅歌', 22, 2, 15, '要为我们捉拿狐狸，就是毁坏葡萄园的小狐狸，因为我们的葡萄园正在开花。”'),
('CNV', '雅歌', 22, 2, 16, '我的良人属我，我也属他，他在百合花中细赏。'),
('CNV', '雅歌', 22, 2, 17, '我的良人啊！等到天起凉风，日影消逝的时候，愿你归来，好像崎岖山上的羚羊或是小鹿。'),
('CNV', '雅歌', 22, 3, 1, '我夜间躺在床上，寻找我心所爱的，我寻找他，却找不到他。'),
('CNV', '雅歌', 22, 3, 2, '我说：“我要起来，走遍全城，在街上，在广场上，寻找我心所爱的。”我寻找他，却找不到他。'),
('CNV', '雅歌', 22, 3, 3, '城中的守卫巡逻的时候，找着我；我就问他们：“你们有没有看见我心所爱的？”'),
('CNV', '雅歌', 22, 3, 4, '我刚刚离开他们，就遇见我心所爱的；我把他拉住，不让他走，等到我带他到我母亲的家，进到怀我者的内室。'),
('CNV', '雅歌', 22, 3, 5, '耶路撒冷的众女子啊！我指着羚羊、田间的母鹿恳求你们，不要激动，不要挑动爱情，等它自发吧。'),
('CNV', '雅歌', 22, 3, 6, '那从旷野上来，好像烟柱；用商人贩卖的各种香粉、没药和乳香薰过的，是谁呢？'),
('CNV', '雅歌', 22, 3, 7, '看哪！是所罗门的御轿，四周有六十个勇士，都是以色列中的勇士。'),
('CNV', '雅歌', 22, 3, 8, '个个手拿武器，能征惯战；各人腿上配有利剑，以防夜间的袭击。'),
('CNV', '雅歌', 22, 3, 9, '所罗门王用黎巴嫩木，为自己做了一乘华轿。'),
('CNV', '雅歌', 22, 3, 10, '他用银子做轿柱，用金子做轿底，用紫色料子做轿的座垫；内部所铺设的，是耶路撒冷众女子的爱情。'),
('CNV', '雅歌', 22, 3, 11, '锡安的众女子啊！你们出来看看所罗门戴着的冠冕，就是在他结婚的日子，在他心里喜乐的时候，他母亲给他戴上的。'),
('CNV', '雅歌', 22, 4, 1, '我的佳偶啊！你很美丽；你很美丽。你的眼在面纱后面好像鸽子的眼睛；头发如同从基列山下来的山羊群。'),
('CNV', '雅歌', 22, 4, 2, '你的牙齿像新剪毛的一群母羊，刚刚洗净那样洁白整齐；它们成双成对，没有单独一只的。'),
('CNV', '雅歌', 22, 4, 3, '你的嘴唇像一条朱红线，你的小嘴美丽；你的两颊在面纱后面，如同切开的石榴。'),
('CNV', '雅歌', 22, 4, 4, '你的颈项像大卫的城楼，建造得十分整齐、雅观；其上悬挂着一千个盾牌，都是勇士的武器。'),
('CNV', '雅歌', 22, 4, 5, '你的两乳像双生的母羚羊，是在百合花中吃草的一对小鹿。'),
('CNV', '雅歌', 22, 4, 6, '等到晚风徐来，日影消逝的时候，我要亲自到没药山，要往乳香冈去。'),
('CNV', '雅歌', 22, 4, 7, '我的佳偶啊！你全然美丽，毫无瑕疵。'),
('CNV', '雅歌', 22, 4, 8, '我的新妇啊！与我同去黎巴嫩山。与我前往黎巴嫩山。从亚玛拿山顶，从示尼珥和黑门山顶，从狮子洞，从豹子山俯望。'),
('CNV', '雅歌', 22, 4, 9, '我的妹妹，我的新妇啊！你夺去了我的心。你用你的眼神、用你项链上的一颗珍珠夺去了我的心。'),
('CNV', '雅歌', 22, 4, 10, '我的妹妹，我的新妇啊！你的爱情多么美丽。你的爱情比酒更好。你膏油的香气胜过一切香料。'),
('CNV', '雅歌', 22, 4, 11, '我的新妇啊！你的嘴唇滴蜜，好像蜂房滴蜜；你的舌下有蜜有奶；你衣服的香气好像黎巴嫩山的香气。'),
('CNV', '雅歌', 22, 4, 12, '我的妹妹，我的新妇，是上了闩的园子，是上了锁的水井，是封闭了的泉源。'),
('CNV', '雅歌', 22, 4, 13, '你所栽种的是一所石榴园，有极美的果子，有凤仙花和哪哒树。'),
('CNV', '雅歌', 22, 4, 14, '有哪哒和番红花，菖蒲和肉桂，以及各种乳香树、没药和沉香，与各样精选的香料。'),
('CNV', '雅歌', 22, 4, 15, '你是园中的泉源，是活水的井，是从黎巴嫩山流下来的溪水。'),
('CNV', '雅歌', 22, 4, 16, '北风啊！兴起。南风啊！吹来。吹进我的园里，让其中的香气散播出来。愿我的良人进入他自己的园中，享用他佳美的果子。'),
('CNV', '雅歌', 22, 5, 1, '我的妹妹，我的新妇啊！我进了我的园中；我采了我的没药与香料；我吃了我的蜂房与蜂蜜；我喝了我的酒和奶。朋友们！你们要开怀吃喝；亲爱的啊！你们要不醉无归。'),
('CNV', '雅歌', 22, 5, 2, '我身虽然睡卧，我心却醒。这是我的良人的声音，他敲着门说：“我的妹妹，我的佳偶，我的鸽子，我的完全人哪！求你给我开门；因为我的头满了露水，头发给夜露滴湿。”'),
('CNV', '雅歌', 22, 5, 3, '我回答：“我脱了外衣，怎能再穿上呢？我洗了脚，怎能再弄脏呢？”'),
('CNV', '雅歌', 22, 5, 4, '我的良人从门孔里伸进手来，我的心因他大为激动。'),
('CNV', '雅歌', 22, 5, 5, '我起来，要给我的良人开门；我的两手滴下没药，指头滴下没药，滴在门闩上。'),
('CNV', '雅歌', 22, 5, 6, '我亲手给我的良人开门，我的良人却已转身走了；我发现他走了，差点昏倒；我到处找他，却找不见，我呼叫他，他却不回答。'),
('CNV', '雅歌', 22, 5, 7, '城中的守卫巡逻的时候，找着我；他们打了我，伤了我；看守城墙的人夺去了我身上的外衣。'),
('CNV', '雅歌', 22, 5, 8, '耶路撒冷的众女子啊！我嘱咐你们：你们若遇见我的良人，你们要告诉他什么呢？你们要告诉他，我患了相思病。'),
('CNV', '雅歌', 22, 5, 9, '你这女子中最美丽的啊！你的良人比别人的良人有什么更可爱之处呢？你的良人比别人的良人有什么更可爱之处呢？以致你这样嘱咐我们呢？'),
('CNV', '雅歌', 22, 5, 10, '我的良人红光满面，是万人中的表表者。'),
('CNV', '雅歌', 22, 5, 11, '他的头像精金，他的头发如棕树枝厚密，像乌鸦那么黑。'),
('CNV', '雅歌', 22, 5, 12, '他的眼好像溪水旁的鸽子，在奶中洗净，塑得合式。'),
('CNV', '雅歌', 22, 5, 13, '他的两颊如香花畦，又如香草台；他的嘴唇像百合花，滴下没药汁。'),
('CNV', '雅歌', 22, 5, 14, '他的双手像金管，镶嵌着水苍玉；他的躯体如象牙块，周围包着蓝宝石。'),
('CNV', '雅歌', 22, 5, 15, '他的双腿像大理石柱，安放在精金的座上；他的容貌如黎巴嫩山，像佳美的香柏树。'),
('CNV', '雅歌', 22, 5, 16, '他的口甜蜜；他全然可爱。耶路撒冷的众女子啊！这就是我的良人，我的朋友。'),
('CNV', '雅歌', 22, 6, 1, '你这女子中极美丽的啊！你的良人到哪里去了？你的良人转到哪里去了？让我们与你去寻找他吧！'),
('CNV', '雅歌', 22, 6, 2, '我的良人下到自己的园中，下到香花畦那里，在园内细赏，采摘百合花。'),
('CNV', '雅歌', 22, 6, 3, '我属我的良人，我的良人也属我；他在百合花中细赏。'),
('CNV', '雅歌', 22, 6, 4, '我的佳偶啊！你美丽如得撒，秀丽如耶路撒冷，威武如展开旗帜的军队。'),
('CNV', '雅歌', 22, 6, 5, '请你转眼不要看我，因为你的眼使我心动！你的头发如同从基列山下来的山羊群。'),
('CNV', '雅歌', 22, 6, 6, '你的牙齿像一群母羊，刚刚洗净上来那样洁白整齐；它们成双成对，没有单独一只的。'),
('CNV', '雅歌', 22, 6, 7, '你的两颊在面纱后面，如同切开的石榴。'),
('CNV', '雅歌', 22, 6, 8, '虽有六十位王后，八十位妃嫔，并有无数的宫女；'),
('CNV', '雅歌', 22, 6, 9, '唯独我的鸽子，我的完全人，是独一的；是她母亲独一的宝贝，是生养她者的宠儿。众女子看见她，都称她为有福；王后妃嫔见了，也都赞赏她，说：'),
('CNV', '雅歌', 22, 6, 10, '“那出现如破晓的晨光，美丽如月亮，灿烂如日头，威武有如展开旗帜的军队的是谁呢？”'),
('CNV', '雅歌', 22, 6, 11, '我下到核桃园去，看看谷中青绿的植物，看看葡萄树发芽没有，石榴树开花没有；'),
('CNV', '雅歌', 22, 6, 12, '不知不觉之间，我的心把我置于我尊贵的民的车中。'),
('CNV', '雅歌', 22, 6, 13, '回来吧，回来吧，书拉密女啊！回来吧，回来吧，让我们看看你。你们为什么要看书拉密女，像看两队兵跳舞呢？（本节在《马索拉文本》为7:1）'),
('CNV', '雅歌', 22, 7, 1, '王女啊！你的脚在鞋中多么美丽；你大腿的曲线美如珠玉，是巧匠手里的杰作。（本节在《马索拉文本》为7:2）'),
('CNV', '雅歌', 22, 7, 2, '你的肚脐如圆杯，永不缺乏调和的酒；你的肚腹像一堆麦子，周围有百合花。'),
('CNV', '雅歌', 22, 7, 3, '你的两乳像一对小鹿，像双生的母羚羊。'),
('CNV', '雅歌', 22, 7, 4, '你的颈项如象牙塔；你的眼像希实本城内，巴特．拉并门旁的水池；你的鼻子好像黎巴嫩的高塔，居高临下朝着大马士革。'),
('CNV', '雅歌', 22, 7, 5, '你的头在你身上像迦密山；你头上的秀发是紫黑色的；君王的心竟给这些发绺系住了。'),
('CNV', '雅歌', 22, 7, 6, '亲爱的啊！使人喜悦的啊！你多么美丽，多么可爱。'),
('CNV', '雅歌', 22, 7, 7, '你的身量像一棵棕树；你的两乳如树上累累的果子。'),
('CNV', '雅歌', 22, 7, 8, '我说：“我要爬上这棵棕树，我要抓住它的果子。”愿你的两乳如一挂一挂的葡萄串；你鼻子的香气如苹果芬芳；'),
('CNV', '雅歌', 22, 7, 9, '你的口像美酒。书拉密女说：“直流入我良人的口里，轻轻流过唇齿之间（按照《马索拉文本》，“唇齿之间”作“睡觉人的唇”；现参照《七十士译本》等古译本翻译）。”'),
('CNV', '雅歌', 22, 7, 10, '我属我的良人，他也恋慕我。'),
('CNV', '雅歌', 22, 7, 11, '我的良人哪！来吧！让我们往田间去；让我们在凤仙花丛中过夜吧。'),
('CNV', '雅歌', 22, 7, 12, '我们早晨起来往葡萄园去，去看葡萄树发芽没有，花朵开放没有；也看看石榴开花没有。我在那里要把我的爱给你。'),
('CNV', '雅歌', 22, 7, 13, '风茄正在散发香气；在我们的门旁有各样佳美的果子，新的旧的都有。我的良人哪，这些都是我为你保存的。'),
('CNV', '雅歌', 22, 8, 1, '但愿你像我的兄弟，像吃我母亲奶的兄弟。这样，我在外面遇见你，就可以吻你，不会被人藐视。'),
('CNV', '雅歌', 22, 8, 2, '我要引领你，领你到我母亲家里去；从小她就教导我。我要给你喝石榴汁酿的香酒。'),
('CNV', '雅歌', 22, 8, 3, '他的左手托住我的头，他的右手拥抱着我。'),
('CNV', '雅歌', 22, 8, 4, '耶路撒冷的众女子啊！我恳求你们，不要激动，不要挑动爱情，等它自发吧。'),
('CNV', '雅歌', 22, 8, 5, '那从旷野上来，靠在她爱人身旁的是谁呢？我在苹果树下唤醒了你；在那里你的母亲怀了你；在那里生育你的为你受生产的痛苦。'),
('CNV', '雅歌', 22, 8, 6, '求你把我放在你心上如印记，把我带在你臂上如戳印；因为爱情像死亡一般的坚强；嫉妒如阴间一般的坚稳；它的烈焰是火的烈焰，是非常猛烈的火焰。'),
('CNV', '雅歌', 22, 8, 7, '爱情，众水不能熄灭，洪流不能淹没；如果有人拿自己家里所有的财产去换取爱情，就必被藐视。'),
('CNV', '雅歌', 22, 8, 8, '我们有一个小妹妹，她的两乳还未发育完全；有人来提亲的时候，我们当为她怎样办理呢？'),
('CNV', '雅歌', 22, 8, 9, '她若是墙，我们就要在她上面建造银塔；她若是门，我们就要用香柏木板围护她。'),
('CNV', '雅歌', 22, 8, 10, '我是墙，我的两乳像其上的塔；我在他的眼中像寻得安乐的人。'),
('CNV', '雅歌', 22, 8, 11, '所罗门在巴力．哈们有个葡萄园；他把这葡萄园租给看守的人，各人要为葡萄园所得的果子付一万一千四百克银子。'),
('CNV', '雅歌', 22, 8, 12, '我自己的葡萄园却在我面前，所罗门哪，一万一千四百克归给你，二千二百八十克归给那些看守果子的人。'),
('CNV', '雅歌', 22, 8, 13, '你这住在园中的啊！我的同伴都在细听你的声音；愿你使我也听见。'),
('CNV', '雅歌', 22, 8, 14, '我的良人哪！愿你快来，像羚羊或小鹿，在香草山上！'),
('CNV', '以赛亚书', 23, 1, 1, '在乌西雅、约坦、亚哈斯和希西家作犹大王的时候，亚摩斯的儿子以赛亚看见异象，是关于犹大和耶路撒冷的：'),
('CNV', '以赛亚书', 23, 1, 2, '诸天哪！要听。大地啊！要留心听。因为主说：“我把孩子养育，使他们成长，他们却背叛了我。'),
('CNV', '以赛亚书', 23, 1, 3, '牛认识主人，驴认识主人的槽；以色列却不认识我，我的子民不明白我。”'),
('CNV', '以赛亚书', 23, 1, 4, '嗐！犯罪的国，罪孽深重的子民，行恶的子孙，败坏的儿女！他们离弃了主，藐视以色列的圣者，他们转离了他。'),
('CNV', '以赛亚书', 23, 1, 5, '你们为什么屡次悖逆，还要受责打吗？你们整个头都受了伤，整个心都发昏了。'),
('CNV', '以赛亚书', 23, 1, 6, '从脚掌到头顶，没有一处是完全的；尽是创伤、鞭痕和流血的伤口；没有挤干净伤口，没有包扎，也没有用膏油滋润。'),
('CNV', '以赛亚书', 23, 1, 7, '你们的土地荒凉，你们的城镇被火烧毁，你们的田地，在你们面前给外族人侵吞；被外族人倾覆之后，就荒凉了。'),
('CNV', '以赛亚书', 23, 1, 8, '仅存的锡安居民（“居民”原文作“女子”），好像葡萄园中的草棚，瓜田里的茅屋，被围困的城镇。'),
('CNV', '以赛亚书', 23, 1, 9, '若不是万军之主给我们留下一些生还者，我们早已像所多玛、蛾摩拉一样了。'),
('CNV', '以赛亚书', 23, 1, 10, '你们这些所多玛的官长啊！要听主的话；你们这些蛾摩拉的人民啊！要侧耳听我们神的教训。'),
('CNV', '以赛亚书', 23, 1, 11, '主说：“你们献上众多祭物，对我有什么益处呢？公绵羊的燔祭和肥畜的脂肪，我已经够了；公牛、羊羔和公山羊的血，我都不喜悦。'),
('CNV', '以赛亚书', 23, 1, 12, '你们来朝见我的时候，谁要求你们这样践踏我的院子呢？'),
('CNV', '以赛亚书', 23, 1, 13, '不要再带没有意义的供物来了，烧献祭物的香气也是我厌恶的。我厌烦月朔、安息日和集会；作罪孽又守严肃会，是我不能容忍的。'),
('CNV', '以赛亚书', 23, 1, 14, '你们的月朔和制定的节期，我心里恨恶；它们都成了我的重担，我已承担得不耐烦了。'),
('CNV', '以赛亚书', 23, 1, 15, '所以你们张开双手的时候，我必掩眼不看你们；即使你们多多祷告，我也不听；你们的手都沾满血腥。'),
('CNV', '以赛亚书', 23, 1, 16, '你们要洗涤自己，洁净自己；从我眼前除掉你们的恶行；要停止作恶，'),
('CNV', '以赛亚书', 23, 1, 17, '学习行善，寻求公平，指责残暴的人，替孤儿伸冤，为寡妇辨屈。”'),
('CNV', '以赛亚书', 23, 1, 18, '主说：“你们来，我们彼此辩论；你们的罪虽像硃红，必变成雪白；虽红如丹颜，必白如羊毛。'),
('CNV', '以赛亚书', 23, 1, 19, '你们若愿意听从，就必得吃地上的美物；'),
('CNV', '以赛亚书', 23, 1, 20, '你们若不听从，反而悖逆，就必被刀剑吞灭。”这是主亲口说的。'),
('CNV', '以赛亚书', 23, 1, 21, '那忠贞的城，怎么会变成妓女！她从前充满公平，有公义居在其中，现在却有凶手居住。'),
('CNV', '以赛亚书', 23, 1, 22, '你的银子变成了渣滓，你的酒用水搀混。'),
('CNV', '以赛亚书', 23, 1, 23, '你的官长存心悖逆，与盗贼同伙；人都贪爱贿赂，追索私酬；他们不替孤儿伸冤，寡妇的案件也呈不到他们面前。'),
('CNV', '以赛亚书', 23, 1, 24, '因此，主万军之主，以色列的大能者说：“哎！我要向我的对头雪恨，向我的仇敌报复。'),
('CNV', '以赛亚书', 23, 1, 25, '我必把手转过来攻击你；我要炼除你的渣滓，如同用碱来炼一样，我要除去你的一切杂质。'),
('CNV', '以赛亚书', 23, 1, 26, '我必恢复你的审判官，像起初一样；也必恢复你的谋士，像起先一般；以后，你必称为公义的城、忠贞的城。”'),
('CNV', '以赛亚书', 23, 1, 27, '锡安必因公平蒙救赎，城中悔改的人也必因公义蒙救赎。'),
('CNV', '以赛亚书', 23, 1, 28, '但悖逆的和犯罪的，必一同灭亡，离弃主的，也必灭亡。'),
('CNV', '以赛亚书', 23, 1, 29, '你们必因你们所喜爱的橡树抱愧，必因你们所选择的园子蒙羞。'),
('CNV', '以赛亚书', 23, 1, 30, '因为你们必像一棵叶子凋落的橡树，又如一个缺水的园子。'),
('CNV', '以赛亚书', 23, 1, 31, '有权势的必如麻絮，他所作的好像火星；都要一同焚毁，没有人能扑灭。'),
('CNV', '以赛亚书', 23, 2, 1, '亚摩斯的儿子以赛亚得到默示，有关犹大和耶路撒冷：'),
('CNV', '以赛亚书', 23, 2, 2, '在末后的日子，主殿的山，必被坚立，超乎众山，必被高举，过于万岭；万国都要流归这山。'),
('CNV', '以赛亚书', 23, 2, 3, '必有多国的人前来，说：“来吧！我们上主的山，登雅各神的殿；他必把他的道指教我们，我们也必遵行他的路。”因为训诲必出于锡安，主的话必来自耶路撒冷。'),
('CNV', '以赛亚书', 23, 2, 4, '他要在列国施行审判，为多国的人断定是非。他们必把刀打成犁头，把矛枪打成镰刀。这国不举刀攻击那国，他们也不再学习战争。'),
('CNV', '以赛亚书', 23, 2, 5, '雅各家啊，来吧！我们要在主的光中行走！'),
('CNV', '以赛亚书', 23, 2, 6, '主啊！你离弃了你的子民雅各家，是因为他们充满了东方的迷信，和占卜的人，像非利士人一样，并且与外族人击掌交易。'),
('CNV', '以赛亚书', 23, 2, 7, '他们的地满了金银，他们的财宝没有穷尽，他们的地满了马匹，他们的车辆也无数。'),
('CNV', '以赛亚书', 23, 2, 8, '他们的地满了偶像；他们敬拜自己双手所做的，就是他们的指头所做的。'),
('CNV', '以赛亚书', 23, 2, 9, '卑贱人向偶像俯首，尊贵人也降卑，所以不可饶恕他们。'),
('CNV', '以赛亚书', 23, 2, 10, '要进入岩洞，藏在泥土中；躲避主的惊吓和他威严的荣光。'),
('CNV', '以赛亚书', 23, 2, 11, '到那日，眼目高傲的人必降卑，性情骄傲的人也必俯首，唯独主被高举。'),
('CNV', '以赛亚书', 23, 2, 12, '因为万军之主必有一日，要攻击一切骄傲的、狂妄的，和所有高抬自己的，他们都要降卑。'),
('CNV', '以赛亚书', 23, 2, 13, '又要攻击黎巴嫩所有高大的香柏树，和巴珊所有的橡树。'),
('CNV', '以赛亚书', 23, 2, 14, '又攻击所有的高山，和所有的峻岭；'),
('CNV', '以赛亚书', 23, 2, 15, '攻击每一个高台，和每一道坚固的城墙；'),
('CNV', '以赛亚书', 23, 2, 16, '攻击所有他施的船只，和所有美丽的船。'),
('CNV', '以赛亚书', 23, 2, 17, '人的高傲必变为谦虚，人的狂妄都必降为卑微，在那日，唯独主被高举。'),
('CNV', '以赛亚书', 23, 2, 18, '偶像却必全然消逝。'),
('CNV', '以赛亚书', 23, 2, 19, '主起来，使大地震动的时候，人必进入石洞，进入土穴，躲避主的惊吓和他威严的荣光。'),
('CNV', '以赛亚书', 23, 2, 20, '到那日，人必把那些自己所做、供自己敬拜的金偶像和银偶像，抛给田鼠和蝙蝠。'),
('CNV', '以赛亚书', 23, 2, 21, '这样，当主起来，大地震动的时候，他们就能进入磐石缝中和岩石隙里，躲避主的惊吓和他威严的荣光。'),
('CNV', '以赛亚书', 23, 2, 22, '你们不要倚靠世人，他的鼻孔里只有一口气息，他实在算得什么呢？'),
('CNV', '以赛亚书', 23, 3, 1, '看哪！主万军之主，快要从耶路撒冷和犹大，除掉人所倚靠的和所倚赖的，就是众人所倚靠的粮，众人所倚赖的水；'),
('CNV', '以赛亚书', 23, 3, 2, '除掉勇士和战士、审判官和先知、占卜的和长老、'),
('CNV', '以赛亚书', 23, 3, 3, '五十夫长和尊贵的人、谋士和有技艺的工人，以及精通法术的。'),
('CNV', '以赛亚书', 23, 3, 4, '我必使孩童作他们的领袖，使婴孩管辖他们。'),
('CNV', '以赛亚书', 23, 3, 5, '人民必互相压迫，人欺压人，也欺压自己的邻舍；年轻人要欺凌老年人，卑贱人必欺凌尊贵人。'),
('CNV', '以赛亚书', 23, 3, 6, '人若在父家里，拉住自己一个兄弟，说：“你有一件外衣，你就作我们的官长吧！这败落的事就归你的手处理。”'),
('CNV', '以赛亚书', 23, 3, 7, '那时，那人必高声说：“我不作医治你们的人，（“医治你们的人”直译是“包紥创伤的”）因为我家里没有粮食，也没有外衣，你们不要立我作人民的官长。”'),
('CNV', '以赛亚书', 23, 3, 8, '耶路撒冷败落，犹大倾倒，是因为他们的舌头和行为都敌对主，惹怒了他那充满荣光的眼目。'),
('CNV', '以赛亚书', 23, 3, 9, '他们面上的表情指证他们的不对；他们像所多玛一般宣扬自己的罪恶，并不隐瞒；他们有祸了，因为他们自招祸害。'),
('CNV', '以赛亚书', 23, 3, 10, '你们要告诉义人，他们必得福乐，因为他们必享自己行为所结的果子。'),
('CNV', '以赛亚书', 23, 3, 11, '恶人却有祸了，他们必遭灾难，因为他们必按自己手所作的得报应。'),
('CNV', '以赛亚书', 23, 3, 12, '至于我的子民，孩童欺压他们，妇女管辖他们；我的子民啊！那引导你们的，使你们走错了路，并且混乱了你们所走的方向。'),
('CNV', '以赛亚书', 23, 3, 13, '主起来辩论，站着审判人民。'),
('CNV', '以赛亚书', 23, 3, 14, '主必审问他子民中的长老和领袖，说：“那吞尽葡萄园的，就是你们；从贫穷人那里掠夺的，都在你们家中。”'),
('CNV', '以赛亚书', 23, 3, 15, '主万军之主说：“你们为什么压迫我的子民，搓磨贫穷人的脸呢？”'),
('CNV', '以赛亚书', 23, 3, 16, '主又说：“因为锡安的女子高傲，走路挺直颈项，媚眼看人，俏步徐行，用脚发出叮当声。'),
('CNV', '以赛亚书', 23, 3, 17, '因此，主必使锡安的女子头顶长出秃疮；主又使她们露出前额。”'),
('CNV', '以赛亚书', 23, 3, 18, '到那日，主必除掉她们华美的脚钏、发网、月牙圈、'),
('CNV', '以赛亚书', 23, 3, 19, '耳坠、手镯、蒙脸的帕子、'),
('CNV', '以赛亚书', 23, 3, 20, '头饰、脚环、华带、香盒、符囊、'),
('CNV', '以赛亚书', 23, 3, 21, '戒指、鼻环、'),
('CNV', '以赛亚书', 23, 3, 22, '美服、外衣、钱袋、'),
('CNV', '以赛亚书', 23, 3, 23, '镜子、细麻衬衣、头巾、蒙身帕子。'),
('CNV', '以赛亚书', 23, 3, 24, '必有腐臭代替馨香，绳子代替腰带，光秃代替美发，麻衣系腰代替美服，烙痕代替美貌。'),
('CNV', '以赛亚书', 23, 3, 25, '你的男丁要倒在刀下，你的勇士必死在战场。'),
('CNV', '以赛亚书', 23, 3, 26, '锡安的城门必悲哀哭号，锡安被掠夺，成了一片荒凉后，必坐在地上。'),
('CNV', '以赛亚书', 23, 4, 1, '到那日，七个女人必拉住一个男人，说：“我们吃自己的饭，穿自己的衣服；只求你让我们归在你名下，使我们的羞辱可以除掉。”'),
('CNV', '以赛亚书', 23, 4, 2, '到那日，从主那里发生的苗必华美荣耀；那地的果实成为以色列那些逃脱的人的夸耀和光荣。'),
('CNV', '以赛亚书', 23, 4, 3, '那时，锡安余剩、仍留在耶路撒冷的人，就是所有登记在耶路撒冷活人名册上的，都必称为圣。'),
('CNV', '以赛亚书', 23, 4, 4, '主要用审判的灵和焚烧的灵把锡安女子的污秽洗去，又把耶路撒冷中间的血腥洗净。'),
('CNV', '以赛亚书', 23, 4, 5, '然后，主必在锡安全山之上，并会众之上，在日间创造云和烟，夜间创造有火焰的光亮，因为在一切荣耀之上，必有遮盖。'),
('CNV', '以赛亚书', 23, 4, 6, '也必有亭子，日间可以使人得阴凉、避炎热，也可以作避难时藏身之所，或作躲避狂风暴雨之处。'),
('CNV', '以赛亚书', 23, 5, 1, '我要为我所爱的唱歌，这歌是关于他的葡萄园：我所爱的人有一个葡萄园，在肥美的山冈上。'),
('CNV', '以赛亚书', 23, 5, 2, '他把园子的泥土挖松了，捡去石头，栽种了上好的葡萄树；在园中建造了一座守望楼，又凿了一个榨酒池。他期望结出好葡萄，却结出野葡萄。'),
('CNV', '以赛亚书', 23, 5, 3, '耶路撒冷的居民和犹大人哪！现在请你们在我与我的葡萄园之间断定是非吧！'),
('CNV', '以赛亚书', 23, 5, 4, '我为我的葡萄园所作的以外，还有什么要作的呢？我期望它结出好葡萄，它为什么倒结出野葡萄呢？'),
('CNV', '以赛亚书', 23, 5, 5, '现在我告诉你们，我要怎样处理我的葡萄园：我要把它的篱笆撤去，使它被吞灭；我要把它的围墙拆毁，使它被践踏。'),
('CNV', '以赛亚书', 23, 5, 6, '我要使它荒废，不再修剪，也不再耕耘，荆棘和蒺藜却要长起来；我也要吩咐云不再降雨在园子上。'),
('CNV', '以赛亚书', 23, 5, 7, '因为万军之主的葡萄园就是以色列家，他喜悦的树就是犹大人；他期望的是公平，但看到的只是流血的事；他期望的是公义，听到的只是哀叫声。'),
('CNV', '以赛亚书', 23, 5, 8, '那些使房屋连接房屋，使田地连接田地，以致不留余地的人，有祸了！你们只可以独居在境内。'),
('CNV', '以赛亚书', 23, 5, 9, '我听闻万军之主说：“必有许多房屋变成荒凉，甚至那些又大又美的房屋也没有人居住。'),
('CNV', '以赛亚书', 23, 5, 10, '十公顷葡萄园只出二十二公升酒；二百二十公升谷种只结二十二公升粮食。”'),
('CNV', '以赛亚书', 23, 5, 11, '那些清早起来，追求浓酒，留连到晚上，以致因酒发烧的人，有祸了！'),
('CNV', '以赛亚书', 23, 5, 12, '在他们的筵席上，有琴、瑟、手鼓、笛和酒，但他们不理主的作为，也不留心他手所作的。'),
('CNV', '以赛亚书', 23, 5, 13, '所以我的人民因无知被掳去；他们的尊贵人十分饥饿；他们的群众极其干渴。'),
('CNV', '以赛亚书', 23, 5, 14, '故此，阴间扩张它的咽喉，张大它的口，没有限量；耶路撒冷城的荣耀（“荣耀”或译：“贵族”）、群众、喧嚷的人和在城中作乐的人，都要下到阴间。'),
('CNV', '以赛亚书', 23, 5, 15, '卑贱人俯首，尊贵人降卑，眼目高傲的也降卑。'),
('CNV', '以赛亚书', 23, 5, 16, '唯独万军之主，因公平被高举；至圣的神，因公义显为圣。'),
('CNV', '以赛亚书', 23, 5, 17, '那时羊羔必来吃草，像在自己的草场一样；富裕者的荒场被寄居者随意吃用。'),
('CNV', '以赛亚书', 23, 5, 18, '那些人虚假的绳索牵引罪孽，又像用车绳拉罪恶的人，有祸了！'),
('CNV', '以赛亚书', 23, 5, 19, '他们说：“愿他赶快、迅速地成就他的作为，给我们看看！愿以色列的圣者所计划的临近！愿它来到，好让我们知道！”'),
('CNV', '以赛亚书', 23, 5, 20, '那些称恶为善，称善为恶，以暗为光，以光为暗，以苦为甜，以甜为苦的人，有祸了！'),
('CNV', '以赛亚书', 23, 5, 21, '那些自以为有智慧，自视为聪明的人，有祸了！'),
('CNV', '以赛亚书', 23, 5, 22, '那些勇于喝酒，又精于调和浓酒的人，有祸了！'),
('CNV', '以赛亚书', 23, 5, 23, '他们因受了贿赂，就称恶人为义；却把义人的权益夺去。'),
('CNV', '以赛亚书', 23, 5, 24, '因此，火舌怎样吞灭碎秸，干草怎样落在火焰之中，照样，他们的根必像腐朽之物，他们的花必像尘土飞扬；因为他们弃绝万军之主的训诲，藐视以色列圣者的话。'),
('CNV', '以赛亚书', 23, 5, 25, '所以主的怒气向他的子民发作，他伸出手来击打他们，群山都震动，他们的尸体在街上好像粪土，虽然这样，他的怒气还未转消，他的手仍然伸出。'),
('CNV', '以赛亚书', 23, 5, 26, '他必竖立旗帜，招一国的人从远方而来，发出哨声把他们从地极召来；看！他们必急速快奔而来。'),
('CNV', '以赛亚书', 23, 5, 27, '他们当中没有疲倦的，没有绊倒的，没有打盹的，也没有睡觉的；他们的腰带没有放松，鞋带也没有折断。'),
('CNV', '以赛亚书', 23, 5, 28, '他们的箭锐利，所有的弓都上了弦；他们的马蹄看来像火石，车辆似旋风。'),
('CNV', '以赛亚书', 23, 5, 29, '他们的吼叫像母狮，他们的咆哮如幼狮；他们咆哮，攫取猎物，把它叼去，无人援救。'),
('CNV', '以赛亚书', 23, 5, 30, '到那日，他们要向以色列人咆哮，像海浪的澎湃声一样；人若望着这地，就只见黑暗与灾难；光在云中也成了黑暗。'),
('CNV', '以赛亚书', 23, 6, 1, '乌西雅王去世那年，我看见主坐在高高的宝座上，他的衣裳垂下，充满圣殿。'),
('CNV', '以赛亚书', 23, 6, 2, '在他上面有撒拉弗侍立，各有六个翅膀；用两个翅膀遮脸，两个翅膀遮脚，两个翅膀飞翔。'),
('CNV', '以赛亚书', 23, 6, 3, '他们彼此高呼着说：“圣哉！圣哉！圣哉！万军之主！他的荣光充满全地。”'),
('CNV', '以赛亚书', 23, 6, 4, '因呼叫者的声音，门槛的根基震撼，殿也充满了烟云。'),
('CNV', '以赛亚书', 23, 6, 5, '那时我说：“我有祸了，我灭亡了！因为我是个嘴唇不洁的人，又住在嘴唇不洁的人民中间，又因为我亲眼看见了大君王万军之主。”'),
('CNV', '以赛亚书', 23, 6, 6, '有一个撒拉弗飞到我面前，手里拿着烧红的炭，是用火钳从祭坛上取来的。'),
('CNV', '以赛亚书', 23, 6, 7, '他用炭沾我的口，说：“看哪！这炭沾了你的嘴唇，你的罪孽就除掉，你的罪恶就赦免了。”'),
('CNV', '以赛亚书', 23, 6, 8, '我又听见主的声音说：“我可以差遣谁呢？谁肯为我们去呢？”我说：“我在这里，请差遣我。”'),
('CNV', '以赛亚书', 23, 6, 9, '他说：“你去告诉这子民，说：‘你们听了又听，却不明白；看了又看，却不晓得。’'),
('CNV', '以赛亚书', 23, 6, 10, '你要使这子民的心思迟钝（“迟钝”直译是“蒙脂油”），耳朵不灵，眼睛昏暗，免得他们眼睛看见，耳朵听见，心里明白，回转过来，得到医治。”'),
('CNV', '以赛亚书', 23, 6, 11, '于是我说：“主啊，这要到几时为止呢？”他回答说：“直到城镇荒凉，无人居住；房屋空置无人，地土废弃荒凉。'),
('CNV', '以赛亚书', 23, 6, 12, '主要把人迁到远方，在这境内必有很多被撇下的地土。'),
('CNV', '以赛亚书', 23, 6, 13, '境内剩下的人，虽然只有十分之一，也必被消灭。但正如栗树和橡树，虽然被砍下，树的余干还存留在那里。这圣洁的苗裔，就是这国的余干。”'),
('CNV', '以赛亚书', 23, 7, 1, '乌西雅的孙子、约坦的儿子犹大王亚哈斯在位的日子，亚兰王利汛和利玛利的儿子以色列王比加，上来攻打耶路撒冷，却不能把它攻陷。'),
('CNV', '以赛亚书', 23, 7, 2, '有人告诉大卫家说：“亚兰已经在以法莲地安营。”王的心和人民的心就都震动，像林中的树被风摇动一样。'),
('CNV', '以赛亚书', 23, 7, 3, '主对以赛亚说：“你和你的儿子施亚雅述出去，在上池的水沟尽头，就是在漂布者田间的大路上，去迎接亚哈斯，'),
('CNV', '以赛亚书', 23, 7, 4, '对他说：‘你要谨慎，要镇定，不要因亚兰王利汛和利玛利的儿子这两个冒烟的火把头所发的怒气而害怕，也不要心里胆怯。'),
('CNV', '以赛亚书', 23, 7, 5, '因为亚兰、以法莲和利玛利的儿子，设恶谋要害你，说：'),
('CNV', '以赛亚书', 23, 7, 6, '“我们可以上去攻打犹大，扰乱她，把她攻占过来，归我们所有，又在其中立他比勒的儿子作王。”'),
('CNV', '以赛亚书', 23, 7, 7, '因此，主神这样说：“这计谋必立不住，也不能成就，'),
('CNV', '以赛亚书', 23, 7, 8, '因为亚兰的首都是大马士革，大马士革的首领是利汛；六十五年之内，以法莲必定毁灭，不再成为一族之民。'),
('CNV', '以赛亚书', 23, 7, 9, '以法莲的首都是撒玛利亚，撒玛利亚的首领是利玛利的儿子；你们若不相信，就必定不得坚立。”’”'),
('CNV', '以赛亚书', 23, 7, 10, '主又告诉亚哈斯说：'),
('CNV', '以赛亚书', 23, 7, 11, '“你向主你的神求一个兆头，或求显在深处，或求显在高处。”'),
('CNV', '以赛亚书', 23, 7, 12, '但亚哈斯说：“我不求，我不试探主。”'),
('CNV', '以赛亚书', 23, 7, 13, '以赛亚说：“大卫家啊，你们要听！你们使人厌烦还算小事，还要使我的神厌烦吗？'),
('CNV', '以赛亚书', 23, 7, 14, '因此主自己必给你们一个兆头：看哪！必有童女怀孕生子；她要给他起名叫‘以马内利’。'),
('CNV', '以赛亚书', 23, 7, 15, '到他晓得弃恶择善的时候，他必吃奶酪和蜂蜜。'),
('CNV', '以赛亚书', 23, 7, 16, '因为在这孩子晓得弃恶择善之先，你所畏惧的那两个王之地，早就被弃绝了。'),
('CNV', '以赛亚书', 23, 7, 17, '“主必使灾难的日子临到你和你的人民，以及你的父家，自从以法莲脱离犹大以来，未曾有过这样的日子，就是亚述王的入侵。”'),
('CNV', '以赛亚书', 23, 7, 18, '到那时，主必发出哨声，把埃及河流尽头的苍蝇和亚述地的蜂子召来。'),
('CNV', '以赛亚书', 23, 7, 19, '它们都必飞来，落在陡峭的山谷中、岩石的穴里、一切荆棘丛中和所有的草场上。'),
('CNV', '以赛亚书', 23, 7, 20, '到那日，主必用大河那边租来的剃刀，就是亚述王，剃去你们的头发和脚上的毛，并且剃净你们的胡须。'),
('CNV', '以赛亚书', 23, 7, 21, '到那时，一个人只能养活一头母牛犊和两只母绵羊。'),
('CNV', '以赛亚书', 23, 7, 22, '因为出的奶多，他就可以吃奶酪；境内剩下的人，都要吃奶酪和蜂蜜。'),
('CNV', '以赛亚书', 23, 7, 23, '到那日，从前种一千棵葡萄树，价值一万一千四百克银子的地方，现在却成为荆棘和蒺藜生长之处。'),
('CNV', '以赛亚书', 23, 7, 24, '人到那里去，必须携带弓和箭，因为遍地都是荆棘和蒺藜。'),
('CNV', '以赛亚书', 23, 7, 25, '以前所有用锄头挖掘的山地，你因为惧怕荆棘和蒺藜，都不敢上那里去；那里就成了放牛之地，羊群践踏之处。'),
('CNV', '以赛亚书', 23, 8, 1, '主对我说：“你拿一块大版，用通用的文字写上‘玛黑珥．沙拉勒．哈施．罢斯’（“玛黑珥．沙拉勒．哈施．罢斯”意即“赶快掳掠，急速夺取”）。'),
('CNV', '以赛亚书', 23, 8, 2, '我要叫两个诚实的见证人，就是乌利亚祭司和耶比利家的儿子撒迦利亚，来为我作见证。”'),
('CNV', '以赛亚书', 23, 8, 3, '我亲近了女先知，就是我妻子，她就怀孕生子。主对我说：“给他起名叫‘玛黑珥．沙拉勒．哈施．罢斯’，'),
('CNV', '以赛亚书', 23, 8, 4, '因为在这孩子晓得喊叫父母以先，大马士革的财宝和撒玛利亚的掳物，必在亚述王面前被搬了去。”'),
('CNV', '以赛亚书', 23, 8, 5, '主又再告诉我说：'),
('CNV', '以赛亚书', 23, 8, 6, '“这子民既然厌弃了西罗亚缓流的水，却喜悦利汛和利玛利的儿子，'),
('CNV', '以赛亚书', 23, 8, 7, '因此，主必使大河又强又大的水临到他们，就是亚述王和他一切威荣，水必涨起来，高过所有的水道；水要泛滥，漫过所有的河岸；'),
('CNV', '以赛亚书', 23, 8, 8, '然后必冲入犹大，涨溢泛滥，直到颈项，以马内利啊！它展开的翅膀必遮遍你广阔的地土。”'),
('CNV', '以赛亚书', 23, 8, 9, '列国之民啊！你们尽管作恶，但你们终必毁灭！所有在远处的人民啊，要留心听！你们尽管束腰吧，你们终必毁灭！你们尽管束腰吧，你们终必毁灭！'),
('CNV', '以赛亚书', 23, 8, 10, '你们尽管计划阴谋吧，这些终必失败；你们尽管提议吧，这些终必不能成立，因为神与我们同在。'),
('CNV', '以赛亚书', 23, 8, 11, '主以大能的手托住我，教导我不要走这子民所走的道路；他对我这样说：'),
('CNV', '以赛亚书', 23, 8, 12, '“这子民所称为阴谋的，你们都不要称为阴谋；他们所怕的，你们不要怕，也不要畏惧。'),
('CNV', '以赛亚书', 23, 8, 13, '你们要尊万军之主为圣，他是你们当怕的，也是你们当畏惧的。'),
('CNV', '以赛亚书', 23, 8, 14, '他必向信靠他的人作圣所，却向以色列两家作绊脚的石头、跌人的磐石；又向耶路撒冷的居民作陷阱和网罗。'),
('CNV', '以赛亚书', 23, 8, 15, '许多人必在其上绊跌、仆倒、跌碎，并且陷入网罗被捉住。”'),
('CNV', '以赛亚书', 23, 8, 16, '你要卷起律法书，在我的门徒中间封住训诲。'),
('CNV', '以赛亚书', 23, 8, 17, '我要等候那掩面不顾雅各家的主，我要仰视他。'),
('CNV', '以赛亚书', 23, 8, 18, '看哪！我和主赐给我的孩子，在以色列中作预兆与奇迹，都是从住在锡安山的万军之主来的。'),
('CNV', '以赛亚书', 23, 8, 19, '有人对你们说：“要求问那些交鬼的和行巫术的，就是那些喃喃细语的人。”一族之民不应当求问自己的神吗？他们怎能为活人求问死人呢？'),
('CNV', '以赛亚书', 23, 8, 20, '他们应当求问神的训诲和法度；他们若不照着这些准则说话，就见不到曙光。'),
('CNV', '以赛亚书', 23, 8, 21, '他们必经过这地，受困迫、受饥饿；他们饥饿的时候，就恼怒，咒骂自己的王和自己的神；'),
('CNV', '以赛亚书', 23, 8, 22, '他们仰脸向天观望，又俯视大地，只见困苦、黑暗、可怕的幽暗；他们必被赶入幽黑的黑暗中。'),
('CNV', '以赛亚书', 23, 9, 1, '但那受过困苦的，必不再见幽暗。以前神使西布伦和拿弗他利地被轻视，日后却要使它们在沿海之路、约旦河外和外族人的加利利，得着荣耀。（本节在《马索拉文本》为8:23）'),
('CNV', '以赛亚书', 23, 9, 2, '行在黑暗中的人民，看见了大光；住在死荫之地的人，有光照耀他们。（本节在《马索拉文本》为9:1）'),
('CNV', '以赛亚书', 23, 9, 3, '你使这国之民增多，又加添他们的欢乐；他们在你面前欢乐，好像收割时的欢乐一样；又像人在均分战利品时的快乐一般。'),
('CNV', '以赛亚书', 23, 9, 4, '因为他们所负的轭和肩头上的杖，以及欺压他们的人的棍，你都折断了，像在米甸的日子一样。'),
('CNV', '以赛亚书', 23, 9, 5, '因为战士在战争喧嚷中所穿的靴，和辊在血中的袍，都必烧毁，成了烧火的燃料。'),
('CNV', '以赛亚书', 23, 9, 6, '因为有一个婴孩为我们而生，有一个儿子赐给我们；政权必担在他的肩头上；他的名必称为“奇妙的策士、全能的神、永恒的父、和平的君”。'),
('CNV', '以赛亚书', 23, 9, 7, '他的政权与平安必无穷无尽地增加，他在大卫的宝座上治理他的国，以公平和公义使国坚立稳固，从现在直到永远。万军之主的热心必成全这事。'),
('CNV', '以赛亚书', 23, 9, 8, '主发出一个信息攻击雅各家，信息落在以色列家。'),
('CNV', '以赛亚书', 23, 9, 9, '所有的人民，就是以法莲和撒玛利亚的居民，都要知道这事；他们凭着骄傲和自大的心说：'),
('CNV', '以赛亚书', 23, 9, 10, '“砖墙倒塌了，我们就用凿好的石头来建筑；桑树砍倒了，我们就用香柏树替换。”'),
('CNV', '以赛亚书', 23, 9, 11, '因此，主必兴起利汛的敌人来攻击以色列，并且要激动以色列的仇敌。'),
('CNV', '以赛亚书', 23, 9, 12, '东有亚兰人，西有非利士人；他们张开口来要吞灭以色列。虽然这样，主的怒气还没有转消，他的手仍然伸出。'),
('CNV', '以赛亚书', 23, 9, 13, '这人民还没有回转、归向那击打他们的万军之主，也没有寻求他。'),
('CNV', '以赛亚书', 23, 9, 14, '因此，主在一日之间，必从以色列中剪除头和尾、棕枝与芦苇。'),
('CNV', '以赛亚书', 23, 9, 15, '长老和尊贵人就是头；用谎言教导人的先知就是尾。'),
('CNV', '以赛亚书', 23, 9, 16, '因为那些领导这人民的，使他们走错了路；那些被领导的，都必一片混乱。'),
('CNV', '以赛亚书', 23, 9, 17, '因此，主不喜欢他们的年轻人，也不怜恤他们的孤儿寡妇；因为他们各人都是不敬虔的，是邪恶的，各人的口都说愚昧的话。虽然这样，主的怒气还没有转消，他的手仍然伸出。'),
('CNV', '以赛亚书', 23, 9, 18, '邪恶像火一般焚烧，吞灭荆棘蒺藜，连树林中的密丛也烧起火来，它们旋转上腾，成了烟柱。'),
('CNV', '以赛亚书', 23, 9, 19, '因着万军之主的烈怒，地被烧毁，人民成了烧火的燃料一般，没有人顾惜自己的兄弟。'),
('CNV', '以赛亚书', 23, 9, 20, '有人在右边切肉，仍然饥饿；在左边吞吃，仍然不饱足；各人竟吃自己手臂的肉。'),
('CNV', '以赛亚书', 23, 9, 21, '玛拿西吞吃以法莲，以法莲吞吃玛拿西，又一起攻击犹大。虽然这样，主的怒气还没有转消，他的手仍然伸出。'),
('CNV', '以赛亚书', 23, 10, 1, '那些制定奸恶律例的，和那些记录诡诈判语的，有祸了！'),
('CNV', '以赛亚书', 23, 10, 2, '他们想藉此屈枉穷乏人的公义，剥夺我子民中困苦人的权利，使寡妇作了他们的掠物，使孤儿作了他们的掳物。'),
('CNV', '以赛亚书', 23, 10, 3, '到降罚的日子，有灾祸从远方来到，那时你们要怎样行呢？你们可以向谁逃奔求助呢？你们可以把你们的财宝撇在哪里呢？'),
('CNV', '以赛亚书', 23, 10, 4, '你们只能屈身在被掳的人中间，或是仆倒在被杀的人中间。虽然这样，主的怒气还没有转消，他的手仍然伸出。'),
('CNV', '以赛亚书', 23, 10, 5, '亚述啊！我怒气的棍子，有祸了。他们手中拿着我忿怒的杖。'),
('CNV', '以赛亚书', 23, 10, 6, '我要差派他去攻击一个不敬虔的国，吩咐他去攻击我恼怒的子民，掳去掠物，抢夺掳物，把他们践踏，像街上的泥土一样。'),
('CNV', '以赛亚书', 23, 10, 7, '但亚述并没有这样想过，他心里也没有这样打算；他心里倒想毁灭、剪除多国。'),
('CNV', '以赛亚书', 23, 10, 8, '因为他说：“在我手下的众领袖不都是王吗？'),
('CNV', '以赛亚书', 23, 10, 9, '迦勒挪不是像迦基米施吗？哈玛不是像亚珥拔吗？撒玛利亚不是像大马士革吗？'),
('CNV', '以赛亚书', 23, 10, 10, '我的手伸展到这些充满偶像的国，他们雕刻的像比耶路撒冷和撒玛利亚的还多。'),
('CNV', '以赛亚书', 23, 10, 11, '我怎样对待撒玛利亚和其中的偶像，不也照样对待耶路撒冷和其中的偶像吗？”'),
('CNV', '以赛亚书', 23, 10, 12, '主在锡安山和耶路撒冷成全了他一切工作的时候，他必说：我要惩罚亚述王自大的心所结的果子，和他眼目高傲的态度。'),
('CNV', '以赛亚书', 23, 10, 13, '因为他说：“我靠着我手的能力和我的智慧行事，因为我很聪明；我挪移了列国的地界，抢夺了他们积蓄的财宝，并且我像个勇士般使他们的居民全都俯伏下来。'),
('CNV', '以赛亚书', 23, 10, 14, '我的手伸到列国的财宝那里，好像抓到鸟窝一样；我取得了全地，好像人拾起被弃的雀蛋；没有动翅膀的，没有张嘴的，也没有鸣叫的。”'),
('CNV', '以赛亚书', 23, 10, 15, '斧头怎可以向用斧头砍木的人自夸呢？锯子怎可以向拉锯的人自大呢？好比棍能挥动那举起棍的，又好比杖举起那不是木头的。'),
('CNV', '以赛亚书', 23, 10, 16, '因此，主万军之主必打发令人消瘦的病临到亚述王肥壮的军人中间，在他的荣耀之下必燃起火焰，如同火烧一样。'),
('CNV', '以赛亚书', 23, 10, 17, '以色列的光必变成火，他的圣者必成为火焰；在一日之间把亚述王的荆棘和蒺藜焚烧与吞灭。'),
('CNV', '以赛亚书', 23, 10, 18, '又把他树林和丰盛果园的荣美全部灭尽，包括灵魂和身体，好像一个患病的人渐渐虚弱一样。'),
('CNV', '以赛亚书', 23, 10, 19, '他林中剩下的树，数目必定稀少，连小孩子也能把它们的数目写下来。'),
('CNV', '以赛亚书', 23, 10, 20, '到那日，以色列的余民和雅各家逃脱的人，必不再倚靠那击打他们的，却要诚实地倚靠主以色列的圣者。'),
('CNV', '以赛亚书', 23, 10, 21, '那些余民，就是雅各家的余民，必回转归向大能的神。'),
('CNV', '以赛亚书', 23, 10, 22, '以色列啊！你的人民虽然像海沙那样多，却只有余剩的人可以归回，因为灭绝的事已经定了，公义必如洪水泛滥。'),
('CNV', '以赛亚书', 23, 10, 23, '主万军之主必在全地之中，作成已定的毁灭之事。'),
('CNV', '以赛亚书', 23, 10, 24, '因此，主万军之主这样说：“我的子民、锡安的居民哪！亚述人虽然用棍击打你们，又像埃及一样举杖攻击你们，你们却不要怕他们。'),
('CNV', '以赛亚书', 23, 10, 25, '因为还有短暂的时候，我向你们发的恼怒就要完结，我的怒气要转向他们，使他们灭亡。”'),
('CNV', '以赛亚书', 23, 10, 26, '万军之主必兴起鞭子攻击他们，好像在俄立磐石那里击杀米甸人一样；他的杖要伸到海上，他必把杖举起，像在埃及一样。'),
('CNV', '以赛亚书', 23, 10, 27, '到那日，亚述人的重压必从你们的肩头上挪开，他们的轭必离开你们的颈项；那轭必因肥壮的缘故折断。'),
('CNV', '以赛亚书', 23, 10, 28, '亚述人来到亚叶，经过米矶仑；在密抹存放军队行装。'),
('CNV', '以赛亚书', 23, 10, 29, '他们过了隘口，在迦巴住宿；拉玛人战兢，扫罗的基比亚人逃跑。'),
('CNV', '以赛亚书', 23, 10, 30, '迦琳的居民哪，高声叫喊吧！莱煞人和可怜的亚拿突啊，留心听吧！'),
('CNV', '以赛亚书', 23, 10, 31, '玛得米那人逃跑，基柄的居民避难。'),
('CNV', '以赛亚书', 23, 10, 32, '就在今日，亚述王要停留在挪伯；他要挥拳攻击锡安居民（“居民”原文作“女子”）的山，就是耶路撒冷的山。'),
('CNV', '以赛亚书', 23, 10, 33, '看哪！主万军之主在可怕的震撼声中，把树枝削去；身量高的必被砍下，高大的必被伐倒。'),
('CNV', '以赛亚书', 23, 10, 34, '树林中的密丛，他必用铁器砍下；黎巴嫩的树木必被大能者伐倒。'),
('CNV', '以赛亚书', 23, 11, 1, '从耶西的树干必生出一根嫩芽，从他的根而出的枝条必结果子。'),
('CNV', '以赛亚书', 23, 11, 2, '主的灵必停留在他身上，就是智慧的灵和聪明的灵，谋略的灵和能力的灵，知识的灵和敬畏主的灵。'),
('CNV', '以赛亚书', 23, 11, 3, '他必以敬畏主为乐。他不凭眼睛所见的施行审判，也不凭耳朵所听的断定是非；'),
('CNV', '以赛亚书', 23, 11, 4, '却要以公义审判贫穷人，以正直判断地上的困苦人；以口中的杖击打世界，以嘴里的气杀死恶人。'),
('CNV', '以赛亚书', 23, 11, 5, '公义必作他腰间的带子，信实必作他胁下的带子。'),
('CNV', '以赛亚书', 23, 11, 6, '豺狼必与绵羊羔同住，豹子要与山羊羔同卧，牛犊、幼狮和肥畜必同群；小孩子要牵引它们。'),
('CNV', '以赛亚书', 23, 11, 7, '牛必与母熊一同吃食，牛犊必与小熊一起躺卧；狮子就像牛一般吃草。'),
('CNV', '以赛亚书', 23, 11, 8, '吃奶的婴儿必在虺蛇的洞口玩耍，断奶的孩子必放他的手在毒蛇的穴上。'),
('CNV', '以赛亚书', 23, 11, 9, '在我整个圣山上面，这一切都不行伤害或毁灭之事；因为认识主的知识要充满大地，好像海水覆盖海洋一般。'),
('CNV', '以赛亚书', 23, 11, 10, '到那日，耶西的根必竖立起来，作万族的旗帜；列国的人必寻求他，他安息之所必大有荣耀。'),
('CNV', '以赛亚书', 23, 11, 11, '到那日，主必再用自己的手，赎回他子民中的余民，就是从亚述、埃及、巴忒罗、古实、以拦、示拿和哈马，以及众海岛所剩下的。'),
('CNV', '以赛亚书', 23, 11, 12, '他必向列国竖起旗帜，召聚以色列被掳去的人，又从地的四方聚集分散了的犹大人。'),
('CNV', '以赛亚书', 23, 11, 13, '以法莲的嫉妒必消除，那敌视犹大的必被剪除；以法莲必不再嫉妒犹大，犹大也必不再敌视以法莲。'),
('CNV', '以赛亚书', 23, 11, 14, '他们要向西飞，扑在非利士人的山麓上，一起掳掠东方人；他们必把手伸到以东和摩押之上，亚扪人必顺服他们。'),
('CNV', '以赛亚书', 23, 11, 15, '主必使埃及的海湾干涸；他要用热风在大河之上挥手，他要击打它，使它分成七道支流，使人走过去也不会把鞋弄湿。'),
('CNV', '以赛亚书', 23, 11, 16, '为着神的余民，就是那些在亚述剩下归回的，必有一条大路给他们归回，正如以色列人从埃及地上来的日子一样。'),
('CNV', '以赛亚书', 23, 12, 1, '到那日，你必说：“主啊！我要称谢你，因为你虽曾向我发怒，你的怒气却已转消，你又安慰了我。'),
('CNV', '以赛亚书', 23, 12, 2, '看哪！神是我的拯救；我要倚靠他，并不惧怕，因为主神是我的力量，我的诗歌，他也成了我的拯救。”'),
('CNV', '以赛亚书', 23, 12, 3, '所以你们要快乐地从救恩的泉源打水。'),
('CNV', '以赛亚书', 23, 12, 4, '到那日，你们必说：“要称谢主，呼求他的名；在万民中传扬他的作为，使他们谨记他那至高的名。'),
('CNV', '以赛亚书', 23, 12, 5, '你们要唱歌赞美主，因为他作了极美的事；愿这事传遍全地。'),
('CNV', '以赛亚书', 23, 12, 6, '锡安的居民哪，当喊叫欢呼！因为以色列的圣者在你们中间是伟大的。”'),
('CNV', '以赛亚书', 23, 13, 1, '亚摩斯的儿子以赛亚得到关于巴比伦的默示：'),
('CNV', '以赛亚书', 23, 13, 2, '你要在光秃的山上竖起旗帜，向众人扬声挥手，叫他们进入权贵的门。'),
('CNV', '以赛亚书', 23, 13, 3, '我向我特选的军兵下了命令；我也呼召了我的勇士，就是我那些骄傲自夸的人，去执行我在怒气中所要作的。'),
('CNV', '以赛亚书', 23, 13, 4, '听啊！山上有喧哗的声音，好像是众多的人民；听啊！有多国的人的嘈杂声，好像是列国聚集在一起。万军之主正在数点军兵，预备打仗。'),
('CNV', '以赛亚书', 23, 13, 5, '他们从远地而来，从天边而来。就是主和他恼怒的工具，要毁灭这全地。'),
('CNV', '以赛亚书', 23, 13, 6, '哀号吧！因为主的日子近了，这日子来到，好像毁灭从全能者那里来到一样。'),
('CNV', '以赛亚书', 23, 13, 7, '因此，各人的手都必发软，各人也必心惊胆战。'),
('CNV', '以赛亚书', 23, 13, 8, '他们都要惊惶失措，疼痛与痛苦必抓住他们；他们必绞痛，像生产中的妇人一样。他们在惊愕中彼此对望，面色像火焰一般。'),
('CNV', '以赛亚书', 23, 13, 9, '看哪！主的日子快来到，必有残忍、愤恨与烈怒，使这地荒凉，使其中的罪人灭绝。'),
('CNV', '以赛亚书', 23, 13, 10, '天上的星星和众星座不再发光；太阳刚出来就变为黑暗，月亮也不再发光。'),
('CNV', '以赛亚书', 23, 13, 11, '我必因世界的邪恶施行刑罚，也必因恶人的罪孽惩罚他们；我要使狂妄人的骄傲止息，使强暴人的狂傲降卑。'),
('CNV', '以赛亚书', 23, 13, 12, '我必使人比精金还少，使人比俄斐的金更稀罕。'),
('CNV', '以赛亚书', 23, 13, 13, '在万军之主发怒的时候，就是我大发烈怒的日子，我要使天震动，大地必摇撼，离开本位。'),
('CNV', '以赛亚书', 23, 13, 14, '人必像被追猎的羚羊，又像无人招聚的羊群，各自归向本族，各自逃回本地。'),
('CNV', '以赛亚书', 23, 13, 15, '凡被追上的，必被刺死；凡被捉住的，必倒在刀下。'),
('CNV', '以赛亚书', 23, 13, 16, '他们的婴孩必在他们眼前被摔死；他们的房屋必被抢掠，他们的妻子必被污辱。'),
('CNV', '以赛亚书', 23, 13, 17, '看哪！我要激动玛代人来攻击他们。玛代人不重视银子，也不喜爱金子。'),
('CNV', '以赛亚书', 23, 13, 18, '他们的弓箭必射倒年轻人，他们不怜悯妇人腹中的婴儿；他们的眼也不顾惜小孩。'),
('CNV', '以赛亚书', 23, 13, 19, '巴比伦本是列国中的华美，是迦勒底人引以为傲的荣耀，必像神倾覆的所多玛、蛾摩拉一样。'),
('CNV', '以赛亚书', 23, 13, 20, '那地必永远没有居民，世世代代无人居住；阿拉伯人不在那里搭帐幕；牧羊人也不领羊群躺卧在那里。'),
('CNV', '以赛亚书', 23, 13, 21, '躺卧在那里的，只有旷野的走兽；充满着他们房屋的，只有吼叫着的野兽；鸵鸟住在那里，野山羊在那里跳跃。'),
('CNV', '以赛亚书', 23, 13, 22, '豺狼必在巴比伦的宫中呼号，野狗必在他们华美的殿里吠叫。巴比伦受罚的时候临近了，它的日子必不长久。'),
('CNV', '以赛亚书', 23, 14, 1, '主怜悯雅各，再拣选以色列，使他们安居在自己的国土上的时候，外族人必与他们联合，归属于雅各家。'),
('CNV', '以赛亚书', 23, 14, 2, '以色列人必把他们带回自己的国土去，以色列家必在主所赐的地上得着这些外族人作仆婢；也要掳掠那些掳掠过他们的，并且统治那些欺压过他们的。'),
('CNV', '以赛亚书', 23, 14, 3, '主使你脱离痛苦、愁烦、被迫作的苦工，得享安息的日子，'),
('CNV', '以赛亚书', 23, 14, 4, '你必唱出这首诗歌来讽刺巴比伦王，说：“欺压人的，怎么止息了呢！强暴怎么止住了呢！'),
('CNV', '以赛亚书', 23, 14, 5, '主折断了恶人的杖和统治者的棒，'),
('CNV', '以赛亚书', 23, 14, 6, '就是那在忿怒中不住击打众民、在怒气中管辖列国、毫无抑制地施行迫害的。'),
('CNV', '以赛亚书', 23, 14, 7, '现在全地都平静安息，各人都发声欢呼。'),
('CNV', '以赛亚书', 23, 14, 8, '连松树和黎巴嫩的香柏树都因你欢乐，说：‘自从你躺下以后，再没有砍伐的人上来砍伐我们了。’'),
('CNV', '以赛亚书', 23, 14, 9, '地下的阴间因你震动，并迎接你的来临；又因你而唤醒了所有曾在地上作过领袖的阴魂；又使所有曾在列国中作君王的，都离位站起来。'),
('CNV', '以赛亚书', 23, 14, 10, '他们都必答话，对你说：‘你也变为衰弱，像我们一样吗？你也与我们相似吗？’'),
('CNV', '以赛亚书', 23, 14, 11, '你的威势和你的琴瑟音乐，都被带下阴间了；你下面铺的是虫，上面盖的是蛆。'),
('CNV', '以赛亚书', 23, 14, 12, '明亮之星、清晨之子啊！你怎么从天上坠落？你这倾覆列国的，怎么被砍倒在地上？'),
('CNV', '以赛亚书', 23, 14, 13, '你心里曾说：‘我要升到天上，我要高举我的宝座到神的众星之上，我要坐在聚会的山上，在北方的极处。'),
('CNV', '以赛亚书', 23, 14, 14, '我要升到云的高处，我要使自己像那至高者一般。’'),
('CNV', '以赛亚书', 23, 14, 15, '然而，你却被抛下阴间，落到坑中的极处。'),
('CNV', '以赛亚书', 23, 14, 16, '那些看见你的，都必定睛看你，他们必注视着你，说：‘那使大地震动，使列国摇撼，'),
('CNV', '以赛亚书', 23, 14, 17, '使世界如同荒野，倾覆城镇，又不释放囚犯的，就是这人吗？’'),
('CNV', '以赛亚书', 23, 14, 18, '列国的君王都在荣耀中安睡，各在自己的坟墓里。'),
('CNV', '以赛亚书', 23, 14, 19, '但你要从你的坟墓中被逐出，好像一根被厌弃的树枝，你被那些遭刀剑所杀的人掩盖，就是那些被抛到坑中石头那里的人。你就像一具遭人践踏的尸体。'),
('CNV', '以赛亚书', 23, 14, 20, '你必不得与别的君王同葬，因为你败坏了你的国，杀戮了你的人民；愿那些恶人的后裔永远不被人提说。'),
('CNV', '以赛亚书', 23, 14, 21, '因为他们的祖宗犯了罪孽，你们要为他的子孙预备屠杀之处；不要让他们兴起来，占有地土，在世上布满城镇。”'),
('CNV', '以赛亚书', 23, 14, 22, '万军之主说：“我必兴起攻击他们，把巴比伦的名号、所剩余的人，以及后裔子孙，都一同剪除。”这是主说的。'),
('CNV', '以赛亚书', 23, 14, 23, '“我必使巴比伦被箭猪所占，又使它变为泥沼之地；我必用毁灭的扫帚把它扫净。”这是万军之主说的。'),
('CNV', '以赛亚书', 23, 14, 24, '万军之主起了誓，说：“我怎样想，事就怎样成就；我怎样计划，事就怎样立定，'),
('CNV', '以赛亚书', 23, 14, 25, '就是在我的地上粉碎亚述人，在我的山上践踏他；他所加的轭必离开以色列人，他所加的重担必离开以色列人的肩头。”'),
('CNV', '以赛亚书', 23, 14, 26, '这就是对全地所定的旨意，就是向列国伸出的手。'),
('CNV', '以赛亚书', 23, 14, 27, '因为万军之主决定的事，谁能阻拦呢？他的手伸了出来，谁能使他收回呢？'),
('CNV', '以赛亚书', 23, 14, 28, '亚哈斯王去世的那一年，有以下的默示：'),
('CNV', '以赛亚书', 23, 14, 29, '非利士全地啊！不要因为那击打你们的杖折断了就欢喜，因为从蛇的根必生出毒蛇来，它所生的，是会飞的蛇。'),
('CNV', '以赛亚书', 23, 14, 30, '最贫寒的人必有食物吃，贫乏人必安然躺卧；我必用饥荒毁灭你的根，你余剩的人，必被饥荒所杀。'),
('CNV', '以赛亚书', 23, 14, 31, '城门啊，要哀号！城镇啊，要呼叫！非利士全地啊，要战栗发软！因为有烟从北方来，在他的行伍中没有离队逃走的。'),
('CNV', '以赛亚书', 23, 14, 32, '人要怎样回答外族的使者呢？要说：“主建立了锡安，他子民中的困苦人必在其中避难。”'),
('CNV', '以赛亚书', 23, 15, 1, '关于摩押的默示：一夜之间，摩押的亚珥受到蹂躏，就灭亡了！一夜之间，摩押的基珥受到蹂躏，也灭亡了！'),
('CNV', '以赛亚书', 23, 15, 2, '他们进入房子（“房子”或译：“庙宇”），又往底本，上到高处去哭泣，摩押人为尼波和米底巴哀号；各人头上都光秃，胡须剃净。'),
('CNV', '以赛亚书', 23, 15, 3, '他们在街上都腰束麻布；在房顶上，在广场上，各人都哀号，流泪痛哭。'),
('CNV', '以赛亚书', 23, 15, 4, '希实本和以利亚利都呼喊，他们的声音达到雅杂，因此摩押配带武器的人大声呼叫，各人的心都战兢。'),
('CNV', '以赛亚书', 23, 15, 5, '我的心为摩押哀号，它的逃民一直去到琐珥，如同一头三岁大的牝牛，要挣脱苦轭，他们登上鲁希的山坡，随走随哭，他们在何罗念的路上，发出灭亡的哀号。'),
('CNV', '以赛亚书', 23, 15, 6, '因为宁林的众水都已荒凉，青草枯干，嫩草灭没，完全没有青绿之物。'),
('CNV', '以赛亚书', 23, 15, 7, '所以，他们把所得的和所积蓄的财富，都带过了柳树溪。'),
('CNV', '以赛亚书', 23, 15, 8, '哀号的声音传遍了摩押四境，哀声直达以基莲，又传到比珥．以琳。'),
('CNV', '以赛亚书', 23, 15, 9, '底们（按照《死海古卷》和一些古译本，“底们”作“底本”；“底们”大概是“底本”的另一种写法，为使与原文“血”字更相似；下同）的水充满了血，我还要把更多的灾祸加给底们，使狮子临到摩押逃难的人和那地余下的人中间。'),
('CNV', '以赛亚书', 23, 16, 1, '你们要把羊羔送给那地的掌权者，从西拉经过旷野，送到锡安居民（“居民”原文作“女子”）的山。'),
('CNV', '以赛亚书', 23, 16, 2, '摩押的居民在亚嫩渡口，像游荡的飞鸟，又像被赶出巢窝的鸟儿。'),
('CNV', '以赛亚书', 23, 16, 3, '“求你给我们献谋略，作裁判！使你的影子在午间如同黑夜，把被赶逐的人隐藏起来，不可出卖逃亡的人。'),
('CNV', '以赛亚书', 23, 16, 4, '让摩押那些被赶逐的人与你同住，求你作他们的隐密处，使他们脱离毁灭者的面。勒索人的必要终止，毁灭人的也将止息，欺压人的必从这地灭绝；'),
('CNV', '以赛亚书', 23, 16, 5, '必有一个宝座在慈爱中建立；必有一位凭信实坐在上面，就是在大卫的帐棚里；他必施行审判，寻求公平，并且迅速行公义。”'),
('CNV', '以赛亚书', 23, 16, 6, '我们听说过摩押的骄傲，十分骄傲；也听说过它的狂妄、骄傲和忿怒，它那浮夸的话都是虚假。'),
('CNV', '以赛亚书', 23, 16, 7, '因此，摩押人必哀哭，各人一同为摩押哀哭，摩押人又要为吉珥．哈列设的葡萄饼哀叹忧伤。'),
('CNV', '以赛亚书', 23, 16, 8, '因为希实本的田地和西比玛的葡萄树都衰残了，它们美好的枝子曾醉倒了列国的君主。它的嫩枝直达雅谢，蔓延到旷野，又向外伸展，越过盐海。'),
('CNV', '以赛亚书', 23, 16, 9, '因此，我要为西比玛的葡萄树哀哭，像雅谢人的哀哭一样。希实本和以利亚利啊！我要用眼泪浸透你；因为有吶喊的声音临到你夏天的果子和你收割的庄稼。'),
('CNV', '以赛亚书', 23, 16, 10, '欢喜快乐都从肥美的田地中被取去了；葡萄园里必再没有歌唱，也没有欢呼；踹酒的不能在榨酒池里踹出酒来；我止息了欢呼的声音！'),
('CNV', '以赛亚书', 23, 16, 11, '因此，我的心肠为摩押哀鸣，有如琴瑟；我的肺腑也为吉珥．哈列设哀哭。'),
('CNV', '以赛亚书', 23, 16, 12, '到那时，摩押人虽朝见他们的神，虽在高处弄得疲乏不堪，又到他们的圣所去祷告，却总不得亨通。'),
('CNV', '以赛亚书', 23, 16, 13, '以上是主从前论到摩押所说的话。'),
('CNV', '以赛亚书', 23, 16, 14, '但现在主宣告说：“三年之内，按照雇工的年数，摩押的荣耀和他所有的群众，都必被藐视；余下的人必稀少，微不足道。”'),
('CNV', '以赛亚书', 23, 17, 1, '关于大马士革的默示：“看哪！大马士革快要被废弃，不再是一个城市，它必变作废墟。'),
('CNV', '以赛亚书', 23, 17, 2, '亚罗珥的城市必被撇弃，成为牧放羊群之处，羊群必在那里躺卧，没有人惊扰它们。'),
('CNV', '以赛亚书', 23, 17, 3, '以法莲的堡垒必失去，大马士革的国权也必消逝；亚兰的余民必像以色列人的荣耀一般消灭。”这是万军之主说的。'),
('CNV', '以赛亚书', 23, 17, 4, '“到那日，雅各的荣耀必衰落，他肥胖的身体必消瘦。'),
('CNV', '以赛亚书', 23, 17, 5, '就像收割的人收聚庄稼，用手割取穗子；又像人在利乏音谷，拾取遗落的穗子。'),
('CNV', '以赛亚书', 23, 17, 6, '虽然其中有少许遗下的穗子，却好像橄榄树被打过一样。在树顶上，只剩下两三个果子；在那本是多结果子的果树枝上，只留下四五个果子。”这是主以色列的神说的。'),
('CNV', '以赛亚书', 23, 17, 7, '到那日，人必仰望他们的创造主，他们必亲眼看见以色列的圣者。'),
('CNV', '以赛亚书', 23, 17, 8, '他们必不仰望自己双手所做的祭坛，也不再看着自己指头所做的，无论是亚舍拉，或是香坛。'),
('CNV', '以赛亚书', 23, 17, 9, '到那日，他们那些因以色列人而撇弃的坚固城，必像树林中和山顶上被撇弃的地方，这样，地就荒凉了。'),
('CNV', '以赛亚书', 23, 17, 10, '因为你忘记了那拯救你的神，又不记念那作你避难所的磐石，所以你虽然栽下佳美的树秧子，种下异种的幼苗，'),
('CNV', '以赛亚书', 23, 17, 11, '又在你栽种的日子里，细心地在周围圈上篱笆，到早晨，又使你所栽种的开花，但在愁苦与极度伤痛的日子里，所收割的就只有一小堆。'),
('CNV', '以赛亚书', 23, 17, 12, '唉！许多民族在喧哗，他们喧嚷好像海浪澎湃；列国在咆哮，他们吼叫，好像洪水奔流。'),
('CNV', '以赛亚书', 23, 17, 13, '万族怒号，好像众水涌流，但神必斥责他们，使他们远远逃跑；他们又被追赶，如同山上风前的糠秕，又像暴风前的尘土卷动。'),
('CNV', '以赛亚书', 23, 17, 14, '在晚上有惊恐，未到早晨，他们就没有了，这是那些抢夺我们的人所得的分，是那些掠劫我们的人应得的报应。'),
('CNV', '以赛亚书', 23, 18, 1, '古实河外，船只彼此碰撞，响声四起之地，有祸了！'),
('CNV', '以赛亚书', 23, 18, 2, '这就是那经常差派使者，在水面上乘坐蒲草船渡海的地方。去吧！快行的使者，到那身躯高大、皮肤光滑的国去，到一个远近都为人所惧怕的民族那里去，这国是强盛和践踏人的，他们的地有河流把地分开。'),
('CNV', '以赛亚书', 23, 18, 3, '世上所有的居民，住在全地上的人哪！山上竖起旗帜的时候，你们要注意；号角吹响的时候，你们要聆听。'),
('CNV', '以赛亚书', 23, 18, 4, '主这样对我说：“我要从我的居所安静观看，像日光中闪烁的热气，又像收割时的热气中有露水的云彩。”'),
('CNV', '以赛亚书', 23, 18, 5, '因为在收割以前，花蕾开尽，花朵也成了将熟的葡萄之时，他就用镰刀削去嫩枝，又砍掉蔓延的枝子。'),
('CNV', '以赛亚书', 23, 18, 6, '它们都要撇下，给山间的鸷鸟，和地上的野兽；鸷鸟必吃它们来度过夏天，地上的百兽必吃它们来度过冬天。'),
('CNV', '以赛亚书', 23, 18, 7, '到那时，这个身躯高大、皮肤光滑的民族，就是远近都为人所惧怕的民族，强盛和践踏人的国，他们的地有河流把地分开，他们必把礼物带来给万军之主，就是奉到锡安山，万军之主立他名的地方。'),
('CNV', '以赛亚书', 23, 19, 1, '关于埃及的默示：看哪！主驾着轻快的云，来到埃及；埃及的偶像在他面前战兢，埃及人的心都惊怕。'),
('CNV', '以赛亚书', 23, 19, 2, '我要激动埃及人去攻击埃及人，他们就相争起来，各人攻击自己的兄弟，各人攻击自己的邻舍，城攻击城；国攻击国。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '以赛亚书', 23, 19, 3, '埃及人的意志必消沉，我要破坏他们的计谋；他们必求问偶像、念咒的、交鬼的和行巫术的。'),
('CNV', '以赛亚书', 23, 19, 4, '我必把埃及人交在残暴的主人手中；凶猛的君王要管辖他们；这是主万军之主说的。'),
('CNV', '以赛亚书', 23, 19, 5, '海中的众水必干透，河床必枯竭干涸。'),
('CNV', '以赛亚书', 23, 19, 6, '河道必发臭，埃及众河流的水必消退干涸；苇子和芦荻都必枯萎。'),
('CNV', '以赛亚书', 23, 19, 7, '尼罗河旁、尼罗河口的草田，以及沿着尼罗河所种的田都必枯干，被吹散，不再存在。'),
('CNV', '以赛亚书', 23, 19, 8, '打鱼的人必哀号；所有在尼罗河上垂钓的必悲伤；那些在水面上撒网的，必灰心难过。'),
('CNV', '以赛亚书', 23, 19, 9, '那些用梳好的麻来纺纱的，和那些织白布的，都必羞愧。'),
('CNV', '以赛亚书', 23, 19, 10, '埃及的柱石必被打碎，所有受雇的工人也必心里忧愁。'),
('CNV', '以赛亚书', 23, 19, 11, '琐安的领袖非常愚昧，法老那些最有智慧的谋士所筹算的，都成为愚昧。你们怎能对法老说：“我是智慧人的儿子，是古代君王的后裔”呢？'),
('CNV', '以赛亚书', 23, 19, 12, '你的智慧人在哪里呢？万军之主向埃及所定的旨意是怎样的？就让他们告诉你，使你知道吧！'),
('CNV', '以赛亚书', 23, 19, 13, '琐安的领袖都变为愚昧，挪弗的领袖都受了欺骗；那些在埃及支派中作房角石的，使埃及人走错了路。'),
('CNV', '以赛亚书', 23, 19, 14, '主让歪曲的灵搀入埃及当中，以致他们使埃及一切所作的都有谬误，好像醉酒的人呕吐的时候，东倒西歪一样。'),
('CNV', '以赛亚书', 23, 19, 15, '无论是头或尾、棕枝或芦苇所作的，都不能为埃及成就什么事。'),
('CNV', '以赛亚书', 23, 19, 16, '到那日，埃及人必像妇人一样。他们必因万军之主在埃及之上挥手而战兢恐惧。'),
('CNV', '以赛亚书', 23, 19, 17, '犹大地必使埃及惊恐；无论谁向埃及人提起犹大地，他们都惧怕，因为这是万军之主向埃及所定的旨意。'),
('CNV', '以赛亚书', 23, 19, 18, '到那日，埃及地必有五座城的人说迦南的方言，又指着万军之主起誓，必有一座城称为“毁灭城”（“毁灭城”或译：“太阳城”）。'),
('CNV', '以赛亚书', 23, 19, 19, '到那日，在埃及地必有一座献给主的祭坛；在埃及的边界上必有一根献给主的柱子。'),
('CNV', '以赛亚书', 23, 19, 20, '这都要在埃及地作万军之主的记号和证据。埃及人因受人欺压向主哀求的时候，他就差派一位拯救者和维护者到他们那里，他必拯救他们。'),
('CNV', '以赛亚书', 23, 19, 21, '主必被埃及人认识。到那日，埃及人必认识主；他们也要用祭物和供物来敬拜他，并且向主许愿、还愿。'),
('CNV', '以赛亚书', 23, 19, 22, '主必击打埃及，既击打、又医治，他们就回转归向主，他必应允他们的祷告，医治他们。'),
('CNV', '以赛亚书', 23, 19, 23, '到那日，必有一条从埃及通到亚述的大道；亚述人要进到埃及，埃及人也要进入亚述；埃及人要与亚述人一同敬拜主。'),
('CNV', '以赛亚书', 23, 19, 24, '到那日，以色列必与埃及和亚述一起成为地上列国的祝福。'),
('CNV', '以赛亚书', 23, 19, 25, '万军之主赐福给他们，说：“我的子民埃及，我手的工程亚述，我的产业以色列，都是有福的！”'),
('CNV', '以赛亚书', 23, 20, 1, '亚述王撒珥根差派统帅去亚实突的那年，那统帅就攻打亚实突，把城占领。'),
('CNV', '以赛亚书', 23, 20, 2, '那时，主藉着亚摩斯的儿子以赛亚说：“你解开你腰间的麻布，脱去你脚上的鞋。”以赛亚就这样作了，露体赤足行走。'),
('CNV', '以赛亚书', 23, 20, 3, '主说：“我的仆人以赛亚怎样露体赤足行走了三年，作攻击埃及和古实的预兆和兆头，'),
('CNV', '以赛亚书', 23, 20, 4, '亚述王也必照样把埃及的俘虏和古实被放逐的人带走，无论老少，都露体赤足，露出下体，使埃及蒙羞。'),
('CNV', '以赛亚书', 23, 20, 5, '以色列人必因他们所仰望的古实和他们所夸耀的埃及，惊惶羞愧。'),
('CNV', '以赛亚书', 23, 20, 6, '到那日，这沿海的居民必说：‘看哪！我们所仰望的，就是我们为着脱离亚述王，逃往投靠的，也不过是这样。我们又怎能逃脱呢？’”'),
('CNV', '以赛亚书', 23, 21, 1, '关于海旁旷野的默示：有敌人从旷野，从可怕之地而来，好像南地的暴风猛烈扫过一般。'),
('CNV', '以赛亚书', 23, 21, 2, '我被指示去看一个惨酷的异象：那行诡诈的仍然行诡诈，那行破坏的仍然行破坏。以拦哪，上去吧！玛代啊，围攻吧！我要使一切叹息止住。'),
('CNV', '以赛亚书', 23, 21, 3, '因此，我满腰疼痛，痛苦抓住我，好像产妇的痛苦一样；我绞痛弯腰至听不见，我惊惶至看不到。'),
('CNV', '以赛亚书', 23, 21, 4, '我的心迷糊，惊恐威吓着我；我所爱慕的黄昏，竟使我战兢。'),
('CNV', '以赛亚书', 23, 21, 5, '他们摆设筵席，铺张地毡，又吃又喝。领袖们，起来吧！用油抹净盾牌。'),
('CNV', '以赛亚书', 23, 21, 6, '因为主这样对我说：“你去设立守望的，叫他把所看见的报告出来。'),
('CNV', '以赛亚书', 23, 21, 7, '他一看见骑兵一对一对而来，又有驴队和骆驼队，他就要留意，非常留意。”'),
('CNV', '以赛亚书', 23, 21, 8, '后来，守望者（按照《马索拉文本》，“守望者”作“狮子”；现参照《死海古卷》和《叙利亚文古译本》翻译）喊叫着说：“主啊！我每日不断站在守望楼上，每夜立在我守望的岗位中。'),
('CNV', '以赛亚书', 23, 21, 9, '看哪！有一队骑兵来了，马兵一对一对而来。”又有人答话说：“倾倒了，巴比伦倾倒了！它所有雕刻的神像都被打碎在地上了。”'),
('CNV', '以赛亚书', 23, 21, 10, '我那被打的禾稼啊！我禾场上的谷啊！我从万军之主，以色列的神那里听见的，都告诉你们了。'),
('CNV', '以赛亚书', 23, 21, 11, '关于以东（“以东”原文作“度玛”，意即寂静，在这里暗示以东的困境）的默示：有人从西珥呼叫我说：“守望的啊！黑夜还有多长？守望的啊！黑夜还有多长？”'),
('CNV', '以赛亚书', 23, 21, 12, '守望的说：“早晨到了，黑夜也会再来；你们若要问，就尽管问；也可以回头再来问。”'),
('CNV', '以赛亚书', 23, 21, 13, '关于阿拉伯的默示：底但的商队啊！你们必在阿拉伯的森林中住宿。'),
('CNV', '以赛亚书', 23, 21, 14, '提玛地的居民哪！要拿水来给那些口渴的，拿饼来接待那些逃难的。'),
('CNV', '以赛亚书', 23, 21, 15, '因为他们逃避了刀剑、已出鞘的刀剑和上了弦的弓，以及严重的战祸。'),
('CNV', '以赛亚书', 23, 21, 16, '主对我这样说：“按照雇工的年数，一年之内，基达的一切光荣都必化为乌有。'),
('CNV', '以赛亚书', 23, 21, 17, '弓箭手剩余的人数，就是基达人的勇士，必定很少；这是主以色列的神说的。”'),
('CNV', '以赛亚书', 23, 22, 1, '关于“异象谷”的默示：你们发生了什么事，以致你们都上了房顶呢？'),
('CNV', '以赛亚书', 23, 22, 2, '你这充满喧哗，繁嚣、欢乐的城市啊！你们中间被杀的，并不是被刀剑所杀，也不是在战场上阵亡。'),
('CNV', '以赛亚书', 23, 22, 3, '你们所有的官长都一起逃跑；他们因没有弓箭而被俘掳，你们中间所有被找到的都一起被俘掳，虽然他们已逃到远方去。'),
('CNV', '以赛亚书', 23, 22, 4, '因此我说：“要转开你们的眼，不要望着我，让我痛哭吧！不要因我人民的毁灭，而急急安慰我。”'),
('CNV', '以赛亚书', 23, 22, 5, '因为主万军之主使“异象谷”有惊恐、践踏、混乱的日子：城墙被拆毁，哀声传到山上。'),
('CNV', '以赛亚书', 23, 22, 6, '以拦拿着箭袋，并有战车、步兵和骑兵；吉珥亮出盾牌。'),
('CNV', '以赛亚书', 23, 22, 7, '你佳美的山谷都布满战车，又有骑兵在城门前列阵。'),
('CNV', '以赛亚书', 23, 22, 8, '他挪去犹大的屏障了。到那日，你就仰望“林宫”里的武器；'),
('CNV', '以赛亚书', 23, 22, 9, '你们看见大卫的缺口很多，就储存下池的水。'),
('CNV', '以赛亚书', 23, 22, 10, '你们又数点耶路撒冷的房屋，把房屋拆掉，用来坚固城墙。'),
('CNV', '以赛亚书', 23, 22, 11, '你们又在两道城墙之间造一个水池，用来盛载旧池的水，你们却不仰望作这事的主，也不顾念远古以来计划这事的神。'),
('CNV', '以赛亚书', 23, 22, 12, '到那日，主万军之主叫人哭泣哀号，剃光头发，穿上麻布。'),
('CNV', '以赛亚书', 23, 22, 13, '看哪！人还是欢喜快乐，宰牛杀羊，吃肉喝酒，说：“我们吃喝吧！因为明天我们就要死了。”'),
('CNV', '以赛亚书', 23, 22, 14, '万军之主亲自启示我说：“直到你们死的时候，这罪孽也不得赦免。”这是主万军之主说的。'),
('CNV', '以赛亚书', 23, 22, 15, '主万军之主这样说：“你去见这掌管库房的，就是总管舍伯那，对他说：'),
('CNV', '以赛亚书', 23, 22, 16, '你在这里有什么权利呢？你在这里有什么人，竟在这里为你自己凿坟墓，就是在高处为自己凿坟墓，在磐石中为自己凿出安身之所呢？'),
('CNV', '以赛亚书', 23, 22, 17, '看哪，勇士啊！主将要猛烈地抛掷你；他必把你紧紧抓住，'),
('CNV', '以赛亚书', 23, 22, 18, '把你卷了又卷，卷成球状，然后掷到宽阔之地；你必死在那里，你那华美的战车也在那里；你成了你主人之家的耻辱。'),
('CNV', '以赛亚书', 23, 22, 19, '我必革除你的官职，从你的原位上把你拉下来。'),
('CNV', '以赛亚书', 23, 22, 20, '到那日，我必召希勒家的儿子，就是我的仆人以利亚敬来，'),
('CNV', '以赛亚书', 23, 22, 21, '我会把你的外袍给他穿，把你的腰带给他系紧，把你的权柄交在他的手中；他要作耶路撒冷的居民和犹大家的父。'),
('CNV', '以赛亚书', 23, 22, 22, '我必把大卫家的钥匙放在他肩头上；他开了，就没有人能关；他关了，就没有人能开。'),
('CNV', '以赛亚书', 23, 22, 23, '我必坚立他，像钉子钉在稳固的地方；他必作父家荣耀的宝座。'),
('CNV', '以赛亚书', 23, 22, 24, '他父家所有的荣耀，他的儿女和子孙以及各样小器皿，从碗子到瓶子，都挂在他身上。'),
('CNV', '以赛亚书', 23, 22, 25, '万军之主说：‘到那日，那钉在稳固地方的钉子必垂下来，被砍断坠落；那挂在上面的担子必被砍掉，因为这是主说的。’”'),
('CNV', '以赛亚书', 23, 23, 1, '关于推罗的默示：他施的船只啊，要哀号！因为推罗被毁灭了，再没有房屋，也不能再作港口，这消息是他们从塞浦路斯地得来的。'),
('CNV', '以赛亚书', 23, 23, 2, '沿海的居民，就是靠航海致富的西顿商人哪！要静默无言。'),
('CNV', '以赛亚书', 23, 23, 3, '在大水之上，西曷的谷物、尼罗河的庄稼，都是推罗的收益，推罗成了列国的市场。'),
('CNV', '以赛亚书', 23, 23, 4, '西顿啊，要惭愧！因为大海说过，就是海上的保障说过：“我没有受过产痛，也没有生产；我没有养大过男孩，也没有抚养过童女。”'),
('CNV', '以赛亚书', 23, 23, 5, '这消息传到埃及时，埃及人就为推罗这消息非常伤痛。'),
('CNV', '以赛亚书', 23, 23, 6, '你们要过到他施去；沿海的居民哪，要哀号！'),
('CNV', '以赛亚书', 23, 23, 7, '这就是你们欢乐的城吗？它的起源溯自上古，它的脚把其中的居民带到远方去寄居。'),
('CNV', '以赛亚书', 23, 23, 8, '谁策划这事来攻击推罗呢？它本是赐人冠冕的城，它的商人是王子，它的商贾是世上的尊贵人。'),
('CNV', '以赛亚书', 23, 23, 9, '这是万军之主所定的旨意，要凌辱那些因荣美而有狂傲，使地上所有的尊贵人被藐视。'),
('CNV', '以赛亚书', 23, 23, 10, '他施的居民哪！要像尼罗河一般流遍你的地，再没有限制了。'),
('CNV', '以赛亚书', 23, 23, 11, '主已经向海伸手，使列国震动；主又发出一个关于迦南的吩咐，就是要毁坏其中的保障。'),
('CNV', '以赛亚书', 23, 23, 12, '他又说：“受压制的西顿居民哪，你们不再有欢乐了！起来，过到塞浦路斯去！就是在那里，你们也得不到安息。”'),
('CNV', '以赛亚书', 23, 23, 13, '看哪！使推罗成为旷野，走兽居住之处的，是来自迦勒底地的人，而不是亚述人；他们要筑起攻城的高塔，拆毁推罗的城堡，使它成为废墟。'),
('CNV', '以赛亚书', 23, 23, 14, '他施的船只啊，要哀号！因为你们的保障已被毁灭了。'),
('CNV', '以赛亚书', 23, 23, 15, '到那日，推罗必被忘记七十年，正如一个王朝的年日；七十年后，推罗必像妓女所唱之歌：'),
('CNV', '以赛亚书', 23, 23, 16, '“你被遗忘的妓女啊！拿起琴来，走遍全城吧。你要巧弹多唱，使人再想起你！”'),
('CNV', '以赛亚书', 23, 23, 17, '七十年后，主必眷顾推罗，推罗就恢复繁荣，可以与地上的万国交易。'),
('CNV', '以赛亚书', 23, 23, 18, '它的货财和所得的利益要分别为圣归给主，必不会积聚或储藏起来；因为它的货财必归给那些住在主面前的人，使他们吃得饱足，穿得漂亮。'),
('CNV', '以赛亚书', 23, 24, 1, '看哪！主使大地空虚，变为荒凉；他必翻转地面，使地上的居民四散。'),
('CNV', '以赛亚书', 23, 24, 2, '人民和祭司，仆人和主人，婢女和主母，购买的和贩卖的，借给人和向人借的，放债的和借债的，全都一样被分散。'),
('CNV', '以赛亚书', 23, 24, 3, '大地必完全倒空，被劫掠净尽，这话是主说的。'),
('CNV', '以赛亚书', 23, 24, 4, '大地悲哀衰残，世界零落衰残，地上居高位的人也衰败了。'),
('CNV', '以赛亚书', 23, 24, 5, '大地被其上的居民玷污，因为他们犯了律法，违了律例，背了永远的约。'),
('CNV', '以赛亚书', 23, 24, 6, '因此，大地被咒诅吞灭，地上的居民要承担惩罚。因此，地上的居民被焚烧，剩下的人很少。'),
('CNV', '以赛亚书', 23, 24, 7, '新酒悲哀，葡萄树衰残，心中欢乐的，变为叹息。'),
('CNV', '以赛亚书', 23, 24, 8, '击鼓的喜乐止息，宴乐者的喧哗停止，弹琴的喜乐也止息了。'),
('CNV', '以赛亚书', 23, 24, 9, '他们不得再饮酒唱歌；喝浓酒的，必觉苦味。'),
('CNV', '以赛亚书', 23, 24, 10, '混乱的城破毁了，各家关门闭户，使人不得进入。'),
('CNV', '以赛亚书', 23, 24, 11, '有人在街上因无酒呼喊；一切喜乐都已过去，地上的喜乐都消逝了。'),
('CNV', '以赛亚书', 23, 24, 12, '城门所剩下的只有荒凉，城门被撞得粉碎。'),
('CNV', '以赛亚书', 23, 24, 13, '在地上的万民，都像摇过的橄榄树，又像被摘取完了的葡萄树，剩下无几。'),
('CNV', '以赛亚书', 23, 24, 14, '剩余的人必高声欢呼，在西边的，要宣扬主的威严。'),
('CNV', '以赛亚书', 23, 24, 15, '在东方那边的，要荣耀主，要在沿海的众岛上，荣耀主以色列神的名。'),
('CNV', '以赛亚书', 23, 24, 16, '我们听见从地极有歌声唱着：“荣耀归于义人。”我却说：“我消瘦了，我消瘦了！我有祸了！诡诈的仍在行诡诈，诡诈的仍在大行诡诈。”'),
('CNV', '以赛亚书', 23, 24, 17, '地上的居民哪！恐惧、陷坑和网罗，都临近你们！'),
('CNV', '以赛亚书', 23, 24, 18, '那逃避恐惧声音的，必堕入陷坑；那从陷坑里上来的，必被网罗缠住；因为天上的窗都开了，地的根基也震动了。'),
('CNV', '以赛亚书', 23, 24, 19, '大地全然破坏，尽都崩裂，大大震动。'),
('CNV', '以赛亚书', 23, 24, 20, '大地东歪西倒，像个醉酒的人，又摇来摇去，像座草棚；大地被其上的罪孽重重压着，以致塌陷，不能再起来。'),
('CNV', '以赛亚书', 23, 24, 21, '到那日，主必在高天之上惩罚天上的众军，又在地上惩罚地上的列王。'),
('CNV', '以赛亚书', 23, 24, 22, '他们必被聚集，像囚犯被聚集在牢狱里一般；他们要被关在监牢中，多日以后，他们要被惩罚。'),
('CNV', '以赛亚书', 23, 24, 23, '那时，月亮必蒙羞，日头要惭愧，因为万军之主必在锡安山，在耶路撒冷作王；并且在他子民的众长老面前，大有荣耀。'),
('CNV', '以赛亚书', 23, 25, 1, '主啊！你是我的神，我要尊崇你，称谢你的名，因为你以信实真诚作成了奇妙的事，就是你远古以前所计划的事。'),
('CNV', '以赛亚书', 23, 25, 2, '你使城市变成废堆，使坚固城变为荒凉的地方，使外族人的城堡不再为城，永远不得重建。'),
('CNV', '以赛亚书', 23, 25, 3, '因此，强大的民族必荣耀你；强暴之国的城也要敬畏你。'),
('CNV', '以赛亚书', 23, 25, 4, '你作了困乏人的保障、贫穷人急难中的保障、躲暴风雨的避难所、避炎热的阴凉处；因为强暴者所吹的气，如同直吹墙壁的暴风。'),
('CNV', '以赛亚书', 23, 25, 5, '你抑制外族人的喧哗，好像减低干旱之地的炎热；你禁止强暴者的凯歌，好像热气因云彩而消散。'),
('CNV', '以赛亚书', 23, 25, 6, '万军之主必在这山上为万民摆设丰盛美筵，有陈酒、满髓的肥甘和醇美好酒。'),
('CNV', '以赛亚书', 23, 25, 7, '他又必在这山上除灭那遮盖万民的面巾，和那遮盖列国的帕子。'),
('CNV', '以赛亚书', 23, 25, 8, '他要吞灭死亡，直到永远；主神必擦去各人脸上的眼泪，又从地上除掉他子民的羞辱；这是主说的。'),
('CNV', '以赛亚书', 23, 25, 9, '到那日，必有人说：“看哪！这是我们的神；我们信靠他，他必拯救我们。这是主，我们所倚靠的，我们要因他的拯救欢喜快乐。'),
('CNV', '以赛亚书', 23, 25, 10, '主的手必放在这山上；但摩押人在自己的地方必受践踏，好像干草在粪坑中被践踏一样。'),
('CNV', '以赛亚书', 23, 25, 11, '他们必在其中伸开手来，好像游泳者伸开手来游泳一样；但主要使他们的骄傲和他们手所行的诡计，一同败落。'),
('CNV', '以赛亚书', 23, 25, 12, '主必使他们高耸而坚固的城墙倾倒下陷，落在地面，变作尘土。”'),
('CNV', '以赛亚书', 23, 26, 1, '到那日，在犹大地必有人唱这歌：“我们有座坚固的城；主把救恩作为城墙和外郭。'),
('CNV', '以赛亚书', 23, 26, 2, '打开城门吧！好让公义和信实的国民，可以进入。'),
('CNV', '以赛亚书', 23, 26, 3, '专心倚靠你的，你必保护他一切平安，因为他倚靠你。'),
('CNV', '以赛亚书', 23, 26, 4, '你们要倚靠主，直到永远，因为主是永存的磐石。'),
('CNV', '以赛亚书', 23, 26, 5, '他使那些骄傲的降卑，使那些高耸的城败落；把它拆毁，散在地上，变作尘土。'),
('CNV', '以赛亚书', 23, 26, 6, '它要被脚践踏，就是困苦人的脚和贫穷人的脚。'),
('CNV', '以赛亚书', 23, 26, 7, '义人的路是正直的，正直的主啊！你必修平义人的路。'),
('CNV', '以赛亚书', 23, 26, 8, '主啊！我们等候你那审判的路径；你的名字和称号，都是我们心里所爱慕的。'),
('CNV', '以赛亚书', 23, 26, 9, '夜间我的心渴想你，我里面的灵切切寻求你，因为你的审判临到大地的时候，世上的居民就会学习到什么是公义了。'),
('CNV', '以赛亚书', 23, 26, 10, '恶人虽然蒙了恩待，他仍不知道什么是公义；在公义的地上，他仍然行恶，也看不见主的威严。'),
('CNV', '以赛亚书', 23, 26, 11, '主啊！你的手高举，他们还是看不见。愿他们因看见你对子民的热心而惭愧；愿那为你的敌人预备的火吞灭他们。'),
('CNV', '以赛亚书', 23, 26, 12, '主啊！你必使我们得平安，因为我们所作的，都是你为我们成就的。'),
('CNV', '以赛亚书', 23, 26, 13, '主我们的神啊！在你以外，曾有别的主管辖我们，但只有你，我们要承认你的名。'),
('CNV', '以赛亚书', 23, 26, 14, '死去的不能再活，离世的不能再起来，因为你惩罚他们，消灭了他们，使他们完全不再被记念。'),
('CNV', '以赛亚书', 23, 26, 15, '主啊！你增添国民；你增添国民，你得了荣耀，又拓展了地的四境。'),
('CNV', '以赛亚书', 23, 26, 16, '主啊！我们在急难中寻求你；你的惩罚临到我们身上的时候，我们就倾心吐意低声祷告。'),
('CNV', '以赛亚书', 23, 26, 17, '怀孕的妇人临产时怎样疼痛，在绞痛中喊叫；主啊！我们在你面前也是这样。'),
('CNV', '以赛亚书', 23, 26, 18, '我们也曾像怀孕一般疼痛，但所生的像风；我们未曾在地上行过拯救的事，世上的居民也未曾因我们生下来。'),
('CNV', '以赛亚书', 23, 26, 19, '属你的死人要活过来，他们的尸体要起来；那些住在尘土里的必醒起，并且欢呼。因为你的甘露像早晨的甘露般临到，使地交出离世的人来。'),
('CNV', '以赛亚书', 23, 26, 20, '我的子民哪！快来，进入你们的内室，把你们的门关上；隐藏片刻，直到神的忿怒过去。'),
('CNV', '以赛亚书', 23, 26, 21, '因为你看！主从他的居所出来，要惩罚地上居民的罪孽；大地要露出其上所流的血，不再遮盖被杀的人。”'),
('CNV', '以赛亚书', 23, 27, 1, '到那日，主要施用他锐利、巨大和有力的刀，惩罚鳄鱼，就是那快行的蛇；惩罚鳄鱼，就是那曲行的蛇；并且要杀海中的大龙。'),
('CNV', '以赛亚书', 23, 27, 2, '到那日，有个出酒的葡萄园，你们必指着这园歌唱说：'),
('CNV', '以赛亚书', 23, 27, 3, '“我主是看守葡萄园的；我时刻浇灌着它，并且为免有人毁坏它，我日夜都看守着。'),
('CNV', '以赛亚书', 23, 27, 4, '我再没有忿怒，若荆棘和蒺藜与我交战，我就上前践踏它们，把它们全部焚毁。'),
('CNV', '以赛亚书', 23, 27, 5, '除非他们抓住我作他们的避难所，与我和好，与我和好。”'),
('CNV', '以赛亚书', 23, 27, 6, '在将来的日子里，雅各要扎根，以色列要发芽开花，他们的果实必遍布地面。'),
('CNV', '以赛亚书', 23, 27, 7, '主击打以色列人，岂像击打那些击打他们的呢？主杀戮以色列人，岂像杀戮那些杀戮他们的呢？'),
('CNV', '以赛亚书', 23, 27, 8, '不，你只是渐渐地，藉着他们被掳与他们相争；在吹东风的日子，就用暴风把他们逐去。'),
('CNV', '以赛亚书', 23, 27, 9, '藉此，雅各的罪孽才得赦免；他的罪过得以除掉的条件全都在于此，就是他叫祭坛上所有的石头都变为破碎的灰石，使亚舍拉和香坛不再竖立。'),
('CNV', '以赛亚书', 23, 27, 10, '坚固的城变为凄凉，成了被撇下、被放弃的居所，像旷野一样；牛犊必在那里吃草，在那里躺卧，并且吃尽那里的树枝。'),
('CNV', '以赛亚书', 23, 27, 11, '枝条枯干了，就必被折断；妇女必来，拿去生火，因为这人民愚昧无知，所以他们的创造主不怜悯他们，那造成他们的，不向他们施恩。'),
('CNV', '以赛亚书', 23, 27, 12, '到那日，主要从幼发拉底的溪流，直到埃及小河，收集他的谷物；以色列人哪！你们必一个一个被捡拾回来。'),
('CNV', '以赛亚书', 23, 27, 13, '到那日，必有大号角吹响，那些在亚述地快要灭亡的，以及那些被赶散在埃及地的，都要前来，在耶路撒冷的圣山上敬拜主。'),
('CNV', '以赛亚书', 23, 28, 1, '以法莲那些醉汉所戴的高傲冠冕，有祸了！它在肥美谷山顶上的荣美，有祸了！它必如将残的花朵，满了喝醉酒的人。'),
('CNV', '以赛亚书', 23, 28, 2, '看哪！主有一个大能大力的人，像一阵冰雹、一阵毁灭的暴风，像涨溢猛流的大水，他必用手把它摔落地上。'),
('CNV', '以赛亚书', 23, 28, 3, '以法莲的醉汉所戴的高傲冠冕，必被践踏在脚下。'),
('CNV', '以赛亚书', 23, 28, 4, '它在肥美谷山顶上如将残的花朵一般的荣美，必像夏天以前初熟的无花果。那些看见它的人，都必注意；一到手里，就把它吞吃了。'),
('CNV', '以赛亚书', 23, 28, 5, '到那日，万军之主必作他余民荣耀的冠冕、美丽的华冠，'),
('CNV', '以赛亚书', 23, 28, 6, '也必作在位上施行审判者公平的心灵，并作在城门口击退敌人者的力量。'),
('CNV', '以赛亚书', 23, 28, 7, '就是这地的人，也因酒摇晃不定，因浓酒东倒西歪；祭司和先知都因浓酒摇晃不定，被酒弄至昏乱，因浓酒东倒西歪。他们见异象的时候，摇晃不定，他们判断的时候，也颠颠倒倒。'),
('CNV', '以赛亚书', 23, 28, 8, '因为各席上都满了污秽的呕吐，没有一处是干净的。'),
('CNV', '以赛亚书', 23, 28, 9, '他们说：“他要把知识教导谁呢？要使谁明白他所传的信息呢？是那些刚断奶，刚离开母怀的吗？'),
('CNV', '以赛亚书', 23, 28, 10, '因为他所说的，只是些重复又重复的话，和毫无意义的字母，这里一点，那里一点罢了。”'),
('CNV', '以赛亚书', 23, 28, 11, '主要藉着外族人的嘴唇和外族人的舌头，对这人民说话。'),
('CNV', '以赛亚书', 23, 28, 12, '他曾对他们说：“这就是安息之处，你们若使疲乏的人得安息，就必得着这安歇的地方。”但他们不肯听从。'),
('CNV', '以赛亚书', 23, 28, 13, '所以主对他们所说的话，就成了重复又重复的话，和毫无意义的字母，这里一点，那里一点，以致他们虽然往前走，却必仰面跌倒，并且跌伤，陷入网罗被缠住。'),
('CNV', '以赛亚书', 23, 28, 14, '因此好讥笑人的人哪！就是管辖这些在耶路撒冷的人民的，你们要听主的话。'),
('CNV', '以赛亚书', 23, 28, 15, '因为你们曾说：“我们与死亡立了约，与阴间结了盟；刑罚的鞭子扫过的时候，必不会碰到我们，因为我们以谎言作遮蔽，以虚假作庇护。”'),
('CNV', '以赛亚书', 23, 28, 16, '所以主神这样说：“看哪！我在锡安放置一块石头，是试验过的石头，是稳固的基石，宝贵的房角石；信靠的人，必不着急。'),
('CNV', '以赛亚书', 23, 28, 17, '我要以公平为准绳，以公义为线铊；冰雹必把谎言的遮蔽冲去，大水必漫过庇护所。”'),
('CNV', '以赛亚书', 23, 28, 18, '你们与死亡所立的约要废除，你们与阴间所结的盟必立不住；刑罚的鞭子扫过的时候，你们就必被践踏。'),
('CNV', '以赛亚书', 23, 28, 19, '每次扫过的时候，都把你们抓去；因为每早晨它必漫过，白天与黑夜也是这样；人若明白所传的，必受惊恐。'),
('CNV', '以赛亚书', 23, 28, 20, '床铺太短，人就不能伸直，被窝太窄，就盖不住全身。'),
('CNV', '以赛亚书', 23, 28, 21, '主必像在毗拉心山一样兴起，又像在基遍谷一样发怒，为要作成他的工，他那奇妙的工，好成就他的事，就是奇异的事。'),
('CNV', '以赛亚书', 23, 28, 22, '现在，你们不可再讥笑了，免得捆绑你们的绳索绑得更紧，因为我从主万军之主那里听到，决定要在全地上施行毁灭的事。'),
('CNV', '以赛亚书', 23, 28, 23, '你们要侧耳听我的声音，留心听我的话。'),
('CNV', '以赛亚书', 23, 28, 24, '农夫怎会不断耕犁来撒种呢？他怎会常常开垦耕地呢？'),
('CNV', '以赛亚书', 23, 28, 25, '他犁平了地面，不就撒种小茴香，播种大茴香，按行列种小麦，在指定的地方种大麦，在田边种粗麦吗？'),
('CNV', '以赛亚书', 23, 28, 26, '因为他的神教导他，指教他正确的方法。'),
('CNV', '以赛亚书', 23, 28, 27, '打小茴香是不用尖耙的，轧大茴香也不用碾轮；而是用杖打小茴香，用棍打大茴香。'),
('CNV', '以赛亚书', 23, 28, 28, '做饼的谷粒怎么要碾碎的呢？从来没有人碾碎它们，虽然他让车轮和马匹辊过谷粒，却不会把他们碾碎。'),
('CNV', '以赛亚书', 23, 28, 29, '这也是出于万军之主，他的谋略奇妙，他的智慧广大。'),
('CNV', '以赛亚书', 23, 29, 1, '亚利伊勒、亚利伊勒（“亚利伊勒”意即“祭坛的炉”，代表耶路撒冷），大卫曾在此安营的城啊，有祸了！虽然你一年又一年按时举行节期，'),
('CNV', '以赛亚书', 23, 29, 2, '我却要使亚利伊勒受困苦，成了一座充满悲伤哀号的城，我要以它为亚利伊勒。'),
('CNV', '以赛亚书', 23, 29, 3, '我必四面安营攻击你，筑起攻城的台来围困你，堆起高垒攻击你。'),
('CNV', '以赛亚书', 23, 29, 4, '你必降低，从地中说话；你说的话必细微，如同出于尘土；你的声音必像交鬼者的声音，从地里出来；你的言语必像耳语般低微，如同出于尘土。'),
('CNV', '以赛亚书', 23, 29, 5, '但你敌人的数量必多如灰尘，那些强暴者的数量也多如被吹散的糠秕，这必在顷刻之间，突然发生。'),
('CNV', '以赛亚书', 23, 29, 6, '万军之主必用雷轰、地震、大声、旋风、暴风和吞灭人的火焰来惩罚他们。'),
('CNV', '以赛亚书', 23, 29, 7, '那时，所有攻击亚利伊勒的列国众军，就是所有攻击亚利伊勒和它的堡垒，以及迫害它的，必如梦景，如夜间的异象。'),
('CNV', '以赛亚书', 23, 29, 8, '又像饥饿的人在梦中吃饭，醒了以后，仍然觉得饥饿；又像口渴的人在梦中喝水，醒了以后，仍然觉得口渴，心里还是想喝。那攻打锡安山的列国众军，也必这样。'),
('CNV', '以赛亚书', 23, 29, 9, '你们留连吧，自我蒙蔽，继续盲目吧！你们醉了，却与酒无关，你们东倒西歪，也不是因为浓酒的缘故。'),
('CNV', '以赛亚书', 23, 29, 10, '因为主把沉睡的灵，倾倒在你们身上；他紧闭你们的眼，就是先知；蒙盖你们的头，就是先见。'),
('CNV', '以赛亚书', 23, 29, 11, '对你们来说，整个异象就像密封的书卷的话，人把这书卷交给识字的，说：“请念吧！”他必回答：“我不能念，因为它是密封的。”'),
('CNV', '以赛亚书', 23, 29, 12, '人又把这书卷交给不识字的人，说：“请念吧！”他必回答：“我不识字。”'),
('CNV', '以赛亚书', 23, 29, 13, '主说：“因为这子民只用言语来亲近我，用嘴唇尊崇我，他们的心却远离我。他们对我的敬畏，只是遵从传统的吩咐。'),
('CNV', '以赛亚书', 23, 29, 14, '因此，看哪！我要再向这子民施行奇事，就是奇妙又奇妙的事；他们智慧人的智慧必要消没，他们聪明人的聪明必被隐藏。”'),
('CNV', '以赛亚书', 23, 29, 15, '那些向主深藏谋略的人，有祸了！他们在暗中行事，说：“谁看见我们？谁知道我们？”'),
('CNV', '以赛亚书', 23, 29, 16, '你们颠倒事理了！窑匠怎能被看作泥土呢？被造的怎能对造它的说：“他没有造我”？制成品怎可对制成它的说：“他不聪明”？'),
('CNV', '以赛亚书', 23, 29, 17, '不是还有一点点的时候，黎巴嫩就要变为肥田，肥田就要被看为树林吗？'),
('CNV', '以赛亚书', 23, 29, 18, '到那日，聋子必听见这书卷上的话；瞎子的眼，必在迷蒙黑暗中也能看见。'),
('CNV', '以赛亚书', 23, 29, 19, '困苦的必因主增添喜乐；贫穷的人必因以色列的圣者而快乐。'),
('CNV', '以赛亚书', 23, 29, 20, '因为强暴人归于无有，好讥笑人的必被灭绝；所有意图行恶的，必被剪除。'),
('CNV', '以赛亚书', 23, 29, 21, '他们只用一句话就定了人的罪，又设下网罗来陷害城门口那执行裁判的，用毫无根据的事屈枉义人。'),
('CNV', '以赛亚书', 23, 29, 22, '因此，曾经救赎亚伯拉罕的主，论到雅各家时，这样说：“雅各今后必不再羞愧，他的面容也不再变为苍白，'),
('CNV', '以赛亚书', 23, 29, 23, '因为他看见了他的子孙在他中间，就是我手所作的。他们必尊我的名为圣，必尊雅各的圣者为圣，也必敬畏以色列的神。'),
('CNV', '以赛亚书', 23, 29, 24, '那些心中迷惑的，必明白真理，那些发怨言的，必接受教训。”'),
('CNV', '以赛亚书', 23, 30, 1, '主说：“这些悖逆的儿女有祸了！他们实行计谋，却不是出于我的意思，他们结盟，却不是出于我的灵，以致罪上加罪。'),
('CNV', '以赛亚书', 23, 30, 2, '他们起程下埃及去，并没有求问我，却要在法老的保护下，作避难处，投靠在埃及的荫庇下。'),
('CNV', '以赛亚书', 23, 30, 3, '因此，法老的保护必成为你们的羞耻，投靠在埃及的荫庇下，变成你们的耻辱。'),
('CNV', '以赛亚书', 23, 30, 4, '他们的领袖虽然已在琐安，他们的使臣虽然已到达哈内斯，'),
('CNV', '以赛亚书', 23, 30, 5, '但他们都必因那对于他们毫无利益的人民而蒙羞，那人民带来的不是帮助或益处，而是羞耻和凌辱。”'),
('CNV', '以赛亚书', 23, 30, 6, '以下是论南地野兽的默示：他们把财富驮在驴驹的背上，把宝物驮在骆驼的峰上，经过艰难困苦之地，就是公狮、母狮、蝮蛇和会飞的火蛇出没的地方，到一个对他们毫无益处的民族那里去。'),
('CNV', '以赛亚书', 23, 30, 7, '埃及的帮助是徒然的，是虚幻的，因此我称它为“坐而不动的拉哈伯”。'),
('CNV', '以赛亚书', 23, 30, 8, '现在你去，在他们面前把这话刻在版上，记在书卷上，作日后的证据，直到永永远远。'),
('CNV', '以赛亚书', 23, 30, 9, '因为这是悖逆的子民，不忠心的儿女，不肯听从主教导的儿女。'),
('CNV', '以赛亚书', 23, 30, 10, '他们对先见说：“你们不要再看异象！”又对先知说：“你们不要再向我说真确的预言！倒要向我说动听的话，预言虚幻的事吧！'),
('CNV', '以赛亚书', 23, 30, 11, '你们要离开正道，转离义路，不要在我们面前再提以色列的圣者了！”'),
('CNV', '以赛亚书', 23, 30, 12, '因此，以色列的圣者这样说：“因为你们弃绝了这话，反而信赖欺压和乖僻的手段，更以此为倚靠，'),
('CNV', '以赛亚书', 23, 30, 13, '所以这罪孽对于你们，必像一道有了裂缝，且凸了出来，快要倒塌的高墙，在顷刻之间，就突然倒塌。'),
('CNV', '以赛亚书', 23, 30, 14, '它的倒塌好像窑匠的瓦器破碎一般，毫不顾惜被彻底粉碎，甚至在碎块中找不到一块，可以用来从炉里取火，或从池中舀水。”'),
('CNV', '以赛亚书', 23, 30, 15, '因为主神以色列的圣者这样说：“你们得救在于悔改和安息，你们得力在于平静和信靠。”但你们竟不愿意。'),
('CNV', '以赛亚书', 23, 30, 16, '你们却说：“不！我们要骑马奔跑。”所以你们真的要逃跑；你们又说：“我们要骑快马。”所以那些追赶你们的，也必快速！'),
('CNV', '以赛亚书', 23, 30, 17, '一个敌人就可以威吓你们一千个人，若五个敌人威吓你们，你们都要逃跑了！以致你们所剩下的，必孤立如同山顶上的旗杆，冈陵上的旗帜。'),
('CNV', '以赛亚书', 23, 30, 18, '因此，主必等候要恩待你们；他必兴起来怜悯你们，因为主是公义的神。等候他的，都是有福的。'),
('CNV', '以赛亚书', 23, 30, 19, '锡安的人民、耶路撒冷的居民哪！你们必不再哭泣。他必因你哀求的声音恩待你；他听见的时候，就必应允你。'),
('CNV', '以赛亚书', 23, 30, 20, '主虽然以艰难给你们当食物，以困迫给你们当水，但你的教师必不再隐藏；你必亲眼看见你的教师。'),
('CNV', '以赛亚书', 23, 30, 21, '每当你偏左或偏右的时候，你必听见后面有声音说：“这是正路，要行在其中！”'),
('CNV', '以赛亚书', 23, 30, 22, '你要抛弃你那些包着银的雕像和镀了金的铸像，如同污秽之物一般抛弃它们，又对它们说：“去吧！”'),
('CNV', '以赛亚书', 23, 30, 23, '你撒在地里的种子，主必降雨在其上，并且使你地里所出产的粮食，既丰盛又肥美。到那日，你的牲畜必在宽阔的草场上吃草。'),
('CNV', '以赛亚书', 23, 30, 24, '耕地的牛和驴驹必吃加盐的饲料，就是用铲和叉所扬净的。'),
('CNV', '以赛亚书', 23, 30, 25, '在大行杀戮的日子，高台倒塌的时候，各高山冈陵都必有溪水涌流。'),
('CNV', '以赛亚书', 23, 30, 26, '主包扎他子民的伤口，医治他们伤痕的日子，月亮的光必像太阳的光；太阳的光必增加七倍，像七日的光一样。'),
('CNV', '以赛亚书', 23, 30, 27, '看哪！主的名从远方而来，他的怒气烧起，浓烟上腾；他的嘴唇充满忿怒，他的舌头像吞灭的火。'),
('CNV', '以赛亚书', 23, 30, 28, '他的气息如涨溢的河水，直涨到颈项，并要用毁灭的筛把列国筛净，又在众民口中放入使人步向灭亡的嚼环。'),
('CNV', '以赛亚书', 23, 30, 29, '你们却必歌唱，好像守圣节的夜间一样；你们必心里喜乐，好像吹着笛行走的人，必上主的山，到以色列的磐石那里。'),
('CNV', '以赛亚书', 23, 30, 30, '主必使人听见他威严的声音，在烈怒、吞灭一切火焰、大雨、暴风和冰雹之中，又使人看见他那降下来的膀臂。'),
('CNV', '以赛亚书', 23, 30, 31, '亚述人必因主的声音惊惶；主要用杖击打他们。'),
('CNV', '以赛亚书', 23, 30, 32, '主必把刑罚的杖加在他们身上，每打一下，都有击鼓和弹琴的声音；主在争战的时候，必挥动着手与他们争战。'),
('CNV', '以赛亚书', 23, 30, 33, '因为陀斐特那烧着的火早已安排好了，是为君王预备的，又深又宽；其中所堆的，是火和许多的柴；主的气像一股硫磺火，把它燃点起来。'),
('CNV', '以赛亚书', 23, 31, 1, '那些下埃及求帮助，倚靠马匹，倚靠众多战车，依靠十分强壮的马兵，却不仰望以色列的圣者，也不求问主的，有祸了！'),
('CNV', '以赛亚书', 23, 31, 2, '主是智慧的，他必降下灾祸，决不收回自己的话，却要起来攻击作恶者之家，又攻击那些助人作孽的。'),
('CNV', '以赛亚书', 23, 31, 3, '埃及人是人，并不是神；他们的马匹是血肉，并不是灵；主一伸手，那帮助人的就绊倒，那受帮助的也必仆倒，并且一同灭亡。'),
('CNV', '以赛亚书', 23, 31, 4, '因为主对我这样说：“狮子和少壮狮子怎样因捕获猎物而咆哮，虽然召集了许多的牧人来攻击它们，它们并不因他们的声音而惊慌，也不因他们的喧嚷而蹲伏；照样，万军之主必降临在锡安山和它的冈陵上争战。”'),
('CNV', '以赛亚书', 23, 31, 5, '雀鸟怎样搧翅护雏，万军之主也必照样保护耶路撒冷，他必保护和拯救，他必越过和搭救。'),
('CNV', '以赛亚书', 23, 31, 6, '以色列人哪！你们要回转，归向那曾被你们（“你们”直译是“他们”）彻底背弃的主。（本节或译“你们要回转，归向那曾被以色列人彻底背弃的主。”）'),
('CNV', '以赛亚书', 23, 31, 7, '到那日，各人都必抛弃自己的金偶像和银偶像，就是你们亲手所做，把自己陷在罪中的。'),
('CNV', '以赛亚书', 23, 31, 8, '亚述人必倒在刀下，不是人的刀；必有刀把他们吞灭，也不是人的刀。他们必不能逃避刀剑，他们的年轻人必作苦工。'),
('CNV', '以赛亚书', 23, 31, 9, '他们的磐石必因惊慌而挪去，他们的领袖必因见到以色列的旗帜而惊惶。这是那有火在锡安，有炉在耶路撒冷的主说的。'),
('CNV', '以赛亚书', 23, 32, 1, '看哪！必有一王凭公义执政，必有众领袖按公平治理。'),
('CNV', '以赛亚书', 23, 32, 2, '必有一人像避风所，和避暴雨的隐密处，像干旱之地的溪水，又像疲乏之地的大磐石的阴影。'),
('CNV', '以赛亚书', 23, 32, 3, '那时，能看见事物者的眼睛，必不再昏暗；能听到事物者的耳朵，必然倾听。'),
('CNV', '以赛亚书', 23, 32, 4, '性急者的心必明白知识，口吃者的舌头必说话清楚。'),
('CNV', '以赛亚书', 23, 32, 5, '愚顽人不再被称为高尚，恶棍也不再被称为大方。'),
('CNV', '以赛亚书', 23, 32, 6, '因为愚顽人说的是愚顽话，他心里所想的是罪孽，惯行亵渎神的事，说错谬的话攻击主，使饥饿的人仍空着肚子，使口渴的人仍无水可喝。'),
('CNV', '以赛亚书', 23, 32, 7, '至于恶棍，他的手段是邪恶的，他图谋恶计，用虚假的言语毁灭困苦的人，即使在穷乏人讲公理的时候，他也是这样。'),
('CNV', '以赛亚书', 23, 32, 8, '高尚的人却筹谋高尚的事，他也必坚持这些高尚的事。'),
('CNV', '以赛亚书', 23, 32, 9, '安逸的妇女啊！你们要起来，听我的声音；无忧无虑的女子啊！你们要侧耳听我的话。'),
('CNV', '以赛亚书', 23, 32, 10, '无忧无虑的女子啊！再过一年多，你们就必受困扰，因为没有葡萄可摘，收禾稼的日子也没有来。'),
('CNV', '以赛亚书', 23, 32, 11, '安逸的妇女啊！你们要受震惊。无忧无虑的女子啊！你们要受困扰了，脱去衣服，赤着身子，以麻布束腰吧。'),
('CNV', '以赛亚书', 23, 32, 12, '你们要为美好的田地和多结果子的葡萄树搥胸哀哭。'),
('CNV', '以赛亚书', 23, 32, 13, '也为那些在我子民的土地上长起来的荆棘和蒺藜而哀哭，为那欢乐的城和所有快乐的房屋，也是这样。'),
('CNV', '以赛亚书', 23, 32, 14, '因为宫殿必被丢弃，热闹的城市也被撇下，山冈和守望楼必永远成为洞穴，作了野驴喜欢的地方和羊群的草场。'),
('CNV', '以赛亚书', 23, 32, 15, '等到圣灵从高处倾倒在我们身上，旷野变为肥田，肥田被看为树林的时候，'),
('CNV', '以赛亚书', 23, 32, 16, '公平就必居在旷野中，公义必住在肥田里。'),
('CNV', '以赛亚书', 23, 32, 17, '公义的果效必是平安，公义的效验必是平静与安稳，直到永远。'),
('CNV', '以赛亚书', 23, 32, 18, '那时，我的子民必住在平安的居所，安稳的住处，不受骚扰的安息之处。'),
('CNV', '以赛亚书', 23, 32, 19, '但在敌人的国土中，必有冰雹降下，打倒他们的树林，他们的城必被夷平。'),
('CNV', '以赛亚书', 23, 32, 20, '你们这些在各水边撒种，又使牛驴随意走动的，是多么有福啊！'),
('CNV', '以赛亚书', 23, 33, 1, '你这毁灭人，自己却不被毁灭的；你这行事诡诈，别人倒不以诡诈待你的，有祸了！你刚停止毁灭人的时候，自己就要被毁灭；你刚停止行诡诈的时候，别人就必以诡诈待你。'),
('CNV', '以赛亚书', 23, 33, 2, '主啊！求你施恩给我们；我们等候你。每天早晨，愿你作我们的膀臂，在遭难的时候，作我们的拯救。'),
('CNV', '以赛亚书', 23, 33, 3, '喧嚷的声音一发，众民必逃跑；你一兴起，列国就四散。'),
('CNV', '以赛亚书', 23, 33, 4, '列国啊！你们所掳掠的必被收取，像蚂蚱收取禾稼一样；蝗虫怎样为食物忙碌走动，人也怎样在掳物上忙乱。'),
('CNV', '以赛亚书', 23, 33, 5, '主必被尊崇，因为他居住在高天；他必以公平与公义充满锡安。'),
('CNV', '以赛亚书', 23, 33, 6, '他是你一生一世的保障、丰盛的救恩、智慧和知识；敬畏主就是你的至宝。'),
('CNV', '以赛亚书', 23, 33, 7, '看哪！他们的勇士在街上呼叫；和平的使者在痛苦哭泣。'),
('CNV', '以赛亚书', 23, 33, 8, '大路荒凉，过路的人绝迹；敌人背约，藐视约章，不尊重任何人。'),
('CNV', '以赛亚书', 23, 33, 9, '大地悲哀衰残，黎巴嫩羞惭枯干；沙仑好像荒原，巴珊和迦密的树木凋零。'),
('CNV', '以赛亚书', 23, 33, 10, '主说：“现在我要起来，现在我要兴起，现在我要被人尊崇。'),
('CNV', '以赛亚书', 23, 33, 11, '你们所怀的是糠秕，所生的是碎秸；我的气息必像火一般吞灭你们。'),
('CNV', '以赛亚书', 23, 33, 12, '众民必像燃烧的石灰，又像被割下的荆棘，在火中焚烧。'),
('CNV', '以赛亚书', 23, 33, 13, '远方的人哪！你们要听我所作的事；近处的人哪！你们要承认我的大能。”'),
('CNV', '以赛亚书', 23, 33, 14, '在锡安的罪人都恐惧；战兢抓住了不敬虔的人：“我们中间谁能与吞灭一切的火同住呢？我们中间谁能与不断燃烧的火同住呢？”'),
('CNV', '以赛亚书', 23, 33, 15, '那行事公义，说话正直，拒绝不义的财利，摇手不受贿赂，塞耳不听血腥的事，闭眼不看邪恶的事的，'),
('CNV', '以赛亚书', 23, 33, 16, '这样的人必居住在高处，他的保障必在坚固的磐石上，他的粮食必有供应，他的水源永不断绝。'),
('CNV', '以赛亚书', 23, 33, 17, '你必亲眼看见王的荣美，必看见辽阔之地。'),
('CNV', '以赛亚书', 23, 33, 18, '你的心必默想已往的恐惧，说：“那记数目的在哪里？那称贡银的在哪里？那数点城楼的在哪里呢？”'),
('CNV', '以赛亚书', 23, 33, 19, '你必不再见那强暴的民了，就是那说话深奥，难以明白，舌头结巴，难以听懂的民。'),
('CNV', '以赛亚书', 23, 33, 20, '你要看着锡安，就是我们举行制定节期的城，你必看见耶路撒冷，是一个安全的居所，一个不挪移的帐幕，它的橛子永不会拔起来，它的绳索也不会扯断。'),
('CNV', '以赛亚书', 23, 33, 21, '在那里，威严的主必作我们江河宽渠溢流之地。必没有荡桨摇橹的船只能在其上往来，威武的战船也不能经过。'),
('CNV', '以赛亚书', 23, 33, 22, '因为主是我们的审判者，主是我们的立法者，主是我们的君王，他必拯救我们。'),
('CNV', '以赛亚书', 23, 33, 23, '现在你的绳索虽然松开，不能绑紧桅杆，也不能扬起帆来，但到那时，许多掳物必被你们瓜分，甚至瘸腿的也能把掠物掠去。'),
('CNV', '以赛亚书', 23, 33, 24, '以色列的居民必不再说：“我有病”；因为在其中居住的，罪孽必得赦免。'),
('CNV', '以赛亚书', 23, 34, 1, '列国啊，要近前来听！众民哪，要留心听！地和地上所充满的，世界和其中所出的一切，都要听！'),
('CNV', '以赛亚书', 23, 34, 2, '因为主向列国发怒，向他们所有的军队发烈怒，要把他们灭尽，要把他们交出来受屠杀。'),
('CNV', '以赛亚书', 23, 34, 3, '他们被杀的必被抛弃在外面，尸体的臭气上腾，众山都被他们的血所溶化。'),
('CNV', '以赛亚书', 23, 34, 4, '天上的万象都必消残；天也像书卷一般被卷起，所有星宿也必衰残，像葡萄树的叶子衰残一样，又像无花果树的叶子凋落一样。'),
('CNV', '以赛亚书', 23, 34, 5, '因为我的刀在天上已经喝足了，看哪！它要落在以东，以及我决定要灭绝的民身上，为要施行审判。'),
('CNV', '以赛亚书', 23, 34, 6, '主的刀染满了血，这刀因脂肪、羊羔和公山羊的血，以及公绵羊腰子的脂肪而滋润，因为主在波斯拉有杀牲献祭的事，在以东地有大屠杀。'),
('CNV', '以赛亚书', 23, 34, 7, '野牛、牛犊与壮牛要与他们一同倒下，他们的地喝足了血，他们的尘土因脂肪而肥润。'),
('CNV', '以赛亚书', 23, 34, 8, '因为主有报仇的日子，为锡安的案件，必有报应之年。'),
('CNV', '以赛亚书', 23, 34, 9, '以东的河水都要变成石油，它的尘土必变成硫磺，它的地土要变成烧着的石油，'),
('CNV', '以赛亚书', 23, 34, 10, '昼夜不熄，烟气永远上腾，并且必世世代代变为荒凉，永永远远无人经过。'),
('CNV', '以赛亚书', 23, 34, 11, '但鹈鹕与箭猪要占据那地，猫头鹰和乌鸦必住在其中。主必把混沌的准绳、空虚的线铊，拉在其上。'),
('CNV', '以赛亚书', 23, 34, 12, '它的显贵一个也没有了，以致不能称为一国，所有的领袖也没有了。'),
('CNV', '以赛亚书', 23, 34, 13, '以东的宫殿必长荆棘，它的堡垒必长蒺藜和刺草；它要作野狗的住处，作鸵鸟的居所。'),
('CNV', '以赛亚书', 23, 34, 14, '旷野的走兽必与豺狼相遇，野山羊必呼喊它的同伴；连夜间的怪物也必在那里栖身，为自己寻找休息的地方。'),
('CNV', '以赛亚书', 23, 34, 15, '箭蛇要在那里筑窝、下蛋、孵蛋，并且聚子在它的阴影下；鹞鹰也各与自己的伴偶，聚集在那里。'),
('CNV', '以赛亚书', 23, 34, 16, '你们要查考和阅读主的书卷；这些都无一缺少，也没有一个是没有伴偶的，因为他的口（按照《马索拉文本》，“他的口”作“我的口”；现参照《死海古卷》和其他古译本翻译）已吩咐了，他的灵已把它们聚集。'),
('CNV', '以赛亚书', 23, 34, 17, '他也为它们抽签，他的手用准绳给它们分地；它们必永远得着那地，也要世世代代住在其中。'),
('CNV', '以赛亚书', 23, 35, 1, '旷野和干旱之地必欢喜；沙漠要快乐，又像番红花一般开花，'),
('CNV', '以赛亚书', 23, 35, 2, '必茂盛地开花，大大快乐，并且欢呼。黎巴嫩的荣耀、迦密和沙仑的华美也赐给它；人们必看见主的荣耀、我们神的华美。'),
('CNV', '以赛亚书', 23, 35, 3, '你们要坚固无力的手，稳固摇动的膝。'),
('CNV', '以赛亚书', 23, 35, 4, '又对那些忧心的人说：“你们要刚强，不要惧怕。看哪！你们的神，他要来报仇，来施行报应，他必来拯救你们。”'),
('CNV', '以赛亚书', 23, 35, 5, '那时，瞎子的眼必打开，聋子的耳必畅通。'),
('CNV', '以赛亚书', 23, 35, 6, '那时，瘸子必像鹿一般跳跃，哑巴的舌头必大声欢呼；旷野必涌出大水，沙漠必流出江河。'),
('CNV', '以赛亚书', 23, 35, 7, '灼热的沙地必变为水池，干旱之地必变成泉源；在野狗的住处，就是它们躺卧之处，必成为青草、芦苇和蒲草生长的地方。'),
('CNV', '以赛亚书', 23, 35, 8, '那里必有一条大路，要称为“圣路”；不洁净的人不能经过，那是为那些行走正路的人预备的；愚昧的人不会在路上留连。'),
('CNV', '以赛亚书', 23, 35, 9, '那里必没有狮子，猛兽也不会上去，在那里必遇不见它们；只有蒙救赎的人在那里行走。'),
('CNV', '以赛亚书', 23, 35, 10, '蒙主赎回的人必归回，必欢呼地来到锡安；永远的喜乐必临到他们的头上；他们必得着欢喜和快乐，忧愁和叹息都必逃跑了。'),
('CNV', '以赛亚书', 23, 36, 1, '希西家王十四年，亚述王西拿基立上来攻击犹大所有的坚固城，并且把城攻取。'),
('CNV', '以赛亚书', 23, 36, 2, '亚述王从拉吉差派拉伯沙基，带领大军往耶路撒冷，到希西家王那里去。他站在上池的水沟旁，就是在往漂布地之大路上的时候，'),
('CNV', '以赛亚书', 23, 36, 3, '希勒家的儿子管家以利亚敬、书记舍伯那和亚萨的儿子史官约亚，都出来见他。'),
('CNV', '以赛亚书', 23, 36, 4, '拉伯沙基对他们说：“你们去对希西家说：‘亚述大王这样说：你所倚靠的算得是什么倚靠呢？'),
('CNV', '以赛亚书', 23, 36, 5, '我说：你打仗所用的谋略和能力，不过是虚话罢了。你到底倚靠谁，以致你背叛我呢？'),
('CNV', '以赛亚书', 23, 36, 6, '看哪！你所倚靠的埃及，是那压伤的芦苇杖；人若倚靠它，它就会插进他的手，把手刺透。埃及王法老对所有倚靠他的人，也是这样。'),
('CNV', '以赛亚书', 23, 36, 7, '你若对我说：我们倚靠主我们的神，这神所有的邱坛和祭坛岂不是都给希西家废去了，他还对犹大和耶路撒冷的人说：你们只要在这祭坛面前敬拜吗？'),
('CNV', '以赛亚书', 23, 36, 8, '现在你可以与我的主人亚述王打赌：我给你二千匹马，看你这一方面能否派出足够骑马的人来。'),
('CNV', '以赛亚书', 23, 36, 9, '若不能，你怎能击退我主的臣仆中最小的军长呢？你竟倚靠埃及的战车和马兵吗？'),
('CNV', '以赛亚书', 23, 36, 10, '现在，我上来攻打这地，要把这地毁灭，岂没有主的意思吗？主曾对我说：你要上去攻打这地，把它毁灭。’”'),
('CNV', '以赛亚书', 23, 36, 11, '以利亚敬、舍伯那和约亚对拉伯沙基说：“请你用亚兰语对你的仆人说话，因为我们听得懂；不要用犹大语对我们说话，免得城墙上的人民听见。”'),
('CNV', '以赛亚书', 23, 36, 12, '但拉伯沙基说：“我主差派我来，只是对你和你的主说这些话吗？不也是对那些坐在城墙上，要和你们一同吃自己的粪、喝自己的尿的人说吗？”'),
('CNV', '以赛亚书', 23, 36, 13, '于是拉伯沙基站着，用犹大语大声呼喊说：“你们要听亚述大王的话，'),
('CNV', '以赛亚书', 23, 36, 14, '王这样说：‘你们不要被希西家欺骗了，因为他决不能拯救你们；'),
('CNV', '以赛亚书', 23, 36, 15, '也不要给希西家说服你们倚靠主，说：主必定拯救我们，这城也必不交在亚述王的手中。’'),
('CNV', '以赛亚书', 23, 36, 16, '不要听希西家的话，因为亚述王这样说：‘你们要与我和好（“与我和好”直译是“向我祝福问安”），出来向我投降，这样各人就可以吃自己葡萄树和无花果树的果子，也可以喝自己井里的水；'),
('CNV', '以赛亚书', 23, 36, 17, '等到我来的时候，就会把你们领到一个与你们本地一样的地方；就是一个有五谷和新酒的地方，一个有粮食和葡萄园的地方。'),
('CNV', '以赛亚书', 23, 36, 18, '你们要小心，免得希西家怂恿你们说：主必拯救我们。列国的神有哪一位曾拯救自己的国土脱离亚述王的手呢？'),
('CNV', '以赛亚书', 23, 36, 19, '哈马和亚珥拔的神在哪里呢？西法瓦音的神在哪里呢？他们曾拯救撒玛利亚脱离我的手吗？'),
('CNV', '以赛亚书', 23, 36, 20, '这些国所有的神中，有哪一个曾拯救自己的国土脱离我的手呢？难道主能拯救耶路撒冷脱离我的手吗？’”'),
('CNV', '以赛亚书', 23, 36, 21, '众人都默不作声，一句话也没有回答他，因为王的吩咐说：“不要回答他。”'),
('CNV', '以赛亚书', 23, 36, 22, '于是希勒家的儿子管家以利亚敬、书记舍伯那和亚萨的儿子史官约亚，都撕裂衣服，来到希西家面前，把拉伯沙基的话告诉了他。'),
('CNV', '以赛亚书', 23, 37, 1, '希西家王听见了，就撕裂衣服，披上麻布，进了主的殿。'),
('CNV', '以赛亚书', 23, 37, 2, '他差派管家以利亚敬、书记舍伯那和祭司中的长老，都披上麻布，去见亚摩斯的儿子以赛亚先知。'),
('CNV', '以赛亚书', 23, 37, 3, '他们对他说：“希西家这样说：‘今日是急难、责罚和凌辱的日子，就像婴孩快要出生的时候，却没有气力生出来一样。'),
('CNV', '以赛亚书', 23, 37, 4, '也许主你的神听见拉伯沙基的话，就是他的主人亚述王派他来辱骂永活的神的话；主你的神会因他所听见的话斥责他；因此，求你为余剩下来的人献上祷告。’”'),
('CNV', '以赛亚书', 23, 37, 5, '希西家王的臣仆就去见以赛亚，'),
('CNV', '以赛亚书', 23, 37, 6, '以赛亚对他们说：“要对你们的主人这样说：‘主这样说：你不要因为听见亚述王的仆人亵渎我的话而害怕。'),
('CNV', '以赛亚书', 23, 37, 7, '看哪！我必使灵进入他里面，以致他听见风声就归回本地；我必使他在那里倒在刀下。’”'),
('CNV', '以赛亚书', 23, 37, 8, '拉伯沙基回去的时候，正遇见亚述王攻打立拿；原来他早已听闻亚述王拔营离开了拉吉。'),
('CNV', '以赛亚书', 23, 37, 9, '亚述王听到关于古实王特哈加的报告说：“他出来要与你争战”；亚述王听见了，就差派使者去见希西家，说：'),
('CNV', '以赛亚书', 23, 37, 10, '“你们要对犹大王希西家这样说：不要给你所倚靠的神欺骗你说：耶路撒冷必不交在亚述王的手里。'),
('CNV', '以赛亚书', 23, 37, 11, '你必定听过亚述列王向列国所行的，就是把她们完全毁灭，难道你还有救吗？'),
('CNV', '以赛亚书', 23, 37, 12, '我列祖所毁灭的国，有歌撒、哈兰、利色和在提．拉撒的伊甸人，这些国的神曾拯救她们吗？'),
('CNV', '以赛亚书', 23, 37, 13, '哈马的王、亚珥拔的王、西法瓦音城的王、希拿和以瓦的王，现在都在哪里呢？”'),
('CNV', '以赛亚书', 23, 37, 14, '希西家从使者手里接过信卷，读完了，就上主的殿，在主面前把信卷展开。'),
('CNV', '以赛亚书', 23, 37, 15, '希西家向主祷告说：'),
('CNV', '以赛亚书', 23, 37, 16, '“万军之主，以色列的神，坐在二基路伯中间的啊！唯独你是地上万国的神；你创造了天地。'),
('CNV', '以赛亚书', 23, 37, 17, '主啊，求你侧耳而听！主啊，求你开眼察看！要听西拿基立的一切话，就是那差派使者来辱骂永活的神的。'),
('CNV', '以赛亚书', 23, 37, 18, '主啊！亚述列王果然使列国和他们的土地变成荒凉，'),
('CNV', '以赛亚书', 23, 37, 19, '又把列国的神都扔进火中；因为他们不是神，只是人手所做的，不过是木头和石头，所以他们就灭绝了他们。'),
('CNV', '以赛亚书', 23, 37, 20, '主我们的神啊！现在求你拯救我们脱离亚述王的手，使地上万国都知道唯有你主是神。”'),
('CNV', '以赛亚书', 23, 37, 21, '亚摩斯的儿子以赛亚就派人去见希西家，说：“主以色列的神这样说：‘因为你向我祷告关于亚述王西拿基立的事，'),
('CNV', '以赛亚书', 23, 37, 22, '主就有以下的话攻击他，说：锡安的处女藐视你，嗤笑你；耶路撒冷的女子在你背后摇头。'),
('CNV', '以赛亚书', 23, 37, 23, '你辱骂谁、亵渎谁？你扬起声音，又高举眼目，要攻击谁？就是攻击以色列的圣者。'),
('CNV', '以赛亚书', 23, 37, 24, '你藉着你的臣仆辱骂主；你又说：我率领我众多的战车上了群山的高峰，到了黎巴嫩极深之处。我砍伐其中高大的香柏树和佳美的松树；我去到极高之处，进入肥田般的树林。'),
('CNV', '以赛亚书', 23, 37, 25, '我挖井和喝水；我用我的脚掌踏干埃及的河流。’'),
('CNV', '以赛亚书', 23, 37, 26, '主说：‘难道你没有听见古时我所安排，往昔所计划的吗？现在我才使它成就，使坚固的城镇荒废，变作乱堆。'),
('CNV', '以赛亚书', 23, 37, 27, '因此，其中的居民软弱无力，惊惶羞愧，像田间的蔬菜和青绿的草，又像房顶上的草，还没有长起来，就干焦了。'),
('CNV', '以赛亚书', 23, 37, 28, '你坐下，你出，你入，你向我发烈怒，我都知道。'),
('CNV', '以赛亚书', 23, 37, 29, '因为你向我发烈怒，又因你的狂傲达到我耳中，我要把钩子放进你的鼻孔，把嚼环放进你的嘴里，使你从你来的路上回去。'),
('CNV', '以赛亚书', 23, 37, 30, '希西家啊！这要作你的兆头：今年你们要吃自生的，明年还要吃自长的，后年你们就要撒种，要收割，要栽种葡萄园，吃园中的果子。'),
('CNV', '以赛亚书', 23, 37, 31, '犹大家所逃脱的余民，必再向下扎根，往上结果。'),
('CNV', '以赛亚书', 23, 37, 32, '因为余下的人必从耶路撒冷出来，逃脱的人必从锡安山出来。万军之主的热心必作成这事。’'),
('CNV', '以赛亚书', 23, 37, 33, '所以主这样论到亚述王，说：‘他必不会来到这城，也不会在这里射箭；不会拿着盾牌来到城前，也不会筑土垒攻城。'),
('CNV', '以赛亚书', 23, 37, 34, '他从哪条路来，也必从哪条路回去；他必不得进入这城；这是主的宣告。'),
('CNV', '以赛亚书', 23, 37, 35, '因我为自己的缘故，又为我仆人大卫的缘故，必保护这城，拯救这城。’”'),
('CNV', '以赛亚书', 23, 37, 36, '于是主的使者出去，在亚述营中击杀了十八万五千人；到了早晨，有人起来，所见的都是死尸。'),
('CNV', '以赛亚书', 23, 37, 37, '亚述王西拿基立就拔营离去，返回本地，住在尼尼微。'),
('CNV', '以赛亚书', 23, 37, 38, '他在自己的神尼斯洛庙里叩拜的时候，他的儿子亚得米勒和沙利色用刀杀了他，然后逃到亚拉腊地。他的儿子以撒哈顿接续他作王。'),
('CNV', '以赛亚书', 23, 38, 1, '那时，希西家患了重病，快要死去。亚摩斯的儿子以赛亚先知来见他，对他说：“主这样说：‘你要把你的家整顿妥当，因为你快要死去，不能存活。’”'),
('CNV', '以赛亚书', 23, 38, 2, '希西家就转脸向墙，对主祷告、'),
('CNV', '以赛亚书', 23, 38, 3, '说：“主啊！求你记念我在你面前怎样诚诚实实、以纯全的心来行事，又作你眼中看为善的事。”然后，希西家就痛哭起来。'),
('CNV', '以赛亚书', 23, 38, 4, '主的话临到以赛亚说：'),
('CNV', '以赛亚书', 23, 38, 5, '“你去告诉希西家：‘主你祖先大卫的神这样说：我听见了你的祷告，看见了你的眼泪；看哪！我必在你的寿数上加添十五年。'),
('CNV', '以赛亚书', 23, 38, 6, '我必救你和这城脱离亚述王的手；我必保护这城。’'),
('CNV', '以赛亚书', 23, 38, 7, '以下就是主给你的兆头，为要证明主必成全他所说过的。'),
('CNV', '以赛亚书', 23, 38, 8, '看哪！我要使亚哈斯日晷上那向前进的日影往后退十级。”于是那向前进的日影，果然在日晷上往后退了十级。'),
('CNV', '以赛亚书', 23, 38, 9, '犹大王希西家从病患中痊愈以后，就写了这诗：'),
('CNV', '以赛亚书', 23, 38, 10, '我曾说：在我盛年之际，我竟要进入阴间之门；我余剩的年日，竟被夺去。'),
('CNV', '以赛亚书', 23, 38, 11, '我曾说：在活人之地，我必不得见主；在世间的居民中，我必不再见到任何人。'),
('CNV', '以赛亚书', 23, 38, 12, '我的住处被拔起，迁离了我，像牧人的帐棚一样；我卷起我的性命，像织布的卷布一样；他把我从机头剪断；一日之间，他必使我生命终结。'),
('CNV', '以赛亚书', 23, 38, 13, '我不断哀叹，直到早晨，他像狮子一般，折断我所有的骨头；一日之间，他必使我生命终结。'),
('CNV', '以赛亚书', 23, 38, 14, '我像燕子呻吟，像白鹤鸣叫，又像鸽子哀鸣。我的眼睛因仰望高处而疲倦；主啊！我受欺压，求你作我的保障。'),
('CNV', '以赛亚书', 23, 38, 15, '我可说什么呢？他应许我的，已给我成全了；因我的心曾受过苦楚，所以我要谨慎地度我所有的年日。'),
('CNV', '以赛亚书', 23, 38, 16, '主啊！人活着是在于这些，我的灵存活，也在于这些。所以求你使我恢复健康，使我存活。'),
('CNV', '以赛亚书', 23, 38, 17, '看哪！我受尽苦楚，为要使我得平安；你保全我的性命，脱离毁灭的坑，因为你把我的一切罪都丢在你的背后。'),
('CNV', '以赛亚书', 23, 38, 18, '阴间不能称谢你，死亡不能赞美你，下坑的人都不能仰望你的信实。'),
('CNV', '以赛亚书', 23, 38, 19, '只有活人才能称谢你，像我今日一样；作父亲的，要让儿女知道你的信实。'),
('CNV', '以赛亚书', 23, 38, 20, '主必拯救我，因此我们要一生一世在主的殿中，用丝弦的乐器弹奏我的诗歌。'),
('CNV', '以赛亚书', 23, 38, 21, '以赛亚说：“叫人拿一块无花果饼来，贴在疮上，王就必痊愈。”'),
('CNV', '以赛亚书', 23, 38, 22, '希西家问：“我能上主的殿去，有什么兆头呢？”'),
('CNV', '以赛亚书', 23, 39, 1, '那时，巴比伦王巴拉但的儿子米罗达．巴拉但，听说希西家病了，又痊愈了，就派人送信和礼物给希西家。'),
('CNV', '以赛亚书', 23, 39, 2, '希西家就十分高兴，并且把他的宝库、银子、金子、香料和贵重的油，以及他整个武器库里和他府库里的一切物件，都给使者们看；他家里和他全国里的东西，希西家没有一样不给他们看。'),
('CNV', '以赛亚书', 23, 39, 3, '于是以赛亚先知来见希西家王，问他说：“这些人说了些什么？他们从哪里来见你？”希西家说：“他们是从远方的巴比伦来见我的。”'),
('CNV', '以赛亚书', 23, 39, 4, '以赛亚又问：“他们在你家里看见了什么？”希西家回答：“我家中所有的，他们都看了；我的财宝中，没有一样不给他们看。”'),
('CNV', '以赛亚书', 23, 39, 5, '以赛亚对希西家说：“你要听万军之主的话。'),
('CNV', '以赛亚书', 23, 39, 6, '看哪！日子必到，你家中所有的，以及你列祖所积蓄到今日的，都要被带到巴比伦去，一样也不留，这是主说的。'),
('CNV', '以赛亚书', 23, 39, 7, '从你所出的众子，就是你所生的，其中必有被掳去的，在巴比伦王宫里作太监。”'),
('CNV', '以赛亚书', 23, 39, 8, '希西家对以赛亚说：“你所说主的话不错呀！”因为他心里想：“在我有生之日，必有平安和稳固。”'),
('CNV', '以赛亚书', 23, 40, 1, '你们的神说：“你们要安慰，要安慰我的子民！'),
('CNV', '以赛亚书', 23, 40, 2, '你们要向耶路撒冷说慈爱的话，又要向它宣告：他们的苦难已经满足了，他们的罪孽已经还清了，他们因着自己的一切罪，已经从主的手里受到过重的刑罚。”'),
('CNV', '以赛亚书', 23, 40, 3, '有声音呼喊说：“你们要在旷野清理主的路，在沙漠修直我们神的大道。'),
('CNV', '以赛亚书', 23, 40, 4, '一切深谷都要填满，一切山冈都要削平；险峻的要改为平地，崎岖的要改为平原。'),
('CNV', '以赛亚书', 23, 40, 5, '主的荣耀必要显现，所有的人都必一同看见，因为这是主亲口说的。”'),
('CNV', '以赛亚书', 23, 40, 6, '有声音说：“你呼喊吧！”他问（“他问”或参照《死海古卷》和《七十士译本》翻译为“我说”）：“我呼喊什么呢？”“所有的人尽都如草；他们的荣美都像野地的花。'),
('CNV', '以赛亚书', 23, 40, 7, '草必枯干，花必凋谢；因为主的气吹在上面；真的，这民的确是草！'),
('CNV', '以赛亚书', 23, 40, 8, '草必枯干，花必凋谢，唯有我们神的道永远长存。”'),
('CNV', '以赛亚书', 23, 40, 9, '报好信息给锡安的啊！你要登上高山。报好信息给耶路撒冷的啊！你要极力扬声。要扬声，不要惧怕！要对犹大的众城说：“看哪，你们的神！”'),
('CNV', '以赛亚书', 23, 40, 10, '看哪！主神必像大能者临到，他的膀臂要为他掌权；看哪！他给予人的赏赐在他那里，他施予人的报应在他面前。'),
('CNV', '以赛亚书', 23, 40, 11, '他必像牧人牧养自己的羊群，像用膀臂聚集羊羔，抱在自己的怀中，慢慢引导乳养小羊的。'),
('CNV', '以赛亚书', 23, 40, 12, '谁曾用掌心量过海水，用手掌测过苍天呢？谁曾用升斗量过大地的尘土，用秤称山岭，用天平称冈陵呢？'),
('CNV', '以赛亚书', 23, 40, 13, '谁曾测度主的灵，或作过他的谋士教导他呢？'),
('CNV', '以赛亚书', 23, 40, 14, '他与谁商议，谁使他有聪明？谁把正确的路指教他，把知识指教他，又把明智的路教导他呢？'),
('CNV', '以赛亚书', 23, 40, 15, '看哪！万国都像水桶里的一滴，又被看作天平上的微尘。看哪！他举起众海岛，好像微细之物。'),
('CNV', '以赛亚书', 23, 40, 16, '黎巴嫩的树林不够当柴烧，其中的走兽也不够作燔祭。'),
('CNV', '以赛亚书', 23, 40, 17, '万国在他跟前好像不存在，在他看来，只是乌有和虚空。'),
('CNV', '以赛亚书', 23, 40, 18, '你们把谁来跟神相比呢？你们用什么形象来与神并列呢？'),
('CNV', '以赛亚书', 23, 40, 19, '至于偶像，是匠人铸造的，铸匠用金子把它包裹，用银子为它做银链。'),
('CNV', '以赛亚书', 23, 40, 20, '贫穷献不起这供物的，就拣选不朽坏的树木，为自己寻找巧匠，立起不会动摇的偶像。'),
('CNV', '以赛亚书', 23, 40, 21, '你们不曾知道吗？你们不曾听见吗？不是从起初就已经告诉过你们吗？自从大地的根基立了以来，你们还不曾明白吗？'),
('CNV', '以赛亚书', 23, 40, 22, '神坐在大地的圆穹之上，地上的居民好像蚱蜢，他铺张诸天如铺张幔子，展开众天像展开可以居住的帐棚。'),
('CNV', '以赛亚书', 23, 40, 23, '他使诸侯都归于无有，使地上的审判官成为虚空。'),
('CNV', '以赛亚书', 23, 40, 24, '他们才刚刚栽上，刚刚种上，他们的树头刚刚在地里扎根，他一吹在其上，他们就枯干了，旋风把他们像碎秸一样吹去。'),
('CNV', '以赛亚书', 23, 40, 25, '那圣者说：“你们把谁来跟我相比，使他与我相等呢？”'),
('CNV', '以赛亚书', 23, 40, 26, '你们向天举目吧！看是谁创造了这些万象？是谁按着数目把万象领出来，一一指名呼唤？因他的大能大力，连一个也不缺少。'),
('CNV', '以赛亚书', 23, 40, 27, '雅各啊！你为什么这样说；以色列啊！你为什么埋怨说：“我的道路向主隐藏，我的案件被我的神忽略了”？'),
('CNV', '以赛亚书', 23, 40, 28, '你不知道吗？你没有听过吗？永在的神、主、地极的创造主既不疲乏，也不困倦；他的知识无法测度。'),
('CNV', '以赛亚书', 23, 40, 29, '疲乏的，他赐气力，无力的，他加力量。'),
('CNV', '以赛亚书', 23, 40, 30, '就是年轻人也会疲乏困倦，强壮的人也会全然跌倒。'),
('CNV', '以赛亚书', 23, 40, 31, '但那些仰望主的人，必重新得力；他们必像鹰一样展翅上腾；他们奔跑，也不困倦，他们行走，也不疲乏。'),
('CNV', '以赛亚书', 23, 41, 1, '众海岛啊！你们要在我面前静默，愿万民重新得力。让他们近前来，然后说话，让我们聚在一起辩论吧！'),
('CNV', '以赛亚书', 23, 41, 2, '谁从东方激动了一个人，凭公义把他召到自己的脚前来？他把列国交在他面前，他制伏众王；他使他们在他的刀下化作灰尘，他使他们在他的弓下像碎秸一样被吹散。'),
('CNV', '以赛亚书', 23, 41, 3, '他追赶他们，安然走过他的脚未曾走过的路。'),
('CNV', '以赛亚书', 23, 41, 4, '谁定这事并且作成？谁从起初预定万代呢？就是我主，我是首先的，与最后的人同在的，也是我。'),
('CNV', '以赛亚书', 23, 41, 5, '众海岛看见了，就都惧怕；地极也都战兢；他们都近前来。'),
('CNV', '以赛亚书', 23, 41, 6, '各人彼此帮助，对自己的兄弟说：“要坚强！”'),
('CNV', '以赛亚书', 23, 41, 7, '木匠坚固金匠，用锤打光金属的，鼓励打砧的；论銲工说：“銲得好！”又用钉子钉稳了。使偶像不致动摇。'),
('CNV', '以赛亚书', 23, 41, 8, '但你以色列，我的仆人啊！雅各，我所拣选、我朋友亚伯拉罕的后裔啊！'),
('CNV', '以赛亚书', 23, 41, 9, '你是我从地极抓来的，我从地的远方召你来，对你说：“你是我的仆人，我拣选了你，并没有弃绝你。”'),
('CNV', '以赛亚书', 23, 41, 10, '不要惧怕，因为我与你同在；不要四处张望，因为我是你的神，我必坚固你，我必帮助你；我必用公义的右手扶持你。'),
('CNV', '以赛亚书', 23, 41, 11, '看哪！向你发怒的都必蒙羞受辱；与你相争的人，都要如同无有，并要灭亡。'),
('CNV', '以赛亚书', 23, 41, 12, '与你争竞的人，你要寻找他们，却找不着；与你交战的人，都必如同无有，好像虚无。'),
('CNV', '以赛亚书', 23, 41, 13, '因为我，主你们的神，紧握着你的右手，对你说：“不要惧怕，我必帮助你。”'),
('CNV', '以赛亚书', 23, 41, 14, '虫子雅各啊！以色列人哪！你不要惧怕。我必帮助你；这是主说的。你的救赎主，就是以色列的圣者。'),
('CNV', '以赛亚书', 23, 41, 15, '看哪！我要使你成为打粮的器具，又新，又锋利，又有很多利齿；你要扬净群山，把它们压得粉碎，又使冈陵变成糠秕。'),
('CNV', '以赛亚书', 23, 41, 16, '你必簸扬它们，风要把它们吹去，旋风也要把它们吹散；但你要靠主喜乐，以以色列的圣者夸耀。'),
('CNV', '以赛亚书', 23, 41, 17, '困苦和贫穷的人寻求水，却没有水；他们的舌头因口渴而干燥；我主必应允他们，我以色列的神必不离弃他们。'),
('CNV', '以赛亚书', 23, 41, 18, '我要在光秃的高处开辟江河，在山谷之间开辟泉源；我要使旷野变为水池，使干地变成水泉。'),
('CNV', '以赛亚书', 23, 41, 19, '我要在旷野种上香柏树、皂荚树、番石榴树和野橄榄树；我要在沙漠中栽种松树、杉树和黄杨树，'),
('CNV', '以赛亚书', 23, 41, 20, '好叫人看见了，就知道；思想过，就都明白，这是主的手所作的，是以色列的圣者所造的。'),
('CNV', '以赛亚书', 23, 41, 21, '主说：“呈上你们的案件吧！”雅各的王说：“把你们有力的证据拿来吧！”'),
('CNV', '以赛亚书', 23, 41, 22, '让它们前来告诉我们将要发生的事。以前的是什么事，让它们告诉我们，好叫我们用心思想，得知事情的结局。或者向我们宣告那要来的事。'),
('CNV', '以赛亚书', 23, 41, 23, '把以后要来的事告诉我们，好叫我们知道你们是神；你们作这些事，或降福或降祸，以致我们彼此对望，一齐观看。'),
('CNV', '以赛亚书', 23, 41, 24, '看哪！你们属于无有，你们的作为都属于虚空，那选择你们的是可厌恶的。'),
('CNV', '以赛亚书', 23, 41, 25, '我从北方兴起一人，他就来了；他从日出之地而来，呼求我的名；他必来践踏掌权的，好像践踏灰泥，又像陶匠踹泥一样。'),
('CNV', '以赛亚书', 23, 41, 26, '谁从起初讲说这事，使我们知道呢？谁从先前说明，以致我们说“他没有错”呢？谁也没有说明，谁也没有宣告，谁也没有听见你们的话！'),
('CNV', '以赛亚书', 23, 41, 27, '我首先对锡安说：“看哪，看看这些！”我要把一位报好信息的赐给耶路撒冷。'),
('CNV', '以赛亚书', 23, 41, 28, '我看的时候，却没有一个人；他们中间也没有谋士，我问他们的时候，可以回答一句话。'),
('CNV', '以赛亚书', 23, 41, 29, '看哪！他们都是无有，他们所作的都是虚无；他们所铸的偶像都是风，都是虚空。'),
('CNV', '以赛亚书', 23, 42, 1, '看哪！这是我的仆人，我扶持他；我所拣选的，我的心喜悦他；我已经把我的灵赐给他，他必把公理带给万国。'),
('CNV', '以赛亚书', 23, 42, 2, '他不呼喊，也不扬声，也不叫人在街上听见他的声音。'),
('CNV', '以赛亚书', 23, 42, 3, '压伤的芦苇，他不折断；将熄灭的灯火，他不吹灭；他忠实地传出公理。'),
('CNV', '以赛亚书', 23, 42, 4, '他不灰心，也不沮丧，直到他在地上设立公理，众海岛的人都等候他的教训。'),
('CNV', '以赛亚书', 23, 42, 5, '那创造诸天，展开穹苍，铺张大地和大地所出的一切，赐气息给地上的众人，又赐灵性给在地上行的人的主神这样说：'),
('CNV', '以赛亚书', 23, 42, 6, '“我主凭着公义呼召了你；我必紧拉着你的手，我必保护你，立你作人民的约，作列国的光，'),
('CNV', '以赛亚书', 23, 42, 7, '为要开瞎子的眼，领被囚的出牢狱，领住在黑暗中的出监牢。'),
('CNV', '以赛亚书', 23, 42, 8, '我是主，这是我的名；我必不把我的荣耀归给别人，也不把我当受的称赞归给雕刻的偶像。'),
('CNV', '以赛亚书', 23, 42, 9, '看哪！先前预言过的事已经成就了，现在我说明新的事；它们还没有发生以前，我就先说给你们听了。”'),
('CNV', '以赛亚书', 23, 42, 10, '所有航海的和海中所充满的，众海岛和其上的居民哪！你们都要向主唱新歌，从地极向他发出赞美。'),
('CNV', '以赛亚书', 23, 42, 11, '愿旷野和其中的城镇都扬声；愿基达人居住的村庄都高呼；愿西拉的居民都欢呼，在山顶上吶喊。'),
('CNV', '以赛亚书', 23, 42, 12, '愿他们把荣耀归给主，在众海岛中宣扬对他的颂赞。'),
('CNV', '以赛亚书', 23, 42, 13, '主必像勇士出战，必像战士激动热心；他要呼喊，大声吶喊，要向仇敌显出自己的威猛。'),
('CNV', '以赛亚书', 23, 42, 14, '我已经很久缄默不言，闭口不语，但现在我要像待产的妇人一样呼喊，我要急速地喘气。'),
('CNV', '以赛亚书', 23, 42, 15, '我必使大山小山都变为荒场，使一切草木都枯干；我要使江河变为干地，使水池干涸。'),
('CNV', '以赛亚书', 23, 42, 16, '我必领瞎子走陌生的道，带他们走他们不知道的路。我必在他们面前使黑暗变为光明，使弯曲的地方变为平直。这些事我都要作，决不放弃。'),
('CNV', '以赛亚书', 23, 42, 17, '那些倚靠偶像，对铸像说：“你们是我们的神”的，必被赶逐，全然蒙羞。'),
('CNV', '以赛亚书', 23, 42, 18, '聋子啊！你们要听。瞎子啊！你们要留心去看。'),
('CNV', '以赛亚书', 23, 42, 19, '有谁比我的仆人更瞎呢？有谁比我差派的使者更聋呢？有谁瞎眼像那与我立了和约的呢？有谁瞎眼像主的仆人呢？'),
('CNV', '以赛亚书', 23, 42, 20, '你们看见了许多的事，却没有留心，耳朵开着，却没有听见。'),
('CNV', '以赛亚书', 23, 42, 21, '主为自己公义的缘故，喜欢使律法为大为尊。'),
('CNV', '以赛亚书', 23, 42, 22, '但这人民是被抢劫和被掠夺的，全都困陷在洞穴中，被收藏在监牢里；他们作了掠物，无人搭救；他们成了掳物，无人说：“要归还！”'),
('CNV', '以赛亚书', 23, 42, 23, '你们中间谁肯听这话呢？谁肯从今以后留心听呢？'),
('CNV', '以赛亚书', 23, 42, 24, '谁把雅各交出来给掠夺者？谁把以色列交给抢劫的呢？岂不是主，就是我们得罪的那位吗？因为他们不肯遵行他的道，也不肯听从他的律法。'),
('CNV', '以赛亚书', 23, 42, 25, '因此，他把他猛烈的怒气和惨酷的战争，倾倒在他身上；这在他四周如火烧起来，他还不知道；把他烧着了，他也不放在心上。'),
('CNV', '以赛亚书', 23, 43, 1, '但是，雅各啊！那创造你的主，以色列啊！那塑造你的主，现在这样说：“不要惧怕，因为我救赎了你；我按着你的名呼召了你；你是属我的。'),
('CNV', '以赛亚书', 23, 43, 2, '你从水中经过的时候，我必与你同在；你渡过江河的时候，水必不淹没你；你从火中行走的时候，必不会烧伤；火焰也不会在你身上烧起来。'),
('CNV', '以赛亚书', 23, 43, 3, '因为我是主你的神，是以色列的圣者，你的拯救者；我使埃及作你的赎价，使古实和示巴作你的替身。'),
('CNV', '以赛亚书', 23, 43, 4, '因为你在我眼中非常宝贵和贵重，所以我爱你；我使别人作你的替身，同别的民族交换你的性命。'),
('CNV', '以赛亚书', 23, 43, 5, '你不要惧怕，因为我与你同在；我必把你的后裔从东方领回来，又从西方招聚你。'),
('CNV', '以赛亚书', 23, 43, 6, '我要对北方说：‘把他们交出来！’又对南方说：‘不要拘留他们！’要把我的众子从远方带回来，把我的女儿从地极领回来，'),
('CNV', '以赛亚书', 23, 43, 7, '就是所有按着我的名被召的人，是我为自己的荣耀创造的，是我所塑造，所作成的。”'),
('CNV', '以赛亚书', 23, 43, 8, '你要把那些有眼却看不见，有耳却听不到的人民领出来。'),
('CNV', '以赛亚书', 23, 43, 9, '列国都聚集在一起，万族都集合起来，他们中间谁能说明这事呢？谁能把先前的事说给我们听呢？让他们带出自己的见证人来，好显明自己为义；让别人听见了，就说：“这是真的。”'),
('CNV', '以赛亚书', 23, 43, 10, '主说：“你们就是我的见证人，我所拣选的仆人，为要使你们知道，并且相信我，又明白我就是‘那位’；在我以前没有神被造出来，在我以后也必没有。'),
('CNV', '以赛亚书', 23, 43, 11, '唯有我是主；除我以外，并没有拯救者。'),
('CNV', '以赛亚书', 23, 43, 12, '我曾预告，我曾拯救，我曾说给你们听，在你们中间没有别的神。”主说：“你们是我的见证人，我就是神。'),
('CNV', '以赛亚书', 23, 43, 13, '自头一天以来，我就是‘那位’；谁也不能救人脱离我的手；我要行事，谁能拦阻呢？”'),
('CNV', '以赛亚书', 23, 43, 14, '你们的救赎主、以色列的圣者、主这样说：“因为你们的缘故，我已经派人到巴比伦去，我要使所有的迦勒底人都像难民一样下来，都坐在他们素来自夸的船下来。'),
('CNV', '以赛亚书', 23, 43, 15, '我就是主，你们的圣者，是以色列的创造主、你们的王。”'),
('CNV', '以赛亚书', 23, 43, 16, '主这样说：他在海中开了一条道，在大水中辟了一条路；'),
('CNV', '以赛亚书', 23, 43, 17, '他使战车、马匹、军兵和勇士都一同出来，他们都躺下去，不能再起来；他们都灭没，好像灯火熄灭一样。'),
('CNV', '以赛亚书', 23, 43, 18, '“你们不要怀念先前的事，也不要思念古时的事。'),
('CNV', '以赛亚书', 23, 43, 19, '“看哪！我要作一件新的事；现在它要发生了，难道你们还不知道吗？我要在旷野开一条道路，在荒地开挖江河。'),
('CNV', '以赛亚书', 23, 43, 20, '野地的走兽必尊重我，野狗和鸵鸟也必这样，因为我使旷野有水，使荒地有江河，好使我拣选的子民有水喝，'),
('CNV', '以赛亚书', 23, 43, 21, '就是我为自己所造的子民，好使他们述说赞美我的话。'),
('CNV', '以赛亚书', 23, 43, 22, '然而，雅各啊！你并没有呼求我。以色列啊！你竟厌烦我。'),
('CNV', '以赛亚书', 23, 43, 23, '作燔祭用的羊，你没有带来给我；也没有用你的祭物来尊敬我；我没有因献供物使你劳累；也没有因献乳香使你厌烦。'),
('CNV', '以赛亚书', 23, 43, 24, '你没有用银子为我买菖蒲，也没有用祭物的脂肪使我饱足；相反地，你用你的罪使我劳累，你用你的罪孽使我厌烦。'),
('CNV', '以赛亚书', 23, 43, 25, '“唯有我为自己的缘故，涂抹你的过犯，我也不再记念你的罪。'),
('CNV', '以赛亚书', 23, 43, 26, '你可以提醒我，我们可以一起辩论；你尽管细说案情，好使你自显为义。'),
('CNV', '以赛亚书', 23, 43, 27, '你的祖先犯了罪，你的代表背叛了我。'),
('CNV', '以赛亚书', 23, 43, 28, '所以我要辱没圣所里的领袖，使雅各遭受毁灭，使以色列被凌辱。”'),
('CNV', '以赛亚书', 23, 44, 1, '“但现在，我的仆人雅各，我所拣选的以色列啊！你要听。'),
('CNV', '以赛亚书', 23, 44, 2, '那创造你，从母胎里就塑造了你，又要帮助你的主这样说：我的仆人雅各啊！我所拣选的耶书仑啊！你不要惧怕。'),
('CNV', '以赛亚书', 23, 44, 3, '因为我要把水浇灌干渴之处，把河水浇灌干旱之地；我必把我的灵浇灌你的后裔，把我的福降给你的子孙。'),
('CNV', '以赛亚书', 23, 44, 4, '他们要从草中生长起来，像溪水旁的柳树。'),
('CNV', '以赛亚书', 23, 44, 5, '这个必说：‘我是属主的’；那个也必以雅各的名称呼自己；另一个必亲手写上‘我是属主的’，并且要以以色列的名字替自己命名。”'),
('CNV', '以赛亚书', 23, 44, 6, '主以色列的王，以色列的救赎主、万军之主这样说：“我是首先的，我是末后的；除我以外，再没有真神。'),
('CNV', '以赛亚书', 23, 44, 7, '谁像我呢？让他宣告，让他述说，又在我面前陈明吧！自从我设立古时的子民，未来的事和将要发生的事，让他们把它们述说出来吧！'),
('CNV', '以赛亚书', 23, 44, 8, '你们不要惊惶，也不要惧怕。我不是老早就说了给你们听，告诉了你们吗？你们就是我的见证人。除我以外，还有真神吗？没有别的磐石；我一个也不知道。”'),
('CNV', '以赛亚书', 23, 44, 9, '制造偶像的人，尽都是虚空的，他们所喜爱的，都没有益处。他们的见证人，一无所见，一无所知，以致他们蒙羞。'),
('CNV', '以赛亚书', 23, 44, 10, '谁制造神像，或铸造偶像，不想得到益处呢？'),
('CNV', '以赛亚书', 23, 44, 11, '看哪！所有与它同伙的都必蒙羞；工匠也不过是人罢了。让他们都集合起来，都站立起来；让他们都惧怕，都一同蒙羞。'),
('CNV', '以赛亚书', 23, 44, 12, '铁匠先用工具在铁上雕刻，然后在火炭中加工，再用锤子把铁锤成形状，用他有力的膀臂锤成。他若饥饿，就没有力量；他若不喝水，就疲乏。'),
('CNV', '以赛亚书', 23, 44, 13, '木匠拉线，用笔画出轮廓，用刨子刨平，用圆规画出模样，做成人的形状，有人一般的美丽，好住在庙里。'),
('CNV', '以赛亚书', 23, 44, 14, '他为自己砍伐香柏树，或选取榆树和橡树，让它在树林中长起来；他栽种松树，让雨水使它长大。'),
('CNV', '以赛亚书', 23, 44, 15, '人可以用这树作燃料，可以拿来生火取暖，又可以烧着烤饼；人竟然用它做神像敬拜，他做了雕刻的偶像，又向它叩拜。'),
('CNV', '以赛亚书', 23, 44, 16, '他把木头的一半放在火里燃烧；在上面烤肉；吃了烤肉，并且吃饱了，就自己烤火取暖，说：“哈哈！我暖和了，我看见火了。”'),
('CNV', '以赛亚书', 23, 44, 17, '他用剩下来的一半做了一个神像，就是他雕刻的偶像，他向它俯伏，向它敬拜，又向它祷告，说：“求你救我，因为你是我的神。”'),
('CNV', '以赛亚书', 23, 44, 18, '他们并不知道，也不明白；因为主闭住他们的眼睛，使他们不能看见，塞住他们的心，使他们不能明白。'),
('CNV', '以赛亚书', 23, 44, 19, '没有人细心思想，也没有人有知识有聪明说：“我把木头的一半放在火里燃烧，我也在炭火上烘过饼，烤过肉吃，剩下的，我却用来做了一个可憎之物，我要向木头叩拜吗？”'),
('CNV', '以赛亚书', 23, 44, 20, '他所追求的只是灰尘，被迷惑了的心使他偏离正道了；他不能救自己，也不会说：“在我的右手中不是有个假神吗？”'),
('CNV', '以赛亚书', 23, 44, 21, '雅各和以色列啊！要记念这些话，因为你是我的仆人。我造了你，是要你作我的仆人；以色列啊！你必不会被我忘记。'),
('CNV', '以赛亚书', 23, 44, 22, '我涂抹了你的过犯，像密云消散；我涂抹了你的罪恶，如薄云灭没，你当归向我，因为我救赎了你。'),
('CNV', '以赛亚书', 23, 44, 23, '诸天啊！你们要欢呼，因为主作成了这事。地的深处啊！你们要吶喊。群山啊！你们要发声欢呼。树林和其中所有的树啊！你们都当这样。因为主救赎了雅各，他要藉着以色列使自己得荣耀。'),
('CNV', '以赛亚书', 23, 44, 24, '你的救赎主，就是那在母胎中就造了你的主这样说：“我主是创造万物的，我是独自展开诸天，铺张大地的。'),
('CNV', '以赛亚书', 23, 44, 25, '我使说假话者的兆头失效，使占卜者都变成愚昧人；我使有智慧的人后退，使他们的知识变为愚拙。'),
('CNV', '以赛亚书', 23, 44, 26, '我使我仆人的话实现，使我使者的谋算成就。我对耶路撒冷说：‘你必有人居住。’对犹大的城镇说：‘你们要再被建造起来，至于其中的废墟，我必重建它们。’'),
('CNV', '以赛亚书', 23, 44, 27, '我对深渊说：‘你干了吧，我必使你的江河干涸！’'),
('CNV', '以赛亚书', 23, 44, 28, '我对古列说：‘我的牧人；他必成就我所喜悦的一切。’他要对耶路撒冷说：‘你必被重建起来！’他必对圣殿说：‘你的根基要奠定！’”'),
('CNV', '以赛亚书', 23, 45, 1, '“我主所膏立的古列，我紧握着他的右手，使列国降服在他面前；我也松开列王的腰带；我使门户在他面前敞开，使城门不得关闭；主对古列这样说：'),
('CNV', '以赛亚书', 23, 45, 2, '我必亲自领导你，把高低不平的路修平；铜门，我必打破；铁门，我必砍断。'),
('CNV', '以赛亚书', 23, 45, 3, '我必把隐藏的宝物和在隐密处的财宝赐给你，使你知道我就是按着你的名呼召了你的主，以色列的神。'),
('CNV', '以赛亚书', 23, 45, 4, '因我的仆人雅各和我所拣选的以色列的缘故，我按着你的名呼召了你；你虽然不认识我，我却给你这个尊贵的名号。'),
('CNV', '以赛亚书', 23, 45, 5, '“我是主，再没有别的神了；除了我以外，并没有真神；你虽然不认识我，我必坚固你，'),
('CNV', '以赛亚书', 23, 45, 6, '为要叫从日出之地到日落之地的人都知道，除了我以外，没有真神；我是主，再没有别的神了。'),
('CNV', '以赛亚书', 23, 45, 7, '我造光，也造黑暗；我赐平安，也降灾祸；我主是造成这一切事的。'),
('CNV', '以赛亚书', 23, 45, 8, '诸天啊！你们要从上滴下公义，让云层降下公义。让大地裂开，生出救恩，使公义一同生长，是我主创造了这事。'),
('CNV', '以赛亚书', 23, 45, 9, '那与他的创造主争论的，有祸了！他不过是地上瓦片中的一片瓦片，泥土能对陶匠说：‘你在作什么？’或你所作成的说：‘他没有手’吗？'),
('CNV', '以赛亚书', 23, 45, 10, '那对父亲说：‘你生的是什么’，或对母亲说：‘你产的是什么’的，有祸了！”'),
('CNV', '以赛亚书', 23, 45, 11, '以色列的圣者，造以色列的主神这样说：“你们可以问我将要来的事，关于我的众子和我手所作的，你们也可以吩咐我回答。'),
('CNV', '以赛亚书', 23, 45, 12, '我造了地，又造了人在地上；我亲手展开了诸天，又命定了天上的万象。'),
('CNV', '以赛亚书', 23, 45, 13, '我凭着公义兴起了古列，我必修平他的一切道路；他必建造我的城，释放我被掳的子民，不必用工价，也不用赏赐，这是万军之主说的。”'),
('CNV', '以赛亚书', 23, 45, 14, '主这样说：“埃及劳碌得来的和古实所得之利，以及身量高大的西巴人，都必过来归你，也要属你；他们必带着锁链过来随从你，向你俯伏，向你恳求，说：‘神真的在你们中间，此外，再没有别的神，没有别的真神。’”'),
('CNV', '以赛亚书', 23, 45, 15, '拯救者以色列的神啊！你实在是隐藏自己的神。'),
('CNV', '以赛亚书', 23, 45, 16, '制造偶像的都必蒙羞受辱，都要一同归于羞愧。'),
('CNV', '以赛亚书', 23, 45, 17, '唯有以色列必靠着主得救，得着永远的拯救；你们必不蒙羞，也不受辱，直到永远。'),
('CNV', '以赛亚书', 23, 45, 18, '因为创造诸天的主，他是神，塑造大地，把大地造成；他坚立大地；他创造大地，不是荒凉的；他塑造大地，是要给人居住；他这样说：“我是主，再没有别的神。'),
('CNV', '以赛亚书', 23, 45, 19, '我没有在隐密处、在黑暗之地说过话；我没有对雅各的后裔说过：‘你们寻求我是徒然的。’我主讲说公义，宣扬正直。'),
('CNV', '以赛亚书', 23, 45, 20, '“列国逃脱的人哪！你们要来集合，一同近前来。那些抬着木头做的偶像，向不能拯救人的神祈求的，真是无知。'),
('CNV', '以赛亚书', 23, 45, 21, '你们述说吧！提出理由吧！让他们彼此商议吧！谁从古时使人听见这事呢？谁从上古把这事述说出来呢？不是我主吗？除了我以外，再没有神，我是公义的神，又是拯救者；除了我以外，并没有别的神。'),
('CNV', '以赛亚书', 23, 45, 22, '全地的人哪！你们都要归向我，都要得救。因为我是神，再没有别的神。'),
('CNV', '以赛亚书', 23, 45, 23, '我指着自己起誓，我的口凭着公义说出的话，决不改变：‘万膝都必向我跪拜，万口都要指着我起誓。’'),
('CNV', '以赛亚书', 23, 45, 24, '人论到我必说：‘只有在主里面才有公义和能力’；向他发怒的，都必来到他面前，并且要蒙羞。'),
('CNV', '以赛亚书', 23, 45, 25, '以色列所有的后裔，都必靠主得称为义，并要夸胜。”'),
('CNV', '以赛亚书', 23, 46, 1, '彼勒俯伏，尼波弯腰；巴比伦人的偶像驮在走兽和牲口上。你们所抬的现在都成了重担，成了疲乏的牲畜身上的重负。'),
('CNV', '以赛亚书', 23, 46, 2, '它们一同弯腰、俯伏，不能保护重负，它们自己反倒被掳去了。'),
('CNV', '以赛亚书', 23, 46, 3, '“雅各家啊，以色列家所有余剩的人哪！你们都要听我的话，你们自出母腹，就蒙我怀抱；自出母胎，就蒙我提携。'),
('CNV', '以赛亚书', 23, 46, 4, '直到你们年老，我还是一样；直到你们发白，我仍然怀抱你。我以前既然这样作了，以后我仍必提携你；我必怀抱你，也必拯救你。'),
('CNV', '以赛亚书', 23, 46, 5, '你们要把谁与我相比，谁与我相似呢？你们把谁与我比较，好使我们同等呢？'),
('CNV', '以赛亚书', 23, 46, 6, '那些从钱袋倒出金子，用天平称银子的人，雇用金匠制造神像；他们向神像又俯伏又叩拜。'),
('CNV', '以赛亚书', 23, 46, 7, '他们把神像抬起来，扛在肩头上，然后把它安置在固定的地方，它就立在那里，总不离开它的本位。虽然有人向它呼求，它也不能回答；它也不能救人脱离患难。'),
('CNV', '以赛亚书', 23, 46, 8, '“你们当记念这事，要坚定不移；悖逆的人哪！你们要留心思想。'),
('CNV', '以赛亚书', 23, 46, 9, '你们当记念上古以前的事，因为我是神，再没有别的神；我是神，没有神像我。'),
('CNV', '以赛亚书', 23, 46, 10, '我从起初就宣告末后的事，从古时就述说还未作成的事，说：‘我的计划必定成功，我所喜悦的，我都必作成。’'),
('CNV', '以赛亚书', 23, 46, 11, '我把鸷鸟从日出之地召来，就是把成就我计划的人从远方召来。我不但说了，而且也要使我的话实现；我不但计划好了，而且也必实行。'),
('CNV', '以赛亚书', 23, 46, 12, '心里顽固的人哪！远离公义的人哪！你们要听我。'),
('CNV', '以赛亚书', 23, 46, 13, '我使我的公义临近了，必不远离；我的救恩必不迟延。我要为以色列，我的荣耀，在锡安施行拯救。”'),
('CNV', '以赛亚书', 23, 47, 1, '巴比伦的处女啊！你下来，坐在尘土中吧！迦勒底的女儿啊！你坐在地上吧！没有宝座了，因为你必不再被称为柔弱娇嫩的了。'),
('CNV', '以赛亚书', 23, 47, 2, '你要拿石磨去磨面，你要揭开你的帕子，脱去长裙，露出大腿，渡过江河。'),
('CNV', '以赛亚书', 23, 47, 3, '你的下体必暴露出来，你的羞耻要被人看见；我必报仇，不顾惜任何人。'),
('CNV', '以赛亚书', 23, 47, 4, '我们的救赎主，他的名字是万军之主、以色列的圣者，他说：'),
('CNV', '以赛亚书', 23, 47, 5, '“迦勒底的女子啊！你要静静坐下，进到黑暗中去，因为人不再称你为列国之后了。'),
('CNV', '以赛亚书', 23, 47, 6, '我曾对我的子民发怒，使我的产业被亵渎，我把他们交在你的手里，你却对他们毫无怜悯。你竟把你的轭，重重压在老年人的身上。'),
('CNV', '以赛亚书', 23, 47, 7, '你曾说：‘我必永远作王后！’所以你不把这些事放在心上，也不思想这事的结局。'),
('CNV', '以赛亚书', 23, 47, 8, '因此，你这淫逸、安居的，现在要听这话。你曾心里说：‘只有我，除我以外再没有别的；我必不会寡居，也不会经历丧子的事。’'),
('CNV', '以赛亚书', 23, 47, 9, '不料丧子和寡居这两件事，竟在忽然之间，一日之内，要临到你身上！正在你多行邪术，竭力施符咒的时候，这两件事就必都临到你身上。'),
('CNV', '以赛亚书', 23, 47, 10, '你向来倚靠自己的邪恶，说：‘没有人看见我’；你的智慧和知识把你引入了歧途。你心里说：‘只有我，除了我以外，再没有别的。’'),
('CNV', '以赛亚书', 23, 47, 11, '但灾祸必临到你身上，你却不知道它的来源；祸患必落在你身上，你却不能把它除去；毁灭必忽然临到你身上，你却不知道。'),
('CNV', '以赛亚书', 23, 47, 12, '继续使用你从幼年时就劳碌施行的符咒和许多的邪术吧！或者你可以得到益处，也许你能叫人战栗。'),
('CNV', '以赛亚书', 23, 47, 13, '你因你许多的计划而劳累；现在让那些划分天象的，观看星辰的，在月朔时说预言的，都站起来，拯救你脱离要临到你身上的事。'),
('CNV', '以赛亚书', 23, 47, 14, '看哪！他们必像碎秸，火必要焚烧他们；他们不能救自己脱离火焰的威力；这不是可以烤火取暖的火炭，也不是可以坐在它面前的火。'),
('CNV', '以赛亚书', 23, 47, 15, '你所劳碌的事，都要这样与你无益；从你年幼时与你交易的，也都必各奔各方，四处飘流，没有人拯救你。”'),
('CNV', '以赛亚书', 23, 48, 1, '雅各家，就是被称为以色列的，从犹大的水源出来的，指着主的名起誓，却不是出于诚实和公义，提说以色列的神的啊！你们要听这话。'),
('CNV', '以赛亚书', 23, 48, 2, '他们被称为圣城的人，又倚靠以色列的神；他的名字是万军之主。'),
('CNV', '以赛亚书', 23, 48, 3, '主说：“先前的事，我从古时就预言过了，已经从我的口里说出来了，又说给人听了；我忽然行事，事情就都成就了。'),
('CNV', '以赛亚书', 23, 48, 4, '因为我知道你是顽固的，你的颈项是铁的，你的额是铜的，'),
('CNV', '以赛亚书', 23, 48, 5, '所以我从古时就告诉了你；在事情还没有发生以前，我就说给你听了，免得你说：‘这些事是我的偶像所作的，是我的雕像和铸像所命定的。’'),
('CNV', '以赛亚书', 23, 48, 6, '你已经听见了，现在要注意这一切事。难道你不述说吗？从今以后，我要把新的事，就是你不知道的隐秘的事，告诉你。'),
('CNV', '以赛亚书', 23, 48, 7, '这些事是现在才造成的，并不是从古时就有的；在今天以前，你还未曾听见过，免得你说：‘看哪！这些事我早已知道了。’'),
('CNV', '以赛亚书', 23, 48, 8, '你从来没有听过，也不知道；你的耳朵从来未曾开通。我原知道你行事非常诡诈；你自出母胎以来，就被称为叛徒。'),
('CNV', '以赛亚书', 23, 48, 9, '为了我的名的缘故，我暂时不发怒；为了我的名誉的缘故，我向你忍耐；不把你剪除。'),
('CNV', '以赛亚书', 23, 48, 10, '看哪！我熬炼了你，却不像熬炼银子；你在苦难的炉中，我拣选了你。'),
('CNV', '以赛亚书', 23, 48, 11, '为了我自己的缘故，为了我自己的缘故，我必作这事。我的名怎能被亵渎呢？我必不把我的荣耀归给别人。'),
('CNV', '以赛亚书', 23, 48, 12, '“雅各，我所呼召的以色列啊！你要听我的话。我就是‘那位’，我是首先的，也是末后的。'),
('CNV', '以赛亚书', 23, 48, 13, '我的手奠定了大地的根基，我的右手展开了诸天；我一呼唤它们，它们就一同站着侍候。'),
('CNV', '以赛亚书', 23, 48, 14, '列国啊！你们都要集合起来听。他们中间有谁预言过这些事呢？主爱他，他必向巴比伦行他所喜悦的；他的膀臂也必击打迦勒底人。'),
('CNV', '以赛亚书', 23, 48, 15, '我亲自说过，又呼召了他；我带领了他来，他所行的就必亨通。'),
('CNV', '以赛亚书', 23, 48, 16, '你们要就近我，当听这话：‘从起初我就没有在隐密处说过话，自从有这事情的存在，我就在那里。’现在主神差遣了我和他的灵。'),
('CNV', '以赛亚书', 23, 48, 17, '主你的救赎主，以色列的圣者，这样说：‘我是主你的神，是教导你，使你得益处的，是在你当行的道路上引导你的。'),
('CNV', '以赛亚书', 23, 48, 18, '但愿你一向都留心听从我的命令，这样你的平安就像河水滔滔，你的公义就如海浪滚滚；'),
('CNV', '以赛亚书', 23, 48, 19, '你的后裔必像海沙那么多，你腹中的子孙要如沙粒这样多；他们的名字必不会被剪除，也不会从我面前消灭。'),
('CNV', '以赛亚书', 23, 48, 20, '“你们要从巴比伦出来，从迦勒底人中逃出来，你们要用欢呼的声音宣告，把这事说给人听，你们要把这事宣扬出去，直到地极，说：‘主救赎了他的仆人雅各了。’'),
('CNV', '以赛亚书', 23, 48, 21, '主领他们走过荒野的时候，他们并不干渴；他为他们使水从磐石流出来。他裂开磐石，水就涌出来。'),
('CNV', '以赛亚书', 23, 48, 22, '主说：‘恶人没有平安。’”'),
('CNV', '以赛亚书', 23, 49, 1, '众海岛啊！你们要听我的话。远方的万族啊！你们要留心听。我在母胎的时候，主就呼召了我；我出母腹的时候，他就提了我的名。'),
('CNV', '以赛亚书', 23, 49, 2, '他使我的口如快刀，把我藏在他手的阴影之下；他又使我成为磨亮的箭，把我藏在他的箭袋里。'),
('CNV', '以赛亚书', 23, 49, 3, '他对我说：“你是我的仆人以色列，我要藉着你得荣耀。”'),
('CNV', '以赛亚书', 23, 49, 4, '但我说：“我劳碌是徒然的；我用尽气力，是虚无虚空的；然而我当得的公理是在主那里，我的赏赐是在我的神那里。”'),
('CNV', '以赛亚书', 23, 49, 5, '现在，主说：（他自我还在母胎的时候，就造了我作他的仆人，好使雅各回转归向他，使以色列可以聚集到他那里；我在主眼中被看为尊贵，我的神是我的力量。）'),
('CNV', '以赛亚书', 23, 49, 6, '“你作我的仆人，使雅各众支派复兴，使以色列中得保全的归回，只是小事，我还要使你作列国的光，使我的救恩传到地极。”'),
('CNV', '以赛亚书', 23, 49, 7, '以色列的救赎主，以色列的圣者主，对那被人藐视的、被本国憎恶的、被统治者奴役的，这样说：“君王看见了，就必起立，领袖看见了，也要下拜，都因信实的主，就是拣选了你的、以色列的圣者的缘故。”'),
('CNV', '以赛亚书', 23, 49, 8, '主这样说：“在悦纳的时候，我应允了你，在拯救的日子，我帮助了你；我要保护你，使你作人民的中保，复兴那地，使人承受荒凉之地作产业，'),
('CNV', '以赛亚书', 23, 49, 9, '对那些被囚的说：‘你们出来吧！’对那些在黑暗中的人说：‘你们现身吧！’他们沿途必得喂养，一切光秃的高处必成为他们的草场。'),
('CNV', '以赛亚书', 23, 49, 10, '他们必不饥饿，也不口渴，炎热和太阳必不伤害他们，因为那怜悯他们的，要引领他们，带领他们到水泉的旁边。'),
('CNV', '以赛亚书', 23, 49, 11, '我必使我的众山成为道路，我的大道都必被修高。'),
('CNV', '以赛亚书', 23, 49, 12, '看哪！有些人从远方而来；看哪！有些从北方，从西方而来，还有些从色尼姆地而来。”'),
('CNV', '以赛亚书', 23, 49, 13, '诸天哪！你们要欢呼。大地啊！你当快乐。众山啊！你们要发声欢呼。因为主已经安慰了他的子民，也必怜悯他受困苦的人。'),
('CNV', '以赛亚书', 23, 49, 14, '但锡安说：“主离弃了我，我的主忘记了我。”'),
('CNV', '以赛亚书', 23, 49, 15, '妇人怎能忘记她吃奶的婴孩，不怜悯她亲生的儿子呢？即使她们可能忘记，我也不会忘记你。'),
('CNV', '以赛亚书', 23, 49, 16, '看哪！我已经把你刻在我的掌上；你的城墙常常在我面前。'),
('CNV', '以赛亚书', 23, 49, 17, '重建你的（按照《马索拉文本》，“重建你的”作“你的儿女们”；现参照《死海古卷》和其他古译本翻译）要急速归回，那些毁坏你的和那些使你荒废的，都必离你而去。'),
('CNV', '以赛亚书', 23, 49, 18, '你举目向四周观看吧！他们都集合到你那里来。主说：“我指着我的永生起誓，你要披戴他们，如同披戴装饰品；你要以他们作华带束腰，像新妇一样。'),
('CNV', '以赛亚书', 23, 49, 19, '至于你那些被毁坏荒废之处和你那些被拆毁之地，现在给众人居住必显为太狭窄了，那些吞灭你的都必远离你。'),
('CNV', '以赛亚书', 23, 49, 20, '你丧子以后所生的儿女还要说给你听，说：‘这地方给我居住太狭窄了；求你给我预备地方居住吧！’'),
('CNV', '以赛亚书', 23, 49, 21, '那时你心里必说：‘我既丧子，又不能生育；我是被掳的，又是被放逐在外的，谁给我生了这些孩子呢？谁把这些孩子养大呢？看哪！我独自一人被撇下，这些孩子是从哪里来的呢？’”'),
('CNV', '以赛亚书', 23, 49, 22, '主神这样说：“看哪！我必向列国举手，我要向万民竖立我的旗帜；他们要把你的儿子都抱在怀中带来，把你的女儿都放在肩上背来。'),
('CNV', '以赛亚书', 23, 49, 23, '列国的君王要作你的养父，他们的王后必作你的保姆；他们必脸伏于地向你下拜，舐你脚上的尘土。那么，你就知道我是主，那些仰望我的决不会羞愧。”'),
('CNV', '以赛亚书', 23, 49, 24, '被抢去的怎能从勇士手中夺回呢？被俘虏的怎能从强暴者（按照《马索拉文本》，“强暴者”作“义者”；现参照《死海古卷》和其他古译本翻译）的手里救出来呢？'),
('CNV', '以赛亚书', 23, 49, 25, '但主这样说：“就是勇士所俘掳的，也可以夺回，强暴者所抢去的，也可以救出来；与你相争的，我必与他们相争；你的儿女，我却要拯救。'),
('CNV', '以赛亚书', 23, 49, 26, '我要使那些欺压你的人，吃自己的肉；他们必喝自己的血醉倒，好像喝了甜酒一样；那么所有的人都必知道，我主是你的拯救者，是你的救赎主，是雅各的大能者。”'),
('CNV', '以赛亚书', 23, 50, 1, '主这样说：“我离弃了你们的母亲，休书在哪里呢？或者我的债主中，哪一个是我把你们卖了给他的呢？看哪！你们被卖是因你们的罪孽；你们的母亲被离弃是因你们的过犯。'),
('CNV', '以赛亚书', 23, 50, 2, '为什么我来的时候，没有人在呢？为什么我呼唤的时候，没有人答应呢？难道我的手太软弱不能救赎吗？或是我没有能力拯救吗？看哪！我以斥责使海干涸，我使江河变成旷野，江河的鱼因无水发臭，因干渴而死。'),
('CNV', '以赛亚书', 23, 50, 3, '我使诸天以黑暗为衣服，以麻布作它们的遮盖。”'),
('CNV', '以赛亚书', 23, 50, 4, '主神赐给了我一个受教者的舌头，使我知道怎样用言语扶助疲乏的人；主每天清晨唤醒我，他每天清晨唤醒我的耳朵，使我能像受教者一样静听。'),
('CNV', '以赛亚书', 23, 50, 5, '主神开启了我的耳朵，我并没有违抗，也没有后退。'),
('CNV', '以赛亚书', 23, 50, 6, '我把我的背给打我的人打，把我的腮颊给拔我胡须的人拔；我并没有掩面躲避人的羞辱和人的唾液。'),
('CNV', '以赛亚书', 23, 50, 7, '但主神必帮助我，所以我必不羞愧，因此我板着脸好像坚硬的燧石，我也知道我必不会蒙羞。'),
('CNV', '以赛亚书', 23, 50, 8, '那称我为义的，与我相近；谁与我争讼呢？让我们一同站起来吧！谁是指控我的？让他就近我来。'),
('CNV', '以赛亚书', 23, 50, 9, '看哪！主神帮助我，谁能定我有罪呢？看哪！他们都要像衣服渐渐破旧，蛀虫必把他们吃光。'),
('CNV', '以赛亚书', 23, 50, 10, '你们中间谁是敬畏主，听从他仆人的声音的？谁是行在黑暗中，没有亮光的呢？他该倚靠主的名，依赖他的神。'),
('CNV', '以赛亚书', 23, 50, 11, '看哪！你们点火的，用火把围绕自己的，都行在你们火焰的光里，都走在你们所燃点的火把中吧！这是你们从我手里所要得的：你们必躺卧在痛苦之中。'),
('CNV', '以赛亚书', 23, 51, 1, '追求公义、寻求主的啊！你们要听我的话。你们要瞻仰那磐石，你们就是从其上凿出来的；你们要瞻仰那采石坑，你们就是从其中挖出来的。'),
('CNV', '以赛亚书', 23, 51, 2, '你们要瞻仰你们的祖宗亚伯拉罕，他们也要瞻仰那生你们的撒拉。亚伯拉罕独自一人的时候，我呼召了他，赐福给他，使他有很多子孙。'),
('CNV', '以赛亚书', 23, 51, 3, '主必安慰锡安，他要安慰它的一切荒场，使它的旷野像伊甸园一样，使它的荒地像主的园子一般，在其中必有欢喜快乐、感谢和歌声。'),
('CNV', '以赛亚书', 23, 51, 4, '我的子民哪！你们要留心听我；我的民族啊！你们要侧耳听我。因为训诲必从我而去；我必坚立我的判词为万民之光。'),
('CNV', '以赛亚书', 23, 51, 5, '我的公义临近，我的拯救已经发出了，我的膀臂审判万民，众海岛的人都要等候我，并且仰赖我的膀臂。'),
('CNV', '以赛亚书', 23, 51, 6, '你们要仰观天空，俯视大地；因为诸天必像烟云消散，大地要像衣服渐渐破旧；其上的居民必像蠓虫死亡（“必像蠓虫死亡”或译：“必要这样死去”），但我的拯救却永远长存，我的公义也不会废去。'),
('CNV', '以赛亚书', 23, 51, 7, '认识公义，把我的训诲存在心里的人民哪！你们要听我的话。你们不要怕人的辱骂，也不要因人的毁谤而惊惶。'),
('CNV', '以赛亚书', 23, 51, 8, '因为蛀虫必吃他们，像吃衣服一样；虫子必吃他们，像吃羊羢一样。但我的公义永远长存。我的拯救直到万代。'),
('CNV', '以赛亚书', 23, 51, 9, '主的膀臂啊，醒来吧！醒来吧！穿上能力吧！像古时的日子，像上古的世代一样醒来吧！从前砍碎了拉哈伯，刺透了海龙的，不是你吗？'),
('CNV', '以赛亚书', 23, 51, 10, '使海，就是大渊的水干涸，使海的深处变为蒙救赎的人经过之路的，不是你吗？'),
('CNV', '以赛亚书', 23, 51, 11, '主所赎的人必归回；他们必欢呼着进入锡安；永远的快乐要临到他们的头上。他们必得着欢喜快乐，忧愁叹息都必逃避。'),
('CNV', '以赛亚书', 23, 51, 12, '“我，我主是安慰你们的；你是谁，竟怕那会死的人，怕那被造如草的世人呢？'),
('CNV', '以赛亚书', 23, 51, 13, '你忘记了造你的主，就是那展开诸天，奠定大地的根基的；又因那欺压者准备行毁灭的时候所发的烈怒，你就终日不住惧怕呢？其实那欺压者的烈怒在哪里呢？'),
('CNV', '以赛亚书', 23, 51, 14, '被掳的快得释放了，他们必不会死，必不会下到阴间里，他们的食物也必不会缺乏。'),
('CNV', '以赛亚书', 23, 51, 15, '我是主你们的神，就是那搅动大海，使海中的波浪澎湃的；万军之主是他的名。'),
('CNV', '以赛亚书', 23, 51, 16, '我把我的话放在你的口里，用我的手影蔽护你，好立定诸天，奠定大地的根基，对锡安说：‘你是我的子民。’”'),
('CNV', '以赛亚书', 23, 51, 17, '耶路撒冷啊，醒来！醒来！站起来吧！你从主的手中喝了他烈怒的杯，喝尽了那使人摇摇摆摆的爵。'),
('CNV', '以赛亚书', 23, 51, 18, '她所生的众子中，没有一个引导她的；她养大的众子中，没有一个扶持她的。'),
('CNV', '以赛亚书', 23, 51, 19, '荒凉与毁灭，饥荒与刀剑，这两样临到你，谁为你悲哀呢？谁能安慰你呢？（按照《马索拉文本》，“谁能安慰你呢？”作“我如何能安慰你呢？”；现参照《死海古卷》和其他古译本翻译）'),
('CNV', '以赛亚书', 23, 51, 20, '你的众子昏倒了，在各街头上躺卧，好像羚羊在网罗之中；他们饱尝了主的烈怒，你的神的斥责。'),
('CNV', '以赛亚书', 23, 51, 21, '所以，你这困苦的，不是因酒而醉倒的，要听这话。'),
('CNV', '以赛亚书', 23, 51, 22, '你的主神，就是为自己的子民争辩的神，这样说：“看哪！我已经把那使人摇摇摆摆的杯，就是我烈怒的爵，从你的手里挪去了；你必不再喝这杯。'),
('CNV', '以赛亚书', 23, 51, 23, '我必把这杯放在那些苦待你的人的手里；他们曾对你说：‘你屈身俯伏，让我们走过去吧！’你就以你的背作陆地，作街道，任由他们踏过去。”'),
('CNV', '以赛亚书', 23, 52, 1, '锡安哪！你要醒来；醒来，披上你的力量。圣城耶路撒冷啊！要穿上你华美的衣服。因为未受割礼的和不洁净的人，都再不得进到你那里去。'),
('CNV', '以赛亚书', 23, 52, 2, '耶路撒冷啊！抖下尘土，起来，坐在位上吧！锡安被掳的居民（“居民”原文作“女子”）哪！解开你颈项上的锁链。'),
('CNV', '以赛亚书', 23, 52, 3, '主这样说：“你们被卖是毫无代价的，你们被赎回也必不用银子。”'),
('CNV', '以赛亚书', 23, 52, 4, '主神这样说：“我的子民先前曾下到埃及，在那里寄居；后来有亚述人无缘无故地欺压了他们。'),
('CNV', '以赛亚书', 23, 52, 5, '现在我在这里作什么呢？”主说：“我的子民毫无代价被取去；统治他们的人大肆咆哮。”主说：“我的名终日不住被藐视。'),
('CNV', '以赛亚书', 23, 52, 6, '所以我的子民必认识我的名，因此到了那日他们就必知道，说这话的就是我。看哪！是我。”'),
('CNV', '以赛亚书', 23, 52, 7, '那传福音、宣布平安、传美好的福音、宣布救恩，又对锡安说“你的神作王了”的，他的脚踪在山上多么的美！'),
('CNV', '以赛亚书', 23, 52, 8, '听啊！你守望者的声音。他们都扬起声来，一同欢呼，因为主归回锡安的时候，他们必亲眼看见。'),
('CNV', '以赛亚书', 23, 52, 9, '耶路撒冷的废墟啊！你们要发声，一同欢呼。因为主安慰了他的子民，救赎了耶路撒冷。'),
('CNV', '以赛亚书', 23, 52, 10, '主在万国的眼前，显露他的圣臂，地极的人必看见我们神的拯救。'),
('CNV', '以赛亚书', 23, 52, 11, '你们要离开，要离开，要从那里出来，不要触摸不洁净的东西。扛抬主器皿的啊！你们要从巴比伦城中出来，要自洁。'),
('CNV', '以赛亚书', 23, 52, 12, '你们出来，不必着急；你们行走，也不必奔逃，因为主要走在你们前面，以色列的神必作你们的后盾。'),
('CNV', '以赛亚书', 23, 52, 13, '看哪！我的仆人必行事亨通，他必受尊崇，被高举，成为至高。'),
('CNV', '以赛亚书', 23, 52, 14, '许多人怎样因你而惊奇，（因为他的容貌毁损得不像人，他的形状毁损得不像世人），'),
('CNV', '以赛亚书', 23, 52, 15, '照样，他也必使多国的人惊异（按照《马索拉文本》，“他也必使多国的人惊异”作“他必洒许多国的民”；现参照《七十士译本》翻译），君王要因他闭口不言，因为从未向他们述说过的事，他们必看见；他们从未听过的，他们要明白。'),
('CNV', '以赛亚书', 23, 53, 1, '谁会相信我们所传的？主的膀臂向谁显露呢？'),
('CNV', '以赛亚书', 23, 53, 2, '他在主面前如嫩芽生长起来，像根出于干旱之地；他没有佳形，也没有威仪，好叫我们仰慕他；他也没有美貌，使我们被他吸引。'),
('CNV', '以赛亚书', 23, 53, 3, '他被藐视，被人拒绝，是个多受痛苦，熟悉病患的人。他像个被人掩面不看的人一样；他被藐视，我们也不重视他。'),
('CNV', '以赛亚书', 23, 53, 4, '原来他担当了我们的病患，背负了我们的痛苦；我们却以为他受责打，被神击打和苦待了。'),
('CNV', '以赛亚书', 23, 53, 5, '然而他是为了我们的过犯被刺透，为了我们的罪孽被压伤；使我们得平安的惩罚加在他身上，因他受了鞭伤，我们才得医治。'),
('CNV', '以赛亚书', 23, 53, 6, '我们众人都如羊走迷了路，各人偏行己路；主却把我们众人的罪孽，都归在他身上。'),
('CNV', '以赛亚书', 23, 53, 7, '他被虐待，受痛苦的时候，他并不开口；他像羊羔被牵去屠宰，又像羊在剪羊毛的人面前寂然无声，他也是这样不开口。'),
('CNV', '以赛亚书', 23, 53, 8, '他受拘禁和审判以后被带走；至于他那个世代的人中，有谁想到从活人之地被剪除，被击打，是因我子民的过犯呢？'),
('CNV', '以赛亚书', 23, 53, 9, '虽然他从来没有行过强暴，他的口里也没有诡诈，人还是使他与恶人同埋，但死的时候与财主同葬。'),
('CNV', '以赛亚书', 23, 53, 10, '主却喜悦把他压伤，使他受痛苦；主若以他的性命作赎罪祭，他必看见后裔，并且得享长寿；主所喜悦的，必在他手中亨通。'),
('CNV', '以赛亚书', 23, 53, 11, '他受了生命之苦以后，必看见光明，并且心满意足；我的义仆必使许多人因认识他而得称为义，他也必背负他们的罪孽。'),
('CNV', '以赛亚书', 23, 53, 12, '所以，我要使他与伟大的人同分，他必与强盛的均分掳物，因为他把自己的性命倾倒，以致于死。他被列在罪犯之中，却担当了多人的罪，又为罪犯代求。'),
('CNV', '以赛亚书', 23, 54, 1, '不能生育、没有生养过孩子的啊！你要欢呼。没有生产过的啊！你要发声欢呼，高声呼喊。因为弃妇比有夫之妇有更多儿子。这是主说的。'),
('CNV', '以赛亚书', 23, 54, 2, '要扩张你帐幕的地方，伸展你居所的幔子，不要限制；要拉长你的绳索，坚固你的橛子。'),
('CNV', '以赛亚书', 23, 54, 3, '因为你要向南向北扩展，你的后裔必占有列国之地，又使荒废了的城镇有人居住。'),
('CNV', '以赛亚书', 23, 54, 4, '不要惧怕，因为你必不致蒙羞；也不要抱愧，因为你必不致受辱，你必忘记你幼年时的羞愧，也不再记念你寡居时的耻辱。'),
('CNV', '以赛亚书', 23, 54, 5, '因为造你的，就是你的丈夫；万军之主是他的名；救赎你的，就是以色列的圣者；他被称为全地的神。'),
('CNV', '以赛亚书', 23, 54, 6, '因为主召唤你，如同召唤被离弃、心灵忧伤的妻子，就是幼年时所娶却被弃绝的妻子；这是你的神说的。'),
('CNV', '以赛亚书', 23, 54, 7, '我只是暂时离弃你，却以极大的怜悯把你招聚回来。'),
('CNV', '以赛亚书', 23, 54, 8, '在怒气涨溢的时候，我暂时向你掩面，却要以永远的慈爱怜悯你；这是主你的救赎主说的。'),
('CNV', '以赛亚书', 23, 54, 9, '这事对我就好像挪亚时代的洪水一般；我怎样起誓不再使挪亚时代的洪水漫过大地，我也照样起誓不向你发怒，也不斥责你。'),
('CNV', '以赛亚书', 23, 54, 10, '虽然大山可以挪开，小山可以迁移，但我的慈爱必不从你身上挪开，我和平的约也必不迁移；这是怜悯你的主说的。'),
('CNV', '以赛亚书', 23, 54, 11, '受困苦、被风飘荡、不得安慰的啊！你看，我要用彩色的石头安置你的基石，以蓝宝石奠定你的根基。'),
('CNV', '以赛亚书', 23, 54, 12, '又用红宝石做你的城楼，用红玉做你的城门，用各种宝石做你四周的围墙。'),
('CNV', '以赛亚书', 23, 54, 13, '你所有的儿女都必受主的教导，你的儿女必大享平安。'),
('CNV', '以赛亚书', 23, 54, 14, '你必因公义得以坚立；你必远离欺压，你必无所惧怕；你也必远离惊吓，因为惊吓必不会临近你。'),
('CNV', '以赛亚书', 23, 54, 15, '看哪！必有人起来攻击你，但那不是出于我；攻击你的，必因你仆倒。'),
('CNV', '以赛亚书', 23, 54, 16, '看哪！那吹炭火、打造出合用武器的铁匠，是我创造的；那残害人、行毁灭的，也是我创造的。'),
('CNV', '以赛亚书', 23, 54, 17, '为攻击你而制成的武器，都没有效用；在审判的时候兴起来与你争辩的舌头，你都必定它为有罪。这是主众仆人的产业，他们的义是从我而得；这是主说的。'),
('CNV', '以赛亚书', 23, 55, 1, '唉！口渴的人哪！你们都就近水来吧。没有银钱的，你们也要来，买了就吃。你们要来，买酒和奶，不用银子，也不用付代价。'),
('CNV', '以赛亚书', 23, 55, 2, '你们为什么用银子去买那不是食物的呢？为什么用你们劳碌得来的去买那不能使人饱足的呢？你们要留心听我的话，就可以吃美物，使你们的心灵享受肥甘。'),
('CNV', '以赛亚书', 23, 55, 3, '你们要侧耳而听，要到我这里来；你们要听，就可以存活；我必与你们立永远的约，就是应许赐给大卫的那确实的慈爱。'),
('CNV', '以赛亚书', 23, 55, 4, '看哪！我已经立了他作万族的见证人，为万族的首领和司令。'),
('CNV', '以赛亚书', 23, 55, 5, '看哪！你要召聚你不认识的国；那些素来不认识你的国也必奔向你，都因主你的神、以色列的圣者的缘故，因为他已经荣耀了你。'),
('CNV', '以赛亚书', 23, 55, 6, '你们要趁着主可以寻找的时候，寻找他，趁着他靠近的时候，呼求他。'),
('CNV', '以赛亚书', 23, 55, 7, '恶人要离弃自己的道路，不义的人当除去自己的意念，回转过来归向主，主就必怜悯他。你们当回转过来归向我们的神，因为他大大赦免人的罪。'),
('CNV', '以赛亚书', 23, 55, 8, '主说：“我的意念不是你们的意念，你们的道路也不是我的道路。'),
('CNV', '以赛亚书', 23, 55, 9, '天怎样高过地，我的道路也怎样高过你们的道路，我的意念也怎样高过你们的意念。'),
('CNV', '以赛亚书', 23, 55, 10, '雨雪怎样从天上降下来，不再返回天上，却灌溉大地，使地上的植物发芽结实，使撒种的有种子，吃的人有粮食；'),
('CNV', '以赛亚书', 23, 55, 11, '从我的口所出的话也必这样，必不徒然返回我这里，却要作成我所喜悦的，使它在我差遣它去作的事上必然亨通。'),
('CNV', '以赛亚书', 23, 55, 12, '你们必欢欢喜喜出来，平平安安蒙引导；大山小山都必在你们面前发声欢呼，田野所有的树木也都拍掌。'),
('CNV', '以赛亚书', 23, 55, 13, '松树要长起来代替荆棘，番石榴要长起来代替蒺藜。这要为主留名，作永远不能废掉的记号。”'),
('CNV', '以赛亚书', 23, 56, 1, '主这样说：“你们要持守公平，实行公义；因为我的拯救快要来到，我的公义快要显现了。'),
('CNV', '以赛亚书', 23, 56, 2, '谨守安息日，不亵渎这日，保守自己的手不作任何恶事，这样行的人和坚持这样作的人，是有福的！”'),
('CNV', '以赛亚书', 23, 56, 3, '与主联合的外族人不要说：“主必把我从他的子民中分别出来。”被阉割了的人也不要说：“看哪！我是一棵枯树。”'),
('CNV', '以赛亚书', 23, 56, 4, '因为主这样说：“那些谨守我的安息日，拣选我所喜悦的事，持守我的约、被阉割了的人，'),
('CNV', '以赛亚书', 23, 56, 5, '在我的殿中和在我的墙内，我要赐给他们有记念，有名号，比有儿女更好；我必赐给他们永远不能废掉的名。'),
('CNV', '以赛亚书', 23, 56, 6, '至于那些与主联合的外族人，为要事奉他，爱主的名，作他的仆人的，就是谨守安息日，不亵渎这日，又持守我的约的，'),
('CNV', '以赛亚书', 23, 56, 7, '我必领他们到我的圣山，使他们在属于我的祷告的殿中喜乐；他们的燔祭和祭品，在我的祭坛上必蒙悦纳；因为我的殿必称为万族祷告的殿。”'),
('CNV', '以赛亚书', 23, 56, 8, '主神，就是招聚以色列被赶散的人的，说：“在以色列这些已经被招聚的人以外，我还要招聚别的人归给他们。”'),
('CNV', '以赛亚书', 23, 56, 9, '田野的百兽啊！你们都来吃吧。林中的百兽啊！你们都要这样。'),
('CNV', '以赛亚书', 23, 56, 10, '他的守望者都是瞎眼的，都没有知识；他们都是哑巴狗，不能吠；只会作梦、躺卧，贪爱睡觉。'),
('CNV', '以赛亚书', 23, 56, 11, '这些狗十分贪吃，不知饱足；他们是牧人，但什么都不明白；他们都偏行自己的道路，各从各方求自己的利益。'),
('CNV', '以赛亚书', 23, 56, 12, '他们说：“来吧！我去拿酒，让我们痛饮烈酒吧！明天必像今天一样，而且比今天还盛大和丰盈。”'),
('CNV', '以赛亚书', 23, 57, 1, '义人死亡，没有人放在心上；虔诚人去世，也没有人明白；义人去世，是脱离了祸患。'),
('CNV', '以赛亚书', 23, 57, 2, '行事为人正直的，死后必得进入平安，在他们的坟墓里享安息。'),
('CNV', '以赛亚书', 23, 57, 3, '但你们这些巫妇的儿子，奸夫和妓女的后裔啊！你们都走近这里行奸淫吧！'),
('CNV', '以赛亚书', 23, 57, 4, '你们戏弄谁呢？你们张大嘴巴，伸长舌头戏弄谁呢？你们不是悖逆的孩子吗？不是虚谎的后裔吗？'),
('CNV', '以赛亚书', 23, 57, 5, '你们在橡树林中，在青翠树下欲火焚心；在山谷间，在岩穴里，宰杀自己的孩子作祭牲。'),
('CNV', '以赛亚书', 23, 57, 6, '在山谷中光滑的石头里有你的分；只有它们是你所要得的分！你也向它们浇了奠祭，献上了供物。这些事我岂能容忍不报复呢？'),
('CNV', '以赛亚书', 23, 57, 7, '你在高高的山上安设你的床榻，又上到那里去献祭。'),
('CNV', '以赛亚书', 23, 57, 8, '你在门后，在门框后，安设了外族神的记号；你远离了我，裸露了自己，就上床去，又扩张你的床，你也与他们立约；你爱他们的床，看他们的下体（“下体”:原文作“手”，是“下体”的委婉语）。'),
('CNV', '以赛亚书', 23, 57, 9, '你带着油走到君王那里，并且加多了你的香料，差派使者到远方去，你甚至自己下到阴间去！'),
('CNV', '以赛亚书', 23, 57, 10, '你因路途遥远而困乏，却不说：“没有希望了！”因为你找着了生命的力量，所以你不觉得疲倦。'),
('CNV', '以赛亚书', 23, 57, 11, '你怕谁？你因谁而惧怕，以致你对我说谎呢？你不记念我，也不把我放在心上，是不是因为我长久缄默，你就不惧怕我呢？'),
('CNV', '以赛亚书', 23, 57, 12, '我要说明你的公义和你所作的，但它们都必与你无益。'),
('CNV', '以赛亚书', 23, 57, 13, '你呼求的时候，让你所收集的偶像拯救你吧！但一阵风要把它们全都刮走，一口气要把它们全部吹去。然而那投靠我的，必承受地土，得着我的圣山作产业。'),
('CNV', '以赛亚书', 23, 57, 14, '必有人说：“你们要填高，要填高，要修平道路；把障碍物从我子民的路上除掉。”'),
('CNV', '以赛亚书', 23, 57, 15, '因为那至高无上、永远存在、他名为圣的这样说：“虽然我住在至高至圣的地方，却与心灵痛悔和谦卑的人同在，要使谦卑人的灵苏醒，也使痛悔人的心苏醒。'),
('CNV', '以赛亚书', 23, 57, 16, '我必不永远争辩，也不长久发怒，因为这样，人的灵，就是我所造的人，在我面前就要发昏。'),
('CNV', '以赛亚书', 23, 57, 17, '因他贪婪的罪孽，我发怒了；我击打他，向他掩面，并且发怒，他仍然随着自己的心意背道。'),
('CNV', '以赛亚书', 23, 57, 18, '他的道路，我看见了，我却要医治他，引导他，把安慰赏赐他和他的哀悼者。'),
('CNV', '以赛亚书', 23, 57, 19, '我创造嘴唇的果子：平安，平安，归给远处的人，也归给近处的人。”主说：“我要医治他。”'),
('CNV', '以赛亚书', 23, 57, 20, '恶人却像翻腾的海，不能平静，海中的水不住翻起污秽和淤泥来。'),
('CNV', '以赛亚书', 23, 57, 21, '我的神说：“恶人必没有平安。”'),
('CNV', '以赛亚书', 23, 58, 1, '你要张开喉咙呼叫，不可停止；你要提高声音，像吹号角一样；你要向我子民宣告他们的过犯，向雅各家陈明他们的罪恶。'),
('CNV', '以赛亚书', 23, 58, 2, '他们天天寻求我，乐意明白我的道路，好像行义的国民，不离弃他们神的公理；他们向我求问公义的判语，又喜欢亲近神。'),
('CNV', '以赛亚书', 23, 58, 3, '他们说：“为什么我们禁食，你不看呢？为什么我们刻苦己身，你不理会呢？”看哪！你们在禁食的日子，仍然追求自己喜欢作的事，欺压为你们作工的人。'),
('CNV', '以赛亚书', 23, 58, 4, '看哪！你们禁食，结果是吵闹和打架，用凶恶的拳头打人；你们不要像今天这样的禁食，使你们的声音可以听闻于天上。'),
('CNV', '以赛亚书', 23, 58, 5, '使人刻苦自己的日子，这样的禁食是我拣选的吗？难道只是叫人垂头像一根苇子，用麻布和炉灰铺在下面吗？你可以称这是禁食，为主所悦纳的日子吗？'),
('CNV', '以赛亚书', 23, 58, 6, '我所拣选的禁食不是这样吗？不是要松开凶恶的锁链，解开轭上的绳索，使被压迫的获得自由，折断所有的轭吗？'),
('CNV', '以赛亚书', 23, 58, 7, '不是要把你的食物分给饥饿的人，把流浪的穷困人接到你的家里，见到赤身露体的，给他衣服蔽体，不可逃避自己的骨肉而不顾恤吗？'),
('CNV', '以赛亚书', 23, 58, 8, '这样，你的光就必突然发出，像黎明的曙光，你的伤口就必快快复原；你的公义就必行在你的前面，主的荣耀要作你的后盾。'),
('CNV', '以赛亚书', 23, 58, 9, '那时，你求告，主必应允；你呼求，他必说：“我在这里！”你若从你中间除掉欺压人的轭，除去指责人的指头和恶毒的言语，'),
('CNV', '以赛亚书', 23, 58, 10, '你的心若顾念饥饿的人，使困苦的人得到饱足，你的光就必在黑暗中升起来，你的幽暗必变得如正午。'),
('CNV', '以赛亚书', 23, 58, 11, '主必常常引导你，在干旱之地使你的心灵饱足，使你的骨头坚强有力；你必像有水源浇灌的园子，又像水流不绝的泉源。'),
('CNV', '以赛亚书', 23, 58, 12, '你的子孙必重建久已荒废之处，你必重建历代拆毁了的根基；你要称为修补破口的人，重修路径给人居住的人。'),
('CNV', '以赛亚书', 23, 58, 13, '“因安息日的缘故，你若转离你的脚步；在我的圣日不作你喜欢作的；你若称安息日为可喜乐的，称主的圣日为可尊重的；你若尊重这日，不作自己的事，不寻求自己所喜悦的，或不说无谓的话，'),
('CNV', '以赛亚书', 23, 58, 14, '你就必以主为乐，我要使你乘驾地的高处，用你祖雅各的产业喂养你。”这是主亲口说的。'),
('CNV', '以赛亚书', 23, 59, 1, '看哪！主的手不是缩短了，以致不能拯救；他的耳朵不是不灵，不能听见；'),
('CNV', '以赛亚书', 23, 59, 2, '而是你们的罪孽使你们与你们的神隔绝；你们的罪恶使他掩面不顾你们，不听你们的祷告。'),
('CNV', '以赛亚书', 23, 59, 3, '因为你们的手沾满了血，你们的指头被罪孽玷污，你们的嘴唇说虚谎的话，你们的舌头讲出凶言。'),
('CNV', '以赛亚书', 23, 59, 4, '没有人按公义求告，没有人凭诚实争辩；他们都倚靠虚无，说虚谎的话；所怀的是毒害，所生的是罪孽。'),
('CNV', '以赛亚书', 23, 59, 5, '他们所孵化的是毒蛇的蛋，他们所结的是蜘蛛的网，吃了它们的蛋，就一定死；蛋破了，就孵出蝮蛇来。'),
('CNV', '以赛亚书', 23, 59, 6, '他们的网，不能作衣服，他们所作的，也不能遮盖自己；他们所作的是罪孽的作为，他们的手里满是强暴的行为。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '以赛亚书', 23, 59, 7, '他们的脚奔跑行恶，他们急于流无辜人的血；他们的思想都是邪恶的思想，他们的行径全是破坏和毁灭。'),
('CNV', '以赛亚书', 23, 59, 8, '平安的路，他们不认识，在他们的行径中没有公平；他们为自己使道路弯曲，行在其上的，都不认识平安。'),
('CNV', '以赛亚书', 23, 59, 9, '因此，公平远离我们，公义赶不上我们，我们指望亮光，不料，却是黑暗。我们指望光明，却行在幽暗中！'),
('CNV', '以赛亚书', 23, 59, 10, '我们摸索墙壁，好像瞎子一样；我们摸索，如同没有眼睛的人一般；我们在中午跌倒，有如在黄昏跌倒一样；我们在肥壮的人中，好像死人一般。'),
('CNV', '以赛亚书', 23, 59, 11, '我们都咆哮如熊，悲鸣像鸽子；我们等候公平，却没有公平；指望拯救，拯救却离我们很远。'),
('CNV', '以赛亚书', 23, 59, 12, '因为我们的过犯在你面前增多，我们的罪作证控告我们，我们的过犯与我们在一起；我们知道我们的罪孽，'),
('CNV', '以赛亚书', 23, 59, 13, '就是悖逆、否认主，转去不跟从我们的神，说欺压和背道的话，心里怀着谎言，随即说出来；'),
('CNV', '以赛亚书', 23, 59, 14, '公平被迫后退，公义站在远处；诚实在街上跌倒，正直不能进入。'),
('CNV', '以赛亚书', 23, 59, 15, '诚实缺乏，远离恶事的人反成为掠物。主看见了，就看这为恶事（“就看这为恶事”或译：“很不喜悦”），因为一点公平也没有。'),
('CNV', '以赛亚书', 23, 59, 16, '他见无人行善，无人代求，就非常诧异，所以他用自己的膀臂为他施行拯救，以自己的公义扶持他。'),
('CNV', '以赛亚书', 23, 59, 17, '他穿上公义的铠甲，戴上救恩的头盔，穿上复仇的衣服，披上热心作外袍。'),
('CNV', '以赛亚书', 23, 59, 18, '他要按照各人的行为施行报应，把烈怒降与他的敌人，把报应加给他的仇敌，向众海岛的人施行报应。'),
('CNV', '以赛亚书', 23, 59, 19, '这样，人从日落之处必敬畏主的名，从日出之地也必敬畏他的荣耀，因为他必像狭急的河流冲来，主的气必向他催逼。'),
('CNV', '以赛亚书', 23, 59, 20, '“必有一位救赎主来到锡安，来到雅各家中那些转离过犯的人那里。”这是主说的。'),
('CNV', '以赛亚书', 23, 59, 21, '主说：“至于我，我与他们所立的约是这样：我加在你们身上的灵和我放在你口里的话，必不离开你的口，不离开你后裔的口，也不离开你后裔的后裔的口，从现在直到永远；这是主说的。”'),
('CNV', '以赛亚书', 23, 60, 1, '锡安哪！起来，发光，因为你的光已经来到，主的荣耀已升起来照耀你。'),
('CNV', '以赛亚书', 23, 60, 2, '看哪！黑暗遮盖大地，幽暗遮蔽万民；但主要升起来照耀你，他的荣耀要彰显在你身上。'),
('CNV', '以赛亚书', 23, 60, 3, '万国要在你的光中行走，列王必在你如旭日初升的光辉中行走。'),
('CNV', '以赛亚书', 23, 60, 4, '你举目四面观看吧！众人都聚集，来到你那里；你的儿子都要从远方而来，你的女儿都必被怀抱而来。'),
('CNV', '以赛亚书', 23, 60, 5, '那时，你看见了，就必有光彩，你的心又惊讶又宽畅；因为大海的财富都必转来归你，列国的财富也都归你。'),
('CNV', '以赛亚书', 23, 60, 6, '成群的骆驼必遮盖你的地，米甸和以法的小骆驼要盖满你的国境；示巴的人都必带着黄金和乳香来到，并且宣扬赞美主的话。'),
('CNV', '以赛亚书', 23, 60, 7, '基达的羊群都必聚集到你那里，尼拜约的公羊要供你使用；它们必献在我的祭坛上，成为蒙悦纳的祭品。我要荣耀我荣耀的殿。'),
('CNV', '以赛亚书', 23, 60, 8, '那些像云彩飞来，像鸽子飞回巢里的，是谁呢？'),
('CNV', '以赛亚书', 23, 60, 9, '众海岛的人都必等候我，他施的船队领先，把你的众子，连他们的金银，都一起从远方带来，都为了主你的神的名，又为了以色列的圣者的缘故，因为他已经荣耀了你。'),
('CNV', '以赛亚书', 23, 60, 10, '外族人要重建你的城墙，他们的君王都必服事你。虽然我曾经在烈怒中击打了你，现在我却在恩典中怜悯你。'),
('CNV', '以赛亚书', 23, 60, 11, '你的城门必常常开，日夜都不关闭，使人把列国的财富带来归你，他们的君王也都被引导而来。'),
('CNV', '以赛亚书', 23, 60, 12, '不事奉你的邦或国，都必灭亡；那些邦国必全然荒废。'),
('CNV', '以赛亚书', 23, 60, 13, '黎巴嫩的荣耀必来归你，就是松树、杉树和黄杨树，都一起归你，为要装饰我圣所之地，我也要使我踏足之处得荣耀。'),
('CNV', '以赛亚书', 23, 60, 14, '那些素来苦待你的人，他们的子孙都必屈身来到你那里；所有藐视你的，都要在你的脚下跪拜；他们要称你为主的城、以色列圣者的锡安。'),
('CNV', '以赛亚书', 23, 60, 15, '你曾经被撇弃、被憎恨，以致无人经过你那里，但我要使你成为永远被夸耀的，成为万代的喜乐。'),
('CNV', '以赛亚书', 23, 60, 16, '你要喝万国的奶，又吮列王的乳，这样，你就知道我主是你的拯救者，是你的救赎主，雅各的大能者。'),
('CNV', '以赛亚书', 23, 60, 17, '我要带来黄金代替铜，带来银子代替铁，铜代替木头，铁代替石头。我要立和平作你的官长，立公义作你的监督。'),
('CNV', '以赛亚书', 23, 60, 18, '在你的国中必不再听见强暴的事，在你的境内，也不再听到荒废和毁坏的事；你必称你的城墙为“拯救”，称你的城门为“赞美”。'),
('CNV', '以赛亚书', 23, 60, 19, '白天太阳必不再作你的光，晚上月亮也必不再发光照耀你，主却要作你永远的光，你的神要作你的荣耀。'),
('CNV', '以赛亚书', 23, 60, 20, '你的太阳必不再下落，你的月亮也必不退缩；因为主要作你永远的光，你悲哀的日子必要终止。'),
('CNV', '以赛亚书', 23, 60, 21, '你的人民都必成为义人，永远得地为业；他们是我栽种的嫩芽，我手所作的工作，使我得荣耀。'),
('CNV', '以赛亚书', 23, 60, 22, '最小的要成为一族，微弱的要成为强盛的国，我主必按着定期速速作成这事。'),
('CNV', '以赛亚书', 23, 61, 1, '主神的灵在我身上，因为主膏了我，叫我传福音给困苦的人；差遣我去医治伤心的人，向被掳的宣告自由，向被囚的宣告释放；'),
('CNV', '以赛亚书', 23, 61, 2, '宣告主悦纳人的禧年，和我们的神报仇的日子；安慰悲哀的人，'),
('CNV', '以赛亚书', 23, 61, 3, '为锡安悲哀的人穿上装饰，赐给他们华冠代替灰尘，喜乐油代替悲哀，赞美衣代替沮丧的灵，他们必称为公义的橡树，是主栽种的，好使他自己得着荣耀。'),
('CNV', '以赛亚书', 23, 61, 4, '他们必重建久已废弃的荒场，建立先前荒凉之地；重修荒废了的城镇，就是历代荒凉之处。'),
('CNV', '以赛亚书', 23, 61, 5, '那时，外人要服事你们，牧放你们的羊群，外族人要作你们的农夫和葡萄园丁。'),
('CNV', '以赛亚书', 23, 61, 6, '至于你们，却要称为主的祭司，人必称你们为我们神的仆人；你们要享用列国的财富，因得着他们的荣耀而夸耀。'),
('CNV', '以赛亚书', 23, 61, 7, '你们必得加倍的分，代替你们所受的羞愧，他们因自己所得的分而欢呼，代替羞辱，所以在他们的境内，他们必拥有加倍的产业，他们必有永远的喜乐。'),
('CNV', '以赛亚书', 23, 61, 8, '因为我主喜爱公平，恨恶不义的抢夺；我要凭真理赏赐他们，与他们立永远的约。'),
('CNV', '以赛亚书', 23, 61, 9, '他们的后裔必在列国中被人认识，他们的子孙在万民中也必这样；看见他们的，都必承认他们是主赐福的后裔。'),
('CNV', '以赛亚书', 23, 61, 10, '我因主大大欢喜，我的心靠着我的神快乐，因为他给我穿上救恩的衣服，给我披上公义的外袍，好像新郎戴上华冠，又像新娘佩戴装饰。'),
('CNV', '以赛亚书', 23, 61, 11, '地怎样发生苗芽，园子怎样使所种的生长起来，主神也必怎样使公义和赞美，在万国之前生长出来。'),
('CNV', '以赛亚书', 23, 62, 1, '为了锡安的缘故我必不缄默，为了耶路撒冷的缘故我决不静止，直到它的公义如光辉发出，它的救恩像明灯发亮。'),
('CNV', '以赛亚书', 23, 62, 2, '列国必看见你的公义，众王必看见你的荣耀；人要给你起一个新名，是主亲口指定的。'),
('CNV', '以赛亚书', 23, 62, 3, '你在主的手中要作美丽的冠冕，在你神的掌上要作君王的华冠。'),
('CNV', '以赛亚书', 23, 62, 4, '你必不再称为被撇弃的，你的地也必不再称为荒凉的，你却要称为我所喜悦的，你的地也要称为有丈夫的，因为主喜悦你，你的地也必有丈夫。'),
('CNV', '以赛亚书', 23, 62, 5, '因为年轻人怎样娶处女，那建造你的也必怎样娶你；新郎怎样因新娘欢乐，你的神也必怎样因你欢乐。'),
('CNV', '以赛亚书', 23, 62, 6, '耶路撒冷啊！我在你的城墙上设立了守望的人；他们昼夜都不缄默；提主之名的啊！你们不要静止。'),
('CNV', '以赛亚书', 23, 62, 7, '你们也不要让神静止，直至他建立耶路撒冷，等到他使耶路撒冷在地上成为受人赞美的城。'),
('CNV', '以赛亚书', 23, 62, 8, '主指着自己的右手和他大能的膀臂起誓，说：“我必不再把你的五谷给你的仇敌作食物，外族人也必不再喝你劳碌所得的新酒；'),
('CNV', '以赛亚书', 23, 62, 9, '唯有那些收割的人可以吃五谷，并且赞美主；那些收集的人可以在我圣所的院子里喝新酒。”'),
('CNV', '以赛亚书', 23, 62, 10, '你们要经过，要从城门经过，预备人民的道路；你们要填高，要填高大道。要捡去石头、向万民竖立旗帜。'),
('CNV', '以赛亚书', 23, 62, 11, '看哪！主曾向地极的人宣告，说：“你们要对锡安的居民（“居民”原文作“女子”）说：‘看哪！你的拯救者来到了。他给予人的赏赐在他那里，他施予人的报应在他面前。’”'),
('CNV', '以赛亚书', 23, 62, 12, '人必称他们为圣洁的子民，为主买赎回来的人；你也必称为被爱慕的，不被遗弃的城。'),
('CNV', '以赛亚书', 23, 63, 1, '那从以东、从波斯拉而来，身穿赤红色的衣服，装扮华丽、能力强大、大步前行的，是谁呢？“就是我，是凭着公义说话，有大能拯救的。”'),
('CNV', '以赛亚书', 23, 63, 2, '你的服装为什么有红色的呢？你的衣服为什么像个踹压酒池的人的衣服一样呢？'),
('CNV', '以赛亚书', 23, 63, 3, '“我独自踹酒槽；万民之中没有一人与我同在；我在忿怒中把他们踹下，在烈怒中把他们践踏；他们的血溅在我的衣服上，我把我所有的衣裳都染污了。'),
('CNV', '以赛亚书', 23, 63, 4, '因为报仇的日子早已在我的心里，我救赎的年日早已经来到。'),
('CNV', '以赛亚书', 23, 63, 5, '我观看，但没有人帮助；我诧异，因没有人扶持；所以我用自己的膀臂为我施行了拯救，我的烈怒扶持了我，'),
('CNV', '以赛亚书', 23, 63, 6, '我在忿怒中践踏万民，在烈怒中使他们沉醉，又把他们的血倒在地上。”'),
('CNV', '以赛亚书', 23, 63, 7, '我照着主为我们所作的一切，提说主的慈爱，主可称颂的事，和他赐给以色列家的大福，就是照着他的怜悯和丰盛的慈爱为他们作成的。'),
('CNV', '以赛亚书', 23, 63, 8, '他曾说：“他们真是我的子民，不行虚假的儿子”，于是，在他们的一切苦难中，他就作了他们的拯救者。'),
('CNV', '以赛亚书', 23, 63, 9, '他不再是敌对者，并且他面前的使者拯救了他们。他以自己的爱和怜悯救赎了他们；在古时的一切日子，他背负他们，怀抱他们。'),
('CNV', '以赛亚书', 23, 63, 10, '可是，他们竟然悖逆，使他的圣灵忧伤；所以他转作他们的仇敌，亲自攻击他们。'),
('CNV', '以赛亚书', 23, 63, 11, '那时，他们想起古时的日子，就是摩西和他的人民的日子，说：那把人民和他羊群的牧者从海里领上来的，在哪里呢？那把自己的圣灵降在他们中间的，在哪里呢？'),
('CNV', '以赛亚书', 23, 63, 12, '那使自己荣耀的膀臂在摩西的右边行走，那在他们面前把水分开，为要建立永远的名的，他在哪里呢？'),
('CNV', '以赛亚书', 23, 63, 13, '那带领他们走过深海，像马走过旷野一样，使他们不致跌倒的，在哪里呢？'),
('CNV', '以赛亚书', 23, 63, 14, '主的灵使他们得了安息，好像牲畜下到山谷；你也这样引导你的人民，为要建立荣耀的名。'),
('CNV', '以赛亚书', 23, 63, 15, '求你从天上垂顾，从你圣洁、荣耀的居所观看。你的热心和你的大能在哪里呢？你爱心的同情和怜悯向我止住了。'),
('CNV', '以赛亚书', 23, 63, 16, '亚伯拉罕虽然不认识我们，以色列也不承认我们，但你是我们的父。主啊！你是我们的父，从亘古以来，你的名字就是“我们的救赎主”。'),
('CNV', '以赛亚书', 23, 63, 17, '主啊！你为什么使我们走错，离开你的道路？使我们的心刚硬，不敬畏你呢？求你为你众仆人的缘故，为你产业的各支派的缘故，回心转意吧！'),
('CNV', '以赛亚书', 23, 63, 18, '你的圣民不过暂时得着你的圣所，我们的敌人已经践踏了你的圣所。'),
('CNV', '以赛亚书', 23, 63, 19, '我们成了好像你从未治理过的人，又像未曾得称为你名下的人。'),
('CNV', '以赛亚书', 23, 64, 1, '愿你裂天而降！（本节在《马索拉文本》为63:19）愿群山都在你面前震动！'),
('CNV', '以赛亚书', 23, 64, 2, '好像火烧着干柴，又像火把水烧开，使你的敌人认识你的名，使列国在你面前发颤。（本节在《马索拉文本》为64:1）'),
('CNV', '以赛亚书', 23, 64, 3, '你行了可畏的事，是我们料想不到的，那时你降临，群山都在你面前震动。'),
('CNV', '以赛亚书', 23, 64, 4, '从古时以来，人未曾听过，耳未曾闻过，眼未曾见过，在你以外还有什么神，能为等候他的人行事的。'),
('CNV', '以赛亚书', 23, 64, 5, '你善待那些喜欢行义，在你的道路上记念你的人。看哪！你曾发怒，因为我们犯了罪；这样的情形已经很久，我们还能得救吗？'),
('CNV', '以赛亚书', 23, 64, 6, '我们众人都像不洁净的人，我们所有的义，都像污秽的衣服；我们众人都像叶子枯干，我们的罪孽好像风一般把我们吹去。'),
('CNV', '以赛亚书', 23, 64, 7, '没有人呼求你的名，没有人奋起抓着你；因为你掩面不顾我们，使我们在自己罪孽的权势下融化。'),
('CNV', '以赛亚书', 23, 64, 8, '主啊！现在你还是我们的父；我们不过是泥土，你才是陶匠；我们众人都是你手所作的。'),
('CNV', '以赛亚书', 23, 64, 9, '主啊！求你不要大发烈怒。不要永远记念罪孽。求你垂看我们，我们众人都是你的子民。'),
('CNV', '以赛亚书', 23, 64, 10, '你的圣城变了旷野，锡安成了旷野，耶路撒冷成了荒场。'),
('CNV', '以赛亚书', 23, 64, 11, '我们那圣洁和荣美的殿，就是我们的列祖赞美你的所在，被火烧了。我们所喜爱的一切，都成了废墟。'),
('CNV', '以赛亚书', 23, 64, 12, '主啊！对这些事你还忍得住吗？你仍然缄默不言，使我们受苦到极点吗？'),
('CNV', '以赛亚书', 23, 65, 1, '没有求问我的，我让他们寻着；没有寻找我的，我让他们遇见。没有呼求我名的国，我对他们说：“我在这里！我在这里！”'),
('CNV', '以赛亚书', 23, 65, 2, '我整天向着悖逆的子民伸开双手，他们随着自己的意念行不善的道。'),
('CNV', '以赛亚书', 23, 65, 3, '这人民常常当面惹我发怒，在园中献祭，在砖坛上烧香，'),
('CNV', '以赛亚书', 23, 65, 4, '坐在坟墓之间，在隐密处过夜，吃猪肉，他们的器皿中有不洁之物作的汤，'),
('CNV', '以赛亚书', 23, 65, 5, '并且对人说：“你站远一点！不要挨近我，因为我会使你圣洁。”主说：“这些人是我鼻中的烟，是整天烧着的火。'),
('CNV', '以赛亚书', 23, 65, 6, '看哪！这都写在我面前，我必不缄默不言，我非报应不可，我必报应在他们的怀中。'),
('CNV', '以赛亚书', 23, 65, 7, '我要同时报应你们的罪孽和你们列祖的罪孽，这是主说的，因为他们曾在山上烧过香，在冈陵上讥笑过我，我必把他们以前所行的量在他们的怀中。”'),
('CNV', '以赛亚书', 23, 65, 8, '主这样说：“人怎样发现累累葡萄中有新酒的时候，就说：‘不要毁灭它，因为有好处在里面’，我因我的众仆人的缘故也必照样而行，不把它们全都毁灭。'),
('CNV', '以赛亚书', 23, 65, 9, '我要从雅各中领出后裔，从犹大中领出承受我众山的；我拣选的人必承受那地为业，我的众仆人必在那里居住。'),
('CNV', '以赛亚书', 23, 65, 10, '沙仑平原必成为羊群的牧场，亚割谷要成为牛群躺卧之处，都为那些寻求我的子民所得。'),
('CNV', '以赛亚书', 23, 65, 11, '“但至于你们，你们这些离弃主的，忘记我的圣山的，为迦得神摆设筵席的，给弥尼神盛满调和之酒的，'),
('CNV', '以赛亚书', 23, 65, 12, '我要命定你们归在刀下，你们众人都要屈身被杀；因为我呼唤，你们不回答；我说话，你们都不听。反倒行我眼中看为恶的事，拣选我不喜悦的事。”'),
('CNV', '以赛亚书', 23, 65, 13, '因此主神这样说：“看哪！我的众仆人必有吃的，你们却要饥饿；看哪！我的仆人必有喝的，你们却要口渴；看哪！我的仆人必要欢喜，你们却要蒙羞；'),
('CNV', '以赛亚书', 23, 65, 14, '看哪！我的仆人必因心里高兴而欢呼，你们却要因心中伤痛而哀叫，因灵里破碎而哀号。'),
('CNV', '以赛亚书', 23, 65, 15, '你们必留下自己的名，作我选民的咒语；主神必杀死你们，必用另外的名去称呼他自己的仆人。'),
('CNV', '以赛亚书', 23, 65, 16, '所以，在地上为自己求福的，必凭着真实的神求福；在地上起誓的，必凭着真实的神起誓。因为先前的患难都已经被人忘记了，也从我的眼前隐藏了。'),
('CNV', '以赛亚书', 23, 65, 17, '“看哪！我要创造新天新地；先前的事不再被人记念，也不再涌上心头了。'),
('CNV', '以赛亚书', 23, 65, 18, '你们要因我所创造的永远欢喜快乐；因为我创造耶路撒冷成为快乐，使她的居民欢乐。'),
('CNV', '以赛亚书', 23, 65, 19, '我必因耶路撒冷快乐，因我的子民欢喜；他们中间必不再听到哭泣的声音，也不再听到哀号的声音。'),
('CNV', '以赛亚书', 23, 65, 20, '那里必再没有数日夭折的婴孩，也没有不满寿数的老人；因为百岁而死的人，仍算是年轻人；有活不到百岁而死的人算是被咒诅的。'),
('CNV', '以赛亚书', 23, 65, 21, '他们必建造房屋，住在其中；他们必栽种葡萄园，吃其中的果子。'),
('CNV', '以赛亚书', 23, 65, 22, '他们不建造由别人来居住的房屋；他们不栽种由别人来享用的葡萄园；因为我的子民的日子必像树木的日子；我的选民必充分享用他们亲手作工得来的。'),
('CNV', '以赛亚书', 23, 65, 23, '他们必不徒然劳碌，他们生孩子不再受惊吓，因为他们都是蒙主赐福的后裔，他们的子孙也跟他们一样。'),
('CNV', '以赛亚书', 23, 65, 24, '那时，他们还未呼求，我就应允，他们还在说话，我就垂听。'),
('CNV', '以赛亚书', 23, 65, 25, '豺狼必与羊羔在一起吃东西，狮子要像牛一样吃草，蛇必以尘土为食物。在我圣山的各处，它们都必不作恶，也不害物；这是主说的。”'),
('CNV', '以赛亚书', 23, 66, 1, '主这样说：“天是我的宝座，地是我的脚凳；你们要在哪里为我建造殿宇呢？怎样的地方才是我安息的所在呢？”'),
('CNV', '以赛亚书', 23, 66, 2, '主说：“这一切都是我亲手所造的，所以它们就有了。以下这种人是我要垂顾的，就是谦卑、心灵伤痛、因我的话而战兢的人。'),
('CNV', '以赛亚书', 23, 66, 3, '宰牛献祭，又杀人，献羊羔为祭，又打折狗的颈项；献上素祭，又献上猪血；烧乳香作记念祭，又称颂虚无之神；他们选择他们自己的道路，他们的心里喜悦他们那些可憎恶的事。'),
('CNV', '以赛亚书', 23, 66, 4, '所以，我也必选择迷惑他们的事，使他们所惧怕的临到他们身上；因为我呼唤你们，却没有人回答；我说话，你们都不听，反倒行我眼中看为恶的事，选择我所不喜悦的事。”'),
('CNV', '以赛亚书', 23, 66, 5, '因主的话而战兢的人哪！你们要听他的话。他说：“你们的兄弟，就是那些憎恨你们、因我的名赶走你们的，曾说：‘愿主得荣耀；让我们看见你们的喜乐。’他们却要蒙羞。'),
('CNV', '以赛亚书', 23, 66, 6, '听啊！有喧嚷的声音出自城中；有声音出于殿里。这是主向他的仇敌施行报应的声音！'),
('CNV', '以赛亚书', 23, 66, 7, '锡安没有绞痛就生产；疼痛没有临到她身上，就生了一个男孩。'),
('CNV', '以赛亚书', 23, 66, 8, '像以下这样的事，谁曾听过呢？像下面这些事，谁曾见过呢？一地之民能在一天之内就产生吗？一国的人能在一时之间就生下来吗？但锡安一绞痛，就生下了儿女。'),
('CNV', '以赛亚书', 23, 66, 9, '主说：‘我既然使她临盆，又怎能不使她生产呢？’你的神说：‘我既然使她生产，又怎能使她闭胎不生呢？’'),
('CNV', '以赛亚书', 23, 66, 10, '所有爱慕耶路撒冷的人哪！你们都要与她一同欢喜，都要因她快乐；所有为耶路撒冷哀悼的人哪！你们都要与她一同尽情欢乐。'),
('CNV', '以赛亚书', 23, 66, 11, '好使你们能在她那安慰人的怀里吃奶得饱；使你们能从她丰盛的荣耀里挤奶而吃，满心喜乐。”'),
('CNV', '以赛亚书', 23, 66, 12, '因为主这样说：“看哪！我必使平安达到她那里，好像江河一样，使列国的财宝达到她那里，如同涨溢的河流一般；你们要吮奶，你们必被抱在怀中，抚弄在膝上。'),
('CNV', '以赛亚书', 23, 66, 13, '人怎样受他母亲的安慰，我也怎样安慰你们；你们要在耶路撒冷得安慰。”'),
('CNV', '以赛亚书', 23, 66, 14, '你们看见了，就心里快乐，你们的骨头必像嫩草一样长起来，主的手必向他的仆人显现，他必向他的仇敌发怒。'),
('CNV', '以赛亚书', 23, 66, 15, '看哪！主必在火中降临，他的战车好像旋风；他要以猛烈的怒气施行报应，用火焰施行斥责。'),
('CNV', '以赛亚书', 23, 66, 16, '因为主必用火和刀剑，在所有的人身上施行审判，被主所杀的人必定很多。'),
('CNV', '以赛亚书', 23, 66, 17, '那些自己分别为圣，又洁净自己，进到园里，在园中一个跟一个，吃猪肉、老鼠和可憎之物。他们都必一同灭亡；这是主说的。'),
('CNV', '以赛亚书', 23, 66, 18, '我知道他们的行为和意念；我要来，聚集万国万族；他们都必来看我的荣耀。'),
('CNV', '以赛亚书', 23, 66, 19, '我要在他们中间施行神迹，从他们中间差遣所有逃脱的人到列国去，就是到他施、普勒、善于拉弓的路德、土巴和雅完，以及从未听过我的名声、从未见过我的荣耀的遥远众海岛；他们必把我的荣耀传扬在列国中。'),
('CNV', '以赛亚书', 23, 66, 20, '他们要从万国中用马、用车、用轿、用骡子、用独峰驼，把你们所有的兄弟都送到我的圣山耶路撒冷来，作供物献给主，好像以色列人用洁净的器皿把供物送到主的殿一样；这是主说的。'),
('CNV', '以赛亚书', 23, 66, 21, '主说：“我也必从他们中间取些人作祭司和作利未人。”'),
('CNV', '以赛亚书', 23, 66, 22, '主说：“我所要造的新天新地怎样在我面前留存，你们的后裔和你们的名字也必怎样长存。'),
('CNV', '以赛亚书', 23, 66, 23, '将来每逢月朔，每逢安息日，所有的人都必来在我面前敬拜；这是主说的。'),
('CNV', '以赛亚书', 23, 66, 24, '他们要出去，观看那些悖逆我的人的尸体；因为他们的虫是不死的，他们的火是不灭的；他们必成为所有人恨恶的东西。”'),
('CNV', '耶利米书', 24, 1, 1, '便雅悯地亚拿突城的一位祭司，希勒家的儿子耶利米的话记在下面。'),
('CNV', '耶利米书', 24, 1, 2, '犹大王亚们的儿子约西亚作王第十三年，主的话临到耶利米。'),
('CNV', '耶利米书', 24, 1, 3, '从犹大王约西亚的儿子约雅敬年间，直到犹大王约西亚的儿子西底家末年，就是第十一年五月，耶路撒冷人被掳的时候，主的话也常临到耶利米。'),
('CNV', '耶利米书', 24, 1, 4, '主的话临到我，说：'),
('CNV', '耶利米书', 24, 1, 5, '“我使你在母腹中成形以先，就认识你；你还未出母胎，我已把你分别为圣，立你作列国的先知。”'),
('CNV', '耶利米书', 24, 1, 6, '我就说：“主神啊！我不晓得说话，因为我年轻。”'),
('CNV', '耶利米书', 24, 1, 7, '主对我说：“你不要说：‘我年轻’，因为无论我差你到谁那里，你都要去；无论我吩咐你说什么，你都要说。'),
('CNV', '耶利米书', 24, 1, 8, '你不要怕他们，因为我与你同在，要拯救你。”这是主的宣告。'),
('CNV', '耶利米书', 24, 1, 9, '于是主伸手按着我的口，对我说：“看哪！我把我的话放在你口中。'),
('CNV', '耶利米书', 24, 1, 10, '今日我立你在列邦列国之上，为要拔出、拆毁、毁灭、倾覆，又要建立和栽植。”'),
('CNV', '耶利米书', 24, 1, 11, '主的话又临到我，说：“耶利米，你看见什么？”我说：“我看见一根杏树枝子。”'),
('CNV', '耶利米书', 24, 1, 12, '主对我说：“你看得不错，因为我要留意使我的话成就。”'),
('CNV', '耶利米书', 24, 1, 13, '主的话再次临到我，说：“你看见什么？”我说：“我看见一个沸腾的锅，锅口从北面向南倾侧。”'),
('CNV', '耶利米书', 24, 1, 14, '主对我说：“必有灾祸从北方发出，临到这地所有的居民。'),
('CNV', '耶利米书', 24, 1, 15, '看哪！我要呼召北方列国的众族，他们要来，各人在耶路撒冷的城门口，设立自己的座位，攻击耶路撒冷周围的城墙，又攻击犹大各城镇。”这是主的宣告。'),
('CNV', '耶利米书', 24, 1, 16, '“为了他们的一切恶事，就是离弃我，向别神烧香，叩拜自己手所做的，我要宣判他们的罪。'),
('CNV', '耶利米书', 24, 1, 17, '“因此，你要束腰，你要起来，把我吩咐你的一切话，都告诉他们。不要因他们惊惶，不然我就使你在他们面前惊惶。'),
('CNV', '耶利米书', 24, 1, 18, '看哪！今日我使你成为坚城、铁柱、铜墙，抵挡全地，就是抵挡犹大的君王、首领、祭司和这地的众民。'),
('CNV', '耶利米书', 24, 1, 19, '他们必攻击你，却不能胜过你，因为我与你同在，要拯救你。”这是主的宣告。'),
('CNV', '耶利米书', 24, 2, 1, '主的话临到我，说：'),
('CNV', '耶利米书', 24, 2, 2, '“你去在耶路撒冷人的耳中呼叫，说：‘主这样说：你年轻时的恩爱，新婚时的爱情，你怎样在旷野、在未曾耕种之地跟从我，我都记得。'),
('CNV', '耶利米书', 24, 2, 3, '那时，以色列归主为圣，作他初熟的土产。吞吃她的，都算为有罪，灾祸必临到他们。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 2, 4, '雅各家啊！以色列家的各族啊！你们要听主的话。'),
('CNV', '耶利米书', 24, 2, 5, '主这样说：“你们列祖在我身上究竟发现了什么不义，使他们远离我，随从虚无的偶像，自己也成了虚妄呢？'),
('CNV', '耶利米书', 24, 2, 6, '他们也不问：‘那领我们从埃及地上来，引导我们走过旷野，走过荒漠有深坑之地、干旱死荫之地、无人经过、无人居住之地的主在哪里呢？’'),
('CNV', '耶利米书', 24, 2, 7, '我领你们进入这肥美之地，得吃其中的果子和美物；可是你们一进来，就玷污了我的地；你们使我的产业成为可憎恶的。'),
('CNV', '耶利米书', 24, 2, 8, '众祭司都不问：‘主在哪里？’律法师不认识我，官长悖逆我，先知奉巴力的名说预言，跟从那无益的偶像。'),
('CNV', '耶利米书', 24, 2, 9, '因此，我要再跟你们争辩，也要跟你们的子孙争辩。”这是主的宣告。'),
('CNV', '耶利米书', 24, 2, 10, '“你们尽管过到基提海岛察看，派人去基达仔细查考，看看曾有这样的事没有。'),
('CNV', '耶利米书', 24, 2, 11, '有哪一国把自己的神换掉呢？其实那些并不是神。我的子民竟把他们的荣耀，换了无益的偶像。'),
('CNV', '耶利米书', 24, 2, 12, '诸天哪！你们要因此震惊，要大大战栗，极其凄凉。”这是主的宣告。'),
('CNV', '耶利米书', 24, 2, 13, '“因为我的子民作了两件恶事，就是离弃了我这活水的泉源，为自己凿了池子，是破裂不能存水的池子。'),
('CNV', '耶利米书', 24, 2, 14, '“以色列岂是奴隶，或是在家中生的奴仆呢？为什么竟成了掠物呢？'),
('CNV', '耶利米书', 24, 2, 15, '幼狮都向他咆哮，大声吼叫，使他的地荒凉，城中破毁，无人居住。'),
('CNV', '耶利米书', 24, 2, 16, '挪弗人和答比匿人也剃光了你的头顶。'),
('CNV', '耶利米书', 24, 2, 17, '你这不是自作自受吗？主你的神在路上引导你时，你却离弃了他。'),
('CNV', '耶利米书', 24, 2, 18, '现在，你为什么要到埃及去，喝西曷的水呢？你为什么要到亚述去，喝幼发拉底河的水呢？'),
('CNV', '耶利米书', 24, 2, 19, '你自己的罪恶要惩罚你，你背道的事必责备你。你当知道，也要明白，离弃主你的神，没有畏惧我的心，是邪恶的，是痛苦的。”这是主万军之主的宣告。'),
('CNV', '耶利米书', 24, 2, 20, '“你从古时就折断了自己的轭，解开了自己的绳索，说：‘我不事奉你了。’你在每个高冈上，在每棵繁茂树下，蹲伏行淫。'),
('CNV', '耶利米书', 24, 2, 21, '我栽你时原是上等的葡萄树，是绝对纯种的；你怎么在我面前变为坏枝子，成了野葡萄呢？'),
('CNV', '耶利米书', 24, 2, 22, '你虽然用碱洗涤，多加肥皂，你罪孽的污渍仍留在我面前。”这是主神的宣告。'),
('CNV', '耶利米书', 24, 2, 23, '“你怎么能说：‘我没有玷污自己，未曾跟从过巴力’呢？看看你在谷中的行径，想想你所作过的！简直像快捷的小雌驼，在路上乱闯；'),
('CNV', '耶利米书', 24, 2, 24, '又像惯在旷野的野驴，欲心一起就喘气，它春情发动，谁能抑制它呢？寻找它的都不必费力，在它的交配期间，必能找到它。'),
('CNV', '耶利米书', 24, 2, 25, '不要使你的脚赤露，你的喉咙干渴！你却说：‘没用的！因为我爱外族人的神，我要跟从他们！’'),
('CNV', '耶利米书', 24, 2, 26, '“贼被捉拿时怎样羞愧，以色列家和他们的君王、领袖、祭司和先知，也都怎样羞愧。'),
('CNV', '耶利米书', 24, 2, 27, '他们对木头说：‘你是我爸爸’；对石头说：‘你是生我的’。他们以背向我，不以脸向我；然而遭遇患难时却说：‘起来，救救我们吧！’'),
('CNV', '耶利米书', 24, 2, 28, '你为自己所做的神在哪里？你遭遇患难时，如果他们能救你，就让他们起来吧！犹大啊！你的城有多少，你的神也有多少！'),
('CNV', '耶利米书', 24, 2, 29, '你们为什么跟我争辩呢？你们都悖逆了我！”这是主的宣告。'),
('CNV', '耶利米书', 24, 2, 30, '“我责打你们的儿女也是没用，因为他们不受管教。你们的刀剑，像灭命的狮子吞噬你们的先知。'),
('CNV', '耶利米书', 24, 2, 31, '这世代的人哪！你们要注意主的话：‘对以色列人来说，难道我是旷野，或是黑暗的地方？我的子民为什么说：我们自由了，不再到你那里去了？'),
('CNV', '耶利米书', 24, 2, 32, '少女能忘记她的饰物吗？新妇能忘记她的华带吗？我的子民却忘记了我，这些日子无法数算。'),
('CNV', '耶利米书', 24, 2, 33, '你多么通晓门路，去寻求爱情！就连坏女人，你也可以把门路指教她们。'),
('CNV', '耶利米书', 24, 2, 34, '在你衣襟上又发现无辜穷人的血，并且你不是发现他们在挖窟窿时杀他们的。虽然这样，'),
('CNV', '耶利米书', 24, 2, 35, '你还说：我是无辜的，他的怒气必已离开我。看哪！我要审判你，因为你曾说：我没有犯罪！'),
('CNV', '耶利米书', 24, 2, 36, '你为什么要东奔西跑，改变你的路向呢？你必因埃及蒙羞，像你从前因亚述受辱一样。'),
('CNV', '耶利米书', 24, 2, 37, '你必双手抱头从埃及出来，因为主弃绝了你所倚靠的，你靠他们必不能成功。’”'),
('CNV', '耶利米书', 24, 3, 1, '主说：“人若是休妻，妻子离开了他，又嫁了别人，前夫怎能与她复合呢？如果复合，那地不是大大玷污了吗？你曾与许多情人行淫，还想归向我。”这是主的宣告。'),
('CNV', '耶利米书', 24, 3, 2, '“你向光秃的高冈举目看看，哪里没有你的淫迹？你坐在路边等候情人，像阿拉伯人在旷野埋伏一样。你以淫乱和邪恶，把这地玷污了。'),
('CNV', '耶利米书', 24, 3, 3, '所以甘霖停止，春雨不降；你还是一副妓女的面孔（“面孔”原文作“额”），不顾羞耻。'),
('CNV', '耶利米书', 24, 3, 4, '你刚刚不是还呼叫我：‘我父啊！你是我年轻时的良伴；'),
('CNV', '耶利米书', 24, 3, 5, '主怎会永远怀怒，常存愤恨呢？’你虽然这样说了，还是尽力去作恶。”'),
('CNV', '耶利米书', 24, 3, 6, '约西亚王在位的日子，主对我说：“背道的以色列所作的，她怎样走上各高山，在每棵繁茂的树下行淫，你看见了没有？'),
('CNV', '耶利米书', 24, 3, 7, '我以为她作了这些事以后，就必回转过来，可是她没有回转。她诡诈的妹妹犹大也看见了。'),
('CNV', '耶利米书', 24, 3, 8, '因背道的以色列犯了淫乱，我就给她休书，把她休了。我看见她诡诈的妹妹犹大还是不惧怕，照样行淫。'),
('CNV', '耶利米书', 24, 3, 9, '因以色列把自己的淫行视作等闲，去与石头木头行淫，就把这地玷污了。'),
('CNV', '耶利米书', 24, 3, 10, '虽然这样，她诡诈的妹妹犹大还没有全心归向我，只是假意地归我。”这是主的宣告。'),
('CNV', '耶利米书', 24, 3, 11, '主对我说：“背道的以色列，比诡诈的犹大还显得正义。'),
('CNV', '耶利米书', 24, 3, 12, '你去，把这些话向北方宣告，说：‘背道的以色列啊，回转吧！’这是主的宣告。‘我必不向你们变脸，因为我是慈爱的，我必不永远怀怒。’这是主的宣告。'),
('CNV', '耶利米书', 24, 3, 13, '‘只要你承认自己的罪孽，就是悖逆了主你的神，在每棵繁茂的树下，滥爱外族人的神，没有听从我的话。’这是主的宣告。'),
('CNV', '耶利米书', 24, 3, 14, '‘背道的人哪，回转吧！’这是主的宣告。‘因为我才是你们的主。我要每城取一人，每族取二人，把你们带到锡安。'),
('CNV', '耶利米书', 24, 3, 15, '“我必把合我心意的牧人赐给你们，他们要用知识和智慧牧养你们。'),
('CNV', '耶利米书', 24, 3, 16, '当那些日子，你们在这地繁衍增多的时候，人必不再提说主的约柜，不把它放在心上，不思念它，不觉得缺少，也不再制造。’这是主的宣告。'),
('CNV', '耶利米书', 24, 3, 17, '‘那时，人必称耶路撒冷为主的宝座，万国要聚集到她那里，因主名的缘故来到耶路撒冷；他们必不再随从自己顽梗的恶心行事。'),
('CNV', '耶利米书', 24, 3, 18, '在那些日子，犹大家必与以色列家同行，他们必从北方之地一同来到我赐给你们列祖为业的地方。’”'),
('CNV', '耶利米书', 24, 3, 19, '“我说：‘我待你，像待儿女一样，赐给你佳美之地，就是列国中最美好的产业；我以为你会称我为父，不再离去不跟从我了。'),
('CNV', '耶利米书', 24, 3, 20, '以色列家啊！妻子怎样行奸诈对丈夫不忠，你也照样以奸诈待我。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 3, 21, '在光秃的高冈听到人声，就是以色列人哭泣恳求的声音；因为他们改转了自己的道路，忘记了主他们的神。'),
('CNV', '耶利米书', 24, 3, 22, '“背道的人哪，回转吧！我必医治你们背道的病。”“看哪！我们来到你这里，因为你是主我们的神！'),
('CNV', '耶利米书', 24, 3, 23, '小山和大山上的喧嚷，真是徒然的，以色列的救恩诚然在于主我们的神。'),
('CNV', '耶利米书', 24, 3, 24, '从我们幼年以来，我们列祖劳苦得来的，他们的牛羊，他们的儿女，都给那可耻的偶像吞掉了。'),
('CNV', '耶利米书', 24, 3, 25, '但愿我们躺卧在羞耻中，让惭愧遮盖着我们！因为我们得罪了主我们的神，从我们幼年直到现在，我们和列祖都没有听从主我们的神的话。”'),
('CNV', '耶利米书', 24, 4, 1, '“以色列啊！你要是回转，就当回转归向我。”这是主的宣告。“如果你从我面前除掉你可憎的偶像，不到处浪荡；'),
('CNV', '耶利米书', 24, 4, 2, '如果你凭真理、公正、公义，指着永活的主起誓；列国就必因主蒙福，也必以他为荣。”'),
('CNV', '耶利米书', 24, 4, 3, '主对犹大和耶路撒冷的人这样说：“你们要为自己开垦未经耕耘之地，却不要撒种在荆棘中！'),
('CNV', '耶利米书', 24, 4, 4, '犹大人和耶路撒冷的居民哪！你们要为了主的缘故自行割礼，除去心里的污秽；不然，我的忿怒必因你们的恶行，如火一般发出来，无人能熄灭！”'),
('CNV', '耶利米书', 24, 4, 5, '“你们应当在犹大宣告，在耶路撒冷传扬，说：‘要在境内吹号。’高声呼叫，说：‘你们要集合起来，我们要进到坚固的城里去！’'),
('CNV', '耶利米书', 24, 4, 6, '要向锡安竖起旗号，赶快逃命，不可停留，因为我必使灾祸与严重的毁灭，从北方而来。”'),
('CNV', '耶利米书', 24, 4, 7, '狮子从它的密林中上来了，毁坏列国的已经动身，从他的本处出发，为要使你的地荒凉，使你的城市破毁，无人居住。'),
('CNV', '耶利米书', 24, 4, 8, '因此，你们应当披上麻布，痛哭哀号，因为主的烈怒，还没有离开我们。'),
('CNV', '耶利米书', 24, 4, 9, '“到那日，君王和首领的勇气消失，祭司也要惊惶，先知都必诧异。”这是主的宣告。'),
('CNV', '耶利米书', 24, 4, 10, '于是我说：“噢！主神啊！你真的欺骗了这人民，也欺骗了耶路撒冷，说：‘你们必平安无事’，其实刀剑已经架在颈项上了！”'),
('CNV', '耶利米书', 24, 4, 11, '到那时，必有话对这人民和耶路撒冷说：“有一阵热风从旷野光秃的高冈，刮向我的子民（“我的子民”原文作“我子民的女子”），不是为簸散，也不是为扬净；'),
('CNV', '耶利米书', 24, 4, 12, '这过强的风要为我刮来，我就要向他们宣告我的判词。”'),
('CNV', '耶利米书', 24, 4, 13, '看哪！他必如密云涌聚，他的战车如旋风，他的马比鹰还快。我们有祸了，我们灭亡了！'),
('CNV', '耶利米书', 24, 4, 14, '耶路撒冷啊！洗净你心中的邪恶，使你可以得救！你心存恶念，要到几时呢？'),
('CNV', '耶利米书', 24, 4, 15, '因为有声音从但宣告，从以法莲山传出灾祸的警报。'),
('CNV', '耶利米书', 24, 4, 16, '“要向列国提说，向耶路撒冷宣扬：‘围攻的人从远地而来，向犹大的各城镇大声吶喊。'),
('CNV', '耶利米书', 24, 4, 17, '他们四面包围耶路撒冷，好像看守田地的人一样，因为耶路撒冷背叛了我。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 4, 18, '“你这一切灾祸是你的所作所为作成的，这就是你的恶果，实在是苦，直透心底。”'),
('CNV', '耶利米书', 24, 4, 19, '我的肺腑，我的肺腑啊！我绞痛欲绝。我的心哪！我的心在我里面颤抖，我不能缄默不语。我的灵啊！我听见了号角的声音，也听见了战争的吶喊。'),
('CNV', '耶利米书', 24, 4, 20, '毁灭的消息频传，因为全国尽都毁坏，我的帐棚忽然毁坏，我的幔子转瞬破裂。'),
('CNV', '耶利米书', 24, 4, 21, '我看见旗号要到几时呢？我听见号角的声音要到几时呢？'),
('CNV', '耶利米书', 24, 4, 22, '“我的子民愚妄，他们连我都不认识，是无知的儿女，没有悟性；他们有智慧行恶，却没有知识行善。”'),
('CNV', '耶利米书', 24, 4, 23, '我观看地，地是空虚混沌；我仰视天，天上也全然无光。'),
('CNV', '耶利米书', 24, 4, 24, '我观看大山，它们尽都震动，小山也都摇来摇去。'),
('CNV', '耶利米书', 24, 4, 25, '我观看，毫无人迹；空中的飞鸟也逃掉了。'),
('CNV', '耶利米书', 24, 4, 26, '我观看，肥美田园变为荒野；在主面前，就是在他烈怒之下，所有的城市都被拆毁。'),
('CNV', '耶利米书', 24, 4, 27, '因为主这样说：“全国都必荒凉，我却不尽行毁灭。'),
('CNV', '耶利米书', 24, 4, 28, '因此，地要悲哀，天必昏暗。因为我说过，就不后悔；我定了意，决不改变。”'),
('CNV', '耶利米书', 24, 4, 29, '因着骑兵和弓箭手的响声，各城的人尽都逃跑。他们进入密林，爬上岩穴；各城都被撇下，无人住在其中。'),
('CNV', '耶利米书', 24, 4, 30, '你这被毁坏的啊！你在干什么？即使你穿上朱红色的服装，佩戴黄金饰物，用颜料画大你的眼睛，你自炫漂亮，也是白费的。爱你的人仍然鄙视你，他们都在寻索你的命！'),
('CNV', '耶利米书', 24, 4, 31, '我听到好像妇人产痛的叫声，正像生头胎孩子的妇人疼痛的叫声，就是锡安居民（“居民”原文作“女子”）的声音，他们喘着气，伸开双手，说：“哎！我有祸了！在那些杀人者跟前，我发昏了！”'),
('CNV', '耶利米书', 24, 5, 1, '“你们去走遍耶路撒冷的街道，到处观察留意，又在城的广场上寻觅；如果能找到一个行正义、求诚实的人，我就赦免这城。'),
('CNV', '耶利米书', 24, 5, 2, '城里的人虽然指着永活的主起誓，其实，他们起的誓是假的。”'),
('CNV', '耶利米书', 24, 5, 3, '主啊！你的眼目不是要看诚实的事吗？你击打他们，他们却不觉得伤痛；你摧毁他们，他们仍不肯接受管教。他们板着脸，脸皮比磐石还硬，总不肯回转。'),
('CNV', '耶利米书', 24, 5, 4, '我说：“这些人只是贫穷小民，为人愚昧；他们不晓得主的道路，也不明白他们神的法则。'),
('CNV', '耶利米书', 24, 5, 5, '我要亲自去见那些权贵领袖，跟他们谈谈；因为他们晓得主的道路，也明白他们神的法则。”谁知他们竟一起把轭折断，挣脱绳索。'),
('CNV', '耶利米书', 24, 5, 6, '因此，狮子必从林中出来袭击他们，旷野的豺狼要杀害他们，豹子在他们的城边窥伺，出城的都必被撕碎；因为他们的过犯众多，背道的事也无法数算。'),
('CNV', '耶利米书', 24, 5, 7, '“为什么我要赦免你？你的儿女离弃我，指着那些不是神的起誓。我使他们饱足，他们却去行淫，一起挤在妓院里。'),
('CNV', '耶利米书', 24, 5, 8, '他们像饱食的马，情欲奔放，各向别人的妻子嘶叫。'),
('CNV', '耶利米书', 24, 5, 9, '我因这些事怎能不施行惩罚呢？像这样的国家，我怎能不亲自报复呢？”这是主的宣告。'),
('CNV', '耶利米书', 24, 5, 10, '“你们要走进她的葡萄园（“葡萄园”原文作“葡萄树的行列”）里施行毁坏，但不可毁灭净尽，要除掉她的枝子，因为它们不属主。'),
('CNV', '耶利米书', 24, 5, 11, '以色列家和犹大家，待我实在太奸诈了。”这是主的宣告。'),
('CNV', '耶利米书', 24, 5, 12, '他们不信主，说：“他不会作什么，灾祸必不临到我们，我们也不会看见刀剑和饥荒。'),
('CNV', '耶利米书', 24, 5, 13, '先知不过是一阵风，主的道也不在他们里面；他们所说的必临到他们身上。”'),
('CNV', '耶利米书', 24, 5, 14, '因此，主万军之神这样说：“因他们说了这话，我必使我的话在你口中成为火，使这人民成为柴，火要把他们吞灭。'),
('CNV', '耶利米书', 24, 5, 15, '以色列家啊！我必使一国从远方来攻击你们。”这是主的宣告。“那国历久不衰，从古就有；他们的言语你们不懂得，他们所说的你们不明白。'),
('CNV', '耶利米书', 24, 5, 16, '他们的箭囊像敞开的坟墓，他们尽都是勇士。'),
('CNV', '耶利米书', 24, 5, 17, '他们必吞灭你们的庄稼和粮食，吞灭你的儿女，你们的羊群牛群，以及你们的葡萄和无花果；他们也必用刀剑毁坏你们所倚仗的坚固城。'),
('CNV', '耶利米书', 24, 5, 18, '就是到了那时，我也不把你们完全毁灭。”这是主的宣告。'),
('CNV', '耶利米书', 24, 5, 19, '“将来如果有人问：‘主我们的神，为什么向我们行这一切事呢？’你就要对他们说：‘你们怎样离弃我，在你们的土地上事奉外族人的神，你们也要在不属你们的土地上照样服事外族人。’”'),
('CNV', '耶利米书', 24, 5, 20, '你们要在雅各家宣告这事，在犹大传扬，说：'),
('CNV', '耶利米书', 24, 5, 21, '“愚昧无知的民哪！你们有眼不能看，有耳不能听；你们应当听这话：'),
('CNV', '耶利米书', 24, 5, 22, '‘你们连我都不惧怕吗？在我面前你们也不战兢吗？’这是主的宣告。‘我以沙作海的疆界，作永远的界限，海就不能越过；波浪翻腾，却不能漫过；怒涛澎湃，仍无法逾越。'),
('CNV', '耶利米书', 24, 5, 23, '可是这人民，竟存着顽梗悖逆的心；背我而去。’'),
('CNV', '耶利米书', 24, 5, 24, '他们心里也不想想：‘我们应当敬畏主我们的神，他按时赐雨，就是秋雨春霖，又为我们保存定时收割的节令。’'),
('CNV', '耶利米书', 24, 5, 25, '你们的罪孽使这些都离开了，你们的罪恶剥夺了你们的幸福。'),
('CNV', '耶利米书', 24, 5, 26, '在我的子民中发现了恶人，他们好像捕鸟的人蹲伏窥探，装置网罗捕捉人。'),
('CNV', '耶利米书', 24, 5, 27, '笼中怎样满了雀鸟，他们的屋里也满了诡诈；他们就因此财雄势大。'),
('CNV', '耶利米书', 24, 5, 28, '他们肥胖光润，作尽各种坏事；他们不为人辩护，不替孤儿辨屈，使他们获益，也不为穷人伸冤。'),
('CNV', '耶利米书', 24, 5, 29, '我因这些事怎能不施行惩罚呢？像这样的国家，我怎能不亲自报复呢？”这是主的宣告。'),
('CNV', '耶利米书', 24, 5, 30, '“恐怖骇人的事在国中发生了。'),
('CNV', '耶利米书', 24, 5, 31, '先知说假预言，祭司凭己意把持权柄。我的子民竟喜爱这样，到了结局你们怎么办呢？”'),
('CNV', '耶利米书', 24, 6, 1, '“便雅悯人哪！赶快逃命，离开耶路撒冷。你们要在提哥亚吹角，在伯．哈基琳升烽火；因为灾祸和严重的毁灭，已从北方迫近。'),
('CNV', '耶利米书', 24, 6, 2, '美丽高贵的锡安居民（“居民”原文作“女子”），我必除灭你们。'),
('CNV', '耶利米书', 24, 6, 3, '牧人必带着他们的羊群，来到锡安那里，在城的四围支搭帐棚，各在自己的地方分别牧放羊群。”'),
('CNV', '耶利米书', 24, 6, 4, '“你们要备战攻击她！起来！我们趁着正午上去。唉！可惜日渐西沉，暮影拖长了！'),
('CNV', '耶利米书', 24, 6, 5, '起来！我们趁着夜间上去，毁坏她的堡垒。”'),
('CNV', '耶利米书', 24, 6, 6, '因为万军之主这样说：“砍下她的树木，筑垒攻打耶路撒冷；她是那该受惩罚的城，其中尽是欺压的事。'),
('CNV', '耶利米书', 24, 6, 7, '井怎样涌出水来，这城也怎样涌出恶来；城中常常听到强暴和毁灭的事，在我面前不断有病患与创伤。'),
('CNV', '耶利米书', 24, 6, 8, '耶路撒冷啊！应当受警戒，免得我的心与你疏远，免得我使你荒凉，成为无人居住之地。”'),
('CNV', '耶利米书', 24, 6, 9, '万军之主这样说：“任凭他们像摘净葡萄一样对待以色列剩下的人；你要像摘葡萄的人，向枝子伸手，摘了又摘。”'),
('CNV', '耶利米书', 24, 6, 10, '我可以向谁说话，向谁警告，使他们可以听从呢？他们的耳朵未受割礼，不能听闻；看哪！他们以主的话为羞辱，一点也不喜欢。'),
('CNV', '耶利米书', 24, 6, 11, '因此，我心里充满主的忿怒，无法容忍。“你要把我的忿怒向街上的孩童倾倒，又倾在联群集结的年轻人身上。夫妻一起被捉住，年老的、寿高的也不例外。'),
('CNV', '耶利米书', 24, 6, 12, '他们的房屋、田地与妻子，都要一起转归别人；因为我要伸手，攻击这地的居民。”这是主的宣告。'),
('CNV', '耶利米书', 24, 6, 13, '“他们从最小的到最大的，个个都贪图不义之财；从先知到祭司，全都行事诡诈。'),
('CNV', '耶利米书', 24, 6, 14, '他们草率地医治我子民（“我子民”原文作“我子民的女子”）的损伤，说：‘平安了！平安了！’其实没有平安。”'),
('CNV', '耶利米书', 24, 6, 15, '主说：“他们行了可憎的事，本应觉得羞愧，可是他们一点羞愧都没有，恬不知耻。因此他们必仆倒在倒下的人中间，我惩罚他们的时候，他们必倒下来。”'),
('CNV', '耶利米书', 24, 6, 16, '主这样说：“你们要站在路上察看，寻访远古的路径，看哪一条是美善的路，就走在其中；这样，你们心里就必得安息。他们却说：‘我们不走在其中。’'),
('CNV', '耶利米书', 24, 6, 17, '我设立守望的人照管你们，说：‘你们要留心听号角的声音！’他们却说：‘我们不听！’'),
('CNV', '耶利米书', 24, 6, 18, '列国啊！因此你们要听。以色列会众啊！要晓得他们将遭遇的。'),
('CNV', '耶利米书', 24, 6, 19, '大地啊，要听！我必使灾祸临到这人民，这是他们的意图带来的结果；因为他们没有留心听我的话，我的律法他们也弃绝了。'),
('CNV', '耶利米书', 24, 6, 20, '从示巴来的乳香，从远地出的菖蒲，献给我有什么益处呢？你们的燔祭不蒙悦纳，你们的祭祀我不喜悦。”'),
('CNV', '耶利米书', 24, 6, 21, '因此，主这样说：“我要把绊脚石放在这人民的前面，他们父子一起在其上绊倒，邻舍与朋友也都灭亡。”'),
('CNV', '耶利米书', 24, 6, 22, '主这样说：“看哪！有一个民族从北方之地而来，有一大国被激动从地极来到。'),
('CNV', '耶利米书', 24, 6, 23, '他们紧握弓和枪，性情残忍，毫无怜悯；他们的声音像海洋怒吼；锡安的居民（“居民”原文作“女子”）哪！他们骑着战马，在战场上如同一人，列阵攻击你们。”'),
('CNV', '耶利米书', 24, 6, 24, '我们听到有关他们的消息，手就发软；痛苦紧紧抓住我们，我们疼痛好像正在生产的妇人。'),
('CNV', '耶利米书', 24, 6, 25, '你们不要出到田野去，也不要在路上走，因为四围有仇敌的刀剑和惊吓。'),
('CNV', '耶利米书', 24, 6, 26, '我的同胞（“同胞”原文作“人民的女子”）啊！应当披上麻布，在灰尘中打滚，悲哀如丧独生子，号咷痛哭，因为有行毁灭的会突然攻击我们。'),
('CNV', '耶利米书', 24, 6, 27, '“我使你在我子民中作鉴辨和试验的（按照《马索拉文本》，“试验的”作“高台”;现参照《七十士译本》翻译），好让你查察、鉴别他们的行径。”'),
('CNV', '耶利米书', 24, 6, 28, '他们都是十分悖逆的人，到处搬弄是非。他们是铜是铁，他们都是败坏的。'),
('CNV', '耶利米书', 24, 6, 29, '风箱猛烈地吹，铅在火中销熔；他们炼而又炼，徒劳无功，因为邪恶的仍未除去。'),
('CNV', '耶利米书', 24, 6, 30, '人要称他们为被弃的银渣，因为主把他们弃绝了。'),
('CNV', '耶利米书', 24, 7, 1, '主有话临到耶利米，说：'),
('CNV', '耶利米书', 24, 7, 2, '“你要站在主的殿门口，在那里宣告这话，说：‘所有进这些门来敬拜主的犹大人哪！你们都要听主的话。’”'),
('CNV', '耶利米书', 24, 7, 3, '万军之主以色列的神这样说：“你们要改正自己的所作所为，我就让你们在这地方居住。'),
('CNV', '耶利米书', 24, 7, 4, '你们不要倚靠虚谎的话，说：‘这是主的殿，是主的殿，是主的殿。’'),
('CNV', '耶利米书', 24, 7, 5, '如果你们实在改正自己的所作所为，人与人之间认真施行公正；'),
('CNV', '耶利米书', 24, 7, 6, '如果你们不欺压寄居的，不欺压孤儿寡妇，不在这地方流无辜人的血，也不跟从别的神，自招祸患；'),
('CNV', '耶利米书', 24, 7, 7, '我就让你们在赐给你们列祖直到永远的这地方居住。'),
('CNV', '耶利米书', 24, 7, 8, '“可是，你们竟然倚靠虚谎无益的话。'),
('CNV', '耶利米书', 24, 7, 9, '你们怎可偷盗、凶杀、奸淫、起假誓、向巴力烧香，跟从你们素不认识的别神，'),
('CNV', '耶利米书', 24, 7, 10, '然后来到这称为我名下的殿，站在我面前，说：‘我们安全啦！’你们这样就可以行这一切可憎的事吗？'),
('CNV', '耶利米书', 24, 7, 11, '这称为我名下的殿，难道在你们眼中看为贼窝吗？但我都看见了。”这是主的宣告。'),
('CNV', '耶利米书', 24, 7, 12, '“你们可以到示罗我的地方去，就是先前我名的居所，看看我因我子民以色列的邪恶，对那地方所行的。'),
('CNV', '耶利米书', 24, 7, 13, '现在，因你们行了这一切事，我不断恳切告诫你们，你们却不听；我呼唤你们，你们却不答话。”这是主的宣告。'),
('CNV', '耶利米书', 24, 7, 14, '“所以我从前怎样对待示罗，将来也怎样对待你们所倚靠的那称为我名下的殿，以及我赐给你们和你们列祖的地方。'),
('CNV', '耶利米书', 24, 7, 15, '我必把你们从我面前赶出，像我从前赶出你们的众兄弟，以法莲所有的后裔一样。'),
('CNV', '耶利米书', 24, 7, 16, '“至于你，不要为这人民祈祷，不要为他们呼求祷告，也不要为他们向我恳求，因为我不会听你。'),
('CNV', '耶利米书', 24, 7, 17, '他们在犹大的各城中，在耶路撒冷的街道上所行的，你没有看见吗？'),
('CNV', '耶利米书', 24, 7, 18, '儿子捡柴，父亲生火，妇女抟面，为天后做饼，又向别的神浇奠祭，惹我发怒。'),
('CNV', '耶利米书', 24, 7, 19, '他们害的是我吗？岂不是他们自己，以致脸上蒙羞吗？”这是主的宣告。'),
('CNV', '耶利米书', 24, 7, 20, '因此，主神这样说：“看哪！我的怒气和忿怒，必倒在这地方，也必倒在人口、牲畜、田野的树木和地的出产上；怒火烧起，不能熄灭。”'),
('CNV', '耶利米书', 24, 7, 21, '万军之主以色列的神这样说：“你们尽管把燔祭加在平安祭上，自己吃祭肉吧！'),
('CNV', '耶利米书', 24, 7, 22, '因为我把你们列祖从埃及地领出来的那日，燔祭和平安祭的事，我并没有向他们提说，也没有吩咐他们。'),
('CNV', '耶利米书', 24, 7, 23, '我只吩咐他们这一件事，说：‘你们要听从我的话，我就作你们的神，你们也作我的子民；你们要遵行我所吩咐的一切道，好使你们蒙福。’'),
('CNV', '耶利米书', 24, 7, 24, '他们却没有听从，也不留心，反倒按着他们的计谋，随从自己顽梗的恶心行事，向后不向前。'),
('CNV', '耶利米书', 24, 7, 25, '自从你们列祖出埃及地的那日直到今日，我差遣我的仆人众先知到你们那里去，而且是每日不断差遣。'),
('CNV', '耶利米书', 24, 7, 26, '你们（“你们”原文作“他们”）却没有听从，毫不留心，反倒硬着颈项行恶，比你们（“你们”原文作“他们”）的列祖还厉害。'),
('CNV', '耶利米书', 24, 7, 27, '“你要把这一切话告诉他们，他们却不听从你；你呼叫他们，他们也不回应。'),
('CNV', '耶利米书', 24, 7, 28, '然而，你要对他们说：‘这就是不听从主他们神的话，不受管教的国；诚实丧尽，并已从他们的口中断绝了。'),
('CNV', '耶利米书', 24, 7, 29, '“‘你要剪去头发，并且把它抛掉，上到光秃的高冈举哀，因为主摈斥、弃绝了他所憎恨的世代。’”'),
('CNV', '耶利米书', 24, 7, 30, '“因为犹大人行了我看为恶的事，把他们可憎的偶像安放在称为我名下的殿中，污渎了这殿。”这是主的宣告。'),
('CNV', '耶利米书', 24, 7, 31, '“他们在欣嫩子谷中，建造了陀斐特的邱坛，用火焚烧自己的儿女；这不是我吩咐的，我也没有在心里想过。'),
('CNV', '耶利米书', 24, 7, 32, '因此，看哪！日子快到，人必不再称这地方为陀斐特或欣嫩子谷，却要称它为‘杀戮谷’；人必在陀斐特埋葬尸体，甚至无处可容。”这是主的宣告。'),
('CNV', '耶利米书', 24, 7, 33, '“这人民的尸体，也必给空中的飞鸟和地上的野兽作食物，没有人来驱赶。'),
('CNV', '耶利米书', 24, 7, 34, '那时，我必在犹大的城市中和耶路撒冷的街道上，使欢欣和快乐的声音、新郎和新妇的声音止息，因为这地必要变为荒场。”'),
('CNV', '耶利米书', 24, 8, 1, '“到那一天（这是主的宣告），敌人要把犹大列王、首领、祭司、先知和耶路撒冷居民的骸骨，都从他们的坟墓里取出来，'),
('CNV', '耶利米书', 24, 8, 2, '抛散在太阳、月亮和天上的万象之下，就是他们从前所爱慕、服事、跟随、求问、敬拜的。这些骸骨必不再被收殓埋葬，必在地面上成为粪肥。'),
('CNV', '耶利米书', 24, 8, 3, '这邪恶的家族剩下的余民，在我驱逐他们到的各地，宁可选择死，也不要存活。”这是万军之主的宣告。'),
('CNV', '耶利米书', 24, 8, 4, '“你要对他们说：‘主这样说：人跌倒了，不再起来吗？人偏离了，不再回转吗？'),
('CNV', '耶利米书', 24, 8, 5, '这人民为什么背道，耶路撒冷为什么长久偏离？他们定意行诡诈，不肯回转。'),
('CNV', '耶利米书', 24, 8, 6, '我留心听，但他们都不说真实的话。没有人为自己的恶行后悔，说：“我究竟作了什么？”他们各人继续走自己偏差的路，像战马直冲入战场。'),
('CNV', '耶利米书', 24, 8, 7, '连空中的鹳鸟也知道自己来去的季候；斑鸠、燕子和白鹤也谨守迁移的时令；我的子民却不晓得主的法则。'),
('CNV', '耶利米书', 24, 8, 8, '你们怎可以说：“我们是智慧人，我们有主的律法”呢？事实上，经学家虚假的笔已把律法变成谎言了。'),
('CNV', '耶利米书', 24, 8, 9, '智慧人必蒙羞，惊惶失措。看哪！他们弃绝了主的话，他们还有什么智慧呢？'),
('CNV', '耶利米书', 24, 8, 10, '因此，我必把他们的妻子给别人，把他们的田地给别的主人，因为他们从最小的到最大的，个个都贪图不义之财；从先知到祭司，全都行事诡诈。'),
('CNV', '耶利米书', 24, 8, 11, '他们草率地医治我子民（“我子民”原文作“我子民的女子”）的损伤，说：“平安了！平安了！”其实没有平安。’'),
('CNV', '耶利米书', 24, 8, 12, '主说：‘他们行了可憎的事，本应觉得羞愧，可是他们一点羞愧都没有，恬不知耻。因此他们必仆倒在倒下的人中间；我惩罚他们的时候，他们必倒下来。'),
('CNV', '耶利米书', 24, 8, 13, '我要彻底除掉他们的庄稼；葡萄树上必没有葡萄，无花果树上必没有无花果，叶子也必枯干。我赐给他们的，都离开他们过去了。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 8, 14, '我们为什么坐着不动呢？你们要集合起来，我们要进入坚固的城里去，在那里灭亡吧！因为主我们的神要我们灭亡，又把毒水给我们喝，因我们得罪了主。'),
('CNV', '耶利米书', 24, 8, 15, '我们期待平安，却得不到好处；期待得医治的时候，不料，只有惊慌。'),
('CNV', '耶利米书', 24, 8, 16, '从但那里听见敌人战马的喷气声，全地因听见壮马的嘶鸣声震动。他们来是要吞灭土地和地上所有的，要吞灭城和城中的居民。'),
('CNV', '耶利米书', 24, 8, 17, '“看哪！我要打发毒蛇到你们中间，是没有法术能制伏的，它们必咬你们。”这是主的宣告。'),
('CNV', '耶利米书', 24, 8, 18, '我的愁苦无法医治（按照《马索拉文本》，本句意思难确定；现参照《七十士译本》翻译），我的心在我里面悲痛欲绝。'),
('CNV', '耶利米书', 24, 8, 19, '听啊！我同胞（“同胞”原文作“人民的女子”）的呼救声，从遥远之地传来：“主不在锡安吗？锡安的王不在其中吗？”“他们为什么以自己雕刻的偶像，和列国虚无的偶像，来惹我发怒呢？”'),
('CNV', '耶利米书', 24, 8, 20, '“收割期已过，夏天也结束；但我们仍未获救。”'),
('CNV', '耶利米书', 24, 8, 21, '因着我的同胞（“同胞”原文作“人民的女子”）被压碎，我的心破碎了；我悲伤痛哭，惊慌抓住了我。'),
('CNV', '耶利米书', 24, 8, 22, '难道基列没有乳香吗？难道那里没有医生吗？我的同胞（“同胞”原文作“人民的女子”）为什么总不痊愈呢？'),
('CNV', '耶利米书', 24, 9, 1, '但愿我的头是水井，我的眼是泪的泉源；我好为我同胞（“同胞”原文作“人民的女子”）中被杀的，昼夜哭泣。（本节在《马索拉文本》为8:23）'),
('CNV', '耶利米书', 24, 9, 2, '但愿我在旷野有一个旅客住宿的地方，好使我离开我的同胞，可以离他们而去；因为他们都是行奸淫的，是行诡诈之徒。（本节在《马索拉文本》为9:1）'),
('CNV', '耶利米书', 24, 9, 3, '“他们弯曲舌头，像弯弓一样；在这地得势的是虚谎，不是诚实；因为他们变本加厉地作恶，连我也不认识。”这是主的宣告。'),
('CNV', '耶利米书', 24, 9, 4, '“你们各人要提防自己的邻舍，不要信靠兄弟；因为每一个兄弟都在欺骗人，每一个邻舍都搬弄是非。'),
('CNV', '耶利米书', 24, 9, 5, '他们各人都欺骗自己的邻舍，不说诚实话。他们训练自己的舌头说谎话，竭力作孽，以致他们不能回转（按照《马索拉文本》，本句意思难确定；现参照《七十士译本》翻译）。'),
('CNV', '耶利米书', 24, 9, 6, '欺凌加上欺凌，诡诈加上诡诈（按照《马索拉文本》，“欺凌加上欺凌，诡诈加上诡诈”作“你的住所在诡诈中；在诡诈里”；现参照《七十士译本》翻译），他们不肯认识我。”这是主的宣告。'),
('CNV', '耶利米书', 24, 9, 7, '因此，万军之主这样说：“看哪！我要熬炼他们，试验他们；因我子民（“我子民”原文作“我子民的女子”）的罪恶，我还可以作什么呢？'),
('CNV', '耶利米书', 24, 9, 8, '他们的舌头是杀人的利箭，嘴里说的是诡诈；跟邻舍说话满口甜言蜜语，心底里却设计陷害他。'),
('CNV', '耶利米书', 24, 9, 9, '我因这些事怎能不惩罚他们呢？像这样的国家，我怎能不亲自报复呢？”这是主的宣告。'),
('CNV', '耶利米书', 24, 9, 10, '我要为众山哭泣哀号，为旷野的草场唱哀歌；因为都已成为荒凉，无人经过，也听不到牲畜的叫声；无论空中的飞鸟，地上的走兽，都逃走跑掉了。'),
('CNV', '耶利米书', 24, 9, 11, '“我要使耶路撒冷变成乱堆，成为野狗的巢穴；我要使犹大的城市荒凉，无人居住。”'),
('CNV', '耶利米书', 24, 9, 12, '谁是智慧人可以解明这事？主的口向谁说过，以致他可以传讲这事？为什么这地被毁坏，像旷野般荒凉，无人经过呢？'),
('CNV', '耶利米书', 24, 9, 13, '主说：“这是因为他们离弃了我摆在他们面前的律法，不听从我的话，没有遵行我的律法；'),
('CNV', '耶利米书', 24, 9, 14, '反而随从自己顽梗的心行事，照他们列祖所教训的，随从众巴力。”'),
('CNV', '耶利米书', 24, 9, 15, '因此，万军之主以色列的神这样说：“看哪！我要使这人民吃苦堇，喝毒水。'),
('CNV', '耶利米书', 24, 9, 16, '我要把他们分散在列国中，就是他们和他们的列祖都不认识的列国；我要使刀剑追杀他们，直到把他们灭绝。”'),
('CNV', '耶利米书', 24, 9, 17, '万军之主这样说：“你们要思想，要把唱哀歌的妇女召来，把那些擅长哀哭的妇女请来；'),
('CNV', '耶利米书', 24, 9, 18, '叫他们赶快为我们举哀，使我们的眼流下眼泪，使我们的眼皮涌出泪水。'),
('CNV', '耶利米书', 24, 9, 19, '因为从锡安可以听到哀声，说：‘我们何等衰败！我们多么羞耻！因我们丢弃了这地，我们的家园被拆毁了。’”'),
('CNV', '耶利米书', 24, 9, 20, '妇女们哪！你们要听主的话，你们的耳朵要领受他口中的话；要教导你们的女儿举哀，各人要彼此学习哀歌。'),
('CNV', '耶利米书', 24, 9, 21, '因为死亡从窗户上来，进入我们的堡垒；要从街上剪除孩童，从广场上剪除年轻人。'),
('CNV', '耶利米书', 24, 9, 22, '你要这样说（这是主的宣告）：“人的尸体横卧着，像田野上的粪肥，又像遗留在收割者后面的麦穗，无人拾取。”'),
('CNV', '耶利米书', 24, 9, 23, '主这样说：“智慧人不可夸耀自己的智慧，勇士不可夸耀自己的勇力，财主不可夸耀自己的财富。'),
('CNV', '耶利米书', 24, 9, 24, '夸口的却要因了解我，认识我而夸口；认识我是主，我在地上施行慈爱、公正、公义；因为我喜悦这些事。”这是主的宣告。'),
('CNV', '耶利米书', 24, 9, 25, '“看哪！日子快到（这是主的宣告），我必惩罚所有只在身体受过割礼，内心却未受割礼的人，'),
('CNV', '耶利米书', 24, 9, 26, '就是埃及、犹大、以东、亚扪、摩押和所有剃除鬓发，住在旷野的人；因为列国的人都没有受过割礼，甚至以色列全家的内心也没有受过割礼。”'),
('CNV', '耶利米书', 24, 10, 1, '以色列家啊！你们要听主对你们所说的话。'),
('CNV', '耶利米书', 24, 10, 2, '主这样说：“你们不要学习列国的行径，列国因天象惊惶，你们却不要因这些惊惶。'),
('CNV', '耶利米书', 24, 10, 3, '因为万民所信奉的都是虚空，只是从林中砍下的树木，是匠人用凿刀制成的产品。'),
('CNV', '耶利米书', 24, 10, 4, '他们用金银把它修饰，用钉子和锤子把它钉牢，使它不动摇。'),
('CNV', '耶利米书', 24, 10, 5, '它们像瓜田里的稻草人，不能说话；它们必须要人抬着走，因为它们不能走路。你们不要害怕它们，因它们不能降祸，也不能降福。”'),
('CNV', '耶利米书', 24, 10, 6, '主啊！没有可以跟你相比的；你是伟大的，你的名大有能力。'),
('CNV', '耶利米书', 24, 10, 7, '万国的王啊！谁敢不敬畏你呢？这是你应得的。因为在列国所有的智慧人中，以及在他们的全国里，没有可以跟你相比的。'),
('CNV', '耶利米书', 24, 10, 8, '他们全是顽梗愚昧，他们所领受的教导是来自那些虚无、木做的偶像。'),
('CNV', '耶利米书', 24, 10, 9, '那些偶像镶有经过锤炼的银片，银子是从他施运来的，也有从乌法运来的金子，都是匠人和金匠手作的产品。它们穿着蓝色和紫色的衣服，全都是巧匠的作品。'),
('CNV', '耶利米书', 24, 10, 10, '只有主是真神；他是永活的神，是永远的君王。他一发怒，大地就震动，万国都不能承受他的忿怒。'),
('CNV', '耶利米书', 24, 10, 11, '你们要对他们这样说：“那些没有创造天地的神，必从地上、从天下消灭。”'),
('CNV', '耶利米书', 24, 10, 12, '主用自己的能力创造了大地，用自己的智慧坚立了世界，又用自己的聪明展开了诸天。'),
('CNV', '耶利米书', 24, 10, 13, '他一发声，空中众水就澎湃；他使云雾从地极上腾；他造了闪电和雷雨，又使风从他的仓库里吹出来。'),
('CNV', '耶利米书', 24, 10, 14, '人人都是顽梗无知；所有的金匠都因偶像羞愧，因为他们铸造的像都是虚假、没有气息的。'),
('CNV', '耶利米书', 24, 10, 15, '偶像都是虚无的，是荒谬可笑的作品；到了讨罪的时候，它们必被除灭。'),
('CNV', '耶利米书', 24, 10, 16, '那作雅各产业的并不像这些偶像，因为他是万物的创造者；以色列是属他的民族，万军之主是他的名。'),
('CNV', '耶利米书', 24, 10, 17, '住在被围困的城中的人哪！你们从地上拾起自己的行囊。'),
('CNV', '耶利米书', 24, 10, 18, '因为主这样说：“看哪！在这时候，我要把这地的居民投掷出去；又使他们受困苦，以致他们被压倒。”'),
('CNV', '耶利米书', 24, 10, 19, '因我的损伤，我有祸了！我的创伤不能医治；但我说：“这是我的痛苦，我必须忍受。”'),
('CNV', '耶利米书', 24, 10, 20, '我的帐棚毁坏，我的绳索都折断了；我的儿女都离我而去，不在这里了；再没有人支搭我的帐棚，挂起我的幔子。'),
('CNV', '耶利米书', 24, 10, 21, '牧人都是顽梗的，他们不求问主；因此，他们不得亨通，他们所有的羊群都四散。'),
('CNV', '耶利米书', 24, 10, 22, '听哪！有风声传来，有大骚动从北方之地而来，要使犹大的城市荒凉，成为野狗的巢穴。'),
('CNV', '耶利米书', 24, 10, 23, '主啊！我知道人的道路是不由自己的；人行走时，也不能确定自己的脚步。'),
('CNV', '耶利米书', 24, 10, 24, '主啊！求你只按着公正惩治我，不要按着你的忿怒施行惩治，免得你使我衰微。'),
('CNV', '耶利米书', 24, 10, 25, '愿你把你的烈怒倾倒在不认识你的列国，和不求告你名的万族身上；因为他们吞吃了雅各，他们吞吃了他，把他消灭，使他的住处荒凉。'),
('CNV', '耶利米书', 24, 11, 1, '主有话临到耶利米，说：'),
('CNV', '耶利米书', 24, 11, 2, '“你要告诉犹大人和耶路撒冷的居民：‘你们要听从这约的话。’'),
('CNV', '耶利米书', 24, 11, 3, '你要对他们说：‘主以色列的神这样说：不听从这约的话的，必受咒诅。'),
('CNV', '耶利米书', 24, 11, 4, '这约就是我把你们的列祖从埃及地、从铁炉那里领出来的那天所吩咐他们的，说：你们要听从我的话，照着我吩咐你们的一切话去行；这样，你们就作我的子民，我也作你们的神。'),
('CNV', '耶利米书', 24, 11, 5, '我好履行向你们列祖所起的誓，就是把流奶与蜜之地赐给他们，好像今天一样。’”于是我回答说：“主啊！阿们。”'),
('CNV', '耶利米书', 24, 11, 6, '主又对我说：“你要在犹大各城中和耶路撒冷的街道上，宣告这一切话，说：‘你们要听从、遵行这约的话。'),
('CNV', '耶利米书', 24, 11, 7, '因为自从我领你们的列祖出埃及地那一天，我已郑重警告他们，直到今日，我仍不断警告他们，说：“你们要听从我的话。”'),
('CNV', '耶利米书', 24, 11, 8, '他们却不听从，毫不留心，各人随从自己顽梗的恶心行事。所以，我使这约中一切咒诅的话临到他们身上。我曾吩咐他们遵行这约，他们却不遵行。’”'),
('CNV', '耶利米书', 24, 11, 9, '主又对我说：“在犹大人和耶路撒冷的居民中间，有背叛的阴谋。'),
('CNV', '耶利米书', 24, 11, 10, '他们回到他们祖先所犯的罪孽中。他们的祖先不肯听从我的话，却随从事奉别的神。以色列家和犹大家都违犯了我和他们列祖所立的约。”'),
('CNV', '耶利米书', 24, 11, 11, '因此主这样说：“看哪！我必使灾祸临到他们身上，是他们不能逃脱的；他们虽然向我哀求，我必不听他们。'),
('CNV', '耶利米书', 24, 11, 12, '那时，犹大各城的人和耶路撒冷的居民，都必去哀求他们烧香供奉的神，只是在他们遭难的时候，这些神却完全不能拯救他们。'),
('CNV', '耶利米书', 24, 11, 13, '犹大啊！你的城有多少，你的神也有多少；耶路撒冷的街道有多少，你为那可耻的巴力所设立烧香的祭坛也有多少。'),
('CNV', '耶利米书', 24, 11, 14, '“至于你，不要为这人民祈祷，不要为他们呼求祷告，因为他们遭难向我呼求的时候，我必不听他们。'),
('CNV', '耶利米书', 24, 11, 15, '“我所爱的既然行了罪大恶极的事，还有什么资格在我的殿里呢？难道祭肉可以消除你的灾祸，使你得着欢乐吗？”'),
('CNV', '耶利米书', 24, 11, 16, '主曾称你的名字为壮丽、多结美果的青橄榄树；现在他必藉风暴雷轰，把它燃点起来，它的枝子也都折断。'),
('CNV', '耶利米书', 24, 11, 17, '那栽种你的万军之主，已经宣布降灾攻击你，是因以色列家和犹大家自己所行的恶；他们向巴力烧香，惹我发怒。'),
('CNV', '耶利米书', 24, 11, 18, '主把他们的阴谋指示我，我就知道了；那时，你把他们所行的给我指明。'),
('CNV', '耶利米书', 24, 11, 19, '至于我，我却像一只驯良的羊羔，被牵到屠宰之地；我并不知道他们设计谋害我。他们说：“我们来把这树和果子（“果子”原文作“它的食物”）都毁灭吧，把它从活人之地剪除，使它的名不再被人记念。”'),
('CNV', '耶利米书', 24, 11, 20, '但万军之主啊！你是凭公义审判人，试验人肺腑和心肠的。求你让我看见你在他们身上施行的报复，因为我已经把我的案件向你陈明了。'),
('CNV', '耶利米书', 24, 11, 21, '因此主指责那些亚拿突人，他们寻索你命，向你恐吓说：“不要奉主的名说预言，免得你死在我们手中。”'),
('CNV', '耶利米书', 24, 11, 22, '万军之主这样说：“看哪！我要惩罚他们；他们的年轻人必死在刀下，他们的儿女必因饥荒而死。'),
('CNV', '耶利米书', 24, 11, 23, '他们中间必没有余剩的，因为在惩罚他们的年日，我必使灾祸临到亚拿突人身上。”'),
('CNV', '耶利米书', 24, 12, 1, '主啊！我跟你争辩的时候，总是你有理；然而我还要跟你讨论有关公正的问题。恶人的道路为什么亨通？所有行诡诈的为什么都得享安逸？'),
('CNV', '耶利米书', 24, 12, 2, '你栽种了他们，他们也扎了根，并且长大，结出果实；他们的口中有你，心里却没有你（“他们的口中有你，心里却没有你”原文作“你与他们的口很接近，却离他们的心很远”）。'),
('CNV', '耶利米书', 24, 12, 3, '但主啊！你认识我，了解我，你察验了我对你的心意。求你把他们拉出来，好像将宰的羊一般；求你把他们分别出来，留待宰杀的日子。'),
('CNV', '耶利米书', 24, 12, 4, '这地悲哀，田野的青草都枯干，要等到几时呢？由于这地居民的恶行，走兽和飞鸟都灭绝了；因为他们说：“神看不见我们的结局。”'),
('CNV', '耶利米书', 24, 12, 5, '主说：“如果你与徒步的人同跑，尚且觉得疲倦，怎能跟马赛跑呢？你在平安稳妥之地，尚且跌倒，在约旦河边的丛林怎么办呢？'),
('CNV', '耶利米书', 24, 12, 6, '因为连你的兄弟、你的父家，都以诡诈待你，连他们也在你后面高声喊叫。虽然他们对你说好话，你也不可信他们。”'),
('CNV', '耶利米书', 24, 12, 7, '“我撇下了我的家，丢弃了我的产业；我把我心爱的交在她仇敌的手中。'),
('CNV', '耶利米书', 24, 12, 8, '我的产业对我，就像树林中的狮子向我咆哮，因此我恨恶她。'),
('CNV', '耶利米书', 24, 12, 9, '我的产业对我，不就像一只带斑点的鸷鸟，其他的鸷鸟都四围攻击她？你们去聚集田野各样的走兽，带它们来吃吧！'),
('CNV', '耶利米书', 24, 12, 10, '许多牧人毁坏了我的葡萄园，践踏了我的田地；他们使我美好的田地变为荒凉的旷野。'),
('CNV', '耶利米书', 24, 12, 11, '他们使地荒凉，在我面前一片荒凉悲哀；全地荒凉，却无人关心。”'),
('CNV', '耶利米书', 24, 12, 12, '在旷野一切光秃的高冈上，行毁灭的已经来到了；因为主的刀。从地这边直到地那边，要吞灭一切；人人都没有平安。'),
('CNV', '耶利米书', 24, 12, 13, '他们种的是小麦，收的却是荆棘；虽然筋疲力竭，却一无所获。因主的烈怒，他们必为自己的（“自己的”原文作“你们的”）出产羞愧（本句或译：“你们必为你们的农获羞愧”）。'),
('CNV', '耶利米书', 24, 12, 14, '主这样说：“至于所有邪恶的邻国，他们侵犯我赐给我子民以色列的产业；看哪！我要把他们从本地拔出来，也要把犹大家从他们中间拔出来。'),
('CNV', '耶利米书', 24, 12, 15, '但我把他们拔出来以后，我必再怜悯他们，把他们领回来，各自归回自己的产业，自己的故乡。'),
('CNV', '耶利米书', 24, 12, 16, '如果那些邻近的国家真的学习我子民的道路，指着我的名起誓，说：‘我指着永活的主起誓！’正如他们从前教导我的子民指着巴力起誓一样，他们就必在我的子民中间被建立起来。'),
('CNV', '耶利米书', 24, 12, 17, '他们如果有不听从的，我就把那国拔出来，把她拔除消灭。”这是主的宣告。'),
('CNV', '耶利米书', 24, 13, 1, '主这样对我说：“你去为自己买一根麻布腰带，束在腰上，但不要把它放在水中。”'),
('CNV', '耶利米书', 24, 13, 2, '我就照着主的话，买了一根腰带，束在腰上。'),
('CNV', '耶利米书', 24, 13, 3, '主的话第二次临到我，说：'),
('CNV', '耶利米书', 24, 13, 4, '“拿你买来束在腰上的腰带，起来，往幼发拉底河去，把腰带藏在那里的岩石缝中。”'),
('CNV', '耶利米书', 24, 13, 5, '我就照着主所吩咐我的，去把腰带藏在幼发拉底河那里。'),
('CNV', '耶利米书', 24, 13, 6, '过了多日，主对我说：“起来，往幼发拉底河去，把我吩咐你藏在那里的腰带取出来。”'),
('CNV', '耶利米书', 24, 13, 7, '于是我往幼发拉底河去，在那里挖掘，把腰带从我埋藏的地方取出来；看哪！腰带已经腐烂了，完全没用了。'),
('CNV', '耶利米书', 24, 13, 8, '那时，主的话临到我，说：'),
('CNV', '耶利米书', 24, 13, 9, '“主这样说：‘我必照样败坏犹大的尊荣和耶路撒冷极大的尊荣。'),
('CNV', '耶利米书', 24, 13, 10, '这邪恶的人民，不肯听从我的话，他们随着自己顽梗的心行事，随从别的神，事奉敬拜他们；所以他们必像这根腰带，毫无用处。'),
('CNV', '耶利米书', 24, 13, 11, '因为腰带怎样紧贴着人的腰，我也曾怎样使以色列全家和犹大全家紧贴着我，好使他们作我的子民，叫我得名声，得赞美，得荣耀；可是他们却不听从。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 13, 12, '“你要对他们说这话：‘主以色列的神这样说：每一个酒瓶都要盛满酒。’如果他们对你说：‘难道我们不清楚知道每一个酒瓶都要盛满酒吗？’'),
('CNV', '耶利米书', 24, 13, 13, '你就要对他们说：‘主这样说：看哪！我要使这地所有的居民，就是那些坐大卫王位的君王，以及祭司、先知和耶路撒冷所有的居民，都完全醉倒。'),
('CNV', '耶利米书', 24, 13, 14, '我要使他们彼此碰撞，连父子也要互相碰撞；我必不爱惜、不可怜，也不怜悯他们，我必把他们灭绝。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 13, 15, '你们要听，要留心听，不要骄傲；因为是主说的。'),
('CNV', '耶利米书', 24, 13, 16, '主你们的神还没有使黑暗临到以前，你们的脚还没有在昏暗的山上绊倒之前，你们要把荣耀归给他。你们期待光明，他却把光明变为死荫，使光明变成黝黑。'),
('CNV', '耶利米书', 24, 13, 17, '如果你们不听从，我必因你们的骄傲暗暗哭泣；我的眼必痛哭流泪，因为主的羊群被掳去了。'),
('CNV', '耶利米书', 24, 13, 18, '你要对君王和太后说：“你们应从宝座下来，因为华丽的冠冕已经从你们的头上脱下来了。”'),
('CNV', '耶利米书', 24, 13, 19, '南地的城市已被围困，没有人能解围；整个犹大都被掳走，全被掳去了。'),
('CNV', '耶利米书', 24, 13, 20, '耶路撒冷啊！你要举目观看那些从北方来的人。从前交给你的羊群，就是你引以为荣的群羊，现今在哪里呢？'),
('CNV', '耶利米书', 24, 13, 21, '主立你自己结交（“结交”原文作“教导”）的盟友为首领管辖你，那时，你还有什么话说呢？痛苦岂不把你抓住，好像妇女生产时的痛苦一样吗？'),
('CNV', '耶利米书', 24, 13, 22, '如果你心里问：“这些事为什么发生在我身上呢？”这是由于你极大的罪孽；你的袍子被掀起，你的下体（“下体”原文作“脚跟”）暴露出来。'),
('CNV', '耶利米书', 24, 13, 23, '古实人怎能改变他的肤色？花豹怎能改变它的斑点？你们这些惯作坏事的人，又怎能行善呢？'),
('CNV', '耶利米书', 24, 13, 24, '“因此，我要使你们（“你们”原文作“他们”）四散，像被旷野的风吹走的碎秸一样。'),
('CNV', '耶利米书', 24, 13, 25, '这是你应得的，是我量给你的分。”这是主的宣告。“因为你忘记了我，去倚靠虚假的偶像；'),
('CNV', '耶利米书', 24, 13, 26, '所以，我必把你的袍子掀到你的脸上，使人看见你的丑态。'),
('CNV', '耶利米书', 24, 13, 27, '你的奸淫，你淫荡的叫声，你邪淫的恶行，在山上，在田野间，你那些可憎的事我都看见了。耶路撒冷啊，你有祸了！你这样不洁净要到几时呢？”'),
('CNV', '耶利米书', 24, 14, 1, '主的话临到耶利米，是关于旱灾的事：'),
('CNV', '耶利米书', 24, 14, 2, '“犹大悲哀，她的城镇（“城镇”原文作“城门”）衰落，人人都坐在地上悲伤痛哭；耶路撒冷的哀声上达于天。'),
('CNV', '耶利米书', 24, 14, 3, '他们的显贵差派童仆去打水；童仆来到池边，却找不到水，就拿着空的器皿回来；他们失望难过，蒙着自己的头。'),
('CNV', '耶利米书', 24, 14, 4, '土地干裂，因为地上没有雨水；农夫失望，都蒙着自己的头。'),
('CNV', '耶利米书', 24, 14, 5, '甚至母鹿在田野生产了小鹿，也得把它丢弃，因为没有青草。'),
('CNV', '耶利米书', 24, 14, 6, '野驴站在光秃的高冈上，像野狗喘着气；它们双目发呆，因为没有青草。”'),
('CNV', '耶利米书', 24, 14, 7, '“主啊！即使我们的罪孽指证我们，还求你因你名的缘故施行拯救。我们实在多次背道，得罪了你。'),
('CNV', '耶利米书', 24, 14, 8, '以色列的盼望啊！以色列遭难时的拯救者啊！你为什么在本地像一个寄居的人，又像个只住宿一夜的旅客呢？'),
('CNV', '耶利米书', 24, 14, 9, '你为什么像个受惊的人，又像个不能拯救人的勇士呢？主啊！你是在我们中间，我们是称为你名下的人，求你不要离弃我们。”'),
('CNV', '耶利米书', 24, 14, 10, '主论到这人民这样说：“他们喜爱这样流荡，不约束自己的脚；因此主不悦纳他们，现在就要记念他们的罪孽，并要惩罚他们的罪恶。”'),
('CNV', '耶利米书', 24, 14, 11, '主对我说：“不要为这人民祈求好处；'),
('CNV', '耶利米书', 24, 14, 12, '即使他们禁食，我也不会听他们的呼求；即使他们献上燔祭和素祭，我也不会悦纳；我却要用刀剑、饥荒和瘟疫去灭尽他们。”'),
('CNV', '耶利米书', 24, 14, 13, '我就说：“唉，主神啊！你看，那些先知常对他们说：‘你们必不会看见刀剑，也必不会有饥荒；因为我主要在这地方赐给你们恒久的平安。’”'),
('CNV', '耶利米书', 24, 14, 14, '主对我说：“那些先知借我的名说假预言；我并没有差遣他们，没有吩咐他们，也没有向他们说话。他们对你们所预言的，是虚假的异象、占卜的预兆、虚无的事，和他们自己心里的诡诈。”'),
('CNV', '耶利米书', 24, 14, 15, '因此，主这样说：“关于那些借我名说预言的先知，我并没有差遣他们，他们竟说：‘这地必不会有刀剑和饥荒。’那些先知必被刀剑和饥荒灭绝。'),
('CNV', '耶利米书', 24, 14, 16, '至于那些听他们说预言的人民，必因刀剑和饥荒被抛弃在耶路撒冷的街上，没有人埋葬他们，也没有人埋葬他们的妻子和儿女。我必要把他们作恶应得的报应倒在他们身上。'),
('CNV', '耶利米书', 24, 14, 17, '“你要对他们说这话：‘愿我的眼泪直流，日夜不停；因为我的同胞（“同胞”原文作“人民的处女”）遭受极大的毁灭，受到很严重的打击。'),
('CNV', '耶利米书', 24, 14, 18, '如果我出到田间，就看见那些被刀剑所杀的人；如果我走进城里，就看见因饥荒而来的各种疾病。连先知和祭司也流亡到他们素不认识的地方。’”'),
('CNV', '耶利米书', 24, 14, 19, '你真的弃绝犹大吗？你真的讨厌锡安吗？你为什么击打我们，使我们无法医治呢？我们期待平安，却得不到好处；期待得医治的时候，不料，只有惊慌。'),
('CNV', '耶利米书', 24, 14, 20, '主啊！我们承认我们的罪恶，和我们列祖的罪孽；我们实在得罪了你。'),
('CNV', '耶利米书', 24, 14, 21, '求你为你名的缘故，不要厌弃我们！不要叫你荣耀的宝座蒙羞！求你记念你和我们所立的约，不要废除！'),
('CNV', '耶利米书', 24, 14, 22, '列国虚无的偶像中，有可以降雨的吗？天能自降甘霖吗？主我们的神啊！能够这样作的，不是只有你吗？所以我们仰望你，因为这一切都是你所作的。'),
('CNV', '耶利米书', 24, 15, 1, '主对我说：“即使摩西和撒母耳站在我面前代求，我的心也不会转向这人民。你把他们从我面前赶走，叫他们出去！'),
('CNV', '耶利米书', 24, 15, 2, '如果他们问你：‘我们要去哪里？’你就告诉他们：‘主这样说：该死亡的，就死亡；该被刀剑所杀的，就被刀剑所杀；该遭遇饥荒的，就遭遇饥荒；该被掳的，就被掳去！’'),
('CNV', '耶利米书', 24, 15, 3, '我要命定四种刑罚对付他们，就是刀剑杀戮，尸体被野狗拖走，被空中的飞鸟和地上的走兽吞吃与毁灭。”这是主的宣告。'),
('CNV', '耶利米书', 24, 15, 4, '“因犹大王希西家的儿子玛拿西在耶路撒冷的所作所为，我必使地上万国看见他们的遭遇就惊恐。”'),
('CNV', '耶利米书', 24, 15, 5, '“耶路撒冷啊！谁会可怜你呢？谁会为你悲伤呢？谁会转身向你问安呢？'),
('CNV', '耶利米书', 24, 15, 6, '你离弃了我，你转身背着我；因此我要伸手攻击你，毁灭你，我不会再回心转意。”这是主的宣告。'),
('CNV', '耶利米书', 24, 15, 7, '“我在这地的城门口，用簸箕簸了我的子民，使他们丧掉儿女，使他们灭亡；他们仍不转离自己所行的路。'),
('CNV', '耶利米书', 24, 15, 8, '我使他们寡妇的数目比海沙还多；我使行毁灭的在午间临到我的子民，打击年轻人的母亲，使痛苦的惊恐忽然临到她们身上。'),
('CNV', '耶利米书', 24, 15, 9, '那生过七个子女的母亲衰竭疲弱，几乎气绝；还在白昼，她的太阳已经西落，她必惭愧蒙羞。我必使他们余剩的人在敌人面前死于刀下。”这是主的宣告。'),
('CNV', '耶利米书', 24, 15, 10, '我母亲哪！我有祸了，因为你生了我，这个跟全地相争相斗的人。我从没有借钱给人，也没有向人借钱，可是人人都咒骂我。'),
('CNV', '耶利米书', 24, 15, 11, '主说：“我必为你的好处释放你；在遭遇祸患和灾难的时候，我必叫你的仇敌恳求你。'),
('CNV', '耶利米书', 24, 15, 12, '谁可以折断铁，就是从北方来的铁和铜呢？'),
('CNV', '耶利米书', 24, 15, 13, '因你在四境之内所犯的一切罪，我必把你的财产和宝物，白白给敌人作掠物。'),
('CNV', '耶利米书', 24, 15, 14, '我必使你在你不认识的地方，服事你的仇敌（有古抄本作“我必使你的仇敌过去，到你所不认识的地方”）；因为我的怒火燃烧起来，要烧灭你们。”'),
('CNV', '耶利米书', 24, 15, 15, '主啊！你知道这一切；求你记念我，看顾我，替我向那些逼迫我的人报复。求你忍怒，不要取去我的性命；要知道，我为你的缘故受了侮辱。'),
('CNV', '耶利米书', 24, 15, 16, '我一得到你的话，就把它们吃了；你的话成了我心中的欢喜快乐；主万军的神啊！因为我是称为你名下的人。'),
('CNV', '耶利米书', 24, 15, 17, '我没有坐在欢笑者的集会中一同欢乐；因为你的手在我身上，你使我满了忿怒，我就独自静坐。'),
('CNV', '耶利米书', 24, 15, 18, '我的痛苦为什么长久不止呢？我的创伤为什么无法医治，不得痊愈呢？你对我真的像叫人失望、靠不住的溪流吗？'),
('CNV', '耶利米书', 24, 15, 19, '因此，主这样说：“如果你回转，我必让你回来，你就可以侍立在我面前。如果你说宝贵的话，不说无价值的话，就必作我的口。他们要归向你，你却不要归向他们。'),
('CNV', '耶利米书', 24, 15, 20, '我要使你成为坚固的铜墙抵挡这人民，他们必攻击你，却不能胜过你；因为我与你同在，要拯救你，搭救你。”这是主的宣告。'),
('CNV', '耶利米书', 24, 15, 21, '“我必搭救你脱离恶人的手，救赎你脱离强暴人的掌握（“掌握”原文作“手掌”）。”'),
('CNV', '耶利米书', 24, 16, 1, '主的话临到我，说：'),
('CNV', '耶利米书', 24, 16, 2, '“在这地方你不可娶妻，不可生儿育女。”'),
('CNV', '耶利米书', 24, 16, 3, '因为论到这地方出生的儿女，和在这地生养他们的父母，主这样说：'),
('CNV', '耶利米书', 24, 16, 4, '“他们都必死于致命的疫症，没有人为他们哀哭，他们的尸体也没有人埋葬，必在地面上成为粪肥。他们必被刀剑和饥荒所灭，他们的尸体成了空中飞鸟和地上走兽的食物。”'),
('CNV', '耶利米书', 24, 16, 5, '主这样说：“你不可进入丧家，也不可去为他们哀哭悲伤；因为我已经从这人民身上收回我的平安、慈爱和怜悯。”这是主的宣告。'),
('CNV', '耶利米书', 24, 16, 6, '“尊大的和卑微的都必死在这地；没有人埋葬他们，没有人为他们哀哭，也没有人为他们割伤自己，剃光头发。'),
('CNV', '耶利米书', 24, 16, 7, '没有人为哀悼的人擘饼，为死者安慰他们；丧父或丧母的人，都没有人给他们喝一杯安慰酒。'),
('CNV', '耶利米书', 24, 16, 8, '你也不可进入欢宴之家，跟他们同坐，一起吃喝。'),
('CNV', '耶利米书', 24, 16, 9, '因为万军之主以色列的神这样说：‘看哪！我必在你们眼前，在你们还活着的日子，使欢笑和快乐的声音，新郎和新娘的声音，都从这地方止息了。’”'),
('CNV', '耶利米书', 24, 16, 10, '“你向这人民传讲这一切时，如果他们问你：‘主为什么宣告这一切严重的灾祸对付我们呢？我们有什么罪孽？我们犯了什么罪，得罪了主我们的神呢？’'),
('CNV', '耶利米书', 24, 16, 11, '你就要回答他们：‘因为你们的列祖离弃了我（这是主的宣告），他们随从别的神，事奉敬拜他们；他们离弃了我，不遵守我的律法。'),
('CNV', '耶利米书', 24, 16, 12, '至于你们，你们作坏事比你们的列祖更厉害；看哪！你们各人都随从自己顽梗的恶心行事，不听从我。'),
('CNV', '耶利米书', 24, 16, 13, '因此，我要把你们从这地赶出去，去到你们和你们列祖所不认识的地；你们在那里必昼夜事奉别的神，因为我不再向你们施恩。’'),
('CNV', '耶利米书', 24, 16, 14, '“看哪！日子快到，人必不再指着那领以色列人从埃及地上来的永活的主起誓。”这是主的宣告。'),
('CNV', '耶利米书', 24, 16, 15, '“他们却要指着那领以色列人从北方之地，从他们被赶逐到的各国上来的永活的主起誓。因我要领他们回到自己的土地，就是我从前赐给他们列祖的。'),
('CNV', '耶利米书', 24, 16, 16, '“看哪！我要差人去叫许多渔夫来，捕捉以色列人；然后我要差人去叫许多猎人来，从各大山、小山和岩石的裂缝里，猎取他们。”这是主的宣告。'),
('CNV', '耶利米书', 24, 16, 17, '“因为我的眼察看他们所行的一切；在我面前这一切都无法隐藏，他们的罪孽不能从我眼前遮掩起来。'),
('CNV', '耶利米书', 24, 16, 18, '首先我要加倍报应他们的罪孽和罪恶，因为他们用自己那些毫无生气、可憎的偶像（“毫无生气，可憎的偶像”原文作“可憎的偶像的尸体”）玷污了我的土地，他们那些可厌之物充满了我的产业。”'),
('CNV', '耶利米书', 24, 16, 19, '主，我的力量、我的堡垒、我遭难时的避难所啊！万国要从地极前来朝见你，说：“我们列祖所承受的只是虚假的偶像，是虚空、一无用处的。'),
('CNV', '耶利米书', 24, 16, 20, '人岂能为自己制造神呢？其实这些偶像并不是神。”'),
('CNV', '耶利米书', 24, 16, 21, '“因此，看哪！我要使他们知道，这一次我必叫他们认识我的手和我的能力，他们就知道我的名是主。”'),
('CNV', '耶利米书', 24, 17, 1, '“犹大的罪是用铁笔铭记的，是用金钢钻刻在他们的心版上，和他们（“他们”有古抄本作“你们”）祭坛的角上。'),
('CNV', '耶利米书', 24, 17, 2, '他们的儿女也怀念着那些在各高冈上、在繁茂树旁的祭坛和亚舍拉。'),
('CNV', '耶利米书', 24, 17, 3, '我在田野的山哪！因你在四境之内所犯的罪，我必把你的财产、一切宝物和你的邱坛，给敌人作掠物。（本节或译：“因你在四境之内所犯的罪，我必把我在田野的山、你的财产、一切宝物和你的邱坛，给敌人作掠物”）'),
('CNV', '耶利米书', 24, 17, 4, '因你自己的缘故，我赐给你的产业，你必失掉；我必使你在你不认识的地方，服事你的仇敌；因为你们惹起我的怒火，我的怒火必燃烧到永远。”'),
('CNV', '耶利米书', 24, 17, 5, '主这样说：“倚靠世人，恃凭肉体为自己的力量，心里偏离主的，这人该受咒诅。'),
('CNV', '耶利米书', 24, 17, 6, '他必像沙漠中的灌木，福乐来到，他也必看不见，却要住在旷野干旱之地、无人居住的咸地。'),
('CNV', '耶利米书', 24, 17, 7, '但倚靠主，以主为他所信赖的，这人是有福的。'),
('CNV', '耶利米书', 24, 17, 8, '他必像一棵树，栽种在水边，树根伸进河里；炎热来到，并不害怕，树叶仍然繁茂；在荒旱之年，它不挂虑，并且不断结果子。”'),
('CNV', '耶利米书', 24, 17, 9, '人心比万物都诡诈，无法医治；谁能识透呢？'),
('CNV', '耶利米书', 24, 17, 10, '“我主是察透人心，试验人肺腑的，要照着各人的行为，和各人所作的事应得的结果报应各人。”'),
('CNV', '耶利米书', 24, 17, 11, '使用不公正的方法发财的，就像一只鹧鸪孵了不是自己所生的蛋；到了中年，那财富必离开他，最后他必成为一个愚昧人。'),
('CNV', '耶利米书', 24, 17, 12, '我们的圣所是荣耀的宝座，从起初就矗立在高处。'),
('CNV', '耶利米书', 24, 17, 13, '主以色列的盼望啊！离弃你的，都必蒙羞；偏离你（“你”原文作“我”）的，他们的名字必写在沙土上，因为他们离弃了主这活水的源头。'),
('CNV', '耶利米书', 24, 17, 14, '主啊！求你医治我，我就得医治；求你拯救我，我就得拯救；因为你是我所赞美的。'),
('CNV', '耶利米书', 24, 17, 15, '看哪！他们常常对我说：“主的话在哪里？使它应验（“应验”原文作“来”）吧！”'),
('CNV', '耶利米书', 24, 17, 16, '至于我，我没有急忙离弃那跟从你作牧人的职分（“我没有急忙离弃那跟从你作牧人的职分”有古译本作“我没有催逼你降灾祸”），也没有想望灾难的日子，这是你知道的；我嘴里所出的话都在你面前。'),
('CNV', '耶利米书', 24, 17, 17, '求你不要使我因你惊恐，在灾祸的日子，你是我的避难所。'),
('CNV', '耶利米书', 24, 17, 18, '愿那些迫害我的蒙羞，却不要叫我蒙羞；愿他们惊恐，却不要使我惊恐；求你使灾祸的日子临到他们，加倍毁灭他们。'),
('CNV', '耶利米书', 24, 17, 19, '主对我这样说：“你去站在犹大列王出入的城门（“城门”原文作“人民城门”），又站在耶路撒冷的各城门口，'),
('CNV', '耶利米书', 24, 17, 20, '对他们说：‘耶路撒冷诸王、犹大众民和所有进入这些城门的犹大居民哪！你们要听他主的话。'),
('CNV', '耶利米书', 24, 17, 21, '主这样说：为了自己的性命，你们要谨慎，不可在安息日挑担子，不可挑进耶路撒冷的城门。'),
('CNV', '耶利米书', 24, 17, 22, '也不可在安息日从你们家里挑担子出来；什么工都不可作，却要守安息日为圣日，正如我吩咐你们列祖的。'),
('CNV', '耶利米书', 24, 17, 23, '你们的列祖却没有听从，毫不在意，反而硬着颈项不肯听，不受管教。’”'),
('CNV', '耶利米书', 24, 17, 24, '主宣告说：“但如果你们真心听从我，不在安息日挑担子进入这城的城门，并且守安息日为圣日，在那日不作任何工作；'),
('CNV', '耶利米书', 24, 17, 25, '这样，就必有坐大卫王位的列王，并有众领袖随着，进入这城的城门；列王和众领袖乘着车，骑着马，跟犹大人和耶路撒冷的居民一同进入这城。这城必永远有人居住。'),
('CNV', '耶利米书', 24, 17, 26, '必有人从犹大的各城和耶路撒冷周围的各处，从便雅悯地、低地、山地和南地而来；他们带着燔祭、平安祭、素祭、乳香和感恩祭到主的殿里去。'),
('CNV', '耶利米书', 24, 17, 27, '但如果你们不听从我，不守安息日为圣日，仍在安息日挑担子，进入耶路撒冷的城门；这样，我就必在耶路撒冷的各城门点起火来，烧毁耶路撒冷的堡垒，没有人能够扑灭。”'),
('CNV', '耶利米书', 24, 18, 1, '主有话临到耶利米，说：'),
('CNV', '耶利米书', 24, 18, 2, '“起来，下到陶匠的家里去，在那里我要使你听到我的话。”'),
('CNV', '耶利米书', 24, 18, 3, '我就下到陶匠的家里去，见他正在转盘旁工作。'),
('CNV', '耶利米书', 24, 18, 4, '陶匠用他手中的泥所做的器皿坏了，他就用这泥再做别的器皿，照着自己的意思去作。'),
('CNV', '耶利米书', 24, 18, 5, '于是主的话临到我，说：'),
('CNV', '耶利米书', 24, 18, 6, '“以色列家啊！难道我不能待你们像这陶匠所作的一样吗？”这是主的宣告。“看哪！泥在陶匠的手中怎样，以色列家啊！你们在我的手中也必怎样。'),
('CNV', '耶利米书', 24, 18, 7, '我什么时候宣布要拔出、拆毁、毁灭一邦或一国，'),
('CNV', '耶利米书', 24, 18, 8, '如果我论到的那一邦转离他们的恶行，我就必回心转意，不把我原定的灾祸降给他们。'),
('CNV', '耶利米书', 24, 18, 9, '同样，我什么时候宣布要建立、栽植一邦或一国，'),
('CNV', '耶利米书', 24, 18, 10, '如果他们行我眼中看为恶的事，不听从我的话，我就必回心转意，不把我应许的好处赐给他们。'),
('CNV', '耶利米书', 24, 18, 11, '“现在你要对犹大人和耶路撒冷的居民说：‘主这样说：看哪！我正在制造灾祸对付你们，拟定计划惩罚你们。你们各人要回转，离开自己的恶道，改正你们的行径和作为。’'),
('CNV', '耶利米书', 24, 18, 12, '他们却说：‘没用的！我们要随着自己的计划而行，各人要按着自己顽梗的恶心行事。’”'),
('CNV', '耶利米书', 24, 18, 13, '因此主这样说：“你们问一问列国，有谁听见过像这样的事呢？童女以色列竟行了一件非常骇人的事。'),
('CNV', '耶利米书', 24, 18, 14, '黎巴嫩山上岩石的积雪融化过吗？从远处流下清凉的溪水干涸过吗？'),
('CNV', '耶利米书', 24, 18, 15, '但我的子民竟忘记我，向虚无的偶像烧香，以致他们在自己的路上、在古道上绊倒，行走小路，不是修建过的大道。'),
('CNV', '耶利米书', 24, 18, 16, '他们的土地变为荒凉，成为永远被人嗤笑的对象；经过这地的，都必惊骇摇头。'),
('CNV', '耶利米书', 24, 18, 17, '在他们的敌人面前，我要像东风吹散他们；在他们遭难的日子，我必使他们只见我的背，不见我的面。”'),
('CNV', '耶利米书', 24, 18, 18, '他们说：“来吧！我们来设计对付耶利米；因为祭司的律法、智慧人的谋略、先知的话都不会断绝。来吧！我们用舌头攻击他，不理会他的一切话。”'),
('CNV', '耶利米书', 24, 18, 19, '主啊！求你倾听我的申诉，听那些指控我的人的声音。'),
('CNV', '耶利米书', 24, 18, 20, '良善的应得恶报吗？他们竟然挖陷坑害我。求你记念我怎样站在你面前，为他们说好话，使你的烈怒离开他们。'),
('CNV', '耶利米书', 24, 18, 21, '因此，愿你使他们的儿女遭受饥荒，把他们交给刀剑（“刀剑”原文作“刀剑的手”）；愿他们的妻子丧夫失子；愿他们的男人被杀死，他们的壮丁在战场上被刀剑击杀。'),
('CNV', '耶利米书', 24, 18, 22, '你使侵略者忽然临到他们的时候，愿人从他们的屋里听见呼救声；因为他们挖陷坑要捉拿我，埋藏网罗要绊我的脚。'),
('CNV', '耶利米书', 24, 18, 23, '主啊！至于你，你知道他们要杀我的一切计谋。求你不要赦免他们的罪孽，不要从你面前涂抹他们的罪！使他们在你面前绊倒；求你在发怒的时候，对付他们。'),
('CNV', '耶利米书', 24, 19, 1, '主这样说：“你去跟陶匠买一个瓦瓶，要带着几位人民的长老和年长的祭司，'),
('CNV', '耶利米书', 24, 19, 2, '出到欣嫩子谷，哈珥西（“哈珥西”意即“瓦片”）门的入口，在那里你要宣告我将对你说的话。'),
('CNV', '耶利米书', 24, 19, 3, '你要说：‘犹大列王和耶路撒冷的居民哪！你们要听主的话。万军之主以色列的神这样说：看哪！我必使灾祸临到这地方；凡听见的，都必耳鸣。'),
('CNV', '耶利米书', 24, 19, 4, '因为他们离弃了我，把这地方玷污了，在这地方向列神烧香。这些神是他们和他们的列祖，以及犹大列王所不认识的；他们又使这地方洒满无辜人的血。'),
('CNV', '耶利米书', 24, 19, 5, '他们筑了巴力的邱坛，好用火焚烧自己的儿女，作燔祭献给巴力。这不是我吩咐的，我没有提说过，也没有在我心里想过。'),
('CNV', '耶利米书', 24, 19, 6, '因此，看哪！日子快到，这地方必不再称为陀斐特或欣嫩子谷，而要称为杀戮谷。’这是主的宣告。'),
('CNV', '耶利米书', 24, 19, 7, '‘我要在这地方使犹大和耶路撒冷的计谋失败，也必使他们在仇敌面前倒毙于刀下，死在寻索他们性命的人手中。我要把他们的尸体给空中的飞鸟和地上的野兽作食物。'),
('CNV', '耶利米书', 24, 19, 8, '我要使这城变为荒凉，成为被人嗤笑的对象；每一个经过这里的，都必因这城所遭受的一切创伤而惊骇，并且嗤笑她。'),
('CNV', '耶利米书', 24, 19, 9, '在他们被围困和受压迫之中，就是在仇敌和寻索他们性命的人压迫他们的时候，我必使他们吞吃自己的儿女的肉，各人也彼此吃对方的肉。’'),
('CNV', '耶利米书', 24, 19, 10, '“然后你要在跟你同去的人眼前，把那瓶子打碎，'),
('CNV', '耶利米书', 24, 19, 11, '并对他们说：‘万军之主这样说：我必照样打碎这人民和这城，好像人打碎陶匠的瓦器一样，不能再修补。人必在陀斐特埋葬尸体，甚至无处可埋葬。'),
('CNV', '耶利米书', 24, 19, 12, '我必照样对待这地方和这地方的居民，使这城像陀斐特一样。’这是主的宣告。'),
('CNV', '耶利米书', 24, 19, 13, '‘耶路撒冷的房屋和犹大列王的宫殿，都要像陀斐特一样成为不洁；人曾在这一切房屋宫殿的屋顶上，向天上的万象烧香，向别神浇奠祭。’”'),
('CNV', '耶利米书', 24, 19, 14, '耶利米从陀斐特，就是从主差遣他去说预言的地方回来，他站在主殿的院中，对众民说：'),
('CNV', '耶利米书', 24, 19, 15, '“万军之主以色列的神这样说：‘看哪！我必使我宣告攻击这城的一切灾祸，临到这城和她附近的一切城镇，因为他们硬着颈项，不听从我的话。’”'),
('CNV', '耶利米书', 24, 20, 1, '音麦的儿子巴施户珥祭司，就是主殿的总管，他听见了耶利米预言这些事，'),
('CNV', '耶利米书', 24, 20, 2, '就殴打耶利米先知，把他枷锁在主殿里，朝向便雅悯的上门内。'),
('CNV', '耶利米书', 24, 20, 3, '次日，巴施户珥把耶利米从枷锁上解下来，耶利米就对他说：“主不再称你的名为巴施户珥，却要称你为玛歌珥．米撒毕（“玛歌珥．米撒毕”意即“四围惊慌”）。'),
('CNV', '耶利米书', 24, 20, 4, '因为主这样说：‘看哪！我要使你自己和你所有的朋友都惊惶失措；他们必倒在他们仇敌的刀下，你也必亲眼看见。我要把全犹大交在巴比伦王手中；他要把他们掳到巴比伦去，或用刀击杀他们。'),
('CNV', '耶利米书', 24, 20, 5, '我要把这城的一切财物、一切劳碌得来的、一切珍宝和犹大列王的一切宝物，都交在他们仇敌的手中；仇敌要把这一切抢劫掠夺，带回巴比伦去。'),
('CNV', '耶利米书', 24, 20, 6, '巴施户珥啊！你和所有住在你家里的人，都要被掳去；你和你所有的朋友，就是你向他们说假预言的，都要到巴比伦去，死在那里，也葬在那里。’”'),
('CNV', '耶利米书', 24, 20, 7, '主啊！你愚弄了我，我受了愚弄；你比我强大，你胜了我。我整天成了别人讥笑的对象，人人都嘲弄我。'),
('CNV', '耶利米书', 24, 20, 8, '因为我每次发言，都大声呼叫；我呼喊，说：“有强暴和毁灭！”主的话使我整天受人辱骂和讥讽。'),
('CNV', '耶利米书', 24, 20, 9, '如果我说：“我不再提起他，也不再奉他的名说话”，他的话就像火在我心中焚烧，被困在我的骨里；我不能再抑制，实在不能了。'),
('CNV', '耶利米书', 24, 20, 10, '我听见许多人耳语：“玛歌珥．米撒毕！告发他，我们要告发他！”我所有的知己朋友都等着看我行差踏错，他们说：“希望他会上当，我们就可以胜过他，向他报复。”'),
('CNV', '耶利米书', 24, 20, 11, '但主与我同在，像一个威武可畏的勇士，因此，逼迫我的都必跌倒，不能得胜。他们必大大蒙羞，因为他们失败了；这永远的耻辱是人不能忘记的。'),
('CNV', '耶利米书', 24, 20, 12, '万军之主啊！你试验义人，察看人的心肠肺腑；求你让我看见你在他们身上施行的报复，因为我已经把我的案件向你陈明了。'),
('CNV', '耶利米书', 24, 20, 13, '你们要歌颂主，赞美主；因为他救了穷乏人的性命，脱离恶人的手。'),
('CNV', '耶利米书', 24, 20, 14, '愿我生的那一天受咒诅！愿我母亲生我的那一天不蒙祝福！'),
('CNV', '耶利米书', 24, 20, 15, '那向我父亲报喜信：“你得了一个男孩”，叫我父亲十分高兴的，愿那人受咒诅！'),
('CNV', '耶利米书', 24, 20, 16, '愿那人像主所倾覆而不顾惜的城市，愿他早晨听见哀号，午间听见战争的吶喊。'),
('CNV', '耶利米书', 24, 20, 17, '因为他没有使我死于母腹，好使我的母亲成了我的坟墓，我永远留在母腹中。'),
('CNV', '耶利米书', 24, 20, 18, '我为什么要出母胎，经历劳苦和忧伤，并且我的年日都消逝在羞辱之中呢？'),
('CNV', '耶利米书', 24, 21, 1, '主有话临到耶利米。那时，西底家王差遣玛基雅的儿子巴施户珥，和玛西雅的儿子西番雅祭司去见耶利米，说：'),
('CNV', '耶利米书', 24, 21, 2, '“请你替我们求问主，因为巴比伦王尼布甲尼撒来攻击我们；也许主会为我们行奇事，使尼布甲尼撒离开我们回去。”'),
('CNV', '耶利米书', 24, 21, 3, '耶利米就对他们说：“你们要对西底家这样说：'),
('CNV', '耶利米书', 24, 21, 4, '‘主以色列的神这样说：看哪！我必使你们手中的武器，就是你们用来与城外围困你们的巴比伦王和迦勒底人作战的武器，转回堆积在这城的中心。'),
('CNV', '耶利米书', 24, 21, 5, '我必在怒气、烈怒和忿怒中，用伸出来的手和强有力的膀臂，亲自攻击你们。'),
('CNV', '耶利米书', 24, 21, 6, '我要击打住在这城的人和牲畜，他们都要因极大的瘟疫而死。'),
('CNV', '耶利米书', 24, 21, 7, '然后，我必把犹大王西底家和他的臣民，就是在这城里经过瘟疫、刀剑之灾和饥荒而幸存的人，都交在巴比伦王尼布甲尼撒和他们的仇敌，以及寻索他们性命的人的手中。尼布甲尼撒要用刀剑击杀他们，绝不顾惜，不留情，不怜悯。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 21, 8, '主又吩咐耶利米：“你要对这人民说：‘主这样说：看哪！我把生命的路和死亡的路摆在你们面前。'),
('CNV', '耶利米书', 24, 21, 9, '凡留在这城里的，必因刀剑、饥荒、瘟疫而死；但出去向围困你们的迦勒底人投降的，必可以活着，捡回自己的性命。'),
('CNV', '耶利米书', 24, 21, 10, '因为我已经决意向这城降祸不降福；这城必交在巴比伦王的手中，他必放火把城烧毁。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 21, 11, '“你要对犹大王室说：‘你们要听主的话。'),
('CNV', '耶利米书', 24, 21, 12, '大卫家啊！主这样说：你们每早晨应秉公审判，解救被抢夺的脱离欺压者的手；免得我的烈怒因你们（“你们”有古抄本作“他们”）的恶行发作，如火焚烧，无人能熄灭。'),
('CNV', '耶利米书', 24, 21, 13, '看哪！在山谷上、在岩石平原上的耶路撒冷啊！我要攻击你。’这是主的宣告。‘你们说：谁能下来攻击我们，谁能进入我们的住处呢？'),
('CNV', '耶利米书', 24, 21, 14, '我必照着你们所作的事应得的结果惩罚你们；我要在耶路撒冷的树林中放火，吞灭她四围的一切。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 22, 1, '主这样说：“你下到犹大王的宫中，在那里宣讲这些话，'),
('CNV', '耶利米书', 24, 22, 2, '说：‘坐大卫王位的犹大王啊！你和你的臣仆，以及从这些门进来的人民，都要听主的话。'),
('CNV', '耶利米书', 24, 22, 3, '主这样说：你们要施行公正和公义，解救被抢夺的脱离欺压者的手，不可虐待或以强暴对待寄居的、孤儿和寡妇，也不可在这地方流无辜人的血。'),
('CNV', '耶利米书', 24, 22, 4, '如果你们切实地行这些事，就必有坐大卫王位的列王，乘着车，骑着马，与自己的臣仆和人民进入这王宫的各门。'),
('CNV', '耶利米书', 24, 22, 5, '如果你们不听从这些话，我指着自己起誓，这宫殿必变为废墟。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 22, 6, '因为主论到犹大王的宫殿这样说：“虽然在我看来，你好像基列，好像黎巴嫩的山峰；我却要使你变为旷野，变为无人居住的城市。'),
('CNV', '耶利米书', 24, 22, 7, '我要指派毁灭者，各有兵器攻击你；他们必砍下你最好的香柏树，丢进火里。'),
('CNV', '耶利米书', 24, 22, 8, '多国的人必经过这城，彼此发问：‘主为什么这样对待这大城呢？’'),
('CNV', '耶利米书', 24, 22, 9, '必有人说：‘是因为他们离弃了主他们神的约，并且敬拜事奉别神。’”'),
('CNV', '耶利米书', 24, 22, 10, '不要为那已死的人哀哭，不要为他悲伤；却要为那远去的人大大哀哭，因为他不得再回来，也不能再见自己的国土。'),
('CNV', '耶利米书', 24, 22, 11, '因为论到犹大王约西亚的儿子，就是继承他父亲约西亚作王的沙龙，主这样说：“他离开了这地方，必不得再回来；'),
('CNV', '耶利米书', 24, 22, 12, '因为他要死在被掳去的地方，不得再见这地。'),
('CNV', '耶利米书', 24, 22, 13, '“用不义的手段建造自己房屋、用不公正的方法建筑自己楼房的，有祸了！他使自己的同胞白白作工，不把工资付给他们。'),
('CNV', '耶利米书', 24, 22, 14, '他说：‘我要为自己建造宏伟的房屋、宽敞的楼房。’他又为房屋装设宽阔的窗户，用香柏木作镶板，并且漆上红色。'),
('CNV', '耶利米书', 24, 22, 15, '难道你是用香柏木争胜来表明王的身分吗？你父亲不是也吃也喝，也施行公正和公义吗？那时他得享福乐。'),
('CNV', '耶利米书', 24, 22, 16, '他为困苦和贫穷人伸冤，那时他得享福乐。这不是认识我的真义吗？”这是主的宣告。'),
('CNV', '耶利米书', 24, 22, 17, '“但你的眼你的心什么都不顾，只顾你的不义之财，只知流无辜人的血，施行欺压和迫害的事。”'),
('CNV', '耶利米书', 24, 22, 18, '因此，论到犹大王约西亚的儿子约雅敬，主这样说：“人必不为他哀伤，说：‘哀哉，我哥哥！’‘哀哉，我姊姊！’人必不为他哀伤，说：‘哀哉，主上！’‘哀哉，尊荣的王！’'),
('CNV', '耶利米书', 24, 22, 19, '他像驴子一样被埋葬，被拖走，抛在耶路撒冷城门外。”'),
('CNV', '耶利米书', 24, 22, 20, '“耶路撒冷啊，上黎巴嫩哀叫吧！在巴珊扬声吧！从亚巴琳哀叫吧！因为你的盟友都毁灭了。'),
('CNV', '耶利米书', 24, 22, 21, '你安定的时候，我曾警告过你，你却说：‘我不听！’从你幼年以来，你就是这样，不听从我的话。'),
('CNV', '耶利米书', 24, 22, 22, '风要卷走你所有的牧人，你的盟友要被掳去；那时，因你的一切恶行，你必蒙羞受辱。'),
('CNV', '耶利米书', 24, 22, 23, '住在黎巴嫩，在香柏林中搭窝的啊！有痛苦临到你，像产妇剧痛的时候，你要怎样呻吟呢？”'),
('CNV', '耶利米书', 24, 22, 24, '“我指着我的永生起誓（这是主的宣告），犹大王约雅敬的儿子哥尼雅，虽然你是我右手上的印戒，我也要把你从手上脱下来，'),
('CNV', '耶利米书', 24, 22, 25, '交在那些寻索你性命和你们惧怕的人手中，就是交在巴比伦王尼布甲尼撒和迦勒底人手中。'),
('CNV', '耶利米书', 24, 22, 26, '我要把你和生你的母亲驱赶到异地去，你们不是生在那里，却要死在那里。'),
('CNV', '耶利米书', 24, 22, 27, '你们（“你们”原文作“他们”）渴望归回本国，却不得回去。”'),
('CNV', '耶利米书', 24, 22, 28, '哥尼雅这个人是被鄙视、被摔碎的瓶子，是没有人喜悦的器皿吗？他和他的后裔为什么被驱赶，被抛弃到他们不认识的地去呢？'),
('CNV', '耶利米书', 24, 22, 29, '大地啊！大地啊！大地啊！要听主的话。'),
('CNV', '耶利米书', 24, 22, 30, '主这样说：“你们要写下，这人算为无子，他的一生毫无成就；因为他的后裔中没有一人可以成功，能坐在大卫的王位上，再次统治犹大。”'),
('CNV', '耶利米书', 24, 23, 1, '“那些残杀和赶散我牧场上的羊群的牧人，有祸了！”这是主的宣告。'),
('CNV', '耶利米书', 24, 23, 2, '因此，主以色列的神论到牧养他（“他”原文作“我”）子民的牧人这样说：“你们使我的羊群四散，把它们赶走，并没有看顾它们；看哪！我必因你们的恶行惩罚你们。”这是主的宣告。'),
('CNV', '耶利米书', 24, 23, 3, '“我要亲自把我羊群中余剩的，从我把它们赶逐到的各地，招聚出来，领它们归回自己的羊圈，使它们繁殖增多。'),
('CNV', '耶利米书', 24, 23, 4, '我要兴起牧人，牧养它们；它们必不再恐惧惊慌，一个也不会失掉。”这是主的宣告。'),
('CNV', '耶利米书', 24, 23, 5, '“看哪！日子快到（这是主的宣告），我必给大卫兴起一个公义的苗裔；他必执政为王，行事有智慧，在地上施行公正和公义。'),
('CNV', '耶利米书', 24, 23, 6, '在他执政的日子，犹大必得救，以色列也必安然居住。人要称他的名字为‘主我们的义’。”'),
('CNV', '耶利米书', 24, 23, 7, '“因此，看哪！日子快到（这是主的宣告），人不再指着那领以色列人从埃及地上来的永活的主起誓，'),
('CNV', '耶利米书', 24, 23, 8, '却要指着那领以色列家的后裔从北方之地、从他（“他”原文作“我”）把他们赶逐到的各地上来的、永活的主起誓。他们就必住在自己的地方。”'),
('CNV', '耶利米书', 24, 23, 9, '论到那些先知，我的心在我里面破碎，我全身的骨头都发抖。因为主的缘故，又因为他的圣言的缘故，我就像一个醉酒的人，像一个被酒灌醉的人。'),
('CNV', '耶利米书', 24, 23, 10, '因为这地满了行淫的人；因受咒诅，地就悲哀，旷野的草场都枯干了；他们走的路是邪恶的，他们的权力误用了。'),
('CNV', '耶利米书', 24, 23, 11, '“先知和祭司都不敬虔，甚至在我殿里我也看见他们的邪恶。”这是主的宣告。'),
('CNV', '耶利米书', 24, 23, 12, '“因此，他们的路必像滑地；他们必被赶逐到黑暗中，必在那里仆倒。因为到了惩罚他们的年日，我必使灾祸临到他们。”这是主的宣告。'),
('CNV', '耶利米书', 24, 23, 13, '“在撒玛利亚的先知中，我看见可厌的事：他们竟奉巴力的名说预言，使我的子民以色列走错了路。'),
('CNV', '耶利米书', 24, 23, 14, '在耶路撒冷的先知中，我看见可怕的事。他们犯奸淫，行事虚假，坚固恶人的手，以致没有人离弃恶行；在我看来，他们都像所多玛人，耶路撒冷的居民也像蛾摩拉人一样。”'),
('CNV', '耶利米书', 24, 23, 15, '因此，论到这些先知，万军之主这样说：“看哪！我必使他们吃苦堇，喝毒水，因为有不敬虔的风气，从耶路撒冷的先知中散播出来，遍及全地。”'),
('CNV', '耶利米书', 24, 23, 16, '万军之主这样说：“不要听从这些向你们说预言的先知所说的话，他们使你们存有虚幻的希望；他们所讲的异象是出于自己的心思，不是出于主的口。'),
('CNV', '耶利米书', 24, 23, 17, '他们不断对那些藐视我的人说：‘主说：你们必平安无事！’又对所有随从自己顽梗的心行事的人说：‘灾祸必不临到你们！’”'),
('CNV', '耶利米书', 24, 23, 18, '可是他们中间有谁曾参与主的议会，看见或听见他的话呢？有谁曾留心听他的话而实在听见呢？'),
('CNV', '耶利米书', 24, 23, 19, '看哪！主的旋风，在震怒中发出，是旋转的狂风，必卷到恶人的头上。'),
('CNV', '耶利米书', 24, 23, 20, '主的怒气必不转消，直到他作成和实现他心中的计划。在末后的日子，你们就会完全明白这事。'),
('CNV', '耶利米书', 24, 23, 21, '“我没有差派这些先知，但他们自己到处跑；我没有对他们说话，他们竟擅自说预言。'),
('CNV', '耶利米书', 24, 23, 22, '如果他们曾参与我的议会，就必向我的子民宣告我的信息，使他们转离他们的恶道，离开他们的恶行。'),
('CNV', '耶利米书', 24, 23, 23, '难道我只是近处的神吗？不也是远处的神吗？”这是主的宣告。'),
('CNV', '耶利米书', 24, 23, 24, '“人怎能躲藏在隐密处，以致我看不见他呢？（这是主的宣告）。我岂不是充满天地吗？”这是主的宣告。'),
('CNV', '耶利米书', 24, 23, 25, '“那些先知所说的话我都听见了，他们冒我的名说虚假的预言：‘我作了梦！我作了梦！’'),
('CNV', '耶利米书', 24, 23, 26, '那些先知心里存着这样的意念要到几时呢？他们说虚假的预言，说出自己心中的诡诈；'),
('CNV', '耶利米书', 24, 23, 27, '他们以为藉着互相传述自己的梦，就可以使我的子民忘记我的名，好像他们的列祖因巴力忘记了我的名一样。'),
('CNV', '耶利米书', 24, 23, 28, '作了梦的先知，让他把梦述说出来；但得了我话语的先知，该忠实地传讲我的话。禾秆怎能和麦子相比呢？”这是主的宣告。'),
('CNV', '耶利米书', 24, 23, 29, '“我的话不是像火，不是像能打碎岩石的大锤吗？”这是主的宣告。'),
('CNV', '耶利米书', 24, 23, 30, '“所以，看哪！那些先知互相偷取对方的话，当作我的话，我要对付他们。”这是主的宣告。'),
('CNV', '耶利米书', 24, 23, 31, '“看哪！那些先知用自己的舌头说：‘这是主的宣告’，我要对付他们。”这是主的宣告。'),
('CNV', '耶利米书', 24, 23, 32, '“看哪！那些藉虚假的梦说预言的，我要对付他们。”这是主的宣告。“他们述说这些梦，以虚谎和夸张的话使我的子民走错了路。我没有差派他们，也没有吩咐他们；他们对这人民毫无益处。”这是主的宣告。'),
('CNV', '耶利米书', 24, 23, 33, '“如果这人民、或先知、或祭司问你说：‘主有什么默示呢？’你要回答他们：‘你们就是重担（按照《马索拉文本》，“你们就是重担”应作“什么默示？”；现参照《七十士译本》翻译。“重担”和“默示”原文是同一个字），我要丢弃你们。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 23, 34, '“无论是先知、是祭司，或是人民，凡说‘这是主的默示’的，我都要惩罚那人和他的家。”'),
('CNV', '耶利米书', 24, 23, 35, '你们各人对自己的邻舍，对自己的兄弟要这样说：“主回答了什么？主说了什么？”'),
('CNV', '耶利米书', 24, 23, 36, '你们不可再提主的默示，你们各人所说的话将成为自己的重担；因为你们曲解永活的神万军之主我们神的话了。'),
('CNV', '耶利米书', 24, 23, 37, '你们要对神的先知（“你们要对神的先知”或译：“耶利米啊，你要对那些先知”）说：“主回答了你什么？主说了什么呢？”'),
('CNV', '耶利米书', 24, 23, 38, '如果你们仍说：“这是主的默示”，主就必这样说：“你们既然说‘这是主的默示’这句话，而我又曾差派人去告诉你们不可再说‘这是主的默示’；'),
('CNV', '耶利米书', 24, 23, 39, '因此，看哪！我必把你们当作重担举起来（“我必把你们当作重担举起来”或译：“我必定忘记你们”），把你们连同我赐给你们和你们列祖的城都从我面前丢弃。'),
('CNV', '耶利米书', 24, 23, 40, '我必使你们蒙受永远的凌辱、永远的羞耻，是不能忘记的。”'),
('CNV', '耶利米书', 24, 24, 1, '巴比伦王尼布甲尼撒把犹大王约雅敬的儿子耶哥尼雅，和犹大的众领袖、工匠与铁匠从耶路撒冷掳到巴比伦去。这事以后，主使我看见在主的殿前面摆着两筐无花果。'),
('CNV', '耶利米书', 24, 24, 2, '一筐是极好的无花果，像初熟的无花果；另一筐是极坏的无花果，坏到不能吃。'),
('CNV', '耶利米书', 24, 24, 3, '于是主问我：“耶利米啊，你看见什么？”我回答：“我看见无花果。那些好的无花果极好，坏的却极坏，坏到不能吃。”'),
('CNV', '耶利米书', 24, 24, 4, '主的话临到我，说：'),
('CNV', '耶利米书', 24, 24, 5, '“主以色列的神这样说：‘被掳去的犹大人，就是我打发离开这地方到迦勒底人之地去的，我必看他们如同这些好的无花果一样，眷顾他们。'),
('CNV', '耶利米书', 24, 24, 6, '我必关注他们，眷顾他们，领他们归回这地。我必建立他们，必不拆毁；我必栽植他们，必不拔除。'),
('CNV', '耶利米书', 24, 24, 7, '我必赐给他们一颗认识我的心，知道我就是主；他们要作我的子民，我要亲自作他们的神，因为他们必一心归向我。’”'),
('CNV', '耶利米书', 24, 24, 8, '“但主这样说：‘我怎样处置那些坏到不能吃的坏无花果，我也必照样对待犹大王西底家、他的众领袖和耶路撒冷的余民，不论是余剩在这地的，或是住在埃及地的。'),
('CNV', '耶利米书', 24, 24, 9, '我必使他们成为地上万国所惊恐、所讨厌的；在我赶逐他们到的各地方，成为被人羞辱、讥笑、嘲弄、咒诅的对象。'),
('CNV', '耶利米书', 24, 24, 10, '我必打发刀剑、饥荒、瘟疫去攻击他们，直到他们从我赐给他们和他们列祖的土地上都消灭了。’”'),
('CNV', '耶利米书', 24, 25, 1, '犹大王约西亚的儿子约雅敬第四年，就是巴比伦王尼布甲尼撒第一年，有话临到耶利米，是关于犹大众民的。'),
('CNV', '耶利米书', 24, 25, 2, '耶利米先知就把这话告诉犹大众民和耶路撒冷所有的居民，说：'),
('CNV', '耶利米书', 24, 25, 3, '“从犹大王亚们的儿子约西亚第十三年直到今日，这二十三年来，常有主的话临到我，我也不断对你们传讲，你们却不听从。'),
('CNV', '耶利米书', 24, 25, 4, '主虽然不断差遣他的仆人众先知到你们那里去；但你们却没有听从，毫不留心。'),
('CNV', '耶利米书', 24, 25, 5, '他们对你们说：‘你们各人要悔改，离开自己的恶道和邪恶的行为，就可以住在主赐给你们和你们列祖的土地上，直到永永远远。’”'),
('CNV', '耶利米书', 24, 25, 6, '“你们不要随从别的神，不要事奉敬拜他们，也不可容你们手所作的惹我发怒；这样，我就不会使祸患临到你们。'),
('CNV', '耶利米书', 24, 25, 7, '但你们没有听从我，竟容你们手所作的惹我发怒，自招祸害。”这是主的宣告。'),
('CNV', '耶利米书', 24, 25, 8, '因此，万军之主这样说：“因为你们没有听从我的话，'),
('CNV', '耶利米书', 24, 25, 9, '看哪！我要打发人去征召北方的众族，和我的仆人巴比伦王尼布甲尼撒，领他们来攻击这地和这地的居民，以及周围的列国；我要把他们彻底消灭，使他们成为令人惊骇，受人嗤笑的对象，和永远荒废的地方。”这是主的宣告。'),
('CNV', '耶利米书', 24, 25, 10, '“我要从他们中间除掉欢喜和快乐的声音，新郎和新妇的声音，推磨的声音和灯的亮光。'),
('CNV', '耶利米书', 24, 25, 11, '这地要全变为荒废，令人惊骇；这些国家要服事巴比伦王七十年。'),
('CNV', '耶利米书', 24, 25, 12, '“七十年满了以后，我要按着他们的罪孽惩罚巴比伦王和那国，就是迦勒底人之地，使它永远荒凉。”这是主的宣告。'),
('CNV', '耶利米书', 24, 25, 13, '“我必使我所说攻击那地的一切话应验在那地；我所说的，就是一切记录在这书上的，是耶利米攻击列国所说的预言。'),
('CNV', '耶利米书', 24, 25, 14, '因为许多国家和大君王将要奴役迦勒底人，我必按着他们的作为和他们手所作的报应他们。”'),
('CNV', '耶利米书', 24, 25, 15, '主以色列的神对我这样说：“你从我的手中拿这杯烈怒的酒，给列国喝，就是我差遣你去的列国。'),
('CNV', '耶利米书', 24, 25, 16, '他们喝了，就会东倒西歪，疯狂乱性，因为我打发刀剑到他们中间去。”'),
('CNV', '耶利米书', 24, 25, 17, '于是我从主的手中接过这杯，给列国喝，就是主差遣我去的列国，'),
('CNV', '耶利米书', 24, 25, 18, '包括耶路撒冷、犹大的城镇，和她的君王、领袖，使这些城镇荒废，成为令人惊骇、被人嗤笑、咒骂的对象，好像今天一样。'),
('CNV', '耶利米书', 24, 25, 19, '又包括法老，就是埃及王，和他的臣仆、王侯，以及全体人民，'),
('CNV', '耶利米书', 24, 25, 20, '并所有外族的人；还有乌斯地的众王、非利士人之地的众王，就是亚实基伦、迦萨，以革伦和亚实突余剩的人的王；'),
('CNV', '耶利米书', 24, 25, 21, '并有以东、摩押、亚扪、'),
('CNV', '耶利米书', 24, 25, 22, '推罗的列王、西顿的列王、海外岛屿的列王、'),
('CNV', '耶利米书', 24, 25, 23, '底但、提玛、布斯，所有剃除鬓发的部落、'),
('CNV', '耶利米书', 24, 25, 24, '阿拉伯的列王、住在沙漠的外族人的列王、'),
('CNV', '耶利米书', 24, 25, 25, '心利的列王、以拦的列王、玛代的列王、'),
('CNV', '耶利米书', 24, 25, 26, '北方远近的列王，一个一个，以及地上的万国，就是在这地面上的列国，都喝了；他们喝了以后，示沙克王也要喝。'),
('CNV', '耶利米书', 24, 25, 27, '“你要对他们说：‘万军之主以色列的神这样说：你们要喝，并要喝醉，呕吐，以致跌倒，不能再起来，因为我打发刀剑到你们中间去。’'),
('CNV', '耶利米书', 24, 25, 28, '如果他们不肯从你的手中接过这杯来喝，你就要对他们说：‘万军之主这样说：你们一定要喝。'),
('CNV', '耶利米书', 24, 25, 29, '因为，看哪！我既然在那称为我名下的城中先降灾祸，你们真可免受惩罚吗？你们必不能免受惩罚，因为我要呼唤刀剑来攻击这地所有的居民。’”这是万军之主的宣告。'),
('CNV', '耶利米书', 24, 25, 30, '“因此你要对他们宣讲这一切话，对他们说：‘主必从高天吼叫，从他的圣所发声；他必大声吼叫攻击自己的羊圈；他要对地上所有的居民呼喊，像那些踹葡萄的人呼喊一样。'),
('CNV', '耶利米书', 24, 25, 31, '吶喊的声音要传到地极，因为主要控告列国，也要审判万人；至于恶人，他必把他们交给刀剑。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 25, 32, '万军之主这样说：“看哪！必有灾祸发出，从这国直到那国；必有大风暴从地极刮起。”'),
('CNV', '耶利米书', 24, 25, 33, '到那日，从地的这边到地的那边，都必有被主刺死的人；必没有人为他们悲哀，没有人收殓他们、埋葬他们；他们都必在地面上成为粪肥。'),
('CNV', '耶利米书', 24, 25, 34, '牧人啊，你们要哀号，呼叫！羊群的领袖啊，你们要在灰尘中打滚！因为你们被宰杀的日子已经到了；我要粉碎你们，你们要跌倒，像珍贵的器皿跌碎一样。'),
('CNV', '耶利米书', 24, 25, 35, '牧人无处逃避，羊群的领袖无法逃脱。'),
('CNV', '耶利米书', 24, 25, 36, '听啊！牧人的哀叫，羊群的领袖的悲号，因为主正在毁坏他们的牧场。'),
('CNV', '耶利米书', 24, 25, 37, '因为主猛烈的怒气，平静的羊圈毁坏了。'),
('CNV', '耶利米书', 24, 25, 38, '他像狮子离开了洞穴，他们的国土实在变成荒野，因为欺压人的刀剑（“刀剑”有古抄本作“猛烈”），和他猛烈的怒气临到他们。'),
('CNV', '耶利米书', 24, 26, 1, '犹大王约西亚的儿子约雅敬开始执政的时候，有这话从主那里临到耶利米，说：'),
('CNV', '耶利米书', 24, 26, 2, '“主这样说：‘你要站在主殿的院子里，对来自犹大各城，到主殿敬拜的人，把我吩咐你对他们说的一切话，一字不漏告诉他们。'),
('CNV', '耶利米书', 24, 26, 3, '或者他们肯听从，各人转离自己的恶道，我就回心转意，不把我因为他们的恶行原想要施行的灾祸，降给他们。'),
('CNV', '耶利米书', 24, 26, 4, '你要对他们说：主这样说：如果你们不听从我，不遵行我设立在你们面前的律法，'),
('CNV', '耶利米书', 24, 26, 5, '不听从我差遣到你们那里去的我的仆人众先知的话（我不断差遣他们，但你们一直都不听从），'),
('CNV', '耶利米书', 24, 26, 6, '我就必使这殿像示罗一样，使这城成为地上列国咒诅的对象。’”'),
('CNV', '耶利米书', 24, 26, 7, '耶利米在主殿里所说的这些话，众祭司、众先知和众民都听见了。'),
('CNV', '耶利米书', 24, 26, 8, '耶利米说完了主吩咐他对众民所说的一切话，众祭司、众先知和众民就抓住他，说：“你必要死！'),
('CNV', '耶利米书', 24, 26, 9, '你为什么奉主的名预言，说：‘这殿必像示罗一样，这城必变为荒场，没有人居住呢？’”于是众民在主的殿里集合到耶利米那里。'),
('CNV', '耶利米书', 24, 26, 10, '犹大的领袖听见了这些事，就从王宫上到主的殿，坐在主殿里新门的入口。'),
('CNV', '耶利米书', 24, 26, 11, '祭司和先知对领袖和众民说：“这人应该处死，因为他说预言攻击这城，正如你们亲耳听见的。”'),
('CNV', '耶利米书', 24, 26, 12, '耶利米对众领袖和众民说：“主差遣我预言你们所听见，一切攻击这殿和这城的话。'),
('CNV', '耶利米书', 24, 26, 13, '现在，你们要改善你们所行所作的，听从主你们的神的话，主就必回心转意，不把所说的灾祸降给你们。'),
('CNV', '耶利米书', 24, 26, 14, '至于我，我在你们手中；你们看怎样好，怎样对，就怎样待我吧！'),
('CNV', '耶利米书', 24, 26, 15, '不过你们要确实知道，如果你们杀死我，就必使无辜的人的血归到你们和这城，以及这城的居民头上，因为主实在差遣了我到你们中间，把这一切话传到你们耳中。”'),
('CNV', '耶利米书', 24, 26, 16, '于是众领袖和众民对祭司和先知说：“这人不应该处死，因为他奉主我们神的名对我们说话。”'),
('CNV', '耶利米书', 24, 26, 17, '那地的长老中有几个人起来，对集合在场的全体人民说：'),
('CNV', '耶利米书', 24, 26, 18, '“在犹大王希西家的日子，摩利沙人弥迦对犹大的众民说预言：‘万军之主这样说：锡安要像田地被耕犁，耶路撒冷必成为废墟，这殿的山必变为杂树丛生的高冈。’'),
('CNV', '耶利米书', 24, 26, 19, '犹大王希西家和犹大众人可曾把他处死呢？希西家不是敬畏主，求他开恩，以致主回心转意，没有把他所说的灾祸降在他们身上吗？但我们现在竟自招大祸。”'),
('CNV', '耶利米书', 24, 26, 20, '曾有一个人，就是基列．耶琳人示玛雅的儿子乌利亚，他奉主的名说预言，攻击这城和这地，他的预言和耶利米所说的一样。'),
('CNV', '耶利米书', 24, 26, 21, '约雅敬王和他所有的勇士，以及犹大的众领袖听见了乌利亚的话，王就想要杀他。乌利亚听见了，就惧怕，就逃往埃及去。'),
('CNV', '耶利米书', 24, 26, 22, '约雅敬王打发人到埃及去，就是派亚革波的儿子以利拿单和一些人同到埃及去。'),
('CNV', '耶利米书', 24, 26, 23, '他们就把乌利亚从埃及带出来，送到约雅敬王那里。王用刀杀死他，把他的尸体抛在平民的坟地里。'),
('CNV', '耶利米书', 24, 26, 24, '然而沙番的儿子亚希甘却保护耶利米，不许人把耶利米交在人民的手中处死。'),
('CNV', '耶利米书', 24, 27, 1, '犹大王约西亚的儿子西底家（“西底家”有古抄本作“约雅敬”）开始执政的时候，有这话从主那里临到耶利米，说：'),
('CNV', '耶利米书', 24, 27, 2, '“主对我这样说：‘你要用绳套和木头做轭，套在自己的颈上。'),
('CNV', '耶利米书', 24, 27, 3, '然后藉着那些前来耶路撒冷朝见犹大王西底家的使臣的手，把轭送到以东王、摩押王、亚扪王、推罗王、西顿王那里。'),
('CNV', '耶利米书', 24, 27, 4, '你要吩咐使臣对他们的王说：万军之主以色列的神这样说：你们要这样对你们的王说：'),
('CNV', '耶利米书', 24, 27, 5, '是我用大能和伸出来的膀臂创造了大地，以及地面上的人和兽；我看给谁适合，就把地给谁。'),
('CNV', '耶利米书', 24, 27, 6, '现在我已经亲自把这一切国家都交在我仆人巴比伦王尼布甲尼撒的手中，连田野的走兽，我也交给他，供他奴役。'),
('CNV', '耶利米书', 24, 27, 7, '列国都要服事他和他的儿子、孙子，直到他本国遭报的时候来到；那时，许多国家和大君王都要奴役他。'),
('CNV', '耶利米书', 24, 27, 8, '“‘无论哪一国、哪一邦，不服事巴比伦王尼布甲尼撒，不把颈项放在巴比伦王的轭下，我必用刀剑、饥荒和瘟疫去惩罚那国，直到我藉着巴比伦王的手把他们完全消灭。’这是主的宣告。'),
('CNV', '耶利米书', 24, 27, 9, '‘至于你们，不可听从你们的先知，也不可听从占卜的、解梦的、算命的和行邪术的；他们告诉你们说：你们必不会服事巴比伦王。'),
('CNV', '耶利米书', 24, 27, 10, '因为他们向你们说虚假的预言，使你们远离你们的土地；我要赶逐你们，你们必要灭亡。')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '耶利米书', 24, 27, 11, '但哪一国肯把颈项放在巴比伦王的轭下，服事他，我就必使那国仍留在本土，可以在那里耕种和居住。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 27, 12, '我照着这一切话对犹大王西底家说：“你们要把颈项放在巴比伦王的轭下，服事他和他的人民，就可以生存。'),
('CNV', '耶利米书', 24, 27, 13, '你和你的人民为什么要因刀剑、饥荒和瘟疫而死，正如主论到不肯服事巴比伦王的国家所说的一样呢？'),
('CNV', '耶利米书', 24, 27, 14, '不要听从那些对你们说‘你们必不会服事巴比伦王’的先知的话，因为他们向你们说的是虚假的预言。'),
('CNV', '耶利米书', 24, 27, 15, '我并没有差遣他们（这是主的宣告），他们却冒我的名说虚假的预言，以致我赶逐你们，使你们和那些向你们说虚假预言的先知都一同灭亡。”'),
('CNV', '耶利米书', 24, 27, 16, '我又对众祭司和这众民说：“主这样说：‘你们的先知对你们预言，说：主殿中的器皿快要从巴比伦送回来了。他们的话，你们不要听从，因为他们对你们说的是虚假的预言。'),
('CNV', '耶利米书', 24, 27, 17, '你们不要听从他们，只要服事巴比伦王，就可以生存。为什么要使这城变为废墟呢？'),
('CNV', '耶利米书', 24, 27, 18, '如果他们是真先知，如果他们有主的话，就让他们向万军之主祈求，使那些留在主殿中和犹大王宫中，以及在耶路撒冷中的器皿，不会被送到巴比伦去。’'),
('CNV', '耶利米书', 24, 27, 19, '因为万军之主这样说，论到这些柱子、铜海、盆座和留在这城其余的器皿，'),
('CNV', '耶利米书', 24, 27, 20, '就是巴比伦王尼布甲尼撒把犹大王约雅敬的儿子耶哥尼雅，以及犹大和耶路撒冷所有的贵族，从耶路撒冷掳到巴比伦去的时候，没有拿走的器皿；'),
('CNV', '耶利米书', 24, 27, 21, '论到那些留在主殿中和犹大王宫中，以及在耶路撒冷中的器皿，万军之主以色列的神这样说：'),
('CNV', '耶利米书', 24, 27, 22, '‘这些器皿必被送到巴比伦，存在那里，直到我眷顾这些器皿的日子。那时，我必把它们带上来，放回这地方。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 28, 1, '当年，就是犹大王西底家开始执政的第四年五月，基遍人押朔的儿子哈拿尼雅先知，在主殿中，当着祭司和众民的面前对我说：'),
('CNV', '耶利米书', 24, 28, 2, '“万军之主以色列的神这样说：‘我已经折断了巴比伦王的轭。'),
('CNV', '耶利米书', 24, 28, 3, '在两年之内，我必把主殿中的一切器皿，就是巴比伦王尼布甲尼撒从这地方掠到巴比伦去的，都带回这地方。'),
('CNV', '耶利米书', 24, 28, 4, '我也必把犹大王约雅敬的儿子耶哥尼雅，和所有被掳到巴比伦去的犹大人，都带回这地方，因为我必折断巴比伦王的轭。’这是主的宣告。”'),
('CNV', '耶利米书', 24, 28, 5, '耶利米先知当着祭司和站在主殿里的众民面前，对哈拿尼雅先知说：'),
('CNV', '耶利米书', 24, 28, 6, '“阿们！愿主这样行，愿主使你预言的话应验，把主殿中的器皿和所有被掳的人，都从巴比伦带回这地方来。'),
('CNV', '耶利米书', 24, 28, 7, '不过，你应该听我向你和众民耳中所说的这话。'),
('CNV', '耶利米书', 24, 28, 8, '自古以来，在你我以前的先知，已经预言有战争、灾祸和瘟疫要临到许多地方和强国。'),
('CNV', '耶利米书', 24, 28, 9, '但预言平安的先知，除非他的话应验，人才会承认他确实是主所差遣的先知。”'),
('CNV', '耶利米书', 24, 28, 10, '于是哈拿尼雅先知把耶利米先知颈项上的轭取下来，折断了。'),
('CNV', '耶利米书', 24, 28, 11, '哈拿尼雅又当着众民面前说：“主这样说：‘两年之内，我必这样从列国的颈项上，折断巴比伦王尼布甲尼撒的轭。’”于是耶利米先知就走了。'),
('CNV', '耶利米书', 24, 28, 12, '哈拿尼雅先知把耶利米先知颈项上的轭折断了以后，主的话就临到耶利米，说：'),
('CNV', '耶利米书', 24, 28, 13, '“你去告诉哈拿尼雅说：‘主这样说：你折断了木轭，却要换来铁轭。'),
('CNV', '耶利米书', 24, 28, 14, '因为万军之主以色列的神这样说：我要把铁轭套在这些国家的颈项上，使他们服事巴比伦王尼布甲尼撒；他们要服事他，连田野的走兽，我也交给他了。’”'),
('CNV', '耶利米书', 24, 28, 15, '耶利米先知就对哈拿尼雅先知说：“哈拿尼雅啊！你要听，主并没有差遣你，你竟使这人民信靠谎言。'),
('CNV', '耶利米书', 24, 28, 16, '因此主这样说：‘看哪！我必使你离开人世；你今年一定死，因为你说了悖逆主的话。’”'),
('CNV', '耶利米书', 24, 28, 17, '这样，在当年七月，哈拿尼雅先知就死了。'),
('CNV', '耶利米书', 24, 29, 1, '以下这一封信，是耶利米先知从耶路撒冷寄给被掳的祭司、先知和众民，以及尚存的长老，就是尼布甲尼撒从耶路撒冷掳到巴比伦去的。'),
('CNV', '耶利米书', 24, 29, 2, '这是在耶哥尼雅王、太后、宫中的臣宰、犹大和耶路撒冷的领袖、工匠和铁匠从耶路撒冷被掳走以后。'),
('CNV', '耶利米书', 24, 29, 3, '这封信是由沙番的儿子以利亚萨和希勒家的儿子基玛利带去的；他们是犹大王西底家差往巴比伦，去见巴比伦王尼布甲尼撒的。信上说：'),
('CNV', '耶利米书', 24, 29, 4, '“万军之主以色列的神对所有被掳的，就是主（“主”原文作“我”）把他们从耶路撒冷掳到巴比伦去的人，这样说：'),
('CNV', '耶利米书', 24, 29, 5, '‘你们要建造房屋，定居下来；要栽种园子，吃园中的果子。'),
('CNV', '耶利米书', 24, 29, 6, '你们要娶妻，生养儿女；要为你们的儿子娶媳妇，把你们的女儿出嫁，好让他们也生养儿女。你们要在那里增多，不可减少。'),
('CNV', '耶利米书', 24, 29, 7, '我把你们掳到的那城，你们要为她求平安，为她向主祈祷；因为她得平安，你们也得平安。’'),
('CNV', '耶利米书', 24, 29, 8, '“万军之主以色列的神这样说：‘不要被你们中间的先知和作占卜的欺骗，也不要听信自己所作的梦（“自己所作的梦”原文作“你们的梦，就是你们所促使作的梦”，有古抄本作“他们所作的梦”）。'),
('CNV', '耶利米书', 24, 29, 9, '因为他们冒我名对你们说虚假的预言，我并没有差派他们。’这是主的宣告。'),
('CNV', '耶利米书', 24, 29, 10, '“主这样说：‘为巴比伦所定的七十年满了以后，我必眷顾你们，向你们实行我满有恩惠的诺言，把你们带回这地方来。'),
('CNV', '耶利米书', 24, 29, 11, '因我自己知道我为你们所定的计划，是使你们得平安，而不是遭受灾祸的计划；要赐给你们美好的前程和盼望。’这是主的宣告。'),
('CNV', '耶利米书', 24, 29, 12, '‘你们要呼求我，要来向我祷告，我就必应允你们。'),
('CNV', '耶利米书', 24, 29, 13, '你们要寻找我，只要一心寻求，就必寻见。'),
('CNV', '耶利米书', 24, 29, 14, '我必给你们寻见（这是主的宣告）；我必使你们被掳的归回，从我赶逐你们去的各国各地，把你们集合起来，带回我掳你们离开的地方去。’这是主的宣告。'),
('CNV', '耶利米书', 24, 29, 15, '“你们既然说：‘主在巴比伦为我们兴起了先知’，'),
('CNV', '耶利米书', 24, 29, 16, '所以主论到那坐大卫王位的君王和住在这城里的众民，就是没有和你们一同被掳去的众兄弟，这样说：'),
('CNV', '耶利米书', 24, 29, 17, '‘万军之主这样说：看哪！我必打发刀剑、饥荒、瘟疫临到他们；我必使他们像腐烂的无花果，坏到不能吃。'),
('CNV', '耶利米书', 24, 29, 18, '我必用刀剑、饥荒、瘟疫追赶他们，使他们成为地上万国所惊惧的，在我赶逐他们到的各国中，成为令人惊骇、被人咒骂、嗤笑、羞辱的对象。'),
('CNV', '耶利米书', 24, 29, 19, '因为他们不听从我的话（这是主的宣告），就是我不断差遣到他们那里去，我的仆人众先知所说的话；同样，你们也没有听从。’这是主的宣告。'),
('CNV', '耶利米书', 24, 29, 20, '“你们这所有被掳去的，就是我从耶路撒冷赶逐到巴比伦去的，要听主的话。'),
('CNV', '耶利米书', 24, 29, 21, '“万军之主以色列的神这样说：‘论到冒我的名向你们说虚假预言的哥赖雅的儿子亚哈和玛西雅的儿子西底家，我要把他们交在巴比伦王尼布甲尼撒的手中，他要在你们眼前击杀他们。'),
('CNV', '耶利米书', 24, 29, 22, '所有被掳到巴比伦的犹大人，都要因他们的遭遇这样咒诅人，说：“愿主使你像巴比伦王用火烧死的西底家和亚哈一样。”'),
('CNV', '耶利米书', 24, 29, 23, '因为他们二人在以色列中行了无耻的事，他们和邻舍的妻子通奸，又冒我的名说虚假的话，是我没有吩咐他们说的。我知道一切，也可以作证。’这是主的宣告。”'),
('CNV', '耶利米书', 24, 29, 24, '主吩咐耶利米说：“你要对尼希兰人示玛雅说：'),
('CNV', '耶利米书', 24, 29, 25, '‘万军之主以色列的神这样说：你曾用自己的名寄信给在耶路撒冷的众民、玛西雅祭司的儿子西番雅，和众祭司，说：'),
('CNV', '耶利米书', 24, 29, 26, '主已经立了你西番雅为祭司，代替耶何耶大，作主殿中的总管，你就应把所有妄自说预言的人，都带上脚镣枷锁。'),
('CNV', '耶利米书', 24, 29, 27, '现在，亚拿突人耶利米向你们说预言，你为什么不斥责他呢？'),
('CNV', '耶利米书', 24, 29, 28, '因为他寄信给我们在巴比伦的人说：被掳的时期必会长久，所以你们要建造房屋，定居下来，也要栽植园子，吃园中的果子。’”（'),
('CNV', '耶利米书', 24, 29, 29, '西番雅祭司却把这封信念给耶利米先知听。）'),
('CNV', '耶利米书', 24, 29, 30, '主的话又临到耶利米，说：'),
('CNV', '耶利米书', 24, 29, 31, '“你要寄信给所有被掳的人，说：‘论到尼希兰人示玛雅，主这样说：因为示玛雅向你们说预言，我并没有差遣他，他竟使你们信靠谎言。'),
('CNV', '耶利米书', 24, 29, 32, '所以主这样说：看哪！我必惩罚尼希兰人示玛雅和他的后代；他必不会有子孙住在这人民中间，也必不能看见我要为我的子民所作的美事，因为他说了悖逆主的话。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 30, 1, '主有话临到耶利米，说：'),
('CNV', '耶利米书', 24, 30, 2, '“主以色列的神这样说：‘你要把我对你说过的一切话都写在书上。'),
('CNV', '耶利米书', 24, 30, 3, '看哪！日子快到（这是主的宣告），我必使我的子民以色列和犹大被掳的人归回。’主说：‘我必使他们回到我赐给他们列祖之地，他们要重得这地为业。’”'),
('CNV', '耶利米书', 24, 30, 4, '以下是主论到以色列和犹大所说的话：'),
('CNV', '耶利米书', 24, 30, 5, '“主这样说：‘我听见了战栗喊叫的声音，一片恐慌，没有平安。'),
('CNV', '耶利米书', 24, 30, 6, '你们去问问，去看看：男人会生孩子吗？为什么我看见所有的壮汉，都用手抱着腹部，像正在生产的妇人，每张脸都变成苍白呢？'),
('CNV', '耶利米书', 24, 30, 7, '哀哉！那日大而可畏，无可比拟；这是雅各受苦的时期，但他必被救出来。’”'),
('CNV', '耶利米书', 24, 30, 8, '“万军之主宣告说：‘当那日，我必从他们（按照《马索拉文本》，“他们”应作“你”；现参照《七十士译本》翻译）的颈项上折断仇敌的轭，扯断他们（按照《马索拉文本》，“他们”应作“你”；现参照《七十士译本》翻译）的绳套；他们必不再作外族人的奴隶。'),
('CNV', '耶利米书', 24, 30, 9, '他们却要事奉主他们的神，和我为他们兴起的大卫王。'),
('CNV', '耶利米书', 24, 30, 10, '所以，我的仆人雅各啊！你不要惧怕。’这是主的宣告。‘以色列啊！你不要惊慌。因为我必拯救你从远方回来，必拯救你的后裔脱离他们被掳之地。雅各必归回，得享平静安逸，没有人可以使他害怕。'),
('CNV', '耶利米书', 24, 30, 11, '因为我与你同在，要拯救你；我要消灭我赶散你去的列国，却必不消灭你。我要按公正惩治你，决不能免你受罚。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 30, 12, '“主这样说：‘你的损伤无法痊愈，你的创伤不能医治。'),
('CNV', '耶利米书', 24, 30, 13, '没有人为你申诉，你的伤处无药可救，你不得医治。'),
('CNV', '耶利米书', 24, 30, 14, '你所有的盟友都忘记了你，不再关心你；我击打了你，好像仇敌击打你，又好像残暴的人惩罚你一样；都因你的罪孽甚多，你的罪恶无数。'),
('CNV', '耶利米书', 24, 30, 15, '你为什么因你的损伤哀叫呢？你的病痛无法痊愈。我这样对你，是因你的罪孽甚多，你的罪恶无数。'),
('CNV', '耶利米书', 24, 30, 16, '但是，吞吃你的，必被吞吃；你所有的敌人全都要被掳走；抢掠你的，必成为被抢掠之物；掠夺你的，我必使他们成为被掠夺之物。'),
('CNV', '耶利米书', 24, 30, 17, '虽然人都说你是被放逐的，是没有人关心的锡安；我却必使你康复，医治你的创伤。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 30, 18, '“主这样说：‘看哪！我必复兴雅各的帐棚，也必怜悯他的居所；城市必在废墟上重建，堡垒必立在原来的地点上。'),
('CNV', '耶利米书', 24, 30, 19, '必有感谢的歌声，和欢笑的声音从其中发出来。我必使他们人数增多，不会减少；我必使他们得尊荣，不再被人轻看。'),
('CNV', '耶利米书', 24, 30, 20, '他们的子孙必像以前一样蒙恩，他们的国家必在我面前坚立；我必惩罚所有压迫他们的人。'),
('CNV', '耶利米书', 24, 30, 21, '他们的元首必是他们自己的人，他们的统治者必出自他们中间；我必使他近前来，他也必亲近我，不然，谁敢冒生命的危险来亲近我呢？’这是主的宣告。'),
('CNV', '耶利米书', 24, 30, 22, '‘你们要作我的子民，我要作你们的神。’”'),
('CNV', '耶利米书', 24, 30, 23, '看哪！主的旋风，在震怒中发出，是横扫的狂风，必卷到恶人的头上。'),
('CNV', '耶利米书', 24, 30, 24, '主的烈怒必不转消，直到他作成和实现他心中的计划。在末后的日子，你们就会明白这事。'),
('CNV', '耶利米书', 24, 31, 1, '“到那时，我必作以色列各家族的神，他们要作我的子民。”这是主的宣告。'),
('CNV', '耶利米书', 24, 31, 2, '主这样说：“在刀剑下幸存的人民，在旷野蒙受了恩宠；以色列来到她安息之处。”'),
('CNV', '耶利米书', 24, 31, 3, '主在古时（“在古时”或译：“从远处”）曾向以色列（按照《马索拉文本》，“以色列”应作“我”；现参照《七十士译本》翻译）显现，说：“我以永远的爱爱你，因此，我对你的慈爱延续不息（“我对你的慈爱延续不息”或译：“我要以慈爱吸引你”）。'),
('CNV', '耶利米书', 24, 31, 4, '童女以色列啊！我要再次建立你，你就必被建立。你要再次拿起铃鼓，出去和那些欢乐的人一同跳舞。'),
('CNV', '耶利米书', 24, 31, 5, '你要再次在撒玛利亚的众山上栽种葡萄园，栽种的人栽种了，必可享用所结的果子。'),
('CNV', '耶利米书', 24, 31, 6, '因为有一天，守望的人要在以法莲山上呼叫，说：‘起来吧！我们上锡安去朝见主我们的神。’”'),
('CNV', '耶利米书', 24, 31, 7, '主这样说：“你们要为雅各喜乐欢呼，要为那在列国为首的呼喊。你们要宣告，要颂赞，说：‘主啊！求你拯救你的子民，就是以色列的余民。’'),
('CNV', '耶利米书', 24, 31, 8, '看哪！我必把他们从北方之地领回来，把他们从地极招集起来；在他们中间有瞎眼的、瘸腿的、孕妇、产妇，都在一起；他们成群结队返回这里。'),
('CNV', '耶利米书', 24, 31, 9, '我引导他们的时候，他们必哭着而来，并且向我乞恩恳求。我要使他们走在溪水旁，行在平直的路上，他们必不会绊跌；因为我是以色列的父亲，以法莲是我的长子。'),
('CNV', '耶利米书', 24, 31, 10, '“列国啊！你们要听主的话，要在远方的海岛传扬，说：‘那赶散以色列的神，必再招集他们；必看守他们，像牧人看守自己的羊群一样。’'),
('CNV', '耶利米书', 24, 31, 11, '因为主买赎了雅各，从比他更强的人手中把他救赎了出来。'),
('CNV', '耶利米书', 24, 31, 12, '他们必来到锡安的高处欢呼；他们必容光焕发，因为主赐他们各样的美物，就是五谷、新酒和油，还有羊羔和牛犊。他们必像有水灌溉的园子，永不再枯干。'),
('CNV', '耶利米书', 24, 31, 13, '那时，童女必欢乐跳舞，年轻的和年老的一起欢乐。我必使他们的悲哀变为喜乐，我必安慰他们，使他们从忧愁中得着欢乐。'),
('CNV', '耶利米书', 24, 31, 14, '我必用肥脂使祭司的心满足；我的子民必因我的美物饱足。”这是主的宣告。'),
('CNV', '耶利米书', 24, 31, 15, '主这样说：“在拉玛听见有声音，是痛哭哀号的声音；拉结为她的儿女哀哭，不肯受安慰，因为他们都不在了。”'),
('CNV', '耶利米书', 24, 31, 16, '主这样说：“止住你的声音，不要哭泣，抑制你的眼睛不要再流泪，因为你所作的必有果效；他们必从仇敌之地回来。”这是主的宣告。'),
('CNV', '耶利米书', 24, 31, 17, '“你的前途必有希望；你的儿女必返回自己的地方。”这是主的宣告。'),
('CNV', '耶利米书', 24, 31, 18, '“我清楚听见以法莲为自己哀叹，说：‘你管教了我，我像一头不驯服的牛犊受管教；求你使我回转，我就得以回转，因为你是主我的神。'),
('CNV', '耶利米书', 24, 31, 19, '我回转以后，就深深悔悟；我醒觉以后，就拍腿悔恨。因为我承受年幼时的耻辱，我感到羞耻和惭愧。’'),
('CNV', '耶利米书', 24, 31, 20, '以法莲是我亲爱的儿子吗？是我喜悦的孩子吗？每逢我说话攻击他，我必再次记念他。因此，我的心恋慕他；我必定怜悯他。”这是主的宣告。'),
('CNV', '耶利米书', 24, 31, 21, '你要为自己设立路标，竖立路牌；你要留心大路，就是你走过的路。童女以色列啊，回转吧！回到你这些城市那里。'),
('CNV', '耶利米书', 24, 31, 22, '转离正道的女儿哪，你转来转去要到几时呢？因为主在地上创造了一件新事，就是女的要环绕男的。'),
('CNV', '耶利米书', 24, 31, 23, '万军之主以色列的神这样说：“我使被掳的人归回的时候，他们在犹大地，在犹大的城镇里，必再说这样的话：‘公义的居所啊，圣山哪，愿主赐福给你！’'),
('CNV', '耶利米书', 24, 31, 24, '犹大各城的人、耕地的和领着群畜游牧的，都要一起住在犹大。'),
('CNV', '耶利米书', 24, 31, 25, '疲倦的人，我必使他振作；愁苦的人，我必使他满足。”'),
('CNV', '耶利米书', 24, 31, 26, '这时，我醒过来，四周观看；我睡得很香甜。'),
('CNV', '耶利米书', 24, 31, 27, '“看哪！日子快到（这是主的宣告），我必使以色列家和犹大家人口和牲畜繁衍。'),
('CNV', '耶利米书', 24, 31, 28, '我先前怎样留意把他们拔出、拆毁、倾覆、毁灭和降灾；将来我也必照样留意把他们建立和栽种起来。”这是主的宣告。'),
('CNV', '耶利米书', 24, 31, 29, '“在那些日子，人必不再说：‘父亲吃了酸葡萄，儿子的牙齿酸倒了。’'),
('CNV', '耶利米书', 24, 31, 30, '因为各人必因自己的罪孽死亡；吃酸葡萄的，那人的牙齿必酸倒。'),
('CNV', '耶利米书', 24, 31, 31, '“看哪！日子快到（这是主的宣告），我要与以色列家和犹大家订立新的约。'),
('CNV', '耶利米书', 24, 31, 32, '这新约不像从前我拉他们祖先的手，领他们出埃及地的日子，与他们所立的约；我虽然是他们的丈夫，他们却违背了我的约。”这是主的宣告。'),
('CNV', '耶利米书', 24, 31, 33, '“但那些日子以后，我要与以色列家所立的约是这样（这是主的宣告）：我要把我的律法放在他们里面，写在他们的心里。我要作他们的神，他们要作我的子民。'),
('CNV', '耶利米书', 24, 31, 34, '他们各人必不再教导自己的邻舍和自己的同胞，说：‘你们要认识主。’因为所有的人，从最小到最大的都必认识我。我也要赦免他们的罪孽，不再记着他们的罪恶。”这是主的宣告。'),
('CNV', '耶利米书', 24, 31, 35, '那使太阳白昼发光，派定月亮和星辰照耀黑夜，又搅动海洋，使海浪澎湃的，万军之主是他的名，他这样说：'),
('CNV', '耶利米书', 24, 31, 36, '“这些定律若能从我面前废掉，以色列的后裔也就会在我面前断绝，永远不再成为一个国家。”这是主的宣告。'),
('CNV', '耶利米书', 24, 31, 37, '主这样说：“人若能量度在上的诸天，测透地下面的根基，我也就会因以色列后裔所作的一切，弃绝他们众人。”这是主的宣告。'),
('CNV', '耶利米书', 24, 31, 38, '“看哪！日子快到（这是主的宣告），这城从哈楠业城楼直到角门，必为主重建起来。'),
('CNV', '耶利米书', 24, 31, 39, '量度的准绳还要往外量，直到迦立山，绕到歌亚。'),
('CNV', '耶利米书', 24, 31, 40, '抛尸和倒灰的整个山谷，以及从汲沦溪直到东边马门拐角一带所有的墓地，都必归主为圣，永远不再拔出，不再倾覆。”'),
('CNV', '耶利米书', 24, 32, 1, '犹大王西底家第十年，就是尼布甲尼撒第十八年，从主那里有话临到耶利米。'),
('CNV', '耶利米书', 24, 32, 2, '那时，巴比伦王的军队正在围困耶路撒冷，耶利米先知被囚禁在犹大王宫中卫兵的院子里。'),
('CNV', '耶利米书', 24, 32, 3, '因为犹大王西底家把他囚禁起来，说：“你为什么预言：‘主这样说：看哪！我必把这城交在巴比伦王的手中，他必攻取这城；'),
('CNV', '耶利米书', 24, 32, 4, '犹大王西底家必不能逃脱迦勒底人的手，他必交在巴比伦王的手中；他们必面对面彼此说话，眼对眼互相对看。'),
('CNV', '耶利米书', 24, 32, 5, '巴比伦王必把西底家带到巴比伦去；西底家必留在那里，直到我眷顾他的时候（这是主的宣告）。即使你们和迦勒底人作战，你们必不能战胜’？”'),
('CNV', '耶利米书', 24, 32, 6, '耶利米说：“主的话临到我，说：'),
('CNV', '耶利米书', 24, 32, 7, '‘看哪！你叔叔沙龙的儿子哈拿篾必来见你，说：请你买下我在亚拿突的那块田地，因为你有近亲的权利和义务去买那田地。’'),
('CNV', '耶利米书', 24, 32, 8, '我叔叔的儿子哈拿篾果然照着主的话，到卫兵的院子里来见我，对我说：‘请你买下我在便雅悯境内亚拿突的那块田地，因为你有那产业的继承权，以及近亲的权利和义务；请你把它买下吧。’于是我知道这是主的话。'),
('CNV', '耶利米书', 24, 32, 9, '我就向我叔叔的儿子哈拿篾，买下了在亚拿突的那块田地，称了一百九十三克银子给他。'),
('CNV', '耶利米书', 24, 32, 10, '“我在契约上签了名，把契封好了，又请了证人作证，就用天平把银子称给他。'),
('CNV', '耶利米书', 24, 32, 11, '然后我取了买卖契约，一份是封好的，一份是没有加封的，上面都有各种细则和条件。'),
('CNV', '耶利米书', 24, 32, 12, '当着我叔叔的儿子哈拿篾眼前，当着那些在买卖契约上签名作证的人眼前，以及当着所有坐在卫兵院子里的犹大人眼前，我把买卖契约交给了玛西雅的孙子、尼利亚的儿子巴录。'),
('CNV', '耶利米书', 24, 32, 13, '我当着这些人眼前吩咐巴录说：'),
('CNV', '耶利米书', 24, 32, 14, '‘万军之主以色列的神这样说：你要拿这两份买卖契约，就是那封好的和没有加封的，放在一个瓦器里，使它们可以长久保存。'),
('CNV', '耶利米书', 24, 32, 15, '因为万军之主以色列的神这样说：将来在这地必再有人买房屋、田地和葡萄园。’'),
('CNV', '耶利米书', 24, 32, 16, '“我把买卖契约交给尼利亚的儿子巴录以后，就向主祷告，说：'),
('CNV', '耶利米书', 24, 32, 17, '‘主神啊！你看，你曾用大能和伸出来的膀臂创造了天地；在你并没有难成的事。'),
('CNV', '耶利米书', 24, 32, 18, '你向千万人施慈爱，又把父亲的罪孽都报应在他们的儿女身上。你是伟大、有能力的神，万军之主是你（“你”原文作“他”）的名。'),
('CNV', '耶利米书', 24, 32, 19, '你的计划伟大，你的作为满有能力；你的眼睛睁开，察看世人一切所行的，要照着各人的行为，和各人所作的事应得的结果来报应各人。'),
('CNV', '耶利米书', 24, 32, 20, '你曾在埃及地行神迹奇事，你在以色列和全人类中间直到今日也是这样，使你自己得了名声，好像今日一样。'),
('CNV', '耶利米书', 24, 32, 21, '你曾用神迹奇事、有力的手、伸出来的膀臂，和大而可畏的事，把你的子民以色列从埃及地领出来。'),
('CNV', '耶利米书', 24, 32, 22, '你把这地赐给他们，就是你向他们列祖起誓，要赐给他们的流奶与蜜之地。'),
('CNV', '耶利米书', 24, 32, 23, '他们进去，得到这地为业，却不听从你的话，也不遵行你的律法；你吩咐他们行的一切事，他们都没有行，因此你使这一切灾祸临到他们身上。'),
('CNV', '耶利米书', 24, 32, 24, '看哪！敌人已经迫近，筑垒攻取这城。这城要因刀剑、饥荒和瘟疫的缘故，交在攻击他们的迦勒底人手中；你所说的都实现了，你也亲眼看见了。'),
('CNV', '耶利米书', 24, 32, 25, '但主神啊！是你对我说：“你要用银子买下那块田地，请证人作证。”其实这城已经交在迦勒底人的手中了。’”'),
('CNV', '耶利米书', 24, 32, 26, '主的话临到耶利米，说：'),
('CNV', '耶利米书', 24, 32, 27, '“看哪！我是主，是全人类的神；在我有难成的事吗？'),
('CNV', '耶利米书', 24, 32, 28, '因此主这样说：‘看哪！我必把这城交在迦勒底人的手中，交在巴比伦王尼布甲尼撒的手中，他必攻取这城。'),
('CNV', '耶利米书', 24, 32, 29, '攻打这城的迦勒底人必进来，放火烧城，城中的房屋都必烧光，因为这城的居民曾在那些房屋的屋顶上向巴力烧香，向别神浇奠祭，惹我发怒。'),
('CNV', '耶利米书', 24, 32, 30, '事实上，以色列人和犹大人自幼以来，就专行我眼中看为恶的事；以色列人的手所作的，无不惹我发怒。’这是主的宣告。'),
('CNV', '耶利米书', 24, 32, 31, '‘因为这城自从建造的那天，直到今日，都不断惹起我的怒气和烈怒，以致我要把她从我面前除掉。'),
('CNV', '耶利米书', 24, 32, 32, '这是因为以色列人和犹大人的一切恶行，就是他们和他们的君王、领袖、祭司、先知，以及犹大每一个人和耶路撒冷居民所行的，都惹我发怒。'),
('CNV', '耶利米书', 24, 32, 33, '他们以背向我，不以脸向我；我不断教导他们，他们却不肯听从，不接受管教；'),
('CNV', '耶利米书', 24, 32, 34, '竟把他们可憎的偶像安放在称为我名下的殿中，污秽了这殿。'),
('CNV', '耶利米书', 24, 32, 35, '他们在欣嫩子谷中，建造了巴力的邱坛，使自己的儿女经火献给摩洛。这不是我吩咐的，也没有在我心里想过；他们竟行了这可憎恶的事，使犹大犯罪。’'),
('CNV', '耶利米书', 24, 32, 36, '“论到这城，就是你们说：‘因为刀剑、饥荒和瘟疫的缘故，交在巴比伦王手中的’，现在主以色列的神却这样说：'),
('CNV', '耶利米书', 24, 32, 37, '‘看哪！我曾在怒气、烈怒和大忿怒中，把以色列人赶逐到各地，将来我必从那里把他们招聚出来，领他们回到这地方，使他们安然居住。'),
('CNV', '耶利米书', 24, 32, 38, '他们必作我的子民，我也必作他们的神。'),
('CNV', '耶利米书', 24, 32, 39, '我要使他们有同一的心志和同一的行为，终生敬畏我，使他们和他们的子孙都得到福乐。'),
('CNV', '耶利米书', 24, 32, 40, '我要和他们立永远的约，我必不离开他们，必使他们得到福乐；我也必把敬畏我的心赐给他们，使他们不会离开我。'),
('CNV', '耶利米书', 24, 32, 41, '我必喜欢他们，使他们得到福乐；我必全心全意、真诚地把他们栽种在这地上。’'),
('CNV', '耶利米书', 24, 32, 42, '“因为主这样说：‘我怎样使这一切大灾祸临到这人民，我也必照样使我应许他们的福乐临到他们。'),
('CNV', '耶利米书', 24, 32, 43, '你们说：“这地荒凉，没有人烟，也没有牲畜，是交在迦勒底人手中的。”但将来在这地上，必有人买卖田地。'),
('CNV', '耶利米书', 24, 32, 44, '在便雅悯地，在耶路撒冷周围的各处，在犹大各城，以及在山地、高地和南地的各城，人必用银子买卖田地，在地契上签名，把契封好，又请证人作证；因为我必使他们被掳的人归回。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 33, 1, '耶利米还监禁在卫兵院子里的时候，主的话第二次临到他，说：'),
('CNV', '耶利米书', 24, 33, 2, '“那创造、塑造和坚定大地的是主，主是他的名。他这样说：'),
('CNV', '耶利米书', 24, 33, 3, '‘你呼求我，我就应允你，并且把你所不知道的那些伟大奥秘的事告诉你。’'),
('CNV', '耶利米书', 24, 33, 4, '论到这城里的房屋和犹大王的宫殿，就是为了抵挡敌人的攻城土垒和刀剑而拆毁的，主以色列的神这样说：'),
('CNV', '耶利米书', 24, 33, 5, '‘这城的居民出去和迦勒底人争战，就必使这些房屋充满死尸，就是我在怒气和烈怒中击杀的。因为他们的一切恶行，我掩面不顾这城。'),
('CNV', '耶利米书', 24, 33, 6, '看哪！我必使这城的伤口痊愈康复，我必医治城中的居民，并且使他们享有十分的平安和稳妥。'),
('CNV', '耶利米书', 24, 33, 7, '我必使犹大被掳的和以色列被掳的都归回，并且建立他们像起初一样。'),
('CNV', '耶利米书', 24, 33, 8, '我必洁净他们得罪我的一切罪孽，并且赦免他们得罪我和悖逆我的一切罪孽。'),
('CNV', '耶利米书', 24, 33, 9, '这城必在地上万国面前使我得名声，得喜乐（按照《马索拉文本》，“得名声，得喜乐”应作“得喜乐的名声”；现参照《七十士译本》翻译），得颂赞，得荣耀，因为万国必听见我向这城的人所施的一切福乐。他们因我向这城所施的一切福乐和平安，就都恐惧战兢。’'),
('CNV', '耶利米书', 24, 33, 10, '“主这样说：‘论到这地方，你们说：“这地荒废，没有人烟，也没有牲畜。”但在这荒凉、没有人烟、没有居民、也没有牲畜的犹大各城和耶路撒冷的街上，必再听见'),
('CNV', '耶利米书', 24, 33, 11, '欢喜和快乐的声音，新郎和新妇的声音；还要听见那些带着感恩祭到主殿的人的声音说：“你们要称谢万军之主，因为主是至善的，他的慈爱永远长存。”因为我必使这地被掳的归回，像起初一样。’”这是主说的。'),
('CNV', '耶利米书', 24, 33, 12, '“万军之主这样说：‘在这荒废、没有人烟、没有牲畜的地方，和这地所有城中，必再有牧人放羊的牧场。'),
('CNV', '耶利米书', 24, 33, 13, '在山地、高地和南地的各城，在便雅悯地，在耶路撒冷周围的各处，以及在犹大的各城里，必再有牧人数点经过手下的羊群。’”这是主说的。'),
('CNV', '耶利米书', 24, 33, 14, '“看哪！日子快到（这是主的宣告），我必实践我向以色列家和犹大家应许赐福的诺言。'),
('CNV', '耶利米书', 24, 33, 15, '在那些日子、那时候，我必使大卫公义的苗裔长起来；他必在地上施行公正和公义。'),
('CNV', '耶利米书', 24, 33, 16, '在那些日子，犹大必得救，耶路撒冷必安然居住；这城必被称为‘主是我们的公义’。'),
('CNV', '耶利米书', 24, 33, 17, '因为主这样说：‘大卫家必不断有人坐在以色列家的王位上。'),
('CNV', '耶利米书', 24, 33, 18, '利未人的祭司也必不断有人在我面前献上燔祭和烧素祭；献祭的事永不止息。’”'),
('CNV', '耶利米书', 24, 33, 19, '主说的话临到耶利米，说：'),
('CNV', '耶利米书', 24, 33, 20, '“主这样说：‘你们若能废掉我所立白昼和黑夜的约，使白昼和黑夜不按时更替，'),
('CNV', '耶利米书', 24, 33, 21, '就能废掉我和我仆人大卫所立的约，使他没有儿子在他的王位上作王；也能废掉我和那些事奉我的利未支派的祭司所立的约。'),
('CNV', '耶利米书', 24, 33, 22, '我却必使我仆人大卫的后裔和事奉我的利未人增多，像天上的万象不能数算、海边的沙粒不能斗量。’”'),
('CNV', '耶利米书', 24, 33, 23, '主的话临到耶利米，说：'),
('CNV', '耶利米书', 24, 33, 24, '“你没有留意列国的人民说什么吗？他们说：‘主所拣选的这两个家族，他已经弃绝了。’他们藐视我的子民，不再把他们看为一个国家。'),
('CNV', '耶利米书', 24, 33, 25, '主这样说：‘我若没有设立白昼和黑夜的约，或立定天地的定律，'),
('CNV', '耶利米书', 24, 33, 26, '我就会弃绝雅各的后裔，和我仆人大卫的后裔，不从大卫的后裔中选人出来统治亚伯拉罕、以撒和雅各的后裔。我却必使他们被掳的人归回，也必怜悯他们。’”'),
('CNV', '耶利米书', 24, 34, 1, '巴比伦王尼布甲尼撒率领他的全军，以及他统治的地上各国各族，攻打耶路撒冷和周围一切城镇的时候，从主那里有话临到耶利米，说：'),
('CNV', '耶利米书', 24, 34, 2, '“主以色列的神这样说：‘你去告诉犹大王西底家说：主这样说：看哪！我要把这城交在巴比伦王的手中，他要用火烧城。'),
('CNV', '耶利米书', 24, 34, 3, '你必逃不出他的手，必被拿住，交在他的手中。你必亲眼看见巴比伦王，他必亲口和你说话；你也必到巴比伦去。’'),
('CNV', '耶利米书', 24, 34, 4, '但犹大王西底家啊，你还要听主的话！主论到你这样说：‘你必不会死在刀下；'),
('CNV', '耶利米书', 24, 34, 5, '你必平平安安死去。人怎样为你的列祖，就是在你以前的君王，焚烧香料，也必照样为你焚烧香料；人必为你哀悼，说：“哀哉，主上！”’这话是我说的。”这是主的宣告。'),
('CNV', '耶利米书', 24, 34, 6, '于是耶利米先知在耶路撒冷把这一切话都告诉了犹大王西底家。'),
('CNV', '耶利米书', 24, 34, 7, '那时，巴比伦王的军队正在攻打耶路撒冷和犹大剩下的城镇，就是拉吉和亚西加，因为在犹大的各城中，只剩下这两座坚固的城了。'),
('CNV', '耶利米书', 24, 34, 8, '西底家王和在耶路撒冷的众民立了约，要向奴仆宣告自由。人人都要释放自己的希伯来奴婢；谁也不可使自己的一位犹大兄弟作奴仆。（这事以后，从主那里有话临到耶利米。）'),
('CNV', '耶利米书', 24, 34, 10, '所有立了约的领袖和众民都同意释放各人自己的奴婢，谁也不再使他们作奴仆。他们都同意了，并且把奴婢释放了。'),
('CNV', '耶利米书', 24, 34, 11, '但后来他们反悔，把他们释放了的奴婢叫回来，强迫他们再作奴婢。'),
('CNV', '耶利米书', 24, 34, 12, '于是主有话临到耶利米，说：'),
('CNV', '耶利米书', 24, 34, 13, '“主以色列的神这样说：‘我把你们的列祖从埃及地为奴之家领出来的那日子，就和他们立了约，说：'),
('CNV', '耶利米书', 24, 34, 14, '“一个希伯来兄弟卖了身给你，服事了你六年，到第七年，你们各人就应释放他，容他自由离去。”但你们的列祖不听从我，毫不在意。'),
('CNV', '耶利米书', 24, 34, 15, '现今你们悔改，行我眼中看为正的事，各人向自己的同胞宣告自由，并且在称为我名下的殿中，在我面前立了约。'),
('CNV', '耶利米书', 24, 34, 16, '你们却又反悔，亵渎我的名；各人把得了释放随意离去的奴婢叫回来，强迫他们再作奴婢。’'),
('CNV', '耶利米书', 24, 34, 17, '“所以，主这样说：‘你们各人没有听从我，向兄弟、同胞宣告自由；看哪！我现在向你们宣告自由，容让你们遭受刀剑、瘟疫和饥荒，使你们成为地上万国所惊惧的。’这是主的宣告。'),
('CNV', '耶利米书', 24, 34, 18, '‘我必把那些违犯我的约的人交出去；他们没有履行在我面前和我立约的誓言，就是他们把牛犊劈开两半，并且从两半中间走过去时立下的。'),
('CNV', '耶利米书', 24, 34, 19, '那些从牛犊两半中间走过去的人，就是犹大的领袖、耶路撒冷的领袖、宫中的臣宰、祭司和这地的众民。'),
('CNV', '耶利米书', 24, 34, 20, '我必把他们交在他们仇敌的手中，和那些寻索他们性命的人的手中；他们的尸体必给空中的飞鸟和地上的走兽作食物。'),
('CNV', '耶利米书', 24, 34, 21, '我也必把犹大王西底家和众领袖交在他们仇敌的手中，和那些寻索他们性命的人的手中，以及那些从你们面前暂时撤退的巴比伦王的军队的手中。'),
('CNV', '耶利米书', 24, 34, 22, '看哪！我必下令，使他们回到这城来；他们必攻打、夺取这城，用火焚烧；我必使犹大的城镇都荒凉，没有人居住。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 35, 1, '在犹大王约西亚的儿子约雅敬作王的日子，主有话临到耶利米，说：'),
('CNV', '耶利米书', 24, 35, 2, '“你去见利甲族的人，和他们交谈，领他们进入主殿里的一个房间，给他们酒喝。”'),
('CNV', '耶利米书', 24, 35, 3, '于是我把哈巴洗尼雅的孙子、雅利米雅的儿子雅撒尼亚，以及他的兄弟、他的众子和利甲全族的人，'),
('CNV', '耶利米书', 24, 35, 4, '都领进主的殿里，进了神人伊基大利的儿子哈难众子的房间；这房间是在众领袖的房间旁边，在沙龙的儿子守卫殿门的玛西雅的房间上面。'),
('CNV', '耶利米书', 24, 35, 5, '然后我把盛满酒的酒壶和酒杯，摆放在利甲族人的面前，对他们说：“请喝酒！”'),
('CNV', '耶利米书', 24, 35, 6, '但他们说：“我们不喝酒，因为我们的祖先利甲的儿子约拿达曾吩咐我们说：‘你们和你们的子孙永远都不可喝酒。'),
('CNV', '耶利米书', 24, 35, 7, '你们也不可建造房屋，不可撒种，不可栽种或拥有葡萄园；你们一生的日子只可住帐棚，使你们在寄居的地上活得长久。’'),
('CNV', '耶利米书', 24, 35, 8, '我们的祖先利甲的儿子约拿达吩咐我们的一切话，我们都听从了；我们和我们的妻子儿女，终生都不喝酒，'),
('CNV', '耶利米书', 24, 35, 9, '不建造房屋居住，也没有葡萄园、田地和种子。'),
('CNV', '耶利米书', 24, 35, 10, '我们只住帐棚；我们听从祖先约拿达吩咐我们的一切话，并且照着去行。'),
('CNV', '耶利米书', 24, 35, 11, '但是，巴比伦王尼布甲尼撒上来攻打这地的时候，我们就说：‘来吧！为了迦勒底和亚兰人的军队的缘故，我们到耶路撒冷去。’这样，我们才住在耶路撒冷。”'),
('CNV', '耶利米书', 24, 35, 12, '主的话临到耶利米，说：'),
('CNV', '耶利米书', 24, 35, 13, '“万军之主以色列的神这样说：你去对犹大人和耶路撒冷的居民说：‘你们不接受管教，不听我的话吗？’这是主的宣告。'),
('CNV', '耶利米书', 24, 35, 14, '‘利甲的儿子约拿达吩咐他的子孙不可喝酒的话，他们已经实行了，他们直到今日都不喝酒，因为他们听从了他们祖先的吩咐。至于我，我不断告诫你们，你们却不听从我。'),
('CNV', '耶利米书', 24, 35, 15, '我不断差遣我的仆人众先知到你们那里去，对你们说：你们各人要悔改，离开自己的恶道，改正你们的行为，不可随从事奉别神；这样，你们就可以住在我赐给你们和你们列祖的土地上。只是你们毫不在意，也没有听从我。'),
('CNV', '耶利米书', 24, 35, 16, '利甲的儿子约拿达的子孙实行了他们祖先吩咐他们的命令，但这人民没有听从我。’'),
('CNV', '耶利米书', 24, 35, 17, '因此，主万军的神、以色列的神这样说：‘看哪！我必使我对他们预告过的一切灾祸，临到犹大人和耶路撒冷所有的居民，因为我对他们说话，他们却不听从；我呼唤他们，他们却不回应。’”'),
('CNV', '耶利米书', 24, 35, 18, '耶利米对利甲族人说：“万军之主以色列的神这样说：‘因为你们听从了你们祖先约拿达的吩咐，谨守他的一切命令，又照着他吩咐你们的一切去行。’'),
('CNV', '耶利米书', 24, 35, 19, '所以，万军之主以色列的神这样说：‘利甲的儿子约拿达必永远不断有人在我面前侍立。’”'),
('CNV', '耶利米书', 24, 36, 1, '犹大王约西亚的儿子约雅敬第四年，主那里有这话临到耶利米，说：'),
('CNV', '耶利米书', 24, 36, 2, '“你取一卷书卷来，在上面写下我在约西亚作王的时候开始，直到今日，对你所说论到以色列和犹大，以及列国的一切话。'),
('CNV', '耶利米书', 24, 36, 3, '或者犹大家听见我想要降给他们的一切灾祸，各人就回转，离开自己的恶道，我就赦免他们的罪孽和罪恶。”'),
('CNV', '耶利米书', 24, 36, 4, '于是耶利米把尼利亚的儿子巴录叫了来，巴录就从耶利米口中，把主向耶利米所说的一切话，都写在书卷上。'),
('CNV', '耶利米书', 24, 36, 5, '耶利米吩咐巴录说：“我被阻止，不能进主的殿里去。'),
('CNV', '耶利米书', 24, 36, 6, '所以你要进去，趁禁食的日子，在主的殿里，向众人宣读书卷上的话，就是你从我口中所录下主的话。你要向从犹大各城来的人宣读。'),
('CNV', '耶利米书', 24, 36, 7, '也许他们会向主恳求，各人回转，离开自己的恶道，因为主向这人民所说要发的怒气和烈怒是很大的。”'),
('CNV', '耶利米书', 24, 36, 8, '尼利亚的儿子巴录就照着耶利米先知吩咐的一切去行，在主的殿里宣读书上主的话。'),
('CNV', '耶利米书', 24, 36, 9, '犹大王约西亚的儿子约雅敬第五年九月，耶路撒冷的众民，和所有从犹大各城来到耶路撒冷的人民，都在主面前宣告禁食。'),
('CNV', '耶利米书', 24, 36, 10, '巴录就在主的殿里，向众民宣读书上耶利米的话。那时他是在沙番的儿子书记基玛利雅的房间里，这房间是在上院，靠近主殿里新门的入口。'),
('CNV', '耶利米书', 24, 36, 11, '沙番的孙子基玛利雅的儿子米该亚，听见了书上主的一切话，'),
('CNV', '耶利米书', 24, 36, 12, '就下到王宫，进入书记的房间里；所有领袖都在那里坐着，他们是书记以利沙玛、示玛雅的儿子第莱雅、亚革波的儿子以利拿单、沙番的儿子基玛利雅、哈拿尼雅的儿子西底家和所有其余的领袖。'),
('CNV', '耶利米书', 24, 36, 13, '米该亚就把所听见的一切都告诉他们，就是巴录向众人宣读那书的时候，他所听见的。'),
('CNV', '耶利米书', 24, 36, 14, '于是所有的领袖差派古示的曾孙、示利米雅的孙子、尼探雅的儿子犹底，去见巴录，说：“请你把向众人宣读的那书卷亲自拿来。”尼利亚的儿子巴录就把书卷亲自带到他们那里。'),
('CNV', '耶利米书', 24, 36, 15, '他们对他说：“请坐下，念给我们听。”巴录就向他们宣读。'),
('CNV', '耶利米书', 24, 36, 16, '他们听见这一切话，就惊惧起来，面面相觑，对巴录说：“我们必须把这一切话禀告王。”'),
('CNV', '耶利米书', 24, 36, 17, '他们向巴录说：“请告诉我们，你怎样写下这一切话，是耶利米亲口说的吗？”'),
('CNV', '耶利米书', 24, 36, 18, '巴录对他们说：“这一切话是他亲口向我讲述的，我就用墨写在书上。”'),
('CNV', '耶利米书', 24, 36, 19, '众领袖对巴录说：“你和耶利米都要去躲藏起来；不要给人知道你们在什么地方。”'),
('CNV', '耶利米书', 24, 36, 20, '众领袖把书卷存在书记以利沙玛的房间里，然后进内院去见王，把这一切话都禀告给王听。'),
('CNV', '耶利米书', 24, 36, 21, '于是王差派犹底去把书卷拿来；犹底就从书记以利沙玛的房间里把书卷取来，向王和所有侍立在王左右的领袖宣读。'),
('CNV', '耶利米书', 24, 36, 22, '那时正是九月，王坐在冬宫里，在他面前有一盆炭火烧着。'),
('CNV', '耶利米书', 24, 36, 23, '每逢犹底宣读完三四段，王就用书记的小刀把书割破，丢进盆中的火里，直到全卷都在盆中的火里烧尽了。'),
('CNV', '耶利米书', 24, 36, 24, '王和他所有听见这一切话的臣仆，都不惊惧，也不撕裂衣服。'),
('CNV', '耶利米书', 24, 36, 25, '虽然以利拿单、第莱雅和基玛利雅恳求王不要烧这书卷，王却不听他们，'),
('CNV', '耶利米书', 24, 36, 26, '更吩咐王子耶拉篾、亚次列的儿子西莱雅和亚伯叠的儿子示利米雅，去捉拿文士巴录和耶利米先知；但主把他们隐藏起来。'),
('CNV', '耶利米书', 24, 36, 27, '王烧了那载有巴录从耶利米口中录下的话的书卷以后，主的话又临到耶利米，说：'),
('CNV', '耶利米书', 24, 36, 28, '“你再取一书卷来，把犹大王约雅敬烧掉的前一书卷里原来的一切话，都写在书卷上面。'),
('CNV', '耶利米书', 24, 36, 29, '论到犹大王约雅敬你要说：‘主这样说：你烧了那书卷，说：你为什么在上面写着说：巴比伦王一定来，毁灭这地，使地上的人畜都灭绝呢？'),
('CNV', '耶利米书', 24, 36, 30, '因此，主论到犹大王约雅敬这样说：他的后代必没有人坐在大卫的王位上；他的尸体必抛弃在外，日间受炎热，夜间受寒霜。'),
('CNV', '耶利米书', 24, 36, 31, '我必惩罚他和他的后裔，以及他臣仆的罪孽；我必使我对他们预告过的一切灾祸，临到他们和耶路撒冷的居民，以及犹大人的身上；他们却不听从。’”'),
('CNV', '耶利米书', 24, 36, 32, '于是耶利米取了另一卷书卷，交给尼利亚的儿子文士巴录；巴录就从耶利米的口中，把犹大王约雅敬在火中烧掉的那书上的一切话，都写在书卷上，还加上很多类似的话。'),
('CNV', '耶利米书', 24, 37, 1, '约西亚的儿子西底家代替约雅敬的儿子哥尼雅作王；西底家是巴比伦王尼布甲尼撒所立在犹大地作王的。'),
('CNV', '耶利米书', 24, 37, 2, '西底家和他的臣仆，以及那地的人民，都不听从主藉耶利米先知所传的话。'),
('CNV', '耶利米书', 24, 37, 3, '西底家王差派示利米雅的儿子犹甲和玛西雅祭司的儿子西番雅，去见耶利米先知，说：“请你为我们向主我们的神祷告。”'),
('CNV', '耶利米书', 24, 37, 4, '那时，耶利米还可以在民众中间自由行动，因为他们还没有把他关进监狱里。'),
('CNV', '耶利米书', 24, 37, 5, '法老的军队已经从埃及出来；那些围困耶路撒冷的迦勒底人听见了他们的风声，就从耶路撒冷撤退了。'),
('CNV', '耶利米书', 24, 37, 6, '那时，主的话临到耶利米先知，'),
('CNV', '耶利米书', 24, 37, 7, '“主以色列的神这样说：你们要对差派你们来求问我的犹大王这样说：‘看哪！那出来帮助你们的法老的军队，必回到他们的埃及本地去。'),
('CNV', '耶利米书', 24, 37, 8, '迦勒底人必回来，攻击这城，占领这城，放火烧毁这城。’'),
('CNV', '耶利米书', 24, 37, 9, '主这样说：你们不要自己欺骗自己，说：‘迦勒底人必定离开我们！’因为他们必不离开。'),
('CNV', '耶利米书', 24, 37, 10, '即使你们击败了那攻打你们的迦勒底全军，他们中间只剩下一些受重伤的人，他们也必各从自己的帐棚里起来，放火烧毁这城。’”'),
('CNV', '耶利米书', 24, 37, 11, '迦勒底人的军队因惧怕法老的军队而从耶路撒冷撤退的时候，'),
('CNV', '耶利米书', 24, 37, 12, '耶利米离开耶路撒冷，往便雅悯地去，要在那里，在同乡中间，取得自己的产业。'),
('CNV', '耶利米书', 24, 37, 13, '他到了便雅悯门，那里有一个守卫的长官，名叫伊利雅，是哈拿尼雅的孙子、示利米雅的儿子；他拿住耶利米先知，说：“你想去投降迦勒底人！”'),
('CNV', '耶利米书', 24, 37, 14, '耶利米说：“这是谎话！我并不是去投降迦勒底人。”但伊利雅不听他，仍拿住他，把他带到众领袖那里。'),
('CNV', '耶利米书', 24, 37, 15, '众领袖都恼怒耶利米，就打他，并且把他关进监里，就是在书记约拿单的房子里，因为他们已把这房子改作监狱。'),
('CNV', '耶利米书', 24, 37, 16, '耶利米进了地牢里的一个囚房，在那里监禁了多日。'),
('CNV', '耶利米书', 24, 37, 17, '后来，西底家王派人去把他带出来；王在自己的宫中私下问他，说：“从主那里有话来吗？”耶利米回答：“有！”又说：“你必交在巴比伦王的手中。”'),
('CNV', '耶利米书', 24, 37, 18, '耶利米再对西底家王说：“我有什么得罪你，或你的臣仆，或这人民，你竟然把我送进监狱里呢？'),
('CNV', '耶利米书', 24, 37, 19, '你们的先知曾向你们预言说：‘巴比伦王必不会来攻击你们和这地。’他们现今在哪里呢？'),
('CNV', '耶利米书', 24, 37, 20, '我主我王啊！现在求你垂听，求你容我向你恳求！不要把我送回书记约拿单的房子去，免得我死在那里。”'),
('CNV', '耶利米书', 24, 37, 21, '于是西底家王下令，把耶利米拘留在卫兵的院子里；他们每天从饼铺街拿一个饼给他，直到城里的饼都吃光了。耶利米就这样留在卫兵的院子里。'),
('CNV', '耶利米书', 24, 38, 1, '玛坦的儿子示法提雅、巴施户珥的儿子基大利、示利米雅的儿子犹甲、玛基雅的儿子示巴户珥，听见耶利米对众民宣讲以下的话：'),
('CNV', '耶利米书', 24, 38, 2, '“主这样说：‘凡留在这城里的，必因刀剑、饥荒、瘟疫而死；但出去向迦勒底人投降的，必可以活着；他们必捡回自己的性命，得以生存。’'),
('CNV', '耶利米书', 24, 38, 3, '主这样说：‘这城必交在巴比伦王军队的手中，巴比伦王必攻取这城。’”'),
('CNV', '耶利米书', 24, 38, 4, '于是众领袖对王说：“这人应该处死，因为他向这城里剩下的军兵和众民说了这样的话，使他们的手都软弱无力。这人不是为这人民求平安，却是惹来灾祸的。”'),
('CNV', '耶利米书', 24, 38, 5, '西底家王说：“看哪！他在你们手中；王不能作什么反对你们。”'),
('CNV', '耶利米书', 24, 38, 6, '他们就拿住耶利米，把他丢在王子玛基雅的井里，那井是在卫兵的院子里的；他们用绳子把耶利米缒下去。井里没有水，只有淤泥；耶利米就陷在淤泥中。'),
('CNV', '耶利米书', 24, 38, 7, '宫中的臣宰古实人以伯．米勒，在王宫里听见他们把耶利米关在井里的消息（那时，王正在便雅悯门坐着），'),
('CNV', '耶利米书', 24, 38, 8, '以伯．米勒就从王宫里出来，禀告王说：'),
('CNV', '耶利米书', 24, 38, 9, '“我主我王啊！这些人对耶利米先知所作的一切真是恶毒，他们把他丢在井里；在那地方他必饿死，因为城里再没有粮食了。”'),
('CNV', '耶利米书', 24, 38, 10, '于是王吩咐古实人以伯．米勒说：“你从这里带三十个人，在耶利米先知未死以前，把他从井里拉上来。”'),
('CNV', '耶利米书', 24, 38, 11, '以伯．米勒就带人进王宫去，到储物室下面的一个房间，从那里取了些破布烂衣，用绳子缒下井里给耶利米。'),
('CNV', '耶利米书', 24, 38, 12, '古实人以伯．米勒对耶利米说：“把这些破布烂衣垫在你的腋下，然后束上绳子。”耶利米就这样作了。'),
('CNV', '耶利米书', 24, 38, 13, '于是他们用绳子把耶利米从井里拉出来；这样，耶利米可以住在卫兵的院子里。'),
('CNV', '耶利米书', 24, 38, 14, '后来，西底家王派人去把耶利米先知带到主殿中的第三道门那里去见他。王对耶利米说：“我要问你一件事，你什么都不可以向我隐瞒。”'),
('CNV', '耶利米书', 24, 38, 15, '耶利米对西底家说：“我若告诉你，你不是要杀死我吗？我若向你建议，你必不听从我。”'),
('CNV', '耶利米书', 24, 38, 16, '于是西底家王私下向耶利米起誓，说：“我指着那创造我们生命的永活的主起誓：我决不杀死你，也不把你交在这些寻索你性命的人的手里。”'),
('CNV', '耶利米书', 24, 38, 17, '耶利米对西底家说：“主万军的神、以色列的神这样说：‘你若出去归降巴比伦王的将领，你的性命就可以存活；这城也不会被火焚烧，你和你一家都可以存活。'),
('CNV', '耶利米书', 24, 38, 18, '但你若不出去归降巴比伦王的将领，这城就必交在迦勒底人的手中；他们必放火烧毁这城，你自己也不能从他们的手里逃脱。’”'),
('CNV', '耶利米书', 24, 38, 19, '西底家王对耶利米说：“我害怕那些已向迦勒底人投降的犹大人，恐怕迦勒底人把我交在他们手中，他们就会凌辱我。”'),
('CNV', '耶利米书', 24, 38, 20, '耶利米说：“迦勒底人必不会把你交给他们。求你听从我对你所说的主的话；这样，你就可以平安无事，你的性命也可以存活。'),
('CNV', '耶利米书', 24, 38, 21, '你若拒绝出去投降，主指示我的话就是这样：'),
('CNV', '耶利米书', 24, 38, 22, '看哪！犹大王宫里所有剩下的妇女，都必被带出来，去到巴比伦王的将领那里。那些妇女必对你说：‘你的盟友煽惑了你，左右了你；现在你的脚陷在泥沼中，他们就都离弃你。’'),
('CNV', '耶利米书', 24, 38, 23, '你所有的后妃和你的儿女，都必被带出来，去到迦勒底人那里；你自己也不能从他们的手里逃脱，因为你必被巴比伦王的手抓住；这城也必被火烧毁（“这城也必被火烧毁”有古抄本作“你必放火烧毁这城”）。”'),
('CNV', '耶利米书', 24, 38, 24, '西底家对耶利米说：“不要给人知道这些话，这样你就不会死。'),
('CNV', '耶利米书', 24, 38, 25, '众领袖若听见了我和你说过话，就会来见你，对你说：‘告诉我们，你对王说了些什么？不可向我们隐瞒，我们就不会杀死你。王又对你说了些什么？’'),
('CNV', '耶利米书', 24, 38, 26, '你就要对他们说：‘我只是把我的恳求呈到王面前，求他不要把我送回约拿单的房子去，免得我死在那里。’”'),
('CNV', '耶利米书', 24, 38, 27, '所有的领袖果然来见耶利米，查问他；他就照着王所吩咐的这一切话告诉他们。于是他们不再追问他，因为王和他说话的内容没有给人听见。'),
('CNV', '耶利米书', 24, 38, 28, '这样，耶利米留在卫兵的院子里，直到耶路撒冷被攻取的那一天。'),
('CNV', '耶利米书', 24, 39, 1, '犹大王西底家第九年十月，巴比伦王尼布甲尼撒率领他的全军来攻击耶路撒冷，把城围困起来。'),
('CNV', '耶利米书', 24, 39, 2, '西底家第十一年四月九日，城被攻破。'),
('CNV', '耶利米书', 24, 39, 3, '巴比伦王所有的将领：尼甲．沙利薛、三甲．尼波、大臣（“大臣”的本意不明确）撒西金、术士长（“术士长”的本意不明确）尼甲．沙利薛，以及巴比伦王所有其余的将领，都进城，坐在中门。'),
('CNV', '耶利米书', 24, 39, 4, '犹大王西底家和所有的军兵看见了他们，就逃跑，在夜间逃出城外，经过王的花园，穿过两道城墙中间的门，直往亚拉巴的路上走去。'),
('CNV', '耶利米书', 24, 39, 5, '但迦勒底人的军队追赶他们，在耶利哥的原野上追上了西底家，把他拿住，带到哈马地的利比拉去见巴比伦王尼布甲尼撒；尼布甲尼撒就宣判他的罪状。'),
('CNV', '耶利米书', 24, 39, 6, '巴比伦王在利比拉，当着西底家眼前杀了他的众子；巴比伦王也杀了犹大所有的显贵，'),
('CNV', '耶利米书', 24, 39, 7, '并且把西底家的眼睛弄瞎了，用铜链锁住他，把他带到巴比伦去。'),
('CNV', '耶利米书', 24, 39, 8, '迦勒底人放火焚烧王宫和民房，又拆毁了耶路撒冷的城墙。'),
('CNV', '耶利米书', 24, 39, 9, '城里剩下的人民，和那些已经向巴比伦王投降的人，以及其余的人民，都被护卫长尼布撒拉旦掳到巴比伦去。'),
('CNV', '耶利米书', 24, 39, 10, '但护卫长尼布撒拉旦把民中一些一无所有的穷人留在犹大地，同时把葡萄园和田地分给他们。'),
('CNV', '耶利米书', 24, 39, 11, '巴比伦王尼布甲尼撒提到耶利米，吩咐护卫长尼布撒拉旦说：'),
('CNV', '耶利米书', 24, 39, 12, '“你把他带去，好好照顾他，切不可伤害他；他对你怎样说，你就给他照办。”'),
('CNV', '耶利米书', 24, 39, 13, '于是护卫长尼布撒拉旦、大臣（“大臣”的本意不明确）尼布沙斯班、术士长（“术士长”的本意不明确）尼甲．沙利薛，以及巴比伦王所有的大臣都派人去，'),
('CNV', '耶利米书', 24, 39, 14, '把耶利米从卫兵的院子里提出来，交给沙番的孙子、亚希甘的儿子基大利，叫他带耶利米回家去。这样，耶利米就住在人民中间。'),
('CNV', '耶利米书', 24, 39, 15, '耶利米还监禁在卫兵的院子里的时候，主的话临到他，说：'),
('CNV', '耶利米书', 24, 39, 16, '“你去告诉古实人以伯．米勒说：‘万军之主以色列的神这样说：看哪！我必在这城实现我的话，降祸不降福；到那日，这一切都必在你面前实现。'),
('CNV', '耶利米书', 24, 39, 17, '但到了那日，我必拯救你；你必不至交在你所惧怕的人手里。’这是主的宣告。'),
('CNV', '耶利米书', 24, 39, 18, '‘因为我必定搭救你；你必不会倒在刀下，必可以捡回自己的性命，因为你信靠我。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 40, 1, '护卫长尼布撒拉旦在拉玛释放了耶利米以后，从主那里有话临到耶利米。耶利米被提出来的时候，还被铁链锁着，在所有从耶路撒冷和犹大被掳到巴比伦去的人中间。'),
('CNV', '耶利米书', 24, 40, 2, '护卫长把耶利米提出来，对他说：“主你的神曾说要降这灾祸在这地方；'),
('CNV', '耶利米书', 24, 40, 3, '现在主使灾祸临到，照他所说的行了；因为你们得罪了主，没有听从他的话，所以这事才临到你们。'),
('CNV', '耶利米书', 24, 40, 4, '我现在解开你手上的铁链。你若认为与我一同到巴比伦去好，就一起去，我必好好照顾你；你若认为与我一同到巴比伦去不好，就不必去。看，全地都在你面前，你认为去哪里好、哪里合宜，就到哪里去吧！”'),
('CNV', '耶利米书', 24, 40, 5, '耶利米还没有回去，护卫长又说：“你可以回到沙番的孙子、亚希甘的儿子基大利那里去！基大利是巴比伦王指派管理犹大各城的。你可以和他一起住在人民中间；或是你认为去哪里合宜，就到哪里去吧！”于是护卫长给他粮食和礼物，就释放他走了。'),
('CNV', '耶利米书', 24, 40, 6, '耶利米就到米斯巴去见亚希甘的儿子基大利，和他一同住在那地剩下的人民中间。'),
('CNV', '耶利米书', 24, 40, 7, '在田野的众将领和他们的士兵，听见巴比伦王委派了亚希甘的儿子基大利管理那地，也委派他管理那些没有被掳到巴比伦去的男人、妇女、孩童，和那地最贫穷的人，'),
('CNV', '耶利米书', 24, 40, 8, '他们就来到米斯巴去见基大利；其中有尼探雅的儿子以实玛利、加利亚的两个儿子约哈难和约拿单、单户篾的儿子西莱雅、尼陀法人以斐的众子，和玛迦人的儿子耶撒尼亚，以及他们的士兵。'),
('CNV', '耶利米书', 24, 40, 9, '沙番的孙子、亚希甘的儿子基大利向他们和他们的士兵起誓，说：“你们不要惧怕服事迦勒底人，只管住在这地，服事巴比伦王，就可以平安无事。'),
('CNV', '耶利米书', 24, 40, 10, '至于我，我要留在米斯巴，侍候那些来到我们这里的迦勒底人。你们只管收存酒、夏天的果子和油，放在器皿里，并且住在你们所占有的城中。”'),
('CNV', '耶利米书', 24, 40, 11, '那些在摩押、亚扪、以东和各地所有的犹大人，听见了巴比伦王在犹大留下一些余民，并且指派沙番的孙子、亚希甘的儿子基大利管理他们，'),
('CNV', '耶利米书', 24, 40, 12, '所有的犹大人就从被赶逐到的各地方回来，到犹大地的米斯巴去见基大利，并且收存了许多的酒和夏天的果子。'),
('CNV', '耶利米书', 24, 40, 13, '加利亚的儿子约哈难和在田野的众将领，都到米斯巴去见基大利，'),
('CNV', '耶利米书', 24, 40, 14, '对他说：“亚扪王巴利斯派尼探雅的儿子以实玛利来杀你，你知道吗？”亚希甘的儿子基大利不相信他们。'),
('CNV', '耶利米书', 24, 40, 15, '后来加利亚的儿子约哈难在米斯巴私下告诉基大利说：“请容我去把尼探雅的儿子以实玛利杀了，必没有人知道；为什么要让他杀你，以致集合到你那里来的所有犹大人都分散，犹大余剩的人都灭亡呢？”'),
('CNV', '耶利米书', 24, 40, 16, '但亚希甘的儿子基大利对加利亚的儿子约哈难说：“你不可作这事，因为你所说关于以实玛利的事都是谎话！”'),
('CNV', '耶利米书', 24, 41, 1, '但在七月的时候，王裔以利沙玛的孙子、尼探雅的儿子以实玛利，也是王的一位大臣，带了十个人和他一起到米斯巴去见亚希甘的儿子基大利；他们在米斯巴一起吃饭的时候，'),
('CNV', '耶利米书', 24, 41, 2, '尼探雅的儿子以实玛利和与他一起的那十个人就起来，用刀袭击沙番的孙子、亚希甘的儿子基大利，就是巴比伦王指派管理那地的，把他杀掉。'),
('CNV', '耶利米书', 24, 41, 3, '以实玛利也击杀了所有在米斯巴和基大利一起的犹大人，以及在那里所遇见的迦勒底军兵。'),
('CNV', '耶利米书', 24, 41, 4, '他杀了基大利以后，没有人知道；第二天，'),
('CNV', '耶利米书', 24, 41, 5, '有八十个人从示剑、示罗和撒玛利亚前来，胡须剃去，衣服撕裂，身体割破，手里拿着素祭和乳香，要带到主的殿里去。'),
('CNV', '耶利米书', 24, 41, 6, '尼探雅的儿子以实玛利从米斯巴出来迎接他们，边走边哭，遇见了他们，就对他们说：“请你们来见亚希甘的儿子基大利！”'),
('CNV', '耶利米书', 24, 41, 7, '他们到了城中，尼探雅的儿子以实玛利和与他一起的人，就把他们杀了，扔在坑里。'),
('CNV', '耶利米书', 24, 41, 8, '只是他们中间有十个人却对以实玛利说：“请不要杀死我们！因为我们有许多小麦、大麦、油和蜜，埋藏在田间。”他就住了手，没有把这十个人在他们的兄弟中一同杀死。'),
('CNV', '耶利米书', 24, 41, 9, '以实玛利把他和基大利所击杀的人的尸体全部扔在坑里（本句原文意思不确定）；这坑是从前亚撒王为了防御以色列王巴沙而挖掘的。尼探雅的儿子以实玛利用那些被杀的人的尸体填满了那坑。'),
('CNV', '耶利米书', 24, 41, 10, '以实玛利还掳去所有留在米斯巴的余民，包括王的众公主和所有留在米斯巴的人民；这些人都是护卫长尼布撒拉旦交给亚希甘的儿子基大利管理的。尼探雅的儿子以实玛利把他们掳走，往亚扪那里去。'),
('CNV', '耶利米书', 24, 41, 11, '加利亚的儿子约哈难和与他一起的众将领，听见了尼探雅的儿子以实玛利所行的一切恶事，'),
('CNV', '耶利米书', 24, 41, 12, '就率领所有的人，去攻打尼探雅的儿子以实玛利，在基遍的大水池边追上他。'),
('CNV', '耶利米书', 24, 41, 13, '在以实玛利那里的众民，看见了加利亚的儿子约哈难和与他一起的众将领，就都欢喜。'),
('CNV', '耶利米书', 24, 41, 14, '于是以实玛利从米斯巴掳去的众民都转身，归到加利亚的儿子约哈难那里。'),
('CNV', '耶利米书', 24, 41, 15, '尼探雅的儿子以实玛利带着八个人逃脱了约哈难的手，到亚扪那里去。'),
('CNV', '耶利米书', 24, 41, 16, '加利亚的儿子约哈难和与他一起的众将领，就夺回了全部余民，包括军兵、妇女、孩童和宫中的臣宰，就是尼探雅的儿子以实玛利在刺杀亚希甘的儿子基大利以后，从米斯巴掳走的。约哈难把这些人都从基遍带回来。'),
('CNV', '耶利米书', 24, 41, 17, '他们去到伯利恒附近的基罗特金罕，停留在那里，想要往埃及去，'),
('CNV', '耶利米书', 24, 41, 18, '躲避迦勒底人。他们惧怕迦勒底人，因为尼探雅的儿子以实玛利杀了巴比伦王指派管理那地的亚希甘的儿子基大利。'),
('CNV', '耶利米书', 24, 42, 1, '所有的将领，包括加利亚的儿子约哈难和何沙雅的儿子耶撒尼亚，以及全体人民，从最小的到最大的，都上前来，'),
('CNV', '耶利米书', 24, 42, 2, '对耶利米先知说：“求你容我们向你恳求，请为我们这余剩的民向主你的神祷告；因为我们从前人数众多，现在剩下的极少，就像你现在亲眼所见的一样。'),
('CNV', '耶利米书', 24, 42, 3, '请为我们求主你的神指示我们当走的路和该作的事。”'),
('CNV', '耶利米书', 24, 42, 4, '耶利米先知对他们说：“我听见了！我必照着你们的话祷告主你们的神。主回答你们所说的一切话，我必告诉你们，一句也不会向你们隐瞒。”'),
('CNV', '耶利米书', 24, 42, 5, '于是他们对耶利米说：“我们若不照着主你的神差遣你到我们这里来所说的一切话去作，愿主作真实和诚信的见证，指控我们。'),
('CNV', '耶利米书', 24, 42, 6, '不论是甜是苦，我们都愿听从主我们神的话，因为是我们委派你向他祈求的；我们听从主我们神的话，就必凡事亨通。”'),
('CNV', '耶利米书', 24, 42, 7, '过了十天，主的话临到耶利米。'),
('CNV', '耶利米书', 24, 42, 8, '耶利米就把加利亚的儿子约哈难，和所有与他一起的将领，以及全体人民，从最小的到最大的，都叫了来，'),
('CNV', '耶利米书', 24, 42, 9, '对他们说：“主以色列的神，就是你们委派我去为你们向他恳求的那位，这样说：'),
('CNV', '耶利米书', 24, 42, 10, '‘你们若决意住在这地，我就建立你们，必不拆毁；栽植你们，必不拔除；因我为那已经降在你们身上的灾祸回心转意。'),
('CNV', '耶利米书', 24, 42, 11, '你们所怕的巴比伦王，你们不要惧怕他；你们不要惧怕他（这是主的宣告），因为我与你们同在，要拯救你们，要搭救你们脱离他的手。'),
('CNV', '耶利米书', 24, 42, 12, '我要向你们施怜悯，他也会怜悯你们，使你们归回自己的土地。’'),
('CNV', '耶利米书', 24, 42, 13, '但是，你们若说：‘我们不住在这地’，不听从主你们的神的话，'),
('CNV', '耶利米书', 24, 42, 14, '或说：‘不！我们要去埃及地，在那里看不到战争，听不见号角的声音，也不会因缺乏粮食而饥饿；我们要留在那里。’'),
('CNV', '耶利米书', 24, 42, 15, '这样，犹大余剩的人哪，你们现在要听主的话！万军之主以色列的神这样说：‘你们若决意去埃及，到那里寄居，'),
('CNV', '耶利米书', 24, 42, 16, '你们惧怕的刀剑必在埃及地追上你们；你们恐惧的饥荒必在埃及紧随着你们；你们必死在那里。'),
('CNV', '耶利米书', 24, 42, 17, '所有决意去埃及，在那里寄居的人，必因刀剑、饥荒和瘟疫而死；他们没有一人能幸存，或避过我降在他们身上的灾祸。’'),
('CNV', '耶利米书', 24, 42, 18, '“因为万军之主以色列的神这样说：‘我从前怎样把我的怒气和烈怒倾倒在耶路撒冷的居民身上，现在你们进入埃及的时候，我也必照样把我的烈怒倾倒在你们身上。你们就必成为令人惊骇、被人咒骂、咒诅和羞辱的对象。你们必不能再看见这地方。'),
('CNV', '耶利米书', 24, 42, 19, '犹大余剩的人哪，主曾对你们说：‘你们不要去埃及。’你们要确实知道，我今天已经警告你们了。'),
('CNV', '耶利米书', 24, 42, 20, '你们实在自己欺骗自己，因为是你们委派我去见主你们的神，你们说：‘请为我们向主我们的神祷告；无论主我们的神说什么，你都要告诉我们，我们就必照着去作。’'),
('CNV', '耶利米书', 24, 42, 21, '我今天告诉了你们，你们却不听从主你们的神派我来告诉你们的一切话。'),
('CNV', '耶利米书', 24, 42, 22, '现在你们要确实知道，在你们想去寄居的那地方，你们必因刀剑、饥荒和瘟疫而死。”'),
('CNV', '耶利米书', 24, 43, 1, '耶利米向众民说完了主他们的神吩咐他的一切话，就是主他们的神差遣他去对他们说的一切话。'),
('CNV', '耶利米书', 24, 43, 2, '何沙雅的儿子亚撒利雅，和加利亚的儿子约哈难，以及所有狂傲的人，就对耶利米说：“你在说谎！主我们的神并没有差遣你来说：‘你们不可去埃及，在那里寄居。’'),
('CNV', '耶利米书', 24, 43, 3, '只是尼利亚的儿子巴录怂恿你来反对我们，为要把我们交在迦勒底人的手中，好使我们被杀害，或被掳到巴比伦去。”'),
('CNV', '耶利米书', 24, 43, 4, '于是加利亚的儿子约哈难和众将领，以及众民，都不听从主要他们留在犹大地的命令。'),
('CNV', '耶利米书', 24, 43, 5, '相反地，加利亚的儿子约哈难和众将领却率领犹大所有余剩的人，就是那些从被赶逐到各国回来住在犹大地的，'),
('CNV', '耶利米书', 24, 43, 6, '包括男人、女人、孩童和王的众公主，以及护卫长尼布撒拉旦留给沙番的孙子、亚希甘的儿子基大利管理的众人，还有耶利米先知和尼利亚的儿子巴录，'),
('CNV', '耶利米书', 24, 43, 7, '把他们都带进埃及地，去到答比匿，没有听从主的话。'),
('CNV', '耶利米书', 24, 43, 8, '在答比匿主的话临到耶利米，说：'),
('CNV', '耶利米书', 24, 43, 9, '“你要在犹大人眼前亲手拿几块大石头，埋藏在答比匿法老宫殿门前砖窑的灰泥中；'),
('CNV', '耶利米书', 24, 43, 10, '然后对他们说：‘万军之主以色列的神这样说：看哪！我要派人去领我的仆人巴比伦王尼布甲尼撒来；我要在我所埋藏的这些石头上安设他的王位；他必在上面张开他的帐篷。'),
('CNV', '耶利米书', 24, 43, 11, '他必来攻打埃及地；那些注定死亡的，必要死亡；那些注定被掳的，必要被掳；那些注定被刀杀的，必被刀杀。'),
('CNV', '耶利米书', 24, 43, 12, '他（按照《马索拉文本》，“他”应作“我”；现参照《七十士译本》翻译）必焚烧埃及的神庙，把它们烧毁，并且掳掠；他必得着埃及地，好像牧人披上衣服那么容易；他必安然离开那里。'),
('CNV', '耶利米书', 24, 43, 13, '他必打碎埃及地伯．示麦（“伯‧示麦”或译：“太阳神庙”）的神柱，放火烧毁埃及神庙。’”'),
('CNV', '耶利米书', 24, 44, 1, '以下的话临到耶利米，论到所有住在埃及地的犹大人，就是那些住在密夺、答比匿、挪弗和巴忒罗地的人，说：'),
('CNV', '耶利米书', 24, 44, 2, '“万军之主以色列的神这样说：‘你们都亲眼看见我降在耶路撒冷和犹大各城的一切灾祸。看哪！那些城镇今天仍然荒凉，没有人居住，'),
('CNV', '耶利米书', 24, 44, 3, '这是因为他们所行的恶事的缘故；他们向别神烧香，事奉它们，惹我发怒。这些神是他们和你们，以及你们的列祖所不认识的。'),
('CNV', '耶利米书', 24, 44, 4, '虽然我不断差遣我的仆人众先知到你们那里去，说：你们千万不可行我所恨恶，这可憎的事！'),
('CNV', '耶利米书', 24, 44, 5, '他们却不听从，毫不留心，不肯离开他们的恶行，仍向别神烧香。'),
('CNV', '耶利米书', 24, 44, 6, '因此，我必倾出我的烈怒和怒气，在犹大的各城镇和耶路撒冷的街上烧起，以致它们都荒凉废弃，像今天一样。’'),
('CNV', '耶利米书', 24, 44, 7, '现在，主万军的神以色列的神这样说：‘你们为什么自己招来这样的大灾祸，使你们的男人、女人、孩童和婴儿都从犹大中除灭，一个余剩的人也不留下呢？'),
('CNV', '耶利米书', 24, 44, 8, '为什么因你们手所作的，在你们来寄居的埃及地向别神烧香，惹我发怒，以致你们被除灭，成为地上万国咒诅和羞辱的对象呢？'),
('CNV', '耶利米书', 24, 44, 9, '你们列祖的恶行、犹大列王的恶行、他们妻子的恶行、你们自己的恶行和你们妻子的恶行，就是在犹大地和耶路撒冷街上所行的，你们忘记了吗？'),
('CNV', '耶利米书', 24, 44, 10, '直到今日，他们还没有痛悔，没有畏惧，也没有遵行我在你们和你们列祖面前所立的律法和条例。’'),
('CNV', '耶利米书', 24, 44, 11, '“因此万军之主以色列的神这样说：‘看哪！我决意向你们降下灾祸，把全犹大都除灭。'),
('CNV', '耶利米书', 24, 44, 12, '那些决意去埃及地，在那里寄居的犹大余剩的人，我必把他们除去；他们必在埃及地灭绝；他们必倒在刀下，必因饥荒灭亡；他们从最小的到最大的都必因刀剑和饥荒而死，以致成了令人惊骇、被人咒骂、咒诅和羞辱的对象。'),
('CNV', '耶利米书', 24, 44, 13, '我必用刀剑、饥荒和瘟疫惩罚那些住在埃及地的人，好像惩罚耶路撒冷一样。'),
('CNV', '耶利米书', 24, 44, 14, '那些去埃及地，在那里寄居的犹大余剩的人，必不能逃脱，不能幸存，不能返回他们心里渴望回去居住的犹大地；除了一些逃脱了的人以外，一个都不能返回。’”'),
('CNV', '耶利米书', 24, 44, 15, '那些知道自己的妻子曾向别神烧香的众人，和一大群站在那里的妇女，以及住在埃及地巴忒罗的众民，回答耶利米说：'),
('CNV', '耶利米书', 24, 44, 16, '“你奉主的名对我们所说的话，我们不听从。'),
('CNV', '耶利米书', 24, 44, 17, '我们口中说过的一切话，我们一定去作，我们要向天后烧香，浇奠祭，好像我们自己和我们的列祖，以及我们的君王和领袖，在犹大的各城和耶路撒冷的街上所行的一样。那时我们吃得饱，得享福乐，不见灾祸。'),
('CNV', '耶利米书', 24, 44, 18, '但是，自从我们停止向天后烧香和浇奠祭以后，我们就样样都缺乏，又因刀剑和饥荒灭亡。”'),
('CNV', '耶利米书', 24, 44, 19, '那些妇女又说：“我们不错是向天后烧香和浇奠祭，难道我们的丈夫不知道我们照着天后的形象制饼供奉她，向她浇奠祭吗？”'),
('CNV', '耶利米书', 24, 44, 20, '耶利米对全体人民，对那些用这话答覆他的男人、女人和众民说：'),
('CNV', '耶利米书', 24, 44, 21, '“你们和你们的列祖，以及你们的君王、领袖，和全国的人民，在犹大的各城和耶路撒冷的街上烧的香，主怎能忘记，他心里怎能不想起呢？'),
('CNV', '耶利米书', 24, 44, 22, '主再不能容忍你们邪恶的行为，和你们所行可憎的事；故此，你们的土地荒凉，成了令人惊骇、被人咒诅的对象，没有人居住，好像今天一样。'),
('CNV', '耶利米书', 24, 44, 23, '因为你们向别神烧香，得罪了主，不听从主的话，不遵行他的律法、条例和法度，所以这灾祸临到你们，好像今天一样。”'),
('CNV', '耶利米书', 24, 44, 24, '耶利米又对众民和众妇女说：“在埃及地所有的犹大人哪，要听主的话！'),
('CNV', '耶利米书', 24, 44, 25, '万军之主以色列的神这样说：‘你们和你们的妻子亲口说过：我们一定要实行我们的愿，向天后烧香，浇奠祭。你们果然亲手作了。现在你们只管持定你们所许的愿，只管实行你们的誓言吧！’'),
('CNV', '耶利米书', 24, 44, 26, '但所有住在埃及地的犹大人哪，你们要听主的话！主说：‘看哪！我指着我伟大的名起誓：在埃及全地每一个犹大人的口中，再不会呼唤我的名，说：我指着永活的主神起誓。'),
('CNV', '耶利米书', 24, 44, 27, '看哪！我要留意向他们降祸不降福；在埃及地所有的犹大人都必因刀剑和饥荒灭亡，直到灭绝。'),
('CNV', '耶利米书', 24, 44, 28, '那些逃脱刀剑的，必从埃及地返回犹大地；他们人数很少。这样，所有去埃及地在那里寄居的犹大余剩的人，就知道谁的话实现：我的，还是他们的。'),
('CNV', '耶利米书', 24, 44, 29, '“‘我要在这地方惩罚你们，这是给你们的征兆，好使你们知道我说要降祸给你们的话，一定实现。’这是主的宣告。'),
('CNV', '耶利米书', 24, 44, 30, '主这样说：‘看哪！我必把埃及王法老合弗拉交在他仇敌的手中，和那些寻索他性命的人的手中，像我把犹大王西底家交在他仇敌，那寻索他性命的巴比伦王尼布甲尼撒的手中一样。’”'),
('CNV', '耶利米书', 24, 45, 1, '以下是犹大王约西亚的儿子约雅敬第四年，耶利米先知对尼利亚的儿子巴录所说的话（巴录从耶利米口中把这些话写在书卷上）：'),
('CNV', '耶利米书', 24, 45, 2, '“巴录啊！主以色列的神这样说：'),
('CNV', '耶利米书', 24, 45, 3, '‘你曾说：我有祸了！因为主在我的痛苦上加添忧愁。我因唉哼而困乏，得不着安宁。’”'),
('CNV', '耶利米书', 24, 45, 4, '主对耶利米说：“你要这样对他说：‘主这样说：看哪！我所建立的，我必拆毁；我所栽种的，我必拔除。我必这样对待全地。'),
('CNV', '耶利米书', 24, 45, 5, '你要为自己图谋大事吗？不要图谋！看哪！我必使灾祸降在全人类身上，但无论你到什么地方去，我必使你捡回自己的性命。’”这是主的宣告。'),
('CNV', '耶利米书', 24, 46, 1, '主论到列国的话临到耶利米先知。'),
('CNV', '耶利米书', 24, 46, 2, '以下的话是关于埃及，论到埃及王法老尼哥的军队，这军队在犹大王约西亚的儿子约雅敬第四年，被巴比伦王尼布甲尼撒在靠近幼发拉底河的迦基米施击败。'),
('CNV', '耶利米书', 24, 46, 3, '“要准备好大小的盾牌，踏上战场。'),
('CNV', '耶利米书', 24, 46, 4, '要装备马匹，骑上战马；站好岗位，戴上头盔；磨快枪矛，穿上铁甲。'),
('CNV', '耶利米书', 24, 46, 5, '但为什么我看见他们惊惶，转身退后呢？他们的勇士被击败了，他们急速奔逃，不敢回转。四围都是惊慌。”这是主的宣告。'),
('CNV', '耶利米书', 24, 46, 6, '“快跑的跑不掉，勇士也不能逃脱；他们在北方、在幼发拉底河边，都绊跌仆倒。'),
('CNV', '耶利米书', 24, 46, 7, '那像尼罗河上涨，像江河的水翻腾的是谁呢？'),
('CNV', '耶利米书', 24, 46, 8, '埃及像尼罗河上涨，像江河的水翻腾；它说：‘我要上涨，淹盖大地；我要毁灭城镇和城里的居民。’'),
('CNV', '耶利米书', 24, 46, 9, '马匹啊，上前吧！战车啊，狂奔吧！勇士啊，就是紧握盾牌的古实人和弗人，以及拉弓的吕底亚人哪，上阵吧！'),
('CNV', '耶利米书', 24, 46, 10, '那是主万军之主的日子，是报仇的日子，他要向自己的敌人报仇；刀剑必吞噬、饱餐他们的肉，痛饮他们的血。因为在北方，靠近幼发拉底河之地，主万军之主要屠宰敌人像杀祭牲一样。'),
('CNV', '耶利米书', 24, 46, 11, '埃及的人民哪，上基列去取乳香吧！你虽多用药物都是无效，你必不得医治。'),
('CNV', '耶利米书', 24, 46, 12, '列国听见你的羞耻，大地满了你的哀号；因为勇士和勇士相碰，双方一同仆倒。”'),
('CNV', '耶利米书', 24, 46, 13, '以下是主对耶利米先知所说的话，论到巴比伦王尼布甲尼撒要来攻打埃及地。'),
('CNV', '耶利米书', 24, 46, 14, '“你们要在埃及传扬，在密夺宣告，在挪弗和答比匿宣扬，说：‘要站好岗位，作好准备，因为刀剑要吞灭你周围的人！’'),
('CNV', '耶利米书', 24, 46, 15, '你的壮士为什么俯伏？他们站立不住（“你的壮士为什么俯伏？他们站立不住”或可参照《七十士译本》译作“为什么亚比士神逃跑？你的牛神站立不住”），是因主把他们推倒了。'),
('CNV', '耶利米书', 24, 46, 16, '他使众人绊跌，倒在一起；他们说：‘起来！我们要回到我们本族，和我们出生之地那里去，躲避欺压者的刀剑。’'),
('CNV', '耶利米书', 24, 46, 17, '他们在那里喊叫：‘埃及王法老不过是喧哗的声音；他已失去机会。’”'),
('CNV', '耶利米书', 24, 46, 18, '名叫万军之主的王宣告说：“我指着我的永生起誓，必有一位要来，像群山中的他泊山，像海边的迦密山一样。'),
('CNV', '耶利米书', 24, 46, 19, '住在埃及的人民哪！要为自己预备被掳时所需的器物；因为挪弗必成为荒场，必被烧毁，无人居住。'),
('CNV', '耶利米书', 24, 46, 20, '埃及是一头肥美的母牛犊，但北方的牛虫已经来到它身上（“它身上”有古卷作“来到了”）。'),
('CNV', '耶利米书', 24, 46, 21, '它中间的雇佣兵像棚里的肥牛犊，他们一同转身逃跑，没有一个站立得住；因为他们遭灾的日子、受惩罚的时候，已经临到他们身上。'),
('CNV', '耶利米书', 24, 46, 22, '它逃走的声音像蛇行的响声，因为敌人要成队而来，像砍伐树木的，拿着斧子前来攻击它。'),
('CNV', '耶利米书', 24, 46, 23, '他们要砍伐它的森林。这是主的宣告；它的森林虽然茂密难以通过，但敌人比蝗虫还多，无法数算。'),
('CNV', '耶利米书', 24, 46, 24, '埃及的人民必蒙羞受辱，必交在北方的民族的手中。”'),
('CNV', '耶利米书', 24, 46, 25, '万军之主以色列的神说：“看哪！我必惩罚挪的亚扪神、法老和那些倚靠法老的人。'),
('CNV', '耶利米书', 24, 46, 26, '我必把他们交在那些寻索他们性命的人的手里，就是交在巴比伦王尼布甲尼撒和他的臣仆的手中。但以后，埃及必再有人居住，像从前一样。”这是主的宣告。'),
('CNV', '耶利米书', 24, 46, 27, '“至于你，我的仆人雅各啊！你不要惧怕。以色列啊！你不要惊慌。因为我必从远方拯救你回来，从被掳之地必拯救你的后裔脱离他们被掳之地。雅各必归回，得享平静安逸，没有人可以使他害怕。'),
('CNV', '耶利米书', 24, 46, 28, '我的仆人雅各啊！你不要惧怕。因为我与你同在；我要消灭我赶逐你去的列国。却必不消灭你。我要按公正惩治你，决不能免你受罚。”这是主的宣告。'),
('CNV', '耶利米书', 24, 47, 1, '在法老攻击迦萨以先，主论到非利士人的话临到耶利米先知。'),
('CNV', '耶利米书', 24, 47, 2, '主这样说：“看哪！有水从北方涨起，成为一股泛滥的洪流，淹没大地和地上的一切，淹没城镇和住在城中的居民。人必呼喊，地上所有的居民必哀号。'),
('CNV', '耶利米书', 24, 47, 3, '因为听见战马的蹄声，还有战车辚辚和车轮辘辘的响声，作父亲的双手酸软无力，不能照顾他们的儿女。'),
('CNV', '耶利米书', 24, 47, 4, '日子将到，非利士人必全遭毁灭，所有曾援助推罗和西顿仍然幸存的人必被剪除，因为主要毁灭非利士人，就是迦斐托岛余剩的人。'),
('CNV', '耶利米书', 24, 47, 5, '迦萨成了秃头的，亚实基伦静默无声（“静默无声”或译：“被毁坏了”），在它们的平原上（“在它们的平原上”或参照《七十士译本》译作“亚衲族”〔参书11:21~22〕）余剩的人哪，你们划伤自己的身体要到几时呢？”'),
('CNV', '耶利米书', 24, 47, 6, '主的刀剑哪，你要到几时才可停下来呢？请你入鞘吧！休息静止吧！'),
('CNV', '耶利米书', 24, 47, 7, '但主既吩咐了它，又怎能停下来呢？他指派了它去攻击亚实基伦和沿海一带。'),
('CNV', '耶利米书', 24, 48, 1, '论到摩押，万军之主以色列的神这样说：“尼波有祸了！因为它变为荒凉；基列亭蒙受羞辱，被占领了；这城堡（“这城堡”或译：“米斯迦”）蒙受羞辱，被毁坏。'),
('CNV', '耶利米书', 24, 48, 2, '摩押不再被人称赞；敌人在希实本计谋害它，说：‘来吧！我们要把它剪除，使它不再成国！’玛得缅哪！你也要静默无声；刀剑必追赶你。'),
('CNV', '耶利米书', 24, 48, 3, '从何罗念传出哀号的声音，说：‘荒凉了，大大毁灭了！’'),
('CNV', '耶利米书', 24, 48, 4, '摩押毁灭了，它的孩童发出哀叫（“它的孩童发出哀叫”或参照《七十士译本》译作“哀叫之声直达琐珥”）。'),
('CNV', '耶利米书', 24, 48, 5, '在上鲁希的路上，摩押人随走随哭；从何罗念下来的途中，听见他们因城被毁发出凄惨的哀号声。”'),
('CNV', '耶利米书', 24, 48, 6, '你们要逃跑，赶快逃命吧！你们好像旷野的灌木。'),
('CNV', '耶利米书', 24, 48, 7, '你因为倚靠你的成就和财富，就必被攻取；基抹必被掳去，事奉它的祭司和领袖都必一同被掳去。'),
('CNV', '耶利米书', 24, 48, 8, '行毁灭的必来攻击一切城镇，没有一座城可以幸免；山谷必被蹂躏，平原必受破坏，正如主所说的。'),
('CNV', '耶利米书', 24, 48, 9, '你们要在摩押上面撒盐，因为它必成为废墟（“你们要在摩押上面撒盐，因为它必成为废墟”或译：“你们要把翅膀给摩押，因为它必飞去”）；它的城镇必成为荒凉，没有人在里面居住。'),
('CNV', '耶利米书', 24, 48, 10, '不努力去作主的工作的，该受咒诅；不使自己的刀剑见血的，应受咒诅。'),
('CNV', '耶利米书', 24, 48, 11, '摩押自年幼以来常享安逸，像不受搅扰的酒在缸里澄清，从没有倒进另一个缸里去，它也从没有被人掳去。因此它仍保留着原味，它的芬芳没有改变失去。'),
('CNV', '耶利米书', 24, 48, 12, '“看哪！日子快到（这是主的宣告），我必差派倒酒的人到它那里去，把它倒出来，直至倒空，又把酒缸打碎。'),
('CNV', '耶利米书', 24, 48, 13, '摩押必因基抹羞愧，好像以色列家因他们可倚靠的伯特利的神像羞愧一样。'),
('CNV', '耶利米书', 24, 48, 14, '你们怎么说：‘我们是勇士，是善战的武士’？'),
('CNV', '耶利米书', 24, 48, 15, '摩押被毁灭；敌人上来攻击它的城镇；摩押最精锐的少年下去被屠杀。”这是君王的宣告，他的名是万军之主。'),
('CNV', '耶利米书', 24, 48, 16, '“摩押的灾难已经临近了，它的祸患迅速来到。'),
('CNV', '耶利米书', 24, 48, 17, '所有在它四围的，所有认识它名的，你们都要为它哀悼，说：‘那有能力的权杖、华美的杖竟然折断了！’'),
('CNV', '耶利米书', 24, 48, 18, '住在底本的人民哪！要从你们荣耀的位上下来，坐在干旱的地上（“干旱的地上”原文作“干渴”），因为毁灭摩押的要上来攻击你们，摧毁你们的坚固城。'),
('CNV', '耶利米书', 24, 48, 19, '亚罗珥的居民哪！要站在路旁观望，询问那些正在逃跑的男女，说：‘发生了什么事？’'),
('CNV', '耶利米书', 24, 48, 20, '摩押蒙受羞辱，因为它已被毁灭了。你们要哀号喊叫，要在亚嫩河宣告：‘摩押毁灭了。’'),
('CNV', '耶利米书', 24, 48, 21, '审判临到了平原之地，就是何伦、雅杂、米法押、'),
('CNV', '耶利米书', 24, 48, 22, '底本、尼波、伯．低比拉太音、'),
('CNV', '耶利米书', 24, 48, 23, '基列亭、伯．迦末、伯．米恩、'),
('CNV', '耶利米书', 24, 48, 24, '加略、波斯拉和摩押地远近所有城市。'),
('CNV', '耶利米书', 24, 48, 25, '摩押的角被砍下，它的膀臂被折断了。”这是主的宣告。'),
('CNV', '耶利米书', 24, 48, 26, '你们要使摩押沉醉，因为它向主妄自尊大；摩押必跌在自己所吐之物上面，也必成为被人讥笑的对象。'),
('CNV', '耶利米书', 24, 48, 27, '摩押啊，以色列不是曾经成为你讥笑的对象吗？它岂是被捕获的强盗，以致你每逢提到它，总是摇头嘲笑。'),
('CNV', '耶利米书', 24, 48, 28, '摩押的居民哪！你们要离弃城镇，住在山岩里，像鸽子在峡谷的边上筑巢。'),
('CNV', '耶利米书', 24, 48, 29, '我们听说摩押的骄傲，它非常骄傲；我们听到它的狂妄、骄傲、傲慢和心里的自高。'),
('CNV', '耶利米书', 24, 48, 30, '“我洞悉它的狂傲（这是主的宣告），它的狂傲毫无根据，它的夸耀不能成事。'),
('CNV', '耶利米书', 24, 48, 31, '因此我要为摩押哀号，为全摩押喊叫，为吉珥．哈列设人（“为吉珥‧哈列设人”有古抄本作“他为吉珥‧哈列设人”）唉哼。'),
('CNV', '耶利米书', 24, 48, 32, '西比玛的葡萄树啊！我要你哀哭比人为雅谢哀哭更厉害。你的枝子伸展过海，延伸到雅谢（“雅谢”有古抄本作“雅谢海”）；那行毁灭的要来摧毁你夏天的果子和你的葡萄。'),
('CNV', '耶利米书', 24, 48, 33, '摩押肥沃的土地上不再有欢喜和快乐；我使榨酒池不再流出酒；再没有人欢呼踹酒；有人呼喊，却不是踹酒的欢呼声。'),
('CNV', '耶利米书', 24, 48, 34, '“希实本的哀叫传到以利亚利，他们发出的声音传到雅杂，从琐珥达到何罗念和伊基拉．施利施亚；因为连宁林的河水也都干涸了。'),
('CNV', '耶利米书', 24, 48, 35, '我要灭绝在摩押那些邱坛上献祭和向他们的神烧香的。”这是主的宣告。'),
('CNV', '耶利米书', 24, 48, 36, '“因此，我的心为摩押呜咽，好像人用笛吹挽歌；我的心为吉珥．哈列设人呜咽，好像人用笛吹挽歌；因为他们所得的财宝都失掉了。'),
('CNV', '耶利米书', 24, 48, 37, '他们各人的头都剃光了，胡须也剃掉了，他们割伤了自己的手，腰束麻布。'),
('CNV', '耶利米书', 24, 48, 38, '摩押境内一切房顶上和广场上，处处都有哀哭的声音；因为我击碎了摩押，好像打碎没有人要的器皿。”这是主的宣告。'),
('CNV', '耶利米书', 24, 48, 39, '摩押的毁灭多么厉害，他们的哀号多么凄惨！摩押怎样蒙羞转背！这样摩押就成了它四围众人讥笑和惊骇的对象。”'),
('CNV', '耶利米书', 24, 48, 40, '因为主这样说：“看哪！必有一人像大鹰疾飞，展开翅膀攻击摩押。'),
('CNV', '耶利米书', 24, 48, 41, '城市被攻取，坚垒被占领；在那日，摩押勇士的心必惊慌，像临产妇人的心一样。'),
('CNV', '耶利米书', 24, 48, 42, '摩押必被摧毁，不再成为一个民族，因为它向主妄自尊大。'),
('CNV', '耶利米书', 24, 48, 43, '摩押的居民哪！恐惧、陷阱、圈套都落在你们身上了。”这是主的宣告。'),
('CNV', '耶利米书', 24, 48, 44, '“那逃避恐惧的，必跌进陷阱；那从陷阱中出来的，必被圈套困着。因为我必使摩押受惩罚的年日临到它。”这是主的宣告。'),
('CNV', '耶利米书', 24, 48, 45, '“在希实本的隐蔽处，难民精疲力尽地站着；因为有火从希实本发出，有火焰从西宏的宫中冒出来，吞灭了摩押的前额，和吵闹的人的头顶。'),
('CNV', '耶利米书', 24, 48, 46, '摩押啊，你有祸了！基抹的人民灭亡了！因为你的众子都被掳去了，你的众女儿也都被掳去了。'),
('CNV', '耶利米书', 24, 48, 47, '但日后，我必使被掳的摩押人归回。”这是主的宣告。有关摩押的宣判到这里为止。'),
('CNV', '耶利米书', 24, 49, 1, '论到亚扪，主这样说：“以色列没有子孙吗？没有后嗣吗？为什么米勒公竟承受了迦得为业呢？它的人民为什么住在迦得的城市里呢？'),
('CNV', '耶利米书', 24, 49, 2, '因此，看哪！日子快到（这是主的宣告），我必使战争的吶喊声响起，有敌人来攻击亚扪的拉巴；拉巴必成为一片废墟，属它的乡镇（“乡镇”原文作“女子”）必被火焚烧。那时以色列人必从侵略他们的人的手中收回土地。”这是主说的。'),
('CNV', '耶利米书', 24, 49, 3, '“希实本哪，你要哀号！因为艾城已被毁灭。拉巴的居民（“居民”原文作“女子”），你们要呼喊，要腰束麻布，要哀哭，要在城墙内跑来跑去。因为米勒公，以及事奉它的祭司和领袖，都必一同被掳去。'),
('CNV', '耶利米书', 24, 49, 4, '背道的居民（“居民”原文作“女子”）哪！你们为什么因有山谷，就是你们那肥沃的山谷而夸口呢？你们十分倚靠自己的财宝，说：‘有谁敢来攻击我们呢？’'),
('CNV', '耶利米书', 24, 49, 5, '看哪！我必使你们因四围的列国而恐慌，这是主万军之主的宣告；你们必被赶逐，各自逃命，没有人把四散奔逃的人聚集起来。'),
('CNV', '耶利米书', 24, 49, 6, '但我日后必使被掳的亚扪人归回。”这是主的宣告。'),
('CNV', '耶利米书', 24, 49, 7, '论到以东，万军之主这样说：“提幔再没有智慧吗？聪明人已经计穷才尽吗？他们的智慧都消失了吗？'),
('CNV', '耶利米书', 24, 49, 8, '底但的居民哪！你们要转身逃跑，藏在隐蔽的地方，因为我惩罚以扫的时候，必使灾祸临到他身上。'),
('CNV', '耶利米书', 24, 49, 9, '收取葡萄的若来到你那里，岂不剩下一些葡萄吗？盗贼若在夜间来到你那里，岂不是只偷他们所要的吗（“岂不是只偷他们所要的吗”或译：“岂不毁坏直到够了吗”）？'),
('CNV', '耶利米书', 24, 49, 10, '但是我要使以扫赤裸，揭露他藏匿的地方，以致他不能隐藏。他的后裔、他的兄弟和他的邻居都必灭亡，'),
('CNV', '耶利米书', 24, 49, 11, '没有人会说：‘你撇下你的孤儿，我必使他们存活；你的寡妇可以倚靠我。’”'),
('CNV', '耶利米书', 24, 49, 12, '主这样说：“看哪！原不该喝那杯的，尚且一定要喝，难道你可以完全免受刑罚吗？你必不能免受刑罚，你一定要喝那杯。'),
('CNV', '耶利米书', 24, 49, 13, '因为我曾指着自己起誓，波斯拉必成为令人惊骇、被人羞辱和咒诅的对象；它必变成荒野，它一切的城镇都必永远变成荒场。”这是主的宣告。'),
('CNV', '耶利米书', 24, 49, 14, '我从主那里听见了一个信息，有一位使者被派往列国去，说：“你们要聚集去攻击以东，要起来争战！”'),
('CNV', '耶利米书', 24, 49, 15, '“看哪！我必使你在列国中成为弱小的，在世人中被藐视。'),
('CNV', '耶利米书', 24, 49, 16, '你那令人战栗的威风，你心中的傲气欺骗了你；你这住在岩石的隐密处，雄据山岭高处的啊！你虽如鹰在高处搭窝，我也必把你从那里拉下来。”这是主的宣告。'),
('CNV', '耶利米书', 24, 49, 17, '“以东必成为令人惊骇的地方；每一个经过那里的，都必因这地所遭受的一切创伤而惊骇，并且嗤笑它。'),
('CNV', '耶利米书', 24, 49, 18, '以东必倾覆，像所多玛、蛾摩拉，和它们的城镇一样（这是主说的），必没有人住在那里，也必没有人在那里寄居。'),
('CNV', '耶利米书', 24, 49, 19, '看哪！狮子怎样从约旦河边的丛林走上来，攻击常绿的牧场，照样，我必在眨眼之间把以东赶走，使它离开这地；谁蒙拣选，我就派谁治理这地。谁能和我相比呢？谁可以把我传来审讯呢？哪一个牧人能在我面前站立得住呢？”'),
('CNV', '耶利米书', 24, 49, 20, '因此，你们要听主筹谋对付以东的计划，和他为了提幔的居民所定下的策略。他们羊群中最小的也必被拉去，他们的牧场也必因临到它们的灾祸而荒废。'),
('CNV', '耶利米书', 24, 49, 21, '因他们倒下的响声，地就震动；并且有哀叫的声音，在红海那里也听得到。'),
('CNV', '耶利米书', 24, 49, 22, '看哪！必有一人像大鹰飞扑而来，展开翅膀攻击波斯拉；在那日，以东勇士的心必惊慌，像临产妇人的心一样。'),
('CNV', '耶利米书', 24, 49, 23, '论到大马士革，主说：“哈马和亚珥拔纷乱不安，因为他们听到了坏消息；他们的心融化，焦虑慌张，像不能平静的海洋。'),
('CNV', '耶利米书', 24, 49, 24, '大马士革失去勇气，转身逃跑；但恐慌抓住它，忧虑痛苦把它捉住，像正在生产的妇人的痛苦一样。'),
('CNV', '耶利米书', 24, 49, 25, '著名的城市，我所欢喜的市镇，怎么竟被撇弃呢！'),
('CNV', '耶利米书', 24, 49, 26, '它的年轻人必仆倒在它的街道上，到那日，所有的战士都必被消灭。”这是万军之主的宣告。'),
('CNV', '耶利米书', 24, 49, 27, '“我要焚烧大马士革的城墙，烧毁便．哈达的堡垒。”'),
('CNV', '耶利米书', 24, 49, 28, '论到巴比伦王尼布甲尼撒所击败的基达，以及夏琐诸国，主这样说：“起来，上去攻击基达，消灭东方人！'),
('CNV', '耶利米书', 24, 49, 29, '夺去他们的帐棚和羊群，带走他们的幔子、一切器具和骆驼；人必向他们呼叫：‘四围都是惊慌。’'),
('CNV', '耶利米书', 24, 49, 30, '夏琐的居民哪！你们要逃跑，快快逃命，藏在隐蔽的地方，因为巴比伦王尼布甲尼撒筹谋计划对付你们，定下策略攻击你们。”这是主的宣告。'),
('CNV', '耶利米书', 24, 49, 31, '“起来！上去攻打那安逸无虑的国家（这是主的宣告）；这国没有城门，也没有门闩；他们是独自居住的。'),
('CNV', '耶利米书', 24, 49, 32, '他们的骆驼必成为掠物，他们无数的牲畜必成为掳物。我必把那些剃除了鬓发的人分散到四方去，我必使灾祸从四面八方临到他们。”这是主的宣告。'),
('CNV', '耶利米书', 24, 49, 33, '“夏琐必成为野狗的巢穴，永远荒凉；必没有人住在那里，也必没有人在那里寄居。”'),
('CNV', '耶利米书', 24, 49, 34, '犹大王西底家开始执政的时候，主论到以拦的话临到耶利米先知，说：'),
('CNV', '耶利米书', 24, 49, 35, '“万军之主这样说：看哪！我要折断以拦的弓，就是他们战斗力强的武器。'),
('CNV', '耶利米书', 24, 49, 36, '我要使四风从天的四边刮到以拦身上，把他们分散到四方，以致没有一个国家没有以拦难民的踪迹。'),
('CNV', '耶利米书', 24, 49, 37, '我必使以拦人在他们的仇敌面前惊慌，在寻索他们性命的人面前恐惧；我必使灾祸，就是我的烈怒，临到他们身上；我必差遣刀剑追赶他们，直到把他们灭绝。”这是主的宣告。'),
('CNV', '耶利米书', 24, 49, 38, '“我必在以拦设立我的宝座，除灭那里的君王和领袖（这是主的宣告）。'),
('CNV', '耶利米书', 24, 49, 39, '但日后我必使被掳的以拦人归回。”这是主的宣告。'),
('CNV', '耶利米书', 24, 50, 1, '以下是主藉耶利米先知论到巴比伦，就是迦勒底人的地所说的话。'),
('CNV', '耶利米书', 24, 50, 2, '“你们要在列国中传扬和宣告，要竖起旗帜宣扬，不可隐瞒，说：‘巴比伦被攻取了！彼勒蒙羞，米罗达惊慌；巴比伦的神像都蒙羞，它的偶像都惊慌。’'),
('CNV', '耶利米书', 24, 50, 3, '因为有一个国家从北方来攻击它，使它的地荒凉；没有人在那里居住，人畜都逃跑无踪。'),
('CNV', '耶利米书', 24, 50, 4, '到那些日子、那时候（这是主的宣告），以色列人必和犹大人一同来，边走边哭，要寻找主他们的神。'),
('CNV', '耶利米书', 24, 50, 5, '他们要询问往锡安的路，又面向锡安，说：‘来吧！我们要以那永不可忘记的约与主连合。’'),
('CNV', '耶利米书', 24, 50, 6, '我的子民成了迷失的羊，他们的牧人使他们走错了路，使他们在山上徘徊；他们从大山走到小山，忘记了他们安歇之处。'),
('CNV', '耶利米书', 24, 50, 7, '所有遇见他们的都吞吃他们；他们的敌人说：‘我们没有罪，因为他们得罪了主，那真正的居所；主是他们列祖的盼望。’'),
('CNV', '耶利米书', 24, 50, 8, '我的子民哪！你们要从巴比伦中间逃跑，从迦勒底人的地出来；要像公山羊走在羊群前面。'),
('CNV', '耶利米书', 24, 50, 9, '因为，看哪！我必激动强国从北方之地联群而来，攻击巴比伦；他们要列阵攻打巴比伦；巴比伦就必被攻取。他们的箭必像善战的勇士，不会空手而回。'),
('CNV', '耶利米书', 24, 50, 10, '迦勒底必成为掠物，掳掠它的都必心满意足。”这是主的宣告。'),
('CNV', '耶利米书', 24, 50, 11, '“抢夺我产业的啊！你们虽然欢喜快乐，像踹谷的母牛犊跳跃，像雄壮的马嘶叫；'),
('CNV', '耶利米书', 24, 50, 12, '但你们的母亲必极度羞愧，生你们的必受耻辱。看哪！她要在列国中沦为最弱小的，成为旷野、旱地、沙漠。”'),
('CNV', '耶利米书', 24, 50, 13, '因主的烈怒，巴比伦必没有人居住，完全荒废；每一个住过巴比伦的，都必因这地遭受的一切创伤而惊骇，并且嗤笑它。'),
('CNV', '耶利米书', 24, 50, 14, '所有拉弓的啊！你们要在巴比伦四围列阵；射箭攻击它，不要吝啬箭枝，因为它得罪了主。'),
('CNV', '耶利米书', 24, 50, 15, '你们要在它的四周吶喊攻击它；它投降了，它城墙的支柱倒塌了，它的城墙拆毁了。因为这是主的报复；你们要向巴比伦报复，它怎样待人，你们也要怎样待它。'),
('CNV', '耶利米书', 24, 50, 16, '你们要把播种的，和在收割的时候手持镰刀的，都从巴比伦剪除；因为欺压者的刀剑，他们各人必归回自己的本族，各自逃回自己的故乡。'),
('CNV', '耶利米书', 24, 50, 17, '以色列是被赶散的羊，它被狮子赶逐。先是亚述王把它吞灭，现在巴比伦王尼布甲尼撒要咬碎它的骨头。'),
('CNV', '耶利米书', 24, 50, 18, '因此，万军之主神这样说：“看哪！我必惩罚巴比伦王和他的国土，像我以前惩罚亚述王一样，'),
('CNV', '耶利米书', 24, 50, 19, '我必领以色列回到它的牧场，它必在迦密和巴珊吃草，又在以法莲山地和基列地吃得饱足。'),
('CNV', '耶利米书', 24, 50, 20, '到那些日子，那时候，人要寻查以色列的罪孽，却无所发现；要查究犹大的罪恶，却一无所见；因为我必赦免我留下的那些人。”这是主的宣告。'),
('CNV', '耶利米书', 24, 50, 21, '“你们要攻击米拉大翁的地，上去攻击她，又攻击比割的居民，屠杀他们，把他们彻底消灭，照着我吩咐你们的一切执行。”这是主的宣告。'),
('CNV', '耶利米书', 24, 50, 22, '境内有战争的声音，和极大的毁灭。'),
('CNV', '耶利米书', 24, 50, 23, '击打全地的大锤，怎么被砍断毁掉！巴比伦在列国中，怎么成了令人惊骇的对象呢！'),
('CNV', '耶利米书', 24, 50, 24, '“巴比伦哪！我设下网罗捉拿你，你被捉住，仍不自觉；你被发现，也被抓住，因为你和主争斗。”'),
('CNV', '耶利米书', 24, 50, 25, '主打开了自己的军械库，拿出他忿怒的武器；因为主万军之主在迦勒底人的地有事要作。'),
('CNV', '耶利米书', 24, 50, 26, '你们要从四面八方攻击巴比伦，打开它的谷仓，把它堆起来好像堆谷物一样；把它彻底消灭，什么都不留下。'),
('CNV', '耶利米书', 24, 50, 27, '要击杀它所有的公牛，使他们下去被屠杀！他们有祸了！因为他们的日子，就是他们受惩罚的时候，来到了。'),
('CNV', '耶利米书', 24, 50, 28, '听哪！从巴比伦的地逃出得以脱险的人，在锡安述说主我们神的报复，就是为他的殿而施行的报复。'),
('CNV', '耶利米书', 24, 50, 29, '“要召集弓箭手去攻击巴比伦，要召集所有拉弓的；要在巴比伦的四围安营攻击它，不容一人逃脱。要照着它的所作所为报应它，它怎样待人，你们也要怎样待它；因它狂傲地敌对主，与以色列的圣者为敌。'),
('CNV', '耶利米书', 24, 50, 30, '所以，它的年轻人必仆倒在它的街道上，到那一天，它所有的战士都必被消灭。”这是主的宣告。'),
('CNV', '耶利米书', 24, 50, 31, '“傲慢的人哪！我必敌对你（这是主万军之主的宣告），因为你的日子，就是我惩罚你的时候，来到了。'),
('CNV', '耶利米书', 24, 50, 32, '那傲慢的必绊跌仆倒，没有人扶他起来；我必在他的城镇中放火，吞灭他四围的一切。”'),
('CNV', '耶利米书', 24, 50, 33, '万军之主这样说：“以色列人被压迫，犹大人也一样受到欺压；所有俘掳他们的都紧紧抓住他们，不肯释放他们。'),
('CNV', '耶利米书', 24, 50, 34, '但他们的救赎主大有能力，万军之主是他的名；他必认真地为他们的案件申辩，好使那地得到安宁，却使巴比伦的居民惶乱不安。'),
('CNV', '耶利米书', 24, 50, 35, '刀剑必攻击迦勒底人，攻击巴比伦的居民，攻击它的领袖和智慧人。”这是主的宣告。'),
('CNV', '耶利米书', 24, 50, 36, '“刀剑必攻击胡说八道的假先知，他们必变成愚昧；刀剑必攻击它的勇士，他们必惊惶失措；'),
('CNV', '耶利米书', 24, 50, 37, '刀剑必攻击它的马匹和战车，攻击它境内所有外族的人，他们必像妇女一样柔弱；刀剑必攻击它的一切宝库，它们必被抢掠；'),
('CNV', '耶利米书', 24, 50, 38, '干旱（“干旱”或参照《七十士译本》和其他古译本翻译为“刀剑”）必攻击它的河流，它们必干涸；因为这是偶像的地，人必因可怕的偶像迷失本性。'),
('CNV', '耶利米书', 24, 50, 39, '旷野的走兽和豺狼必住在那里，鸵鸟也必住在其中；那地永远再没有人居住，世世代代不再有人住在那里，'),
('CNV', '耶利米书', 24, 50, 40, '就像神倾覆的所多玛、蛾摩拉，和它们邻近的城镇一样；必没有人住在那里，也必没有人在那里寄居。”这是主的宣告。'),
('CNV', '耶利米书', 24, 50, 41, '“看哪！有一个民族从北方而来，有一大国和许多君王被激动，从地极来到。'),
('CNV', '耶利米书', 24, 50, 42, '他们紧握弓和枪，性情残忍，毫无怜悯；他们的声音像海洋怒吼；巴比伦的居民哪！他们骑着战马，在战场上如同一人，列阵攻击你们。'),
('CNV', '耶利米书', 24, 50, 43, '巴比伦王听了有关他们的消息，手就发软；痛苦紧紧抓住他，他疼痛好像正在生产的妇人。'),
('CNV', '耶利米书', 24, 50, 44, '看哪！狮子怎样从约旦河边的丛林走上来，攻击常绿的牧场，照样，我必在眨眼之间把巴比伦赶走，使它离开这地；谁蒙拣选，我就派谁治理这地。谁能和我相比呢？谁可以把我传来审讯呢？哪一个牧人能在我面前站立得住呢？”'),
('CNV', '耶利米书', 24, 50, 45, '因此，你们要听主筹谋对付巴比伦的计划，和他为了攻击迦勒底人的地所定下的策略。他们羊群中最小的也必被拉去，他们的牧场也必因临到它们的灾祸而荒废。'),
('CNV', '耶利米书', 24, 50, 46, '因巴比伦陷落的响声，地就震动；列国都听见它的哀叫声。'),
('CNV', '耶利米书', 24, 51, 1, '主这样说：“看哪！我必激动毁灭者的心，去攻击巴比伦和住在立加米的人。'),
('CNV', '耶利米书', 24, 51, 2, '我必打发外族人去巴比伦簸扬它，扬净它的地；在它遭祸的日子，他们必从四围攻击它。'),
('CNV', '耶利米书', 24, 51, 3, '不要容拉弓的拉他的弓，也不要容战士穿上盔甲站起来；不要顾惜巴比伦的年轻人，要把它的全军灭绝。'),
('CNV', '耶利米书', 24, 51, 4, '它的全军必在迦勒底人的地被杀倒下，在它的街道上被刺死。”'),
('CNV', '耶利米书', 24, 51, 5, '但以色列和犹大却不会被他们的神万军之主遗弃，虽然他们的地在以色列圣者面前充满了罪恶。'),
('CNV', '耶利米书', 24, 51, 6, '你仍要从巴比伦境内逃出来，各自逃命！不要因它的罪孽灭亡；因为这是主报复的时候，他必向巴比伦施行应得的报应。'),
('CNV', '耶利米书', 24, 51, 7, '巴比伦曾是主手中的金杯，使全地都喝醉；列国喝了它的酒，就都疯狂乱性。'),
('CNV', '耶利米书', 24, 51, 8, '巴比伦必突然倾覆毁灭，你们要为它哀号！拿乳香来消除它的痛楚，也许可以治好它。'),
('CNV', '耶利米书', 24, 51, 9, '我们本想医治巴比伦，但它没有治好。我们离开它，各归本地去吧！因为它的刑罚极大，上达于天，直到云霄。'),
('CNV', '耶利米书', 24, 51, 10, '主已为我们伸冤；来吧！我们要在锡安宣扬主我们神的作为。'),
('CNV', '耶利米书', 24, 51, 11, '你们要磨尖箭头，拿起盾牌（“拿起盾牌”《七十士译本》译作“装满箭袋”）；主定意要毁灭巴比伦，所以激动玛代诸王的心；这是主的报复，就是为他的殿而施行的报复。'),
('CNV', '耶利米书', 24, 51, 12, '你们要竖起旗帜，攻击巴比伦的城墙，并要加强防卫，设立防哨，布下埋伏；因为主不但定意，也必作成他攻击巴比伦居民的话。'),
('CNV', '耶利米书', 24, 51, 13, '你这住在众水旁，多有财宝的啊！你的结局到了，你被剪除的时刻到了。'),
('CNV', '耶利米书', 24, 51, 14, '万军之主指着自己起誓，说：“我必使敌人充满你，像蝗虫一样布满你的全地，他们必对你发出胜利的吶喊。”'),
('CNV', '耶利米书', 24, 51, 15, '主用自己的能力创造了大地，用自己的智慧坚立了世界，又用自己的聪明展开了诸天。'),
('CNV', '耶利米书', 24, 51, 16, '他一发声，空中诸水就澎湃；他使云雾从地极上腾；他造了闪电和雷雨，又使风从他的仓库里吹出来。'),
('CNV', '耶利米书', 24, 51, 17, '人人都是顽梗无知；所有的金匠都因偶像羞愧，因为他们铸造的像都是虚假，没有气息。'),
('CNV', '耶利米书', 24, 51, 18, '偶像都是虚无的，是荒谬可笑的作品；到了讨罪的时候，它们必被除灭。'),
('CNV', '耶利米书', 24, 51, 19, '那作雅各产业的并不像这些偶像，因为他是万物的创造者；以色列是属他的民族，万军之主是他的名。'),
('CNV', '耶利米书', 24, 51, 20, '主说：“你是我的铁锤，作我的兵器；我用你们打碎列国，用你毁灭万邦。'),
('CNV', '耶利米书', 24, 51, 21, '我用你打碎战马和骑马的，用你打碎战车和坐战车的。'),
('CNV', '耶利米书', 24, 51, 22, '我用你打碎男人和妇女，用你打碎老年人和少年人，用你打碎少男和少女。'),
('CNV', '耶利米书', 24, 51, 23, '我用你打碎牧人和他的羊群，用你打碎农夫和他的耕牛，用你打碎省长和总监。'),
('CNV', '耶利米书', 24, 51, 24, '“但我必在你们眼前报复巴比伦和迦勒底所有的居民在锡安所作的一切恶事。”这是主的宣告。'),
('CNV', '耶利米书', 24, 51, 25, '“行毁灭的山哪，就是毁灭全地的山哪！我要和你作对，我要伸手攻击你，使你从山岩上滚下来，使你成为烧毁了的山。”这是主的宣告。'),
('CNV', '耶利米书', 24, 51, 26, '“人必不从你那里取石头作房角石，也不从你那里取石头作基石，因为你必永远荒凉。”这是主的宣告。'),
('CNV', '耶利米书', 24, 51, 27, '“你们要在地上竖起旗帜，在列国中吹号角，使列国作好准备攻击巴比伦，把亚拉腊、米尼、亚实基拿等国召来攻击她，又指派元帅来攻击她，使马匹像蝗虫汹涌上来。'),
('CNV', '耶利米书', 24, 51, 28, '你们要使列国作好准备攻击她，使玛代诸王，和她的省长、总监，以及他们辖下各地的人民都作好准备攻击她。'),
('CNV', '耶利米书', 24, 51, 29, '大地震动翻腾，因为主攻击巴比伦所定的旨意立定不移，要使巴比伦的地荒凉，没有人居住。'),
('CNV', '耶利米书', 24, 51, 30, '巴比伦的勇士停止作战，留在堡垒里面；他们的勇士消退，变成像妇人一样软弱。巴比伦的房屋被火焚烧，她的门闩都被折断。'),
('CNV', '耶利米书', 24, 51, 31, '驿卒一个接一个跑来，报信的也相继而至，向巴比伦王报告，他的京城已经完全被攻取了。'),
('CNV', '耶利米书', 24, 51, 32, '渡口已经被占据了，生满芦苇的沼泽也被火烧了，军兵都惊慌失措。”'),
('CNV', '耶利米书', 24, 51, 33, '因为万军之主以色列的神这样说：“巴比伦城（“城”原文作“女子”）好像正被踹平的禾场，再过片时，她被收割的时候就到了。”'),
('CNV', '耶利米书', 24, 51, 34, '以色列人说：“巴比伦王尼布甲尼撒吞灭了我们，使我们十分混乱，又使我们成为空的器皿；他像怪兽把我们吞下，他的肚塞满了我们的美物，他却把我们吐出去。”'),
('CNV', '耶利米书', 24, 51, 35, '锡安的居民要说：“愿巴比伦以强暴待我们（“我们”或译：“我和我骨肉之亲”）的罪归到巴比伦身上。”耶路撒冷要说：“愿流我血的罪归到迦勒底的居民身上。”'),
('CNV', '耶利米书', 24, 51, 36, '因此，主这样说：“看哪！我必为你的案件申诉，为你报仇；我必使巴比伦的河水枯竭，使它们的水源干涸。'),
('CNV', '耶利米书', 24, 51, 37, '巴比伦必变成乱堆，成为野狗的巢穴，成为令人惊骇和嗤笑的对象，没有人居住。'),
('CNV', '耶利米书', 24, 51, 38, '巴比伦人必像少壮狮子一起吼叫，又像幼狮咆哮。'),
('CNV', '耶利米书', 24, 51, 39, '他们食欲大动的时候，我必为他们摆设筵席，使他们喝醉，狂欢乱叫，然后永远沉睡，不再醒来（这是主的宣告）。'),
('CNV', '耶利米书', 24, 51, 40, '我必使他们像羊羔，像公绵羊和公山羊一样下到屠宰之地。'),
('CNV', '耶利米书', 24, 51, 41, '示沙克怎么竟被攻取！全地所称赞的怎么竟被占领！巴比伦在列国中怎么竟成了令人惊骇的对象！'),
('CNV', '耶利米书', 24, 51, 42, '大海上涨漫过巴比伦，它被汹涌的波浪淹没。'),
('CNV', '耶利米书', 24, 51, 43, '它的城镇变为荒凉，成为干旱的地和沙漠，没有人住在里面，也没有人经过。'),
('CNV', '耶利米书', 24, 51, 44, '我必惩罚巴比伦的彼勒，使它从口中吐出它所吞噬的；列国必不再归附它，巴比伦的城墙也倒塌了。'),
('CNV', '耶利米书', 24, 51, 45, '我的子民哪！你们要从它那里出来，各自逃命，躲避主的烈怒。'),
('CNV', '耶利米书', 24, 51, 46, '你们不要心惊胆怯，也不要因在境内听到的谣言惧怕；因为今年有谣言传来，明年也会有谣言传来，境内有强暴的事，官长互相攻击。'),
('CNV', '耶利米书', 24, 51, 47, '因此，你看，日子快到，我必惩罚巴比伦的偶像；巴比伦全地都必蒙羞，所有被刺杀的人都必倒在境内。'),
('CNV', '耶利米书', 24, 51, 48, '那时天地和其中的一切，都必因巴比伦的倾覆欢呼，因为行毁灭的要从北方来攻击她。”这是主的宣告。'),
('CNV', '耶利米书', 24, 51, 49, '“巴比伦必因以色列被刺杀的人而倒下，就如全地被刺杀的人因巴比伦而倒下。'),
('CNV', '耶利米书', 24, 51, 50, '那些已逃脱了刀剑的人哪！走吧！不要站着，要从远方记念主，心中惦念耶路撒冷。'),
('CNV', '耶利米书', 24, 51, 51, '我们因听见辱骂而蒙羞，满面惭愧；因为外族人进入了主殿的圣所。'),
('CNV', '耶利米书', 24, 51, 52, '因此，看哪！日子快到，这是主的宣告。我必惩罚巴比伦的偶像，在巴比伦全境到处都有被刺伤的人在唉哼。'),
('CNV', '耶利米书', 24, 51, 53, '即使巴比伦升到天上，即使它在高处建造难以进侵的堡垒，但必有行毁灭的从我这里去攻击它。”这是主的宣告。'),
('CNV', '耶利米书', 24, 51, 54, '“听啊！有哀号的声音从巴比伦传出，有大毁灭的声音从迦勒底人的地发出。'),
('CNV', '耶利米书', 24, 51, 55, '因为主正在毁灭巴比伦，使城中喧闹的声音灭绝。敌军好像洪水，波浪澎湃，发出吶喊的声音。'),
('CNV', '耶利米书', 24, 51, 56, '因为有一位行毁灭的来攻击巴比伦，巴比伦的勇士被擒住，他们的弓弩折断了，因为主是报应的神，他必报复巴比伦。'),
('CNV', '耶利米书', 24, 51, 57, '我必使巴比伦的领袖和智慧人，省长、总监和勇士都喝醉，永远沉睡，不再醒来。”这是君王的宣告，万军之主是他的名。'),
('CNV', '耶利米书', 24, 51, 58, '万军之主这样说：“巴比伦宽阔的城墙必被夷为平地，它高大的城门必被焚烧；万民所劳碌的都必成空，万族所辛劳的都付诸一炬。”'),
('CNV', '耶利米书', 24, 51, 59, '犹大王西底家执政的第四年，玛西雅的孙子、尼利亚的儿子西莱雅和王同去巴比伦的时候，耶利米先知有话吩咐西莱雅，他是掌管住宿事务的官员。'),
('CNV', '耶利米书', 24, 51, 60, '耶利米把一切将要临到巴比伦的灾祸，就是这一切论到巴比伦的话，都写在一卷书上。'),
('CNV', '耶利米书', 24, 51, 61, '耶利米对西莱雅说：“你到了巴比伦以后，一定要宣读这一切话，'),
('CNV', '耶利米书', 24, 51, 62, '然后你要说：‘主啊！论到这地方，你曾经亲自说过要把它剪除，使这地永远荒凉，没有人畜居住。’'),
('CNV', '耶利米书', 24, 51, 63, '你宣读完这书卷以后，要把一块石头和书拴在一起，丢进幼发拉底河里，'),
('CNV', '耶利米书', 24, 51, 64, '然后说：‘巴比伦必因主（“主”原文作“我”）所要降给它的灾祸，照样沉下去，不再浮上来；它的人民也必灭没。’”耶利米的话到此为止。'),
('CNV', '耶利米书', 24, 52, 1, '西底家登基的时候是二十一岁，他在耶路撒冷作王十一年；他母亲名叫哈慕他，是立拿人耶利米的女儿。'),
('CNV', '耶利米书', 24, 52, 2, '他行主眼中看为恶的事，像约雅敬一切所行的。'),
('CNV', '耶利米书', 24, 52, 3, '因为主的怒气向耶路撒冷和犹大发作，直到他把他们从自己的面前赶走。后来，西底家背叛了巴比伦王。'),
('CNV', '耶利米书', 24, 52, 4, '西底家作王第九年十月十日，巴比伦王尼布甲尼撒率领他的全军来攻打耶路撒冷；他们在城外安营，又在四周筑垒攻城。'),
('CNV', '耶利米书', 24, 52, 5, '于是，城被围困，直到西底家王第十一年。'),
('CNV', '耶利米书', 24, 52, 6, '四月九日，城里饥荒非常严重，甚至那地的人民都断了粮食。'),
('CNV', '耶利米书', 24, 52, 7, '城终于被攻破了，所有的战士就在夜间从靠近王的花园的两墙中间的那门，逃跑出城。那时迦勒底人在四围攻城；他们就往亚拉巴的方向逃走。'),
('CNV', '耶利米书', 24, 52, 8, '迦勒底人的军队追赶，在耶利哥的原野上把西底家追上了；他的全军都离开他四散了。'),
('CNV', '耶利米书', 24, 52, 9, '他们把王擒住，把他解到哈马地的利比拉巴比伦王那里；他就宣判他的罪。'),
('CNV', '耶利米书', 24, 52, 10, '巴比伦王在利比拉，当着西底家眼前杀了他的众子，也杀了犹大所有的领袖，'),
('CNV', '耶利米书', 24, 52, 11, '并且把西底家的眼睛弄瞎，然后用铜链锁住他。巴比伦王把他带到巴比伦去，关在牢里，直到他去世的日子。'),
('CNV', '耶利米书', 24, 52, 12, '五月十日，就是巴比伦王尼布甲尼撒第十九年，侍立在巴比伦王面前的护卫长尼布撒拉旦来到耶路撒冷。'),
('CNV', '耶利米书', 24, 52, 13, '他放火焚烧主的殿和王宫，以及耶路撒冷一切房屋，一切高大的房屋，他都放火烧了。'),
('CNV', '耶利米书', 24, 52, 14, '跟随护卫长的迦勒底人全军拆毁了耶路撒冷周围所有的城墙。'),
('CNV', '耶利米书', 24, 52, 15, '至于人民中最贫穷的、城中剩下的人民，和已经向巴比伦王投降的人，以及剩下的技工，护卫长尼布撒拉旦都掳了去。'),
('CNV', '耶利米书', 24, 52, 16, '至于那地最贫穷的人，护卫长尼布撒拉旦把他们留下，去修理葡萄园和耕种田地。'),
('CNV', '耶利米书', 24, 52, 17, '主殿的铜柱，以及主殿的铜座和铜海，迦勒底人都打碎了，把所有的铜都运到巴比伦去。'),
('CNV', '耶利米书', 24, 52, 18, '他们又把锅、铲子、烛剪、碗、碟子，和敬拜用的一切铜器都拿去了。'),
('CNV', '耶利米书', 24, 52, 19, '此外，碗盆、火鼎、碗、锅、灯台、碟子和奠酒的爵，无论是金的或是银的，护卫长都拿去了。'),
('CNV', '耶利米书', 24, 52, 20, '所罗门王为主的殿所做的两根铜柱、一个铜海、铜海下面的十二头铜牛，和十个铜座，这一切器皿的铜，重得无法可称。'),
('CNV', '耶利米书', 24, 52, 21, '至于那些柱子，每根高八公尺，圆周是五公尺三公分，柱子是空心的。铜的厚度有七十五公厘。'),
('CNV', '耶利米书', 24, 52, 22, '柱上有铜柱头，柱头高两公尺三十公分，柱头四周有网子和石榴都是铜的；另一根柱子同样也有石榴。'),
('CNV', '耶利米书', 24, 52, 23, '每个网子周围共有一百个石榴，明显可见的有九十六个。'),
('CNV', '耶利米书', 24, 52, 24, '护卫长拿住祭司长西莱雅、副祭司长西番亚和三个守门的；'),
('CNV', '耶利米书', 24, 52, 25, '又从城里拿住一个管理军兵的官长，并且在城里搜获常见王面的七个人，和一个负责召募当地人民的军长书记，又在城中搜获六十个当地的人民。'),
('CNV', '耶利米书', 24, 52, 26, '护卫长尼布撒拉旦把他们拿住，带到利比拉巴比伦王那里。'),
('CNV', '耶利米书', 24, 52, 27, '巴比伦王击打他们，在哈马地的利比拉把他们处死。这样，犹大人被掳，离开了他们的国土。'),
('CNV', '耶利米书', 24, 52, 28, '以下是尼布甲尼撒掳去的人民的数目：在他执政第七年，有犹大人三千零二十三名；'),
('CNV', '耶利米书', 24, 52, 29, '尼布甲尼撒第十八年，从耶路撒冷掳去的，有八百三十二人；'),
('CNV', '耶利米书', 24, 52, 30, '尼布甲尼撒第二十三年，护卫长尼布撒拉旦掳去犹大人七百四十五名。总数是四千六百人。'),
('CNV', '耶利米书', 24, 52, 31, '犹大王约雅斤被掳后第三十七年，就是巴比伦王以未．米罗达登基的那一年，十二月二十五日，他恩待（“恩待”原文作“使抬起头来”）犹大王约雅斤，把他从狱中领出来，'),
('CNV', '耶利米书', 24, 52, 32, '并且安慰他，使他的地位高过和他一起在巴比伦的众王。'),
('CNV', '耶利米书', 24, 52, 33, '又换下他的囚衣，赐他终生常在王面前吃饭。'),
('CNV', '耶利米书', 24, 52, 34, '他的生活费用，在他一生的年日中，每日不断由巴比伦王供应，直到他去世的日子。'),
('CNV', '耶利米哀歌', 25, 1, 1, '从前人烟稠密的城中，现在怎么竟然孤独地坐在那里。从前在列国中为大的，现在怎么竟然像个寡妇。从前在众省份中为王后的，现在怎么竟然成了奴隶。'),
('CNV', '耶利米哀歌', 25, 1, 2, '她在夜间痛哭，泪流满面。在她所有亲爱的人中，没有一个安慰她的。她所有的朋友都以诡诈待她，都成了她的仇敌。'),
('CNV', '耶利米哀歌', 25, 1, 3, '犹大受尽痛苦，饱经劳役，更遭流徙异地。她住在列国中，找不着安居之所。在困境之中，追赶她的人把她追上了。'),
('CNV', '耶利米哀歌', 25, 1, 4, '通往锡安道路悲哀，因为没有人去守节。锡安一切的城门冷落，祭司唉哼，处女忧伤，锡安也受尽痛苦。'),
('CNV', '耶利米哀歌', 25, 1, 5, '锡安的敌人成为主人；她的仇敌亨通。因为她的过犯众多，主就使她受苦。她的孩童在敌人面前被掳去。'),
('CNV', '耶利米哀歌', 25, 1, 6, '锡安（“锡安”原文作“锡安的女子”）所有的尊荣，都离开了她的居民。她的众领袖都像找不着牧场的鹿；在追赶的人面前无力逃走。'),
('CNV', '耶利米哀歌', 25, 1, 7, '耶路撒冷在困苦飘流的日子，就追念她昔日的一切珍宝。她的人民落在敌人手里的时候，没有人帮助她。敌人看见她，就讥笑她的灭亡。'),
('CNV', '耶利米哀歌', 25, 1, 8, '耶路撒冷犯了大罪，因此成了不洁之物。素来尊敬她的现在都藐视她，因为看见她赤身露体；她自己也唉哼，转身退避。'),
('CNV', '耶利米哀歌', 25, 1, 9, '她的污秽沾满了衣裙；她从不思想自己的结局。所以她令人惊异地败落了；没有人安慰她。她说：“主啊！求你看看我的苦难，因为仇敌显为大。”'),
('CNV', '耶利米哀歌', 25, 1, 10, '敌人伸手夺取她的一切珍宝，她看着外族人闯入她的圣所：你曾禁止他们进入你的会中。'),
('CNV', '耶利米哀歌', 25, 1, 11, '她所有的人民都在唉哼，到处寻觅食物；他们为了维持生命，拿自己的珍宝去换取粮食。她说：“主啊！求你垂看，求你鉴察，因为我被人藐视。”'),
('CNV', '耶利米哀歌', 25, 1, 12, '所有过路的人啊！你们毫不在意吗？你们要细察要观看，有没有痛苦像我所受的痛苦，就是主在他发烈怒的日子使我所受的痛苦。'),
('CNV', '耶利米哀歌', 25, 1, 13, '他从高天降火，使火进入我的骨头里（按照《马索拉文本》，“他从高天降火，使火进入我的骨头里”作“他从高天降火进入我的骨头里，他管理火”；现参照《七十士译本》翻译）。他设置网罗绊我的脚，使我退去。他使我孤单凄凉，终日愁烦。'),
('CNV', '耶利米哀歌', 25, 1, 14, '我的过犯像轭一样被绑好；是他亲手缠绑的。我的过犯加在我的颈上，他使我的气力衰弱。主把我交在我不能对抗的人手中。'),
('CNV', '耶利米哀歌', 25, 1, 15, '主丢弃我中间的所有勇士；他招聚了一大群人来攻击我，要打碎我的青年人。主践踏犹大女儿中的处女，像践踏压酒池一样。'),
('CNV', '耶利米哀歌', 25, 1, 16, '为了这些事我不住哭泣，我的眼不住流下泪水；因为那安慰我、使我重新振作的，都远离了我。我的儿女孤单凄凉，因为仇敌得胜了。'),
('CNV', '耶利米哀歌', 25, 1, 17, '锡安伸出双手，但没有人安慰她。论到雅各，主已经下令，使他四围的人都与他为敌；耶路撒冷在他们中间，已经成了不洁的东西。'),
('CNV', '耶利米哀歌', 25, 1, 18, '主是公义的，他这样待我，是因为我违背了他的命令。万民哪！请你们听我的话！看看我的痛苦！我的少女和青年人都已经被掳去了。'),
('CNV', '耶利米哀歌', 25, 1, 19, '我向我所爱的人呼求，他们却欺骗我。我的祭司和长老为了延续生命，寻找粮食的时候，就在城中气绝身亡了。'),
('CNV', '耶利米哀歌', 25, 1, 20, '主啊！你看，患难临到我！我的心肠激动，我的心在我里面翻转，因为我曾经非常悖逆。街上有刀剑使人丧子，屋里也有死亡。'),
('CNV', '耶利米哀歌', 25, 1, 21, '有人听见我的唉哼，却没有人安慰我，我所有的仇敌都听见我的灾难；你作了这事，他们就欢乐。愿你使你所宣告的日子来临那时，他们就必像我一样。'),
('CNV', '耶利米哀歌', 25, 1, 22, '愿他们的一切恶行都摆在你面前，愿你对付他们，好像你因我的一切过犯对付我一样。因为我唉哼甚苦，我心里愁烦。'),
('CNV', '耶利米哀歌', 25, 2, 1, '主在烈怒中，怎么竟然使黑云遮盖锡安的居民（“居民”原文作“女子”）！他把以色列的荣美，从天上抛到地上；他在发怒的日子，竟不记念自己的脚凳。'),
('CNV', '耶利米哀歌', 25, 2, 2, '主吞灭了雅各所有住处，毫不顾惜；他在忿怒中，把犹大居民的坚固城拆毁；他使国家和国中众领袖都倒在地上，受尽羞辱。'),
('CNV', '耶利米哀歌', 25, 2, 3, '他在烈怒中砍断以色列所有的角；他从仇敌面前，收回自己的右手。他像吞灭四周物件的火焰，在雅各中间焚烧。'),
('CNV', '耶利米哀歌', 25, 2, 4, '他像仇敌拉弓，他的右手已经预备好。他像敌人把一切悦人眼目的都杀灭了；他如火的忿怒倒在锡安居民（“居民”原文作“女子”）的帐棚上。'),
('CNV', '耶利米哀歌', 25, 2, 5, '主好像成了仇敌；他吞灭了以色列和她所有的宫殿，毁坏了她的坚固城。他在犹大居民的中间，增添了悲哀和哭号。'),
('CNV', '耶利米哀歌', 25, 2, 6, '他把自己的住所破坏，好像园子一样；他毁坏了属他的聚会之处。主使节期和安息日都在锡安被忘记；他在他的盛怒中弃绝了君王和祭司。'),
('CNV', '耶利米哀歌', 25, 2, 7, '主丢弃了自己的祭坛，厌弃了自己的圣所。他把宫殿的围墙，交付在仇敌的手里；他们在主的殿中喧嚷，好像庆祝节日一样。'),
('CNV', '耶利米哀歌', 25, 2, 8, '主定意要拆毁锡安居民（“居民”原文作“女子”）的城墙；他拉了准绳，决不停手，务要把它吞灭。他使堡垒和城墙都悲哀，一同受痛苦。'),
('CNV', '耶利米哀歌', 25, 2, 9, '锡安的众城门已经陷入地里；主把锡安的门闩都毁坏折断了。锡安的君王和领袖都身在列国中；锡安再没有律法了；它的众先知也得不到从主而来的异象。'),
('CNV', '耶利米哀歌', 25, 2, 10, '锡安居民（“居民”原文作“女子”）的长老都坐在地上，默默无声；他们把尘灰撒在头上，腰束麻布。耶路撒冷的处女都垂头至地。'),
('CNV', '耶利米哀歌', 25, 2, 11, '我的眼睛因流泪而失明，我的心肠激动，我的肝胆倾倒在地，都因我的子民（“我的子民”原文作“我子民的女子”）遭毁灭，孩童和婴儿在城里的街上昏倒。'),
('CNV', '耶利米哀歌', 25, 2, 12, '他们像被刺伤的人昏倒在城里街上的时候，他们在母亲的怀里快要丧命的时候，他们就问母亲：“五谷和酒在哪里呢？”'),
('CNV', '耶利米哀歌', 25, 2, 13, '耶路撒冷的居民哪，我怎样向你说明呢？用什么与你比较呢？锡安的居民哪，我们用什么跟你相比，好安慰你呢？你的裂口像海那样大，谁能医治你呢？'),
('CNV', '耶利米哀歌', 25, 2, 14, '你的假先知为了你所见的异象，尽是虚谎和愚昧；他们没有显露你的罪孽，使你的命运得以挽回；他们为你所得的默示，全是虚谎，是引人走错路的。'),
('CNV', '耶利米哀歌', 25, 2, 15, '所有过路的人，都拍掌嘲笑你；他们嗤笑耶路撒冷的居民，并摇头说：“被人称为最完美，为全地所喜悦的，就是这城吗？”'),
('CNV', '耶利米哀歌', 25, 2, 16, '你所有的仇敌都张开口攻击你，他们嗤笑你，又咬牙切齿，说：“我们吞灭它了！这真是我们期待的日子！我们等到了！亲眼看见了！”'),
('CNV', '耶利米哀歌', 25, 2, 17, '主作成了他定意去作的，成就了他的话，就是他昔日所宣告的，他把你拆毁，并不怜惜，他使仇敌因胜过你而高兴，他高举你敌人的角。'),
('CNV', '耶利米哀歌', 25, 2, 18, '锡安居民（“居民”原文作“女子”）的城墙啊，你要一心向主哀求；愿你的眼泪像江河般涌流，昼夜不息；愿你得不着歇息，愿你眼中的瞳人不能休息。'),
('CNV', '耶利米哀歌', 25, 2, 19, '夜里每到交更的时分，你要起来呼喊；在主面前你要倾心如水！你的孩童在各街头上因饥饿而昏倒，你要为他们的性命向主举手祷告。'),
('CNV', '耶利米哀歌', 25, 2, 20, '“主啊，求你观看！求你鉴察！你曾这样对待过谁呢？难道妇人应该吃掉自己所生的，就是自己所抚养的婴孩吗？难道祭司和先知应该在主的圣所里被杀害吗？”'),
('CNV', '耶利米哀歌', 25, 2, 21, '少年人和老年人都在街上倒卧在地死了；我的年轻男女都倒毙于刀下；在你忿怒的日子，你杀了他们，你屠杀了他们，毫不怜惜。'),
('CNV', '耶利米哀歌', 25, 2, 22, '你从四围招聚惊吓我的，好像招聚人过节的日子一样。在主忿怒的日子，没有人可以逃脱，可以生存。我所抚育、所养大的，我的仇敌都灭尽了。'),
('CNV', '耶利米哀歌', 25, 3, 1, '我是在主忿怒的杖下受过苦的人。'),
('CNV', '耶利米哀歌', 25, 3, 2, '他领我，使我行在黑暗中，不行在光明里。'),
('CNV', '耶利米哀歌', 25, 3, 3, '他真是终日不停地反手攻击我。'),
('CNV', '耶利米哀歌', 25, 3, 4, '他使我的肌肤衰残，折断我的骨头。'),
('CNV', '耶利米哀歌', 25, 3, 5, '他筑垒围困我，使毒害和艰难环绕我。'),
('CNV', '耶利米哀歌', 25, 3, 6, '他使我住在黑暗之处，好像死了许久的人一样。'),
('CNV', '耶利米哀歌', 25, 3, 7, '他筑墙围住我，使我不能逃出去；他又加重我的钢链。'),
('CNV', '耶利米哀歌', 25, 3, 8, '甚至我哀求呼救的时候，他也掩耳不听我的祷告。'),
('CNV', '耶利米哀歌', 25, 3, 9, '他用砍凿好的石头堵塞我的道路，他使我的路径曲折。'),
('CNV', '耶利米哀歌', 25, 3, 10, '他像熊埋伏着，又像狮子在藏匿的地方，等候攻击我。'),
('CNV', '耶利米哀歌', 25, 3, 11, '他把我拖离大路，把我撕碎，弃我于荒野。'),
('CNV', '耶利米哀歌', 25, 3, 12, '他拉开了他的弓，立我作箭靶子。'),
('CNV', '耶利米哀歌', 25, 3, 13, '他把他箭囊中的箭，射进我的肺腑。'),
('CNV', '耶利米哀歌', 25, 3, 14, '我成了众民讥笑的对象，他们终日以我为歌嘲讽我（全句或译：“我成了众民的笑柄，他们终日喝颂的讽歌”）。'),
('CNV', '耶利米哀歌', 25, 3, 15, '他使我饱尝苦菜，饱享苦堇。'),
('CNV', '耶利米哀歌', 25, 3, 16, '他用沙石使我的牙齿破碎，把我践踏在灰尘中。'),
('CNV', '耶利米哀歌', 25, 3, 17, '你使我失去了平安，我已忘记了福乐是什么。'),
('CNV', '耶利米哀歌', 25, 3, 18, '所以我说：“我的力量已消失了，我从主所得的盼望也没有了。”'),
('CNV', '耶利米哀歌', 25, 3, 19, '回忆起我的困苦飘流，就象是苦堇和毒草。'),
('CNV', '耶利米哀歌', 25, 3, 20, '每逢我的心想起往事，我的心就消沉。'),
('CNV', '耶利米哀歌', 25, 3, 21, '但我的心一想起下面这件事，我就有指望。'),
('CNV', '耶利米哀歌', 25, 3, 22, '主的慈爱永不断绝，他的怜悯永不止息。'),
('CNV', '耶利米哀歌', 25, 3, 23, '每天早晨都是新的；你的信实多么广大！'),
('CNV', '耶利米哀歌', 25, 3, 24, '我心里说：“主是我的业分，所以，我必仰望他。”'),
('CNV', '耶利米哀歌', 25, 3, 25, '主善待等候他的和心里寻求他的人。'),
('CNV', '耶利米哀歌', 25, 3, 26, '安静等候主的救恩，是多么的美好！'),
('CNV', '耶利米哀歌', 25, 3, 27, '人在幼年时就负轭，是多么的美好！'),
('CNV', '耶利米哀歌', 25, 3, 28, '他要无言独坐，因为这是主加在他身上的。'),
('CNV', '耶利米哀歌', 25, 3, 29, '他要把自己的口埋于尘土中，或者还有盼望。'),
('CNV', '耶利米哀歌', 25, 3, 30, '他要让人打他的脸颊，要饱受凌辱。'),
('CNV', '耶利米哀歌', 25, 3, 31, '主必不会永远丢弃人。'),
('CNV', '耶利米哀歌', 25, 3, 32, '他虽然使人忧愁，却必照着他丰盛的慈爱施怜悯。'),
('CNV', '耶利米哀歌', 25, 3, 33, '因为他心里本不是要人受困苦，或是要世人愁苦。'),
('CNV', '耶利米哀歌', 25, 3, 34, '人把地上所有被囚的，都践踏在脚下，'),
('CNV', '耶利米哀歌', 25, 3, 35, '或在至高者面前，屈枉正直，'),
('CNV', '耶利米哀歌', 25, 3, 36, '或在诉讼的事上颠倒是非，主不都看见吗？'),
('CNV', '耶利米哀歌', 25, 3, 37, '除非主命定，谁能说成，就成了呢？'),
('CNV', '耶利米哀歌', 25, 3, 38, '或祸或福，不都是出于至高者的口吗？'),
('CNV', '耶利米哀歌', 25, 3, 39, '人活在世上，因自己的罪受惩罚，为什么发怨言呢？'),
('CNV', '耶利米哀歌', 25, 3, 40, '我们要检讨和省察自己的行为，然后归向主。'),
('CNV', '耶利米哀歌', 25, 3, 41, '我们要向天上的神，诚心举手祷告：'),
('CNV', '耶利米哀歌', 25, 3, 42, '“我们犯罪悖逆，你并不赦免。'),
('CNV', '耶利米哀歌', 25, 3, 43, '你被怒气笼罩着，你追赶我们，杀戮我们，毫不顾惜。'),
('CNV', '耶利米哀歌', 25, 3, 44, '你用密云把自己遮蔽起来，以致我们的祷告不能达到你那里。'),
('CNV', '耶利米哀歌', 25, 3, 45, '你使我们在万族中，成了渣滓和废物。'),
('CNV', '耶利米哀歌', 25, 3, 46, '我们所有的仇敌，都张开口攻击我们。'),
('CNV', '耶利米哀歌', 25, 3, 47, '我们遭遇的，只是恐惧、陷阱、毁坏和灭亡。”'),
('CNV', '耶利米哀歌', 25, 3, 48, '我的眼泪像江河流下，都因我的人民的灭亡。'),
('CNV', '耶利米哀歌', 25, 3, 49, '我的眼泪涌流不停，总不止息，'),
('CNV', '耶利米哀歌', 25, 3, 50, '直到主垂顾，从天上关注。'),
('CNV', '耶利米哀歌', 25, 3, 51, '因眼见我城中众民的遭遇，我的心很痛苦。'),
('CNV', '耶利米哀歌', 25, 3, 52, '那些无故与我为敌的人追捕我，像追捕雀鸟一样。'),
('CNV', '耶利米哀歌', 25, 3, 53, '他们把我投在坑中要结束我的性命，又把石头抛在我身上；')
on conflict (version, book, chapter, verse) do nothing;
insert into public.bible_verses (version, book, book_index, chapter, verse, text) values
('CNV', '耶利米哀歌', 25, 3, 54, '水淹过我的头，我说：“我要死了！”'),
('CNV', '耶利米哀歌', 25, 3, 55, '主啊，我从坑的最深处呼求你的名，'),
('CNV', '耶利米哀歌', 25, 3, 56, '你曾经垂听我的声音，现在求你不要掩耳不听我求救的呼声。'),
('CNV', '耶利米哀歌', 25, 3, 57, '我每逢呼求你的时候，你就靠近我，说：“不要惧怕！”'),
('CNV', '耶利米哀歌', 25, 3, 58, '主啊！你为我的案件申辩，赎回了我的性命。'),
('CNV', '耶利米哀歌', 25, 3, 59, '主啊，你看见了我的冤屈，求你为我主持公道。'),
('CNV', '耶利米哀歌', 25, 3, 60, '你已看见了他们种种的仇恨，以及所有害我的阴谋。'),
('CNV', '耶利米哀歌', 25, 3, 61, '主啊！你已听见了他们的辱骂，以及所有害我的计谋；'),
('CNV', '耶利米哀歌', 25, 3, 62, '你也听见了那些起来攻击我的人嘴里的话，以及他们终日要攻击我的企图。'),
('CNV', '耶利米哀歌', 25, 3, 63, '你看，他们或坐下或起来，我都成了他们歌唱嘲笑的对象。'),
('CNV', '耶利米哀歌', 25, 3, 64, '主啊！求你按着他们手所作的，报应他们！'),
('CNV', '耶利米哀歌', 25, 3, 65, '求你使他们的心顽梗，愿你的咒诅临到他们。'),
('CNV', '耶利米哀歌', 25, 3, 66, '求你在烈怒中追赶他们，从主管治的天下除灭他们。'),
('CNV', '耶利米哀歌', 25, 4, 1, '黄金怎么竟然失去光泽，纯金怎么竟然变色？圣殿的石头都被抛弃在各街头上。'),
('CNV', '耶利米哀歌', 25, 4, 2, '锡安尊贵的众民，本来和精金一样贵重；现在怎么竟被看为瓦器，好像陶匠手中所作的呢？'),
('CNV', '耶利米哀歌', 25, 4, 3, '野狗尚且用乳房哺养它们的幼儿；但我的众民变得多么残忍，像旷野的鸵鸟一样。'),
('CNV', '耶利米哀歌', 25, 4, 4, '婴儿的舌头因干渴而紧贴上膛；孩童求饼，却没有人分给他们。'),
('CNV', '耶利米哀歌', 25, 4, 5, '那些从前吃美食的，现今都在街上孤单凄凉；那些从前在豪奢生活中长大的，现今却在垃圾堆中打滚。'),
('CNV', '耶利米哀歌', 25, 4, 6, '我众民（“我众民”原文作“我子民的女子”）的罪孽比所多玛的罪恶更大；所多玛在转眼之间倾覆了，尽管无人攻击它。'),
('CNV', '耶利米哀歌', 25, 4, 7, '锡安的贵族素来比雪更明亮，比奶更洁白；他们的身体比红宝石更红润，他们的样貌像蓝宝石一样美丽。'),
('CNV', '耶利米哀歌', 25, 4, 8, '现在他们的面貌比煤炭还黑，在街上再没有人认得他们；他们皮包骨头，枯瘦如柴。'),
('CNV', '耶利米哀歌', 25, 4, 9, '那些死于刀下的比饿死的还好；饿死的因缺乏田间的出产，就日渐消瘦而死亡。'),
('CNV', '耶利米哀歌', 25, 4, 10, '慈心的妇人亲手烹煮自己所生的孩子；在我众民（“我众民”原文作“我子民的女子”）遭毁灭的时候，孩子竟成了母亲的食物。'),
('CNV', '耶利米哀歌', 25, 4, 11, '主大发震怒，倾倒他的烈怒；他在锡安放火，吞灭了锡安的根基。'),
('CNV', '耶利米哀歌', 25, 4, 12, '地上的君王，以及世上所有的居民都不相信，会有任何敌人和仇敌攻进耶路撒冷的城门。'),
('CNV', '耶利米哀歌', 25, 4, 13, '因为锡安先知的罪恶，和祭司的罪孽，就是他们在城中流了义人的血，'),
('CNV', '耶利米哀歌', 25, 4, 14, '所以，他们像瞎子在街上流荡，他们被血玷污，没有人可以触摸他们的衣服。'),
('CNV', '耶利米哀歌', 25, 4, 15, '有人向他们喊叫：“走开！你们不洁的人；走开！走开！不要触摸我。”他们到处逃亡飘流的时候，列国的人就说：“他们再不能在这里寄居。”'),
('CNV', '耶利米哀歌', 25, 4, 16, '主亲临（“主亲临”直译作“主的面”）分散他们，不再看顾他们；人不再尊重祭司，也不厚待长老。'),
('CNV', '耶利米哀歌', 25, 4, 17, '我们徒然等待帮助，等到双目失去视力；我们在瞭望台上期望一个不能拯救我们的国家来临。'),
('CNV', '耶利米哀歌', 25, 4, 18, '敌人追踪我们，使我们不敢在自己的街道上行走。我们的结局近了，我们的日子满了；我们的结局已经到了。'),
('CNV', '耶利米哀歌', 25, 4, 19, '追赶我们的比空中的鹰还快；他们在山上追赶我们，在旷野埋伏攻击我们。'),
('CNV', '耶利米哀歌', 25, 4, 20, '主所膏立的，我们鼻孔的气息，在他们的陷坑中被捉住；我们论到他曾说：“我们要在他的荫庇之下，在列国中存活。”'),
('CNV', '耶利米哀歌', 25, 4, 21, '以东人哪，乌斯地的居民哪，欢喜快乐吧！这杯也要传到你那里，你必喝醉以致赤身露体。'),
('CNV', '耶利米哀歌', 25, 4, 22, '锡安的居民（“居民”原文作“女子”）哪！你的刑罚已经受够了，主必不再使你流亡；以东的居民哪！他必惩罚你的罪孽，揭露你的罪恶。'),
('CNV', '耶利米哀歌', 25, 5, 1, '主啊！求你记念我们所遭遇的！垂顾关注我们的耻辱。'),
('CNV', '耶利米哀歌', 25, 5, 2, '我们的产业转归外人，我们的房屋归给异族。'),
('CNV', '耶利米哀歌', 25, 5, 3, '我们成为孤儿，没有父亲，我们的母亲好像寡妇一样。'),
('CNV', '耶利米哀歌', 25, 5, 4, '我们所喝的水要用银子买，我们的柴也付代价而得。'),
('CNV', '耶利米哀歌', 25, 5, 5, '我们被人追赶，颈项带上重轭；我们疲乏，得不着歇息。'),
('CNV', '耶利米哀歌', 25, 5, 6, '我们臣服埃及和亚述，为要得着粮食充饥。'),
('CNV', '耶利米哀歌', 25, 5, 7, '我们的先祖犯了罪，现在他们不在了；我们却要担负他们的罪孽。'),
('CNV', '耶利米哀歌', 25, 5, 8, '奴仆辖制我们；没有人救我们脱离他们的手。'),
('CNV', '耶利米哀歌', 25, 5, 9, '因为旷野有刀剑的威胁，我们要冒生命的危险才得到粮食。'),
('CNV', '耶利米哀歌', 25, 5, 10, '我们因饥饿而发烧，我们的皮肤好像火炉一般的热。'),
('CNV', '耶利米哀歌', 25, 5, 11, '妇女在锡安被污辱，处女在犹大的城镇被强暴。'),
('CNV', '耶利米哀歌', 25, 5, 12, '众领袖被敌人吊起来；长老也不受人尊敬。'),
('CNV', '耶利米哀歌', 25, 5, 13, '青年人推磨吃苦；孩童因背木柴而跌倒。'),
('CNV', '耶利米哀歌', 25, 5, 14, '众长老不再坐在城门口；青年人不再唱歌作乐。'),
('CNV', '耶利米哀歌', 25, 5, 15, '我们心里不再欢乐；我们的舞蹈变为哀哭。'),
('CNV', '耶利米哀歌', 25, 5, 16, '冠冕从我们的头上掉下来。我们有祸了；因为我们犯了罪。'),
('CNV', '耶利米哀歌', 25, 5, 17, '为了这事，我们心里愁烦；为了这事，我们的眼睛昏花；'),
('CNV', '耶利米哀歌', 25, 5, 18, '因为锡安山荒凉，野狗就在山上到处出没。'),
('CNV', '耶利米哀歌', 25, 5, 19, '但主啊，你永远坐着为王；你的宝座代代长存。'),
('CNV', '耶利米哀歌', 25, 5, 20, '你为什么永远忘记我们？为什么长久离弃我们？'),
('CNV', '耶利米哀歌', 25, 5, 21, '主啊！除非你真的弃绝我们，你向我们所发的怒气难收，不然，求你使我们归向你，好使我们回转过来；求你更新我们的日子，像古时一样。'),
('CNV', '以西结书', 26, 1, 1, '第三十年四月五日，我正在迦巴鲁河边的时候，天开了，我就看见神的异象；那时，我是在被掳的人中间。'),
('CNV', '以西结书', 26, 1, 2, '（当天是约雅斤王被掳后第五年四月五日。'),
('CNV', '以西结书', 26, 1, 3, '在迦勒底人的地方，迦巴鲁河边，主的话确实临到布西的儿子以西结祭司。主的手在那里临到他身上。）'),
('CNV', '以西结书', 26, 1, 4, '我观望，看见有狂风从北方刮来，并有一块闪耀着火焰的很大的云，云的周围有光芒，在云中的火焰里，好像有发光的金属。'),
('CNV', '以西结书', 26, 1, 5, '在火中又有四个活物的形状，它们的样子是这样：它们都有人的形状。'),
('CNV', '以西结书', 26, 1, 6, '它们各有四个脸孔、四个翅膀。'),
('CNV', '以西结书', 26, 1, 7, '它们的腿是直的，脚掌像牛犊的蹄，都很灿烂，像擦亮了的铜。'),
('CNV', '以西结书', 26, 1, 8, '在它们四边的翅膀下都有人的手。它们四个活物的脸孔和翅膀是这样的：'),
('CNV', '以西结书', 26, 1, 9, '它们的翅膀互相接触，走动的时候，不必转身，都是朝着脸孔的方向行走。'),
('CNV', '以西结书', 26, 1, 10, '至于它们脸孔的形状，四个活物都各有一个人的脸孔，在右边各有一个狮子的脸孔，在左边各有一个牛的脸孔，此外各有一个鹰的脸孔；'),
('CNV', '以西结书', 26, 1, 11, '它们的脸孔就是这样。它们向上展开翅膀，各自用两个翅膀互相接触，用两个翅膀遮蔽身体。'),
('CNV', '以西结书', 26, 1, 12, '它们都是朝着脸孔的方向行走。灵往哪里去，它们就往哪里去。它们走动的时候，都不必转身。'),
('CNV', '以西结书', 26, 1, 13, '至于四个活物的形状，样子像烧着的火炭，又像火把。火在四活物中间到处闪耀。这火很明亮，有闪电从火中发出。'),
('CNV', '以西结书', 26, 1, 14, '四个活物往来奔走，好像闪电。'),
('CNV', '以西结书', 26, 1, 15, '我观看那些活物的时候，看见四个活物的旁边都有一个触地的轮子。'),
('CNV', '以西结书', 26, 1, 16, '四个轮子的样子与构造都是一个形状，它们好像闪耀的水苍玉，又好像轮子套着轮子。'),
('CNV', '以西结书', 26, 1, 17, '轮子可以向四方移动，移动的时候，不必转向。'),
('CNV', '以西结书', 26, 1, 18, '轮辋很高，十分可畏，四个轮辋都布满了眼睛。'),
('CNV', '以西结书', 26, 1, 19, '活物走动的时候，它们旁边的轮子也随着移动。活物从地上升起的时候，轮子也随着升起。'),
('CNV', '以西结书', 26, 1, 20, '灵往哪里去，活物就往哪里去，轮子也随着它们升起，因为活物的灵是在轮子里面。'),
('CNV', '以西结书', 26, 1, 21, '活物走动，轮子也随着移动；活物站着不动，轮子也不动；活物从地上升起，轮子也随着升起，因为活物的灵是在轮子里面。'),
('CNV', '以西结书', 26, 1, 22, '在活物的头顶上面，有穹苍的形状，好像闪耀的水晶，十分可畏，在活物的头顶上面张开。'),
('CNV', '以西结书', 26, 1, 23, '在穹苍下面，活物的翅膀伸直张开，互相接触；各自用两个翅膀遮蔽身体。'),
('CNV', '以西结书', 26, 1, 24, '活物走动的时候，我听见它们翅膀的响声，像洪水的声音，也像全能者的声音，又像军队喧嚷的声音。它们站着不动的时候，翅膀就垂下来。'),
('CNV', '以西结书', 26, 1, 25, '有声音从它们头顶上面的穹苍发出来；它们站着不动的时候，翅膀就垂下来。'),
('CNV', '以西结书', 26, 1, 26, '在它们头顶的穹苍上面，有宝座的形状，好像蓝宝石的样子。在宝座的形象上面，有一个样子像人的形象。'),
('CNV', '以西结书', 26, 1, 27, '我看见在那仿佛是他腰部以上，好像闪耀的金属，又好像有火四面包围。在那仿佛是他腰部以下，我又看见好像有火，光芒环绕着他。'),
('CNV', '以西结书', 26, 1, 28, '下雨的日子，云中彩虹的样子怎样，环绕他的光芒的样子也怎样。这就是主荣耀的形状的样子。我一看见，就俯伏在地上，跟着听见有说话的声音。'),
('CNV', '以西结书', 26, 2, 1, '他对我说：“人子啊！站起来，我要跟你说话。”'),
('CNV', '以西结书', 26, 2, 2, '他对我说话的时候，灵就进到我里面，使我站立起来；我又听见对我说话的声音。'),
('CNV', '以西结书', 26, 2, 3, '他对我说：“人子啊！我差派你到以色列人那里去，就是到那背叛我的叛逆国民那里去！他们和他们的列祖都得罪了我，直到今日。'),
('CNV', '以西结书', 26, 2, 4, '这人民十分顽固，心里刚硬，我差派你到他们那里去。你要对他们说：‘主神这样说。’'),
('CNV', '以西结书', 26, 2, 5, '他们或听或不听（他们原是叛逆的民族），也必知道在他们中间有一位先知。'),
('CNV', '以西结书', 26, 2, 6, '“人子啊！至于你，虽然荆棘和蒺藜在你周围，你又住在蝎子群中，你不要怕他们，也不要怕他们讲的话。他们原是叛逆的民族，你总不要怕他们讲的话，在他们面前，也不要惊惶。'),
('CNV', '以西结书', 26, 2, 7, '他们或听或不听，你只要把我的话告诉他们，他们原是叛逆的。'),
('CNV', '以西结书', 26, 2, 8, '“人子啊！至于你，你要听我对你讲的话。不要叛逆我，像那叛逆的民族一样。张开你的口，把我赐给你的吃下去！”'),
('CNV', '以西结书', 26, 2, 9, '我观看，看见一只手向我伸过来，手中有一卷书卷。'),
('CNV', '以西结书', 26, 2, 10, '他把书卷在我面前展开，书卷内外都写上字，写的是哀歌、悲叹和灾祸。'),
('CNV', '以西结书', 26, 3, 1, '他对我说：“人子啊，把你得到的吃下去吧！吃下这书卷，然后去向以色列家说话。”'),
('CNV', '以西结书', 26, 3, 2, '于是我把口张开，他就给我吃下那书卷。'),
('CNV', '以西结书', 26, 3, 3, '他又对我说：“人子啊！把我赐给你的那书卷吃下去，填满你的肚子。”于是我吃了，这书卷在我口里像蜜糖一样甘甜。'),
('CNV', '以西结书', 26, 3, 4, '他对我说：“人子啊，你去！到以色列家那里，把我的话告诉他们。'),
('CNV', '以西结书', 26, 3, 5, '你受差派不是到一个说话难明、言语难懂的民族那里去，而是到以色列家去；'),
('CNV', '以西结书', 26, 3, 6, '不是到说话难明、言语难懂的众多民族那里去，他们的话是你听不懂的。但是，如果我差派你到他们那里去，他们必听从你。'),
('CNV', '以西结书', 26, 3, 7, '以色列家却不肯听从你，因为他们不肯听从我，整个以色列家都是额坚心硬的。'),
('CNV', '以西结书', 26, 3, 8, '看哪！我要使你的脸像他们的脸一样坚硬，使你的前额像他们的前额一样坚硬。'),
('CNV', '以西结书', 26, 3, 9, '我要使你的额好像最坚硬的宝石，比火石更硬。他们虽然是叛逆的民族，你却不要怕他们，在他们面前，也不要惊惶。”'),
('CNV', '以西结书', 26, 3, 10, '他又对我说：“人子啊！我对你说的一切话，你都要留心听，记在心里。'),
('CNV', '以西结书', 26, 3, 11, '你去，到被掳的人民那里，向他们宣讲；他们或听或不听，你只要对他们说：‘主神这样说。’”'),
('CNV', '以西结书', 26, 3, 12, '那时，灵使我升起，我就听见后面有轰轰的响声：“主的居所显现出来的荣耀是应当称颂的！”'),
('CNV', '以西结书', 26, 3, 13, '我又听见那些活物的翅膀彼此相碰的声音和活物旁边的轮子的声音，以及轰轰的响声。'),
('CNV', '以西结书', 26, 3, 14, '灵使我升起，把我提去。那时我心灵忿激、愁苦。主的手强而有力临到我身上。'),
('CNV', '以西结书', 26, 3, 15, '于是我来到提勒．亚毕被掳的人那里，他们住在迦巴鲁河边。我在他们居住的地方坐了七天，在他们中间震惊得不知所措。'),
('CNV', '以西结书', 26, 3, 16, '过了七天，主的话临到我说：'),
('CNV', '以西结书', 26, 3, 17, '“人子啊，我立了你作以色列家守望的人，所以你要聆听我口中的话，替我警告他们。'),
('CNV', '以西结书', 26, 3, 18, '如果我对恶人说：‘你必定死亡！’你却不警告他，也不警戒他离开恶行，好救他的性命，这恶人就必因自己的罪孽死亡。但我要因他的死追究你。'),
('CNV', '以西结书', 26, 3, 19, '如果你警告恶人，他仍不离开他的罪恶和他的恶行，他就必因自己的罪孽死亡，你却救了自己的性命。'),
('CNV', '以西结书', 26, 3, 20, '如果义人偏离正义，行事邪恶，我必把绊脚石放在他面前，他必定死亡；因为你没有警告他，他必因自己的罪死亡。他素常所行的义，也必不被记念。但我要因他的死追究你。'),
('CNV', '以西结书', 26, 3, 21, '如果你警告义人不要犯罪，他就不犯罪。他因为接受警告，就必存活，你也救了自己的性命。”'),
('CNV', '以西结书', 26, 3, 22, '主的手在那里临到我身上，他对我说：“你起来，出到平原去，在那里我要向你说话。”'),
('CNV', '以西结书', 26, 3, 23, '于是，我起来，出到平原去，看见主的荣耀停在那里，这荣耀就像我在迦巴鲁河边看见的一样。于是我俯伏在地。'),
('CNV', '以西结书', 26, 3, 24, '灵进到我里面，使我站立起来，主对我说：“你进去，把自己关在家里。'),
('CNV', '以西结书', 26, 3, 25, '人子啊！人要用绳子把你捆绑起来，使你不能出到他们中间去。'),
('CNV', '以西结书', 26, 3, 26, '我要使你的舌头贴住上膛，使你变成哑巴，不能作责备他们的人，因为他们是叛逆的民族。'),
('CNV', '以西结书', 26, 3, 27, '但我对你说话的时候，我必开你的口，你就要对他们说：‘主神这样说。’肯听的就让他听，不肯听的，就由他不听吧，因为他们是叛逆的民族。”'),
('CNV', '以西结书', 26, 4, 1, '“人子啊！你要拿一块砖头，放在你面前，在上面刻一座城，代表耶路撒冷。'),
('CNV', '以西结书', 26, 4, 2, '然后安放围城设施，建造围城高墙，筑起攻城土垒，摆列兵营，四周架起攻城锤。'),
('CNV', '以西结书', 26, 4, 3, '你又要拿一个铁的煎盘，放在你和城的中间当作铁墙。你要面向着城，象征城要被围困，你就是围攻那城的。这要作以色列家的预兆。'),
('CNV', '以西结书', 26, 4, 4, '“你要向左边侧卧，承担以色列家的罪孽。你向左边侧卧多少日子，你担当他们的罪孽也是多少日子。'),
('CNV', '以西结书', 26, 4, 5, '我已经给你定了日子的数目，就是三百九十天，等于他们作孽的年数，你要在这些日子担当以色列家的罪孽。'),
('CNV', '以西结书', 26, 4, 6, '这些日子满了以后，你要再向右边侧卧，担当犹大家的罪孽，我已经给你定了四十天，一天等于一年。'),
('CNV', '以西结书', 26, 4, 7, '你要面向着被围困的耶路撒冷，赤露着膀臂，说预言攻击这城。'),
('CNV', '以西结书', 26, 4, 8, '我要用绳子把你捆绑起来，使你不能转身，直等到你围困城的日子满了。'),
('CNV', '以西结书', 26, 4, 9, '“你要拿小麦、大麦、豆子、扁豆、粟米和粗麦，放在一个器皿里，给自己做饼。在你侧卧的三百九十天里，你都要吃这些饼。'),
('CNV', '以西结书', 26, 4, 10, '你所吃的食物要有一定分量，每天二百三十克，要在指定的时候吃。'),
('CNV', '以西结书', 26, 4, 11, '你喝的水也要有一定分量，每天半公升，要在指定的时候喝。'),
('CNV', '以西结书', 26, 4, 12, '你吃这些饼，要像吃烙的大麦饼一样，但要用人粪在众人面前烧烤。”'),
('CNV', '以西结书', 26, 4, 13, '主说：“以色列人在我赶他们去的列国中，也要这样吃不洁净的食物。”'),
('CNV', '以西结书', 26, 4, 14, '我说：“主神啊！我从来没有玷污过自己。我从小到现在都没有吃过已经死去的，或是野兽撕裂的动物，不洁净的肉从没有进过我的口。”'),
('CNV', '以西结书', 26, 4, 15, '于是他对我说：“你看，我准你用牛粪代替人粪，你可以在牛粪上烤你的饼。”'),
('CNV', '以西结书', 26, 4, 16, '他又对我说：“人子啊，我要断绝耶路撒冷的粮食。他们要满心忧虑，吃配给的口粮；十分惊惶，喝配给的水。'),
('CNV', '以西结书', 26, 4, 17, '他们缺粮缺水，各人都必惊惶，因自己的罪孽衰弱而死。”'),
('CNV', '以西结书', 26, 5, 1, '“人子啊！你要拿一把利剑，当作理发匠的剃刀，剃你的头和刮你的胡子，把须发放在天平上称，然后把它们分成几份。'),
('CNV', '以西结书', 26, 5, 2, '围困这城的日子满了，你要拿须发的三分之一在城中用火烧掉，又拿三分之一在城的周围用刀剁碎，三分之一撒在风中，我还要拔刀追赶它们。'),
('CNV', '以西结书', 26, 5, 3, '你要在这些须发中取几根，用你的衣角把它们包起来。'),
('CNV', '以西结书', 26, 5, 4, '再从这几根须发中取一部分投在火里焚烧；火必从那里蔓延到以色列全家。”'),
('CNV', '以西结书', 26, 5, 5, '主神这样说：“这就是耶路撒冷！我曾把她安置在列国中间，万邦环绕着她。'),
('CNV', '以西结书', 26, 5, 6, '但她违背我的典章，行恶胜过列国；触犯我的律例，比环绕着她的万邦更坏。她弃绝我的典章，不遵行我的律例。”'),
('CNV', '以西结书', 26, 5, 7, '主神这样说：“你们比你们四围的列国更叛逆，不遵行我的律例，不遵守我的典章，连你们四围列国的法规你们也不遵守（有些抄本没有“也不”）。”'),
('CNV', '以西结书', 26, 5, 8, '所以，主神这样说：“看哪！我要敌对你。我要在你中间，在列国的眼前，施行审判。'),
('CNV', '以西结书', 26, 5, 9, '我要因你一切可憎的事在你中间施行我未曾行过，以后也不会这样施行的审判。'),
('CNV', '以西结书', 26, 5, 10, '因此，在你中间，父亲要吃儿子，儿子要吃父亲。我要向你施行审判，把你余剩的众人分散到四方去。'),
('CNV', '以西结书', 26, 5, 11, '“我指着我的永生起誓（这是主神的宣告），你既然用你一切可憎的偶像和一切可厌的事来玷污我的圣所，我必收回对你的恩宠，我的眼必不顾惜你，我也不怜恤你。'),
('CNV', '以西结书', 26, 5, 12, '你的人民三分之一必在你中间因瘟疫死亡，因饥荒消灭；三分之一必在你周围因刀剑倒毙；三分之一，我要分散到四方去，我还要拔刀追赶他们。'),
('CNV', '以西结书', 26, 5, 13, '“这样我的怒气才可以发尽，我向他们所发的烈怒才可以平息，自己才得到舒畅。我向他们所发的烈怒完全发尽的时候，他们就知道我主说过的话是出于嫉恨的心。'),
('CNV', '以西结书', 26, 5, 14, '我要使你变成荒地，使你在你四围的列国中和在所有路过的人眼前，成为羞辱的对象。'),
('CNV', '以西结书', 26, 5, 15, '我以怒气、烈怒和忿怒的责备向你施行审判的时候，你就必在你四围的列国中成为羞辱、讥讽和令人惊骇的对象，也成了他们的警戒。这是我主说的。'),
('CNV', '以西结书', 26, 5, 16, '我射出饥荒和毁灭的毒箭的时候，是为了毁灭你们。我要使你们的饥荒加剧，断绝你们粮食的供应。'),
('CNV', '以西结书', 26, 5, 17, '我要差遣饥荒和恶兽到你们那里去，使你丧掉儿女；在你中间必到处发生瘟疫和流血的事；我也必使刀剑临到你。这是我主说的。”'),
('CNV', '以西结书', 26, 6, 1, '主的话临到我说：'),
('CNV', '以西结书', 26, 6, 2, '“人子啊！你要面向以色列的群山说预言，'),
('CNV', '以西结书', 26, 6, 3, '说：‘以色列的群山，当听主神的话！主神对大山、小山、溪涧和山谷这样说：看哪！我必使刀剑临到你，毁灭你们的邱坛。'),
('CNV', '以西结书', 26, 6, 4, '你们的祭坛必然荒废，你们的香坛要被打碎；我要使你们被杀的人倒在你们的偶像面前。'),
('CNV', '以西结书', 26, 6, 5, '我要把以色列人的尸体放在他们的偶像面前，又把你们的骸骨抛散在你们祭坛的周围。'),
('CNV', '以西结书', 26, 6, 6, '在你们居住的一切地方，城镇都必荒凉，邱坛都必荒废，以致你们的祭坛荒废被弃，你们的偶像被打碎、被消灭，你们的香坛要被砍下，你们所制造的要被除灭；'),
('CNV', '以西结书', 26, 6, 7, '被杀的人必倒在你们中间，你们就知道我是主。'),
('CNV', '以西结书', 26, 6, 8, '“‘但我要保留一些余剩的人，你们分散在各地的时候，你们必有人在列国中从刀剑下逃出来。'),
('CNV', '以西结书', 26, 6, 9, '那时，逃脱的人必在被掳去的列国中想起我怎样为了他们而伤痛，因为他们动了淫乱的心离弃我，他们邪淫的眼恋慕偶像；那时他们必为了自己所行的恶事和他们一切可憎的事厌恶自己。'),
('CNV', '以西结书', 26, 6, 10, '他们必知道我是主，我说要降这灾祸在他们身上的话并不是空话。’”'),
('CNV', '以西结书', 26, 6, 11, '主神这样说：“你要拍手顿足，说：‘哀哉！因以色列家一切可憎的恶事，他们必倒在刀剑、饥荒、瘟疫之下。’'),
('CNV', '以西结书', 26, 6, 12, '在远处的必因瘟疫死亡，在近处的必倒在刀剑之下，那余下被围困的也必因饥荒死亡。我必这样在他们身上完全发尽我的烈怒。'),
('CNV', '以西结书', 26, 6, 13, '他们被杀的人倒在他们偶像的中间，在他们祭坛的周围，就是在各高冈各山顶上，在每一棵翠绿的树下和茂盛的橡树下，就是他们献馨香的祭给一切偶像的地方。那时，他们就知道我是主。'),
('CNV', '以西结书', 26, 6, 14, '我必伸手攻击他们，使他们一切居住的地方，从旷野到第伯拉他，都变成非常荒凉，他们就知道我是主。”'),
('CNV', '以西结书', 26, 7, 1, '主的话临到我说：'),
('CNV', '以西结书', 26, 7, 2, '“人子啊！主神对以色列地这样说：‘终局到了！终局临到这地的四境了！'),
('CNV', '以西结书', 26, 7, 3, '现在终局已经临到你了。我要发怒攻击你，按着你的行为审判你，照着你一切可憎的事报应你。'),
('CNV', '以西结书', 26, 7, 4, '我的眼必不顾惜你，我也不怜恤你，我却要按着你的行为，照着你中间可憎的事报应你，你们就知道我是主。’'),
('CNV', '以西结书', 26, 7, 5, '主神这样说：‘看哪，灾祸，独特的灾祸，临到了！'),
('CNV', '以西结书', 26, 7, 6, '终局到了，终局临到了，它已经起来跟你作对。看哪，它临到了！'),
('CNV', '以西结书', 26, 7, 7, '这地的居民哪，灾害临到你了！时候到了，日子近了，是混乱喧嚷的日子，不是山上欢呼的日子。'),
('CNV', '以西结书', 26, 7, 8, '现在我快要把我的烈怒倒在你身上，向你完全发尽我的怒气。我要按着你的行为审判你，照着你一切可憎的事报应你。'),
('CNV', '以西结书', 26, 7, 9, '我的眼必不顾惜，我也不怜恤。我却要按着你的行为，照着你中间可憎的事报应你，你们就知道击打你们的是我主。'),
('CNV', '以西结书', 26, 7, 10, '“‘看哪，这日子到了！灾害已经发出，杖已经开花，狂傲已经发芽。'),
('CNV', '以西结书', 26, 7, 11, '强暴兴起，成了惩罚邪恶的杖，他们无一存留，他们的群众都不在了。他们的财富没有了，他们中间也没有尊荣。'),
('CNV', '以西结书', 26, 7, 12, '时候到了，日子近了，买的不必欢喜，卖的不用忧愁；因为烈怒要临到众人身上。'),
('CNV', '以西结书', 26, 7, 13, '卖的人虽然还活着，却不能得回所卖的。因为这个关乎众人的异象必不更改。因为罪孽的缘故，没有人能保全自己的性命。'),
('CNV', '以西结书', 26, 7, 14, '“‘他们吹了号角，准备了一切，却没有人出去作战；因为我的烈怒要临到众人身上。'),
('CNV', '以西结书', 26, 7, 15, '城外有刀剑，城内有瘟疫和饥荒；在田野的必死在刀下，在城里的必被饥荒和瘟疫吞灭。'),
('CNV', '以西结书', 26, 7, 16, '他们中间逃脱的，必因自己的罪孽在山上发出哀声，像谷中的鸽子哀鸣一样。'),
('CNV', '以西结书', 26, 7, 17, '他们的手都发软，他们的膝像水一般软弱。'),
('CNV', '以西结书', 26, 7, 18, '他们必用麻布束腰，战兢把他们遮盖，各人的脸上满是羞愧，各人的头上都光秃。'),
('CNV', '以西结书', 26, 7, 19, '他们要把自己的银子抛在街上，把自己的金子当作污秽之物。在主发怒的日子，他们的金银不能拯救他们，不能满足他们的心，也不能填满他们的肚腹，因为这些金银都成了叫他们落在罪孽里的绊脚石。'),
('CNV', '以西结书', 26, 7, 20, '他们以美丽的饰物为夸耀，又用这些来铸造可憎可厌的偶像，因此我要使它们成为污秽之物。'),
('CNV', '以西结书', 26, 7, 21, '我要把它们交在外族人的手里作掠物，给地上的恶人作战利品，他们必亵渎这些东西。'),
('CNV', '以西结书', 26, 7, 22, '我必转脸不看他们，让他们亵渎我的圣所。强盗要进那里去，亵渎那地方。'),
('CNV', '以西结书', 26, 7, 23, '你要制造锁链，因为这地满了血腥（“血腥”或译：“流血的审判”），这城满了强暴。'),
('CNV', '以西结书', 26, 7, 24, '我要使列国中最凶恶的人来占领他们的房屋；我要止息强盛者的骄傲，他们的圣所都被亵渎。'),
('CNV', '以西结书', 26, 7, 25, '惊恐临到，他们就求平安，却得不着。'),
('CNV', '以西结书', 26, 7, 26, '灾祸加上灾祸，坏消息加上坏消息，不绝而来，他们要向先知求异象，但是，祭司的教训、长老的指导，都必断绝，'),
('CNV', '以西结书', 26, 7, 27, '君王要悲哀，官长要把凄凉当作衣服穿上，那地人民的手都要发颤。我要按着他们的行为待他们，按着他们审判的法则审判他们，他们就知道我是主。’”'),
('CNV', '以西结书', 26, 8, 1, '第六年六月五日，我坐在家中，犹大的众长老也坐在我面前，在那里主神的灵降在我身上。'),
('CNV', '以西结书', 26, 8, 2, '我观看，见有一形状好像人（按照《马索拉文本》，“人”作“火”；两者在原文非常相似，现参照《七十士译本》翻译）的样子，在那仿佛是他腰部以下，有火的样子，在那仿佛是他腰部的以上有光辉的样子，好像闪耀的金属。'),
('CNV', '以西结书', 26, 8, 3, '他伸出一只形状像手的东西，抓住我的一绺头发；灵就把我提到天地之间，在神的异象中，他把我带往耶路撒冷，到圣殿北门内院的入口处，在那里有令神愤恨的偶像的座位，就是触动神愤恨的。'),
('CNV', '以西结书', 26, 8, 4, '不料，在那里有以色列神的荣耀，形状与我在平原所见的一样。'),
('CNV', '以西结书', 26, 8, 5, '他对我说：“人子啊！举目向北观看。”我就举目向北观看，见祭坛门的北面，在入口的地方，有令神愤恨的偶像。'),
('CNV', '以西结书', 26, 8, 6, '他又对我说：“人子啊！以色列家在这里所行的，就是他们行这极其可憎的事，使我远离我的圣所，你看见了吗？但你还要看见更加可憎的事。”'),
('CNV', '以西结书', 26, 8, 7, '他领我到院子的门口；我观看，见墙上有一个洞。'),
('CNV', '以西结书', 26, 8, 8, '他对我说：“人子啊，挖墙吧！”我就挖墙，不料，见有一道门。'),
('CNV', '以西结书', 26, 8, 9, '他对我说：“你进去，看看他们在这里所行可憎的恶事。”'),
('CNV', '以西结书', 26, 8, 10, '于是我进去观看，见四围的墙上刻着各种形状的爬行的动物，和可憎恶的走兽，以及以色列家所有的偶像。'),
('CNV', '以西结书', 26, 8, 11, '站在这些像面前的有以色列家的七十个长老，沙番的儿子雅撒尼亚也站在他们中间；各人手里拿着自己的香炉，香的烟往上升。'),
('CNV', '以西结书', 26, 8, 12, '他对我说：“人子啊！以色列家的众长老各在自己偶像的房间里暗中所行的，你看见了吗？他们说：‘主看不见我们，主已经离开这地了。’”'),
('CNV', '以西结书', 26, 8, 13, '他又对我说：“你还要看见他们行更加可憎的事。”'),
('CNV', '以西结书', 26, 8, 14, '他领我到主殿朝北的门口，在那里有些妇女坐着，为搭模斯哭泣。'),
('CNV', '以西结书', 26, 8, 15, '他对我说：“人子啊，你看见了吗？你还要看见比这些更可憎的事。”'),
('CNV', '以西结书', 26, 8, 16, '他又领我到主殿的内院，在主殿的门口，就是在走廊和祭坛中间，约有二十五个人，背向主的殿，面向着东方；他们正在朝着东面叩拜太阳。'),
('CNV', '以西结书', 26, 8, 17, '他对我说：“人子啊，你看见了吗？犹大家在这里行这可憎的事，还算小事吗？他们使这地充满了强暴，再三惹我发怒；看哪！他们把树枝拿到自己的鼻前。'),
('CNV', '以西结书', 26, 8, 18, '因此我要以烈怒待他们；我的眼必不顾惜，我也不怜恤；他们虽然在我耳中大声呼求，我还是不听他们。”'),
('CNV', '以西结书', 26, 9, 1, '我听见他大声呼叫说：“惩罚这城的啊！你们要近前来，各人手里拿着灭命的武器。”'),
('CNV', '以西结书', 26, 9, 2, '忽然，有六个人从朝北的上门那边走来，各人手里拿着杀人的武器；他们中间有一个人身穿细麻布衣服，腰间带着墨盒子；他们进来，站在铜祭坛旁边。'),
('CNV', '以西结书', 26, 9, 3, '以色列神的荣耀本来是在基路伯上面的，现在从那里移到殿的门槛；主把那身穿细麻布衣服，腰间带着墨盒子的人召来，'),
('CNV', '以西结书', 26, 9, 4, '对他说：“你要走遍耶路撒冷全城，那些因城中所行的一切可憎的事而叹息悲哀的人，你要在他们的额上画个记号。”'),
('CNV', '以西结书', 26, 9, 5, '我又听见他对其余的人说：“你们要跟随他走遍那城，进行杀戮；你们的眼不要顾惜，你们也不要怜恤。'),
('CNV', '以西结书', 26, 9, 6, '你们要从我的圣所开始，把老年人、少年人、少女、孩童和妇女都杀尽灭绝，只是那些额上有记号的人，你们都不可伤害。”于是他们从殿前那些长老开始杀戮。'),
('CNV', '以西结书', 26, 9, 7, '他又对他们说：“你们要玷污这殿，使这些院子充满被杀的人；你们出去吧！”于是他们出去，在城中进行杀戮。'),
('CNV', '以西结书', 26, 9, 8, '他们杀戮的时候，只留下我一个人，我就脸伏在地，呼叫说：“哎，主神啊！难道你要向耶路撒冷倾倒你的烈怒，使所有以色列余剩的人都灭绝么？”'),
('CNV', '以西结书', 26, 9, 9, '他对我说：“以色列家和犹大家罪大恶极，地上充满血腥，城内充满不义，因为他们说：‘主已经离开这地，他看不见我们了！’'),
('CNV', '以西结书', 26, 9, 10, '因此，我的眼必不顾惜，我也必不怜恤；我要把他们所行的报应在他们的头上。”'),
('CNV', '以西结书', 26, 9, 11, '那身穿细麻布衣服，腰间带着墨盒子的人回报这事，说：“我已经照着你所吩咐我的行了。”'),
('CNV', '以西结书', 26, 10, 1, '我观看，见基路伯头顶以上的穹苍，有好像蓝宝石宝座的形状，显现出来。'),
('CNV', '以西结书', 26, 10, 2, '主对那身穿细麻布衣服的人说：“你进到基路伯以下的轮子之间那里去；从基路伯之间，用两手捧满火炭，然后把它们撒在城上。”他就在我眼前进去了。'),
('CNV', '以西结书', 26, 10, 3, '那人进去的时候，基路伯站在殿的右边，云彩充满了内院。'),
('CNV', '以西结书', 26, 10, 4, '主的荣耀从基路伯上面升到殿的门槛那里；殿里充满了云彩，院子也充满了主荣耀的光辉。'),
('CNV', '以西结书', 26, 10, 5, '基路伯的翅膀发出的声音在外院也可以听到，好像全能的神说话的声音。'),
('CNV', '以西结书', 26, 10, 6, '他吩咐那身穿细麻布衣服的人说：“你要从轮子之间，就是从基路伯之间取火。”那人就进去，站在一个轮子的旁边。'),
('CNV', '以西结书', 26, 10, 7, '有一个基路伯从众基路伯之间，伸手到他们中间的火那里去，取了些火，放在那身穿细麻布衣服的人手中；那人拿了火，就出去了。'),
('CNV', '以西结书', 26, 10, 8, '在那些基路伯的翅膀下面，可以看见人手的形状。'),
('CNV', '以西结书', 26, 10, 9, '我观看，见众基路伯旁边有四个轮子；每一个基路伯旁边都有一个轮子；轮子的样子好像闪耀的水苍玉。'),
('CNV', '以西结书', 26, 10, 10, '四个轮子的样子，都是一个形状，好像轮子套着轮子。'),
('CNV', '以西结书', 26, 10, 11, '轮子可以向四方移动，移动的时候，不必转向；基路伯头向哪一个方向走，它们就跟着移动；移动的时候，不必转向。'),
('CNV', '以西结书', 26, 10, 12, '基路伯的全身、背、手和翅膀，以及那些轮子，都布满了眼睛；四个基路伯的轮子都是这样。'),
('CNV', '以西结书', 26, 10, 13, '至于那些轮子，我听见它们称为“旋转的轮子”。'),
('CNV', '以西结书', 26, 10, 14, '每一个基路伯各有四个脸孔：第一是基路伯的脸孔，第二是人的脸孔，第三是狮子的脸孔，第四是鹰的脸孔。'),
('CNV', '以西结书', 26, 10, 15, '后来基路伯也升起（这些就是我在迦巴鲁河边所看见的活物）。'),
('CNV', '以西结书', 26, 10, 16, '基路伯移动的时候，轮子也在他们旁边移动；基路伯展开翅膀飞离地面的时候，轮子也不离开他们。'),
('CNV', '以西结书', 26, 10, 17, '他们站着不动，轮子也不动；他们升起的时候，轮子也与他们一同上升，因为活物的灵是在轮子里面。'),
('CNV', '以西结书', 26, 10, 18, '以后，主的荣耀离开殿的门槛，停在基路伯上面。'),
('CNV', '以西结书', 26, 10, 19, '基路伯离开的时候，他们在我眼前展开翅膀，飞离地面，轮子也与他们一起；他们停在主殿的东门口，在他们上面有以色列神的荣耀。'),
('CNV', '以西结书', 26, 10, 20, '这些是我在迦巴鲁河边所看见、在以色列神荣耀下面的活物，我就知道他们是基路伯。'),
('CNV', '以西结书', 26, 10, 21, '四个基路伯各有四个脸孔，四个翅膀；在翅膀下面有人手的形状。'),
('CNV', '以西结书', 26, 10, 22, '至于他们脸孔的形状，就像我从前在迦巴鲁河边所看见的一样。他们每个都是朝着脸孔的方向行走。'),
('CNV', '以西结书', 26, 11, 1, '灵把我提起来，带到主殿朝东的东门；在门口那里有二十五个人；我看见他们中间有人民的领袖押朔的儿子雅撒尼亚和比拿雅的儿子毗拉提。'),
('CNV', '以西结书', 26, 11, 2, '主对我说：“人子啊！这些就是图谋罪孽，在这城里设恶谋的人。'),
('CNV', '以西结书', 26, 11, 3, '他们说：‘建造房屋的时候还没有到；这城是锅，我们是肉。’'),
('CNV', '以西结书', 26, 11, 4, '因此，人子啊！你要说预言，要说预言攻击他们。”'),
('CNV', '以西结书', 26, 11, 5, '主的灵降在我身上，他对我说：“你要说：‘主这样说：以色列家啊！你们口里所说、心中所想的，我都知道。'),
('CNV', '以西结书', 26, 11, 6, '你们在这城里杀了许多人，使街道满了死人。'),
('CNV', '以西结书', 26, 11, 7, '因此，主神这样说：你们弃置在城中的死人就是肉，这城就是锅；至于你们，却要从城中被赶出去。'),
('CNV', '以西结书', 26, 11, 8, '你们惧怕刀剑，我就使刀剑临到你们，这是主神的宣告。'),
('CNV', '以西结书', 26, 11, 9, '我要把你们从城中赶出去，交在外族人的手里；我要向你们施行审判。'),
('CNV', '以西结书', 26, 11, 10, '你们必倒在刀下，我必审判你们，直到以色列的边境；你们就知道我是主。'),
('CNV', '以西结书', 26, 11, 11, '这城必不作你们的锅，你们也必不作其中的肉。我必审判你们直到以色列的边境；'),
('CNV', '以西结书', 26, 11, 12, '你们就知道我是主。这是因为你们没有遵行我的律例，也没有遵守我的典章，却效法你们周围列国的习俗去行。’”'),
('CNV', '以西结书', 26, 11, 13, '我正在说预言的时候，比拿雅的儿子毗拉提死了。于是我脸伏在地，大声呼叫，说：“哎，主神啊！难道你要把以色列余剩的人都尽行毁灭吗？”'),
('CNV', '以西结书', 26, 11, 14, '主的话临到我说：'),
('CNV', '以西结书', 26, 11, 15, '“人子啊！论到你的兄弟、你的亲属、与你一同被掳的人（“与你一同被掳的人”或译：“你的近亲”）和以色列全家，耶路撒冷的居民曾经这样说：‘他们远离了主，这地是赐给我们作产业的。’'),
('CNV', '以西结书', 26, 11, 16, '因此你要说：‘主神这样说：我虽然把他们远远地迁到列国之中，使他们分散在各地，我还要在他们所到的各地暂作他们的圣所。’'),
('CNV', '以西结书', 26, 11, 17, '因此你要说：‘主神这样说：我要从万族中招聚你们，从你们被分散到的各地聚集你们，把以色列地赐给你们。’'),
('CNV', '以西结书', 26, 11, 18, '他们必回到那里，也必除掉那里所有可厌的偶像和所有可憎之物。'),
('CNV', '以西结书', 26, 11, 19, '“我要把一颗心赐给他们，把新的灵放在他们里面；我要从他们肉体中除掉石心，赐给他们肉心，'),
('CNV', '以西结书', 26, 11, 20, '使他们遵从我的律例，谨守遵行我的典章，这样，他们就必作我的子民，我必作他们的神。'),
('CNV', '以西结书', 26, 11, 21, '至于那些心中随从可厌的偶像和可憎之物的人，我要把他们所行的，报应在他们的头上。”这是主神的宣告。'),
('CNV', '以西结书', 26, 11, 22, '以后，基路伯展开翅膀，轮子都在他们旁边；在他们以上有以色列神的荣耀。'),
('CNV', '以西结书', 26, 11, 23, '主的荣耀从城中升起，停在城东的那座山上。'),
('CNV', '以西结书', 26, 11, 24, '灵把我提起来，在异象中藉着神的灵，领我到迦勒底被掳的人那里去；我看见的异象就离开我上升去了。'),
('CNV', '以西结书', 26, 11, 25, '我就把主指示我的一切事都说给被掳的人听。'),
('CNV', '以西结书', 26, 12, 1, '主的话又临到我说：'),
('CNV', '以西结书', 26, 12, 2, '“人子啊！你是住在叛逆的民族之中；他们有眼睛可以看，却看不见；他们有耳朵可以听，却听不见，因为他们是叛逆的民族。'),
('CNV', '以西结书', 26, 12, 3, '因此，人子啊！你要为自己预备被掳时所需的东西，在日间当着他们眼前离去，从你所住的地方移居别处；他们虽然是叛逆的民族，或者他们可以看得明白。'),
('CNV', '以西结书', 26, 12, 4, '你要在日间当着他们眼前，把你的东西（好像被掳时所需的物件）搬出来，到了晚上，你要当着他们眼前出去，像被掳的人出去一样。'),
('CNV', '以西结书', 26, 12, 5, '你要当着他们眼前把墙挖穿，把你的东西从那里带出去。'),
('CNV', '以西结书', 26, 12, 6, '到了天黑，你要当着他们眼前把这些东西扛在肩头上带出去；你要蒙住你的脸，使你看不见这地，因为我已经立你作以色列家的一个兆头。”'),
('CNV', '以西结书', 26, 12, 7, '于是我照着所吩咐的去行，在日间我把我的东西（好像被掳时所需的物件）搬出来；到了晚上，我用手把墙挖穿；天黑的时候，我就当着他们眼前把这些东西扛在肩头上带出去。'),
('CNV', '以西结书', 26, 12, 8, '到了早晨，主的话临到我说：'),
('CNV', '以西结书', 26, 12, 9, '“人子啊！以色列家，就是叛逆的民族，不是问你：‘你在作什么呢？’'),
('CNV', '以西结书', 26, 12, 10, '你要对他们说：‘主神这样说：这默示（“默示”原文作“担子”）是关乎耶路撒冷的君王，和在它中间的以色列全家。’'),
('CNV', '以西结书', 26, 12, 11, '你要说：‘我作你们的一个兆头，我怎样行，他们的遭遇也必怎样；他们必被掳去。’'),
('CNV', '以西结书', 26, 12, 12, '他们中间的君王必在天黑的时候，把东西扛在肩头上，从他们挖穿的墙带出去；他必蒙住自己的脸，不能看见这地。'),
('CNV', '以西结书', 26, 12, 13, '我要把我的网撒在他身上，他必被我的网罗网住；我要把他带到巴比伦，就是迦勒底人之地；他不会看见那地，却要死在那里。'),
('CNV', '以西结书', 26, 12, 14, '我要把他周围所有的人，就是所有帮助他的和他所有的军队，分散到四方去，也要拔出刀来追赶他们。'),
('CNV', '以西结书', 26, 12, 15, '我使他们四散到列邦中，分散在各地的时候，他们就知道我是主。'),
('CNV', '以西结书', 26, 12, 16, '然而我却要留下他们少数的人，免受刀剑、饥荒和瘟疫之害，好使他们在所到的列国中，述说他们一切可憎恶的事，他们就知道我是主。”'),
('CNV', '以西结书', 26, 12, 17, '主的话又临到我说：'),
('CNV', '以西结书', 26, 12, 18, '“人子啊！你要战战兢兢地吃你的饭，满心忧虑地喝你的水。'),
('CNV', '以西结书', 26, 12, 19, '你要对这地的人民说：‘论到耶路撒冷的居民和以色列地，主神这样说：他们要满心忧虑地吃他们的饭，十分惊惶地喝他们的水；因为所有居民的强暴，这地必全然荒凉。'),
('CNV', '以西结书', 26, 12, 20, '有人居住的城市必成为荒场，这地必然荒凉，你们就知道我是主。’”'),
('CNV', '以西结书', 26, 12, 21, '主的话临到我说：'),
('CNV', '以西结书', 26, 12, 22, '“人子啊！你们在以色列地怎么有这一句俗语说：‘日子一天一天过去，所有异象都落空了’呢？'),
('CNV', '以西结书', 26, 12, 23, '因此，你要对他们说：主神这样说：‘我必使这一句俗语不再流行，在以色列中，人必不再引用这句俗语。’你却要对他们说：‘日子临近了，所有异象都必应验。’'),
('CNV', '以西结书', 26, 12, 24, '从此，在以色列家中必不再有虚假的异象和奉承的占卜。'),
('CNV', '以西结书', 26, 12, 25, '我主所说的，是我要说的话，我所说的必定成就，不再耽延。叛逆的民族啊！我所说的话必在你们还活着的日子成就。这是主神的宣告。”'),
('CNV', '以西结书', 26, 12, 26, '主的话又临到我说：'),
('CNV', '以西结书', 26, 12, 27, '“人子啊！以色列家说：‘这人所见的异象是关乎许多年日以后的事，他所说的预言是指着遥远的将来。’'),
('CNV', '以西结书', 26, 12, 28, '因此，你要对他们说：‘主神这样说：我所有的话，必没有一句再耽延；我所说的，都必成就。这是主神的宣告。’”'),
('CNV', '以西结书', 26, 13, 1, '主的话临到我说：'),
('CNV', '以西结书', 26, 13, 2, '“人子啊！你要说预言攻击那些在以色列中说预言的先知，对那些随着自己心意说预言的人说：‘你们要听主的话。’”'),
('CNV', '以西结书', 26, 13, 3, '主神这样说：“愚顽的先知有祸了，他们只是随从自己的灵说预言，却没有看见过什么异象。'),
('CNV', '以西结书', 26, 13, 4, '以色列啊！你的先知好像废墟中的狐狸。'),
('CNV', '以西结书', 26, 13, 5, '他们没有上去堵塞破口，也没有为以色列家重修墙垣，使它在主的日子，在战争中可以站立得住。'),
('CNV', '以西结书', 26, 13, 6, '他们所见的是虚假的异象，是骗人的占卜；他们说：‘这是主的宣告。’其实主并没有差遣他们，他们却希望自己的话能够应验。'),
('CNV', '以西结书', 26, 13, 7, '你们不是见了虚假的异象，不是说了骗人的占卜吗？你们还说：‘这是主的宣告。’其实我并没有说过。”'),
('CNV', '以西结书', 26, 13, 8, '因此，主神这样说：“因为你们所说的是虚假，所见的是欺诈，因此我就攻击你们。这是主神的宣告。'),
('CNV', '以西结书', 26, 13, 9, '我的手必攻击那些看见虚假异象、以占卜骗人的先知，他们必不得列在我子民的会中，不得被记录在以色列家的名册上，也不得进入以色列地；你们就知道我是主神。'),
('CNV', '以西结书', 26, 13, 10, '因为他们迷惑了我的子民，说：‘平安了。’其实没有平安。有人筑起薄墙的时候，他们就用灰泥粉刷那墙。'),
('CNV', '以西结书', 26, 13, 11, '所以你要对那些用灰泥粉刷那墙的人说：‘那墙要倒塌，必有暴雨漫过。大冰雹啊！你们要降下，狂风也必暴刮。’'),
('CNV', '以西结书', 26, 13, 12, '那墙倒塌以后，人岂不会问你们：‘你们所粉刷的在哪里呢？’”'),
('CNV', '以西结书', 26, 13, 13, '因此，主神这样说：“我要在我的烈怒中使狂风暴刮；在我的忿怒中有暴雨漫过；在烈怒中有大冰雹降下毁灭这墙。'),
('CNV', '以西结书', 26, 13, 14, '我要拆毁你们用灰泥粉刷的墙。使它倾倒在地，以致根基露出来；墙必倒塌，你们必在其中灭亡；你们就知道我是主。'),
('CNV', '以西结书', 26, 13, 15, '我必这样向墙，和向那些用灰泥粉刷这墙的人发尽我的烈怒。我要对他们说：‘墙没有了！粉刷那墙的人也没有了！’'),
('CNV', '以西结书', 26, 13, 16, '粉刷那墙的人，就是以色列的众先知；他们指着耶路撒冷说预言，在没有平安的时候，为这城见平安的异象。这是主神的宣告。'),
('CNV', '以西结书', 26, 13, 17, '“人子啊！你要面向民中那些随着自己心意说预言的女子，说预言攻击她们。你要说：'),
('CNV', '以西结书', 26, 13, 18, '‘主神这样说：这些女子有祸了，她们替众人的手腕缝制符咒的带子，又替众人制造不同长度的头巾，为要猎取人的性命。难道你们猎取我子民的性命，就能保全自己的性命吗？'),
('CNV', '以西结书', 26, 13, 19, '你们为了几把大麦，为了几块饼，就在我的子民中间亵渎我；你们向我那些愿听谎言的子民说谎，不该死的人，你们杀死了；不该活的人，你们却保全他们的性命。'),
('CNV', '以西结书', 26, 13, 20, '“‘因此，主神这样说：我要与你们符咒的带子作对。你们用它们来猎取人的性命，好像猎取飞鸟一样。我必把它们从你们的膀臂上扯下来，释放那些被你们像飞鸟一样猎取的性命。'),
('CNV', '以西结书', 26, 13, 21, '我必扯下你们的头巾，救我的子民脱离你们的手，使他们不再被你们的手猎取；你们就知道我是主。'),
('CNV', '以西结书', 26, 13, 22, '我没有使义人灰心，你们却用谎言使他们灰心，又坚固恶人的手，使他们不转离恶道而得拯救。'),
('CNV', '以西结书', 26, 13, 23, '因此，你们不得再见虚假的异象，也不得再行占卜的事；我要救我的子民脱离你们的手。你们就知道我是主。’”'),
('CNV', '以西结书', 26, 14, 1, '有几个以色列的长老来见我，在我面前坐下。'),
('CNV', '以西结书', 26, 14, 2, '主的话就临到我说：'),
('CNV', '以西结书', 26, 14, 3, '“人子啊！这些人已经把他们的偶像接到心里去，把那陷他们在罪孽中的绊脚石放在自己面前，我怎能让他们向我求问呢？'),
('CNV', '以西结书', 26, 14, 4, '因此，你要告诉他们，对他们说：‘主神这样说：以色列家的人中，凡把他的偶像接到心里去，把那陷自己在罪孽中的绊脚石放在自己面前，却又来见先知的，我主必按他拜众多偶像的罪报应他，'),
('CNV', '以西结书', 26, 14, 5, '好夺回以色列家的心。他们众人因自己的偶像，与我疏远。’'),
('CNV', '以西结书', 26, 14, 6, '“因此，你要对以色列家说：‘主神这样说：回转吧！转离你们的偶像！转脸离弃你们一切可憎之物吧！'),
('CNV', '以西结书', 26, 14, 7, '因为以色列家的人中，或是在以色列寄居的外族人中，凡与我疏远，把他们的偶像接到心里去，把那陷自己在罪孽中的绊脚石放在自己面前，却又来见先知，要为自己求问我的，我主必亲自报应他；'),
('CNV', '以西结书', 26, 14, 8, '我必向那人变脸，使他成为别人的鉴戒和讥笑的对象；我要把他从我子民中剪除；你们就知道我是主。'),
('CNV', '以西结书', 26, 14, 9, '如果有先知被欺骗说一句话，是我主任那先知受欺骗的；我必伸手攻击他，把他从我子民以色列中除灭。'),
('CNV', '以西结书', 26, 14, 10, '他们必担当自己的罪孽；求问的人的罪孽怎样，先知的罪孽也必怎样。'),
('CNV', '以西结书', 26, 14, 11, '这样，以色列家必不再走迷路离开我，也不再因他们的一切过犯玷污自己；他们要作我的子民，我要作他们的神。这是主神的宣告。’”'),
('CNV', '以西结书', 26, 14, 12, '主的话又临到我说：'),
('CNV', '以西结书', 26, 14, 13, '“人子啊！如果一国行了不忠的事得罪我，我就必伸手攻击那国，断绝那地的粮食，使饥荒临到那地，使人和牲畜都从那地剪除，'),
('CNV', '以西结书', 26, 14, 14, '即使有挪亚、但以理和约伯这三个人，他们也只能因自己的义救自己的性命。这是主神的宣告。'),
('CNV', '以西结书', 26, 14, 15, '如果我使猛兽经过那地，蹂躏那地，使它荒凉，以致因为这些兽的缘故，没有人敢经过；'),
('CNV', '以西结书', 26, 14, 16, '即使有这三个人在其中，我指着我的永生起誓，他们只能救自己，连儿女也不能救，那地却仍然荒凉。这是主神的宣告。'),
('CNV', '以西结书', 26, 14, 17, '如果我使刀剑临到那地，说：‘愿刀剑经过那地，好让我把人和牲畜从那地剪除。’'),
('CNV', '以西结书', 26, 14, 18, '即使有这三个人在其中，主神说：我指着我的永生起誓，他们只能救自己，连儿女也不能救。'),
('CNV', '以西结书', 26, 14, 19, '如果我使瘟疫流行那地，藉着流血的事把我的烈怒倾倒在那地上，使人和牲畜都从那地剪除；'),
('CNV', '以西结书', 26, 14, 20, '即使当中有挪亚、但以理和约伯，我指着我的永生起誓，他们只能因自己的义救自己的性命，连儿女也不能救。这是主神的宣告。”'),
('CNV', '以西结书', 26, 14, 21, '主神这样说：“我打发刀剑、饥荒、猛兽和瘟疫这四样可怕的刑罚临到耶路撒冷，要把人和牲畜从那里剪除的时候，那情况岂不更严重吗？'),
('CNV', '以西结书', 26, 14, 22, '其中将有剩下逃脱的人，连同儿女被带出来，他们来到你们那里，你们看见他们的所行所为，就会因我降给耶路撒冷的一切灾祸，得了安慰。'),
('CNV', '以西结书', 26, 14, 23, '你们看见了他们的所行所为，就必得安慰，因为你们知道我在耶路撒冷所行的一切，并不是无缘无故的。这是主的宣告。”'),
('CNV', '以西结书', 26, 15, 1, '主的话临到我说：'),
('CNV', '以西结书', 26, 15, 2, '“人子啊！葡萄树的木料怎能胜过树林中的枝子呢？'),
('CNV', '以西结书', 26, 15, 3, '人可以从葡萄树上取木料制造物件吗？可以从葡萄树上取木料做钉子挂器皿吗？'),
('CNV', '以西结书', 26, 15, 4, '看哪！已经抛在火里当作燃料，火既烧毁了两端，连中间也烧焦了，它还可以用来制造物件吗？'),
('CNV', '以西结书', 26, 15, 5, '看哪！它完整的时候，尚且不能用来制造物件，何况它被火烧毁和烧焦了，它还能用来做什么呢？”'),
('CNV', '以西结书', 26, 15, 6, '因此，主神这样说：“我怎样把树林中的葡萄树抛在火里当作燃料，也必照样对待耶路撒冷的居民。'),
('CNV', '以西结书', 26, 15, 7, '我必变脸攻击他们；他们虽然从火里逃出来，火仍要吞灭他们；我变脸攻击他们的时候，你们就知道我是主。'),
('CNV', '以西结书', 26, 15, 8, '我必使这地荒凉，因为他们行了不忠的事。这是主神的宣告。”'),
('CNV', '以西结书', 26, 16, 1, '主的话又临到我说：'),
('CNV', '以西结书', 26, 16, 2, '“人子啊！你要使耶路撒冷知道她那些可憎之事；'),
('CNV', '以西结书', 26, 16, 3, '你要说：‘主神对耶路撒冷这样说：你的根源和出生地是在迦南地；你的父亲是亚摩利人，你的母亲是赫人。'),
('CNV', '以西结书', 26, 16, 4, '论到你出生的景况：在你生下来的日子，没有人替你断脐带，没有人用水洗你，使你洁净，没有人撒盐在你身上，也没有人用布包裹你。'),
('CNV', '以西结书', 26, 16, 5, '没有人顾惜可怜你，愿意为你作上述任何一件事；你却被人抛弃在田野，因为你出生的时候，你是被人厌恶的。'),
('CNV', '以西结书', 26, 16, 6, '“‘但我从你身旁经过，见你在血中挣扎。那时，你躺在血中，我对你说：要活下去（《马索拉文本》重复一遍“那时，你躺在血中，我对你说：要活下去”，现参照其他抄本和古译本翻译）。'),
('CNV', '以西结书', 26, 16, 7, '我使你生长起来，像田间的植物。于是你生长起来，渐渐长大，好像最美丽的珠宝，你的两乳长成，头发秀长；但你仍是赤身露体。'),
('CNV', '以西结书', 26, 16, 8, '我又从你身旁经过，见你已经到了谈情说爱的时候，我就用我的衣襟搭在你身上，遮盖你赤裸的身体；我又向你起誓，与你立约，于是你就属于我了。这是主神的宣告。'),
('CNV', '以西结书', 26, 16, 9, '那时我用水洗你，洗净你身上的血，又用油抹你。'),
('CNV', '以西结书', 26, 16, 10, '我使你身穿刺绣的衣裳，脚穿海狗皮鞋；用细麻布给你裹头；又用丝绸给你披在身上。'),
('CNV', '以西结书', 26, 16, 11, '我用珠宝给你打扮，把手环戴在你手上，把项链戴在你颈上，'),
('CNV', '以西结书', 26, 16, 12, '又把鼻环戴在你鼻子上，把耳环戴在你耳朵上，把美丽的冠冕戴在你头上。'),
('CNV', '以西结书', 26, 16, 13, '这样你就有了金银的装饰，你穿的是细麻、丝绸和刺绣的衣服；你吃的是细面、蜂蜜和油；你实在非常美丽，配登王后的位。'),
('CNV', '以西结书', 26, 16, 14, '你的名声因你的美丽传遍列国，你全然美丽，是因为我加在你身上的荣美。这是主神的宣告。'),
('CNV', '以西结书', 26, 16, 15, '“‘可是你倚仗你的美丽，又凭着你的名声去行淫；你向每一个过路的人纵情淫乱（《马索拉文本》在本节最后有“而那便成了属他的”；现参照《七十士译本》和其他古译本的较短读文翻译）。'),
('CNV', '以西结书', 26, 16, 16, '你拿了你的一些衣服，为自己建造色彩缤纷的邱坛，又在那里行淫。这样的事不应发生，将来也不会再出现。'),
('CNV', '以西结书', 26, 16, 17, '你又拿了我送给你那些美丽的金器银器，为自己铸造男人的像，与那些像行淫。'),
('CNV', '以西结书', 26, 16, 18, '你又拿你的刺绣衣服，盖在它们身上，并且把我的油和香料都摆在它们面前。'),
('CNV', '以西结书', 26, 16, 19, '你把我赐给你的食物，就是我给你吃的细面、油和蜂蜜，都摆在它们面前作馨香的祭物。这是主神的宣告。'),
('CNV', '以西结书', 26, 16, 20, '你更把你的儿女，就是你给我所生的儿女，献给它们作食物；你所行的淫乱还算是小事吗？'),
('CNV', '以西结书', 26, 16, 21, '你竟宰杀了我的儿女，使他们经火，献给它们。'),
('CNV', '以西结书', 26, 16, 22, '你行这一切可憎和淫乱的事，并没有想过你年幼的日子，那时你赤身露体，在血中挣扎。'),
('CNV', '以西结书', 26, 16, 23, '“‘你有祸了，有祸了！这是主神的宣告。你行了这一切恶事以后，'),
('CNV', '以西结书', 26, 16, 24, '你又为自己建造高冈，在各广场上筑起高坛。'),
('CNV', '以西结书', 26, 16, 25, '你在各路口建造高坛，使你的美丽变为可憎的，又向每一个过路的人张开两腿，多行淫乱。'),
('CNV', '以西结书', 26, 16, 26, '你也与放纵情欲的邻居埃及人行淫，多行淫乱，惹我发怒。'),
('CNV', '以西结书', 26, 16, 27, '因此，我伸手攻击你，减少你的粮食（“粮食”或译：“领土”），又把你交给那些恨你的非利士女子，使她们任意待你；她们对你邪荡的行为也感到羞愧。'),
('CNV', '以西结书', 26, 16, 28, '可是，因为你还不满足，又与亚述人行淫；你与他们行淫之后，还是不满足。'),
('CNV', '以西结书', 26, 16, 29, '于是你增多你的淫乱，与贸易之地迦勒底行淫，你还是不满足。'),
('CNV', '以西结书', 26, 16, 30, '“‘你行的这一切事，简直是任性无耻的妓女所为，可见你的意志是多么的薄弱。这是主的宣告。'),
('CNV', '以西结书', 26, 16, 31, '你在各路口建造你的高冈，又在各广场上筑起你的高坛；然而你并不像一个妓女，因为你藐视卖淫所得的赏赐。'),
('CNV', '以西结书', 26, 16, 32, '你这淫乱的妻子啊！你竟接外人而不接自己的丈夫。'),
('CNV', '以西结书', 26, 16, 33, '人都把礼物送给妓女，你却把你的礼物送给你所有的爱人，贿赂他们从四面来与你行淫。'),
('CNV', '以西结书', 26, 16, 34, '你的淫行与别的妇女不同，因为不是人把礼物送给你，要求与你行淫，是你把礼物送给人，所以你是不同的。'),
('CNV', '以西结书', 26, 16, 35, '“‘因此，你这妓女啊，要听主的话！'),
('CNV', '以西结书', 26, 16, 36, '主神这样说：因为你的情欲倾注出来，你与你的爱人行淫，露出你的下体，又因为你拜一切可憎的偶像，流儿女的血，把血献给偶像，'),
('CNV', '以西结书', 26, 16, 37, '所以我要把所有与你欢合的爱人，就是所有你所爱的和你所恨的，都聚集起来；我要把他们从四围聚集起来攻击你；我要在他们面前露出你的下体，使他们看见你全身赤裸。'),
('CNV', '以西结书', 26, 16, 38, '我要审判你，像审判行奸淫和流人血的妇人一样；我要因我的烈怒和妒忿，使流人血的罪归在你身上。'),
('CNV', '以西结书', 26, 16, 39, '我要把你交在他们手里，他们要拆毁你的高冈，破坏你的高坛，剥去你的衣服，夺去你美丽的珠宝，只留下你赤露的身躯。'),
('CNV', '以西结书', 26, 16, 40, '他们必带一大群人上来攻击你，用石头打死你，用他们的刀把你砍碎。'),
('CNV', '以西结书', 26, 16, 41, '他们也要用火烧你的房屋，在许多妇人面前向你施行审判。我必止住你的淫行，也必使你不再把诱人行淫的礼物送给人。'),
('CNV', '以西结书', 26, 16, 42, '这样我向你发的烈怒就可以平息，我的妒忿也可以离开你；我可以安静，不再恼怒了。'),
('CNV', '以西结书', 26, 16, 43, '因为你不追念你年幼的日子，反而在这一切事上惹我发怒；看哪！我必照着你所行的报应在你头上，这是主神的宣告。在你一切可憎的事以外，你岂不是还行了这淫乱的丑事吗？'),
('CNV', '以西结书', 26, 16, 44, '“‘凡引用俗语的，必用这俗语指着你说：有其母，必有其女。'),
('CNV', '以西结书', 26, 16, 45, '你实在是你母亲的女儿，她厌弃自己的丈夫和儿女；你实在是你姊妹的姊妹，她们厌弃她们的丈夫和儿女；你们的母亲是赫人，你们的父亲是亚摩利人。'),
('CNV', '以西结书', 26, 16, 46, '你的姊姊是撒玛利亚，她和她的女儿们住在你的北面；你的妹妹是所多玛，她和她的女儿们住在你的南面。')
on conflict (version, book, chapter, verse) do nothing;
